window.DOCS["g2610"] = {"id":"g2610","kind":"book","title":{"en":"Notre-Dame de Paris","tr":"Notre Dame'ın Kamburu"},"authors":["Victor Hugo","Isabel Florence Hapgood"],"source":"Project Gutenberg — eBook #2610","year":null,"level":"C1","words":184828,"minutes":1027,"blurb":{"tr":"1482 Paris'inde geçer. Katedralin çan kulesinde yaşayan sağır ve kambur Quasimodo, Çingene kızı Esmeralda'ya duyduğu bağlılıkla, ona takıntılı başdiyakoz Frollo'nun kurduğu tuzağın arasında kalır. Hugo aynı zamanda ortaçağ Paris'ini ve katedral mimarisini uzun uzun anlatır. Betimleme bölümleri uzun, tarih ve mimarlık kelimeleri yoğundur."},"cover":{"emoji":"🏛️","hue":210},"toc":[{"level":0,"n":"","t":"Chapter I. THE GRAND HALL.","id":"chapter-i-the-grand-hall"},{"level":0,"n":"","t":"Chapter II. PIERRE GRINGOIRE.","id":"chapter-ii-pierre-gringoire"},{"level":0,"n":"","t":"Chapter III. MONSIEUR THE CARDINAL.","id":"chapter-iii-monsieur-the-cardinal"},{"level":0,"n":"","t":"Chapter IV. MASTER JACQUES COPPENOLE.","id":"chapter-iv-master-jacques-coppenole"},{"level":0,"n":"","t":"Chapter V. QUASIMODO.","id":"chapter-v-quasimodo"},{"level":0,"n":"","t":"Chapter VI. ESMERALDA.","id":"chapter-vi-esmeralda"},{"level":0,"n":"","t":"Chapter I. FROM CHARYBDIS TO SCYLLA.","id":"chapter-i-from-charybdis-to-scylla"},{"level":0,"n":"","t":"Chapter II. THE PLACE DE GRÈVE.","id":"chapter-ii-the-place-de-gr-ve"},{"level":0,"n":"","t":"Chapter III. KISSES FOR BLOWS.","id":"chapter-iii-kisses-for-blows"},{"level":0,"n":"","t":"Chapter IV. THE INCONVENIENCES OF FOLLOWING A PRETTY WOMAN","id":"chapter-iv-the-inconveniences-of-following-a-pre"},{"level":0,"n":"","t":"Chapter V. RESULT OF THE DANGERS.","id":"chapter-v-result-of-the-dangers"},{"level":0,"n":"","t":"Chapter VI. THE BROKEN JUG.","id":"chapter-vi-the-broken-jug"},{"level":0,"n":"","t":"Chapter VII. A BRIDAL NIGHT.","id":"chapter-vii-a-bridal-night"},{"level":0,"n":"","t":"Chapter I. NOTRE-DAME.","id":"chapter-i-notre-dame"},{"level":0,"n":"","t":"Chapter II. A BIRD’S-EYE VIEW OF PARIS.","id":"chapter-ii-a-birds-eye-view-of-paris"},{"level":0,"n":"","t":"Chapter I. GOOD SOULS.","id":"chapter-i-good-souls"},{"level":0,"n":"","t":"Chapter II. CLAUDE FROLLO.","id":"chapter-ii-claude-frollo"},{"level":0,"n":"","t":"Chapter III. _IMMANIS PECORIS CUSTOS, IMMANIOR IPSE_.","id":"chapter-iii-immanis-pecoris-custos-immanior-ipse"},{"level":0,"n":"","t":"Chapter IV. THE DOG AND HIS MASTER.","id":"chapter-iv-the-dog-and-his-master"},{"level":0,"n":"","t":"Chapter V. MORE ABOUT CLAUDE FROLLO.","id":"chapter-v-more-about-claude-frollo"},{"level":0,"n":"","t":"Chapter VI. UNPOPULARITY.","id":"chapter-vi-unpopularity"},{"level":0,"n":"","t":"Chapter I. _ABBAS BEATI MARTINI_.","id":"chapter-i-abbas-beati-martini"},{"level":0,"n":"","t":"Chapter II. THIS WILL KILL THAT.","id":"chapter-ii-this-will-kill-that"},{"level":0,"n":"","t":"Chapter I. AN IMPARTIAL GLANCE AT THE ANCIENT MAGISTRACY.","id":"chapter-i-an-impartial-glance-at-the-ancient-mag"},{"level":0,"n":"","t":"Chapter II. THE RAT-HOLE.","id":"chapter-ii-the-rat-hole"},{"level":0,"n":"","t":"Chapter III. HISTORY OF A LEAVENED CAKE OF MAIZE.","id":"chapter-iii-history-of-a-leavened-cake-of-maize"},{"level":0,"n":"","t":"Chapter IV. A TEAR FOR A DROP OF WATER.","id":"chapter-iv-a-tear-for-a-drop-of-water"},{"level":0,"n":"","t":"Chapter V. END OF THE STORY OF THE CAKE.","id":"chapter-v-end-of-the-story-of-the-cake"},{"level":0,"n":"","t":"Chapter I. THE DANGER OF CONFIDING ONE’S SECRET TO A GOAT.","id":"chapter-i-the-danger-of-confiding-ones-secret-to"},{"level":0,"n":"","t":"Chapter II. A PRIEST AND A PHILOSOPHER ARE TWO DIFFERENT THINGS.","id":"chapter-ii-a-priest-and-a-philosopher-are-two-di"},{"level":0,"n":"","t":"Chapter III. THE BELLS.","id":"chapter-iii-the-bells"},{"level":0,"n":"","t":"Chapter IV. ἈΝÁΓΚΗ.","id":"chapter-iv"},{"level":0,"n":"","t":"Chapter V. THE TWO MEN CLOTHED IN BLACK.","id":"chapter-v-the-two-men-clothed-in-black"},{"level":0,"n":"","t":"Chapter VI. THE EFFECT WHICH SEVEN OATHS IN THE OPEN AIR CAN","id":"chapter-vi-the-effect-which-seven-oaths-in-the-o"},{"level":0,"n":"","t":"Chapter VII. THE MYSTERIOUS MONK.","id":"chapter-vii-the-mysterious-monk"},{"level":0,"n":"","t":"Chapter VIII. THE UTILITY OF WINDOWS WHICH OPEN ON THE RIVER.","id":"chapter-viii-the-utility-of-windows-which-open-o"},{"level":0,"n":"","t":"Chapter I. THE CROWN CHANGED INTO A DRY LEAF.","id":"chapter-i-the-crown-changed-into-a-dry-leaf"},{"level":0,"n":"","t":"Chapter II. CONTINUATION OF THE CROWN WHICH WAS CHANGED INTO A","id":"chapter-ii-continuation-of-the-crown-which-was-c"},{"level":0,"n":"","t":"Chapter III. END OF THE CROWN WHICH WAS TURNED INTO A DRY LEAF.","id":"chapter-iii-end-of-the-crown-which-was-turned-in"},{"level":0,"n":"","t":"Chapter IV. _LASCIATE OGNI SPERANZA_—LEAVE ALL HOPE BEHIND, YE","id":"chapter-iv-lasciate-ogni-speranza-leave-all-hope"},{"level":0,"n":"","t":"Chapter V. THE MOTHER.","id":"chapter-v-the-mother"},{"level":0,"n":"","t":"Chapter VI. THREE HUMAN HEARTS DIFFERENTLY CONSTRUCTED.","id":"chapter-vi-three-human-hearts-differently-constr"},{"level":0,"n":"","t":"Chapter I. DELIRIUM.","id":"chapter-i-delirium"},{"level":0,"n":"","t":"Chapter II. HUNCHBACKED, ONE EYED, LAME.","id":"chapter-ii-hunchbacked-one-eyed-lame"},{"level":0,"n":"","t":"Chapter III. DEAF.","id":"chapter-iii-deaf"},{"level":0,"n":"","t":"Chapter IV. EARTHENWARE AND CRYSTAL.","id":"chapter-iv-earthenware-and-crystal"},{"level":0,"n":"","t":"Chapter V. THE KEY TO THE RED DOOR.","id":"chapter-v-the-key-to-the-red-door"},{"level":0,"n":"","t":"Chapter VI. CONTINUATION OF THE KEY TO THE RED DOOR.","id":"chapter-vi-continuation-of-the-key-to-the-red-do"},{"level":0,"n":"","t":"Chapter I. GRINGOIRE HAS MANY GOOD IDEAS IN SUCCESSION.—RUE DES","id":"chapter-i-gringoire-has-many-good-ideas-in-succe"},{"level":0,"n":"","t":"Chapter II. TURN VAGABOND.","id":"chapter-ii-turn-vagabond"},{"level":0,"n":"","t":"Chapter III. LONG LIVE MIRTH.","id":"chapter-iii-long-live-mirth"},{"level":0,"n":"","t":"Chapter IV. AN AWKWARD FRIEND.","id":"chapter-iv-an-awkward-friend"},{"level":0,"n":"","t":"Chapter V. THE RETREAT IN WHICH MONSIEUR LOUIS OF FRANCE SAYS HIS","id":"chapter-v-the-retreat-in-which-monsieur-louis-of"},{"level":0,"n":"","t":"Chapter VI. LITTLE SWORD IN POCKET.","id":"chapter-vi-little-sword-in-pocket"},{"level":0,"n":"","t":"Chapter VII. CHATEAUPERS TO THE RESCUE.","id":"chapter-vii-chateaupers-to-the-rescue"},{"level":0,"n":"","t":"Chapter I. THE LITTLE SHOE.","id":"chapter-i-the-little-shoe"},{"level":0,"n":"","t":"Chapter II. THE BEAUTIFUL CREATURE CLAD IN WHITE. (Dante.)","id":"chapter-ii-the-beautiful-creature-clad-in-white-"},{"level":0,"n":"","t":"Chapter III. THE MARRIAGE OF PHOEBUS.","id":"chapter-iii-the-marriage-of-phoebus"},{"level":0,"n":"","t":"Chapter IV. THE MARRIAGE OF QUASIMODO.","id":"chapter-iv-the-marriage-of-quasimodo"}],"html":"<h1 class=\"chapter\" id=\"chapter-i-the-grand-hall\">Chapter I. THE GRAND HALL.</h1>\n<p>Three hundred and forty-eight years, six months, and nineteen<br>days ago to-day, the Parisians awoke to the sound of all the<br>bells in the triple circuit of the city, the university, and the<br>town ringing a full peal.</p>\n<p>The sixth of January, 1482, is not, however, a day of which<br>history has preserved the memory. There was nothing notable in<br>the event which thus set the bells and the <em>bourgeois</em> of Paris<br>in a ferment from early morning. It was neither an assault by the<br>Picards nor the Burgundians, nor a hunt led along in procession,<br>nor a revolt of scholars in the town of Laas, nor an entry of<br>“our much dread lord, monsieur the king,” nor even a pretty<br>hanging of male and female thieves by the courts of Paris.<br>Neither was it the arrival, so frequent in the fifteenth century,<br>of some plumed and bedizened embassy. It was barely two days<br>since the last cavalcade of that nature, that of the Flemish<br>ambassadors charged with concluding the marriage between the<br>dauphin and Marguerite of Flanders, had made its entry into<br>Paris, to the great annoyance of M. le Cardinal de Bourbon, who,<br>for the sake of pleasing the king, had been obliged to assume an<br>amiable mien towards this whole rustic rabble of Flemish<br>burgomasters, and to regale them at his Hôtel de Bourbon, with a<br>very “pretty morality, allegorical satire, and farce,” while a<br>driving rain drenched the magnificent tapestries at his door.</p>\n<p>What put the “whole population of Paris in commotion,” as Jehan<br>de Troyes expresses it, on the sixth of January, was the double<br>solemnity, united from time immemorial, of the Epiphany and the<br>Feast of Fools.</p>\n<p>On that day, there was to be a bonfire on the Place de Grève, a<br>maypole at the Chapelle de Braque, and a mystery at the Palais de<br>Justice. It had been cried, to the sound of the trumpet, the<br>preceding evening at all the cross roads, by the provost’s men,<br>clad in handsome, short, sleeveless coats of violet camelot, with<br>large white crosses upon their breasts.</p>\n<p>So the crowd of citizens, male and female, having closed their<br>houses and shops, thronged from every direction, at early morn,<br>towards some one of the three spots designated.</p>\n<p>Each had made his choice; one, the bonfire; another, the maypole;<br>another, the mystery play. It must be stated, in honor of the<br>good sense of the loungers of Paris, that the greater part of<br>this crowd directed their steps towards the bonfire, which was<br>quite in season, or towards the mystery play, which was to be<br>presented in the grand hall of the Palais de Justice (the courts<br>of law), which was well roofed and walled; and that the curious<br>left the poor, scantily flowered maypole to shiver all alone<br>beneath the sky of January, in the cemetery of the Chapel of<br>Braque.</p>\n<p>The populace thronged the avenues of the law courts in<br>particular, because they knew that the Flemish ambassadors, who<br>had arrived two days previously, intended to be present at the<br>representation of the mystery, and at the election of the Pope of<br>the Fools, which was also to take place in the grand hall.</p>\n<p>It was no easy matter on that day, to force one’s way into that<br>grand hall, although it was then reputed to be the largest<br>covered enclosure in the world (it is true that Sauval had not<br>yet measured the grand hall of the Château of Montargis). The<br>palace place, encumbered with people, offered to the curious<br>gazers at the windows the aspect of a sea; into which five or six<br>streets, like so many mouths of rivers, discharged every moment<br>fresh floods of heads. The waves of this crowd, augmented<br>incessantly, dashed against the angles of the houses which<br>projected here and there, like so many promontories, into the<br>irregular basin of the place. In the centre of the lofty<br>Gothic[1] façade of the palace, the grand staircase, incessantly<br>ascended and descended by a double current, which, after parting<br>on the intermediate landing-place, flowed in broad waves along<br>its lateral slopes,—the grand staircase, I say, trickled<br>incessantly into the place, like a cascade into a lake. The<br>cries, the laughter, the trampling of those thousands of feet,<br>produced a great noise and a great clamor. From time to time,<br>this noise and clamor redoubled; the current which drove the<br>crowd towards the grand staircase flowed backwards, became<br>troubled, formed whirlpools. This was produced by the buffet of<br>an archer, or the horse of one of the provost’s sergeants, which<br>kicked to restore order; an admirable tradition which the<br>provostship has bequeathed to the constablery, the constablery to<br>the <em>maréchaussée</em>, the <em>maréchaussée</em> to our <em>gendarmeri</em> of<br>Paris.</p>\n<p>Thousands of good, calm, <em>bourgeois</em> faces thronged the windows,<br>the doors, the dormer windows, the roofs, gazing at the palace,<br>gazing at the populace, and asking nothing more; for many<br>Parisians content themselves with the spectacle of the<br>spectators, and a wall behind which something is going on becomes<br>at once, for us, a very curious thing indeed.</p>\n<p>If it could be granted to us, the men of 1830, to mingle in<br>thought with those Parisians of the fifteenth century, and to<br>enter with them, jostled, elbowed, pulled about, into that<br>immense hall of the palace, which was so cramped on that sixth of<br>January, 1482, the spectacle would not be devoid of either<br>interest or charm, and we should have about us only things that<br>were so old that they would seem new.</p>\n<p>With the reader’s consent, we will endeavor to retrace in<br>thought, the impression which he would have experienced in<br>company with us on crossing the threshold of that grand hall, in<br>the midst of that tumultuous crowd in surcoats, short, sleeveless<br>jackets, and doublets.</p>\n<p>And, first of all, there is a buzzing in the ears, a dazzlement<br>in the eyes. Above our heads is a double ogive vault, panelled<br>with wood carving, painted azure, and sown with golden<br>fleurs-de-lis; beneath our feet a pavement of black and white<br>marble, alternating. A few paces distant, an enormous pillar,<br>then another, then another; seven pillars in all, down the length<br>of the hall, sustaining the spring of the arches of the double<br>vault, in the centre of its width. Around four of the pillars,<br>stalls of merchants, all sparkling with glass and tinsel; around<br>the last three, benches of oak, worn and polished by the trunk<br>hose of the litigants, and the robes of the attorneys. Around the<br>hall, along the lofty wall, between the doors, between the<br>windows, between the pillars, the interminable row of all the<br>kings of France, from Pharamond down: the lazy kings, with<br>pendent arms and downcast eyes; the valiant and combative kings,<br>with heads and arms raised boldly heavenward. Then in the long,<br>pointed windows, glass of a thousand hues; at the wide entrances<br>to the hall, rich doors, finely sculptured; and all, the vaults,<br>pillars, walls, jambs, panelling, doors, statues, covered from<br>top to bottom with a splendid blue and gold illumination, which,<br>a trifle tarnished at the epoch when we behold it, had almost<br>entirely disappeared beneath dust and spiders in the year of<br>grace, 1549, when du Breul still admired it from tradition.</p>\n<p>Let the reader picture to himself now, this immense, oblong hall,<br>illuminated by the pallid light of a January day, invaded by a<br>motley and noisy throng which drifts along the walls, and eddies<br>round the seven pillars, and he will have a confused idea of the<br>whole effect of the picture, whose curious details we shall make<br>an effort to indicate with more precision.</p>\n<p>It is certain, that if Ravaillac had not assassinated Henri IV.,<br>there would have been no documents in the trial of Ravaillac<br>deposited in the clerk’s office of the Palais de Justice, no<br>accomplices interested in causing the said documents to<br>disappear; hence, no incendiaries obliged, for lack of better<br>means, to burn the clerk’s office in order to burn the documents,<br>and to burn the Palais de Justice in order to burn the clerk’s<br>office; consequently, in short, no conflagration in 1618. The old<br>Palais would be standing still, with its ancient grand hall; I<br>should be able to say to the reader, “Go and look at it,” and we<br>should thus both escape the necessity,—I of making, and he of<br>reading, a description of it, such as it is. Which demonstrates a<br>new truth: that great events have incalculable results.</p>\n<p>It is true that it may be quite possible, in the first place,<br>that Ravaillac had no accomplices; and in the second, that if he<br>had any, they were in no way connected with the fire of 1618. Two<br>other very plausible explanations exist: First, the great flaming<br>star, a foot broad, and a cubit high, which fell from heaven, as<br>every one knows, upon the law courts, after midnight on the<br>seventh of March; second, Théophile’s quatrain,—</p>\n<p>“Sure, ’twas but a sorry game<br>When at Paris, Dame Justice,<br>Through having eaten too much spice,<br>Set the palace all aflame.”</p>\n<p>Whatever may be thought of this triple explanation, political,<br>physical, and poetical, of the burning of the law courts in 1618,<br>the unfortunate fact of the fire is certain. Very little to-day<br>remains, thanks to this catastrophe,—thanks, above all, to the<br>successive restorations which have completed what it spared,—very<br>little remains of that first dwelling of the kings of France,—of<br>that elder palace of the Louvre, already so old in the time of<br>Philip the Handsome, that they sought there for the traces of the<br>magnificent buildings erected by King Robert and described by<br>Helgaldus. Nearly everything has disappeared. What has become of<br>the chamber of the chancellery, where Saint Louis consummated his<br>marriage? the garden where he administered justice, “clad in a<br>coat of camelot, a surcoat of linsey-woolsey, without sleeves,<br>and a sur-mantle of black sandal, as he lay upon the carpet with<br>Joinville?” Where is the chamber of the Emperor Sigismond? and<br>that of Charles IV.? that of Jean the Landless? Where is the<br>staircase, from which Charles VI. promulgated his edict of<br>pardon? the slab where Marcel cut the throats of Robert de<br>Clermont and the Marshal of Champagne, in the presence of the<br>dauphin? the wicket where the bulls of Pope Benedict were torn,<br>and whence those who had brought them departed decked out, in<br>derision, in copes and mitres, and making an apology through all<br>Paris? and the grand hall, with its gilding, its azure, its<br>statues, its pointed arches, its pillars, its immense vault, all<br>fretted with carvings? and the gilded chamber? and the stone<br>lion, which stood at the door, with lowered head and tail between<br>his legs, like the lions on the throne of Solomon, in the<br>humiliated attitude which befits force in the presence of<br>justice? and the beautiful doors? and the stained glass? and the<br>chased ironwork, which drove Biscornette to despair? and the<br>delicate woodwork of Hancy? What has time, what have men done<br>with these marvels? What have they given us in return for all<br>this Gallic history, for all this Gothic art? The heavy flattened<br>arches of M. de Brosse, that awkward architect of the<br>Saint-Gervais portal. So much for art; and, as for history, we<br>have the gossiping reminiscences of the great pillar, still<br>ringing with the tattle of the Patru.</p>\n<p>It is not much. Let us return to the veritable grand hall of the<br>veritable old palace. The two extremities of this gigantic<br>parallelogram were occupied, the one by the famous marble table,<br>so long, so broad, and so thick that, as the ancient land<br>rolls—in a style that would have given Gargantua an appetite—say,<br>“such a slice of marble as was never beheld in the world”; the<br>other by the chapel where Louis XI. had himself sculptured on his<br>knees before the Virgin, and whither he caused to be brought,<br>without heeding the two gaps thus made in the row of royal<br>statues, the statues of Charlemagne and of Saint Louis, two<br>saints whom he supposed to be great in favor in heaven, as kings<br>of France. This chapel, quite new, having been built only six<br>years, was entirely in that charming taste of delicate<br>architecture, of marvellous sculpture, of fine and deep chasing,<br>which marks with us the end of the Gothic era, and which is<br>perpetuated to about the middle of the sixteenth century in the<br>fairylike fancies of the Renaissance. The little open-work rose<br>window, pierced above the portal, was, in particular, a<br>masterpiece of lightness and grace; one would have pronounced it<br>a star of lace.</p>\n<p>In the middle of the hall, opposite the great door, a platform of<br>gold brocade, placed against the wall, a special entrance to<br>which had been effected through a window in the corridor of the<br>gold chamber, had been erected for the Flemish emissaries and the<br>other great personages invited to the presentation of the mystery<br>play.</p>\n<p>It was upon the marble table that the mystery was to be enacted,<br>as usual. It had been arranged for the purpose, early in the<br>morning; its rich slabs of marble, all scratched by the heels of<br>law clerks, supported a cage of carpenter’s work of considerable<br>height, the upper surface of which, within view of the whole<br>hall, was to serve as the theatre, and whose interior, masked by<br>tapestries, was to take the place of dressing-rooms for the<br>personages of the piece. A ladder, naively placed on the outside,<br>was to serve as means of communication between the dressing-room<br>and the stage, and lend its rude rungs to entrances as well as to<br>exits. There was no personage, however unexpected, no sudden<br>change, no theatrical effect, which was not obliged to mount that<br>ladder. Innocent and venerable infancy of art and contrivances!</p>\n<p>Four of the bailiff of the palace’s sergeants, perfunctory<br>guardians of all the pleasures of the people, on days of festival<br>as well as on days of execution, stood at the four corners of the<br>marble table.</p>\n<p>The piece was only to begin with the twelfth stroke of the great<br>palace clock sounding midday. It was very late, no doubt, for a<br>theatrical representation, but they had been obliged to fix the<br>hour to suit the convenience of the ambassadors.</p>\n<p>Now, this whole multitude had been waiting since morning. A<br>goodly number of curious, good people had been shivering since<br>daybreak before the grand staircase of the palace; some even<br>affirmed that they had passed the night across the threshold of<br>the great door, in order to make sure that they should be the<br>first to pass in. The crowd grew more dense every moment, and,<br>like water, which rises above its normal level, began to mount<br>along the walls, to swell around the pillars, to spread out on<br>the entablatures, on the cornices, on the window-sills, on all<br>the salient points of the architecture, on all the reliefs of the<br>sculpture. Hence, discomfort, impatience, weariness, the liberty<br>of a day of cynicism and folly, the quarrels which break forth<br>for all sorts of causes—a pointed elbow, an iron-shod shoe, the<br>fatigue of long waiting—had already, long before the hour<br>appointed for the arrival of the ambassadors, imparted a harsh<br>and bitter accent to the clamor of these people who were shut in,<br>fitted into each other, pressed, trampled upon, stifled. Nothing<br>was to be heard but imprecations on the Flemish, the provost of<br>the merchants, the Cardinal de Bourbon, the bailiff of the<br>courts, Madame Marguerite of Austria, the sergeants with their<br>rods, the cold, the heat, the bad weather, the Bishop of Paris,<br>the Pope of the Fools, the pillars, the statues, that closed<br>door, that open window; all to the vast amusement of a band of<br>scholars and lackeys scattered through the mass, who mingled with<br>all this discontent their teasing remarks, and their malicious<br>suggestions, and pricked the general bad temper with a pin, so to<br>speak.</p>\n<p>Among the rest there was a group of those merry imps, who, after<br>smashing the glass in a window, had seated themselves hardily on<br>the entablature, and from that point despatched their gaze and<br>their railleries both within and without, upon the throng in the<br>hall, and the throng upon the Place. It was easy to see, from<br>their parodied gestures, their ringing laughter, the bantering<br>appeals which they exchanged with their comrades, from one end of<br>the hall to the other, that these young clerks did not share the<br>weariness and fatigue of the rest of the spectators, and that<br>they understood very well the art of extracting, for their own<br>private diversion from that which they had under their eyes, a<br>spectacle which made them await the other with patience.</p>\n<p>“Upon my soul, so it’s you, ‘Joannes Frollo de Molendino!’” cried<br>one of them, to a sort of little, light-haired imp, with a<br>well-favored and malign countenance, clinging to the acanthus<br>leaves of a capital; “you are well named John of the Mill, for<br>your two arms and your two legs have the air of four wings<br>fluttering on the breeze. How long have you been here?”</p>\n<p>“By the mercy of the devil,” retorted Joannes Frollo, “these four<br>hours and more; and I hope that they will be reckoned to my<br>credit in purgatory. I heard the eight singers of the King of<br>Sicily intone the first verse of seven o’clock mass in the<br>Sainte-Chapelle.”</p>\n<p>“Fine singers!” replied the other, “with voices even more pointed<br>than their caps! Before founding a mass for Monsieur Saint John,<br>the king should have inquired whether Monsieur Saint John likes<br>Latin droned out in a Provençal accent.”</p>\n<p>“He did it for the sake of employing those accursed singers of<br>the King of Sicily!” cried an old woman sharply from among the<br>crowd beneath the window. “I just put it to you! A thousand<br><em>livres parisi</em> for a mass! and out of the tax on sea fish in the<br>markets of Paris, to boot!”</p>\n<p>“Peace, old crone,” said a tall, grave person, stopping up his<br>nose on the side towards the fishwife; “a mass had to be founded.<br>Would you wish the king to fall ill again?”</p>\n<p>“Bravely spoken, Sire Gilles Lecornu, master furrier of king’s<br>robes!” cried the little student, clinging to the capital.</p>\n<p>A shout of laughter from all the students greeted the unlucky<br>name of the poor furrier of the king’s robes.</p>\n<p>“Lecornu! Gilles Lecornu!” said some.</p>\n<p>“<em>Cornutus et hirsutus</em>, horned and hairy,” another went on.</p>\n<p>“He! of course,” continued the small imp on the capital, “What<br>are they laughing at? An honorable man is Gilles Lecornu, brother<br>of Master Jehan Lecornu, provost of the king’s house, son of<br>Master Mahiet Lecornu, first porter of the Bois de Vincennes,—all<br><em>bourgeois</em> of Paris, all married, from father to son.”</p>\n<p>The gayety redoubled. The big furrier, without uttering a word in<br>reply, tried to escape all the eyes riveted upon him from all<br>sides; but he perspired and panted in vain; like a wedge entering<br>the wood, his efforts served only to bury still more deeply in<br>the shoulders of his neighbors, his large, apoplectic face,<br>purple with spite and rage.</p>\n<p>At length one of these, as fat, short, and venerable as himself,<br>came to his rescue.</p>\n<p>“Abomination! scholars addressing a <em>bourgeois</em> in that fashion<br>in my day would have been flogged with a fagot, which would have<br>afterwards been used to burn them.”</p>\n<p>The whole band burst into laughter.</p>\n<p>“Holà hé! who is scolding so? Who is that screech owl of evil<br>fortune?”</p>\n<p>“Hold, I know him” said one of them; “’tis Master Andry Musnier.”</p>\n<p>“Because he is one of the four sworn booksellers of the<br>university!” said the other.</p>\n<p>“Everything goes by fours in that shop,” cried a third; “the four<br>nations, the four faculties, the four feasts, the four<br>procurators, the four electors, the four booksellers.”</p>\n<p>“Well,” began Jean Frollo once more, “we must play the devil with<br>them.”[2]</p>\n<p>“Musnier, we’ll burn your books.”</p>\n<p>“Musnier, we’ll beat your lackeys.”</p>\n<p>“Musnier, we’ll kiss your wife.”</p>\n<p>“That fine, big Mademoiselle Oudarde.”</p>\n<p>“Who is as fresh and as gay as though she were a widow.”</p>\n<p>“Devil take you!” growled Master Andry Musnier.</p>\n<p>“Master Andry,” pursued Jean Jehan, still clinging to his<br>capital, “hold your tongue, or I’ll drop on your head!”</p>\n<p>Master Andry raised his eyes, seemed to measure in an instant the<br>height of the pillar, the weight of the scamp, mentally<br>multiplied that weight by the square of the velocity and remained<br>silent.</p>\n<p>Jehan, master of the field of battle, pursued triumphantly:</p>\n<p>“That’s what I’ll do, even if I am the brother of an archdeacon!”</p>\n<p>“Fine gentry are our people of the university, not to have caused<br>our privileges to be respected on such a day as this! However,<br>there is a maypole and a bonfire in the town; a mystery, Pope of<br>the Fools, and Flemish ambassadors in the city; and, at the<br>university, nothing!”</p>\n<p>“Nevertheless, the Place Maubert is sufficiently large!”<br>interposed one of the clerks established on the window-sill.</p>\n<p>“Down with the rector, the electors, and the procurators!” cried<br>Joannes.</p>\n<p>“We must have a bonfire this evening in the Champ-Gaillard,” went<br>on the other, “made of Master Andry’s books.”</p>\n<p>“And the desks of the scribes!” added his neighbor.</p>\n<p>“And the beadles’ wands!”</p>\n<p>“And the spittoons of the deans!”</p>\n<p>“And the cupboards of the procurators!”</p>\n<p>“And the hutches of the electors!”</p>\n<p>“And the stools of the rector!”</p>\n<p>“Down with them!” put in little Jehan, as counterpoint; “down<br>with Master Andry, the beadles and the scribes; the theologians,<br>the doctors and the decretists; the procurators, the electors and<br>the rector!”</p>\n<p>“The end of the world has come!” muttered Master Andry, stopping<br>up his ears.</p>\n<p>“By the way, there’s the rector! see, he is passing through the<br>Place,” cried one of those in the window.</p>\n<p>Each rivalled his neighbor in his haste to turn towards the<br>Place.</p>\n<p>“Is it really our venerable rector, Master Thibaut?” demanded<br>Jehan Frollo du Moulin, who, as he was clinging to one of the<br>inner pillars, could not see what was going on outside.</p>\n<p>“Yes, yes,” replied all the others, “it is really he, Master<br>Thibaut, the rector.”</p>\n<p>It was, in fact, the rector and all the dignitaries of the<br>university, who were marching in procession in front of the<br>embassy, and at that moment traversing the Place. The students<br>crowded into the window, saluted them as they passed with<br>sarcasms and ironical applause. The rector, who was walking at<br>the head of his company, had to support the first broadside; it<br>was severe.</p>\n<p>“Good day, monsieur le recteur! Holà hé! good day there!”</p>\n<p>“How does he manage to be here, the old gambler? Has he abandoned<br>his dice?”</p>\n<p>“How he trots along on his mule! her ears are not so long as<br>his!”</p>\n<p>“Holà hé! good day, monsieur le recteur Thibaut! _Tybalde<br>aleator_! Old fool! old gambler!”</p>\n<p>“God preserve you! Did you throw double six often last night?”</p>\n<p>“Oh! what a decrepit face, livid and haggard and drawn with the<br>love of gambling and of dice!”</p>\n<p>“Where are you bound for in that fashion, Thibaut, _Tybalde ad<br>dados_, with your back turned to the university, and trotting<br>towards the town?”</p>\n<p>“He is on his way, no doubt, to seek a lodging in the Rue<br>Thibautodé?”[3] cried Jehan du M. Moulin.</p>\n<p>The entire band repeated this quip in a voice of thunder,<br>clapping their hands furiously.</p>\n<p>“You are going to seek a lodging in the Rue Thibautodé, are you<br>not, monsieur le recteur, gamester on the side of the devil?”</p>\n<p>Then came the turns of the other dignitaries.</p>\n<p>“Down with the beadles! down with the mace-bearers!”</p>\n<p>“Tell me, Robin Pouissepain, who is that yonder?”</p>\n<p>“He is Gilbert de Suilly, <em>Gilbertus de Soliaco</em>, the chancellor<br>of the College of Autun.”</p>\n<p>“Hold on, here’s my shoe; you are better placed than I, fling it<br>in his face.”</p>\n<p>“<em>Saturnalitias mittimus ecce nuces</em>.”</p>\n<p>“Down with the six theologians, with their white surplices!”</p>\n<p>“Are those the theologians? I thought they were the white geese<br>given by Sainte-Geneviève to the city, for the fief of Roogny.”</p>\n<p>“Down with the doctors!”</p>\n<p>“Down with the cardinal disputations, and quibblers!”</p>\n<p>“My cap to you, Chancellor of Sainte-Geneviève! You have done me<br>a wrong. ’Tis true; he gave my place in the nation of Normandy to<br>little Ascanio Falzapada, who comes from the province of Bourges,<br>since he is an Italian.”</p>\n<p>“That is an injustice,” said all the scholars. “Down with the<br>Chancellor of Sainte-Geneviève!”</p>\n<p>“Ho hé! Master Joachim de Ladehors! Ho hé! Louis Dahuille! Ho hé<br>Lambert Hoctement!”</p>\n<p>“May the devil stifle the procurator of the German nation!”</p>\n<p>“And the chaplains of the Sainte-Chapelle, with their gray<br><em>amices; cum tunices grisis</em>!”</p>\n<p>“<em>Seu de pellibus grisis fourratis</em>!”</p>\n<p>“Holà hé! Masters of Arts! All the beautiful black copes! all the<br>fine red copes!”</p>\n<p>“They make a fine tail for the rector.”</p>\n<p>“One would say that he was a Doge of Venice on his way to his<br>bridal with the sea.”</p>\n<p>“Say, Jehan! here are the canons of Sainte-Geneviève!”</p>\n<p>“To the deuce with the whole set of canons!”</p>\n<p>“Abbé Claude Choart! Doctor Claude Choart! Are you in search of<br>Marie la Giffarde?”</p>\n<p>“She is in the Rue de Glatigny.”</p>\n<p>“She is making the bed of the king of the debauchees.”</p>\n<p>“She is paying her four deniers[4] <em>quatuor denarios</em>.”</p>\n<p>“<em>Aut unum bombum</em>.”</p>\n<p>“Would you like to have her pay you in the face?”</p>\n<p>“Comrades! Master Simon Sanguin, the Elector of Picardy, with his<br>wife on the crupper!”</p>\n<p>“<em>Post equitem sedet atra cura</em>—behind the horseman sits black<br>care.”</p>\n<p>“Courage, Master Simon!”</p>\n<p>“Good day, Mister Elector!”</p>\n<p>“Good night, Madame Electress!”</p>\n<p>“How happy they are to see all that!” sighed Joannes de<br>Molendino, still perched in the foliage of his capital.</p>\n<p>Meanwhile, the sworn bookseller of the university, Master Andry<br>Musnier, was inclining his ear to the furrier of the king’s<br>robes, Master Gilles Lecornu.</p>\n<p>“I tell you, sir, that the end of the world has come. No one has<br>ever beheld such outbreaks among the students! It is the accursed<br>inventions of this century that are ruining<br>everything,—artilleries, bombards, and, above all, printing, that<br>other German pest. No more manuscripts, no more books! printing<br>will kill bookselling. It is the end of the world that is drawing<br>nigh.”</p>\n<p>“I see that plainly, from the progress of velvet stuffs,” said<br>the fur-merchant.</p>\n<p>At this moment, midday sounded.</p>\n<p>“Ha!” exclaimed the entire crowd, in one voice.</p>\n<p>The scholars held their peace. Then a great hurly-burly ensued; a<br>vast movement of feet, hands, and heads; a general outbreak of<br>coughs and handkerchiefs; each one arranged himself, assumed his<br>post, raised himself up, and grouped himself. Then came a great<br>silence; all necks remained outstretched, all mouths remained<br>open, all glances were directed towards the marble table. Nothing<br>made its appearance there. The bailiff’s four sergeants were<br>still there, stiff, motionless, as painted statues. All eyes<br>turned to the estrade reserved for the Flemish envoys. The door<br>remained closed, the platform empty. This crowd had been waiting<br>since daybreak for three things: noonday, the embassy from<br>Flanders, the mystery play. Noonday alone had arrived on time.</p>\n<p>On this occasion, it was too much.</p>\n<p>They waited one, two, three, five minutes, a quarter of an hour;<br>nothing came. The dais remained empty, the theatre dumb. In the<br>meantime, wrath had succeeded to impatience. Irritated words<br>circulated in a low tone, still, it is true. “The mystery! the<br>mystery!” they murmured, in hollow voices. Heads began to<br>ferment. A tempest, which was only rumbling in the distance as<br>yet, was floating on the surface of this crowd. It was Jehan du<br>Moulin who struck the first spark from it.</p>\n<p>“The mystery, and to the devil with the Flemings!” he exclaimed<br>at the full force of his lungs, twining like a serpent around his<br>pillar.</p>\n<p>The crowd clapped their hands.</p>\n<p>“The mystery!” it repeated, “and may all the devils take<br>Flanders!”</p>\n<p>“We must have the mystery instantly,” resumed the student; “or<br>else, my advice is that we should hang the bailiff of the courts,<br>by way of a morality and a comedy.”</p>\n<p>“Well said,” cried the people, “and let us begin the hanging with<br>his sergeants.”</p>\n<p>A grand acclamation followed. The four poor fellows began to turn<br>pale, and to exchange glances. The crowd hurled itself towards<br>them, and they already beheld the frail wooden railing, which<br>separated them from it, giving way and bending before the<br>pressure of the throng.</p>\n<p>It was a critical moment.</p>\n<p>“To the sack, to the sack!” rose the cry on all sides.</p>\n<p>At that moment, the tapestry of the dressing-room, which we have<br>described above, was raised, and afforded passage to a personage,<br>the mere sight of whom suddenly stopped the crowd, and changed<br>its wrath into curiosity as by enchantment.</p>\n<p>“Silence! silence!”</p>\n<p>The personage, but little reassured, and trembling in every limb,<br>advanced to the edge of the marble table with a vast amount of<br>bows, which, in proportion as he drew nearer, more and more<br>resembled genuflections.</p>\n<p>In the meanwhile, tranquillity had gradually been restored. All<br>that remained was that slight murmur which always rises above the<br>silence of a crowd.</p>\n<p>“Messieurs the <em>bourgeois</em>,” said he, “and mesdemoiselles the<br><em>bourgeoises</em>, we shall have the honor of declaiming and<br>representing, before his eminence, monsieur the cardinal, a very<br>beautiful morality which has for its title, ‘The Good Judgment of<br>Madame the Virgin Mary.’ I am to play Jupiter. His eminence is,<br>at this moment, escorting the very honorable embassy of the Duke<br>of Austria; which is detained, at present, listening to the<br>harangue of monsieur the rector of the university, at the gate<br>Baudets. As soon as his illustrious eminence, the cardinal,<br>arrives, we will begin.”</p>\n<p>It is certain, that nothing less than the intervention of Jupiter<br>was required to save the four unfortunate sergeants of the<br>bailiff of the courts. If we had the happiness of having invented<br>this very veracious tale, and of being, in consequence,<br>responsible for it before our Lady Criticism, it is not against<br>us that the classic precept, <em>Nec deus intersit</em>, could be<br>invoked. Moreover, the costume of Seigneur Jupiter, was very<br>handsome, and contributed not a little towards calming the crowd,<br>by attracting all its attention. Jupiter was clad in a coat of<br>mail, covered with black velvet, with gilt nails; and had it not<br>been for the rouge, and the huge red beard, each of which covered<br>one-half of his face,—had it not been for the roll of gilded<br>cardboard, spangled, and all bristling with strips of tinsel,<br>which he held in his hand, and in which the eyes of the initiated<br>easily recognized thunderbolts,—had not his feet been<br>flesh-colored, and banded with ribbons in Greek fashion, he might<br>have borne comparison, so far as the severity of his mien was<br>concerned, with a Breton archer from the guard of Monsieur de<br>Berry.</p>\n<h1 class=\"chapter\" id=\"chapter-ii-pierre-gringoire\">Chapter II. PIERRE GRINGOIRE.</h1>\n<p>Nevertheless, as he harangued them, the satisfaction and<br>admiration unanimously excited by his costume were dissipated by<br>his words; and when he reached that untoward conclusion: “As soon<br>as his illustrious eminence, the cardinal, arrives, we will<br>begin,” his voice was drowned in a thunder of hooting.</p>\n<p>“Begin instantly! The mystery! the mystery immediately!” shrieked<br>the people. And above all the voices, that of Johannes de<br>Molendino was audible, piercing the uproar like the fife’s<br>derisive serenade: “Commence instantly!” yelped the scholar.</p>\n<p>“Down with Jupiter and the Cardinal de Bourbon!” vociferated<br>Robin Poussepain and the other clerks perched in the window.</p>\n<p>“The morality this very instant!” repeated the crowd; “this very<br>instant! the sack and the rope for the comedians, and the<br>cardinal!”</p>\n<p>Poor Jupiter, haggard, frightened, pale beneath his rouge,<br>dropped his thunderbolt, took his cap in his hand; then he bowed<br>and trembled and stammered: “His eminence—the ambassadors—Madame<br>Marguerite of Flanders—.” He did not know what to say. In truth,<br>he was afraid of being hung.</p>\n<p>Hung by the populace for waiting, hung by the cardinal for not<br>having waited, he saw between the two dilemmas only an abyss;<br>that is to say, a gallows.</p>\n<p>Luckily, some one came to rescue him from his embarrassment, and<br>assume the responsibility.</p>\n<p>An individual who was standing beyond the railing, in the free<br>space around the marble table, and whom no one had yet caught<br>sight of, since his long, thin body was completely sheltered from<br>every visual ray by the diameter of the pillar against which he<br>was leaning; this individual, we say, tall, gaunt, pallid, blond,<br>still young, although already wrinkled about the brow and cheeks,<br>with brilliant eyes and a smiling mouth, clad in garments of<br>black serge, worn and shining with age, approached the marble<br>table, and made a sign to the poor sufferer. But the other was so<br>confused that he did not see him. The new comer advanced another<br>step.</p>\n<p>“Jupiter,” said he, “my dear Jupiter!”</p>\n<p>The other did not hear.</p>\n<p>At last, the tall blond, driven out of patience, shrieked almost<br>in his face,—</p>\n<p>“Michel Giborne!”</p>\n<p>“Who calls me?” said Jupiter, as though awakened with a start.</p>\n<p>“I,” replied the person clad in black.</p>\n<p>“Ah!” said Jupiter.</p>\n<p>“Begin at once,” went on the other. “Satisfy the populace; I<br>undertake to appease the bailiff, who will appease monsieur the<br>cardinal.”</p>\n<p>Jupiter breathed once more.</p>\n<p>“Messeigneurs the <em>bourgeois</em>,” he cried, at the top of his lungs<br>to the crowd, which continued to hoot him, “we are going to begin<br>at once.”</p>\n<p>“<em>Evoe Jupiter! Plaudite cives</em>! All hail, Jupiter! Applaud,<br>citizens!” shouted the scholars.</p>\n<p>“Noël! Noël! good, good,” shouted the people.</p>\n<p>The hand clapping was deafening, and Jupiter had already<br>withdrawn under his tapestry, while the hall still trembled with<br>acclamations.</p>\n<p>In the meanwhile, the personage who had so magically turned the<br>tempest into dead calm, as our old and dear Corneille puts it,<br>had modestly retreated to the half-shadow of his pillar, and<br>would, no doubt, have remained invisible there, motionless, and<br>mute as before, had he not been plucked by the sleeve by two<br>young women, who, standing in the front row of the spectators,<br>had noticed his colloquy with Michel Giborne-Jupiter.</p>\n<p>“Master,” said one of them, making him a sign to approach.</p>\n<p>“Hold your tongue, my dear Liénarde,” said her neighbor, pretty,<br>fresh, and very brave, in consequence of being dressed up in her<br>best attire. “He is not a clerk, he is a layman; you must not say<br>master to him, but messire.”</p>\n<p>“Messire,” said Liénarde.</p>\n<p>The stranger approached the railing.</p>\n<p>“What would you have of me, damsels?” he asked, with alacrity.</p>\n<p>“Oh! nothing,” replied Liénarde, in great confusion; “it is my<br>neighbor, Gisquette la Gencienne, who wishes to speak with you.”</p>\n<p>“Not so,” replied Gisquette, blushing; “it was Liénarde who<br>called you master; I only told her to say messire.”</p>\n<p>The two young girls dropped their eyes. The man, who asked<br>nothing better than to enter into conversation, looked at them<br>with a smile.</p>\n<p>“So you have nothing to say to me, damsels?”</p>\n<p>“Oh! nothing at all,” replied Gisquette.</p>\n<p>“Nothing,” said Liénarde.</p>\n<p>The tall, light-haired young man retreated a step; but the two<br>curious maidens had no mind to let slip their prize.</p>\n<p>“Messire,” said Gisquette, with the impetuosity of an open<br>sluice, or of a woman who has made up her mind, “do you know that<br>soldier who is to play the part of Madame the Virgin in the<br>mystery?”</p>\n<p>“You mean the part of Jupiter?” replied the stranger.</p>\n<p>“Hé! yes,” said Liénarde, “isn’t she stupid? So you know<br>Jupiter?”</p>\n<p>“Michel Giborne?” replied the unknown; “yes, madam.”</p>\n<p>“He has a fine beard!” said Liénarde.</p>\n<p>“Will what they are about to say here be fine?” inquired<br>Gisquette, timidly.</p>\n<p>“Very fine, mademoiselle,” replied the unknown, without the<br>slightest hesitation.</p>\n<p>“What is it to be?” said Liénarde.</p>\n<p>“‘The Good Judgment of Madame the Virgin,’—a morality, if you<br>please, damsel.”</p>\n<p>“Ah! that makes a difference,” responded Liénarde.</p>\n<p>A brief silence ensued—broken by the stranger.</p>\n<p>“It is a perfectly new morality, and one which has never yet been<br>played.”</p>\n<p>“Then it is not the same one,” said Gisquette, “that was given<br>two years ago, on the day of the entrance of monsieur the legate,<br>and where three handsome maids played the parts—”</p>\n<p>“Of sirens,” said Liénarde.</p>\n<p>“And all naked,” added the young man.</p>\n<p>Liénarde lowered her eyes modestly. Gisquette glanced at her and<br>did the same. He continued, with a smile,—</p>\n<p>“It was a very pleasant thing to see. To-day it is a morality<br>made expressly for Madame the Demoiselle of Flanders.”</p>\n<p>“Will they sing shepherd songs?” inquired Gisquette.</p>\n<p>“Fie!” said the stranger, “in a morality? you must not confound<br>styles. If it were a farce, well and good.”</p>\n<p>“That is a pity,” resumed Gisquette. “That day, at the Ponceau<br>Fountain, there were wild men and women, who fought and assumed<br>many aspects, as they sang little motets and bergerettes.”</p>\n<p>“That which is suitable for a legate,” returned the stranger,<br>with a good deal of dryness, “is not suitable for a princess.”</p>\n<p>“And beside them,” resumed Liénarde, “played many brass<br>instruments, making great melodies.”</p>\n<p>“And for the refreshment of the passers-by,” continued Gisquette,<br>“the fountain spouted through three mouths, wine, milk, and<br>hippocrass, of which every one drank who wished.”</p>\n<p>“And a little below the Ponceau, at the Trinity,” pursued<br>Liénarde, “there was a passion performed, and without any<br>speaking.”</p>\n<p>“How well I remember that!” exclaimed Gisquette; “God on the<br>cross, and the two thieves on the right and the left.” Here the<br>young gossips, growing warm at the memory of the entrance of<br>monsieur the legate, both began to talk at once.</p>\n<p>“And, further on, at the Painters’ Gate, there were other<br>personages, very richly clad.”</p>\n<p>“And at the fountain of Saint-Innocent, that huntsman, who was<br>chasing a hind with great clamor of dogs and hunting-horns.”</p>\n<p>“And, at the Paris slaughter-houses, stages, representing the<br>fortress of Dieppe!”</p>\n<p>“And when the legate passed, you remember, Gisquette? they made<br>the assault, and the English all had their throats cut.”</p>\n<p>“And against the gate of the Châtelet, there were very fine<br>personages!”</p>\n<p>“And on the Port au Change, which was all draped above!”</p>\n<p>“And when the legate passed, they let fly on the bridge more than<br>two hundred sorts of birds; wasn’t it beautiful, Liénarde?”</p>\n<p>“It will be better to-day,” finally resumed their interlocutor,<br>who seemed to listen to them with impatience.</p>\n<p>“Do you promise us that this mystery will be fine?” said<br>Gisquette.</p>\n<p>“Without doubt,” he replied; then he added, with a certain<br>emphasis,—“I am the author of it, damsels.”</p>\n<p>“Truly?” said the young girls, quite taken aback.</p>\n<p>“Truly!” replied the poet, bridling a little; “that is, to say,<br>there are two of us; Jehan Marchand, who has sawed the planks and<br>erected the framework of the theatre and the woodwork; and I, who<br>have made the piece. My name is Pierre Gringoire.”</p>\n<p>The author of the “Cid” could not have said “Pierre Corneille”<br>with more pride.</p>\n<p>Our readers have been able to observe, that a certain amount of<br>time must have already elapsed from the moment when Jupiter had<br>retired beneath the tapestry to the instant when the author of<br>the new morality had thus abruptly revealed himself to the<br>innocent admiration of Gisquette and Liénarde. Remarkable fact:<br>that whole crowd, so tumultuous but a few moments before, now<br>waited amiably on the word of the comedian; which proves the<br>eternal truth, still experienced every day in our theatres, that<br>the best means of making the public wait patiently is to assure<br>them that one is about to begin instantly.</p>\n<p>However, scholar Johannes had not fallen asleep.</p>\n<p>“Holà hé!” he shouted suddenly, in the midst of the peaceable<br>waiting which had followed the tumult. “Jupiter, Madame the<br>Virgin, buffoons of the devil! are you jeering at us? The piece!<br>the piece! commence or we will commence again!”</p>\n<p>This was all that was needed.</p>\n<p>The music of high and low instruments immediately became audible<br>from the interior of the stage; the tapestry was raised; four<br>personages, in motley attire and painted faces, emerged from it,<br>climbed the steep ladder of the theatre, and, arrived upon the<br>upper platform, arranged themselves in a line before the public,<br>whom they saluted with profound reverences; then the symphony<br>ceased.</p>\n<p>The mystery was about to begin.</p>\n<p>The four personages, after having reaped a rich reward of<br>applause for their reverences, began, in the midst of profound<br>silence, a prologue, which we gladly spare the reader. Moreover,<br>as happens in our own day, the public was more occupied with the<br>costumes that the actors wore than with the roles that they were<br>enacting; and, in truth, they were right. All four were dressed<br>in parti-colored robes of yellow and white, which were<br>distinguished from each other only by the nature of the stuff;<br>the first was of gold and silver brocade; the second, of silk;<br>the third, of wool; the fourth, of linen. The first of these<br>personages carried in his right hand a sword; the second, two<br>golden keys; the third, a pair of scales; the fourth, a spade:<br>and, in order to aid sluggish minds which would not have seen<br>clearly through the transparency of these attributes, there was<br>to be read, in large, black letters, on the hem of the robe of<br>brocade, MY NAME IS NOBILITY; on the hem of the silken robe, MY<br>NAME IS CLERGY; on the hem of the woolen robe, MY NAME IS<br>MERCHANDISE; on the hem of the linen robe, MY NAME IS LABOR. The<br>sex of the two male characters was briefly indicated to every<br>judicious spectator, by their shorter robes, and by the cap which<br>they wore on their heads; while the two female characters, less<br>briefly clad, were covered with hoods.</p>\n<p>Much ill-will would also have been required, not to comprehend,<br>through the medium of the poetry of the prologue, that Labor was<br>wedded to Merchandise, and Clergy to Nobility, and that the two<br>happy couples possessed in common a magnificent golden dolphin,<br>which they desired to adjudge to the fairest only. So they were<br>roaming about the world seeking and searching for this beauty,<br>and, after having successively rejected the Queen of Golconda,<br>the Princess of Trebizonde, the daughter of the Grand Khan of<br>Tartary, etc., Labor and Clergy, Nobility and Merchandise, had<br>come to rest upon the marble table of the Palais de Justice, and<br>to utter, in the presence of the honest audience, as many<br>sentences and maxims as could then be dispensed at the Faculty of<br>Arts, at examinations, sophisms, determinances, figures, and<br>acts, where the masters took their degrees.</p>\n<p>All this was, in fact, very fine.</p>\n<p>Nevertheless, in that throng, upon which the four allegories vied<br>with each other in pouring out floods of metaphors, there was no<br>ear more attentive, no heart that palpitated more, not an eye was<br>more haggard, no neck more outstretched, than the eye, the ear,<br>the neck, and the heart of the author, of the poet, of that brave<br>Pierre Gringoire, who had not been able to resist, a moment<br>before, the joy of telling his name to two pretty girls. He had<br>retreated a few paces from them, behind his pillar, and there he<br>listened, looked, enjoyed. The amiable applause which had greeted<br>the beginning of his prologue was still echoing in his bosom, and<br>he was completely absorbed in that species of ecstatic<br>contemplation with which an author beholds his ideas fall, one by<br>one, from the mouth of the actor into the vast silence of the<br>audience. Worthy Pierre Gringoire!</p>\n<p>It pains us to say it, but this first ecstasy was speedily<br>disturbed. Hardly had Gringoire raised this intoxicating cup of<br>joy and triumph to his lips, when a drop of bitterness was<br>mingled with it.</p>\n<p>A tattered mendicant, who could not collect any coins, lost as he<br>was in the midst of the crowd, and who had not probably found<br>sufficient indemnity in the pockets of his neighbors, had hit<br>upon the idea of perching himself upon some conspicuous point, in<br>order to attract looks and alms. He had, accordingly, hoisted<br>himself, during the first verses of the prologue, with the aid of<br>the pillars of the reserve gallery, to the cornice which ran<br>round the balustrade at its lower edge; and there he had seated<br>himself, soliciting the attention and the pity of the multitude,<br>with his rags and a hideous sore which covered his right arm.<br>However, he uttered not a word.</p>\n<p>The silence which he preserved allowed the prologue to proceed<br>without hindrance, and no perceptible disorder would have ensued,<br>if ill-luck had not willed that the scholar Joannes should catch<br>sight, from the heights of his pillar, of the mendicant and his<br>grimaces. A wild fit of laughter took possession of the young<br>scamp, who, without caring that he was interrupting the<br>spectacle, and disturbing the universal composure, shouted<br>boldly,—</p>\n<p>“Look! see that sickly creature asking alms!”</p>\n<p>Any one who has thrown a stone into a frog pond, or fired a shot<br>into a covey of birds, can form an idea of the effect produced by<br>these incongruous words, in the midst of the general attention.<br>It made Gringoire shudder as though it had been an electric<br>shock. The prologue stopped short, and all heads turned<br>tumultuously towards the beggar, who, far from being disconcerted<br>by this, saw, in this incident, a good opportunity for reaping<br>his harvest, and who began to whine in a doleful way, half<br>closing his eyes the while,—“Charity, please!”</p>\n<p>“Well—upon my soul,” resumed Joannes, “it’s Clopin Trouillefou!<br>Holà hé, my friend, did your sore bother you on the leg, that you<br>have transferred it to your arm?” So saying, with the dexterity<br>of a monkey, he flung a bit of silver into the gray felt hat<br>which the beggar held in his ailing arm. The mendicant received<br>both the alms and the sarcasm without wincing, and continued, in<br>lamentable tones,—</p>\n<p>“Charity, please!”</p>\n<p>This episode considerably distracted the attention of the<br>audience; and a goodly number of spectators, among them Robin<br>Poussepain, and all the clerks at their head, gayly applauded<br>this eccentric duet, which the scholar, with his shrill voice,<br>and the mendicant had just improvised in the middle of the<br>prologue.</p>\n<p>Gringoire was highly displeased. On recovering from his first<br>stupefaction, he bestirred himself to shout, to the four<br>personages on the stage, “Go on! What the devil!—go on!”—without<br>even deigning to cast a glance of disdain upon the two<br>interrupters.</p>\n<p>At that moment, he felt some one pluck at the hem of his surtout;<br>he turned round, and not without ill-humor, and found<br>considerable difficulty in smiling; but he was obliged to do so,<br>nevertheless. It was the pretty arm of Gisquette la Gencienne,<br>which, passed through the railing, was soliciting his attention<br>in this manner.</p>\n<p>“Monsieur,” said the young girl, “are they going to continue?”</p>\n<p>“Of course,” replied Gringoire, a good deal shocked by the<br>question.</p>\n<p>“In that case, messire,” she resumed, “would you have the<br>courtesy to explain to me—”</p>\n<p>“What they are about to say?” interrupted Gringoire. “Well,<br>listen.”</p>\n<p>“No,” said Gisquette, “but what they have said so far.”</p>\n<p>Gringoire started, like a man whose wound has been probed to the<br>quick.</p>\n<p>“A plague on the stupid and dull-witted little girl!” he<br>muttered, between his teeth.</p>\n<p>From that moment forth, Gisquette was nothing to him.</p>\n<p>In the meantime, the actors had obeyed his injunction, and the<br>public, seeing that they were beginning to speak again, began<br>once more to listen, not without having lost many beauties in the<br>sort of soldered joint which was formed between the two portions<br>of the piece thus abruptly cut short. Gringoire commented on it<br>bitterly to himself. Nevertheless, tranquillity was gradually<br>restored, the scholar held his peace, the mendicant counted over<br>some coins in his hat, and the piece resumed the upper hand.</p>\n<p>It was, in fact, a very fine work, and one which, as it seems to<br>us, might be put to use to-day, by the aid of a little<br>rearrangement. The exposition, rather long and rather empty, that<br>is to say, according to the rules, was simple; and Gringoire, in<br>the candid sanctuary of his own conscience, admired its<br>clearness. As the reader may surmise, the four allegorical<br>personages were somewhat weary with having traversed the three<br>sections of the world, without having found suitable opportunity<br>for getting rid of their golden dolphin. Thereupon a eulogy of<br>the marvellous fish, with a thousand delicate allusions to the<br>young betrothed of Marguerite of Flanders, then sadly cloistered<br>in at Amboise, and without a suspicion that Labor and Clergy,<br>Nobility and Merchandise had just made the circuit of the world<br>in his behalf. The said dauphin was then young, was handsome, was<br>stout, and, above all (magnificent origin of all royal virtues),<br>he was the son of the Lion of France. I declare that this bold<br>metaphor is admirable, and that the natural history of the<br>theatre, on a day of allegory and royal marriage songs, is not in<br>the least startled by a dolphin who is the son of a lion. It is<br>precisely these rare and Pindaric mixtures which prove the poet’s<br>enthusiasm. Nevertheless, in order to play the part of critic<br>also, the poet might have developed this beautiful idea in<br>something less than two hundred lines. It is true that the<br>mystery was to last from noon until four o’clock, in accordance<br>with the orders of monsieur the provost, and that it was<br>necessary to say something. Besides, the people listened<br>patiently.</p>\n<p>All at once, in the very middle of a quarrel between Mademoiselle<br>Merchandise and Madame Nobility, at the moment when Monsieur<br>Labor was giving utterance to this wonderful line,—</p>\n<p>In forest ne’er was seen a more triumphant beast;</p>\n<p>the door of the reserved gallery which had hitherto remained so<br>inopportunely closed, opened still more inopportunely; and the<br>ringing voice of the usher announced abruptly, “His eminence,<br>Monseigneur the Cardinal de Bourbon.”</p>\n<h1 class=\"chapter\" id=\"chapter-iii-monsieur-the-cardinal\">Chapter III. MONSIEUR THE CARDINAL.</h1>\n<p>Poor Gringoire! the din of all the great double petards of the<br>Saint-Jean, the discharge of twenty arquebuses on supports, the<br>detonation of that famous serpentine of the Tower of Billy,<br>which, during the siege of Paris, on Sunday, the twenty-sixth of<br>September, 1465, killed seven Burgundians at one blow, the<br>explosion of all the powder stored at the gate of the Temple,<br>would have rent his ears less rudely at that solemn and dramatic<br>moment, than these few words, which fell from the lips of the<br>usher, “His eminence, Monseigneur the Cardinal de Bourbon.”</p>\n<p>It is not that Pierre Gringoire either feared or disdained<br>monsieur the cardinal. He had neither the weakness nor the<br>audacity for that. A true eclectic, as it would be expressed<br>nowadays, Gringoire was one of those firm and lofty, moderate and<br>calm spirits, which always know how to bear themselves amid all<br>circumstances (<em>stare in dimidio rerum</em>), and who are full of<br>reason and of liberal philosophy, while still setting store by<br>cardinals. A rare, precious, and never interrupted race of<br>philosophers to whom wisdom, like another Ariadne, seems to have<br>given a clew of thread which they have been walking along<br>unwinding since the beginning of the world, through the labyrinth<br>of human affairs. One finds them in all ages, ever the same; that<br>is to say, always according to all times. And, without reckoning<br>our Pierre Gringoire, who may represent them in the fifteenth<br>century if we succeed in bestowing upon him the distinction which<br>he deserves, it certainly was their spirit which animated Father<br>du Breul, when he wrote, in the sixteenth, these naively sublime<br>words, worthy of all centuries: “I am a Parisian by nation, and a<br>Parrhisian in language, for <em>parrhisia</em> in Greek signifies<br>liberty of speech; of which I have made use even towards<br>messeigneurs the cardinals, uncle and brother to Monsieur the<br>Prince de Conty, always with respect to their greatness, and<br>without offending any one of their suite, which is much to say.”</p>\n<p>There was then neither hatred for the cardinal, nor disdain for<br>his presence, in the disagreeable impression produced upon Pierre<br>Gringoire. Quite the contrary; our poet had too much good sense<br>and too threadbare a coat, not to attach particular importance to<br>having the numerous allusions in his prologue, and, in<br>particular, the glorification of the dauphin, son of the Lion of<br>France, fall upon the most eminent ear. But it is not interest<br>which predominates in the noble nature of poets. I suppose that<br>the entity of the poet may be represented by the number ten; it<br>is certain that a chemist on analyzing and pharmacopolizing it,<br>as Rabelais says, would find it composed of one part interest to<br>nine parts of self-esteem.</p>\n<p>Now, at the moment when the door had opened to admit the<br>cardinal, the nine parts of self-esteem in Gringoire, swollen and<br>expanded by the breath of popular admiration, were in a state of<br>prodigious augmentation, beneath which disappeared, as though<br>stifled, that imperceptible molecule of which we have just<br>remarked upon in the constitution of poets; a precious<br>ingredient, by the way, a ballast of reality and humanity,<br>without which they would not touch the earth. Gringoire enjoyed<br>seeing, feeling, fingering, so to speak an entire assembly (of<br>knaves, it is true, but what matters that?) stupefied, petrified,<br>and as though asphyxiated in the presence of the incommensurable<br>tirades which welled up every instant from all parts of his<br>bridal song. I affirm that he shared the general beatitude, and<br>that, quite the reverse of La Fontaine, who, at the presentation<br>of his comedy of the “Florentine,” asked, “Who is the ill-bred<br>lout who made that rhapsody?” Gringoire would gladly have<br>inquired of his neighbor, “Whose masterpiece is this?”</p>\n<p>The reader can now judge of the effect produced upon him by the<br>abrupt and unseasonable arrival of the cardinal.</p>\n<p>That which he had to fear was only too fully realized. The<br>entrance of his eminence upset the audience. All heads turned<br>towards the gallery. It was no longer possible to hear one’s<br>self. “The cardinal! The cardinal!” repeated all mouths. The<br>unhappy prologue stopped short for the second time.</p>\n<p>The cardinal halted for a moment on the threshold of the estrade.<br>While he was sending a rather indifferent glance around the<br>audience, the tumult redoubled. Each person wished to get a<br>better view of him. Each man vied with the other in thrusting his<br>head over his neighbor’s shoulder.</p>\n<p>He was, in fact, an exalted personage, the sight of whom was well<br>worth any other comedy. Charles, Cardinal de Bourbon, Archbishop<br>and Comte of Lyon, Primate of the Gauls, was allied both to Louis<br>XI., through his brother, Pierre, Seigneur de Beaujeu, who had<br>married the king’s eldest daughter, and to Charles the Bold<br>through his mother, Agnes of Burgundy. Now, the dominating trait,<br>the peculiar and distinctive trait of the character of the<br>Primate of the Gauls, was the spirit of the courtier, and<br>devotion to the powers that be. The reader can form an idea of<br>the numberless embarrassments which this double relationship had<br>caused him, and of all the temporal reefs among which his<br>spiritual bark had been forced to tack, in order not to suffer<br>shipwreck on either Louis or Charles, that Scylla and that<br>Charybdis which had devoured the Duc de Nemours and the Constable<br>de Saint-Pol. Thanks to Heaven’s mercy, he had made the voyage<br>successfully, and had reached home without hindrance. But<br>although he was in port, and precisely because he was in port, he<br>never recalled without disquiet the varied haps of his political<br>career, so long uneasy and laborious. Thus, he was in the habit<br>of saying that the year 1476 had been “white and black” for<br>him—meaning thereby, that in the course of that year he had lost<br>his mother, the Duchesse de la Bourbonnais, and his cousin, the<br>Duke of Burgundy, and that one grief had consoled him for the<br>other.</p>\n<p>Nevertheless, he was a fine man; he led a joyous cardinal’s life,<br>liked to enliven himself with the royal vintage of Challuau, did<br>not hate Richarde la Garmoise and Thomasse la Saillarde, bestowed<br>alms on pretty girls rather than on old women,—and for all these<br>reasons was very agreeable to the <em>populace</em> of Paris. He never<br>went about otherwise than surrounded by a small court of bishops<br>and abbés of high lineage, gallant, jovial, and given to<br>carousing on occasion; and more than once the good and devout<br>women of Saint Germain d’ Auxerre, when passing at night beneath<br>the brightly illuminated windows of Bourbon, had been scandalized<br>to hear the same voices which had intoned vespers for them during<br>the day carolling, to the clinking of glasses, the bacchic<br>proverb of Benedict XII., that pope who had added a third crown<br>to the Tiara—<em>Bibamus papaliter</em>.</p>\n<p>It was this justly acquired popularity, no doubt, which preserved<br>him on his entrance from any bad reception at the hands of the<br>mob, which had been so displeased but a moment before, and very<br>little disposed to respect a cardinal on the very day when it was<br>to elect a pope. But the Parisians cherish little rancor; and<br>then, having forced the beginning of the play by their authority,<br>the good <em>bourgeois</em> had got the upper hand of the cardinal, and<br>this triumph was sufficient for them. Moreover, the Cardinal de<br>Bourbon was a handsome man,—he wore a fine scarlet robe, which he<br>carried off very well,—that is to say, he had all the women on<br>his side, and, consequently, the best half of the audience.<br>Assuredly, it would be injustice and bad taste to hoot a cardinal<br>for having come late to the spectacle, when he is a handsome man,<br>and when he wears his scarlet robe well.</p>\n<p>He entered, then, bowed to those present with the hereditary<br>smile of the great for the people, and directed his course slowly<br>towards his scarlet velvet arm-chair, with the air of thinking of<br>something quite different. His cortege—what we should nowadays<br>call his staff—of bishops and abbés invaded the estrade in his<br>train, not without causing redoubled tumult and curiosity among<br>the audience. Each man vied with his neighbor in pointing them<br>out and naming them, in seeing who should recognize at least one<br>of them: this one, the Bishop of Marseilles (Alaudet, if my<br>memory serves me right);—this one, the primicier of<br>Saint-Denis;—this one, Robert de Lespinasse, Abbé of<br>Saint-Germain des Prés, that libertine brother of a mistress of<br>Louis XI.; all with many errors and absurdities. As for the<br>scholars, they swore. This was their day, their feast of fools,<br>their saturnalia, the annual orgy of the corporation of law<br>clerks and of the school. There was no turpitude which was not<br>sacred on that day. And then there were gay gossips in the<br>crowd—Simone Quatrelivres, Agnès la Gadine, and Rabine Piédebou.<br>Was it not the least that one could do to swear at one’s ease and<br>revile the name of God a little, on so fine a day, in such good<br>company as dignitaries of the church and loose women? So they did<br>not abstain; and, in the midst of the uproar, there was a<br>frightful concert of blasphemies and enormities of all the<br>unbridled tongues, the tongues of clerks and students restrained<br>during the rest of the year, by the fear of the hot iron of Saint<br>Louis. Poor Saint Louis! how they set him at defiance in his own<br>court of law! Each one of them selected from the new-comers on<br>the platform, a black, gray, white, or violet cassock as his<br>target. Joannes Frollo de Molendin, in his quality of brother to<br>an archdeacon, boldly attacked the scarlet; he sang in deafening<br>tones, with his impudent eyes fastened on the cardinal, “_Cappa<br>repleta mero_!”</p>\n<p>All these details which we here lay bare for the edification of<br>the reader, were so covered by the general uproar, that they were<br>lost in it before reaching the reserved platforms; moreover, they<br>would have moved the cardinal but little, so much a part of the<br>customs were the liberties of that day. Moreover, he had another<br>cause for solicitude, and his mien as wholly preoccupied with it,<br>which entered the estrade the same time as himself; this was the<br>embassy from Flanders.</p>\n<p>Not that he was a profound politician, nor was he borrowing<br>trouble about the possible consequences of the marriage of his<br>cousin Marguerite de Bourgoyne to his cousin Charles, Dauphin de<br>Vienne; nor as to how long the good understanding which had been<br>patched up between the Duke of Austria and the King of France<br>would last; nor how the King of England would take this disdain<br>of his daughter. All that troubled him but little; and he gave a<br>warm reception every evening to the wine of the royal vintage of<br>Chaillot, without a suspicion that several flasks of that same<br>wine (somewhat revised and corrected, it is true, by Doctor<br>Coictier), cordially offered to Edward IV. by Louis XI., would,<br>some fine morning, rid Louis XI. of Edward IV. “The much honored<br>embassy of Monsieur the Duke of Austria,” brought the cardinal<br>none of these cares, but it troubled him in another direction. It<br>was, in fact, somewhat hard, and we have already hinted at it on<br>the second page of this book,—for him, Charles de Bourbon, to be<br>obliged to feast and receive cordially no one knows what<br><em>bourgeois</em>;—for him, a cardinal, to receive aldermen;—for him, a<br>Frenchman, and a jolly companion, to receive Flemish<br>beer-drinkers,—and that in public! This was, certainly, one of<br>the most irksome grimaces that he had ever executed for the good<br>pleasure of the king.</p>\n<p>So he turned toward the door, and with the best grace in the<br>world (so well had he trained himself to it), when the usher<br>announced, in a sonorous voice, “Messieurs the Envoys of Monsieur<br>the Duke of Austria.” It is useless to add that the whole hall<br>did the same.</p>\n<p>Then arrived, two by two, with a gravity which made a contrast in<br>the midst of the frisky ecclesiastical escort of Charles de<br>Bourbon, the eight and forty ambassadors of Maximilian of<br>Austria, having at their head the reverend Father in God, Jehan,<br>Abbot of Saint-Bertin, Chancellor of the Golden Fleece, and<br>Jacques de Goy, Sieur Dauby, Grand Bailiff of Ghent. A deep<br>silence settled over the assembly, accompanied by stifled<br>laughter at the preposterous names and all the <em>bourgeois</em><br>designations which each of these personages transmitted with<br>imperturbable gravity to the usher, who then tossed names and<br>titles pell-mell and mutilated to the crowd below. There were<br>Master Loys Roelof, alderman of the city of Louvain; Messire<br>Clays d’Etuelde, alderman of Brussels; Messire Paul de Baeust,<br>Sieur de Voirmizelle, President of Flanders; Master Jehan<br>Coleghens, burgomaster of the city of Antwerp; Master George de<br>la Moere, first alderman of the kuere of the city of Ghent;<br>Master Gheldolf van der Hage, first alderman of the <em>parchons</em> of<br>the said town; and the Sieur de Bierbecque, and Jehan Pinnock,<br>and Jehan Dymaerzelle, etc., etc., etc.; bailiffs, aldermen,<br>burgomasters; burgomasters, aldermen, bailiffs—all stiff,<br>affectedly grave, formal, dressed out in velvet and damask,<br>hooded with caps of black velvet, with great tufts of Cyprus gold<br>thread; good Flemish heads, after all, severe and worthy faces,<br>of the family which Rembrandt makes to stand out so strong and<br>grave from the black background of his “Night Patrol”; personages<br>all of whom bore, written on their brows, that Maximilian of<br>Austria had done well in “trusting implicitly,” as the manifest<br>ran, “in their sense, valor, experience, loyalty, and good<br>wisdom.”</p>\n<p>There was one exception, however. It was a subtle, intelligent,<br>crafty-looking face, a sort of combined monkey and diplomat phiz,<br>before whom the cardinal made three steps and a profound bow, and<br>whose name, nevertheless, was only, “Guillaume Rym, counsellor<br>and pensioner of the City of Ghent.”</p>\n<p>Few persons were then aware who Guillaume Rym was. A rare genius<br>who in a time of revolution would have made a brilliant<br>appearance on the surface of events, but who in the fifteenth<br>century was reduced to cavernous intrigues, and to “living in<br>mines,” as the Duc de Saint-Simon expresses it. Nevertheless, he<br>was appreciated by the “miner” of Europe; he plotted familiarly<br>with Louis XI., and often lent a hand to the king’s secret jobs.<br>All which things were quite unknown to that throng, who were<br>amazed at the cardinal’s politeness to that frail figure of a<br>Flemish bailiff.</p>\n<h1 class=\"chapter\" id=\"chapter-iv-master-jacques-coppenole\">Chapter IV. MASTER JACQUES COPPENOLE.</h1>\n<p>While the pensioner of Ghent and his eminence were exchanging<br>very low bows and a few words in voices still lower, a man of<br>lofty stature, with a large face and broad shoulders, presented<br>himself, in order to enter abreast with Guillaume Rym; one would<br>have pronounced him a bull-dog by the side of a fox. His felt<br>doublet and leather jerkin made a spot on the velvet and silk<br>which surrounded him. Presuming that he was some groom who had<br>stolen in, the usher stopped him.</p>\n<p>“Hold, my friend, you cannot pass!”</p>\n<p>The man in the leather jerkin shouldered him aside.</p>\n<p>“What does this knave want with me?” said he, in stentorian<br>tones, which rendered the entire hall attentive to this strange<br>colloquy. “Don’t you see that I am one of them?”</p>\n<p>“Your name?” demanded the usher.</p>\n<p>“Jacques Coppenole.”</p>\n<p>“Your titles?”</p>\n<p>“Hosier at the sign of the ‘Three Little Chains,’ of Ghent.”</p>\n<p>The usher recoiled. One might bring one’s self to announce<br>aldermen and burgomasters, but a hosier was too much. The<br>cardinal was on thorns. All the people were staring and<br>listening. For two days his eminence had been exerting his utmost<br>efforts to lick these Flemish bears into shape, and to render<br>them a little more presentable to the public, and this freak was<br>startling. But Guillaume Rym, with his polished smile, approached<br>the usher.</p>\n<p>“Announce Master Jacques Coppenole, clerk of the aldermen of the<br>city of Ghent,” he whispered, very low.</p>\n<p>“Usher,” interposed the cardinal, aloud, “announce Master Jacques<br>Coppenole, clerk of the aldermen of the illustrious city of<br>Ghent.”</p>\n<p>This was a mistake. Guillaume Rym alone might have conjured away<br>the difficulty, but Coppenole had heard the cardinal.</p>\n<p>“No, cross of God?” he exclaimed, in his voice of thunder,<br>“Jacques Coppenole, hosier. Do you hear, usher? Nothing more,<br>nothing less. Cross of God! hosier; that’s fine enough. Monsieur<br>the Archduke has more than once sought his <em>gant</em>[5] in my hose.”</p>\n<p>Laughter and applause burst forth. A jest is always understood in<br>Paris, and, consequently, always applauded.</p>\n<p>Let us add that Coppenole was of the people, and that the<br>auditors which surrounded him were also of the people. Thus the<br>communication between him and them had been prompt, electric,<br>and, so to speak, on a level. The haughty air of the Flemish<br>hosier, by humiliating the courtiers, had touched in all these<br>plebeian souls that latent sentiment of dignity still vague and<br>indistinct in the fifteenth century.</p>\n<p>This hosier was an equal, who had just held his own before<br>monsieur the cardinal. A very sweet reflection to poor fellows<br>habituated to respect and obedience towards the underlings of the<br>sergeants of the bailiff of Sainte-Geneviève, the cardinal’s<br>train-bearer.</p>\n<p>Coppenole proudly saluted his eminence, who returned the salute<br>of the all-powerful <em>bourgeois</em> feared by Louis XI. Then, while<br>Guillaume Rym, a “sage and malicious man,” as Philippe de Comines<br>puts it, watched them both with a smile of raillery and<br>superiority, each sought his place, the cardinal quite abashed<br>and troubled, Coppenole tranquil and haughty, and thinking, no<br>doubt, that his title of hosier was as good as any other, after<br>all, and that Marie of Burgundy, mother to that Marguerite whom<br>Coppenole was to-day bestowing in marriage, would have been less<br>afraid of the cardinal than of the hosier; for it is not a<br>cardinal who would have stirred up a revolt among the men of<br>Ghent against the favorites of the daughter of Charles the Bold;<br>it is not a cardinal who could have fortified the populace with a<br>word against her tears and prayers, when the Maid of Flanders<br>came to supplicate her people in their behalf, even at the very<br>foot of the scaffold; while the hosier had only to raise his<br>leather elbow, in order to cause to fall your two heads, most<br>illustrious seigneurs, Guy d’Hymbercourt and Chancellor Guillaume<br>Hugonet.</p>\n<p>Nevertheless, all was over for the poor cardinal, and he was<br>obliged to quaff to the dregs the bitter cup of being in such bad<br>company.</p>\n<p>The reader has, probably, not forgotten the impudent beggar who<br>had been clinging fast to the fringes of the cardinal’s gallery<br>ever since the beginning of the prologue. The arrival of the<br>illustrious guests had by no means caused him to relax his hold,<br>and, while the prelates and ambassadors were packing themselves<br>into the stalls—like genuine Flemish herrings—he settled himself<br>at his ease, and boldly crossed his legs on the architrave. The<br>insolence of this proceeding was extraordinary, yet no one<br>noticed it at first, the attention of all being directed<br>elsewhere. He, on his side, perceived nothing that was going on<br>in the hall; he wagged his head with the unconcern of a<br>Neapolitan, repeating from time to time, amid the clamor, as from<br>a mechanical habit, “Charity, please!” And, assuredly, he was,<br>out of all those present, the only one who had not deigned to<br>turn his head at the altercation between Coppenole and the usher.<br>Now, chance ordained that the master hosier of Ghent, with whom<br>the people were already in lively sympathy, and upon whom all<br>eyes were riveted—should come and seat himself in the front row<br>of the gallery, directly above the mendicant; and people were not<br>a little amazed to see the Flemish ambassador, on concluding his<br>inspection of the knave thus placed beneath his eyes, bestow a<br>friendly tap on that ragged shoulder. The beggar turned round;<br>there was surprise, recognition, a lighting up of the two<br>countenances, and so forth; then, without paying the slightest<br>heed in the world to the spectators, the hosier and the wretched<br>being began to converse in a low tone, holding each other’s<br>hands, in the meantime, while the rags of Clopin Trouillefou,<br>spread out upon the cloth of gold of the dais, produced the<br>effect of a caterpillar on an orange.</p>\n<p>The novelty of this singular scene excited such a murmur of mirth<br>and gayety in the hall, that the cardinal was not slow to<br>perceive it; he half bent forward, and, as from the point where<br>he was placed he could catch only an imperfect view of<br>Trouillerfou’s ignominious doublet, he very naturally imagined<br>that the mendicant was asking alms, and, disgusted with his<br>audacity, he exclaimed: “Bailiff of the Courts, toss me that<br>knave into the river!”</p>\n<p>“Cross of God! monseigneur the cardinal,” said Coppenole, without<br>quitting Clopin’s hand, “he’s a friend of mine.”</p>\n<p>“Good! good!” shouted the populace. From that moment, Master<br>Coppenole enjoyed in Paris as in Ghent, “great favor with the<br>people; for men of that sort do enjoy it,” says Philippe de<br>Comines, “when they are thus disorderly.” The cardinal bit his<br>lips. He bent towards his neighbor, the Abbé of Sainte-Geneviève,<br>and said to him in a low tone,—“Fine ambassadors monsieur the<br>archduke sends here, to announce to us Madame Marguerite!”</p>\n<p>“Your eminence,” replied the abbé, “wastes your politeness on<br>these Flemish swine. <em>Margaritas ante porcos</em>, pearls before<br>swine.”</p>\n<p>“Say rather,” retorted the cardinal, with a smile, “_Porcos ante<br>Margaritam_, swine before the pearl.”</p>\n<p>The whole little court in cassocks went into ecstacies over this<br>play upon words. The cardinal felt a little relieved; he was<br>quits with Coppenole, he also had had his jest applauded.</p>\n<p>Now, will those of our readers who possess the power of<br>generalizing an image or an idea, as the expression runs in the<br>style of to-day, permit us to ask them if they have formed a very<br>clear conception of the spectacle presented at this moment, upon<br>which we have arrested their attention, by the vast parallelogram<br>of the grand hall of the palace.</p>\n<p>In the middle of the hall, backed against the western wall, a<br>large and magnificent gallery draped with cloth of gold, into<br>which enter in procession, through a small, arched door, grave<br>personages, announced successively by the shrill voice of an<br>usher. On the front benches were already a number of venerable<br>figures, muffled in ermine, velvet, and scarlet. Around the<br>dais—which remains silent and dignified—below, opposite,<br>everywhere, a great crowd and a great murmur. Thousands of<br>glances directed by the people on each face upon the dais, a<br>thousand whispers over each name. Certainly, the spectacle is<br>curious, and well deserves the attention of the spectators. But<br>yonder, quite at the end, what is that sort of trestle work with<br>four motley puppets upon it, and more below? Who is that man<br>beside the trestle, with a black doublet and a pale face? Alas!<br>my dear reader, it is Pierre Gringoire and his prologue.</p>\n<p>We have all forgotten him completely.</p>\n<p>This is precisely what he feared.</p>\n<p>From the moment of the cardinal’s entrance, Gringoire had never<br>ceased to tremble for the safety of his prologue. At first he had<br>enjoined the actors, who had stopped in suspense, to continue,<br>and to raise their voices; then, perceiving that no one was<br>listening, he had stopped them; and, during the entire quarter of<br>an hour that the interruption lasted, he had not ceased to stamp,<br>to flounce about, to appeal to Gisquette and Liénarde, and to<br>urge his neighbors to the continuance of the prologue; all in<br>vain. No one quitted the cardinal, the embassy, and the<br>gallery—sole centre of this vast circle of visual rays. We must<br>also believe, and we say it with regret, that the prologue had<br>begun slightly to weary the audience at the moment when his<br>eminence had arrived, and created a diversion in so terrible a<br>fashion. After all, on the gallery as well as on the marble<br>table, the spectacle was the same: the conflict of Labor and<br>Clergy, of Nobility and Merchandise. And many people preferred to<br>see them alive, breathing, moving, elbowing each other in flesh<br>and blood, in this Flemish embassy, in this Episcopal court,<br>under the cardinal’s robe, under Coppenole’s jerkin, than<br>painted, decked out, talking in verse, and, so to speak, stuffed<br>beneath the yellow amid white tunics in which Gringoire had so<br>ridiculously clothed them.</p>\n<p>Nevertheless, when our poet beheld quiet reestablished to some<br>extent, he devised a stratagem which might have redeemed all.</p>\n<p>“Monsieur,” he said, turning towards one of his neighbors, a<br>fine, big man, with a patient face, “suppose we begin again.”</p>\n<p>“What?” said his neighbor.</p>\n<p>“Hé! the Mystery,” said Gringoire.</p>\n<p>“As you like,” returned his neighbor.</p>\n<p>This semi-approbation sufficed for Gringoire, and, conducting his<br>own affairs, he began to shout, confounding himself with the<br>crowd as much as possible: “Begin the mystery again! begin<br>again!”</p>\n<p>“The devil!” said Joannes de Molendino, “what are they jabbering<br>down yonder, at the end of the hall?” (for Gringoire was making<br>noise enough for four.) “Say, comrades, isn’t that mystery<br>finished? They want to begin it all over again. That’s not fair!”</p>\n<p>“No, no!” shouted all the scholars. “Down with the mystery! Down<br>with it!”</p>\n<p>But Gringoire had multiplied himself, and only shouted the more<br>vigorously: “Begin again! begin again!”</p>\n<p>These clamors attracted the attention of the cardinal.</p>\n<p>“Monsieur Bailiff of the Courts,” said he to a tall, black man,<br>placed a few paces from him, “are those knaves in a holy-water<br>vessel, that they make such a hellish noise?”</p>\n<p>The bailiff of the courts was a sort of amphibious magistrate, a<br>sort of bat of the judicial order, related to both the rat and<br>the bird, the judge and the soldier.</p>\n<p>He approached his eminence, and not without a good deal of fear<br>of the latter’s displeasure, he awkwardly explained to him the<br>seeming disrespect of the audience: that noonday had arrived<br>before his eminence, and that the comedians had been forced to<br>begin without waiting for his eminence.</p>\n<p>The cardinal burst into a laugh.</p>\n<p>“On my faith, the rector of the university ought to have done the<br>same. What say you, Master Guillaume Rym?”</p>\n<p>“Monseigneur,” replied Guillaume Rym, “let us be content with<br>having escaped half of the comedy. There is at least that much<br>gained.”</p>\n<p>“Can these rascals continue their farce?” asked the bailiff.</p>\n<p>“Continue, continue,” said the cardinal, “it’s all the same to<br>me. I’ll read my breviary in the meantime.”</p>\n<p>The bailiff advanced to the edge of the estrade, and cried, after<br>having invoked silence by a wave of the hand,—</p>\n<p>“<em>Bourgeois</em>, rustics, and citizens, in order to satisfy those<br>who wish the play to begin again, and those who wish it to end,<br>his eminence orders that it be continued.”</p>\n<p>Both parties were forced to resign themselves. But the public and<br>the author long cherished a grudge against the cardinal.</p>\n<p>So the personages on the stage took up their parts, and Gringoire<br>hoped that the rest of his work, at least, would be listened to.<br>This hope was speedily dispelled like his other illusions;<br>silence had indeed, been restored in the audience, after a<br>fashion; but Gringoire had not observed that at the moment when<br>the cardinal gave the order to continue, the gallery was far from<br>full, and that after the Flemish envoys there had arrived new<br>personages forming part of the <em>cortège</em>, whose names and ranks,<br>shouted out in the midst of his dialogue by the intermittent cry<br>of the usher, produced considerable ravages in it. Let the reader<br>imagine the effect in the midst of a theatrical piece, of the<br>yelping of an usher, flinging in between two rhymes, and often in<br>the middle of a line, parentheses like the following,—</p>\n<p>“Master Jacques Charmolue, procurator to the king in the<br>Ecclesiastical Courts!”</p>\n<p>“Jehan de Harlay, equerry guardian of the office of chevalier of<br>the night watch of the city of Paris!”</p>\n<p>“Messire Galiot de Genoilhac, chevalier, seigneur de Brussac,<br>master of the king’s artillery!”</p>\n<p>“Master Dreux-Raguier, surveyor of the woods and forests of the<br>king our sovereign, in the land of France, Champagne and Brie!”</p>\n<p>“Messire Louis de Graville, chevalier, councillor, and<br>chamberlain of the king, admiral of France, keeper of the Forest<br>of Vincennes!”</p>\n<p>“Master Denis le Mercier, guardian of the house of the blind at<br>Paris!” etc., etc., etc.</p>\n<p>This was becoming unbearable.</p>\n<p>This strange accompaniment, which rendered it difficult to follow<br>the piece, made Gringoire all the more indignant because he could<br>not conceal from himself the fact that the interest was<br>continually increasing, and that all his work required was a<br>chance of being heard.</p>\n<p>It was, in fact, difficult to imagine a more ingenious and more<br>dramatic composition. The four personages of the prologue were<br>bewailing themselves in their mortal embarrassment, when Venus in<br>person, (<em>vera incessa patuit dea</em>) presented herself to them,<br>clad in a fine robe bearing the heraldic device of the ship of<br>the city of Paris. She had come herself to claim the dolphin<br>promised to the most beautiful. Jupiter, whose thunder could be<br>heard rumbling in the dressing-room, supported her claim, and<br>Venus was on the point of carrying it off,—that is to say,<br>without allegory, of marrying monsieur the dauphin, when a young<br>child clad in white damask, and holding in her hand a daisy (a<br>transparent personification of Mademoiselle Marguerite of<br>Flanders) came to contest it with Venus.</p>\n<p>Theatrical effect and change.</p>\n<p>After a dispute, Venus, Marguerite, and the assistants agreed to<br>submit to the good judgment of time holy Virgin. There was<br>another good part, that of the king of Mesopotamia; but through<br>so many interruptions, it was difficult to make out what end he<br>served. All these persons had ascended by the ladder to the<br>stage.</p>\n<p>But all was over; none of these beauties had been felt nor<br>understood. On the entrance of the cardinal, one would have said<br>that an invisible magic thread had suddenly drawn all glances<br>from the marble table to the gallery, from the southern to the<br>western extremity of the hall. Nothing could disenchant the<br>audience; all eyes remained fixed there, and the new-comers and<br>their accursed names, and their faces, and their costumes,<br>afforded a continual diversion. This was very distressing. With<br>the exception of Gisquette and Liénarde, who turned round from<br>time to time when Gringoire plucked them by the sleeve; with the<br>exception of the big, patient neighbor, no one listened, no one<br>looked at the poor, deserted morality full face. Gringoire saw<br>only profiles.</p>\n<p>With what bitterness did he behold his whole erection of glory<br>and of poetry crumble away bit by bit! And to think that these<br>people had been upon the point of instituting a revolt against<br>the bailiff through impatience to hear his work! now that they<br>had it they did not care for it. This same representation which<br>had been begun amid so unanimous an acclamation! Eternal flood<br>and ebb of popular favor! To think that they had been on the<br>point of hanging the bailiff’s sergeant! What would he not have<br>given to be still at that hour of honey!</p>\n<p>But the usher’s brutal monologue came to an end; every one had<br>arrived, and Gringoire breathed freely once more; the actors<br>continued bravely. But Master Coppenole, the hosier, must needs<br>rise of a sudden, and Gringoire was forced to listen to him<br>deliver, amid universal attention, the following abominable<br>harangue.</p>\n<p>“Messieurs the <em>bourgeois</em> and squires of Paris, I don’t know,<br>cross of God! what we are doing here. I certainly do see yonder<br>in the corner on that stage, some people who appear to be<br>fighting. I don’t know whether that is what you call a “mystery,”<br>but it is not amusing; they quarrel with their tongues and<br>nothing more. I have been waiting for the first blow this quarter<br>of an hour; nothing comes; they are cowards who only scratch each<br>other with insults. You ought to send for the fighters of London<br>or Rotterdam; and, I can tell you! you would have had blows of<br>the fist that could be heard in the Place; but these men excite<br>our pity. They ought at least, to give us a moorish dance, or<br>some other mummer! That is not what was told me; I was promised a<br>feast of fools, with the election of a pope. We have our pope of<br>fools at Ghent also; we’re not behindhand in that, cross of God!<br>But this is the way we manage it; we collect a crowd like this<br>one here, then each person in turn passes his head through a<br>hole, and makes a grimace at the rest; time one who makes the<br>ugliest, is elected pope by general acclamation; that’s the way<br>it is. It is very diverting. Would you like to make your pope<br>after the fashion of my country? At all events, it will be less<br>wearisome than to listen to chatterers. If they wish to come and<br>make their grimaces through the hole, they can join the game.<br>What say you, Messieurs les <em>bourgeois</em>? You have here enough<br>grotesque specimens of both sexes, to allow of laughing in<br>Flemish fashion, and there are enough of us ugly in countenance<br>to hope for a fine grinning match.”</p>\n<p>Gringoire would have liked to retort; stupefaction, rage,<br>indignation, deprived him of words. Moreover, the suggestion of<br>the popular hosier was received with such enthusiasm by these<br><em>bourgeois</em> who were flattered at being called “squires,” that<br>all resistance was useless. There was nothing to be done but to<br>allow one’s self to drift with the torrent. Gringoire hid his<br>face between his two hands, not being so fortunate as to have a<br>mantle with which to veil his head, like Agamemnon of Timantis.</p>\n<h1 class=\"chapter\" id=\"chapter-v-quasimodo\">Chapter V. QUASIMODO.</h1>\n<p>In the twinkling of an eye, all was ready to execute Coppenole’s<br>idea. <em>Bourgeois</em>, scholars and law clerks all set to work. The<br>little chapel situated opposite the marble table was selected for<br>the scene of the grinning match. A pane broken in the pretty rose<br>window above the door, left free a circle of stone through which<br>it was agreed that the competitors should thrust their heads. In<br>order to reach it, it was only necessary to mount upon a couple<br>of hogsheads, which had been produced from I know not where, and<br>perched one upon the other, after a fashion. It was settled that<br>each candidate, man or woman (for it was possible to choose a<br>female pope), should, for the sake of leaving the impression of<br>his grimace fresh and complete, cover his face and remain<br>concealed in the chapel until the moment of his appearance. In<br>less than an instant, the chapel was crowded with competitors,<br>upon whom the door was then closed.</p>\n<p>Coppenole, from his post, ordered all, directed all, arranged<br>all. During the uproar, the cardinal, no less abashed than<br>Gringoire, had retired with all his suite, under the pretext of<br>business and vespers, without the crowd which his arrival had so<br>deeply stirred being in the least moved by his departure.<br>Guillaume Rym was the only one who noticed his eminence’s<br>discomfiture. The attention of the populace, like the sun,<br>pursued its revolution; having set out from one end of the hall,<br>and halted for a space in the middle, it had now reached the<br>other end. The marble table, the brocaded gallery had each had<br>their day; it was now the turn of the chapel of Louis XI.<br>Henceforth, the field was open to all folly. There was no one<br>there now, but the Flemings and the rabble.</p>\n<p>The grimaces began. The first face which appeared at the<br>aperture, with eyelids turned up to the reds, a mouth open like a<br>maw, and a brow wrinkled like our hussar boots of the Empire,<br>evoked such an inextinguishable peal of laughter that Homer would<br>have taken all these louts for gods. Nevertheless, the grand hall<br>was anything but Olympus, and Gringoire’s poor Jupiter knew it<br>better than any one else. A second and third grimace followed,<br>then another and another; and the laughter and transports of<br>delight went on increasing. There was in this spectacle, a<br>peculiar power of intoxication and fascination, of which it would<br>be difficult to convey to the reader of our day and our salons<br>any idea.</p>\n<p>Let the reader picture to himself a series of visages presenting<br>successively all geometrical forms, from the triangle to the<br>trapezium, from the cone to the polyhedron; all human<br>expressions, from wrath to lewdness; all ages, from the wrinkles<br>of the new-born babe to the wrinkles of the aged and dying; all<br>religious phantasmagories, from Faun to Beelzebub; all animal<br>profiles, from the maw to the beak, from the jowl to the muzzle.<br>Let the reader imagine all these grotesque figures of the Pont<br>Neuf, those nightmares petrified beneath the hand of Germain<br>Pilon, assuming life and breath, and coming in turn to stare you<br>in the face with burning eyes; all the masks of the Carnival of<br>Venice passing in succession before your glass,—in a word, a<br>human kaleidoscope.</p>\n<p>The orgy grew more and more Flemish. Teniers could have given but<br>a very imperfect idea of it. Let the reader picture to himself in<br>bacchanal form, Salvator Rosa’s battle. There were no longer<br>either scholars or ambassadors or <em>bourgeois</em> or men or women;<br>there was no longer any Clopin Trouillefou, nor Gilles Lecornu,<br>nor Marie Quatrelivres, nor Robin Poussepain. All was universal<br>license. The grand hall was no longer anything but a vast furnace<br>of effrontry and joviality, where every mouth was a cry, every<br>individual a posture; everything shouted and howled. The strange<br>visages which came, in turn, to gnash their teeth in the rose<br>window, were like so many brands cast into the brazier; and from<br>the whole of this effervescing crowd, there escaped, as from a<br>furnace, a sharp, piercing, stinging noise, hissing like the<br>wings of a gnat.</p>\n<p>“Ho hé! curse it!”</p>\n<p>“Just look at that face!”</p>\n<p>“It’s not good for anything.”</p>\n<p>“Guillemette Maugerepuis, just look at that bull’s muzzle; it<br>only lacks the horns. It can’t be your husband.”</p>\n<p>“Another!”</p>\n<p>“Belly of the pope! what sort of a grimace is that?”</p>\n<p>“Holà hé! that’s cheating. One must show only one’s face.”</p>\n<p>“That damned Perrette Callebotte! she’s capable of that!”</p>\n<p>“Good! Good!”</p>\n<p>“I’m stifling!”</p>\n<p>“There’s a fellow whose ears won’t go through!” Etc., etc.</p>\n<p>But we must do justice to our friend Jehan. In the midst of this<br>witches’ sabbath, he was still to be seen on the top of his<br>pillar, like the cabin-boy on the topmast. He floundered about<br>with incredible fury. His mouth was wide open, and from it there<br>escaped a cry which no one heard, not that it was covered by the<br>general clamor, great as that was but because it attained, no<br>doubt, the limit of perceptible sharp sounds, the thousand<br>vibrations of Sauveur, or the eight thousand of Biot.</p>\n<p>As for Gringoire, the first moment of depression having passed,<br>he had regained his composure. He had hardened himself against<br>adversity.—“Continue!” he had said for the third time, to his<br>comedians, speaking machines; then as he was marching with great<br>strides in front of the marble table, a fancy seized him to go<br>and appear in his turn at the aperture of the chapel, were it<br>only for the pleasure of making a grimace at that ungrateful<br>populace.—“But no, that would not be worthy of us; no, vengeance!<br>let us combat until the end,” he repeated to himself; “the power<br>of poetry over people is great; I will bring them back. We shall<br>see which will carry the day, grimaces or polite literature.”</p>\n<p>Alas! he had been left the sole spectator of his piece. It was<br>far worse than it had been a little while before. He no longer<br>beheld anything but backs.</p>\n<p>I am mistaken. The big, patient man, whom he had already<br>consulted in a critical moment, had remained with his face turned<br>towards the stage. As for Gisquette and Liénarde, they had<br>deserted him long ago.</p>\n<p>Gringoire was touched to the heart by the fidelity of his only<br>spectator. He approached him and addressed him, shaking his arm<br>slightly; for the good man was leaning on the balustrade and<br>dozing a little.</p>\n<p>“Monsieur,” said Gringoire, “I thank you!”</p>\n<p>“Monsieur,” replied the big man with a yawn, “for what?”</p>\n<p>“I see what wearies you,” resumed the poet; “’tis all this noise<br>which prevents your hearing comfortably. But be at ease! your<br>name shall descend to posterity! Your name, if you please?”</p>\n<p>“Renauld Chateau, guardian of the seals of the Châtelet of Paris,<br>at your service.”</p>\n<p>“Monsieur, you are the only representative of the muses here,”<br>said Gringoire.</p>\n<p>“You are too kind, sir,” said the guardian of the seals at the<br>Châtelet.</p>\n<p>“You are the only one,” resumed Gringoire, “who has listened to<br>the piece decorously. What do you think of it?”</p>\n<p>“He! he!” replied the fat magistrate, half aroused, “it’s<br>tolerably jolly, that’s a fact.”</p>\n<p>Gringoire was forced to content himself with this eulogy; for a<br>thunder of applause, mingled with a prodigious acclamation, cut<br>their conversation short. The Pope of the Fools had been elected.</p>\n<p>“Noël! Noël! Noël!”[6] shouted the people on all sides. That was,<br>in fact, a marvellous grimace which was beaming at that moment<br>through the aperture in the rose window. After all the<br>pentagonal, hexagonal, and whimsical faces, which had succeeded<br>each other at that hole without realizing the ideal of the<br>grotesque which their imaginations, excited by the orgy, had<br>constructed, nothing less was needed to win their suffrages than<br>the sublime grimace which had just dazzled the assembly. Master<br>Coppenole himself applauded, and Clopin Trouillefou, who had been<br>among the competitors (and God knows what intensity of ugliness<br>his visage could attain), confessed himself conquered: We will do<br>the same. We shall not try to give the reader an idea of that<br>tetrahedral nose, that horseshoe mouth; that little left eye<br>obstructed with a red, bushy, bristling eyebrow, while the right<br>eye disappeared entirely beneath an enormous wart; of those teeth<br>in disarray, broken here and there, like the embattled parapet of<br>a fortress; of that callous lip, upon which one of these teeth<br>encroached, like the tusk of an elephant; of that forked chin;<br>and above all, of the expression spread over the whole; of that<br>mixture of malice, amazement, and sadness. Let the reader dream<br>of this whole, if he can.</p>\n<p>The acclamation was unanimous; people rushed towards the chapel.<br>They made the lucky Pope of the Fools come forth in triumph. But<br>it was then that surprise and admiration attained their highest<br>pitch; the grimace was his face.</p>\n<p>Or rather, his whole person was a grimace. A huge head, bristling<br>with red hair; between his shoulders an enormous hump, a<br>counterpart perceptible in front; a system of thighs and legs so<br>strangely astray that they could touch each other only at the<br>knees, and, viewed from the front, resembled the crescents of two<br>scythes joined by the handles; large feet, monstrous hands; and,<br>with all this deformity, an indescribable and redoubtable air of<br>vigor, agility, and courage,—strange exception to the eternal<br>rule which wills that force as well as beauty shall be the result<br>of harmony. Such was the pope whom the fools had just chosen for<br>themselves.</p>\n<p>One would have pronounced him a giant who had been broken and<br>badly put together again.</p>\n<p>When this species of cyclops appeared on the threshold of the<br>chapel, motionless, squat, and almost as broad as he was tall;<br><em>squared</em> on the <em>base</em>, as a great man says; with his doublet<br>half red, half violet, sown with silver bells, and, above all, in<br>the perfection of his ugliness, the populace recognized him on<br>the instant, and shouted with one voice,—</p>\n<p>“’Tis Quasimodo, the bellringer! ’tis Quasimodo, the hunchback of<br>Notre-Dame! Quasimodo, the one-eyed! Quasimodo, the bandy-legged!<br>Noël! Noël!”</p>\n<p>It will be seen that the poor fellow had a choice of surnames.</p>\n<p>“Let the women with child beware!” shouted the scholars.</p>\n<p>“Or those who wish to be,” resumed Joannes.</p>\n<p>The women did, in fact, hide their faces.</p>\n<p>“Oh! the horrible monkey!” said one of them.</p>\n<p>“As wicked as he is ugly,” retorted another.</p>\n<p>“He’s the devil,” added a third.</p>\n<p>“I have the misfortune to live near Notre-Dame; I hear him<br>prowling round the eaves by night.”</p>\n<p>“With the cats.”</p>\n<p>“He’s always on our roofs.”</p>\n<p>“He throws spells down our chimneys.”</p>\n<p>“The other evening, he came and made a grimace at me through my<br>attic window. I thought that it was a man. Such a fright as I<br>had!”</p>\n<p>“I’m sure that he goes to the witches’ sabbath. Once he left a<br>broom on my leads.”</p>\n<p>“Oh! what a displeasing hunchback’s face!”</p>\n<p>“Oh! what an ill-favored soul!”</p>\n<p>“Whew!”</p>\n<p>The men, on the contrary, were delighted and applauded.<br>Quasimodo, the object of the tumult, still stood on the threshold<br>of the chapel, sombre and grave, and allowed them to admire him.</p>\n<p>One scholar (Robin Poussepain, I think), came and laughed in his<br>face, and too close. Quasimodo contented himself with taking him<br>by the girdle, and hurling him ten paces off amid the crowd; all<br>without uttering a word.</p>\n<p>Master Coppenole, in amazement, approached him.</p>\n<p>“Cross of God! Holy Father! you possess the handsomest ugliness<br>that I have ever beheld in my life. You would deserve to be pope<br>at Rome, as well as at Paris.”</p>\n<p>So saying, he placed his hand gayly on his shoulder. Quasimodo<br>did not stir. Coppenole went on,—</p>\n<p>“You are a rogue with whom I have a fancy for carousing, were it<br>to cost me a new dozen of twelve livres of Tours. How does it<br>strike you?”</p>\n<p>Quasimodo made no reply.</p>\n<p>“Cross of God!” said the hosier, “are you deaf?”</p>\n<p>He was, in truth, deaf.</p>\n<p>Nevertheless, he began to grow impatient with Coppenole’s<br>behavior, and suddenly turned towards him with so formidable a<br>gnashing of teeth, that the Flemish giant recoiled, like a<br>bull-dog before a cat.</p>\n<p>Then there was created around that strange personage, a circle of<br>terror and respect, whose radius was at least fifteen geometrical<br>feet. An old woman explained to Coppenole that Quasimodo was<br>deaf.</p>\n<p>“Deaf!” said the hosier, with his great Flemish laugh. “Cross of<br>God! He’s a perfect pope!”</p>\n<p>“Hé! I recognize him,” exclaimed Jehan, who had, at last,<br>descended from his capital, in order to see Quasimodo at closer<br>quarters, “he’s the bellringer of my brother, the archdeacon.<br>Good-day, Quasimodo!”</p>\n<p>“What a devil of a man!” said Robin Poussepain still all bruised<br>with his fall. “He shows himself; he’s a hunchback. He walks;<br>he’s bandy-legged. He looks at you; he’s one-eyed. You speak to<br>him; he’s deaf. And what does this Polyphemus do with his<br>tongue?”</p>\n<p>“He speaks when he chooses,” said the old woman; “he became deaf<br>through ringing the bells. He is not dumb.”</p>\n<p>“That he lacks,” remarks Jehan.</p>\n<p>“And he has one eye too many,” added Robin Poussepain.</p>\n<p>“Not at all,” said Jehan wisely. “A one-eyed man is far less<br>complete than a blind man. He knows what he lacks.”</p>\n<p>In the meantime, all the beggars, all the lackeys, all the<br>cutpurses, joined with the scholars, had gone in procession to<br>seek, in the cupboard of the law clerks’ company, the cardboard<br>tiara, and the derisive robe of the Pope of the Fools. Quasimodo<br>allowed them to array him in them without wincing, and with a<br>sort of proud docility. Then they made him seat himself on a<br>motley litter. Twelve officers of the fraternity of fools raised<br>him on their shoulders; and a sort of bitter and disdainful joy<br>lighted up the morose face of the cyclops, when he beheld beneath<br>his deformed feet all those heads of handsome, straight,<br>well-made men. Then the ragged and howling procession set out on<br>its march, according to custom, around the inner galleries of the<br>Courts, before making the circuit of the streets and squares.</p>\n<h1 class=\"chapter\" id=\"chapter-vi-esmeralda\">Chapter VI. ESMERALDA.</h1>\n<p>We are delighted to be able to inform the reader, that during the<br>whole of this scene, Gringoire and his piece had stood firm. His<br>actors, spurred on by him, had not ceased to spout his comedy,<br>and he had not ceased to listen to it. He had made up his mind<br>about the tumult, and was determined to proceed to the end, not<br>giving up the hope of a return of attention on the part of the<br>public. This gleam of hope acquired fresh life, when he saw<br>Quasimodo, Coppenole, and the deafening escort of the pope of the<br>procession of fools quit the hall amid great uproar. The throng<br>rushed eagerly after them. “Good,” he said to himself, “there go<br>all the mischief-makers.” Unfortunately, all the mischief-makers<br>constituted the entire audience. In the twinkling of an eye, the<br>grand hall was empty.</p>\n<p>To tell the truth, a few spectators still remained, some<br>scattered, others in groups around the pillars, women, old men,<br>or children, who had had enough of the uproar and tumult. Some<br>scholars were still perched astride of the window-sills, engaged<br>in gazing into the Place.</p>\n<p>“Well,” thought Gringoire, “here are still as many as are<br>required to hear the end of my mystery. They are few in number,<br>but it is a choice audience, a lettered audience.”</p>\n<p>An instant later, a symphony which had been intended to produce<br>the greatest effect on the arrival of the Virgin, was lacking.<br>Gringoire perceived that his music had been carried off by the<br>procession of the Pope of the Fools. “Skip it,” said he,<br>stoically.</p>\n<p>He approached a group of <em>bourgeois</em>, who seemed to him to be<br>discussing his piece. This is the fragment of conversation which<br>he caught,—</p>\n<p>“You know, Master Cheneteau, the Hôtel de Navarre, which belonged<br>to Monsieur de Nemours?”</p>\n<p>“Yes, opposite the Chapelle de Braque.”</p>\n<p>“Well, the treasury has just let it to Guillaume Alixandre,<br>historian, for six livres, eight sols, parisian, a year.”</p>\n<p>“How rents are going up!”</p>\n<p>“Come,” said Gringoire to himself, with a sigh, “the others are<br>listening.”</p>\n<p>“Comrades,” suddenly shouted one of the young scamps from the<br>window, “La Esmeralda! La Esmeralda in the Place!”</p>\n<p>This word produced a magical effect. Every one who was left in<br>the hall flew to the windows, climbing the walls in order to see,<br>and repeating, “La Esmeralda! La Esmeralda?” At the same time, a<br>great sound of applause was heard from without.</p>\n<p>“What’s the meaning of this, of the Esmeralda?” said Gringoire,<br>wringing his hands in despair. “Ah, good heavens! it seems to be<br>the turn of the windows now.”</p>\n<p>He returned towards the marble table, and saw that the<br>representation had been interrupted. It was precisely at the<br>instant when Jupiter should have appeared with his thunder. But<br>Jupiter was standing motionless at the foot of the stage.</p>\n<p>“Michel Giborne!” cried the irritated poet, “what are you doing<br>there? Is that your part? Come up!”</p>\n<p>“Alas!” said Jupiter, “a scholar has just seized the ladder.”</p>\n<p>Gringoire looked. It was but too true. All communication between<br>his plot and its solution was intercepted.</p>\n<p>“The rascal,” he murmured. “And why did he take that ladder?”</p>\n<p>“In order to go and see the Esmeralda,” replied Jupiter<br>piteously. “He said, ‘Come, here’s a ladder that’s of no use!’<br>and he took it.”</p>\n<p>This was the last blow. Gringoire received it with resignation.</p>\n<p>“May the devil fly away with you!” he said to the comedian, “and<br>if I get my pay, you shall receive yours.”</p>\n<p>Then he beat a retreat, with drooping head, but the last in the<br>field, like a general who has fought well.</p>\n<p>And as he descended the winding stairs of the courts: “A fine<br>rabble of asses and dolts these Parisians!” he muttered between<br>his teeth; “they come to hear a mystery and don’t listen to it at<br>all! They are engrossed by every one, by Clopin Trouillefou, by<br>the cardinal, by Coppenole, by Quasimodo, by the devil! but by<br>Madame the Virgin Mary, not at all. If I had known, I’d have<br>given you Virgin Mary; you ninnies! And I! to come to see faces<br>and behold only backs! to be a poet, and to reap the success of<br>an apothecary! It is true that Homerus begged through the Greek<br>towns, and that Naso died in exile among the Muscovites. But may<br>the devil flay me if I understand what they mean with their<br>Esmeralda! What is that word, in the first place?—’tis Egyptian!”</p>\n<p>BOOK SECOND.</p>\n<h1 class=\"chapter\" id=\"chapter-i-from-charybdis-to-scylla\">Chapter I. FROM CHARYBDIS TO SCYLLA.</h1>\n<p>Night comes on early in January. The streets were already dark<br>when Gringoire issued forth from the Courts. This gloom pleased<br>him; he was in haste to reach some obscure and deserted alley, in<br>order there to meditate at his ease, and in order that the<br>philosopher might place the first dressing upon the wound of the<br>poet. Philosophy, moreover, was his sole refuge, for he did not<br>know where he was to lodge for the night. After the brilliant<br>failure of his first theatrical venture, he dared not return to<br>the lodging which he occupied in the Rue Grenier-sur-l’Eau,<br>opposite to the Port-au-Foin, having depended upon receiving from<br>monsieur the provost for his epithalamium, the wherewithal to pay<br>Master Guillaume Doulx-Sire, farmer of the taxes on cloven-footed<br>animals in Paris, the rent which he owed him, that is to say,<br>twelve sols parisian; twelve times the value of all that he<br>possessed in the world, including his trunk-hose, his shirt, and<br>his cap. After reflecting a moment, temporarily sheltered beneath<br>the little wicket of the prison of the treasurer of the<br>Sainte-Chappelle, as to the shelter which he would select for the<br>night, having all the pavements of Paris to choose from, he<br>remembered to have noticed the week previously in the Rue de la<br>Savaterie, at the door of a councillor of the parliament, a<br>stepping stone for mounting a mule, and to have said to himself<br>that that stone would furnish, on occasion, a very excellent<br>pillow for a mendicant or a poet. He thanked Providence for<br>having sent this happy idea to him; but, as he was preparing to<br>cross the Place, in order to reach the tortuous labyrinth of the<br>city, where meander all those old sister streets, the Rues de la<br>Barillerie, de la Vieille-Draperie, de la Savaterie, de la<br>Juiverie, etc., still extant to-day, with their nine-story<br>houses, he saw the procession of the Pope of the Fools, which was<br>also emerging from the court house, and rushing across the<br>courtyard, with great cries, a great flashing of torches, and the<br>music which belonged to him, Gringoire. This sight revived the<br>pain of his self-love; he fled. In the bitterness of his dramatic<br>misadventure, everything which reminded him of the festival of<br>that day irritated his wound and made it bleed.</p>\n<p>He was on the point of turning to the Pont Saint-Michel; children<br>were running about here and there with fire lances and rockets.</p>\n<p>“Pest on firework candles!” said Gringoire; and he fell back on<br>the Pont au Change. To the house at the head of the bridge there<br>had been affixed three small banners, representing the king, the<br>dauphin, and Marguerite of Flanders, and six little pennons on<br>which were portrayed the Duke of Austria, the Cardinal de<br>Bourbon, M. de Beaujeu, and Madame Jeanne de France, and Monsieur<br>the Bastard of Bourbon, and I know not whom else; all being<br>illuminated with torches. The rabble were admiring.</p>\n<p>“Happy painter, Jehan Fourbault!” said Gringoire with a deep<br>sigh; and he turned his back upon the bannerets and pennons. A<br>street opened before him; he thought it so dark and deserted that<br>he hoped to there escape from all the rumors as well as from all<br>the gleams of the festival. At the end of a few moments his foot<br>came in contact with an obstacle; he stumbled and fell. It was<br>the May truss, which the clerks of the clerks’ law court had<br>deposited that morning at the door of a president of the<br>parliament, in honor of the solemnity of the day. Gringoire bore<br>this new disaster heroically; he picked himself up, and reached<br>the water’s edge. After leaving behind him the civic Tournelle[7]<br>and the criminal tower, and skirted the great walls of the king’s<br>garden, on that unpaved strand where the mud reached to his<br>ankles, he reached the western point of the city, and considered<br>for some time the islet of the Passeur-aux-Vaches, which has<br>disappeared beneath the bronze horse of the Pont Neuf. The islet<br>appeared to him in the shadow like a black mass, beyond the<br>narrow strip of whitish water which separated him from it. One<br>could divine by the ray of a tiny light the sort of hut in the<br>form of a beehive where the ferryman of cows took refuge at<br>night.</p>\n<p>“Happy ferryman!” thought Gringoire; “you do not dream of glory,<br>and you do not make marriage songs! What matters it to you, if<br>kings and Duchesses of Burgundy marry? You know no other daisies<br>(<em>marguerites</em>) than those which your April greensward gives your<br>cows to browse upon; while I, a poet, am hooted, and shiver, and<br>owe twelve sous, and the soles of my shoes are so transparent,<br>that they might serve as glasses for your lantern! Thanks,<br>ferryman, your cabin rests my eyes, and makes me forget Paris!”</p>\n<p>He was roused from his almost lyric ecstacy, by a big double<br>Saint-Jean cracker, which suddenly went off from the happy cabin.<br>It was the cow ferryman, who was taking his part in the<br>rejoicings of the day, and letting off fireworks.</p>\n<p>This cracker made Gringoire’s skin bristle up all over.</p>\n<p>“Accursed festival!” he exclaimed, “wilt thou pursue me<br>everywhere? Oh! good God! even to the ferryman’s!”</p>\n<p>Then he looked at the Seine at his feet, and a horrible<br>temptation took possession of him:</p>\n<p>“Oh!” said he, “I would gladly drown myself, were the water not<br>so cold!”</p>\n<p>Then a desperate resolution occurred to him. It was, since he<br>could not escape from the Pope of the Fools, from Jehan<br>Fourbault’s bannerets, from May trusses, from squibs and<br>crackers, to go to the Place de Grève.</p>\n<p>“At least,” he said to himself, “I shall there have a firebrand<br>of joy wherewith to warm myself, and I can sup on some crumbs of<br>the three great armorial bearings of royal sugar which have been<br>erected on the public refreshment-stall of the city.”</p>\n<h1 class=\"chapter\" id=\"chapter-ii-the-place-de-gr-ve\">Chapter II. THE PLACE DE GRÈVE.</h1>\n<p>There remains to-day but a very imperceptible vestige of the<br>Place de Grève, such as it existed then; it consists in the<br>charming little turret, which occupies the angle north of the<br>Place, and which, already enshrouded in the ignoble plaster which<br>fills with paste the delicate lines of its sculpture, would soon<br>have disappeared, perhaps submerged by that flood of new houses<br>which so rapidly devours all the ancient façades of Paris.</p>\n<p>The persons who, like ourselves, never cross the Place de Grève<br>without casting a glance of pity and sympathy on that poor turret<br>strangled between two hovels of the time of Louis XV., can easily<br>reconstruct in their minds the aggregate of edifices to which it<br>belonged, and find again entire in it the ancient Gothic place of<br>the fifteenth century.</p>\n<p>It was then, as it is to-day, an irregular trapezoid, bordered on<br>one side by the quay, and on the other three by a series of<br>lofty, narrow, and gloomy houses. By day, one could admire the<br>variety of its edifices, all sculptured in stone or wood, and<br>already presenting complete specimens of the different domestic<br>architectures of the Middle Ages, running back from the fifteenth<br>to the eleventh century, from the casement which had begun to<br>dethrone the arch, to the Roman semicircle, which had been<br>supplanted by the ogive, and which still occupies, below it, the<br>first story of that ancient house de la Tour Roland, at the<br>corner of the Place upon the Seine, on the side of the street<br>with the Tannerie. At night, one could distinguish nothing of all<br>that mass of buildings, except the black indentation of the<br>roofs, unrolling their chain of acute angles round the place; for<br>one of the radical differences between the cities of that time,<br>and the cities of the present day, lay in the façades which<br>looked upon the places and streets, and which were then gables.<br>For the last two centuries the houses have been turned round.</p>\n<p>In the centre of the eastern side of the Place, rose a heavy and<br>hybrid construction, formed of three buildings placed in<br>juxtaposition. It was called by three names which explain its<br>history, its destination, and its architecture: “The House of the<br>Dauphin,” because Charles V., when Dauphin, had inhabited it;<br>“The Marchandise,” because it had served as town hall; and “The<br>Pillared House” (<em>domus ad piloria</em>), because of a series of<br>large pillars which sustained the three stories. The city found<br>there all that is required for a city like Paris; a chapel in<br>which to pray to God; a <em>plaidoyer</em>, or pleading room, in which<br>to hold hearings, and to repel, at need, the King’s people; and<br>under the roof, an <em>arsenac</em> full of artillery. For the<br><em>bourgeois</em> of Paris were aware that it is not sufficient to pray<br>in every conjuncture, and to plead for the franchises of the<br>city, and they had always in reserve, in the garret of the town<br>hall, a few good rusty arquebuses. The Grève had then that<br>sinister aspect which it preserves to-day from the execrable<br>ideas which it awakens, and from the sombre town hall of<br>Dominique Bocador, which has replaced the Pillared House. It must<br>be admitted that a permanent gibbet and a pillory, “a justice and<br>a ladder,” as they were called in that day, erected side by side<br>in the centre of the pavement, contributed not a little to cause<br>eyes to be turned away from that fatal place, where so many<br>beings full of life and health have agonized; where, fifty years<br>later, that fever of Saint Vallier was destined to have its<br>birth, that terror of the scaffold, the most monstrous of all<br>maladies because it comes not from God, but from man.</p>\n<p>It is a consoling idea (let us remark in passing), to think that<br>the death penalty, which three hundred years ago still encumbered<br>with its iron wheels, its stone gibbets, and all its<br>paraphernalia of torture, permanent and riveted to the pavement,<br>the Grève, the Halles, the Place Dauphine, the Cross du Trahoir,<br>the Marché aux Pourceaux, that hideous Montfaucon, the barrier<br>des Sergents, the Place aux Chats, the Porte Saint-Denis,<br>Champeaux, the Porte Baudets, the Porte Saint Jacques, without<br>reckoning the innumerable ladders of the provosts, the bishop of<br>the chapters, of the abbots, of the priors, who had the decree of<br>life and death,—without reckoning the judicial drownings in the<br>river Seine; it is consoling to-day, after having lost<br>successively all the pieces of its armor, its luxury of torment,<br>its penalty of imagination and fancy, its torture for which it<br>reconstructed every five years a leather bed at the Grand<br>Châtelet, that ancient suzerain of feudal society almost expunged<br>from our laws and our cities, hunted from code to code, chased<br>from place to place, has no longer, in our immense Paris, any<br>more than a dishonored corner of the Grève,—than a miserable<br>guillotine, furtive, uneasy, shameful, which seems always afraid<br>of being caught in the act, so quickly does it disappear after<br>having dealt its blow.</p>\n<h1 class=\"chapter\" id=\"chapter-iii-kisses-for-blows\">Chapter III. KISSES FOR BLOWS.</h1>\n<p>When Pierre Gringoire arrived on the Place de Grève, he was<br>paralyzed. He had directed his course across the Pont aux<br>Meuniers, in order to avoid the rabble on the Pont au Change, and<br>the pennons of Jehan Fourbault; but the wheels of all the<br>bishop’s mills had splashed him as he passed, and his doublet was<br>drenched; it seemed to him besides, that the failure of his piece<br>had rendered him still more sensible to cold than usual. Hence he<br>made haste to draw near the bonfire, which was burning<br>magnificently in the middle of the Place. But a considerable<br>crowd formed a circle around it.</p>\n<p>“Accursed Parisians!” he said to himself (for Gringoire, like a<br>true dramatic poet, was subject to monologues) “there they are<br>obstructing my fire! Nevertheless, I am greatly in need of a<br>chimney corner; my shoes drink in the water, and all those cursed<br>mills wept upon me! That devil of a Bishop of Paris, with his<br>mills! I’d just like to know what use a bishop can make of a<br>mill! Does he expect to become a miller instead of a bishop? If<br>only my malediction is needed for that, I bestow it upon him! and<br>his cathedral, and his mills! Just see if those boobies will put<br>themselves out! Move aside! I’d like to know what they are doing<br>there! They are warming themselves, much pleasure may it give<br>them! They are watching a hundred fagots burn; a fine spectacle!”</p>\n<p>On looking more closely, he perceived that the circle was much<br>larger than was required simply for the purpose of getting warm<br>at the king’s fire, and that this concourse of people had not<br>been attracted solely by the beauty of the hundred fagots which<br>were burning.</p>\n<p>In a vast space left free between the crowd and the fire, a young<br>girl was dancing.</p>\n<p>Whether this young girl was a human being, a fairy, or an angel,<br>is what Gringoire, sceptical philosopher and ironical poet that<br>he was, could not decide at the first moment, so fascinated was<br>he by this dazzling vision.</p>\n<p>She was not tall, though she seemed so, so boldly did her slender<br>form dart about. She was swarthy of complexion, but one divined<br>that, by day, her skin must possess that beautiful golden tone of<br>the Andalusians and the Roman women. Her little foot, too, was<br>Andalusian, for it was both pinched and at ease in its graceful<br>shoe. She danced, she turned, she whirled rapidly about on an old<br>Persian rug, spread negligently under her feet; and each time<br>that her radiant face passed before you, as she whirled, her<br>great black eyes darted a flash of lightning at you.</p>\n<p>All around her, all glances were riveted, all mouths open; and,<br>in fact, when she danced thus, to the humming of the Basque<br>tambourine, which her two pure, rounded arms raised above her<br>head, slender, frail and vivacious as a wasp, with her corsage of<br>gold without a fold, her variegated gown puffing out, her bare<br>shoulders, her delicate limbs, which her petticoat revealed at<br>times, her black hair, her eyes of flame, she was a supernatural<br>creature.</p>\n<p>“In truth,” said Gringoire to himself, “she is a salamander, she<br>is a nymph, she is a goddess, she is a bacchante of the Menelean<br>Mount!”</p>\n<p>At that moment, one of the salamander’s braids of hair became<br>unfastened, and a piece of yellow copper which was attached to<br>it, rolled to the ground.</p>\n<p>“Hé, no!” said he, “she is a gypsy!”</p>\n<p>All illusions had disappeared.</p>\n<p>She began her dance once more; she took from the ground two<br>swords, whose points she rested against her brow, and which she<br>made to turn in one direction, while she turned in the other; it<br>was a purely gypsy effect. But, disenchanted though Gringoire<br>was, the whole effect of this picture was not without its charm<br>and its magic; the bonfire illuminated, with a red flaring light,<br>which trembled, all alive, over the circle of faces in the crowd,<br>on the brow of the young girl, and at the background of the Place<br>cast a pallid reflection, on one side upon the ancient, black,<br>and wrinkled façade of the House of Pillars, on the other, upon<br>the old stone gibbet.</p>\n<p>Among the thousands of visages which that light tinged with<br>scarlet, there was one which seemed, even more than all the<br>others, absorbed in contemplation of the dancer. It was the face<br>of a man, austere, calm, and sombre. This man, whose costume was<br>concealed by the crowd which surrounded him, did not appear to be<br>more than five and thirty years of age; nevertheless, he was<br>bald; he had merely a few tufts of thin, gray hair on his<br>temples; his broad, high forehead had begun to be furrowed with<br>wrinkles, but his deep-set eyes sparkled with extraordinary<br>youthfulness, an ardent life, a profound passion. He kept them<br>fixed incessantly on the gypsy, and, while the giddy young girl<br>of sixteen danced and whirled, for the pleasure of all, his<br>revery seemed to become more and more sombre. From time to time,<br>a smile and a sigh met upon his lips, but the smile was more<br>melancholy than the sigh.</p>\n<p>The young girl, stopped at length, breathless, and the people<br>applauded her lovingly.</p>\n<p>“Djali!” said the gypsy.</p>\n<p>Then Gringoire saw come up to her, a pretty little white goat,<br>alert, wide-awake, glossy, with gilded horns, gilded hoofs, and<br>gilded collar, which he had not hitherto perceived, and which had<br>remained lying curled up on one corner of the carpet watching his<br>mistress dance.</p>\n<p>“Djali!” said the dancer, “it is your turn.”</p>\n<p>And, seating herself, she gracefully presented her tambourine to<br>the goat.</p>\n<p>“Djali,” she continued, “what month is this?”</p>\n<p>The goat lifted its fore foot, and struck one blow upon the<br>tambourine. It was the first month in the year, in fact.</p>\n<p>“Djali,” pursued the young girl, turning her tambourine round,<br>“what day of the month is this?”</p>\n<p>Djali raised his little gilt hoof, and struck six blows on the<br>tambourine.</p>\n<p>“Djali,” pursued the Egyptian, with still another movement of the<br>tambourine, “what hour of the day is it?”</p>\n<p>Djali struck seven blows. At that moment, the clock of the Pillar<br>House rang out seven.</p>\n<p>The people were amazed.</p>\n<p>“There’s sorcery at the bottom of it,” said a sinister voice in<br>the crowd. It was that of the bald man, who never removed his<br>eyes from the gypsy.</p>\n<p>She shuddered and turned round; but applause broke forth and<br>drowned the morose exclamation.</p>\n<p>It even effaced it so completely from her mind, that she<br>continued to question her goat.</p>\n<p>“Djali, what does Master Guichard Grand-Remy, captain of the<br>pistoliers of the town do, at the procession of Candlemas?”</p>\n<p>Djali reared himself on his hind legs, and began to bleat,<br>marching along with so much dainty gravity, that the entire<br>circle of spectators burst into a laugh at this parody of the<br>interested devoutness of the captain of pistoliers.</p>\n<p>“Djali,” resumed the young girl, emboldened by her growing<br>success, “how preaches Master Jacques Charmolue, procurator to<br>the king in the ecclesiastical court?”</p>\n<p>The goat seated himself on his hind quarters, and began to bleat,<br>waving his fore feet in so strange a manner, that, with the<br>exception of the bad French, and worse Latin, Jacques Charmolue<br>was there complete,—gesture, accent, and attitude.</p>\n<p>And the crowd applauded louder than ever.</p>\n<p>“Sacrilege! profanation!” resumed the voice of the bald man.</p>\n<p>The gypsy turned round once more.</p>\n<p>“Ah!” said she, “’tis that villanous man!” Then, thrusting her<br>under lip out beyond the upper, she made a little pout, which<br>appeared to be familiar to her, executed a pirouette on her heel,<br>and set about collecting in her tambourine the gifts of the<br>multitude.</p>\n<p>Big blanks, little blanks, targes[8] and eagle liards showered<br>into it.</p>\n<p>All at once, she passed in front of Gringoire. Gringoire put his<br>hand so recklessly into his pocket that she halted. “The devil!”<br>said the poet, finding at the bottom of his pocket the reality,<br>that is, to say, a void. In the meantime, the pretty girl stood<br>there, gazing at him with her big eyes, and holding out her<br>tambourine to him and waiting. Gringoire broke into a violent<br>perspiration.</p>\n<p>If he had all Peru in his pocket, he would certainly have given<br>it to the dancer; but Gringoire had not Peru, and, moreover,<br>America had not yet been discovered.</p>\n<p>Happily, an unexpected incident came to his rescue.</p>\n<p>“Will you take yourself off, you Egyptian grasshopper?” cried a<br>sharp voice, which proceeded from the darkest corner of the<br>Place.</p>\n<p>The young girl turned round in affright. It was no longer the<br>voice of the bald man; it was the voice of a woman, bigoted and<br>malicious.</p>\n<p>However, this cry, which alarmed the gypsy, delighted a troop of<br>children who were prowling about there.</p>\n<p>“It is the recluse of the Tour-Roland,” they exclaimed, with wild<br>laughter, “it is the sacked nun who is scolding! Hasn’t she<br>supped? Let’s carry her the remains of the city refreshments!”</p>\n<p>All rushed towards the Pillar House.</p>\n<p>In the meanwhile, Gringoire had taken advantage of the dancer’s<br>embarrassment, to disappear. The children’s shouts had reminded<br>him that he, also, had not supped, so he ran to the public<br>buffet. But the little rascals had better legs than he; when he<br>arrived, they had stripped the table. There remained not so much<br>as a miserable <em>camichon</em> at five sous the pound. Nothing<br>remained upon the wall but slender fleurs-de-lis, mingled with<br>rose bushes, painted in 1434 by Mathieu Biterne. It was a meagre<br>supper.</p>\n<p>It is an unpleasant thing to go to bed without supper, it is a<br>still less pleasant thing not to sup and not to know where one is<br>to sleep. That was Gringoire’s condition. No supper, no shelter;<br>he saw himself pressed on all sides by necessity, and he found<br>necessity very crabbed. He had long ago discovered the truth,<br>that Jupiter created men during a fit of misanthropy, and that<br>during a wise man’s whole life, his destiny holds his philosophy<br>in a state of siege. As for himself, he had never seen the<br>blockade so complete; he heard his stomach sounding a parley, and<br>he considered it very much out of place that evil destiny should<br>capture his philosophy by famine.</p>\n<p>This melancholy revery was absorbing him more and more, when a<br>song, quaint but full of sweetness, suddenly tore him from it. It<br>was the young gypsy who was singing.</p>\n<p>Her voice was like her dancing, like her beauty. It was<br>indefinable and charming; something pure and sonorous, aerial,<br>winged, so to speak. There were continual outbursts, melodies,<br>unexpected cadences, then simple phrases strewn with aerial and<br>hissing notes; then floods of scales which would have put a<br>nightingale to rout, but in which harmony was always present;<br>then soft modulations of octaves which rose and fell, like the<br>bosom of the young singer. Her beautiful face followed, with<br>singular mobility, all the caprices of her song, from the wildest<br>inspiration to the chastest dignity. One would have pronounced<br>her now a mad creature, now a queen.</p>\n<p>The words which she sang were in a tongue unknown to Gringoire,<br>and which seemed to him to be unknown to herself, so little<br>relation did the expression which she imparted to her song bear<br>to the sense of the words. Thus, these four lines, in her mouth,<br>were madly gay,—</p>\n<p>Un cofre de gran riqueza<br>Hallaron dentro un pilar,<br>Dentro del, nuevas banderas<br>Con figuras de espantar.[9]</p>\n<p>And an instant afterwards, at the accents which she imparted to<br>this stanza,—</p>\n<p>Alarabes de cavallo<br>Sin poderse menear,<br>Con espadas, y los cuellos,<br>Ballestas de buen echar,</p>\n<p>Gringoire felt the tears start to his eyes. Nevertheless, her<br>song breathed joy, most of all, and she seemed to sing like a<br>bird, from serenity and heedlessness.</p>\n<p>The gypsy’s song had disturbed Gringoire’s revery as the swan<br>disturbs the water. He listened in a sort of rapture, and<br>forgetfulness of everything. It was the first moment in the<br>course of many hours when he did not feel that he suffered.</p>\n<p>The moment was brief.</p>\n<p>The same woman’s voice, which had interrupted the gypsy’s dance,<br>interrupted her song.</p>\n<p>“Will you hold your tongue, you cricket of hell?” it cried, still<br>from the same obscure corner of the place.</p>\n<p>The poor “cricket” stopped short. Gringoire covered up his ears.</p>\n<p>“Oh!” he exclaimed, “accursed saw with missing teeth, which comes<br>to break the lyre!”</p>\n<p>Meanwhile, the other spectators murmured like himself; “To the<br>devil with the sacked nun!” said some of them. And the old<br>invisible kill-joy might have had occasion to repent of her<br>aggressions against the gypsy had their attention not been<br>diverted at this moment by the procession of the Pope of the<br>Fools, which, after having traversed many streets and squares,<br>debouched on the Place de Grève, with all its torches and all its<br>uproar.</p>\n<p>This procession, which our readers have seen set out from the<br>Palais de Justice, had organized on the way, and had been<br>recruited by all the knaves, idle thieves, and unemployed<br>vagabonds in Paris; so that it presented a very respectable<br>aspect when it arrived at the Grève.</p>\n<p>First came Egypt. The Duke of Egypt headed it, on horseback, with<br>his counts on foot holding his bridle and stirrups for him;<br>behind them, the male and female Egyptians, pell-mell, with their<br>little children crying on their shoulders; all—duke, counts, and<br>populace—in rags and tatters. Then came the Kingdom of Argot;<br>that is to say, all the thieves of France, arranged according to<br>the order of their dignity; the minor people walking first. Thus<br>defiled by fours, with the divers insignia of their grades, in<br>that strange faculty, most of them lame, some cripples, others<br>one-armed, shop clerks, pilgrims, <em>hubins</em>, bootblacks,<br>thimble-riggers, street arabs, beggars, the blear-eyed beggars,<br>thieves, the weakly, vagabonds, merchants, sham soldiers,<br>goldsmiths, passed masters of pickpockets, isolated thieves. A<br>catalogue that would weary Homer. In the centre of the conclave<br>of the passed masters of pickpockets, one had some difficulty in<br>distinguishing the King of Argot, the grand coësre, so called,<br>crouching in a little cart drawn by two big dogs. After the<br>kingdom of the Argotiers, came the Empire of Galilee. Guillaume<br>Rousseau, Emperor of the Empire of Galilee, marched majestically<br>in his robe of purple, spotted with wine, preceded by buffoons<br>wrestling and executing military dances; surrounded by his<br>macebearers, his pickpockets and clerks of the chamber of<br>accounts. Last of all came the corporation of law clerks, with<br>its maypoles crowned with flowers, its black robes, its music<br>worthy of the orgy, and its large candles of yellow wax. In the<br>centre of this crowd, the grand officers of the Brotherhood of<br>Fools bore on their shoulders a litter more loaded down with<br>candles than the reliquary of Sainte-Geneviève in time of pest;<br>and on this litter shone resplendent, with crosier, cope, and<br>mitre, the new Pope of the Fools, the bellringer of Notre-Dame,<br>Quasimodo the hunchback.</p>\n<p>Each section of this grotesque procession had its own music. The<br>Egyptians made their drums and African tambourines resound. The<br>slang men, not a very musical race, still clung to the goat’s<br>horn trumpet and the Gothic rubebbe of the twelfth century. The<br>Empire of Galilee was not much more advanced; among its music one<br>could hardly distinguish some miserable rebec, from the infancy<br>of the art, still imprisoned in the <em>ré-la-mi</em>. But it was around<br>the Pope of the Fools that all the musical riches of the epoch<br>were displayed in a magnificent discord. It was nothing but<br>soprano rebecs, counter-tenor rebecs, and tenor rebecs, not to<br>reckon the flutes and brass instruments. Alas! our readers will<br>remember that this was Gringoire’s orchestra.</p>\n<p>It is difficult to convey an idea of the degree of proud and<br>blissful expansion to which the sad and hideous visage of<br>Quasimodo had attained during the transit from the Palais de<br>Justice, to the Place de Grève. It was the first enjoyment of<br>self-love that he had ever experienced. Down to that day, he had<br>known only humiliation, disdain for his condition, disgust for<br>his person. Hence, deaf though he was, he enjoyed, like a<br>veritable pope, the acclamations of that throng, which he hated<br>because he felt that he was hated by it. What mattered it that<br>his people consisted of a pack of fools, cripples, thieves, and<br>beggars? it was still a people and he was its sovereign. And he<br>accepted seriously all this ironical applause, all this derisive<br>respect, with which the crowd mingled, it must be admitted, a<br>good deal of very real fear. For the hunchback was robust; for<br>the bandy-legged fellow was agile; for the deaf man was<br>malicious: three qualities which temper ridicule.</p>\n<p>We are far from believing, however, that the new Pope of the<br>Fools understood both the sentiments which he felt and the<br>sentiments which he inspired. The spirit which was lodged in this<br>failure of a body had, necessarily, something incomplete and deaf<br>about it. Thus, what he felt at the moment was to him, absolutely<br>vague, indistinct, and confused. Only joy made itself felt, only<br>pride dominated. Around that sombre and unhappy face, there hung<br>a radiance.</p>\n<p>It was, then, not without surprise and alarm, that at the very<br>moment when Quasimodo was passing the Pillar House, in that<br>semi-intoxicated state, a man was seen to dart from the crowd,<br>and to tear from his hands, with a gesture of anger, his crosier<br>of gilded wood, the emblem of his mock popeship.</p>\n<p>This man, this rash individual, was the man with the bald brow,<br>who, a moment earlier, standing with the gypsy’s group had<br>chilled the poor girl with his words of menace and of hatred. He<br>was dressed in an ecclesiastical costume. At the moment when he<br>stood forth from the crowd, Gringoire, who had not noticed him up<br>to that time, recognized him: “Hold!” he said, with an<br>exclamation of astonishment. “Eh! ’tis my master in Hermes, Dom<br>Claude Frollo, the archdeacon! What the devil does he want of<br>that old one-eyed fellow? He’ll get himself devoured!”</p>\n<p>A cry of terror arose, in fact. The formidable Quasimodo had<br>hurled himself from the litter, and the women turned aside their<br>eyes in order not to see him tear the archdeacon asunder.</p>\n<p>He made one bound as far as the priest, looked at him, and fell<br>upon his knees.</p>\n<p>The priest tore off his tiara, broke his crozier, and rent his<br>tinsel cope.</p>\n<p>Quasimodo remained on his knees, with head bent and hands<br>clasped. Then there was established between them a strange<br>dialogue of signs and gestures, for neither of them spoke. The<br>priest, erect on his feet, irritated, threatening, imperious;<br>Quasimodo, prostrate, humble, suppliant. And, nevertheless, it is<br>certain that Quasimodo could have crushed the priest with his<br>thumb.</p>\n<p>At length the archdeacon, giving Quasimodo’s powerful shoulder a<br>rough shake, made him a sign to rise and follow him.</p>\n<p>Quasimodo rose.</p>\n<p>Then the Brotherhood of Fools, their first stupor having passed<br>off, wished to defend their pope, so abruptly dethroned. The<br>Egyptians, the men of slang, and all the fraternity of law<br>clerks, gathered howling round the priest.</p>\n<p>Quasimodo placed himself in front of the priest, set in play the<br>muscles of his athletic fists, and glared upon the assailants<br>with the snarl of an angry tiger.</p>\n<p>The priest resumed his sombre gravity, made a sign to Quasimodo,<br>and retired in silence.</p>\n<p>Quasimodo walked in front of him, scattering the crowd as he<br>passed.</p>\n<p>When they had traversed the populace and the Place, the cloud of<br>curious and idle were minded to follow them. Quasimodo then<br>constituted himself the rearguard, and followed the archdeacon,<br>walking backwards, squat, surly, monstrous, bristling, gathering<br>up his limbs, licking his boar’s tusks, growling like a wild<br>beast, and imparting to the crowd immense vibrations, with a look<br>or a gesture.</p>\n<p>Both were allowed to plunge into a dark and narrow street, where<br>no one dared to venture after them; so thoroughly did the mere<br>chimera of Quasimodo gnashing his teeth bar the entrance.</p>\n<p>“Here’s a marvellous thing,” said Gringoire; “but where the deuce<br>shall I find some supper?”</p>\n<h1 class=\"chapter\" id=\"chapter-iv-the-inconveniences-of-following-a-pre\">Chapter IV. THE INCONVENIENCES OF FOLLOWING A PRETTY WOMAN</h1>\n<p>THROUGH THE STREETS IN THE EVENING.</p>\n<p>Gringoire set out to follow the gypsy at all hazards. He had seen<br>her, accompanied by her goat, take to the Rue de la Coutellerie;<br>he took the Rue de la Coutellerie.</p>\n<p>“Why not?” he said to himself.</p>\n<p>Gringoire, a practical philosopher of the streets of Paris, had<br>noticed that nothing is more propitious to revery than following<br>a pretty woman without knowing whither she is going. There was in<br>this voluntary abdication of his freewill, in this fancy<br>submitting itself to another fancy, which suspects it not, a<br>mixture of fantastic independence and blind obedience, something<br>indescribable, intermediate between slavery and liberty, which<br>pleased Gringoire,—a spirit essentially compound, undecided, and<br>complex, holding the extremities of all extremes, incessantly<br>suspended between all human propensities, and neutralizing one by<br>the other. He was fond of comparing himself to Mahomet’s coffin,<br>attracted in two different directions by two loadstones, and<br>hesitating eternally between the heights and the depths, between<br>the vault and the pavement, between fall and ascent, between<br>zenith and nadir.</p>\n<p>If Gringoire had lived in our day, what a fine middle course he<br>would hold between classicism and romanticism!</p>\n<p>But he was not sufficiently primitive to live three hundred<br>years, and ’tis a pity. His absence is a void which is but too<br>sensibly felt to-day.</p>\n<p>Moreover, for the purpose of thus following passers-by (and<br>especially female passers-by) in the streets, which Gringoire was<br>fond of doing, there is no better disposition than ignorance of<br>where one is going to sleep.</p>\n<p>So he walked along, very thoughtfully, behind the young girl, who<br>hastened her pace and made her goat trot as she saw the<br><em>bourgeois</em> returning home and the taverns—the only shops which<br>had been open that day—closing.</p>\n<p>“After all,” he half thought to himself, “she must lodge<br>somewhere; gypsies have kindly hearts. Who knows?—”</p>\n<p>And in the points of suspense which he placed after this<br>reticence in his mind, there lay I know not what flattering<br>ideas.</p>\n<p>Meanwhile, from time to time, as he passed the last groups of<br><em>bourgeois</em> closing their doors, he caught some scraps of their<br>conversation, which broke the thread of his pleasant hypotheses.</p>\n<p>Now it was two old men accosting each other.</p>\n<p>“Do you know that it is cold, Master Thibaut Fernicle?”<br>(Gringoire had been aware of this since the beginning of the<br>winter.)</p>\n<p>“Yes, indeed, Master Boniface Disome! Are we going to have a<br>winter such as we had three years ago, in ’80, when wood cost<br>eight sous the measure?”</p>\n<p>“Bah! that’s nothing, Master Thibaut, compared with the winter of<br>1407, when it froze from St. Martin’s Day until Candlemas! and so<br>cold that the pen of the registrar of the parliament froze every<br>three words, in the Grand Chamber! which interrupted the<br>registration of justice.”</p>\n<p>Further on there were two female neighbors at their windows,<br>holding candles, which the fog caused to sputter.</p>\n<p>“Has your husband told you about the mishap, Mademoiselle la<br>Boudraque?”</p>\n<p>“No. What is it, Mademoiselle Turquant?”</p>\n<p>“The horse of M. Gilles Godin, the notary at the Châtelet, took<br>fright at the Flemings and their procession, and overturned<br>Master Philippe Avrillot, lay monk of the Célestins.”</p>\n<p>“Really?”</p>\n<p>“Actually.”</p>\n<p>“A <em>bourgeois</em> horse! ’tis rather too much! If it had been a<br>cavalry horse, well and good!”</p>\n<p>And the windows were closed. But Gringoire had lost the thread of<br>his ideas, nevertheless.</p>\n<p>Fortunately, he speedily found it again, and he knotted it<br>together without difficulty, thanks to the gypsy, thanks to<br>Djali, who still walked in front of him; two fine, delicate, and<br>charming creatures, whose tiny feet, beautiful forms, and<br>graceful manners he was engaged in admiring, almost confusing<br>them in his contemplation; believing them to be both young girls,<br>from their intelligence and good friendship; regarding them both<br>as goats,—so far as the lightness, agility, and dexterity of<br>their walk were concerned.</p>\n<p>But the streets were becoming blacker and more deserted every<br>moment. The curfew had sounded long ago, and it was only at rare<br>intervals now that they encountered a passer-by in the street, or<br>a light in the windows. Gringoire had become involved, in his<br>pursuit of the gypsy, in that inextricable labyrinth of alleys,<br>squares, and closed courts which surround the ancient sepulchre<br>of the Saints-Innocents, and which resembles a ball of thread<br>tangled by a cat. “Here are streets which possess but little<br>logic!” said Gringoire, lost in the thousands of circuits which<br>returned upon themselves incessantly, but where the young girl<br>pursued a road which seemed familiar to her, without hesitation<br>and with a step which became ever more rapid. As for him, he<br>would have been utterly ignorant of his situation had he not<br>espied, in passing, at the turn of a street, the octagonal mass<br>of the pillory of the fish markets, the open-work summit of which<br>threw its black, fretted outlines clearly upon a window which was<br>still lighted in the Rue Verdelet.</p>\n<p>The young girl’s attention had been attracted to him for the last<br>few moments; she had repeatedly turned her head towards him with<br>uneasiness; she had even once come to a standstill, and taking<br>advantage of a ray of light which escaped from a half-open bakery<br>to survey him intently, from head to foot, then, having cast this<br>glance, Gringoire had seen her make that little pout which he had<br>already noticed, after which she passed on.</p>\n<p>This little pout had furnished Gringoire with food for thought.<br>There was certainly both disdain and mockery in that graceful<br>grimace. So he dropped his head, began to count the<br>paving-stones, and to follow the young girl at a little greater<br>distance, when, at the turn of a street, which had caused him to<br>lose sight of her, he heard her utter a piercing cry.</p>\n<p>He hastened his steps.</p>\n<p>The street was full of shadows. Nevertheless, a twist of tow<br>soaked in oil, which burned in a cage at the feet of the Holy<br>Virgin at the street corner, permitted Gringoire to make out the<br>gypsy struggling in the arms of two men, who were endeavoring to<br>stifle her cries. The poor little goat, in great alarm, lowered<br>his horns and bleated.</p>\n<p>“Help! gentlemen of the watch!” shouted Gringoire, and advanced<br>bravely. One of the men who held the young girl turned towards<br>him. It was the formidable visage of Quasimodo.</p>\n<p>Gringoire did not take to flight, but neither did he advance<br>another step.</p>\n<p>Quasimodo came up to him, tossed him four paces away on the<br>pavement with a backward turn of the hand, and plunged rapidly<br>into the gloom, bearing the young girl folded across one arm like<br>a silken scarf. His companion followed him, and the poor goat ran<br>after them all, bleating plaintively.</p>\n<p>“Murder! murder!” shrieked the unhappy gypsy.</p>\n<p>“Halt, rascals, and yield me that wench!” suddenly shouted in a<br>voice of thunder, a cavalier who appeared suddenly from a<br>neighboring square.</p>\n<p>It was a captain of the king’s archers, armed from head to foot,<br>with his sword in his hand.</p>\n<p>He tore the gypsy from the arms of the dazed Quasimodo, threw her<br>across his saddle, and at the moment when the terrible hunchback,<br>recovering from his surprise, rushed upon him to regain his prey,<br>fifteen or sixteen archers, who followed their captain closely,<br>made their appearance, with their two-edged swords in their<br>fists. It was a squad of the king’s police, which was making the<br>rounds, by order of Messire Robert d’Estouteville, guard of the<br>provostship of Paris.</p>\n<p>Quasimodo was surrounded, seized, garroted; he roared, he foamed<br>at the mouth, he bit; and had it been broad daylight, there is no<br>doubt that his face alone, rendered more hideous by wrath, would<br>have put the entire squad to flight. But by night he was deprived<br>of his most formidable weapon, his ugliness.</p>\n<p>His companion had disappeared during the struggle.</p>\n<p>The gypsy gracefully raised herself upright upon the officer’s<br>saddle, placed both hands upon the young man’s shoulders, and<br>gazed fixedly at him for several seconds, as though enchanted<br>with his good looks and with the aid which he had just rendered<br>her. Then breaking silence first, she said to him, making her<br>sweet voice still sweeter than usual,—</p>\n<p>“What is your name, monsieur le gendarme?”</p>\n<p>“Captain Phœbus de Châteaupers, at your service, my beauty!”<br>replied the officer, drawing himself up.</p>\n<p>“Thanks,” said she.</p>\n<p>And while Captain Phœbus was turning up his moustache in<br>Burgundian fashion, she slipped from the horse, like an arrow<br>falling to earth, and fled.</p>\n<p>A flash of lightning would have vanished less quickly.</p>\n<p>“Nombrill of the Pope!” said the captain, causing Quasimodo’s<br>straps to be drawn tighter, “I should have preferred to keep the<br>wench.”</p>\n<p>“What would you have, captain?” said one gendarme. “The warbler<br>has fled, and the bat remains.”</p>\n<h1 class=\"chapter\" id=\"chapter-v-result-of-the-dangers\">Chapter V. RESULT OF THE DANGERS.</h1>\n<p>Gringoire, thoroughly stunned by his fall, remained on the<br>pavement in front of the Holy Virgin at the street corner. Little<br>by little, he regained his senses; at first, for several minutes,<br>he was floating in a sort of half-somnolent revery, which was not<br>without its charm, in which æriel figures of the gypsy and her<br>goat were coupled with Quasimodo’s heavy fist. This state lasted<br>but a short time. A decidedly vivid sensation of cold in the part<br>of his body which was in contact with the pavement, suddenly<br>aroused him and caused his spirit to return to the surface.</p>\n<p>“Whence comes this chill?” he said abruptly, to himself. He then<br>perceived that he was lying half in the middle of the gutter.</p>\n<p>“That devil of a hunchbacked cyclops!” he muttered between his<br>teeth; and he tried to rise. But he was too much dazed and<br>bruised; he was forced to remain where he was. Moreover, his hand<br>was tolerably free; he stopped up his nose and resigned himself.</p>\n<p>“The mud of Paris,” he said to himself—for decidedly he thought<br>that he was sure that the gutter would prove his refuge for the<br>night; and what can one do in a refuge, except dream?—“the mud of<br>Paris is particularly stinking; it must contain a great deal of<br>volatile and nitric salts. That, moreover, is the opinion of<br>Master Nicholas Flamel, and of the alchemists—”</p>\n<p>The word <em>alchemists</em> suddenly suggested to his mind the idea of<br>Archdeacon Claude Frollo. He recalled the violent scene which he<br>had just witnessed in part; that the gypsy was struggling with<br>two men, that Quasimodo had a companion; and the morose and<br>haughty face of the archdeacon passed confusedly through his<br>memory. “That would be strange!” he said to himself. And on that<br>fact and that basis he began to construct a fantastic edifice of<br>hypothesis, that card-castle of philosophers; then, suddenly<br>returning once more to reality, “Come! I’m freezing!” he<br>ejaculated.</p>\n<p>The place was, in fact, becoming less and less tenable. Each<br>molecule of the gutter bore away a molecule of heat radiating<br>from Gringoire’s loins, and the equilibrium between the<br>temperature of his body and the temperature of the brook, began<br>to be established in rough fashion.</p>\n<p>Quite a different annoyance suddenly assailed him. A group of<br>children, those little bare-footed savages who have always roamed<br>the pavements of Paris under the eternal name of <em>gamins</em>, and<br>who, when we were also children ourselves, threw stones at all of<br>us in the afternoon, when we came out of school, because our<br>trousers were not torn—a swarm of these young scamps rushed<br>towards the square where Gringoire lay, with shouts and laughter<br>which seemed to pay but little heed to the sleep of the<br>neighbors. They were dragging after them some sort of hideous<br>sack; and the noise of their wooden shoes alone would have roused<br>the dead. Gringoire who was not quite dead yet, half raised<br>himself.</p>\n<p>“Ohé, Hennequin Dandèche! Ohé, Jehan Pincebourde!” they shouted<br>in deafening tones, “old Eustache Moubon, the merchant at the<br>corner, has just died. We’ve got his straw pallet, we’re going to<br>have a bonfire out of it. It’s the turn of the Flemish to-day!”</p>\n<p>And behold, they flung the pallet directly upon Gringoire, beside<br>whom they had arrived, without espying him. At the same time, one<br>of them took a handful of straw and set off to light it at the<br>wick of the good Virgin.</p>\n<p>“S’death!” growled Gringoire, “am I going to be too warm now?”</p>\n<p>It was a critical moment. He was caught between fire and water;<br>he made a superhuman effort, the effort of a counterfeiter of<br>money who is on the point of being boiled, and who seeks to<br>escape. He rose to his feet, flung aside the straw pallet upon<br>the street urchins, and fled.</p>\n<p>“Holy Virgin!” shrieked the children; “’tis the merchant’s<br>ghost!”</p>\n<p>And they fled in their turn.</p>\n<p>The straw mattress remained master of the field. Belleforêt,<br>Father Le Juge, and Corrozet affirm that it was picked up on the<br>morrow, with great pomp, by the clergy of the quarter, and borne<br>to the treasury of the church of Saint Opportune, where the<br>sacristan, even as late as 1789, earned a tolerably handsome<br>revenue out of the great miracle of the Statue of the Virgin at<br>the corner of the Rue Mauconseil, which had, by its mere<br>presence, on the memorable night between the sixth and seventh of<br>January, 1482, exorcised the defunct Eustache Moubon, who, in<br>order to play a trick on the devil, had at his death maliciously<br>concealed his soul in his straw pallet.</p>\n<h1 class=\"chapter\" id=\"chapter-vi-the-broken-jug\">Chapter VI. THE BROKEN JUG.</h1>\n<p>After having run for some time at the top of his speed, without<br>knowing whither, knocking his head against many a street corner,<br>leaping many a gutter, traversing many an alley, many a court,<br>many a square, seeking flight and passage through all the<br>meanderings of the ancient passages of the Halles, exploring in<br>his panic terror what the fine Latin of the maps calls _tota via,<br>cheminum et viaria_, our poet suddenly halted for lack of breath<br>in the first place, and in the second, because he had been<br>collared, after a fashion, by a dilemma which had just occurred<br>to his mind. “It strikes me, Master Pierre Gringoire,” he said to<br>himself, placing his finger to his brow, “that you are running<br>like a madman. The little scamps are no less afraid of you than<br>you are of them. It strikes me, I say, that you heard the clatter<br>of their wooden shoes fleeing southward, while you were fleeing<br>northward. Now, one of two things, either they have taken flight,<br>and the pallet, which they must have forgotten in their terror,<br>is precisely that hospitable bed in search of which you have been<br>running ever since morning, and which madame the Virgin<br>miraculously sends you, in order to recompense you for having<br>made a morality in her honor, accompanied by triumphs and<br>mummeries; or the children have not taken flight, and in that<br>case they have put the brand to the pallet, and that is precisely<br>the good fire which you need to cheer, dry, and warm you. In<br>either case, good fire or good bed, that straw pallet is a gift<br>from heaven. The blessed Virgin Marie who stands at the corner of<br>the Rue Mauconseil, could only have made Eustache Moubon die for<br>that express purpose; and it is folly on your part to flee thus<br>zigzag, like a Picard before a Frenchman, leaving behind you what<br>you seek before you; and you are a fool!”</p>\n<p>Then he retraced his steps, and feeling his way and searching,<br>with his nose to the wind and his ears on the alert, he tried to<br>find the blessed pallet again, but in vain. There was nothing to<br>be found but intersections of houses, closed courts, and<br>crossings of streets, in the midst of which he hesitated and<br>doubted incessantly, being more perplexed and entangled in this<br>medley of streets than he would have been even in the labyrinth<br>of the Hôtel des Tournelles. At length he lost patience, and<br>exclaimed solemnly: “Cursed be cross roads! ’tis the devil who<br>has made them in the shape of his pitchfork!”</p>\n<p>This exclamation afforded him a little solace, and a sort of<br>reddish reflection which he caught sight of at that moment, at<br>the extremity of a long and narrow lane, completed the elevation<br>of his moral tone. “God be praised!” said he, “There it is<br>yonder! There is my pallet burning.” And comparing himself to the<br>pilot who suffers shipwreck by night, “<em>Salve</em>,” he added<br>piously, “<em>salve, maris stella</em>!”</p>\n<p>Did he address this fragment of litany to the Holy Virgin, or to<br>the pallet? We are utterly unable to say.</p>\n<p>He had taken but a few steps in the long street, which sloped<br>downwards, was unpaved, and more and more muddy and steep, when<br>he noticed a very singular thing. It was not deserted; here and<br>there along its extent crawled certain vague and formless masses,<br>all directing their course towards the light which flickered at<br>the end of the street, like those heavy insects which drag along<br>by night, from blade to blade of grass, towards the shepherd’s<br>fire.</p>\n<p>Nothing renders one so adventurous as not being able to feel the<br>place where one’s pocket is situated. Gringoire continued to<br>advance, and had soon joined that one of the forms which dragged<br>along most indolently, behind the others. On drawing near, he<br>perceived that it was nothing else than a wretched legless<br>cripple in a bowl, who was hopping along on his two hands like a<br>wounded field-spider which has but two legs left. At the moment<br>when he passed close to this species of spider with a human<br>countenance, it raised towards him a lamentable voice: “_La buona<br>mancia, signor! la buona mancia_!”[10]</p>\n<p>“Deuce take you,” said Gringoire, “and me with you, if I know<br>what you mean!”</p>\n<p>And he passed on.</p>\n<p>He overtook another of these itinerant masses, and examined it.<br>It was an impotent man, both halt and crippled, and halt and<br>crippled to such a degree that the complicated system of crutches<br>and wooden legs which sustained him, gave him the air of a<br>mason’s scaffolding on the march. Gringoire, who liked noble and<br>classical comparisons, compared him in thought to the living<br>tripod of Vulcan.</p>\n<p>This living tripod saluted him as he passed, but stopping his hat<br>on a level with Gringoire’s chin, like a shaving dish, while he<br>shouted in the latter’s ears: “_Señor cabellero, para comprar un<br>pedaso de pan_!”[11]</p>\n<p>“It appears,” said Gringoire, “that this one can also talk; but<br>’tis a rude language, and he is more fortunate than I if he<br>understands it.” Then, smiting his brow, in a sudden transition<br>of ideas: “By the way, what the deuce did they mean this morning<br>with their <em>Esmeralda?</em>”</p>\n<p>He was minded to augment his pace, but for the third time<br>something barred his way. This something or, rather, some one was<br>a blind man, a little blind fellow with a bearded, Jewish face,<br>who, rowing away in the space about him with a stick, and towed<br>by a large dog, droned through his nose with a Hungarian accent:<br>“<em>Facitote caritatem</em>!”</p>\n<p>“Well, now,” said Gringoire, “here’s one at last who speaks a<br>Christian tongue. I must have a very charitable aspect, since<br>they ask alms of me in the present lean condition of my purse. My<br>friend,” and he turned towards the blind man, “I sold my last<br>shirt last week; that is to say, since you understand only the<br>language of Cicero: _Vendidi hebdomade nuper transita meam<br>ultimam chemisam_.”</p>\n<p>That said, he turned his back upon the blind man, and pursued his<br>way. But the blind man began to increase his stride at the same<br>time; and, behold! the cripple and the legless man, in his bowl,<br>came up on their side in great haste, and with great clamor of<br>bowl and crutches, upon the pavement. Then all three, jostling<br>each other at poor Gringoire’s heels, began to sing their song to<br>him,—</p>\n<p>“<em>Caritatem</em>!” chanted the blind man.</p>\n<p>“<em>La buona mancia</em>!” chanted the cripple in the bowl.</p>\n<p>And the lame man took up the musical phrase by repeating: “_Un<br>pedaso de pan_!”</p>\n<p>Gringoire stopped up his ears. “Oh, tower of Babel!” he<br>exclaimed.</p>\n<p>He set out to run. The blind man ran! The lame man ran! The<br>cripple in the bowl ran!</p>\n<p>And then, in proportion as he plunged deeper into the street,<br>cripples in bowls, blind men and lame men, swarmed about him, and<br>men with one arm, and with one eye, and the leprous with their<br>sores, some emerging from little streets adjacent, some from the<br>air-holes of cellars, howling, bellowing, yelping, all limping<br>and halting, all flinging themselves towards the light, and<br>humped up in the mire, like snails after a shower.</p>\n<p>Gringoire, still followed by his three persecutors, and not<br>knowing very well what was to become of him, marched along in<br>terror among them, turning out for the lame, stepping over the<br>cripples in bowls, with his feet imbedded in that ant-hill of<br>lame men, like the English captain who got caught in the<br>quicksand of a swarm of crabs.</p>\n<p>The idea occurred to him of making an effort to retrace his<br>steps. But it was too late. This whole legion had closed in<br>behind him, and his three beggars held him fast. So he proceeded,<br>impelled both by this irresistible flood, by fear, and by a<br>vertigo which converted all this into a sort of horrible dream.</p>\n<p>At last he reached the end of the street. It opened upon an<br>immense place, where a thousand scattered lights flickered in the<br>confused mists of night. Gringoire flew thither, hoping to<br>escape, by the swiftness of his legs, from the three infirm<br>spectres who had clutched him.</p>\n<p>“<em>Onde vas, hombre</em>?” (Where are you going, my man?) cried the<br>cripple, flinging away his crutches, and running after him with<br>the best legs that ever traced a geometrical step upon the<br>pavements of Paris.</p>\n<p>In the meantime the legless man, erect upon his feet, crowned<br>Gringoire with his heavy iron bowl, and the blind man glared in<br>his face with flaming eyes!</p>\n<p>“Where am I?” said the terrified poet.</p>\n<p>“In the Court of Miracles,” replied a fourth spectre, who had<br>accosted them.</p>\n<p>“Upon my soul,” resumed Gringoire, “I certainly do behold the<br>blind who see, and the lame who walk, but where is the Saviour?”</p>\n<p>They replied by a burst of sinister laughter.</p>\n<p>The poor poet cast his eyes about him. It was, in truth, that<br>redoubtable Cour des Miracles, whither an honest man had never<br>penetrated at such an hour; the magic circle where the officers<br>of the Châtelet and the sergeants of the provostship, who<br>ventured thither, disappeared in morsels; a city of thieves, a<br>hideous wart on the face of Paris; a sewer, from which escaped<br>every morning, and whither returned every night to crouch, that<br>stream of vices, of mendicancy and vagabondage which always<br>overflows in the streets of capitals; a monstrous hive, to which<br>returned at nightfall, with their booty, all the drones of the<br>social order; a lying hospital where the bohemian, the disfrocked<br>monk, the ruined scholar, the ne’er-do-wells of all nations,<br>Spaniards, Italians, Germans,—of all religions, Jews, Christians,<br>Mahometans, idolaters, covered with painted sores, beggars by<br>day, were transformed by night into brigands; an immense<br>dressing-room, in a word, where, at that epoch, the actors of<br>that eternal comedy, which theft, prostitution, and murder play<br>upon the pavements of Paris, dressed and undressed.</p>\n<p>It was a vast place, irregular and badly paved, like all the<br>squares of Paris at that date. Fires, around which swarmed<br>strange groups, blazed here and there. Every one was going,<br>coming, and shouting. Shrill laughter was to be heard, the<br>wailing of children, the voices of women. The hands and heads of<br>this throng, black against the luminous background, outlined<br>against it a thousand eccentric gestures. At times, upon the<br>ground, where trembled the light of the fires, mingled with<br>large, indefinite shadows, one could behold a dog passing, which<br>resembled a man, a man who resembled a dog. The limits of races<br>and species seemed effaced in this city, as in a pandemonium.<br>Men, women, beasts, age, sex, health, maladies, all seemed to be<br>in common among these people; all went together, they mingled,<br>confounded, superposed; each one there participated in all.</p>\n<p>The poor and flickering flames of the fire permitted Gringoire to<br>distinguish, amid his trouble, all around the immense place, a<br>hideous frame of ancient houses, whose wormeaten, shrivelled,<br>stunted façades, each pierced with one or two lighted attic<br>windows, seemed to him, in the darkness, like enormous heads of<br>old women, ranged in a circle, monstrous and crabbed, winking as<br>they looked on at the Witches’ Sabbath.</p>\n<p>It was like a new world, unknown, unheard of, misshapen,<br>creeping, swarming, fantastic.</p>\n<p>Gringoire, more and more terrified, clutched by the three beggars<br>as by three pairs of tongs, dazed by a throng of other faces<br>which frothed and yelped around him, unhappy Gringoire endeavored<br>to summon his presence of mind, in order to recall whether it was<br>a Saturday. But his efforts were vain; the thread of his memory<br>and of his thought was broken; and, doubting everything, wavering<br>between what he saw and what he felt, he put to himself this<br>unanswerable question,—</p>\n<p>“If I exist, does this exist? if this exists, do I exist?”</p>\n<p>At that moment, a distinct cry arose in the buzzing throng which<br>surrounded him, “Let’s take him to the king! let’s take him to<br>the king!”</p>\n<p>“Holy Virgin!” murmured Gringoire, “the king here must be a ram.”</p>\n<p>“To the king! to the king!” repeated all voices.</p>\n<p>They dragged him off. Each vied with the other in laying his<br>claws upon him. But the three beggars did not loose their hold<br>and tore him from the rest, howling, “He belongs to us!”</p>\n<p>The poet’s already sickly doublet yielded its last sigh in this<br>struggle.</p>\n<p>While traversing the horrible place, his vertigo vanished. After<br>taking a few steps, the sentiment of reality returned to him. He<br>began to become accustomed to the atmosphere of the place. At the<br>first moment there had arisen from his poet’s head, or, simply<br>and prosaically, from his empty stomach, a mist, a vapor, so to<br>speak, which, spreading between objects and himself, permitted<br>him to catch a glimpse of them only in the incoherent fog of<br>nightmare,—in those shadows of dreams which distort every<br>outline, agglomerating objects into unwieldy groups, dilating<br>things into chimeras, and men into phantoms. Little by little,<br>this hallucination was succeeded by a less bewildered and<br>exaggerating view. Reality made its way to the light around him,<br>struck his eyes, struck his feet, and demolished, bit by bit, all<br>that frightful poetry with which he had, at first, believed<br>himself to be surrounded. He was forced to perceive that he was<br>not walking in the Styx, but in mud, that he was elbowed not by<br>demons, but by thieves; that it was not his soul which was in<br>question, but his life (since he lacked that precious<br>conciliator, which places itself so effectually between the<br>bandit and the honest man—a purse). In short, on examining the<br>orgy more closely, and with more coolness, he fell from the<br>witches’ sabbath to the dram-shop.</p>\n<p>The Cour des Miracles was, in fact, merely a dram-shop; but a<br>brigand’s dram-shop, reddened quite as much with blood as with<br>wine.</p>\n<p>The spectacle which presented itself to his eyes, when his ragged<br>escort finally deposited him at the end of his trip, was not<br>fitted to bear him back to poetry, even to the poetry of hell. It<br>was more than ever the prosaic and brutal reality of the tavern.<br>Were we not in the fifteenth century, we would say that Gringoire<br>had descended from Michael Angelo to Callot.</p>\n<p>Around a great fire which burned on a large, circular flagstone,<br>the flames of which had heated red-hot the legs of a tripod,<br>which was empty for the moment, some wormeaten tables were<br>placed, here and there, haphazard, no lackey of a geometrical<br>turn having deigned to adjust their parallelism, or to see to it<br>that they did not make too unusual angles. Upon these tables<br>gleamed several dripping pots of wine and beer, and round these<br>pots were grouped many bacchic visages, purple with the fire and<br>the wine. There was a man with a huge belly and a jovial face,<br>noisily kissing a woman of the town, thickset and brawny. There<br>was a sort of sham soldier, a “naquois,” as the slang expression<br>runs, who was whistling as he undid the bandages from his<br>fictitious wound, and removing the numbness from his sound and<br>vigorous knee, which had been swathed since morning in a thousand<br>ligatures. On the other hand, there was a wretched fellow,<br>preparing with celandine and beef’s blood, his “leg of God,” for<br>the next day. Two tables further on, a palmer, with his pilgrim’s<br>costume complete, was practising the lament of the Holy Queen,<br>not forgetting the drone and the nasal drawl. Further on, a young<br>scamp was taking a lesson in epilepsy from an old pretender, who<br>was instructing him in the art of foaming at the mouth, by<br>chewing a morsel of soap. Beside him, a man with the dropsy was<br>getting rid of his swelling, and making four or five female<br>thieves, who were disputing at the same table, over a child who<br>had been stolen that evening, hold their noses. All circumstances<br>which, two centuries later, “seemed so ridiculous to the court,”<br>as Sauval says, “that they served as a pastime to the king, and<br>as an introduction to the royal ballet of Night, divided into<br>four parts and danced on the theatre of the Petit-Bourbon.”<br>“Never,” adds an eye witness of 1653, “have the sudden<br>metamorphoses of the Court of Miracles been more happily<br>presented. Benserade prepared us for it by some very gallant<br>verses.”</p>\n<p>Loud laughter everywhere, and obscene songs. Each one held his<br>own course, carping and swearing, without listening to his<br>neighbor. Pots clinked, and quarrels sprang up at the shock of<br>the pots, and the broken pots made rents in the rags.</p>\n<p>A big dog, seated on his tail, gazed at the fire. Some children<br>were mingled in this orgy. The stolen child wept and cried.<br>Another, a big boy four years of age, seated with legs dangling,<br>upon a bench that was too high for him, before a table that<br>reached to his chin, and uttering not a word. A third, gravely<br>spreading out upon the table with his finger, the melted tallow<br>which dripped from a candle. Last of all, a little fellow<br>crouching in the mud, almost lost in a cauldron, which he was<br>scraping with a tile, and from which he was evoking a sound that<br>would have made Stradivarius swoon.</p>\n<p>Near the fire was a hogshead, and on the hogshead a beggar. This<br>was the king on his throne.</p>\n<p>The three who had Gringoire in their clutches led him in front of<br>this hogshead, and the entire bacchanal rout fell silent for a<br>moment, with the exception of the cauldron inhabited by the<br>child.</p>\n<p>Gringoire dared neither breathe nor raise his eyes.</p>\n<p>“<em>Hombre, quita tu sombrero</em>!” said one of the three knaves, in<br>whose grasp he was, and, before he had comprehended the meaning,<br>the other had snatched his hat—a wretched headgear, it is true,<br>but still good on a sunny day or when there was but little rain.<br>Gringoire sighed.</p>\n<p>Meanwhile the king addressed him, from the summit of his cask,—</p>\n<p>“Who is this rogue?”</p>\n<p>Gringoire shuddered. That voice, although accentuated by menace,<br>recalled to him another voice, which, that very morning, had<br>dealt the deathblow to his mystery, by drawling, nasally, in the<br>midst of the audience, “Charity, please!” He raised his head. It<br>was indeed Clopin Trouillefou.</p>\n<p>Clopin Trouillefou, arrayed in his royal insignia, wore neither<br>one rag more nor one rag less. The sore upon his arm had already<br>disappeared. He held in his hand one of those whips made of<br>thongs of white leather, which police sergeants then used to<br>repress the crowd, and which were called <em>boullayes</em>. On his head<br>he wore a sort of headgear, bound round and closed at the top.<br>But it was difficult to make out whether it was a child’s cap or<br>a king’s crown, the two things bore so strong a resemblance to<br>each other.</p>\n<p>Meanwhile Gringoire, without knowing why, had regained some hope,<br>on recognizing in the King of the Cour des Miracles his accursed<br>mendicant of the Grand Hall.</p>\n<p>“Master,” stammered he; “monseigneur—sire—how ought I to address<br>you?” he said at length, having reached the culminating point of<br>his crescendo, and knowing neither how to mount higher, nor to<br>descend again.</p>\n<p>“Monseigneur, his majesty, or comrade, call me what you please.<br>But make haste. What have you to say in your own defence?”</p>\n<p>“<em>In your own defence?</em>” thought Gringoire, “that displeases me.”<br>He resumed, stuttering, “I am he, who this morning—”</p>\n<p>“By the devil’s claws!” interrupted Clopin, “your name, knave,<br>and nothing more. Listen. You are in the presence of three<br>powerful sovereigns: myself, Clopin Trouillefou, King of Thunes,<br>successor to the Grand Coësre, supreme suzerain of the Realm of<br>Argot; Mathias Hunyadi Spicali, Duke of Egypt and of Bohemia, the<br>old yellow fellow whom you see yonder, with a dish clout round<br>his head; Guillaume Rousseau, Emperor of Galilee, that fat fellow<br>who is not listening to us but caressing a wench. We are your<br>judges. You have entered the Kingdom of Argot, without being an<br><em>argotier</em>; you have violated the privileges of our city. You<br>must be punished unless you are a <em>capon</em>, a <em>franc-mitou</em> or a<br><em>rifodé</em>; that is to say, in the slang of honest folks,—a thief,<br>a beggar, or a vagabond. Are you anything of that sort? Justify<br>yourself; announce your titles.”</p>\n<p>“Alas!” said Gringoire, “I have not that honor. I am the author—”</p>\n<p>“That is sufficient,” resumed Trouillefou, without permitting him<br>to finish. “You are going to be hanged. ’Tis a very simple<br>matter, gentlemen and honest <em>bourgeois</em>! as you treat our people<br>in your abode, so we treat you in ours! The law which you apply<br>to vagabonds, vagabonds apply to you. ’Tis your fault if it is<br>harsh. One really must behold the grimace of an honest man above<br>the hempen collar now and then; that renders the thing honorable.<br>Come, friend, divide your rags gayly among these damsels. I am<br>going to have you hanged to amuse the vagabonds, and you are to<br>give them your purse to drink your health. If you have any<br>mummery to go through with, there’s a very good God the Father in<br>that mortar yonder, in stone, which we stole from Saint-Pierre<br>aux Bœufs. You have four minutes in which to fling your soul at<br>his head.”</p>\n<p>The harangue was formidable.</p>\n<p>“Well said, upon my soul! Clopin Trouillefou preaches like the<br>Holy Father the Pope!” exclaimed the Emperor of Galilee, smashing<br>his pot in order to prop up his table.</p>\n<p>“Messeigneurs, emperors, and kings,” said Gringoire coolly (for I<br>know not how, firmness had returned to him, and he spoke with<br>resolution), “don’t think of such a thing; my name is Pierre<br>Gringoire. I am the poet whose morality was presented this<br>morning in the grand hall of the Courts.”</p>\n<p>“Ah! so it was you, master!” said Clopin. “I was there, _par la<br>tête Dieu_! Well! comrade, is that any reason, because you bored<br>us to death this morning, that you should not be hung this<br>evening?”</p>\n<p>“I shall find difficulty in getting out of it,” said Gringoire to<br>himself. Nevertheless, he made one more effort: “I don’t see why<br>poets are not classed with vagabonds,” said he. “Vagabond, Æsopus<br>certainly was; Homerus was a beggar; Mercurius was a thief—”</p>\n<p>Clopin interrupted him: “I believe that you are trying to blarney<br>us with your jargon. Zounds! let yourself be hung, and don’t kick<br>up such a row over it!”</p>\n<p>“Pardon me, monseigneur, the King of Thunes,” replied Gringoire,<br>disputing the ground foot by foot. “It is worth trouble—One<br>moment!—Listen to me—You are not going to condemn me without<br>having heard me”—</p>\n<p>His unlucky voice was, in fact, drowned in the uproar which rose<br>around him. The little boy scraped away at his cauldron with more<br>spirit than ever; and, to crown all, an old woman had just placed<br>on the tripod a frying-pan of grease, which hissed away on the<br>fire with a noise similar to the cry of a troop of children in<br>pursuit of a masker.</p>\n<p>In the meantime, Clopin Trouillefou appeared to hold a momentary<br>conference with the Duke of Egypt, and the Emperor of Galilee,<br>who was completely drunk. Then he shouted shrilly: “Silence!”<br>and, as the cauldron and the frying-pan did not heed him, and<br>continued their duet, he jumped down from his hogshead, gave a<br>kick to the boiler, which rolled ten paces away bearing the child<br>with it, a kick to the frying-pan, which upset in the fire with<br>all its grease, and gravely remounted his throne, without<br>troubling himself about the stifled tears of the child, or the<br>grumbling of the old woman, whose supper was wasting away in a<br>fine white flame.</p>\n<p>Trouillefou made a sign, and the duke, the emperor, and the<br>passed masters of pickpockets, and the isolated robbers, came and<br>ranged themselves around him in a horseshoe, of which Gringoire,<br>still roughly held by the body, formed the centre. It was a<br>semicircle of rags, tatters, tinsel, pitchforks, axes, legs<br>staggering with intoxication, huge, bare arms, faces sordid,<br>dull, and stupid. In the midst of this Round Table of beggary,<br>Clopin Trouillefou,—as the doge of this senate, as the king of<br>this peerage, as the pope of this conclave,—dominated; first by<br>virtue of the height of his hogshead, and next by virtue of an<br>indescribable, haughty, fierce, and formidable air, which caused<br>his eyes to flash, and corrected in his savage profile the<br>bestial type of the race of vagabonds. One would have pronounced<br>him a boar amid a herd of swine.</p>\n<p>“Listen,” said he to Gringoire, fondling his misshapen chin with<br>his horny hand; “I don’t see why you should not be hung. It is<br>true that it appears to be repugnant to you; and it is very<br>natural, for you <em>bourgeois</em> are not accustomed to it. You form<br>for yourselves a great idea of the thing. After all, we don’t<br>wish you any harm. Here is a means of extricating yourself from<br>your predicament for the moment. Will you become one of us?”</p>\n<p>The reader can judge of the effect which this proposition<br>produced upon Gringoire, who beheld life slipping away from him,<br>and who was beginning to lose his hold upon it. He clutched at it<br>again with energy.</p>\n<p>“Certainly I will, and right heartily,” said he.</p>\n<p>“Do you consent,” resumed Clopin, “to enroll yourself among the<br>people of the knife?”</p>\n<p>“Of the knife, precisely,” responded Gringoire.</p>\n<p>“You recognize yourself as a member of the free<br><em>bourgeoisie?</em>”[12] added the King of Thunes.</p>\n<p>“Of the free <em>bourgeoisie</em>.”</p>\n<p>“Subject of the Kingdom of Argot?”</p>\n<p>“Of the Kingdom of Argot[13].”</p>\n<p>“A vagabond?”</p>\n<p>“A vagabond.”</p>\n<p>“In your soul?”</p>\n<p>“In my soul.”</p>\n<p>“I must call your attention to the fact,” continued the king,<br>“that you will be hung all the same.”</p>\n<p>“The devil!” said the poet.</p>\n<p>“Only,” continued Clopin imperturbably, “you will be hung later<br>on, with more ceremony, at the expense of the good city of Paris,<br>on a handsome stone gibbet, and by honest men. That is a<br>consolation.”</p>\n<p>“Just so,” responded Gringoire.</p>\n<p>“There are other advantages. In your quality of a high-toned<br>sharper, you will not have to pay the taxes on mud, or the poor,<br>or lanterns, to which the <em>bourgeois</em> of Paris are subject.”</p>\n<p>“So be it,” said the poet. “I agree. I am a vagabond, a thief, a<br>sharper, a man of the knife, anything you please; and I am all<br>that already, monsieur, King of Thunes, for I am a philosopher;<br><em>et omnia in philosophia, omnes in philosopho continentur</em>,—all<br>things are contained in philosophy, all men in the philosopher,<br>as you know.”</p>\n<p>The King of Thunes scowled.</p>\n<p>“What do you take me for, my friend? What Hungarian Jew patter<br>are you jabbering at us? I don’t know Hebrew. One isn’t a Jew<br>because one is a bandit. I don’t even steal any longer. I’m above<br>that; I kill. Cut-throat, yes; cutpurse, no.”</p>\n<p>Gringoire tried to slip in some excuse between these curt words,<br>which wrath rendered more and more jerky.</p>\n<p>“I ask your pardon, monseigneur. It is not Hebrew; ’tis Latin.”</p>\n<p>“I tell you,” resumed Clopin angrily, “that I’m not a Jew, and<br>that I’ll have you hung, belly of the synagogue, like that little<br>shopkeeper of Judea, who is by your side, and whom I entertain<br>strong hopes of seeing nailed to a counter one of these days,<br>like the counterfeit coin that he is!”</p>\n<p>So saying, he pointed his finger at the little, bearded Hungarian<br>Jew who had accosted Gringoire with his <em>facitote caritatem</em>, and<br>who, understanding no other language beheld with surprise the<br>King of Thunes’s ill-humor overflow upon him.</p>\n<p>At length Monsieur Clopin calmed down.</p>\n<p>“So you will be a vagabond, you knave?” he said to our poet.</p>\n<p>“Of course,” replied the poet.</p>\n<p>“Willing is not all,” said the surly Clopin; “good will doesn’t<br>put one onion the more into the soup, and ’tis good for nothing<br>except to go to Paradise with; now, Paradise and the thieves’<br>band are two different things. In order to be received among the<br>thieves,[14] you must prove that you are good for something, and<br>for that purpose, you must search the manikin.”</p>\n<p>“I’ll search anything you like,” said Gringoire.</p>\n<p>Clopin made a sign. Several thieves detached themselves from the<br>circle, and returned a moment later. They brought two thick<br>posts, terminated at their lower extremities in spreading timber<br>supports, which made them stand readily upon the ground; to the<br>upper extremity of the two posts they fitted a cross-beam, and<br>the whole constituted a very pretty portable gibbet, which<br>Gringoire had the satisfaction of beholding rise before him, in a<br>twinkling. Nothing was lacking, not even the rope, which swung<br>gracefully over the cross-beam.</p>\n<p>“What are they going to do?” Gringoire asked himself with some<br>uneasiness. A sound of bells, which he heard at that moment, put<br>an end to his anxiety; it was a stuffed manikin, which the<br>vagabonds were suspending by the neck from the rope, a sort of<br>scarecrow dressed in red, and so hung with mule-bells and larger<br>bells, that one might have tricked out thirty Castilian mules<br>with them. These thousand tiny bells quivered for some time with<br>the vibration of the rope, then gradually died away, and finally<br>became silent when the manikin had been brought into a state of<br>immobility by that law of the pendulum which has dethroned the<br>water clock and the hour-glass. Then Clopin, pointing out to<br>Gringoire a rickety old stool placed beneath the manikin,—“Climb<br>up there.”</p>\n<p>“Death of the devil!” objected Gringoire; “I shall break my neck.<br>Your stool limps like one of Martial’s distiches; it has one<br>hexameter leg and one pentameter leg.”</p>\n<p>“Climb!” repeated Clopin.</p>\n<p>Gringoire mounted the stool, and succeeded, not without some<br>oscillations of head and arms, in regaining his centre of<br>gravity.</p>\n<p>“Now,” went on the King of Thunes, “twist your right foot round<br>your left leg, and rise on the tip of your left foot.”</p>\n<p>“Monseigneur,” said Gringoire, “so you absolutely insist on my<br>breaking some one of my limbs?”</p>\n<p>Clopin tossed his head.</p>\n<p>“Hark ye, my friend, you talk too much. Here’s the gist of the<br>matter in two words: you are to rise on tiptoe, as I tell you; in<br>that way you will be able to reach the pocket of the manikin, you<br>will rummage it, you will pull out the purse that is there,—and<br>if you do all this without our hearing the sound of a bell, all<br>is well: you shall be a vagabond. All we shall then have to do,<br>will be to thrash you soundly for the space of a week.”</p>\n<p>“<em>Ventre-Dieu</em>! I will be careful,” said Gringoire. “And suppose<br>I do make the bells sound?”</p>\n<p>“Then you will be hanged. Do you understand?”</p>\n<p>“I don’t understand at all,” replied Gringoire.</p>\n<p>“Listen, once more. You are to search the manikin, and take away<br>its purse; if a single bell stirs during the operation, you will<br>be hung. Do you understand that?”</p>\n<p>“Good,” said Gringoire; “I understand that. And then?”</p>\n<p>“If you succeed in removing the purse without our hearing the<br>bells, you are a vagabond, and you will be thrashed for eight<br>consecutive days. You understand now, no doubt?”</p>\n<p>“No, monseigneur; I no longer understand. Where is the advantage<br>to me? hanged in one case, cudgelled in the other?”</p>\n<p>“And a vagabond,” resumed Clopin, “and a vagabond; is that<br>nothing? It is for your interest that we should beat you, in<br>order to harden you to blows.”</p>\n<p>“Many thanks,” replied the poet.</p>\n<p>“Come, make haste,” said the king, stamping upon his cask, which<br>resounded like a huge drum! “Search the manikin, and let there be<br>an end to this! I warn you for the last time, that if I hear a<br>single bell, you will take the place of the manikin.”</p>\n<p>The band of thieves applauded Clopin’s words, and arranged<br>themselves in a circle round the gibbet, with a laugh so pitiless<br>that Gringoire perceived that he amused them too much not to have<br>everything to fear from them. No hope was left for him,<br>accordingly, unless it were the slight chance of succeeding in<br>the formidable operation which was imposed upon him; he decided<br>to risk it, but it was not without first having addressed a<br>fervent prayer to the manikin he was about to plunder, and who<br>would have been easier to move to pity than the vagabonds. These<br>myriad bells, with their little copper tongues, seemed to him<br>like the mouths of so many asps, open and ready to sting and to<br>hiss.</p>\n<p>“Oh!” he said, in a very low voice, “is it possible that my life<br>depends on the slightest vibration of the least of these bells?<br>Oh!” he added, with clasped hands, “bells, do not ring,<br>hand-bells do not clang, mule-bells do not quiver!”</p>\n<p>He made one more attempt upon Trouillefou.</p>\n<p>“And if there should come a gust of wind?”</p>\n<p>“You will be hanged,” replied the other, without hesitation.</p>\n<p>Perceiving that no respite, nor reprieve, nor subterfuge was<br>possible, he bravely decided upon his course of action; he wound<br>his right foot round his left leg, raised himself on his left<br>foot, and stretched out his arm: but at the moment when his hand<br>touched the manikin, his body, which was now supported upon one<br>leg only, wavered on the stool which had but three; he made an<br>involuntary effort to support himself by the manikin, lost his<br>balance, and fell heavily to the ground, deafened by the fatal<br>vibration of the thousand bells of the manikin, which, yielding<br>to the impulse imparted by his hand, described first a rotary<br>motion, and then swayed majestically between the two posts.</p>\n<p>“Malediction!” he cried as he fell, and remained as though dead,<br>with his face to the earth.</p>\n<p>Meanwhile, he heard the dreadful peal above his head, the<br>diabolical laughter of the vagabonds, and the voice of<br>Trouillefou saying,—</p>\n<p>“Pick me up that knave, and hang him without ceremony.” He rose.<br>They had already detached the manikin to make room for him.</p>\n<p>The thieves made him mount the stool, Clopin came to him, passed<br>the rope about his neck, and, tapping him on the shoulder,—</p>\n<p>“Adieu, my friend. You can’t escape now, even if you digested<br>with the pope’s guts.”</p>\n<p>The word “Mercy!” died away upon Gringoire’s lips. He cast his<br>eyes about him; but there was no hope: all were laughing.</p>\n<p>“Bellevigne de l’Étoile,” said the King of Thunes to an enormous<br>vagabond, who stepped out from the ranks, “climb upon the cross<br>beam.”</p>\n<p>Bellevigne de l’Étoile nimbly mounted the transverse beam, and in<br>another minute, Gringoire, on raising his eyes, beheld him, with<br>terror, seated upon the beam above his head.</p>\n<p>“Now,” resumed Clopin Trouillefou, “as soon as I clap my hands,<br>you, Andry the Red, will fling the stool to the ground with a<br>blow of your knee; you, François Chanteprune, will cling to the<br>feet of the rascal; and you, Bellevigne, will fling yourself on<br>his shoulders; and all three at once, do you hear?”</p>\n<p>Gringoire shuddered.</p>\n<p>“Are you ready?” said Clopin Trouillefou to the three thieves,<br>who held themselves in readiness to fall upon Gringoire. A moment<br>of horrible suspense ensued for the poor victim, during which<br>Clopin tranquilly thrust into the fire with the tip of his foot,<br>some bits of vine shoots which the flame had not caught. “Are you<br>ready?” he repeated, and opened his hands to clap. One second<br>more and all would have been over.</p>\n<p>But he paused, as though struck by a sudden thought.</p>\n<p>“One moment!” said he; “I forgot! It is our custom not to hang a<br>man without inquiring whether there is any woman who wants him.<br>Comrade, this is your last resource. You must wed either a female<br>vagabond or the noose.”</p>\n<p>This law of the vagabonds, singular as it may strike the reader,<br>remains to-day written out at length, in ancient English<br>legislation. (See <em>Burington’s Observations</em>.)</p>\n<p>Gringoire breathed again. This was the second time that he had<br>returned to life within an hour. So he did not dare to trust to<br>it too implicitly.</p>\n<p>“Holà!” cried Clopin, mounted once more upon his cask, “holà!<br>women, females, is there among you, from the sorceress to her<br>cat, a wench who wants this rascal? Holà, Colette la Charonne!<br>Elisabeth Trouvain! Simone Jodouyne! Marie Piédebou! Thonne la<br>Longue! Bérarde Fanouel! Michelle Genaille! Claude Ronge-oreille!<br>Mathurine Girorou!—Holà! Isabeau-la-Thierrye! Come and see! A man<br>for nothing! Who wants him?”</p>\n<p>Gringoire, no doubt, was not very appetizing in this miserable<br>condition. The female vagabonds did not seem to be much affected<br>by the proposition. The unhappy wretch heard them answer: “No!<br>no! hang him; there’ll be the more fun for us all!”</p>\n<p>Nevertheless, three emerged from the throng and came to smell of<br>him. The first was a big wench, with a square face. She examined<br>the philosopher’s deplorable doublet attentively. His garment was<br>worn, and more full of holes than a stove for roasting chestnuts.<br>The girl made a wry face. “Old rag!” she muttered, and addressing<br>Gringoire, “Let’s see your cloak!” “I have lost it,” replied<br>Gringoire. “Your hat?” “They took it away from me.” “Your shoes?”<br>“They have hardly any soles left.” “Your purse?” “Alas!”<br>stammered Gringoire, “I have not even a sou.” “Let them hang you,<br>then, and say ‘Thank you!’” retorted the vagabond wench, turning<br>her back on him.</p>\n<p>The second,—old, black, wrinkled, hideous, with an ugliness<br>conspicuous even in the Cour des Miracles, trotted round<br>Gringoire. He almost trembled lest she should want him. But she<br>mumbled between her teeth, “He’s too thin,” and went off.</p>\n<p>The third was a young girl, quite fresh, and not too ugly. “Save<br>me!” said the poor fellow to her, in a low tone. She gazed at him<br>for a moment with an air of pity, then dropped her eyes, made a<br>plait in her petticoat, and remained in indecision. He followed<br>all these movements with his eyes; it was the last gleam of hope.<br>“No,” said the young girl, at length, “no! Guillaume Longuejoue<br>would beat me.” She retreated into the crowd.</p>\n<p>“You are unlucky, comrade,” said Clopin.</p>\n<p>Then rising to his feet, upon his hogshead. “No one wants him,”<br>he exclaimed, imitating the accent of an auctioneer, to the great<br>delight of all; “no one wants him? once, twice, three times!”<br>and, turning towards the gibbet with a sign of his hand, “Gone!”</p>\n<p>Bellevigne de l’Étoile, Andry the Red, François Chanteprune,<br>stepped up to Gringoire.</p>\n<p>At that moment a cry arose among the thieves: “_La Esmeralda! La<br>Esmeralda!_”</p>\n<p>Gringoire shuddered, and turned towards the side whence the<br>clamor proceeded.</p>\n<p>The crowd opened, and gave passage to a pure and dazzling form.</p>\n<p>It was the gypsy.</p>\n<p>“La Esmeralda!” said Gringoire, stupefied in the midst of his<br>emotions, by the abrupt manner in which that magic word knotted<br>together all his reminiscences of the day.</p>\n<p>This rare creature seemed, even in the Cour des Miracles, to<br>exercise her sway of charm and beauty. The vagabonds, male and<br>female, ranged themselves gently along her path, and their brutal<br>faces beamed beneath her glance.</p>\n<p>She approached the victim with her light step. Her pretty Djali<br>followed her. Gringoire was more dead than alive. She examined<br>him for a moment in silence.</p>\n<p>“You are going to hang this man?” she said gravely, to Clopin.</p>\n<p>“Yes, sister,” replied the King of Thunes, “unless you will take<br>him for your husband.”</p>\n<p>She made her pretty little pout with her under lip. “I’ll take<br>him,” said she.</p>\n<p>Gringoire firmly believed that he had been in a dream ever since<br>morning, and that this was the continuation of it.</p>\n<p>The change was, in fact, violent, though a gratifying one. They<br>undid the noose, and made the poet step down from the stool. His<br>emotion was so lively that he was obliged to sit down.</p>\n<p>The Duke of Egypt brought an earthenware crock, without uttering<br>a word. The gypsy offered it to Gringoire: “Fling it on the<br>ground,” said she.</p>\n<p>The crock broke into four pieces.</p>\n<p>“Brother,” then said the Duke of Egypt, laying his hands upon<br>their foreheads, “she is your wife; sister, he is your husband<br>for four years. Go.”</p>\n<h1 class=\"chapter\" id=\"chapter-vii-a-bridal-night\">Chapter VII. A BRIDAL NIGHT.</h1>\n<p>A few moments later our poet found himself in a tiny arched<br>chamber, very cosy, very warm, seated at a table which appeared<br>to ask nothing better than to make some loans from a larder<br>hanging near by, having a good bed in prospect, and alone with a<br>pretty girl. The adventure smacked of enchantment. He began<br>seriously to take himself for a personage in a fairy tale; he<br>cast his eyes about him from time to time to time, as though to<br>see if the chariot of fire, harnessed to two-winged chimeras,<br>which alone could have so rapidly transported him from Tartarus<br>to Paradise, were still there. At times, also, he fixed his eyes<br>obstinately upon the holes in his doublet, in order to cling to<br>reality, and not lose the ground from under his feet completely.<br>His reason, tossed about in imaginary space, now hung only by<br>this thread.</p>\n<p>The young girl did not appear to pay any attention to him; she<br>went and came, displaced a stool, talked to her goat, and<br>indulged in a pout now and then. At last she came and seated<br>herself near the table, and Gringoire was able to scrutinize her<br>at his ease.</p>\n<p>You have been a child, reader, and you would, perhaps, be very<br>happy to be one still. It is quite certain that you have not,<br>more than once (and for my part, I have passed whole days, the<br>best employed of my life, at it) followed from thicket to<br>thicket, by the side of running water, on a sunny day, a<br>beautiful green or blue dragon-fly, breaking its flight in abrupt<br>angles, and kissing the tips of all the branches. You recollect<br>with what amorous curiosity your thought and your gaze were<br>riveted upon this little whirlwind, hissing and humming with<br>wings of purple and azure, in the midst of which floated an<br>imperceptible body, veiled by the very rapidity of its movement.<br>The aerial being which was dimly outlined amid this quivering of<br>wings, appeared to you chimerical, imaginary, impossible to<br>touch, impossible to see. But when, at length, the dragon-fly<br>alighted on the tip of a reed, and, holding your breath the<br>while, you were able to examine the long, gauze wings, the long<br>enamel robe, the two globes of crystal, what astonishment you<br>felt, and what fear lest you should again behold the form<br>disappear into a shade, and the creature into a chimera! Recall<br>these impressions, and you will readily appreciate what Gringoire<br>felt on contemplating, beneath her visible and palpable form,<br>that Esmeralda of whom, up to that time, he had only caught a<br>glimpse, amidst a whirlwind of dance, song, and tumult.</p>\n<p>Sinking deeper and deeper into his revery: “So this,” he said to<br>himself, following her vaguely with his eyes, “is <em>la Esmeralda!</em><br>a celestial creature! a street dancer! so much, and so little!<br>’Twas she who dealt the death-blow to my mystery this morning,<br>’tis she who saves my life this evening! My evil genius! My good<br>angel! A pretty woman, on my word! and who must needs love me<br>madly to have taken me in that fashion. By the way,” said he,<br>rising suddenly, with that sentiment of the true which formed the<br>foundation of his character and his philosophy, “I don’t know<br>very well how it happens, but I am her husband!”</p>\n<p>With this idea in his head and in his eyes, he stepped up to the<br>young girl in a manner so military and so gallant that she drew<br>back.</p>\n<p>“What do you want of me?” said she.</p>\n<p>“Can you ask me, adorable Esmeralda?” replied Gringoire, with so<br>passionate an accent that he was himself astonished at it on<br>hearing himself speak.</p>\n<p>The gypsy opened her great eyes. “I don’t know what you mean.”</p>\n<p>“What!” resumed Gringoire, growing warmer and warmer, and<br>supposing that, after all, he had to deal merely with a virtue of<br>the Cour des Miracles; “am I not thine, sweet friend, art thou<br>not mine?”</p>\n<p>And, quite ingenuously, he clasped her waist.</p>\n<p>The gypsy’s corsage slipped through his hands like the skin of an<br>eel. She bounded from one end of the tiny room to the other,<br>stooped down, and raised herself again, with a little poniard in<br>her hand, before Gringoire had even had time to see whence the<br>poniard came; proud and angry, with swelling lips and inflated<br>nostrils, her cheeks as red as an api apple,[15] and her eyes<br>darting lightnings. At the same time, the white goat placed<br>itself in front of her, and presented to Gringoire a hostile<br>front, bristling with two pretty horns, gilded and very sharp.<br>All this took place in the twinkling of an eye.</p>\n<p>The dragon-fly had turned into a wasp, and asked nothing better<br>than to sting.</p>\n<p>Our philosopher was speechless, and turned his astonished eyes<br>from the goat to the young girl. “Holy Virgin!” he said at last,<br>when surprise permitted him to speak, “here are two hearty<br>dames!”</p>\n<p>The gypsy broke the silence on her side.</p>\n<p>“You must be a very bold knave!”</p>\n<p>“Pardon, mademoiselle,” said Gringoire, with a smile. “But why<br>did you take me for your husband?”</p>\n<p>“Should I have allowed you to be hanged?”</p>\n<p>“So,” said the poet, somewhat disappointed in his amorous hopes.<br>“You had no other idea in marrying me than to save me from the<br>gibbet?”</p>\n<p>“And what other idea did you suppose that I had?”</p>\n<p>Gringoire bit his lips. “Come,” said he, “I am not yet so<br>triumphant in Cupido, as I thought. But then, what was the good<br>of breaking that poor jug?”</p>\n<p>Meanwhile Esmeralda’s dagger and the goat’s horns were still upon<br>the defensive.</p>\n<p>“Mademoiselle Esmeralda,” said the poet, “let us come to terms. I<br>am not a clerk of the court, and I shall not go to law with you<br>for thus carrying a dagger in Paris, in the teeth of the<br>ordinances and prohibitions of M. the Provost. Nevertheless, you<br>are not ignorant of the fact that Noël Lescrivain was condemned,<br>a week ago, to pay ten Parisian sous, for having carried a<br>cutlass. But this is no affair of mine, and I will come to the<br>point. I swear to you, upon my share of Paradise, not to approach<br>you without your leave and permission, but do give me some<br>supper.”</p>\n<p>The truth is, Gringoire was, like M. Despreaux, “not very<br>voluptuous.” He did not belong to that chevalier and musketeer<br>species, who take young girls by assault. In the matter of love,<br>as in all other affairs, he willingly assented to temporizing and<br>adjusting terms; and a good supper, and an amiable tête-à-tête<br>appeared to him, especially when he was hungry, an excellent<br>interlude between the prologue and the catastrophe of a love<br>adventure.</p>\n<p>The gypsy did not reply. She made her disdainful little grimace,<br>drew up her head like a bird, then burst out laughing, and the<br>tiny poniard disappeared as it had come, without Gringoire being<br>able to see where the wasp concealed its sting.</p>\n<p>A moment later, there stood upon the table a loaf of rye bread, a<br>slice of bacon, some wrinkled apples and a jug of beer. Gringoire<br>began to eat eagerly. One would have said, to hear the furious<br>clashing of his iron fork and his earthenware plate, that all his<br>love had turned to appetite.</p>\n<p>The young girl seated opposite him, watched him in silence,<br>visibly preoccupied with another thought, at which she smiled<br>from time to time, while her soft hand caressed the intelligent<br>head of the goat, gently pressed between her knees.</p>\n<p>A candle of yellow wax illuminated this scene of voracity and<br>revery.</p>\n<p>Meanwhile, the first cravings of his stomach having been stilled,<br>Gringoire felt some false shame at perceiving that nothing<br>remained but one apple.</p>\n<p>“You do not eat, Mademoiselle Esmeralda?”</p>\n<p>She replied by a negative sign of the head, and her pensive<br>glance fixed itself upon the vault of the ceiling.</p>\n<p>“What the deuce is she thinking of?” thought Gringoire, staring<br>at what she was gazing at; “’tis impossible that it can be that<br>stone dwarf carved in the keystone of that arch, which thus<br>absorbs her attention. What the deuce! I can bear the<br>comparison!”</p>\n<p>He raised his voice, “Mademoiselle!”</p>\n<p>She seemed not to hear him.</p>\n<p>He repeated, still more loudly, “Mademoiselle Esmeralda!”</p>\n<p>Trouble wasted. The young girl’s mind was elsewhere, and<br>Gringoire’s voice had not the power to recall it. Fortunately,<br>the goat interfered. She began to pull her mistress gently by the<br>sleeve.</p>\n<p>“What dost thou want, Djali?” said the gypsy, hastily, as though<br>suddenly awakened.</p>\n<p>“She is hungry,” said Gringoire, charmed to enter into<br>conversation. Esmeralda began to crumble some bread, which Djali<br>ate gracefully from the hollow of her hand.</p>\n<p>Moreover, Gringoire did not give her time to resume her revery.<br>He hazarded a delicate question.</p>\n<p>“So you don’t want me for your husband?”</p>\n<p>The young girl looked at him intently, and said, “No.”</p>\n<p>“For your lover?” went on Gringoire.</p>\n<p>She pouted, and replied, “No.”</p>\n<p>“For your friend?” pursued Gringoire.</p>\n<p>She gazed fixedly at him again, and said, after a momentary<br>reflection, “Perhaps.”</p>\n<p>This “perhaps,” so dear to philosophers, emboldened Gringoire.</p>\n<p>“Do you know what friendship is?” he asked.</p>\n<p>“Yes,” replied the gypsy; “it is to be brother and sister; two<br>souls which touch without mingling, two fingers on one hand.”</p>\n<p>“And love?” pursued Gringoire.</p>\n<p>“Oh! love!” said she, and her voice trembled, and her eye beamed.<br>“That is to be two and to be but one. A man and a woman mingled<br>into one angel. It is heaven.”</p>\n<p>The street dancer had a beauty as she spoke thus, that struck<br>Gringoire singularly, and seemed to him in perfect keeping with<br>the almost oriental exaltation of her words. Her pure, red lips<br>half smiled; her serene and candid brow became troubled, at<br>intervals, under her thoughts, like a mirror under the breath;<br>and from beneath her long, drooping, black eyelashes, there<br>escaped a sort of ineffable light, which gave to her profile that<br>ideal serenity which Raphael found at the mystic point of<br>intersection of virginity, maternity, and divinity.</p>\n<p>Nevertheless, Gringoire continued,—</p>\n<p>“What must one be then, in order to please you?”</p>\n<p>“A man.”</p>\n<p>“And I—” said he, “what, then, am I?”</p>\n<p>“A man has a helmet on his head, a sword in his hand, and golden<br>spurs on his heels.”</p>\n<p>“Good,” said Gringoire, “without a horse, no man. Do you love any<br>one?”</p>\n<p>“As a lover?—”</p>\n<p>“Yes.”</p>\n<p>She remained thoughtful for a moment, then said with a peculiar<br>expression: “That I shall know soon.”</p>\n<p>“Why not this evening?” resumed the poet tenderly. “Why not me?”</p>\n<p>She cast a grave glance upon him and said,—</p>\n<p>“I can never love a man who cannot protect me.”</p>\n<p>Gringoire colored, and took the hint. It was evident that the<br>young girl was alluding to the slight assistance which he had<br>rendered her in the critical situation in which she had found<br>herself two hours previously. This memory, effaced by his own<br>adventures of the evening, now recurred to him. He smote his<br>brow.</p>\n<p>“By the way, mademoiselle, I ought to have begun there. Pardon my<br>foolish absence of mind. How did you contrive to escape from the<br>claws of Quasimodo?”</p>\n<p>This question made the gypsy shudder.</p>\n<p>“Oh! the horrible hunchback,” said she, hiding her face in her<br>hands. And she shuddered as though with violent cold.</p>\n<p>“Horrible, in truth,” said Gringoire, who clung to his idea; “but<br>how did you manage to escape him?”</p>\n<p>La Esmeralda smiled, sighed, and remained silent.</p>\n<p>“Do you know why he followed you?” began Gringoire again, seeking<br>to return to his question by a circuitous route.</p>\n<p>“I don’t know,” said the young girl, and she added hastily, “but<br>you were following me also, why were you following me?”</p>\n<p>“In good faith,” responded Gringoire, “I don’t know either.”</p>\n<p>Silence ensued. Gringoire slashed the table with his knife. The<br>young girl smiled and seemed to be gazing through the wall at<br>something. All at once she began to sing in a barely articulate<br>voice,—</p>\n<p>Quando las pintadas aves,<br>Mudas estan, y la tierra—[16]</p>\n<p>She broke off abruptly, and began to caress Djali.</p>\n<p>“That’s a pretty animal of yours,” said Gringoire.</p>\n<p>“She is my sister,” she answered.</p>\n<p>“Why are you called <em>la Esmeralda?</em>” asked the poet.</p>\n<p>“I do not know.”</p>\n<p>“But why?”</p>\n<p>She drew from her bosom a sort of little oblong bag, suspended<br>from her neck by a string of adrézarach beads. This bag exhaled a<br>strong odor of camphor. It was covered with green silk, and bore<br>in its centre a large piece of green glass, in imitation of an<br>emerald.</p>\n<p>“Perhaps it is because of this,” said she.</p>\n<p>Gringoire was on the point of taking the bag in his hand. She<br>drew back.</p>\n<p>“Don’t touch it! It is an amulet. You would injure the charm or<br>the charm would injure you.”</p>\n<p>The poet’s curiosity was more and more aroused.</p>\n<p>“Who gave it to you?”</p>\n<p>She laid one finger on her mouth and concealed the amulet in her<br>bosom. He tried a few more questions, but she hardly replied.</p>\n<p>“What is the meaning of the words, <em>la Esmeralda?</em>”</p>\n<p>“I don’t know,” said she.</p>\n<p>“To what language do they belong?”</p>\n<p>“They are Egyptian, I think.”</p>\n<p>“I suspected as much,” said Gringoire, “you are not a native of<br>France?”</p>\n<p>“I don’t know.”</p>\n<p>“Are your parents alive?”</p>\n<p>She began to sing, to an ancient air,—</p>\n<p>Mon père est oiseau,<br>Ma mère est oiselle.<br>Je passe l’eau sans nacelle,<br>Je passe l’eau sans bateau,<br>Ma mère est oiselle,<br>Mon père est oiseau.[17]</p>\n<p>“Good,” said Gringoire. “At what age did you come to France?”</p>\n<p>“When I was very young.”</p>\n<p>“And when to Paris?”</p>\n<p>“Last year. At the moment when we were entering the papal gate I<br>saw a reed warbler flit through the air, that was at the end of<br>August; I said, it will be a hard winter.”</p>\n<p>“So it was,” said Gringoire, delighted at this beginning of a<br>conversation. “I passed it in blowing my fingers. So you have the<br>gift of prophecy?”</p>\n<p>She retired into her laconics again.</p>\n<p>“Is that man whom you call the Duke of Egypt, the chief of your<br>tribe?”</p>\n<p>“Yes.”</p>\n<p>“But it was he who married us,” remarked the poet timidly.</p>\n<p>She made her customary pretty grimace.</p>\n<p>“I don’t even know your name.”</p>\n<p>“My name? If you want it, here it is,—Pierre Gringoire.”</p>\n<p>“I know a prettier one,” said she.</p>\n<p>“Naughty girl!” retorted the poet. “Never mind, you shall not<br>provoke me. Wait, perhaps you will love me more when you know me<br>better; and then, you have told me your story with so much<br>confidence, that I owe you a little of mine. You must know, then,<br>that my name is Pierre Gringoire, and that I am a son of the<br>farmer of the notary’s office of Gonesse. My father was hung by<br>the Burgundians, and my mother disembowelled by the Picards, at<br>the siege of Paris, twenty years ago. At six years of age,<br>therefore, I was an orphan, without a sole to my foot except the<br>pavements of Paris. I do not know how I passed the interval from<br>six to sixteen. A fruit dealer gave me a plum here, a baker flung<br>me a crust there; in the evening I got myself taken up by the<br>watch, who threw me into prison, and there I found a bundle of<br>straw. All this did not prevent my growing up and growing thin,<br>as you see. In the winter I warmed myself in the sun, under the<br>porch of the Hôtel de Sens, and I thought it very ridiculous that<br>the fire on Saint John’s Day was reserved for the dog days. At<br>sixteen, I wished to choose a calling. I tried all in succession.<br>I became a soldier; but I was not brave enough. I became a monk;<br>but I was not sufficiently devout; and then I’m a bad hand at<br>drinking. In despair, I became an apprentice of the woodcutters,<br>but I was not strong enough; I had more of an inclination to<br>become a schoolmaster; ’tis true that I did not know how to read,<br>but that’s no reason. I perceived at the end of a certain time,<br>that I lacked something in every direction; and seeing that I was<br>good for nothing, of my own free will I became a poet and<br>rhymester. That is a trade which one can always adopt when one is<br>a vagabond, and it’s better than stealing, as some young brigands<br>of my acquaintance advised me to do. One day I met by luck, Dom<br>Claude Frollo, the reverend archdeacon of Notre-Dame. He took an<br>interest in me, and it is to him that I to-day owe it that I am a<br>veritable man of letters, who knows Latin from the <em>de Officiis</em><br>of Cicero to the mortuology of the Celestine Fathers, and a<br>barbarian neither in scholastics, nor in politics, nor in<br>rhythmics, that sophism of sophisms. I am the author of the<br>Mystery which was presented to-day with great triumph and a great<br>concourse of populace, in the grand hall of the Palais de<br>Justice. I have also made a book which will contain six hundred<br>pages, on the wonderful comet of 1465, which sent one man mad. I<br>have enjoyed still other successes. Being somewhat of an<br>artillery carpenter, I lent a hand to Jean Mangue’s great<br>bombard, which burst, as you know, on the day when it was tested,<br>on the Pont de Charenton, and killed four and twenty curious<br>spectators. You see that I am not a bad match in marriage. I know<br>a great many sorts of very engaging tricks, which I will teach<br>your goat; for example, to mimic the Bishop of Paris, that cursed<br>Pharisee whose mill wheels splash passers-by the whole length of<br>the Pont aux Meuniers. And then my mystery will bring me in a<br>great deal of coined money, if they will only pay me. And<br>finally, I am at your orders, I and my wits, and my science and<br>my letters, ready to live with you, damsel, as it shall please<br>you, chastely or joyously; husband and wife, if you see fit;<br>brother and sister, if you think that better.”</p>\n<p>Gringoire ceased, awaiting the effect of his harangue on the<br>young girl. Her eyes were fixed on the ground.</p>\n<p>“<em>Phœbus,</em>” she said in a low voice. Then, turning towards the<br>poet, “<em>Phœbus</em>,—what does that mean?”</p>\n<p>Gringoire, without exactly understanding what the connection<br>could be between his address and this question, was not sorry to<br>display his erudition. Assuming an air of importance, he<br>replied,—</p>\n<p>“It is a Latin word which means <em>sun.</em>”</p>\n<p>“Sun!” she repeated.</p>\n<p>“It is the name of a handsome archer, who was a god,” added<br>Gringoire.</p>\n<p>“A god!” repeated the gypsy, and there was something pensive and<br>passionate in her tone.</p>\n<p>At that moment, one of her bracelets became unfastened and fell.<br>Gringoire stooped quickly to pick it up; when he straightened up,<br>the young girl and the goat had disappeared. He heard the sound<br>of a bolt. It was a little door, communicating, no doubt, with a<br>neighboring cell, which was being fastened on the outside.</p>\n<p>“Has she left me a bed, at least?” said our philosopher.</p>\n<p>He made the tour of his cell. There was no piece of furniture<br>adapted to sleeping purposes, except a tolerably long wooden<br>coffer; and its cover was carved, to boot; which afforded<br>Gringoire, when he stretched himself out upon it, a sensation<br>somewhat similar to that which Micromégas would feel if he were<br>to lie down on the Alps.</p>\n<p>“Come!” said he, adjusting himself as well as possible, “I must<br>resign myself. But here’s a strange nuptial night. ’Tis a pity.<br>There was something innocent and antediluvian about that broken<br>crock, which quite pleased me.”</p>\n<p>BOOK THIRD.</p>\n<h1 class=\"chapter\" id=\"chapter-i-notre-dame\">Chapter I. NOTRE-DAME.</h1>\n<p>The church of Notre-Dame de Paris is still no doubt, a majestic<br>and sublime edifice. But, beautiful as it has been preserved in<br>growing old, it is difficult not to sigh, not to wax indignant,<br>before the numberless degradations and mutilations which time and<br>men have both caused the venerable monument to suffer, without<br>respect for Charlemagne, who laid its first stone, or for Philip<br>Augustus, who laid the last.</p>\n<p>On the face of this aged queen of our cathedrals, by the side of<br>a wrinkle, one always finds a scar. _Tempus edax, homo<br>edacior_[18]; which I should be glad to translate thus: time is<br>blind, man is stupid.</p>\n<p>If we had leisure to examine with the reader, one by one, the<br>diverse traces of destruction imprinted upon the old church,<br>time’s share would be the least, the share of men the most,<br>especially <em>the men of art</em>, since there have been individuals<br>who assumed the title of architects during the last two<br>centuries.</p>\n<p>And, in the first place, to cite only a few leading examples,<br>there certainly are few finer architectural pages than this<br>façade, where, successively and at once, the three portals<br>hollowed out in an arch; the broidered and dentated cordon of the<br>eight and twenty royal niches; the immense central rose window,<br>flanked by its two lateral windows, like a priest by his deacon<br>and subdeacon; the frail and lofty gallery of trefoil arcades,<br>which supports a heavy platform above its fine, slender columns;<br>and lastly, the two black and massive towers with their slate<br>penthouses, harmonious parts of a magnificent whole, superposed<br>in five gigantic stories;—develop themselves before the eye, in a<br>mass and without confusion, with their innumerable details of<br>statuary, carving, and sculpture, joined powerfully to the<br>tranquil grandeur of the whole; a vast symphony in stone, so to<br>speak; the colossal work of one man and one people, all together<br>one and complex, like the Iliads and the Romanceros, whose sister<br>it is; prodigious product of the grouping together of all the<br>forces of an epoch, where, upon each stone, one sees the fancy of<br>the workman disciplined by the genius of the artist start forth<br>in a hundred fashions; a sort of human creation, in a word,<br>powerful and fecund as the divine creation of which it seems to<br>have stolen the double character,—variety, eternity.</p>\n<p>And what we here say of the façade must be said of the entire<br>church; and what we say of the cathedral church of Paris, must be<br>said of all the churches of Christendom in the Middle Ages. All<br>things are in place in that art, self-created, logical, and well<br>proportioned. To measure the great toe of the foot is to measure<br>the giant.</p>\n<p>Let us return to the façade of Notre-Dame, as it still appears to<br>us, when we go piously to admire the grave and puissant<br>cathedral, which inspires terror, so its chronicles assert: _quæ<br>mole sua terrorem incutit spectantibus_.</p>\n<p>Three important things are to-day lacking in that façade: in the<br>first place, the staircase of eleven steps which formerly raised<br>it above the soil; next, the lower series of statues which<br>occupied the niches of the three portals; and lastly the upper<br>series, of the twenty-eight most ancient kings of France, which<br>garnished the gallery of the first story, beginning with<br>Childebert, and ending with Phillip Augustus, holding in his hand<br>“the imperial apple.”</p>\n<p>Time has caused the staircase to disappear, by raising the soil<br>of the city with a slow and irresistible progress; but, while<br>thus causing the eleven steps which added to the majestic height<br>of the edifice, to be devoured, one by one, by the rising tide of<br>the pavements of Paris,—time has bestowed upon the church perhaps<br>more than it has taken away, for it is time which has spread over<br>the façade that sombre hue of the centuries which makes the old<br>age of monuments the period of their beauty.</p>\n<p>But who has thrown down the two rows of statues? who has left the<br>niches empty? who has cut, in the very middle of the central<br>portal, that new and bastard arch? who has dared to frame therein<br>that commonplace and heavy door of carved wood, à la Louis XV.,<br>beside the arabesques of Biscornette? The men, the architects,<br>the artists of our day.</p>\n<p>And if we enter the interior of the edifice, who has overthrown<br>that colossus of Saint Christopher, proverbial for magnitude<br>among statues, as the grand hall of the Palais de Justice was<br>among halls, as the spire of Strasbourg among spires? And those<br>myriads of statues, which peopled all the spaces between the<br>columns of the nave and the choir, kneeling, standing,<br>equestrian, men, women, children, kings, bishops, gendarmes, in<br>stone, in marble, in gold, in silver, in copper, in wax even,—who<br>has brutally swept them away? It is not time.</p>\n<p>And who substituted for the ancient gothic altar, splendidly<br>encumbered with shrines and reliquaries, that heavy marble<br>sarcophagus, with angels’ heads and clouds, which seems a<br>specimen pillaged from the Val-de-Grâce or the Invalides? Who<br>stupidly sealed that heavy anachronism of stone in the<br>Carlovingian pavement of Hercandus? Was it not Louis XIV.,<br>fulfilling the request of Louis XIII.?</p>\n<p>And who put the cold, white panes in the place of those windows,<br>“high in color,” which caused the astonished eyes of our fathers<br>to hesitate between the rose of the grand portal and the arches<br>of the apse? And what would a sub-chanter of the sixteenth<br>century say, on beholding the beautiful yellow wash, with which<br>our archiepiscopal vandals have desmeared their cathedral? He<br>would remember that it was the color with which the hangman<br>smeared “accursed” edifices; he would recall the Hôtel du<br>Petit-Bourbon, all smeared thus, on account of the constable’s<br>treason. “Yellow, after all, of so good a quality,” said Sauval,<br>“and so well recommended, that more than a century has not yet<br>caused it to lose its color.” He would think that the sacred<br>place had become infamous, and would flee.</p>\n<p>And if we ascend the cathedral, without mentioning a thousand<br>barbarisms of every sort,—what has become of that charming little<br>bell tower, which rested upon the point of intersection of the<br>cross-roofs, and which, no less frail and no less bold than its<br>neighbor (also destroyed), the spire of the Sainte-Chapelle,<br>buried itself in the sky, farther forward than the towers,<br>slender, pointed, sonorous, carved in open work. An architect of<br>good taste amputated it (1787), and considered it sufficient to<br>mask the wound with that large, leaden plaster, which resembles a<br>pot cover.</p>\n<p>’Tis thus that the marvellous art of the Middle Ages has been<br>treated in nearly every country, especially in France. One can<br>distinguish on its ruins three sorts of lesions, all three of<br>which cut into it at different depths; first, time, which has<br>insensibly notched its surface here and there, and gnawed it<br>everywhere; next, political and religious revolution, which,<br>blind and wrathful by nature, have flung themselves tumultuously<br>upon it, torn its rich garment of carving and sculpture, burst<br>its rose windows, broken its necklace of arabesques and tiny<br>figures, torn out its statues, sometimes because of their mitres,<br>sometimes because of their crowns; lastly, fashions, even more<br>grotesque and foolish, which, since the anarchical and splendid<br>deviations of the Renaissance, have followed each other in the<br>necessary decadence of architecture. Fashions have wrought more<br>harm than revolutions. They have cut to the quick; they have<br>attacked the very bone and framework of art; they have cut,<br>slashed, disorganized, killed the edifice, in form as in the<br>symbol, in its consistency as well as in its beauty. And then<br>they have made it over; a presumption of which neither time nor<br>revolutions at least have been guilty. They have audaciously<br>adjusted, in the name of “good taste,” upon the wounds of gothic<br>architecture, their miserable gewgaws of a day, their ribbons of<br>marble, their pompons of metal, a veritable leprosy of egg-shaped<br>ornaments, volutes, whorls, draperies, garlands, fringes, stone<br>flames, bronze clouds, pudgy cupids, chubby-cheeked cherubim,<br>which begin to devour the face of art in the oratory of Catherine<br>de Medicis, and cause it to expire, two centuries later, tortured<br>and grimacing, in the boudoir of the Dubarry.</p>\n<p>Thus, to sum up the points which we have just indicated, three<br>sorts of ravages to-day disfigure Gothic architecture. Wrinkles<br>and warts on the epidermis; this is the work of time. Deeds of<br>violence, brutalities, contusions, fractures; this is the work of<br>the revolutions from Luther to Mirabeau. Mutilations,<br>amputations, dislocation of the joints, <em>restorations</em>; this is<br>the Greek, Roman, and barbarian work of professors according to<br>Vitruvius and Vignole. This magnificent art produced by the<br>Vandals has been slain by the academies. The centuries, the<br>revolutions, which at least devastate with impartiality and<br>grandeur, have been joined by a cloud of school architects,<br>licensed, sworn, and bound by oath; defacing with the discernment<br>and choice of bad taste, substituting the <em>chicorées</em> of Louis<br>XV. for the Gothic lace, for the greater glory of the Parthenon.<br>It is the kick of the ass at the dying lion. It is the old oak<br>crowning itself, and which, to heap the measure full, is stung,<br>bitten, and gnawed by caterpillars.</p>\n<p>How far it is from the epoch when Robert Cenalis, comparing<br>Notre-Dame de Paris to the famous temple of Diana at Ephesus, _so<br>much lauded by the ancient pagans<em>, which Erostatus </em>has_<br>immortalized, found the Gallic temple “more excellent in length,<br>breadth, height, and structure.”[19]</p>\n<p>Notre-Dame is not, moreover, what can be called a complete,<br>definite, classified monument. It is no longer a Romanesque<br>church; nor is it a Gothic church. This edifice is not a type.<br>Notre-Dame de Paris has not, like the Abbey of Tournus, the grave<br>and massive frame, the large and round vault, the glacial<br>bareness, the majestic simplicity of the edifices which have the<br>rounded arch for their progenitor. It is not, like the Cathedral<br>of Bourges, the magnificent, light, multiform, tufted, bristling<br>efflorescent product of the pointed arch. Impossible to class it<br>in that ancient family of sombre, mysterious churches, low and<br>crushed as it were by the round arch, almost Egyptian, with the<br>exception of the ceiling; all hieroglyphics, all sacerdotal, all<br>symbolical, more loaded in their ornaments, with lozenges and<br>zigzags, than with flowers, with flowers than with animals, with<br>animals than with men; the work of the architect less than of the<br>bishop; first transformation of art, all impressed with<br>theocratic and military discipline, taking root in the Lower<br>Empire, and stopping with the time of William the Conqueror.<br>Impossible to place our Cathedral in that other family of lofty,<br>aerial churches, rich in painted windows and sculpture; pointed<br>in form, bold in attitude; communal and <em>bourgeois</em> as political<br>symbols; free, capricious, lawless, as a work of art; second<br>transformation of architecture, no longer hieroglyphic, immovable<br>and sacerdotal, but artistic, progressive, and popular, which<br>begins at the return from the crusades, and ends with Louis IX.<br>Notre-Dame de Paris is not of pure Romanesque, like the first;<br>nor of pure Arabian race, like the second.</p>\n<p>It is an edifice of the transition period. The Saxon architect<br>completed the erection of the first pillars of the nave, when the<br>pointed arch, which dates from the Crusade, arrived and placed<br>itself as a conqueror upon the large Romanesque capitals which<br>should support only round arches. The pointed arch, mistress<br>since that time, constructed the rest of the church.<br>Nevertheless, timid and inexperienced at the start, it sweeps<br>out, grows larger, restrains itself, and dares no longer dart<br>upwards in spires and lancet windows, as it did later on, in so<br>many marvellous cathedrals. One would say that it were conscious<br>of the vicinity of the heavy Romanesque pillars.</p>\n<p>However, these edifices of the transition from the Romanesque to<br>the Gothic, are no less precious for study than the pure types.<br>They express a shade of the art which would be lost without them.<br>It is the graft of the pointed upon the round arch.</p>\n<p>Notre-Dame de Paris is, in particular, a curious specimen of this<br>variety. Each face, each stone of the venerable monument, is a<br>page not only of the history of the country, but of the history<br>of science and art as well. Thus, in order to indicate here only<br>the principal details, while the little Red Door almost attains<br>to the limits of the Gothic delicacy of the fifteenth century,<br>the pillars of the nave, by their size and weight, go back to the<br>Carlovingian Abbey of Saint-Germain-des-Prés. One would suppose<br>that six centuries separated these pillars from that door. There<br>is no one, not even the hermetics, who does not find in the<br>symbols of the grand portal a satisfactory compendium of their<br>science, of which the Church of Saint-Jacques de la Boucherie was<br>so complete a hieroglyph. Thus, the Roman abbey, the<br>philosophers’ church, the Gothic art, Saxon art, the heavy, round<br>pillar, which recalls Gregory VII., the hermetic symbolism, with<br>which Nicolas Flamel played the prelude to Luther, papal unity,<br>schism, Saint-Germain des Prés, Saint-Jacques de la<br>Boucherie,—all are mingled, combined, amalgamated in Notre-Dame.<br>This central mother church is, among the ancient churches of<br>Paris, a sort of chimera; it has the head of one, the limbs of<br>another, the haunches of another, something of all.</p>\n<p>We repeat it, these hybrid constructions are not the least<br>interesting for the artist, for the antiquarian, for the<br>historian. They make one feel to what a degree architecture is a<br>primitive thing, by demonstrating (what is also demonstrated by<br>the cyclopean vestiges, the pyramids of Egypt, the gigantic<br>Hindoo pagodas) that the greatest products of architecture are<br>less the works of individuals than of society; rather the<br>offspring of a nation’s effort, than the inspired flash of a man<br>of genius; the deposit left by a whole people; the heaps<br>accumulated by centuries; the residue of successive evaporations<br>of human society,—in a word, species of formations. Each wave of<br>time contributes its alluvium, each race deposits its layer on<br>the monument, each individual brings his stone. Thus do the<br>beavers, thus do the bees, thus do men. The great symbol of<br>architecture, Babel, is a hive.</p>\n<p>Great edifices, like great mountains, are the work of centuries.<br>Art often undergoes a transformation while they are pending,<br><em>pendent opera interrupta</em>; they proceed quietly in accordance<br>with the transformed art. The new art takes the monument where it<br>finds it, incrusts itself there, assimilates it to itself,<br>develops it according to its fancy, and finishes it if it can.<br>The thing is accomplished without trouble, without effort,<br>without reaction,—following a natural and tranquil law. It is a<br>graft which shoots up, a sap which circulates, a vegetation which<br>starts forth anew. Certainly there is matter here for many large<br>volumes, and often the universal history of humanity in the<br>successive engrafting of many arts at many levels, upon the same<br>monument. The man, the artist, the individual, is effaced in<br>these great masses, which lack the name of their author; human<br>intelligence is there summed up and totalized. Time is the<br>architect, the nation is the builder.</p>\n<p>Not to consider here anything except the Christian architecture<br>of Europe, that younger sister of the great masonries of the<br>Orient, it appears to the eyes as an immense formation divided<br>into three well-defined zones, which are superposed, the one upon<br>the other: the Romanesque zone[20], the Gothic zone, the zone of<br>the Renaissance, which we would gladly call the Greco-Roman zone.<br>The Roman layer, which is the most ancient and deepest, is<br>occupied by the round arch, which reappears, supported by the<br>Greek column, in the modern and upper layer of the Renaissance.<br>The pointed arch is found between the two. The edifices which<br>belong exclusively to any one of these three layers are perfectly<br>distinct, uniform, and complete. There is the Abbey of Jumiéges,<br>there is the Cathedral of Reims, there is the Sainte-Croix of<br>Orléans. But the three zones mingle and amalgamate along the<br>edges, like the colors in the solar spectrum. Hence, complex<br>monuments, edifices of gradation and transition. One is Roman at<br>the base, Gothic in the middle, Greco-Roman at the top. It is<br>because it was six hundred years in building. This variety is<br>rare. The donjon keep of d’Étampes is a specimen of it. But<br>monuments of two formations are more frequent. There is<br>Notre-Dame de Paris, a pointed-arch edifice, which is imbedded by<br>its pillars in that Roman zone, in which are plunged the portal<br>of Saint-Denis, and the nave of Saint-Germain des Prés. There is<br>the charming, half-Gothic chapter-house of Bocherville, where the<br>Roman layer extends half way up. There is the cathedral of Rouen,<br>which would be entirely Gothic if it did not bathe the tip of its<br>central spire in the zone of the Renaissance.[21]</p>\n<p>However, all these shades, all these differences, do not affect<br>the surfaces of edifices only. It is art which has changed its<br>skin. The very constitution of the Christian church is not<br>attacked by it. There is always the same internal woodwork, the<br>same logical arrangement of parts. Whatever may be the carved and<br>embroidered envelope of a cathedral, one always finds beneath<br>it—in the state of a germ, and of a rudiment at the least—the<br>Roman basilica. It is eternally developed upon the soil according<br>to the same law. There are, invariably, two naves, which<br>intersect in a cross, and whose upper portion, rounded into an<br>apse, forms the choir; there are always the side aisles, for<br>interior processions, for chapels,—a sort of lateral walks or<br>promenades where the principal nave discharges itself through the<br>spaces between the pillars. That settled, the number of chapels,<br>doors, bell towers, and pinnacles are modified to infinity,<br>according to the fancy of the century, the people, and art. The<br>service of religion once assured and provided for, architecture<br>does what she pleases. Statues, stained glass, rose windows,<br>arabesques, denticulations, capitals, bas-reliefs,—she combines<br>all these imaginings according to the arrangement which best<br>suits her. Hence, the prodigious exterior variety of these<br>edifices, at whose foundation dwells so much order and unity. The<br>trunk of a tree is immovable; the foliage is capricious.</p>\n<h1 class=\"chapter\" id=\"chapter-ii-a-birds-eye-view-of-paris\">Chapter II. A BIRD’S-EYE VIEW OF PARIS.</h1>\n<p>We have just attempted to restore, for the reader’s benefit, that<br>admirable church of Notre-Dame de Paris. We have briefly pointed<br>out the greater part of the beauties which it possessed in the<br>fifteenth century, and which it lacks to-day; but we have omitted<br>the principal thing,—the view of Paris which was then to be<br>obtained from the summits of its towers.</p>\n<p>That was, in fact,—when, after having long groped one’s way up<br>the dark spiral which perpendicularly pierces the thick wall of<br>the belfries, one emerged, at last abruptly, upon one of the<br>lofty platforms inundated with light and air,—that was, in fact,<br>a fine picture which spread out, on all sides at once, before the<br>eye; a spectacle <em>sui generis</em>, of which those of our readers who<br>have had the good fortune to see a Gothic city entire, complete,<br>homogeneous,—a few of which still remain, Nuremberg in Bavaria<br>and Vittoria in Spain,—can readily form an idea; or even smaller<br>specimens, provided that they are well preserved,—Vitré in<br>Brittany, Nordhausen in Prussia.</p>\n<p>The Paris of three hundred and fifty years ago—the Paris of the<br>fifteenth century—was already a gigantic city. We Parisians<br>generally make a mistake as to the ground which we think that we<br>have gained, since Paris has not increased much over one-third<br>since the time of Louis XI. It has certainly lost more in beauty<br>than it has gained in size.</p>\n<p>Paris had its birth, as the reader knows, in that old island of<br>the City which has the form of a cradle. The strand of that<br>island was its first boundary wall, the Seine its first moat.<br>Paris remained for many centuries in its island state, with two<br>bridges, one on the north, the other on the south; and two bridge<br>heads, which were at the same time its gates and its<br>fortresses,—the Grand-Châtelet on the right bank, the<br>Petit-Châtelet on the left. Then, from the date of the kings of<br>the first race, Paris, being too cribbed and confined in its<br>island, and unable to return thither, crossed the water. Then,<br>beyond the Grand, beyond the Petit-Châtelet, a first circle of<br>walls and towers began to infringe upon the country on the two<br>sides of the Seine. Some vestiges of this ancient enclosure still<br>remained in the last century; to-day, only the memory of it is<br>left, and here and there a tradition, the Baudets or Baudoyer<br>gate, <em>Porta Bagauda</em>.</p>\n<p>Little by little, the tide of houses, always thrust from the<br>heart of the city outwards, overflows, devours, wears away, and<br>effaces this wall. Philip Augustus makes a new dike for it. He<br>imprisons Paris in a circular chain of great towers, both lofty<br>and solid. For the period of more than a century, the houses<br>press upon each other, accumulate, and raise their level in this<br>basin, like water in a reservoir. They begin to deepen; they pile<br>story upon story; they mount upon each other; they gush forth at<br>the top, like all laterally compressed growth, and there is a<br>rivalry as to which shall thrust its head above its neighbors,<br>for the sake of getting a little air. The street glows narrower<br>and deeper, every space is overwhelmed and disappears. The houses<br>finally leap the wall of Philip Augustus, and scatter joyfully<br>over the plain, without order, and all askew, like runaways.<br>There they plant themselves squarely, cut themselves gardens from<br>the fields, and take their ease. Beginning with 1367, the city<br>spreads to such an extent into the suburbs, that a new wall<br>becomes necessary, particularly on the right bank; Charles V.<br>builds it. But a city like Paris is perpetually growing. It is<br>only such cities that become capitals. They are funnels, into<br>which all the geographical, political, moral, and intellectual<br>water-sheds of a country, all the natural slopes of a people,<br>pour; wells of civilization, so to speak, and also sewers, where<br>commerce, industry, intelligence, population,—all that is sap,<br>all that is life, all that is the soul of a nation, filters and<br>amasses unceasingly, drop by drop, century by century.</p>\n<p>So Charles V.’s wall suffered the fate of that of Philip<br>Augustus. At the end of the fifteenth century, the Faubourg<br>strides across it, passes beyond it, and runs farther. In the<br>sixteenth, it seems to retreat visibly, and to bury itself deeper<br>and deeper in the old city, so thick had the new city already<br>become outside of it. Thus, beginning with the fifteenth century,<br>where our story finds us, Paris had already outgrown the three<br>concentric circles of walls which, from the time of Julian the<br>Apostate, existed, so to speak, in germ in the Grand-Châtelet and<br>the Petit-Châtelet. The mighty city had cracked, in succession,<br>its four enclosures of walls, like a child grown too large for<br>his garments of last year. Under Louis XI., this sea of houses<br>was seen to be pierced at intervals by several groups of ruined<br>towers, from the ancient wall, like the summits of hills in an<br>inundation,—like archipelagos of the old Paris submerged beneath<br>the new. Since that time Paris has undergone yet another<br>transformation, unfortunately for our eyes; but it has passed<br>only one more wall, that of Louis XV., that miserable wall of mud<br>and spittle, worthy of the king who built it, worthy of the poet<br>who sung it,—</p>\n<p>Le mur murant Paris rend Paris murmurant.[22]</p>\n<p>In the fifteenth century, Paris was still divided into three<br>wholly distinct and separate towns, each having its own<br>physiognomy, its own specialty, its manners, customs, privileges,<br>and history: the City, the University, the Town. The City, which<br>occupied the island, was the most ancient, the smallest, and the<br>mother of the other two, crowded in between them like (may we be<br>pardoned the comparison) a little old woman between two large and<br>handsome maidens. The University covered the left bank of the<br>Seine, from the Tournelle to the Tour de Nesle, points which<br>correspond in the Paris of to-day, the one to the wine market,<br>the other to the mint. Its wall included a large part of that<br>plain where Julian had built his hot baths. The hill of<br>Sainte-Geneviève was enclosed in it. The culminating point of<br>this sweep of walls was the Papal gate, that is to say, near the<br>present site of the Pantheon. The Town, which was the largest of<br>the three fragments of Paris, held the right bank. Its quay,<br>broken or interrupted in many places, ran along the Seine, from<br>the Tour de Billy to the Tour du Bois; that is to say, from the<br>place where the granary stands to-day, to the present site of the<br>Tuileries. These four points, where the Seine intersected the<br>wall of the capital, the Tournelle and the Tour de Nesle on the<br>right, the Tour de Billy and the Tour du Bois on the left, were<br>called pre-eminently, <em>the four towers of Paris</em>. The Town<br>encroached still more extensively upon the fields than the<br>University. The culminating point of the Town wall (that of<br>Charles V.) was at the gates of Saint-Denis and Saint-Martin,<br>whose situation has not been changed.</p>\n<p>As we have just said, each of these three great divisions of<br>Paris was a town, but too special a town to be complete, a city<br>which could not get along without the other two. Hence three<br>entirely distinct aspects: churches abounded in the City;<br>palaces, in the Town; and colleges, in the University. Neglecting<br>here the originalities, of secondary importance in old Paris, and<br>the capricious regulations regarding the public highways, we will<br>say, from a general point of view, taking only masses and the<br>whole group, in this chaos of communal jurisdictions, that the<br>island belonged to the bishop, the right bank to the provost of<br>the merchants, the left bank to the Rector; over all ruled the<br>provost of Paris, a royal not a municipal official. The City had<br>Notre-Dame; the Town, the Louvre and the Hôtel de Ville; the<br>University, the Sorbonne. The Town had the markets (Halles); the<br>city, the Hospital; the University, the Pré-aux-Clercs. Offences<br>committed by the scholars on the left bank were tried in the law<br>courts on the island, and were punished on the right bank at<br>Montfaucon; unless the rector, feeling the university to be<br>strong and the king weak, intervened; for it was the students’<br>privilege to be hanged on their own grounds.</p>\n<p>The greater part of these privileges, it may be noted in passing,<br>and there were some even better than the above, had been extorted<br>from the kings by revolts and mutinies. It is the course of<br>things from time immemorial; the king only lets go when the<br>people tear away. There is an old charter which puts the matter<br>naively: <em>àpropos</em> of fidelity: _Civibus fidelitas in reges, quæ<br>tamen aliquoties seditionibus interrupta, multa peperit<br>privilegia_.</p>\n<p>In the fifteenth century, the Seine bathed five islands within<br>the walls of Paris: Louviers island, where there were then trees,<br>and where there is no longer anything but wood; l’île aux Vaches,<br>and l’île Notre-Dame, both deserted, with the exception of one<br>house, both fiefs of the bishop—in the seventeenth century, a<br>single island was formed out of these two, which was built upon<br>and named l’île Saint-Louis—, lastly the City, and at its point,<br>the little islet of the cow tender, which was afterwards engulfed<br>beneath the platform of the Pont-Neuf. The City then had five<br>bridges: three on the right, the Pont Notre-Dame, and the Pont au<br>Change, of stone, the Pont aux Meuniers, of wood; two on the<br>left, the Petit Pont, of stone, the Pont Saint-Michel, of wood;<br>all loaded with houses.</p>\n<p>The University had six gates, built by Philip Augustus; there<br>were, beginning with la Tournelle, the Porte Saint-Victor, the<br>Porte Bordelle, the Porte Papale, the Porte Saint-Jacques, the<br>Porte Saint-Michel, the Porte Saint-Germain. The Town had six<br>gates, built by Charles V.; beginning with the Tour de Billy they<br>were: the Porte Saint-Antoine, the Porte du Temple, the Porte<br>Saint-Martin, the Porte Saint-Denis, the Porte Montmartre, the<br>Porte Saint-Honoré. All these gates were strong, and also<br>handsome, which does not detract from strength. A large, deep<br>moat, with a brisk current during the high water of winter,<br>bathed the base of the wall round Paris; the Seine furnished the<br>water. At night, the gates were shut, the river was barred at<br>both ends of the city with huge iron chains, and Paris slept<br>tranquilly.</p>\n<p>From a bird’s-eye view, these three burgs, the City, the Town,<br>and the University, each presented to the eye an inextricable<br>skein of eccentrically tangled streets. Nevertheless, at first<br>sight, one recognized the fact that these three fragments formed<br>but one body. One immediately perceived three long parallel<br>streets, unbroken, undisturbed, traversing, almost in a straight<br>line, all three cities, from one end to the other; from North to<br>South, perpendicularly, to the Seine, which bound them together,<br>mingled them, infused them in each other, poured and transfused<br>the people incessantly, from one to the other, and made one out<br>of the three. The first of these streets ran from the Porte<br>Saint-Martin: it was called the Rue Saint-Jacques in the<br>University, Rue de la Juiverie in the City, Rue Saint-Martin in<br>the Town; it crossed the water twice, under the name of the Petit<br>Pont and the Pont Notre-Dame. The second, which was called the<br>Rue de la Harpe on the left bank, Rue de la Barillerié in the<br>island, Rue Saint-Denis on the right bank, Pont Saint-Michel on<br>one arm of the Seine, Pont au Change on the other, ran from the<br>Porte Saint-Michel in the University, to the Porte Saint-Denis in<br>the Town. However, under all these names, there were but two<br>streets, parent streets, generating streets,—the two arteries of<br>Paris. All the other veins of the triple city either derived<br>their supply from them or emptied into them.</p>\n<p>Independently of these two principal streets, piercing Paris<br>diametrically in its whole breadth, from side to side, common to<br>the entire capital, the City and the University had also each its<br>own great special street, which ran lengthwise by them, parallel<br>to the Seine, cutting, as it passed, at right angles, the two<br>arterial thoroughfares. Thus, in the Town, one descended in a<br>straight line from the Porte Saint-Antoine to the Porte<br>Saint-Honoré; in the University from the Porte Saint-Victor to<br>the Porte Saint-Germain. These two great thoroughfares<br>intersected by the two first, formed the canvas upon which<br>reposed, knotted and crowded together on every hand, the<br>labyrinthine network of the streets of Paris. In the<br>incomprehensible plan of these streets, one distinguished<br>likewise, on looking attentively, two clusters of great streets,<br>like magnified sheaves of grain, one in the University, the other<br>in the Town, which spread out gradually from the bridges to the<br>gates.</p>\n<p>Some traces of this geometrical plan still exist to-day.</p>\n<p>Now, what aspect did this whole present, when, as viewed from the<br>summit of the towers of Notre-Dame, in 1482? That we shall try to<br>describe.</p>\n<p>For the spectator who arrived, panting, upon that pinnacle, it<br>was first a dazzling confusing view of roofs, chimneys, streets,<br>bridges, places, spires, bell towers. Everything struck your eye<br>at once: the carved gable, the pointed roof, the turrets<br>suspended at the angles of the walls; the stone pyramids of the<br>eleventh century, the slate obelisks of the fifteenth; the round,<br>bare tower of the donjon keep; the square and fretted tower of<br>the church; the great and the little, the massive and the aerial.<br>The eye was, for a long time, wholly lost in this labyrinth,<br>where there was nothing which did not possess its originality,<br>its reason, its genius, its beauty,—nothing which did not proceed<br>from art; beginning with the smallest house, with its painted and<br>carved front, with external beams, elliptical door, with<br>projecting stories, to the royal Louvre, which then had a<br>colonnade of towers. But these are the principal masses which<br>were then to be distinguished when the eye began to accustom<br>itself to this tumult of edifices.</p>\n<p>In the first place, the City.—“The island of the City,” as Sauval<br>says, who, in spite of his confused medley, sometimes has such<br>happy turns of expression,—“the island of the city is made like a<br>great ship, stuck in the mud and run aground in the current, near<br>the centre of the Seine.”</p>\n<p>We have just explained that, in the fifteenth century, this ship<br>was anchored to the two banks of the river by five bridges. This<br>form of a ship had also struck the heraldic scribes; for it is<br>from that, and not from the siege by the Normans, that the ship<br>which blazons the old shield of Paris, comes, according to Favyn<br>and Pasquier. For him who understands how to decipher them,<br>armorial bearings are algebra, armorial bearings have a tongue.<br>The whole history of the second half of the Middle Ages is<br>written in armorial bearings,—the first half is in the symbolism<br>of the Roman churches. They are the hieroglyphics of feudalism,<br>succeeding those of theocracy.</p>\n<p>Thus the City first presented itself to the eye, with its stern<br>to the east, and its prow to the west. Turning towards the prow,<br>one had before one an innumerable flock of ancient roofs, over<br>which arched broadly the lead-covered apse of the<br>Sainte-Chapelle, like an elephant’s haunches loaded with its<br>tower. Only here, this tower was the most audacious, the most<br>open, the most ornamented spire of cabinet-maker’s work that ever<br>let the sky peep through its cone of lace. In front of<br>Notre-Dame, and very near at hand, three streets opened into the<br>cathedral square,—a fine square, lined with ancient houses. Over<br>the south side of this place bent the wrinkled and sullen façade<br>of the Hôtel Dieu, and its roof, which seemed covered with warts<br>and pustules. Then, on the right and the left, to east and west,<br>within that wall of the City, which was yet so contracted, rose<br>the bell towers of its one and twenty churches, of every date, of<br>every form, of every size, from the low and wormeaten belfry of<br>Saint-Denis du Pas (<em>Carcer Glaucini</em>) to the slender needles of<br>Saint-Pierre aux Bœufs and Saint-Landry.</p>\n<p>Behind Notre-Dame, the cloister and its Gothic galleries spread<br>out towards the north; on the south, the half-Roman palace of the<br>bishop; on the east, the desert point of the Terrain. In this<br>throng of houses the eye also distinguished, by the lofty<br>open-work mitres of stone which then crowned the roof itself,<br>even the most elevated windows of the palace, the hotel given by<br>the city, under Charles VI., to Juvénal des Ursins; a little<br>farther on, the pitch-covered sheds of the Palus Market; in still<br>another quarter the new apse of Saint-Germain le Vieux,<br>lengthened in 1458, with a bit of the Rue aux Febves; and then,<br>in places, a square crowded with people; a pillory, erected at<br>the corner of a street; a fine fragment of the pavement of Philip<br>Augustus, a magnificent flagging, grooved for the horses’ feet,<br>in the middle of the road, and so badly replaced in the sixteenth<br>century by the miserable cobblestones, called the _pavement of<br>the League;_ a deserted back courtyard, with one of those<br>diaphanous staircase turrets, such as were erected in the<br>fifteenth century, one of which is still to be seen in the Rue<br>des Bourdonnais. Lastly, at the right of the Sainte-Chapelle,<br>towards the west, the Palais de Justice rested its group of<br>towers at the edge of the water. The thickets of the king’s<br>gardens, which covered the western point of the City, masked the<br>Island du Passeur. As for the water, from the summit of the<br>towers of Notre-Dame one hardly saw it, on either side of the<br>City; the Seine was hidden by bridges, the bridges by houses.</p>\n<p>And when the glance passed these bridges, whose roofs were<br>visibly green, rendered mouldy before their time by the vapors<br>from the water, if it was directed to the left, towards the<br>University, the first edifice which struck it was a large, low<br>sheaf of towers, the Petit-Châtelet, whose yawning gate devoured<br>the end of the Petit-Pont. Then, if your view ran along the bank,<br>from east to west, from the Tournelle to the Tour de Nesle, there<br>was a long cordon of houses, with carved beams, stained-glass<br>windows, each story projecting over that beneath it, an<br>interminable zigzag of <em>bourgeois</em> gables, frequently interrupted<br>by the mouth of a street, and from time to time also by the front<br>or angle of a huge stone mansion, planted at its ease, with<br>courts and gardens, wings and detached buildings, amid this<br>populace of crowded and narrow houses, like a grand gentleman<br>among a throng of rustics. There were five or six of these<br>mansions on the quay, from the house of Lorraine, which shared<br>with the Bernardins the grand enclosure adjoining the Tournelle,<br>to the Hôtel de Nesle, whose principal tower ended Paris, and<br>whose pointed roofs were in a position, during three months of<br>the year, to encroach, with their black triangles, upon the<br>scarlet disk of the setting sun.</p>\n<p>This side of the Seine was, however, the least mercantile of the<br>two. Students furnished more of a crowd and more noise there than<br>artisans, and there was not, properly speaking, any quay, except<br>from the Pont Saint-Michel to the Tour de Nesle. The rest of the<br>bank of the Seine was now a naked strand, the same as beyond the<br>Bernardins; again, a throng of houses, standing with their feet<br>in the water, as between the two bridges.</p>\n<p>There was a great uproar of laundresses; they screamed, and<br>talked, and sang from morning till night along the beach, and<br>beat a great deal of linen there, just as in our day. This is not<br>the least of the gayeties of Paris.</p>\n<p>The University presented a dense mass to the eye. From one end to<br>the other, it was homogeneous and compact. The thousand roofs,<br>dense, angular, clinging to each other, composed, nearly all, of<br>the same geometrical element, offered, when viewed from above,<br>the aspect of a crystallization of the same substance.</p>\n<p>The capricious ravine of streets did not cut this block of houses<br>into too disproportionate slices. The forty-two colleges were<br>scattered about in a fairly equal manner, and there were some<br>everywhere. The amusingly varied crests of these beautiful<br>edifices were the product of the same art as the simple roofs<br>which they overshot, and were, actually, only a multiplication of<br>the square or the cube of the same geometrical figure. Hence they<br>complicated the whole effect, without disturbing it; completed,<br>without overloading it. Geometry is harmony. Some fine mansions<br>here and there made magnificent outlines against the picturesque<br>attics of the left bank. The house of Nevers, the house of Rome,<br>the house of Reims, which have disappeared; the Hôtel de Cluny,<br>which still exists, for the consolation of the artist, and whose<br>tower was so stupidly deprived of its crown a few years ago.<br>Close to Cluny, that Roman palace, with fine round arches, were<br>once the hot baths of Julian. There were a great many abbeys, of<br>a beauty more devout, of a grandeur more solemn than the<br>mansions, but not less beautiful, not less grand. Those which<br>first caught the eye were the Bernardins, with their three bell<br>towers; Sainte-Geneviève, whose square tower, which still exists,<br>makes us regret the rest; the Sorbonne, half college, half<br>monastery, of which so admirable a nave survives; the fine<br>quadrilateral cloister of the Mathurins; its neighbor, the<br>cloister of Saint-Benoît, within whose walls they have had time<br>to cobble up a theatre, between the seventh and eighth editions<br>of this book; the Cordeliers, with their three enormous adjacent<br>gables; the Augustins, whose graceful spire formed, after the<br>Tour de Nesle, the second denticulation on this side of Paris,<br>starting from the west. The colleges, which are, in fact, the<br>intermediate ring between the cloister and the world, hold the<br>middle position in the monumental series between the hotels and<br>the abbeys, with a severity full of elegance, sculpture less<br>giddy than the palaces, an architecture less severe than the<br>convents. Unfortunately, hardly anything remains of these<br>monuments, where Gothic art combined with so just a balance,<br>richness and economy. The churches (and they were numerous and<br>splendid in the University, and they were graded there also in<br>all the ages of architecture, from the round arches of<br>Saint-Julian to the pointed arches of Saint-Séverin), the<br>churches dominated the whole; and, like one harmony more in this<br>mass of harmonies, they pierced in quick succession the multiple<br>open work of the gables with slashed spires, with open-work bell<br>towers, with slender pinnacles, whose line was also only a<br>magnificent exaggeration of the acute angle of the roofs.</p>\n<p>The ground of the University was hilly; Mount Sainte-Geneviève<br>formed an enormous mound to the south; and it was a sight to see<br>from the summit of Notre-Dame how that throng of narrow and<br>tortuous streets (to-day the Latin Quarter), those bunches of<br>houses which, spread out in every direction from the top of this<br>eminence, precipitated themselves in disorder, and almost<br>perpendicularly down its flanks, nearly to the water’s edge,<br>having the air, some of falling, others of clambering up again,<br>and all of holding to one another. A continual flux of a thousand<br>black points which passed each other on the pavements made<br>everything move before the eyes; it was the populace seen thus<br>from aloft and afar.</p>\n<p>Lastly, in the intervals of these roofs, of these spires, of<br>these accidents of numberless edifices, which bent and writhed,<br>and jagged in so eccentric a manner the extreme line of the<br>University, one caught a glimpse, here and there, of a great<br>expanse of moss-grown wall, a thick, round tower, a crenellated<br>city gate, shadowing forth the fortress; it was the wall of<br>Philip Augustus. Beyond, the fields gleamed green; beyond, fled<br>the roads, along which were scattered a few more suburban houses,<br>which became more infrequent as they became more distant. Some of<br>these faubourgs were important: there were, first, starting from<br>la Tournelle, the Bourg Saint-Victor, with its one arch bridge<br>over the Bièvre, its abbey where one could read the epitaph of<br>Louis le Gros, <em>epitaphium Ludovici Grossi</em>, and its church with<br>an octagonal spire, flanked with four little bell towers of the<br>eleventh century (a similar one can be seen at Étampes; it is not<br>yet destroyed); next, the Bourg Saint-Marceau, which already had<br>three churches and one convent; then, leaving the mill of the<br>Gobelins and its four white walls on the left, there was the<br>Faubourg Saint-Jacques with the beautiful carved cross in its<br>square; the church of Saint-Jacques du Haut-Pas, which was then<br>Gothic, pointed, charming; Saint-Magloire, a fine nave of the<br>fourteenth century, which Napoleon turned into a hayloft;<br>Notre-Dame des Champs, where there were Byzantine mosaics;<br>lastly, after having left behind, full in the country, the<br>Monastery des Chartreux, a rich edifice contemporary with the<br>Palais de Justice, with its little garden divided into<br>compartments, and the haunted ruins of Vauvert, the eye fell, to<br>the west, upon the three Roman spires of Saint-Germain des Prés.<br>The Bourg Saint-Germain, already a large community, formed<br>fifteen or twenty streets in the rear; the pointed bell tower of<br>Saint-Sulpice marked one corner of the town. Close beside it one<br>descried the quadrilateral enclosure of the fair of<br>Saint-Germain, where the market is situated to-day; then the<br>abbot’s pillory, a pretty little round tower, well capped with a<br>leaden cone; the brickyard was further on, and the Rue du Four,<br>which led to the common bakehouse, and the mill on its hillock,<br>and the lazar house, a tiny house, isolated and half seen.</p>\n<p>But that which attracted the eye most of all, and fixed it for a<br>long time on that point, was the abbey itself. It is certain that<br>this monastery, which had a grand air, both as a church and as a<br>seignory; that abbatial palace, where the bishops of Paris<br>counted themselves happy if they could pass the night; that<br>refectory, upon which the architect had bestowed the air, the<br>beauty, and the rose window of a cathedral; that elegant chapel<br>of the Virgin; that monumental dormitory; those vast gardens;<br>that portcullis; that drawbridge; that envelope of battlements<br>which notched to the eye the verdure of the surrounding meadows;<br>those courtyards, where gleamed men at arms, intermingled with<br>golden copes;—the whole grouped and clustered about three lofty<br>spires, with round arches, well planted upon a Gothic apse, made<br>a magnificent figure against the horizon.</p>\n<p>When, at length, after having contemplated the University for a<br>long time, you turned towards the right bank, towards the Town,<br>the character of the spectacle was abruptly altered. The Town, in<br>fact much larger than the University, was also less of a unit. At<br>the first glance, one saw that it was divided into many masses,<br>singularly distinct. First, to the eastward, in that part of the<br>town which still takes its name from the marsh where Camulogènes<br>entangled Cæsar, was a pile of palaces. The block extended to the<br>very water’s edge. Four almost contiguous hotels, Jouy, Sens,<br>Barbeau, the house of the Queen, mirrored their slate peaks,<br>broken with slender turrets, in the Seine.</p>\n<p>These four edifices filled the space from the Rue des<br>Nonaindières, to the abbey of the Celestins, whose spire<br>gracefully relieved their line of gables and battlements. A few<br>miserable, greenish hovels, hanging over the water in front of<br>these sumptuous hotels, did not prevent one from seeing the fine<br>angles of their façades, their large, square windows with stone<br>mullions, their pointed porches overloaded with statues, the<br>vivid outlines of their walls, always clear cut, and all those<br>charming accidents of architecture, which cause Gothic art to<br>have the air of beginning its combinations afresh with every<br>monument.</p>\n<p>Behind these palaces, extended in all directions, now broken,<br>fenced in, battlemented like a citadel, now veiled by great trees<br>like a Carthusian convent, the immense and multiform enclosure of<br>that miraculous Hôtel de Saint-Pol, where the King of France<br>possessed the means of lodging superbly two and twenty princes of<br>the rank of the dauphin and the Duke of Burgundy, with their<br>domestics and their suites, without counting the great lords, and<br>the emperor when he came to view Paris, and the lions, who had<br>their separate hotel at the royal hotel. Let us say here that a<br>prince’s apartment was then composed of never less than eleven<br>large rooms, from the chamber of state to the oratory, not to<br>mention the galleries, baths, vapor-baths, and other “superfluous<br>places,” with which each apartment was provided; not to mention<br>the private gardens for each of the king’s guests; not to mention<br>the kitchens, the cellars, the domestic offices, the general<br>refectories of the house, the poultry-yards, where there were<br>twenty-two general laboratories, from the bakehouses to the<br>wine-cellars; games of a thousand sorts, malls, tennis, and<br>riding at the ring; aviaries, fishponds, menageries, stables,<br>barns, libraries, arsenals and foundries. This was what a king’s<br>palace, a Louvre, a Hôtel de Saint-Pol was then. A city within a<br>city.</p>\n<p>From the tower where we are placed, the Hôtel Saint-Pol, almost<br>half hidden by the four great houses of which we have just<br>spoken, was still very considerable and very marvellous to see.<br>One could there distinguish, very well, though cleverly united<br>with the principal building by long galleries, decked with<br>painted glass and slender columns, the three hotels which Charles<br>V. had amalgamated with his palace: the Hôtel du Petit-Muce, with<br>the airy balustrade, which formed a graceful border to its roof;<br>the Hôtel of the Abbé de Saint-Maur, having the vanity of a<br>stronghold, a great tower, machicolations, loopholes, iron<br>gratings, and over the large Saxon door, the armorial bearings of<br>the abbé, between the two mortises of the drawbridge; the Hôtel<br>of the Comte d’Étampes, whose donjon keep, ruined at its summit,<br>was rounded and notched like a cock’s comb; here and there, three<br>or four ancient oaks, forming a tuft together like enormous<br>cauliflowers; gambols of swans, in the clear water of the<br>fishponds, all in folds of light and shade; many courtyards of<br>which one beheld picturesque bits; the Hôtel of the Lions, with<br>its low, pointed arches on short, Saxon pillars, its iron<br>gratings and its perpetual roar; shooting up above the whole, the<br>scale-ornamented spire of the Ave-Maria; on the left, the house<br>of the Provost of Paris, flanked by four small towers, delicately<br>grooved, in the middle; at the extremity, the Hôtel Saint-Pol,<br>properly speaking, with its multiplied façades, its successive<br>enrichments from the time of Charles V., the hybrid excrescences,<br>with which the fancy of the architects had loaded it during the<br>last two centuries, with all the apses of its chapels, all the<br>gables of its galleries, a thousand weathercocks for the four<br>winds, and its two lofty contiguous towers, whose conical roof,<br>surrounded by battlements at its base, looked like those pointed<br>caps which have their edges turned up.</p>\n<p>Continuing to mount the stories of this amphitheatre of palaces<br>spread out afar upon the ground, after crossing a deep ravine<br>hollowed out of the roofs in the Town, which marked the passage<br>of the Rue Saint-Antoine, the eye reached the house of Angoulême,<br>a vast construction of many epochs, where there were perfectly<br>new and very white parts, which melted no better into the whole<br>than a red patch on a blue doublet. Nevertheless, the remarkably<br>pointed and lofty roof of the modern palace, bristling with<br>carved eaves, covered with sheets of lead, where coiled a<br>thousand fantastic arabesques of sparkling incrustations of<br>gilded bronze, that roof, so curiously damascened, darted upwards<br>gracefully from the midst of the brown ruins of the ancient<br>edifice; whose huge and ancient towers, rounded by age like<br>casks, sinking together with old age, and rending themselves from<br>top to bottom, resembled great bellies unbuttoned. Behind rose<br>the forest of spires of the Palais des Tournelles. Not a view in<br>the world, either at Chambord or at the Alhambra, is more magic,<br>more aerial, more enchanting, than that thicket of spires, tiny<br>bell towers, chimneys, weather-vanes, winding staircases,<br>lanterns through which the daylight makes its way, which seem cut<br>out at a blow, pavilions, spindle-shaped turrets, or, as they<br>were then called, <em>tournelles</em>, all differing in form, in height,<br>and attitude. One would have pronounced it a gigantic stone<br>chess-board.</p>\n<p>To the right of the Tournelles, that truss of enormous towers,<br>black as ink, running into each other and tied, as it were, by a<br>circular moat; that donjon keep, much more pierced with loopholes<br>than with windows; that drawbridge, always raised; that<br>portcullis, always lowered,—is the Bastille. Those sorts of black<br>beaks which project from between the battlements, and which you<br>take from a distance to be cave spouts, are cannons.</p>\n<p>Beneath them, at the foot of the formidable edifice, behold the<br>Porte Sainte-Antoine, buried between its two towers.</p>\n<p>Beyond the Tournelles, as far as the wall of Charles V., spread<br>out, with rich compartments of verdure and of flowers, a velvet<br>carpet of cultivated land and royal parks, in the midst of which<br>one recognized, by its labyrinth of trees and alleys, the famous<br>Dædalus garden which Louis XI. had given to Coictier. The<br>doctor’s observatory rose above the labyrinth like a great<br>isolated column, with a tiny house for a capital. Terrible<br>astrologies took place in that laboratory.</p>\n<p>There to-day is the Place Royale.</p>\n<p>As we have just said, the quarter of the palace, of which we have<br>just endeavored to give the reader some idea by indicating only<br>the chief points, filled the angle which Charles V.’s wall made<br>with the Seine on the east. The centre of the Town was occupied<br>by a pile of houses for the populace. It was there, in fact, that<br>the three bridges disgorged upon the right bank, and bridges lead<br>to the building of houses rather than palaces. That congregation<br>of <em>bourgeois</em> habitations, pressed together like the cells in a<br>hive, had a beauty of its own. It is with the roofs of a capital<br>as with the waves of the sea,—they are grand. First the streets,<br>crossed and entangled, forming a hundred amusing figures in the<br>block; around the market-place, it was like a star with a<br>thousand rays.</p>\n<p>The Rues Saint-Denis and Saint-Martin, with their innumerable<br>ramifications, rose one after the other, like trees intertwining<br>their branches; and then the tortuous lines, the Rues de la<br>Plâtrerie, de la Verrerie, de la Tixeranderie, etc., meandered<br>over all. There were also fine edifices which pierced the<br>petrified undulations of that sea of gables. At the head of the<br>Pont aux Changeurs, behind which one beheld the Seine foaming<br>beneath the wheels of the Pont aux Meuniers, there was the<br>Châlelet, no longer a Roman tower, as under Julian the Apostate,<br>but a feudal tower of the thirteenth century, and of a stone so<br>hard that the pickaxe could not break away so much as the<br>thickness of the fist in a space of three hours; there was the<br>rich square bell tower of Saint-Jacques de la Boucherie, with its<br>angles all frothing with carvings, already admirable, although it<br>was not finished in the fifteenth century. (It lacked, in<br>particular, the four monsters, which, still perched to-day on the<br>corners of its roof, have the air of so many sphinxes who are<br>propounding to new Paris the riddle of the ancient Paris. Rault,<br>the sculptor, only placed them in position in 1526, and received<br>twenty francs for his pains.) There was the Maison-aux-Piliers,<br>the Pillar House, opening upon that Place de Grève of which we<br>have given the reader some idea; there was Saint-Gervais, which a<br>front “in good taste” has since spoiled; Saint-Méry, whose<br>ancient pointed arches were still almost round arches;<br>Saint-Jean, whose magnificent spire was proverbial; there were<br>twenty other monuments, which did not disdain to bury their<br>wonders in that chaos of black, deep, narrow streets. Add the<br>crosses of carved stone, more lavishly scattered through the<br>squares than even the gibbets; the cemetery of the Innocents,<br>whose architectural wall could be seen in the distance above the<br>roofs; the pillory of the Markets, whose top was visible between<br>two chimneys of the Rue de la Cossonnerie; the ladder of the<br>Croix-du-Trahoir, in its square always black with people; the<br>circular buildings of the wheat mart; the fragments of Philip<br>Augustus’s ancient wall, which could be made out here and there,<br>drowned among the houses, its towers gnawed by ivy, its gates in<br>ruins, with crumbling and deformed stretches of wall; the quay<br>with its thousand shops, and its bloody knacker’s yards; the<br>Seine encumbered with boats, from the Port au Foin to<br>For-l’Évêque, and you will have a confused picture of what the<br>central trapezium of the Town was like in 1482.</p>\n<p>With these two quarters, one of hotels, the other of houses, the<br>third feature of aspect presented by the city was a long zone of<br>abbeys, which bordered it in nearly the whole of its<br>circumference, from the rising to the setting sun, and, behind<br>the circle of fortifications which hemmed in Paris, formed a<br>second interior enclosure of convents and chapels. Thus,<br>immediately adjoining the park des Tournelles, between the Rue<br>Saint-Antoine and the Vieille Rue du Temple, there stood<br>Sainte-Catherine, with its immense cultivated lands, which were<br>terminated only by the wall of Paris. Between the old and the new<br>Rue du Temple, there was the Temple, a sinister group of towers,<br>lofty, erect, and isolated in the middle of a vast, battlemented<br>enclosure. Between the Rue Neuve-du-Temple and the Rue<br>Saint-Martin, there was the Abbey of Saint-Martin, in the midst<br>of its gardens, a superb fortified church, whose girdle of<br>towers, whose diadem of bell towers, yielded in force and<br>splendor only to Saint-Germain des Prés. Between the Rue<br>Saint-Martin and the Rue Saint-Denis, spread the enclosure of the<br>Trinité.</p>\n<p>Lastly, between the Rue Saint-Denis, and the Rue Montorgueil,<br>stood the Filles-Dieu. On one side, the rotting roofs and unpaved<br>enclosure of the Cour des Miracles could be descried. It was the<br>sole profane ring which was linked to that devout chain of<br>convents.</p>\n<p>Finally, the fourth compartment, which stretched itself out in<br>the agglomeration of the roofs on the right bank, and which<br>occupied the western angle of the enclosure, and the banks of the<br>river down stream, was a fresh cluster of palaces and hôtels<br>pressed close about the base of the Louvre. The old Louvre of<br>Philip Augustus, that immense edifice whose great tower rallied<br>about it three and twenty chief towers, not to reckon the lesser<br>towers, seemed from a distance to be enshrined in the Gothic<br>roofs of the Hôtel d’Alençon, and the Petit-Bourbon. This hydra<br>of towers, giant guardian of Paris, with its four and twenty<br>heads, always erect, with its monstrous haunches, loaded or<br>scaled with slates, and all streaming with metallic reflections,<br>terminated with wonderful effect the configuration of the Town<br>towards the west.</p>\n<p>Thus an immense block, which the Romans called <em>insula</em>, or<br>island, of <em>bourgeois</em> houses, flanked on the right and the left<br>by two blocks of palaces, crowned, the one by the Louvre, the<br>other by the Tournelles, bordered on the north by a long girdle<br>of abbeys and cultivated enclosures, all amalgamated and melted<br>together in one view; upon these thousands of edifices, whose<br>tiled and slated roofs outlined upon each other so many fantastic<br>chains, the bell towers, tattooed, fluted, and ornamented with<br>twisted bands, of the four and forty churches on the right bank;<br>myriads of cross streets; for boundary on one side, an enclosure<br>of lofty walls with square towers (that of the University had<br>round towers); on the other, the Seine, cut by bridges, and<br>bearing on its bosom a multitude of boats; behold the Town of<br>Paris in the fifteenth century.</p>\n<p>Beyond the walls, several suburban villages pressed close about<br>the gates, but less numerous and more scattered than those of the<br>University. Behind the Bastille there were twenty hovels<br>clustered round the curious sculptures of the Croix-Faubin and<br>the flying buttresses of the Abbey of Saint-Antoine des Champs;<br>then Popincourt, lost amid wheat fields; then la Courtille, a<br>merry village of wine-shops; the hamlet of Saint-Laurent with its<br>church whose bell tower, from afar, seemed to add itself to the<br>pointed towers of the Porte Saint-Martin; the Faubourg<br>Saint-Denis, with the vast enclosure of Saint-Ladre; beyond the<br>Montmartre Gate, the Grange-Batelière, encircled with white<br>walls; behind it, with its chalky slopes, Montmartre, which had<br>then almost as many churches as windmills, and which has kept<br>only the windmills, for society no longer demands anything but<br>bread for the body. Lastly, beyond the Louvre, the Faubourg<br>Saint-Honoré, already considerable at that time, could be seen<br>stretching away into the fields, and Petit-Bretagne gleaming<br>green, and the Marché aux Pourceaux spreading abroad, in whose<br>centre swelled the horrible apparatus used for boiling<br>counterfeiters. Between la Courtille and Saint-Laurent, your eye<br>had already noticed, on the summit of an eminence crouching amid<br>desert plains, a sort of edifice which resembled from a distance<br>a ruined colonnade, mounted upon a basement with its foundation<br>laid bare. This was neither a Parthenon, nor a temple of the<br>Olympian Jupiter. It was Montfaucon.</p>\n<p>Now, if the enumeration of so many edifices, summary as we have<br>endeavored to make it, has not shattered in the reader’s mind the<br>general image of old Paris, as we have constructed it, we will<br>recapitulate it in a few words. In the centre, the island of the<br>City, resembling as to form an enormous tortoise, and throwing<br>out its bridges with tiles for scales; like legs from beneath its<br>gray shell of roofs. On the left, the monolithic trapezium, firm,<br>dense, bristling, of the University; on the right, the vast<br>semicircle of the Town, much more intermixed with gardens and<br>monuments. The three blocks, city, university, and town, marbled<br>with innumerable streets. Across all, the Seine, “foster-mother<br>Seine,” as says Father Du Breul, blocked with islands, bridges,<br>and boats. All about an immense plain, patched with a thousand<br>sorts of cultivated plots, sown with fine villages. On the left,<br>Issy, Vanvres, Vaugirarde, Montrouge, Gentilly, with its round<br>tower and its square tower, etc.; on the right, twenty others,<br>from Conflans to Ville-l’Évêque. On the horizon, a border of<br>hills arranged in a circle like the rim of the basin. Finally,<br>far away to the east, Vincennes, and its seven quadrangular<br>towers to the south, Bicêtre and its pointed turrets; to the<br>north, Saint-Denis and its spire; to the west, Saint Cloud and<br>its donjon keep. Such was the Paris which the ravens, who lived<br>in 1482, beheld from the summits of the towers of Notre-Dame.</p>\n<p>Nevertheless, Voltaire said of this city, that “before Louis<br>XIV., it possessed but four fine monuments”: the dome of the<br>Sorbonne, the Val-de-Grâce, the modern Louvre, and I know not<br>what the fourth was—the Luxembourg, perhaps. Fortunately,<br>Voltaire was the author of “Candide” in spite of this, and in<br>spite of this, he is, among all the men who have followed each<br>other in the long series of humanity, the one who has best<br>possessed the diabolical laugh. Moreover, this proves that one<br>can be a fine genius, and yet understand nothing of an art to<br>which one does not belong. Did not Molière imagine that he was<br>doing Raphael and Michael-Angelo a very great honor, by calling<br>them “those Mignards of their age?”</p>\n<p>Let us return to Paris and to the fifteenth century.</p>\n<p>It was not then merely a handsome city; it was a homogeneous<br>city, an architectural and historical product of the Middle Ages,<br>a chronicle in stone. It was a city formed of two layers only;<br>the Romanesque layer and the Gothic layer; for the Roman layer<br>had disappeared long before, with the exception of the Hot Baths<br>of Julian, where it still pierced through the thick crust of the<br>Middle Ages. As for the Celtic layer, no specimens were any<br>longer to be found, even when sinking wells.</p>\n<p>Fifty years later, when the Renaissance began to mingle with this<br>unity which was so severe and yet so varied, the dazzling luxury<br>of its fantasies and systems, its debasements of Roman round<br>arches, Greek columns, and Gothic bases, its sculpture which was<br>so tender and so ideal, its peculiar taste for arabesques and<br>acanthus leaves, its architectural paganism, contemporary with<br>Luther, Paris, was perhaps, still more beautiful, although less<br>harmonious to the eye, and to the thought.</p>\n<p>But this splendid moment lasted only for a short time; the<br>Renaissance was not impartial; it did not content itself with<br>building, it wished to destroy; it is true that it required the<br>room. Thus Gothic Paris was complete only for a moment.<br>Saint-Jacques de la Boucherie had barely been completed when the<br>demolition of the old Louvre was begun.</p>\n<p>After that, the great city became more disfigured every day.<br>Gothic Paris, beneath which Roman Paris was effaced, was effaced<br>in its turn; but can any one say what Paris has replaced it?</p>\n<p>There is the Paris of Catherine de Medicis at the<br>Tuileries;[23]—the Paris of Henri II., at the Hôtel de Ville, two<br>edifices still in fine taste;—the Paris of Henri IV., at the<br>Place Royale: façades of brick with stone corners, and slated<br>roofs, tri-colored houses;—the Paris of Louis XIII., at the<br>Val-de-Grâce: a crushed and squat architecture, with vaults like<br>basket-handles, and something indescribably pot-bellied in the<br>column, and thickset in the dome;—the Paris of Louis XIV., in the<br>Invalides: grand, rich, gilded, cold;—the Paris of Louis XV., in<br>Saint-Sulpice: volutes, knots of ribbon, clouds, vermicelli and<br>chiccory leaves, all in stone;—the Paris of Louis XVI., in the<br>Pantheon: Saint Peter of Rome, badly copied (the edifice is<br>awkwardly heaped together, which has not amended its lines);—the<br>Paris of the Republic, in the School of Medicine: a poor Greek<br>and Roman taste, which resembles the Coliseum or the Parthenon as<br>the constitution of the year III., resembles the laws of<br>Minos,—it is called in architecture, “the Messidor”[24]<br>taste;—the Paris of Napoleon in the Place Vendôme: this one is<br>sublime, a column of bronze made of cannons;—the Paris of the<br>Restoration, at the Bourse: a very white colonnade supporting a<br>very smooth frieze; the whole is square and cost twenty millions.</p>\n<p>To each of these characteristic monuments there is attached by a<br>similarity of taste, fashion, and attitude, a certain number of<br>houses scattered about in different quarters and which the eyes<br>of the connoisseur easily distinguishes and furnishes with a<br>date. When one knows how to look, one finds the spirit of a<br>century, and the physiognomy of a king, even in the knocker on a<br>door.</p>\n<p>The Paris of the present day has then, no general physiognomy. It<br>is a collection of specimens of many centuries, and the finest<br>have disappeared. The capital grows only in houses, and what<br>houses! At the rate at which Paris is now proceeding, it will<br>renew itself every fifty years.</p>\n<p>Thus the historical significance of its architecture is being<br>effaced every day. Monuments are becoming rarer and rarer, and<br>one seems to see them gradually engulfed, by the flood of houses.<br>Our fathers had a Paris of stone; our sons will have one of<br>plaster.</p>\n<p>So far as the modern monuments of new Paris are concerned, we<br>would gladly be excused from mentioning them. It is not that we<br>do not admire them as they deserve. The Sainte-Geneviève of M.<br>Soufflot is certainly the finest Savoy cake that has ever been<br>made in stone. The Palace of the Legion of Honor is also a very<br>distinguished bit of pastry. The dome of the wheat market is an<br>English jockey cap, on a grand scale. The towers of Saint-Sulpice<br>are two huge clarinets, and the form is as good as any other; the<br>telegraph, contorted and grimacing, forms an admirable accident<br>upon their roofs. Saint-Roch has a door which, for magnificence,<br>is comparable only to that of Saint-Thomas d’Aquin. It has, also,<br>a crucifixion in high relief, in a cellar, with a sun of gilded<br>wood. These things are fairly marvellous. The lantern of the<br>labyrinth of the Jardin des Plantes is also very ingenious.</p>\n<p>As for the Palace of the Bourse, which is Greek as to its<br>colonnade, Roman in the round arches of its doors and windows, of<br>the Renaissance by virtue of its flattened vault, it is<br>indubitably a very correct and very pure monument; the proof is<br>that it is crowned with an attic, such as was never seen in<br>Athens, a beautiful, straight line, gracefully broken here and<br>there by stovepipes. Let us add that if it is according to rule<br>that the architecture of a building should be adapted to its<br>purpose in such a manner that this purpose shall be immediately<br>apparent from the mere aspect of the building, one cannot be too<br>much amazed at a structure which might be indifferently—the<br>palace of a king, a chamber of communes, a town-hall, a college,<br>a riding-school, an academy, a warehouse, a court-house, a<br>museum, a barracks, a sepulchre, a temple, or a theatre. However,<br>it is an Exchange. An edifice ought to be, moreover, suitable to<br>the climate. This one is evidently constructed expressly for our<br>cold and rainy skies. It has a roof almost as flat as roofs in<br>the East, which involves sweeping the roof in winter, when it<br>snows; and of course roofs are made to be swept. As for its<br>purpose, of which we just spoke, it fulfils it to a marvel; it is<br>a bourse in France as it would have been a temple in Greece. It<br>is true that the architect was at a good deal of trouble to<br>conceal the clock face, which would have destroyed the purity of<br>the fine lines of the façade; but, on the other hand, we have<br>that colonnade which circles round the edifice and under which,<br>on days of high religious ceremony, the theories of the<br>stock-brokers and the courtiers of commerce can be developed so<br>majestically.</p>\n<p>These are very superb structures. Let us add a quantity of fine,<br>amusing, and varied streets, like the Rue de Rivoli, and I do not<br>despair of Paris presenting to the eye, when viewed from a<br>balloon, that richness of line, that opulence of detail, that<br>diversity of aspect, that grandiose something in the simple, and<br>unexpected in the beautiful, which characterizes a checker-board.</p>\n<p>However, admirable as the Paris of to-day may seem to you,<br>reconstruct the Paris of the fifteenth century, call it up before<br>you in thought; look at the sky athwart that surprising forest of<br>spires, towers, and belfries; spread out in the centre of the<br>city, tear away at the point of the islands, fold at the arches<br>of the bridges, the Seine, with its broad green and yellow<br>expanses, more variable than the skin of a serpent; project<br>clearly against an azure horizon the Gothic profile of this<br>ancient Paris. Make its contour float in a winter’s mist which<br>clings to its numerous chimneys; drown it in profound night and<br>watch the odd play of lights and shadows in that sombre labyrinth<br>of edifices; cast upon it a ray of light which shall vaguely<br>outline it and cause to emerge from the fog the great heads of<br>the towers; or take that black silhouette again, enliven with<br>shadow the thousand acute angles of the spires and gables, and<br>make it start out more toothed than a shark’s jaw against a<br>copper-colored western sky,—and then compare.</p>\n<p>And if you wish to receive of the ancient city an impression with<br>which the modern one can no longer furnish you, climb—on the<br>morning of some grand festival, beneath the rising sun of Easter<br>or of Pentecost—climb upon some elevated point, whence you<br>command the entire capital; and be present at the wakening of the<br>chimes. Behold, at a signal given from heaven, for it is the sun<br>which gives it, all those churches quiver simultaneously. First<br>come scattered strokes, running from one church to another, as<br>when musicians give warning that they are about to begin. Then,<br>all at once, behold!—for it seems at times, as though the ear<br>also possessed a sight of its own,—behold, rising from each bell<br>tower, something like a column of sound, a cloud of harmony.<br>First, the vibration of each bell mounts straight upwards, pure<br>and, so to speak, isolated from the others, into the splendid<br>morning sky; then, little by little, as they swell they melt<br>together, mingle, are lost in each other, and amalgamate in a<br>magnificent concert. It is no longer anything but a mass of<br>sonorous vibrations incessantly sent forth from the numerous<br>belfries; floats, undulates, bounds, whirls over the city, and<br>prolongs far beyond the horizon the deafening circle of its<br>oscillations.</p>\n<p>Nevertheless, this sea of harmony is not a chaos; great and<br>profound as it is, it has not lost its transparency; you behold<br>the windings of each group of notes which escapes from the<br>belfries. You can follow the dialogue, by turns grave and shrill,<br>of the treble and the bass; you can see the octaves leap from one<br>tower to another; you watch them spring forth, winged, light, and<br>whistling, from the silver bell, to fall, broken and limping from<br>the bell of wood; you admire in their midst the rich gamut which<br>incessantly ascends and re-ascends the seven bells of<br>Saint-Eustache; you see light and rapid notes running across it,<br>executing three or four luminous zigzags, and vanishing like<br>flashes of lightning. Yonder is the Abbey of Saint-Martin, a<br>shrill, cracked singer; here the gruff and gloomy voice of the<br>Bastille; at the other end, the great tower of the Louvre, with<br>its bass. The royal chime of the palace scatters on all sides,<br>and without relaxation, resplendent trills, upon which fall, at<br>regular intervals, the heavy strokes from the belfry of<br>Notre-Dame, which makes them sparkle like the anvil under the<br>hammer. At intervals you behold the passage of sounds of all<br>forms which come from the triple peal of Saint-Germain-des-Prés.<br>Then, again, from time to time, this mass of sublime noises opens<br>and gives passage to the beats of the Ave Maria, which bursts<br>forth and sparkles like an aigrette of stars. Below, in the very<br>depths of the concert, you confusedly distinguish the interior<br>chanting of the churches, which exhales through the vibrating<br>pores of their vaulted roofs.</p>\n<p>Assuredly, this is an opera which it is worth the trouble of<br>listening to. Ordinarily, the noise which escapes from Paris by<br>day is the city speaking; by night, it is the city breathing; in<br>this case, it is the city singing. Lend an ear, then, to this<br>concert of bell towers; spread over all the murmur of half a<br>million men, the eternal plaint of the river, the infinite<br>breathings of the wind, the grave and distant quartette of the<br>four forests arranged upon the hills, on the horizon, like<br>immense stacks of organ pipes; extinguish, as in a half shade,<br>all that is too hoarse and too shrill about the central chime,<br>and say whether you know anything in the world more rich and<br>joyful, more golden, more dazzling, than this tumult of bells and<br>chimes;—than this furnace of music,—than these ten thousand<br>brazen voices chanting simultaneously in the flutes of stone,<br>three hundred feet high,—than this city which is no longer<br>anything but an orchestra,—than this symphony which produces the<br>noise of a tempest.</p>\n<p>BOOK FOURTH.</p>\n<h1 class=\"chapter\" id=\"chapter-i-good-souls\">Chapter I. GOOD SOULS.</h1>\n<p>Sixteen years previous to the epoch when this story takes place,<br>one fine morning, on Quasimodo Sunday, a living creature had been<br>deposited, after mass, in the church of Notre-Dame, on the wooden<br>bed securely fixed in the vestibule on the left, opposite that<br>great image of Saint Christopher, which the figure of Messire<br>Antoine des Essarts, chevalier, carved in stone, had been gazing<br>at on his knees since 1413, when they took it into their heads to<br>overthrow the saint and the faithful follower. Upon this bed of<br>wood it was customary to expose foundlings for public charity.<br>Whoever cared to take them did so. In front of the wooden bed was<br>a copper basin for alms.</p>\n<p>The sort of living being which lay upon that plank on the morning<br>of Quasimodo, in the year of the Lord, 1467, appeared to excite<br>to a high degree, the curiosity of the numerous group which had<br>congregated about the wooden bed. The group was formed for the<br>most part of the fair sex. Hardly any one was there except old<br>women.</p>\n<p>In the first row, and among those who were most bent over the<br>bed, four were noticeable, who, from their gray <em>cagoule</em>, a sort<br>of cassock, were recognizable as attached to some devout<br>sisterhood. I do not see why history has not transmitted to<br>posterity the names of these four discreet and venerable damsels.<br>They were Agnès la Herme, Jehanne de la Tarme, Henriette la<br>Gaultière, Gauchère la Violette, all four widows, all four dames<br>of the Chapel Étienne Haudry, who had quitted their house with<br>the permission of their mistress, and in conformity with the<br>statutes of Pierre d’Ailly, in order to come and hear the sermon.</p>\n<p>However, if these good Haudriettes were, for the moment,<br>complying with the statutes of Pierre d’Ailly, they certainly<br>violated with joy those of Michel de Brache, and the Cardinal of<br>Pisa, which so inhumanly enjoined silence upon them.</p>\n<p>“What is this, sister?” said Agnès to Gauchère, gazing at the<br>little creature exposed, which was screaming and writhing on the<br>wooden bed, terrified by so many glances.</p>\n<p>“What is to become of us,” said Jehanne, “if that is the way<br>children are made now?”</p>\n<p>“I’m not learned in the matter of children,” resumed Agnès, “but<br>it must be a sin to look at this one.”</p>\n<p>“’Tis not a child, Agnès.”</p>\n<p>“’Tis an abortion of a monkey,” remarked Gauchère.</p>\n<p>“’Tis a miracle,” interposed Henriette la Gaultière.</p>\n<p>“Then,” remarked Agnès, “it is the third since the Sunday of the<br><em>Lætare</em>: for, in less than a week, we had the miracle of the<br>mocker of pilgrims divinely punished by Notre-Dame<br>d’Aubervilliers, and that was the second miracle within a month.”</p>\n<p>“This pretended foundling is a real monster of abomination,”<br>resumed Jehanne.</p>\n<p>“He yells loud enough to deafen a chanter,” continued Gauchère.<br>“Hold your tongue, you little howler!”</p>\n<p>“To think that Monsieur of Reims sent this enormity to Monsieur<br>of Paris,” added la Gaultière, clasping her hands.</p>\n<p>“I imagine,” said Agnès la Herme, “that it is a beast, an<br>animal,—the fruit of a Jew and a sow; something not Christian, in<br>short, which ought to be thrown into the fire or into the water.”</p>\n<p>“I really hope,” resumed la Gaultière, “that nobody will apply<br>for it.”</p>\n<p>“Ah, good heavens!” exclaimed Agnès; “those poor nurses yonder in<br>the foundling asylum, which forms the lower end of the lane as<br>you go to the river, just beside Monseigneur the bishop! what if<br>this little monster were to be carried to them to suckle? I’d<br>rather give suck to a vampire.”</p>\n<p>“How innocent that poor la Herme is!” resumed Jehanne; “don’t you<br>see, sister, that this little monster is at least four years old,<br>and that he would have less appetite for your breast than for a<br>turnspit.”</p>\n<p>The “little monster” we should find it difficult ourselves to<br>describe him otherwise, was, in fact, not a new-born child. It<br>was a very angular and very lively little mass, imprisoned in its<br>linen sack, stamped with the cipher of Messire Guillaume<br>Chartier, then bishop of Paris, with a head projecting. That head<br>was deformed enough; one beheld only a forest of red hair, one<br>eye, a mouth, and teeth. The eye wept, the mouth cried, and the<br>teeth seemed to ask only to be allowed to bite. The whole<br>struggled in the sack, to the great consternation of the crowd,<br>which increased and was renewed incessantly around it.</p>\n<p>Dame Aloïse de Gondelaurier, a rich and noble woman, who held by<br>the hand a pretty girl about five or six years of age, and<br>dragged a long veil about, suspended to the golden horn of her<br>headdress, halted as she passed the wooden bed, and gazed for a<br>moment at the wretched creature, while her charming little<br>daughter, Fleur-de-Lys de Gondelaurier, spelled out with her<br>tiny, pretty finger, the permanent inscription attached to the<br>wooden bed: “Foundlings.”</p>\n<p>“Really,” said the dame, turning away in disgust, “I thought that<br>they only exposed children here.”</p>\n<p>She turned her back, throwing into the basin a silver florin,<br>which rang among the liards, and made the poor goodwives of the<br>chapel of Étienne Haudry open their eyes.</p>\n<p>A moment later, the grave and learned Robert Mistricolle, the<br>king’s protonotary, passed, with an enormous missal under one arm<br>and his wife on the other (Damoiselle Guillemette la Mairesse),<br>having thus by his side his two regulators,—spiritual and<br>temporal.</p>\n<p>“Foundling!” he said, after examining the object; “found,<br>apparently, on the banks of the river Phlegethon.”</p>\n<p>“One can only see one eye,” observed Damoiselle Guillemette;<br>“there is a wart on the other.”</p>\n<p>“It’s not a wart,” returned Master Robert Mistricolle, “it is an<br>egg which contains another demon exactly similar, who bears<br>another little egg which contains another devil, and so on.”</p>\n<p>“How do you know that?” asked Guillemette la Mairesse.</p>\n<p>“I know it pertinently,” replied the protonotary.</p>\n<p>“Monsieur le protonotare,” asked Gauchère, “what do you<br>prognosticate of this pretended foundling?”</p>\n<p>“The greatest misfortunes,” replied Mistricolle.</p>\n<p>“Ah! good heavens!” said an old woman among the spectators, “and<br>that besides our having had a considerable pestilence last year,<br>and that they say that the English are going to disembark in a<br>company at Harfleur.”</p>\n<p>“Perhaps that will prevent the queen from coming to Paris in the<br>month of September,” interposed another; “trade is so bad<br>already.”</p>\n<p>“My opinion is,” exclaimed Jehanne de la Tarme, “that it would be<br>better for the louts of Paris, if this little magician were put<br>to bed on a fagot than on a plank.”</p>\n<p>“A fine, flaming fagot,” added the old woman.</p>\n<p>“It would be more prudent,” said Mistricolle.</p>\n<p>For several minutes, a young priest had been listening to the<br>reasoning of the Haudriettes and the sentences of the notary. He<br>had a severe face, with a large brow, a profound glance. He<br>thrust the crowd silently aside, scrutinized the “little<br>magician,” and stretched out his hand upon him. It was high time,<br>for all the devotees were already licking their chops over the<br>“fine, flaming fagot.”</p>\n<p>“I adopt this child,” said the priest.</p>\n<p>He took it in his cassock and carried it off. The spectators<br>followed him with frightened glances. A moment later, he had<br>disappeared through the “Red Door,” which then led from the<br>church to the cloister.</p>\n<p>When the first surprise was over, Jehanne de la Tarme bent down<br>to the ear of la Gaultière,—</p>\n<p>“I told you so, sister,—that young clerk, Monsieur Claude Frollo,<br>is a sorcerer.”</p>\n<h1 class=\"chapter\" id=\"chapter-ii-claude-frollo\">Chapter II. CLAUDE FROLLO.</h1>\n<p>In fact, Claude Frollo was no common person.</p>\n<p>He belonged to one of those middle-class families which were<br>called indifferently, in the impertinent language of the last<br>century, the high <em>bourgeoise</em> or the petty nobility. This family<br>had inherited from the brothers Paclet the fief of Tirechappe,<br>which was dependent upon the Bishop of Paris, and whose<br>twenty-one houses had been in the thirteenth century the object<br>of so many suits before the official. As possessor of this fief,<br>Claude Frollo was one of the twenty-seven seigneurs keeping claim<br>to a manor in fee in Paris and its suburbs; and for a long time,<br>his name was to be seen inscribed in this quality, between the<br>Hôtel de Tancarville, belonging to Master François Le Rez, and<br>the college of Tours, in the records deposited at Saint Martin<br>des Champs.</p>\n<p>Claude Frollo had been destined from infancy, by his parents, to<br>the ecclesiastical profession. He had been taught to read in<br>Latin; he had been trained to keep his eyes on the ground and to<br>speak low. While still a child, his father had cloistered him in<br>the college of Torchi in the University. There it was that he had<br>grown up, on the missal and the lexicon.</p>\n<p>Moreover, he was a sad, grave, serious child, who studied<br>ardently, and learned quickly; he never uttered a loud cry in<br>recreation hour, mixed but little in the bacchanals of the Rue du<br>Fouarre, did not know what it was to _dare alapas et capillos<br>laniare_, and had cut no figure in that revolt of 1463, which the<br>annalists register gravely, under the title of “The sixth trouble<br>of the University.” He seldom rallied the poor students of<br>Montaigu on the <em>cappettes</em> from which they derived their name,<br>or the bursars of the college of Dormans on their shaved tonsure,<br>and their surtout parti-colored of bluish-green, blue, and violet<br>cloth, <em>azurini coloris et bruni</em>, as says the charter of the<br>Cardinal des Quatre-Couronnes.</p>\n<p>On the other hand, he was assiduous at the great and the small<br>schools of the Rue Saint Jean de Beauvais. The first pupil whom<br>the Abbé de Saint Pierre de Val, at the moment of beginning his<br>reading on canon law, always perceived, glued to a pillar of the<br>school Saint-Vendregesile, opposite his rostrum, was Claude<br>Frollo, armed with his horn ink-bottle, biting his pen,<br>scribbling on his threadbare knee, and, in winter, blowing on his<br>fingers. The first auditor whom Messire Miles d’Isliers, doctor<br>in decretals, saw arrive every Monday morning, all breathless, at<br>the opening of the gates of the school of the Chef-Saint-Denis,<br>was Claude Frollo. Thus, at sixteen years of age, the young clerk<br>might have held his own, in mystical theology, against a father<br>of the church; in canonical theology, against a father of the<br>councils; in scholastic theology, against a doctor of Sorbonne.</p>\n<p>Theology conquered, he had plunged into decretals. From the<br>“Master of Sentences,” he had passed to the “Capitularies of<br>Charlemagne;” and he had devoured in succession, in his appetite<br>for science, decretals upon decretals, those of Theodore, Bishop<br>of Hispalus; those of Bouchard, Bishop of Worms; those of Yves,<br>Bishop of Chartres; next the decretal of Gratian, which succeeded<br>the capitularies of Charlemagne; then the collection of Gregory<br>IX.; then the Epistle of <em>Superspecula</em>, of Honorius III. He<br>rendered clear and familiar to himself that vast and tumultuous<br>period of civil law and canon law in conflict and at strife with<br>each other, in the chaos of the Middle Ages,—a period which<br>Bishop Theodore opens in 618, and which Pope Gregory closes in<br>1227.</p>\n<p>Decretals digested, he flung himself upon medicine, on the<br>liberal arts. He studied the science of herbs, the science of<br>unguents; he became an expert in fevers and in contusions, in<br>sprains and abcesses. Jacques d’ Espars would have received him<br>as a physician; Richard Hellain, as a surgeon. He also passed<br>through all the degrees of licentiate, master, and doctor of<br>arts. He studied the languages, Latin, Greek, Hebrew, a triple<br>sanctuary then very little frequented. His was a veritable fever<br>for acquiring and hoarding, in the matter of science. At the age<br>of eighteen, he had made his way through the four faculties; it<br>seemed to the young man that life had but one sole object:<br>learning.</p>\n<p>It was towards this epoch, that the excessive heat of the summer<br>of 1466 caused that grand outburst of the plague which carried<br>off more than forty thousand souls in the vicomty of Paris, and<br>among others, as Jean de Troyes states, “Master Arnoul,<br>astrologer to the king, who was a very fine man, both wise and<br>pleasant.” The rumor spread in the University that the Rue<br>Tirechappe was especially devastated by the malady. It was there<br>that Claude’s parents resided, in the midst of their fief. The<br>young scholar rushed in great alarm to the paternal mansion. When<br>he entered it, he found that both father and mother had died on<br>the preceding day. A very young brother of his, who was in<br>swaddling clothes, was still alive and crying abandoned in his<br>cradle. This was all that remained to Claude of his family; the<br>young man took the child under his arm and went off in a pensive<br>mood. Up to that moment, he had lived only in science; he now<br>began to live in life.</p>\n<p>This catastrophe was a crisis in Claude’s existence. Orphaned,<br>the eldest, head of the family at the age of nineteen, he felt<br>himself rudely recalled from the reveries of school to the<br>realities of this world. Then, moved with pity, he was seized<br>with passion and devotion towards that child, his brother; a<br>sweet and strange thing was a human affection to him, who had<br>hitherto loved his books alone.</p>\n<p>This affection developed to a singular point; in a soul so new,<br>it was like a first love. Separated since infancy from his<br>parents, whom he had hardly known; cloistered and immured, as it<br>were, in his books; eager above all things to study and to learn;<br>exclusively attentive up to that time, to his intelligence which<br>broadened in science, to his imagination, which expanded in<br>letters,—the poor scholar had not yet had time to feel the place<br>of his heart.</p>\n<p>This young brother, without mother or father, this little child<br>which had fallen abruptly from heaven into his arms, made a new<br>man of him. He perceived that there was something else in the<br>world besides the speculations of the Sorbonne, and the verses of<br>Homer; that man needed affections; that life without tenderness<br>and without love was only a set of dry, shrieking, and rending<br>wheels. Only, he imagined, for he was at the age when illusions<br>are as yet replaced only by illusions, that the affections of<br>blood and family were the sole ones necessary, and that a little<br>brother to love sufficed to fill an entire existence.</p>\n<p>He threw himself, therefore, into the love for his little Jehan<br>with the passion of a character already profound, ardent,<br>concentrated; that poor frail creature, pretty, fair-haired,<br>rosy, and curly,—that orphan with another orphan for his only<br>support, touched him to the bottom of his heart; and grave<br>thinker as he was, he set to meditating upon Jehan with an<br>infinite compassion. He kept watch and ward over him as over<br>something very fragile, and very worthy of care. He was more than<br>a brother to the child; he became a mother to him.</p>\n<p>Little Jehan had lost his mother while he was still at the<br>breast; Claude gave him to a nurse. Besides the fief of<br>Tirechappe, he had inherited from his father the fief of Moulin,<br>which was a dependency of the square tower of Gentilly; it was a<br>mill on a hill, near the château of Winchestre (Bicêtre). There<br>was a miller’s wife there who was nursing a fine child; it was<br>not far from the university, and Claude carried the little Jehan<br>to her in his own arms.</p>\n<p>From that time forth, feeling that he had a burden to bear, he<br>took life very seriously. The thought of his little brother<br>became not only his recreation, but the object of his studies. He<br>resolved to consecrate himself entirely to a future for which he<br>was responsible in the sight of God, and never to have any other<br>wife, any other child than the happiness and fortune of his<br>brother. Therefore, he attached himself more closely than ever to<br>the clerical profession. His merits, his learning, his quality of<br>immediate vassal of the Bishop of Paris, threw the doors of the<br>church wide open to him. At the age of twenty, by special<br>dispensation of the Holy See, he was a priest, and served as the<br>youngest of the chaplains of Notre-Dame the altar which is<br>called, because of the late mass which is said there, _altare<br>pigrorum_.</p>\n<p>There, plunged more deeply than ever in his dear books, which he<br>quitted only to run for an hour to the fief of Moulin, this<br>mixture of learning and austerity, so rare at his age, had<br>promptly acquired for him the respect and admiration of the<br>monastery. From the cloister, his reputation as a learned man had<br>passed to the people, among whom it had changed a little, a<br>frequent occurrence at that time, into reputation as a sorcerer.</p>\n<p>It was at the moment when he was returning, on Quasimodo day,<br>from saying his mass at the Altar of the Lazy, which was by the<br>side of the door leading to the nave on the right, near the image<br>of the Virgin, that his attention had been attracted by the group<br>of old women chattering around the bed for foundlings.</p>\n<p>Then it was that he approached the unhappy little creature, which<br>was so hated and so menaced. That distress, that deformity, that<br>abandonment, the thought of his young brother, the idea which<br>suddenly occurred to him, that if he were to die, his dear little<br>Jehan might also be flung miserably on the plank for<br>foundlings,—all this had gone to his heart simultaneously; a<br>great pity had moved in him, and he had carried off the child.</p>\n<p>When he removed the child from the sack, he found it greatly<br>deformed, in very sooth. The poor little wretch had a wart on his<br>left eye, his head placed directly on his shoulders, his spinal<br>column was crooked, his breast bone prominent, and his legs<br>bowed; but he appeared to be lively; and although it was<br>impossible to say in what language he lisped, his cry indicated<br>considerable force and health. Claude’s compassion increased at<br>the sight of this ugliness; and he made a vow in his heart to<br>rear the child for the love of his brother, in order that,<br>whatever might be the future faults of the little Jehan, he<br>should have beside him that charity done for his sake. It was a<br>sort of investment of good works, which he was effecting in the<br>name of his young brother; it was a stock of good works which he<br>wished to amass in advance for him, in case the little rogue<br>should some day find himself short of that coin, the only sort<br>which is received at the toll-bar of paradise.</p>\n<p>He baptized his adopted child, and gave him the name of<br>Quasimodo, either because he desired thereby to mark the day,<br>when he had found him, or because he wished to designate by that<br>name to what a degree the poor little creature was incomplete,<br>and hardly sketched out. In fact, Quasimodo, blind, hunchbacked,<br>knock-kneed, was only an “almost.”</p>\n<h1 class=\"chapter\" id=\"chapter-iii-immanis-pecoris-custos-immanior-ipse\">Chapter III. _IMMANIS PECORIS CUSTOS, IMMANIOR IPSE_.</h1>\n<p>Now, in 1482, Quasimodo had grown up. He had become a few years<br>previously the bellringer of Notre-Dame, thanks to his father by<br>adoption, Claude Frollo,—who had become archdeacon of Josas,<br>thanks to his suzerain, Messire Louis de Beaumont,—who had become<br>Bishop of Paris, at the death of Guillaume Chartier in 1472,<br>thanks to his patron, Olivier Le Daim, barber to Louis XI., king<br>by the grace of God.</p>\n<p>So Quasimodo was the ringer of the chimes of Notre-Dame.</p>\n<p>In the course of time there had been formed a certain peculiarly<br>intimate bond which united the ringer to the church. Separated<br>forever from the world, by the double fatality of his unknown<br>birth and his natural deformity, imprisoned from his infancy in<br>that impassable double circle, the poor wretch had grown used to<br>seeing nothing in this world beyond the religious walls which had<br>received him under their shadow. Notre-Dame had been to him<br>successively, as he grew up and developed, the egg, the nest, the<br>house, the country, the universe.</p>\n<p>There was certainly a sort of mysterious and pre-existing harmony<br>between this creature and this church. When, still a little<br>fellow, he had dragged himself tortuously and by jerks beneath<br>the shadows of its vaults, he seemed, with his human face and his<br>bestial limbs, the natural reptile of that humid and sombre<br>pavement, upon which the shadow of the Romanesque capitals cast<br>so many strange forms.</p>\n<p>Later on, the first time that he caught hold, mechanically, of<br>the ropes to the towers, and hung suspended from them, and set<br>the bell to clanging, it produced upon his adopted father,<br>Claude, the effect of a child whose tongue is unloosed and who<br>begins to speak.</p>\n<p>It is thus that, little by little, developing always in sympathy<br>with the cathedral, living there, sleeping there, hardly ever<br>leaving it, subject every hour to the mysterious impress, he came<br>to resemble it, he incrusted himself in it, so to speak, and<br>became an integral part of it. His salient angles fitted into the<br>retreating angles of the cathedral (if we may be allowed this<br>figure of speech), and he seemed not only its inhabitant but more<br>than that, its natural tenant. One might almost say that he had<br>assumed its form, as the snail takes on the form of its shell. It<br>was his dwelling, his hole, his envelope. There existed between<br>him and the old church so profound an instinctive sympathy, so<br>many magnetic affinities, so many material affinities, that he<br>adhered to it somewhat as a tortoise adheres to its shell. The<br>rough and wrinkled cathedral was his shell.</p>\n<p>It is useless to warn the reader not to take literally all the<br>similes which we are obliged to employ here to express the<br>singular, symmetrical, direct, almost consubstantial union of a<br>man and an edifice. It is equally unnecessary to state to what a<br>degree that whole cathedral was familiar to him, after so long<br>and so intimate a cohabitation. That dwelling was peculiar to<br>him. It had no depths to which Quasimodo had not penetrated, no<br>height which he had not scaled. He often climbed many stones up<br>the front, aided solely by the uneven points of the carving. The<br>towers, on whose exterior surface he was frequently seen<br>clambering, like a lizard gliding along a perpendicular wall,<br>those two gigantic twins, so lofty, so menacing, so formidable,<br>possessed for him neither vertigo, nor terror, nor shocks of<br>amazement.</p>\n<p>To see them so gentle under his hand, so easy to scale, one would<br>have said that he had tamed them. By dint of leaping, climbing,<br>gambolling amid the abysses of the gigantic cathedral he had<br>become, in some sort, a monkey and a goat, like the Calabrian<br>child who swims before he walks, and plays with the sea while<br>still a babe.</p>\n<p>Moreover, it was not his body alone which seemed fashioned after<br>the Cathedral, but his mind also. In what condition was that<br>mind? What bent had it contracted, what form had it assumed<br>beneath that knotted envelope, in that savage life? This it would<br>be hard to determine. Quasimodo had been born one-eyed,<br>hunchbacked, lame. It was with great difficulty, and by dint of<br>great patience that Claude Frollo had succeeded in teaching him<br>to talk. But a fatality was attached to the poor foundling.<br>Bellringer of Notre-Dame at the age of fourteen, a new infirmity<br>had come to complete his misfortunes: the bells had broken the<br>drums of his ears; he had become deaf. The only gate which nature<br>had left wide open for him had been abruptly closed, and forever.</p>\n<p>In closing, it had cut off the only ray of joy and of light which<br>still made its way into the soul of Quasimodo. His soul fell into<br>profound night. The wretched being’s misery became as incurable<br>and as complete as his deformity. Let us add that his deafness<br>rendered him to some extent dumb. For, in order not to make<br>others laugh, the very moment that he found himself to be deaf,<br>he resolved upon a silence which he only broke when he was alone.<br>He voluntarily tied that tongue which Claude Frollo had taken so<br>much pains to unloose. Hence, it came about, that when necessity<br>constrained him to speak, his tongue was torpid, awkward, and<br>like a door whose hinges have grown rusty.</p>\n<p>If now we were to try to penetrate to the soul of Quasimodo<br>through that thick, hard rind; if we could sound the depths of<br>that badly constructed organism; if it were granted to us to look<br>with a torch behind those non-transparent organs to explore the<br>shadowy interior of that opaque creature, to elucidate his<br>obscure corners, his absurd no-thoroughfares, and suddenly to<br>cast a vivid light upon the soul enchained at the extremity of<br>that cave, we should, no doubt, find the unhappy Psyche in some<br>poor, cramped, and ricketty attitude, like those prisoners<br>beneath the Leads of Venice, who grew old bent double in a stone<br>box which was both too low and too short for them.</p>\n<p>It is certain that the mind becomes atrophied in a defective<br>body. Quasimodo was barely conscious of a soul cast in his own<br>image, moving blindly within him. The impressions of objects<br>underwent a considerable refraction before reaching his mind. His<br>brain was a peculiar medium; the ideas which passed through it<br>issued forth completely distorted. The reflection which resulted<br>from this refraction was, necessarily, divergent and perverted.</p>\n<p>Hence a thousand optical illusions, a thousand aberrations of<br>judgment, a thousand deviations, in which his thought strayed,<br>now mad, now idiotic.</p>\n<p>The first effect of this fatal organization was to trouble the<br>glance which he cast upon things. He received hardly any<br>immediate perception of them. The external world seemed much<br>farther away to him than it does to us.</p>\n<p>The second effect of his misfortune was to render him malicious.</p>\n<p>He was malicious, in fact, because he was savage; he was savage<br>because he was ugly. There was logic in his nature, as there is<br>in ours.</p>\n<p>His strength, so extraordinarily developed, was a cause of still<br>greater malevolence: “<em>Malus puer robustus</em>,” says Hobbes.</p>\n<p>This justice must, however be rendered to him. Malevolence was<br>not, perhaps, innate in him. From his very first steps among men,<br>he had felt himself, later on he had seen himself, spewed out,<br>blasted, rejected. Human words were, for him, always a raillery<br>or a malediction. As he grew up, he had found nothing but hatred<br>around him. He had caught the general malevolence. He had picked<br>up the weapon with which he had been wounded.</p>\n<p>After all, he turned his face towards men only with reluctance;<br>his cathedral was sufficient for him. It was peopled with marble<br>figures,—kings, saints, bishops,—who at least did not burst out<br>laughing in his face, and who gazed upon him only with<br>tranquillity and kindliness. The other statues, those of the<br>monsters and demons, cherished no hatred for him, Quasimodo. He<br>resembled them too much for that. They seemed rather, to be<br>scoffing at other men. The saints were his friends, and blessed<br>him; the monsters were his friends and guarded him. So he held<br>long communion with them. He sometimes passed whole hours<br>crouching before one of these statues, in solitary conversation<br>with it. If any one came, he fled like a lover surprised in his<br>serenade.</p>\n<p>And the cathedral was not only society for him, but the universe,<br>and all nature beside. He dreamed of no other hedgerows than the<br>painted windows, always in flower; no other shade than that of<br>the foliage of stone which spread out, loaded with birds, in the<br>tufts of the Saxon capitals; of no other mountains than the<br>colossal towers of the church; of no other ocean than Paris,<br>roaring at their bases.</p>\n<p>What he loved above all else in the maternal edifice, that which<br>aroused his soul, and made it open its poor wings, which it kept<br>so miserably folded in its cavern, that which sometimes rendered<br>him even happy, was the bells. He loved them, fondled them,<br>talked to them, understood them. From the chime in the spire,<br>over the intersection of the aisles and nave, to the great bell<br>of the front, he cherished a tenderness for them all. The central<br>spire and the two towers were to him as three great cages, whose<br>birds, reared by himself, sang for him alone. Yet it was these<br>very bells which had made him deaf; but mothers often love best<br>that child which has caused them the most suffering.</p>\n<p>It is true that their voice was the only one which he could still<br>hear. On this score, the big bell was his beloved. It was she<br>whom he preferred out of all that family of noisy girls which<br>bustled above him, on festival days. This bell was named Marie.<br>She was alone in the southern tower, with her sister Jacqueline,<br>a bell of lesser size, shut up in a smaller cage beside hers.<br>This Jacqueline was so called from the name of the wife of Jean<br>Montagu, who had given it to the church, which had not prevented<br>his going and figuring without his head at Montfaucon. In the<br>second tower there were six other bells, and, finally, six<br>smaller ones inhabited the belfry over the crossing, with the<br>wooden bell, which rang only between after dinner on Good Friday<br>and the morning of the day before Easter. So Quasimodo had<br>fifteen bells in his seraglio; but big Marie was his favorite.</p>\n<p>No idea can be formed of his delight on days when the grand peal<br>was sounded. At the moment when the archdeacon dismissed him, and<br>said, “Go!” he mounted the spiral staircase of the clock tower<br>faster than any one else could have descended it. He entered<br>perfectly breathless into the aerial chamber of the great bell;<br>he gazed at her a moment, devoutly and lovingly; then he gently<br>addressed her and patted her with his hand, like a good horse,<br>which is about to set out on a long journey. He pitied her for<br>the trouble that she was about to suffer. After these first<br>caresses, he shouted to his assistants, placed in the lower story<br>of the tower, to begin. They grasped the ropes, the wheel<br>creaked, the enormous capsule of metal started slowly into<br>motion. Quasimodo followed it with his glance and trembled. The<br>first shock of the clapper and the brazen wall made the framework<br>upon which it was mounted quiver. Quasimodo vibrated with the<br>bell.</p>\n<p>“Vah!” he cried, with a senseless burst of laughter. However, the<br>movement of the bass was accelerated, and, in proportion as it<br>described a wider angle, Quasimodo’s eye opened also more and<br>more widely, phosphoric and flaming. At length the grand peal<br>began; the whole tower trembled; woodwork, leads, cut stones, all<br>groaned at once, from the piles of the foundation to the trefoils<br>of its summit. Then Quasimodo boiled and frothed; he went and<br>came; he trembled from head to foot with the tower. The bell,<br>furious, running riot, presented to the two walls of the tower<br>alternately its brazen throat, whence escaped that tempestuous<br>breath, which is audible leagues away. Quasimodo stationed<br>himself in front of this open throat; he crouched and rose with<br>the oscillations of the bell, breathed in this overwhelming<br>breath, gazed by turns at the deep place, which swarmed with<br>people, two hundred feet below him, and at that enormous, brazen<br>tongue which came, second after second, to howl in his ear.</p>\n<p>It was the only speech which he understood, the only sound which<br>broke for him the universal silence. He swelled out in it as a<br>bird does in the sun. All of a sudden, the frenzy of the bell<br>seized upon him; his look became extraordinary; he lay in wait<br>for the great bell as it passed, as a spider lies in wait for a<br>fly, and flung himself abruptly upon it, with might and main.<br>Then, suspended above the abyss, borne to and fro by the<br>formidable swinging of the bell, he seized the brazen monster by<br>the ear-laps, pressed it between both knees, spurred it on with<br>his heels, and redoubled the fury of the peal with the whole<br>shock and weight of his body. Meanwhile, the tower trembled; he<br>shrieked and gnashed his teeth, his red hair rose erect, his<br>breast heaving like a bellows, his eye flashed flames, the<br>monstrous bell neighed, panting, beneath him; and then it was no<br>longer the great bell of Notre-Dame nor Quasimodo: it was a<br>dream, a whirlwind, a tempest, dizziness mounted astride of<br>noise; a spirit clinging to a flying crupper, a strange centaur,<br>half man, half bell; a sort of horrible Astolphus, borne away<br>upon a prodigious hippogriff of living bronze.</p>\n<p>The presence of this extraordinary being caused, as it were, a<br>breath of life to circulate throughout the entire cathedral. It<br>seemed as though there escaped from him, at least according to<br>the growing superstitions of the crowd, a mysterious emanation<br>which animated all the stones of Notre-Dame, and made the deep<br>bowels of the ancient church to palpitate. It sufficed for people<br>to know that he was there, to make them believe that they beheld<br>the thousand statues of the galleries and the fronts in motion.<br>And the cathedral did indeed seem a docile and obedient creature<br>beneath his hand; it waited on his will to raise its great voice;<br>it was possessed and filled with Quasimodo, as with a familiar<br>spirit. One would have said that he made the immense edifice<br>breathe. He was everywhere about it; in fact, he multiplied<br>himself on all points of the structure. Now one perceived with<br>affright at the very top of one of the towers, a fantastic dwarf<br>climbing, writhing, crawling on all fours, descending outside<br>above the abyss, leaping from projection to projection, and going<br>to ransack the belly of some sculptured gorgon; it was Quasimodo<br>dislodging the crows. Again, in some obscure corner of the church<br>one came in contact with a sort of living chimera, crouching and<br>scowling; it was Quasimodo engaged in thought. Sometimes one<br>caught sight, upon a bell tower, of an enormous head and a bundle<br>of disordered limbs swinging furiously at the end of a rope; it<br>was Quasimodo ringing vespers or the Angelus. Often at night a<br>hideous form was seen wandering along the frail balustrade of<br>carved lacework, which crowns the towers and borders the<br>circumference of the apse; again it was the hunchback of<br>Notre-Dame. Then, said the women of the neighborhood, the whole<br>church took on something fantastic, supernatural, horrible; eyes<br>and mouths were opened, here and there; one heard the dogs, the<br>monsters, and the gargoyles of stone, which keep watch night and<br>day, with outstretched neck and open jaws, around the monstrous<br>cathedral, barking. And, if it was a Christmas Eve, while the<br>great bell, which seemed to emit the death rattle, summoned the<br>faithful to the midnight mass, such an air was spread over the<br>sombre façade that one would have declared that the grand portal<br>was devouring the throng, and that the rose window was watching<br>it. And all this came from Quasimodo. Egypt would have taken him<br>for the god of this temple; the Middle Ages believed him to be<br>its demon: he was in fact its soul.</p>\n<p>To such an extent was this disease that for those who know that<br>Quasimodo has existed, Notre-Dame is to-day deserted, inanimate,<br>dead. One feels that something has disappeared from it. That<br>immense body is empty; it is a skeleton; the spirit has quitted<br>it, one sees its place and that is all. It is like a skull which<br>still has holes for the eyes, but no longer sight.</p>\n<h1 class=\"chapter\" id=\"chapter-iv-the-dog-and-his-master\">Chapter IV. THE DOG AND HIS MASTER.</h1>\n<p>Nevertheless, there was one human creature whom Quasimodo<br>excepted from his malice and from his hatred for others, and whom<br>he loved even more, perhaps, than his cathedral: this was Claude<br>Frollo.</p>\n<p>The matter was simple; Claude Frollo had taken him in, had<br>adopted him, had nourished him, had reared him. When a little<br>lad, it was between Claude Frollo’s legs that he was accustomed<br>to seek refuge, when the dogs and the children barked after him.<br>Claude Frollo had taught him to talk, to read, to write. Claude<br>Frollo had finally made him the bellringer. Now, to give the big<br>bell in marriage to Quasimodo was to give Juliet to Romeo.</p>\n<p>Hence Quasimodo’s gratitude was profound, passionate, boundless;<br>and although the visage of his adopted father was often clouded<br>or severe, although his speech was habitually curt, harsh,<br>imperious, that gratitude never wavered for a single moment. The<br>archdeacon had in Quasimodo the most submissive slave, the most<br>docile lackey, the most vigilant of dogs. When the poor<br>bellringer became deaf, there had been established between him<br>and Claude Frollo, a language of signs, mysterious and understood<br>by themselves alone. In this manner the archdeacon was the sole<br>human being with whom Quasimodo had preserved communication. He<br>was in sympathy with but two things in this world: Notre-Dame and<br>Claude Frollo.</p>\n<p>There is nothing which can be compared with the empire of the<br>archdeacon over the bellringer; with the attachment of the<br>bellringer for the archdeacon. A sign from Claude and the idea of<br>giving him pleasure would have sufficed to make Quasimodo hurl<br>himself headlong from the summit of Notre-Dame. It was a<br>remarkable thing—all that physical strength which had reached in<br>Quasimodo such an extraordinary development, and which was placed<br>by him blindly at the disposition of another. There was in it, no<br>doubt, filial devotion, domestic attachment; there was also the<br>fascination of one spirit by another spirit. It was a poor,<br>awkward, and clumsy organization, which stood with lowered head<br>and supplicating eyes before a lofty and profound, a powerful and<br>superior intellect. Lastly, and above all, it was gratitude.<br>Gratitude so pushed to its extremest limit, that we do not know<br>to what to compare it. This virtue is not one of those of which<br>the finest examples are to be met with among men. We will say<br>then, that Quasimodo loved the archdeacon as never a dog, never a<br>horse, never an elephant loved his master.</p>\n<h1 class=\"chapter\" id=\"chapter-v-more-about-claude-frollo\">Chapter V. MORE ABOUT CLAUDE FROLLO.</h1>\n<p>In 1482, Quasimodo was about twenty years of age; Claude Frollo,<br>about thirty-six. One had grown up, the other had grown old.</p>\n<p>Claude Frollo was no longer the simple scholar of the college of<br>Torchi, the tender protector of a little child, the young and<br>dreamy philosopher who knew many things and was ignorant of many.<br>He was a priest, austere, grave, morose; one charged with souls;<br>monsieur the archdeacon of Josas, the bishop’s second acolyte,<br>having charge of the two deaneries of Montlhéry, and Châteaufort,<br>and one hundred and seventy-four country curacies. He was an<br>imposing and sombre personage, before whom the choir boys in alb<br>and in jacket trembled, as well as the machicots[25], and the<br>brothers of Saint-Augustine and the matutinal clerks of<br>Notre-Dame, when he passed slowly beneath the lofty arches of the<br>choir, majestic, thoughtful, with arms folded and his head so<br>bent upon his breast that all one saw of his face was his large,<br>bald brow.</p>\n<p>Dom Claude Frollo had, however, abandoned neither science nor the<br>education of his young brother, those two occupations of his<br>life. But as time went on, some bitterness had been mingled with<br>these things which were so sweet. In the long run, says Paul<br>Diacre, the best lard turns rancid. Little Jehan Frollo, surnamed<br>(<em>du Moulin</em>) “of the Mill” because of the place where he had<br>been reared, had not grown up in the direction which Claude would<br>have liked to impose upon him. The big brother counted upon a<br>pious, docile, learned, and honorable pupil. But the little<br>brother, like those young trees which deceive the gardener’s<br>hopes and turn obstinately to the quarter whence they receive sun<br>and air, the little brother did not grow and did not multiply,<br>but only put forth fine bushy and luxuriant branches on the side<br>of laziness, ignorance, and debauchery. He was a regular devil,<br>and a very disorderly one, who made Dom Claude scowl; but very<br>droll and very subtle, which made the big brother smile.</p>\n<p>Claude had confided him to that same college of Torchi where he<br>had passed his early years in study and meditation; and it was a<br>grief to him that this sanctuary, formerly edified by the name of<br>Frollo, should to-day be scandalized by it. He sometimes preached<br>Jehan very long and severe sermons, which the latter intrepidly<br>endured. After all, the young scapegrace had a good heart, as can<br>be seen in all comedies. But the sermon over, he none the less<br>tranquilly resumed his course of seditions and enormities. Now it<br>was a <em>béjaune</em> or yellow beak (as they called the new arrivals<br>at the university), whom he had been mauling by way of welcome; a<br>precious tradition which has been carefully preserved to our own<br>day. Again, he had set in movement a band of scholars, who had<br>flung themselves upon a wine-shop in classic fashion, _quasi<br>classico excitati_, had then beaten the tavern-keeper “with<br>offensive cudgels,” and joyously pillaged the tavern, even to<br>smashing in the hogsheads of wine in the cellar. And then it was<br>a fine report in Latin, which the sub-monitor of Torchi carried<br>piteously to Dom Claude with this dolorous marginal<br>comment,—<em>Rixa; prima causa vinum optimum potatum</em>. Finally, it<br>was said, a thing quite horrible in a boy of sixteen, that his<br>debauchery often extended as far as the Rue de Glatigny.</p>\n<p>Claude, saddened and discouraged in his human affections, by all<br>this, had flung himself eagerly into the arms of learning, that<br>sister which, at least does not laugh in your face, and which<br>always pays you, though in money that is sometimes a little<br>hollow, for the attention which you have paid to her. Hence, he<br>became more and more learned, and, at the same time, as a natural<br>consequence, more and more rigid as a priest, more and more sad<br>as a man. There are for each of us several parallelisms between<br>our intelligence, our habits, and our character, which develop<br>without a break, and break only in the great disturbances of<br>life.</p>\n<p>As Claude Frollo had passed through nearly the entire circle of<br>human learning—positive, exterior, and permissible—since his<br>youth, he was obliged, unless he came to a halt, _ubi defuit<br>orbis_, to proceed further and seek other aliments for the<br>insatiable activity of his intelligence. The antique symbol of<br>the serpent biting its tail is, above all, applicable to science.<br>It would appear that Claude Frollo had experienced this. Many<br>grave persons affirm that, after having exhausted the <em>fas</em> of<br>human learning, he had dared to penetrate into the <em>nefas</em>. He<br>had, they said, tasted in succession all the apples of the tree<br>of knowledge, and, whether from hunger or disgust, had ended by<br>tasting the forbidden fruit. He had taken his place by turns, as<br>the reader has seen, in the conferences of the theologians in<br>Sorbonne,—in the assemblies of the doctors of art, after the<br>manner of Saint-Hilaire,—in the disputes of the decretalists,<br>after the manner of Saint-Martin,—in the congregations of<br>physicians at the holy water font of Notre-Dame, _ad cupam<br>Nostræ-Dominæ_. All the dishes permitted and approved, which<br>those four great kitchens called the four faculties could<br>elaborate and serve to the understanding, he had devoured, and<br>had been satiated with them before his hunger was appeased. Then<br>he had penetrated further, lower, beneath all that finished,<br>material, limited knowledge; he had, perhaps, risked his soul,<br>and had seated himself in the cavern at that mysterious table of<br>the alchemists, of the astrologers, of the hermetics, of which<br>Averroès, Guillaume de Paris, and Nicolas Flamel hold the end in<br>the Middle Ages; and which extends in the East, by the light of<br>the seven-branched candlestick, to Solomon, Pythagoras, and<br>Zoroaster.</p>\n<p>That is, at least, what was supposed, whether rightly or not. It<br>is certain that the archdeacon often visited the cemetery of the<br>Saints-Innocents, where, it is true, his father and mother had<br>been buried, with other victims of the plague of 1466; but that<br>he appeared far less devout before the cross of their grave than<br>before the strange figures with which the tomb of Nicolas Flamel<br>and Claude Pernelle, erected just beside it, was loaded.</p>\n<p>It is certain that he had frequently been seen to pass along the<br>Rue des Lombards, and furtively enter a little house which formed<br>the corner of the Rue des Ecrivans and the Rue Marivault. It was<br>the house which Nicolas Flamel had built, where he had died about<br>1417, and which, constantly deserted since that time, had already<br>begun to fall in ruins,—so greatly had the hermetics and the<br>alchemists of all countries wasted away the walls, merely by<br>carving their names upon them. Some neighbors even affirm that<br>they had once seen, through an air-hole, Archdeacon Claude<br>excavating, turning over, digging up the earth in the two<br>cellars, whose supports had been daubed with numberless couplets<br>and hieroglyphics by Nicolas Flamel himself. It was supposed that<br>Flamel had buried the philosopher’s stone in the cellar; and the<br>alchemists, for the space of two centuries, from Magistri to<br>Father Pacifique, never ceased to worry the soil until the house,<br>so cruelly ransacked and turned over, ended by falling into dust<br>beneath their feet.</p>\n<p>Again, it is certain that the archdeacon had been seized with a<br>singular passion for the symbolical door of Notre-Dame, that page<br>of a conjuring book written in stone, by Bishop Guillaume de<br>Paris, who has, no doubt, been damned for having affixed so<br>infernal a frontispiece to the sacred poem chanted by the rest of<br>the edifice. Archdeacon Claude had the credit also of having<br>fathomed the mystery of the colossus of Saint Christopher, and of<br>that lofty, enigmatical statue which then stood at the entrance<br>of the vestibule, and which the people, in derision, called<br>“Monsieur Legris.” But, what every one might have noticed was the<br>interminable hours which he often employed, seated upon the<br>parapet of the area in front of the church, in contemplating the<br>sculptures of the front; examining now the foolish virgins with<br>their lamps reversed, now the wise virgins with their lamps<br>upright; again, calculating the angle of vision of that raven<br>which belongs to the left front, and which is looking at a<br>mysterious point inside the church, where is concealed the<br>philosopher’s stone, if it be not in the cellar of Nicolas<br>Flamel.</p>\n<p>It was, let us remark in passing, a singular fate for the Church<br>of Notre-Dame at that epoch to be so beloved, in two different<br>degrees, and with so much devotion, by two beings so dissimilar<br>as Claude and Quasimodo. Beloved by one, a sort of instinctive<br>and savage half-man, for its beauty, for its stature, for the<br>harmonies which emanated from its magnificent ensemble; beloved<br>by the other, a learned and passionate imagination, for its myth,<br>for the sense which it contains, for the symbolism scattered<br>beneath the sculptures of its front,—like the first text<br>underneath the second in a palimpsest,—in a word, for the enigma<br>which it is eternally propounding to the understanding.</p>\n<p>Furthermore, it is certain that the archdeacon had established<br>himself in that one of the two towers which looks upon the Grève,<br>just beside the frame for the bells, a very secret little cell,<br>into which no one, not even the bishop, entered without his<br>leave, it was said. This tiny cell had formerly been made almost<br>at the summit of the tower, among the ravens’ nests, by Bishop<br>Hugo de Besançon[26] who had wrought sorcery there in his day.<br>What that cell contained, no one knew; but from the strand of the<br>Terrain, at night, there was often seen to appear, disappear, and<br>reappear at brief and regular intervals, at a little dormer<br>window opening upon the back of the tower, a certain red,<br>intermittent, singular light which seemed to follow the panting<br>breaths of a bellows, and to proceed from a flame, rather than<br>from a light. In the darkness, at that height, it produced a<br>singular effect; and the goodwives said: “There’s the archdeacon<br>blowing! hell is sparkling up yonder!”</p>\n<p>There were no great proofs of sorcery in that, after all, but<br>there was still enough smoke to warrant a surmise of fire, and<br>the archdeacon bore a tolerably formidable reputation. We ought<br>to mention however, that the sciences of Egypt, that necromancy<br>and magic, even the whitest, even the most innocent, had no more<br>envenomed enemy, no more pitiless denunciator before the<br>gentlemen of the officialty of Notre-Dame. Whether this was<br>sincere horror, or the game played by the thief who shouts, “stop<br>thief!” at all events, it did not prevent the archdeacon from<br>being considered by the learned heads of the chapter, as a soul<br>who had ventured into the vestibule of hell, who was lost in the<br>caves of the cabal, groping amid the shadows of the occult<br>sciences. Neither were the people deceived thereby; with any one<br>who possessed any sagacity, Quasimodo passed for the demon;<br>Claude Frollo, for the sorcerer. It was evident that the<br>bellringer was to serve the archdeacon for a given time, at the<br>end of which he would carry away the latter’s soul, by way of<br>payment. Thus the archdeacon, in spite of the excessive austerity<br>of his life, was in bad odor among all pious souls; and there was<br>no devout nose so inexperienced that it could not smell him out<br>to be a magician.</p>\n<p>And if, as he grew older, abysses had formed in his science, they<br>had also formed in his heart. That at least, is what one had<br>grounds for believing on scrutinizing that face upon which the<br>soul was only seen to shine through a sombre cloud. Whence that<br>large, bald brow? that head forever bent? that breast always<br>heaving with sighs? What secret thought caused his mouth to smile<br>with so much bitterness, at the same moment that his scowling<br>brows approached each other like two bulls on the point of<br>fighting? Why was what hair he had left already gray? What was<br>that internal fire which sometimes broke forth in his glance, to<br>such a degree that his eye resembled a hole pierced in the wall<br>of a furnace?</p>\n<p>These symptoms of a violent moral preoccupation, had acquired an<br>especially high degree of intensity at the epoch when this story<br>takes place. More than once a choir-boy had fled in terror at<br>finding him alone in the church, so strange and dazzling was his<br>look. More than once, in the choir, at the hour of the offices,<br>his neighbor in the stalls had heard him mingle with the plain<br>song, <em>ad omnem tonum</em>, unintelligible parentheses. More than<br>once the laundress of the Terrain charged “with washing the<br>chapter” had observed, not without affright, the marks of nails<br>and clenched fingers on the surplice of monsieur the archdeacon<br>of Josas.</p>\n<p>However, he redoubled his severity, and had never been more<br>exemplary. By profession as well as by character, he had always<br>held himself aloof from women; he seemed to hate them more than<br>ever. The mere rustling of a silken petticoat caused his hood to<br>fall over his eyes. Upon this score he was so jealous of<br>austerity and reserve, that when the Dame de Beaujeu, the king’s<br>daughter, came to visit the cloister of Notre-Dame, in the month<br>of December, 1481, he gravely opposed her entrance, reminding the<br>bishop of the statute of the Black Book, dating from the vigil of<br>Saint-Barthélemy, 1334, which interdicts access to the cloister<br>to “any woman whatever, old or young, mistress or maid.” Upon<br>which the bishop had been constrained to recite to him the<br>ordinance of Legate Odo, which excepts certain great dames,<br><em>aliquæ magnates mulieres, quæ sine scandalo vitari non possunt</em>.<br>And again the archdeacon had protested, objecting that the<br>ordinance of the legate, which dated back to 1207, was anterior<br>by a hundred and twenty-seven years to the Black Book, and<br>consequently was abrogated in fact by it. And he had refused to<br>appear before the princess.</p>\n<p>It was also noticed that his horror for Bohemian women and<br>gypsies had seemed to redouble for some time past. He had<br>petitioned the bishop for an edict which expressly forbade the<br>Bohemian women to come and dance and beat their tambourines on<br>the place of the Parvis; and for about the same length of time,<br>he had been ransacking the mouldy placards of the officialty, in<br>order to collect the cases of sorcerers and witches condemned to<br>fire or the rope, for complicity in crimes with rams, sows, or<br>goats.</p>\n<h1 class=\"chapter\" id=\"chapter-vi-unpopularity\">Chapter VI. UNPOPULARITY.</h1>\n<p>The archdeacon and the bellringer, as we have already said, were<br>but little loved by the populace great and small, in the vicinity<br>of the cathedral. When Claude and Quasimodo went out together,<br>which frequently happened, and when they were seen traversing in<br>company, the valet behind the master, the cold, narrow, and<br>gloomy streets of the block of Notre-Dame, more than one evil<br>word, more than one ironical quaver, more than one insulting jest<br>greeted them on their way, unless Claude Frollo, which was rarely<br>the case, walked with head upright and raised, showing his severe<br>and almost august brow to the dumbfounded jeerers.</p>\n<p>Both were in their quarter like “the poets” of whom Régnier<br>speaks,—</p>\n<p>“All sorts of persons run after poets,<br>As warblers fly shrieking after owls.”</p>\n<p>Sometimes a mischievous child risked his skin and bones for the<br>ineffable pleasure of driving a pin into Quasimodo’s hump. Again,<br>a young girl, more bold and saucy than was fitting, brushed the<br>priest’s black robe, singing in his face the sardonic ditty,<br>“<em>niche, niche</em>, the devil is caught.” Sometimes a group of<br>squalid old crones, squatting in a file under the shadow of the<br>steps to a porch, scolded noisily as the archdeacon and the<br>bellringer passed, and tossed them this encouraging welcome, with<br>a curse: “Hum! there’s a fellow whose soul is made like the other<br>one’s body!” Or a band of schoolboys and street urchins, playing<br>hop-scotch, rose in a body and saluted him classically, with some<br>cry in Latin: “<em>Eia! eia! Claudius cum claudo</em>!”</p>\n<p>But the insult generally passed unnoticed both by the priest and<br>the bellringer. Quasimodo was too deaf to hear all these gracious<br>things, and Claude was too dreamy.</p>\n<p>BOOK FIFTH.</p>\n<h1 class=\"chapter\" id=\"chapter-i-abbas-beati-martini\">Chapter I. _ABBAS BEATI MARTINI_.</h1>\n<p>Dom Claude’s fame had spread far and wide. It procured for him,<br>at about the epoch when he refused to see Madame de Beaujeu, a<br>visit which he long remembered.</p>\n<p>It was in the evening. He had just retired, after the office, to<br>his canon’s cell in the cloister of Notre-Dame. This cell, with<br>the exception, possibly, of some glass phials, relegated to a<br>corner, and filled with a decidedly equivocal powder, which<br>strongly resembled the alchemist’s “powder of projection,”<br>presented nothing strange or mysterious. There were, indeed, here<br>and there, some inscriptions on the walls, but they were pure<br>sentences of learning and piety, extracted from good authors. The<br>archdeacon had just seated himself, by the light of a<br>three-jetted copper lamp, before a vast coffer crammed with<br>manuscripts. He had rested his elbow upon the open volume of<br>Honorius d’Autun, <em>De predestinatione et libero arbitrio</em>, and he<br>was turning over, in deep meditation, the leaves of a printed<br>folio which he had just brought, the sole product of the press<br>which his cell contained. In the midst of his revery there came a<br>knock at his door. “Who’s there?” cried the learned man, in the<br>gracious tone of a famished dog, disturbed over his bone.</p>\n<p>A voice without replied, “Your friend, Jacques Coictier.” He went<br>to open the door.</p>\n<p>It was, in fact, the king’s physician; a person about fifty years<br>of age, whose harsh physiognomy was modified only by a crafty<br>eye. Another man accompanied him. Both wore long slate-colored<br>robes, furred with minever, girded and closed, with caps of the<br>same stuff and hue. Their hands were concealed by their sleeves,<br>their feet by their robes, their eyes by their caps.</p>\n<p>“God help me, messieurs!” said the archdeacon, showing them in;<br>“I was not expecting distinguished visitors at such an hour.” And<br>while speaking in this courteous fashion he cast an uneasy and<br>scrutinizing glance from the physician to his companion.</p>\n<p>“’Tis never too late to come and pay a visit to so considerable a<br>learned man as Dom Claude Frollo de Tirechappe,” replied Doctor<br>Coictier, whose Franche-Comté accent made all his phrases drag<br>along with the majesty of a train-robe.</p>\n<p>There then ensued between the physician and the archdeacon one of<br>those congratulatory prologues which, in accordance with custom,<br>at that epoch preceded all conversations between learned men, and<br>which did not prevent them from detesting each other in the most<br>cordial manner in the world. However, it is the same nowadays;<br>every wise man’s mouth complimenting another wise man is a vase<br>of honeyed gall.</p>\n<p>Claude Frollo’s felicitations to Jacques Coictier bore reference<br>principally to the temporal advantages which the worthy physician<br>had found means to extract, in the course of his much envied<br>career, from each malady of the king, an operation of alchemy<br>much better and more certain than the pursuit of the<br>philosopher’s stone.</p>\n<p>“In truth, Monsieur le Docteur Coictier, I felt great joy on<br>learning of the bishopric given your nephew, my reverend seigneur<br>Pierre Versé. Is he not Bishop of Amiens?”</p>\n<p>“Yes, monsieur Archdeacon; it is a grace and mercy of God.”</p>\n<p>“Do you know that you made a great figure on Christmas Day at the<br>head of your company of the chamber of accounts, Monsieur<br>President?”</p>\n<p>“Vice-President, Dom Claude. Alas! nothing more.”</p>\n<p>“How is your superb house in the Rue Saint-André des Arcs coming<br>on? ’Tis a Louvre. I love greatly the apricot tree which is<br>carved on the door, with this play of words: ‘A<br>L’ABRI-COTIER—Sheltered from reefs.’”</p>\n<p>“Alas! Master Claude, all that masonry costeth me dear. In<br>proportion as the house is erected, I am ruined.”</p>\n<p>“Ho! have you not your revenues from the jail, and the bailiwick<br>of the Palais, and the rents of all the houses, sheds, stalls,<br>and booths of the enclosure? ’Tis a fine breast to suck.”</p>\n<p>“My castellany of Poissy has brought me in nothing this year.”</p>\n<p>“But your tolls of Triel, of Saint-James, of<br>Saint-Germain-en-Laye are always good.”</p>\n<p>“Six score livres, and not even Parisian livres at that.”</p>\n<p>“You have your office of counsellor to the king. That is fixed.”</p>\n<p>“Yes, brother Claude; but that accursed seigneury of Poligny,<br>which people make so much noise about, is worth not sixty gold<br>crowns, year out and year in.”</p>\n<p>In the compliments which Dom Claude addressed to Jacques<br>Coictier, there was that sardonical, biting, and covertly mocking<br>accent, and the sad cruel smile of a superior and unhappy man who<br>toys for a moment, by way of distraction, with the dense<br>prosperity of a vulgar man. The other did not perceive it.</p>\n<p>“Upon my soul,” said Claude at length, pressing his hand, “I am<br>glad to see you and in such good health.”</p>\n<p>“Thanks, Master Claude.”</p>\n<p>“By the way,” exclaimed Dom Claude, “how is your royal patient?”</p>\n<p>“He payeth not sufficiently his physician,” replied the doctor,<br>casting a side glance at his companion.</p>\n<p>“Think you so, Gossip Coictier,” said the latter.</p>\n<p>These words, uttered in a tone of surprise and reproach, drew<br>upon this unknown personage the attention of the archdeacon<br>which, to tell the truth, had not been diverted from him a single<br>moment since the stranger had set foot across the threshold of<br>his cell. It had even required all the thousand reasons which he<br>had for handling tenderly Doctor Jacques Coictier, the<br>all-powerful physician of King Louis XI., to induce him to<br>receive the latter thus accompanied. Hence, there was nothing<br>very cordial in his manner when Jacques Coictier said to him,—</p>\n<p>“By the way, Dom Claude, I bring you a colleague who has desired<br>to see you on account of your reputation.”</p>\n<p>“Monsieur belongs to science?” asked the archdeacon, fixing his<br>piercing eye upon Coictier’s companion. He found beneath the<br>brows of the stranger a glance no less piercing or less<br>distrustful than his own.</p>\n<p>He was, so far as the feeble light of the lamp permitted one to<br>judge, an old man about sixty years of age and of medium stature,<br>who appeared somewhat sickly and broken in health. His profile,<br>although of a very ordinary outline, had something powerful and<br>severe about it; his eyes sparkled beneath a very deep<br>superciliary arch, like a light in the depths of a cave; and<br>beneath his cap which was well drawn down and fell upon his nose,<br>one recognized the broad expanse of a brow of genius.</p>\n<p>He took it upon himself to reply to the archdeacon’s question,—</p>\n<p>“Reverend master,” he said in a grave tone, “your renown has<br>reached my ears, and I wish to consult you. I am but a poor<br>provincial gentleman, who removeth his shoes before entering the<br>dwellings of the learned. You must know my name. I am called<br>Gossip Tourangeau.”</p>\n<p>“Strange name for a gentleman,” said the archdeacon to himself.</p>\n<p>Nevertheless, he had a feeling that he was in the presence of a<br>strong and earnest character. The instinct of his own lofty<br>intellect made him recognize an intellect no less lofty under<br>Gossip Tourangeau’s furred cap, and as he gazed at the solemn<br>face, the ironical smile which Jacques Coictier’s presence called<br>forth on his gloomy face, gradually disappeared as twilight fades<br>on the horizon of night. Stern and silent, he had resumed his<br>seat in his great armchair; his elbow rested as usual, on the<br>table, and his brow on his hand. After a few moments of<br>reflection, he motioned his visitors to be seated, and, turning<br>to Gossip Tourangeau he said,—</p>\n<p>“You come to consult me, master, and upon what science?”</p>\n<p>“Your reverence,” replied Tourangeau, “I am ill, very ill. You<br>are said to be great Æsculapius, and I am come to ask your advice<br>in medicine.”</p>\n<p>“Medicine!” said the archdeacon, tossing his head. He seemed to<br>meditate for a moment, and then resumed: “Gossip Tourangeau,<br>since that is your name, turn your head, you will find my reply<br>already written on the wall.”</p>\n<p>Gossip Tourangeau obeyed, and read this inscription engraved<br>above his head: “_Medicine is the daughter of<br>dreams_.—JAMBLIQUE.”</p>\n<p>Meanwhile, Doctor Jacques Coictier had heard his companion’s<br>question with a displeasure which Dom Claude’s response had but<br>redoubled. He bent down to the ear of Gossip Tourangeau, and said<br>to him, softly enough not to be heard by the archdeacon: “I<br>warned you that he was mad. You insisted on seeing him.”</p>\n<p>“’Tis very possible that he is right, madman as he is, Doctor<br>Jacques,” replied his comrade in the same low tone, and with a<br>bitter smile.</p>\n<p>“As you please,” replied Coictier dryly. Then, addressing the<br>archdeacon: “You are clever at your trade, Dom Claude, and you<br>are no more at a loss over Hippocrates than a monkey is over a<br>nut. Medicine a dream! I suspect that the pharmacopolists and the<br>master physicians would insist upon stoning you if they were<br>here. So you deny the influence of philtres upon the blood, and<br>unguents on the skin! You deny that eternal pharmacy of flowers<br>and metals, which is called the world, made expressly for that<br>eternal invalid called man!”</p>\n<p>“I deny,” said Dom Claude coldly, “neither pharmacy nor the<br>invalid. I reject the physician.”</p>\n<p>“Then it is not true,” resumed Coictier hotly, “that gout is an<br>internal eruption; that a wound caused by artillery is to be<br>cured by the application of a young mouse roasted; that young<br>blood, properly injected, restores youth to aged veins; it is not<br>true that two and two make four, and that emprostathonos follows<br>opistathonos.”</p>\n<p>The archdeacon replied without perturbation: “There are certain<br>things of which I think in a certain fashion.”</p>\n<p>Coictier became crimson with anger.</p>\n<p>“There, there, my good Coictier, let us not get angry,” said<br>Gossip Tourangeau. “Monsieur the archdeacon is our friend.”</p>\n<p>Coictier calmed down, muttering in a low tone,—</p>\n<p>“After all, he’s mad.”</p>\n<p>“<em>Pasque-dieu</em>, Master Claude,” resumed Gossip Tourangeau, after<br>a silence, “You embarrass me greatly. I had two things to consult<br>you upon, one touching my health and the other touching my star.”</p>\n<p>“Monsieur,” returned the archdeacon, “if that be your motive, you<br>would have done as well not to put yourself out of breath<br>climbing my staircase. I do not believe in Medicine. I do not<br>believe in Astrology.”</p>\n<p>“Indeed!” said the man, with surprise.</p>\n<p>Coictier gave a forced laugh.</p>\n<p>“You see that he is mad,” he said, in a low tone, to Gossip<br>Tourangeau. “He does not believe in astrology.”</p>\n<p>“The idea of imagining,” pursued Dom Claude, “that every ray of a<br>star is a thread which is fastened to the head of a man!”</p>\n<p>“And what then, do you believe in?” exclaimed Gossip Tourangeau.</p>\n<p>The archdeacon hesitated for a moment, then he allowed a gloomy<br>smile to escape, which seemed to give the lie to his response:<br>“<em>Credo in Deum</em>.”</p>\n<p>“<em>Dominum nostrum</em>,” added Gossip Tourangeau, making the sign of<br>the cross.</p>\n<p>“Amen,” said Coictier.</p>\n<p>“Reverend master,” resumed Tourangeau, “I am charmed in soul to<br>see you in such a religious frame of mind. But have you reached<br>the point, great savant as you are, of no longer believing in<br>science?”</p>\n<p>“No,” said the archdeacon, grasping the arm of Gossip Tourangeau,<br>and a ray of enthusiasm lighted up his gloomy eyes, “no, I do not<br>reject science. I have not crawled so long, flat on my belly,<br>with my nails in the earth, through the innumerable ramifications<br>of its caverns, without perceiving far in front of me, at the end<br>of the obscure gallery, a light, a flame, a something, the<br>reflection, no doubt, of the dazzling central laboratory where<br>the patient and the wise have found out God.”</p>\n<p>“And in short,” interrupted Tourangeau, “what do you hold to be<br>true and certain?”</p>\n<p>“Alchemy.”</p>\n<p>Coictier exclaimed, “Pardieu, Dom Claude, alchemy has its use, no<br>doubt, but why blaspheme medicine and astrology?”</p>\n<p>“Naught is your science of man, naught is your science of the<br>stars,” said the archdeacon, commandingly.</p>\n<p>“That’s driving Epidaurus and Chaldea very fast,” replied the<br>physician with a grin.</p>\n<p>“Listen, Messire Jacques. This is said in good faith. I am not<br>the king’s physician, and his majesty has not given me the Garden<br>of Dædalus in which to observe the constellations. Don’t get<br>angry, but listen to me. What truth have you deduced, I will not<br>say from medicine, which is too foolish a thing, but from<br>astrology? Cite to me the virtues of the vertical boustrophedon,<br>the treasures of the number ziruph and those of the number<br>zephirod!”</p>\n<p>“Will you deny,” said Coictier, “the sympathetic force of the<br>collar bone, and the cabalistics which are derived from it?”</p>\n<p>“An error, Messire Jacques! None of your formulas end in reality.<br>Alchemy on the other hand has its discoveries. Will you contest<br>results like this? Ice confined beneath the earth for a thousand<br>years is transformed into rock crystals. Lead is the ancestor of<br>all metals. For gold is not a metal, gold is light. Lead requires<br>only four periods of two hundred years each, to pass in<br>succession from the state of lead, to the state of red arsenic,<br>from red arsenic to tin, from tin to silver. Are not these facts?<br>But to believe in the collar bone, in the full line and in the<br>stars, is as ridiculous as to believe with the inhabitants of<br>Grand-Cathay that the golden oriole turns into a mole, and that<br>grains of wheat turn into fish of the carp species.”</p>\n<p>“I have studied hermetic science!” exclaimed Coictier, “and I<br>affirm—”</p>\n<p>The fiery archdeacon did not allow him to finish: “And I have<br>studied medicine, astrology, and hermetics. Here alone is the<br>truth.” (As he spoke thus, he took from the top of the coffer a<br>phial filled with the powder which we have mentioned above),<br>“here alone is light! Hippocrates is a dream; Urania is a dream;<br>Hermes, a thought. Gold is the sun; to make gold is to be God.<br>Herein lies the one and only science. I have sounded the depths<br>of medicine and astrology, I tell you! Naught, nothingness! The<br>human body, shadows! the planets, shadows!”</p>\n<p>And he fell back in his armchair in a commanding and inspired<br>attitude. Gossip Touraugeau watched him in silence. Coictier<br>tried to grin, shrugged his shoulders imperceptibly, and repeated<br>in a low voice,—</p>\n<p>“A madman!”</p>\n<p>“And,” said Tourangeau suddenly, “the wondrous result,—have you<br>attained it, have you made gold?”</p>\n<p>“If I had made it,” replied the archdeacon, articulating his<br>words slowly, like a man who is reflecting, “the king of France<br>would be named Claude and not Louis.”</p>\n<p>The stranger frowned.</p>\n<p>“What am I saying?” resumed Dom Claude, with a smile of disdain.<br>“What would the throne of France be to me when I could rebuild<br>the empire of the Orient?”</p>\n<p>“Very good!” said the stranger.</p>\n<p>“Oh, the poor fool!” murmured Coictier.</p>\n<p>The archdeacon went on, appearing to reply now only to his<br>thoughts,—</p>\n<p>“But no, I am still crawling; I am scratching my face and knees<br>against the pebbles of the subterranean pathway. I catch a<br>glimpse, I do not contemplate! I do not read, I spell out!”</p>\n<p>“And when you know how to read!” demanded the stranger, “will you<br>make gold?”</p>\n<p>“Who doubts it?” said the archdeacon.</p>\n<p>“In that case Our Lady knows that I am greatly in need of money,<br>and I should much desire to read in your books. Tell me, reverend<br>master, is your science inimical or displeasing to Our Lady?”</p>\n<p>“Whose archdeacon I am?” Dom Claude contented himself with<br>replying, with tranquil hauteur.</p>\n<p>“That is true, my master. Well! will it please you to initiate<br>me? Let me spell with you.”</p>\n<p>Claude assumed the majestic and pontifical attitude of a Samuel.</p>\n<p>“Old man, it requires longer years than remain to you, to<br>undertake this voyage across mysterious things. Your head is very<br>gray! One comes forth from the cavern only with white hair, but<br>only those with dark hair enter it. Science alone knows well how<br>to hollow, wither, and dry up human faces; she needs not to have<br>old age bring her faces already furrowed. Nevertheless, if the<br>desire possesses you of putting yourself under discipline at your<br>age, and of deciphering the formidable alphabet of the sages,<br>come to me; ’tis well, I will make the effort. I will not tell<br>you, poor old man, to go and visit the sepulchral chambers of the<br>pyramids, of which ancient Herodotus speaks, nor the brick tower<br>of Babylon, nor the immense white marble sanctuary of the Indian<br>temple of Eklinga. I, no more than yourself, have seen the<br>Chaldean masonry works constructed according to the sacred form<br>of the Sikra, nor the temple of Solomon, which is destroyed, nor<br>the stone doors of the sepulchre of the kings of Israel, which<br>are broken. We will content ourselves with the fragments of the<br>book of Hermes which we have here. I will explain to you the<br>statue of Saint Christopher, the symbol of the sower, and that of<br>the two angels which are on the front of the Sainte-Chapelle, and<br>one of which holds in his hands a vase, the other, a cloud—”</p>\n<p>Here Jacques Coictier, who had been unhorsed by the archdeacon’s<br>impetuous replies, regained his saddle, and interrupted him with<br>the triumphant tone of one learned man correcting<br>another,—“<em>Erras amice Claudi</em>. The symbol is not the number. You<br>take Orpheus for Hermes.”</p>\n<p>“’Tis you who are in error,” replied the archdeacon, gravely.<br>“Dædalus is the base; Orpheus is the wall; Hermes is the<br>edifice,—that is all. You shall come when you will,” he<br>continued, turning to Tourangeau, “I will show you the little<br>parcels of gold which remained at the bottom of Nicholas Flamel’s<br>alembic, and you shall compare them with the gold of Guillaume de<br>Paris. I will teach you the secret virtues of the Greek word,<br><em>peristera</em>. But, first of all, I will make you read, one after<br>the other, the marble letters of the alphabet, the granite pages<br>of the book. We shall go to the portal of Bishop Guillaume and of<br>Saint-Jean le Rond at the Sainte-Chapelle, then to the house of<br>Nicholas Flamel, Rue Manvault, to his tomb, which is at the<br>Saints-Innocents, to his two hospitals, Rue de Montmorency. I<br>will make you read the hieroglyphics which cover the four great<br>iron cramps on the portal of the hospital Saint-Gervais, and of<br>the Rue de la Ferronnerie. We will spell out in company, also,<br>the façade of Saint-Côme, of Sainte-Geneviève-des-Ardents, of<br>Saint Martin, of Saint-Jacques de la Boucherie—.”</p>\n<p>For a long time, Gossip Tourangeau, intelligent as was his<br>glance, had appeared not to understand Dom Claude. He<br>interrupted.</p>\n<p>“<em>Pasque-dieu</em>! what are your books, then?”</p>\n<p>“Here is one of them,” said the archdeacon.</p>\n<p>And opening the window of his cell he pointed out with his finger<br>the immense church of Notre-Dame, which, outlining against the<br>starry sky the black silhouette of its two towers, its stone<br>flanks, its monstrous haunches, seemed an enormous two-headed<br>sphinx, seated in the middle of the city.</p>\n<p>The archdeacon gazed at the gigantic edifice for some time in<br>silence, then extending his right hand, with a sigh, towards the<br>printed book which lay open on the table, and his left towards<br>Notre-Dame, and turning a sad glance from the book to the<br>church,—“Alas,” he said, “this will kill that.”</p>\n<p>Coictier, who had eagerly approached the book, could not repress<br>an exclamation. “Hé, but now, what is there so formidable in<br>this: ‘GLOSSA IN EPISTOLAS D. PAULI, _Norimbergæ, Antonius<br>Koburger_, 1474.’ This is not new. ’Tis a book of Pierre Lombard,<br>the Master of Sentences. Is it because it is printed?”</p>\n<p>“You have said it,” replied Claude, who seemed absorbed in a<br>profound meditation, and stood resting, his forefinger bent<br>backward on the folio which had come from the famous press of<br>Nuremberg. Then he added these mysterious words: “Alas! alas!<br>small things come at the end of great things; a tooth triumphs<br>over a mass. The Nile rat kills the crocodile, the swordfish<br>kills the whale, the book will kill the edifice.”</p>\n<p>The curfew of the cloister sounded at the moment when Master<br>Jacques was repeating to his companion in low tones, his eternal<br>refrain, “<em>He is mad!</em>” To which his companion this time replied,<br>“I believe that he is.”</p>\n<p>It was the hour when no stranger could remain in the cloister.<br>The two visitors withdrew. “Master,” said Gossip Tourangeau, as<br>he took leave of the archdeacon, “I love wise men and great<br>minds, and I hold you in singular esteem. Come to-morrow to the<br>Palace des Tournelles, and inquire for the Abbé de Sainte-Martin,<br>of Tours.”</p>\n<p>The archdeacon returned to his chamber dumbfounded, comprehending<br>at last who Gossip Tourangeau was, and recalling that passage of<br>the register of Sainte-Martin, of Tours:—_Abbas beati Martini,<br>SCILICET REX FRANCIÆ, est canonicus de consuetudine et habet<br>parvam præbendam quam habet sanctus Venantius, et debet sedere in<br>sede thesaurarii_.</p>\n<p>It is asserted that after that epoch the archdeacon had frequent<br>conferences with Louis XI., when his majesty came to Paris, and<br>that Dom Claude’s influence quite overshadowed that of Olivier le<br>Daim and Jacques Coictier, who, as was his habit, rudely took the<br>king to task on that account.</p>\n<h1 class=\"chapter\" id=\"chapter-ii-this-will-kill-that\">Chapter II. THIS WILL KILL THAT.</h1>\n<p>Our lady readers will pardon us if we pause for a moment to seek<br>what could have been the thought concealed beneath those<br>enigmatic words of the archdeacon: “This will kill that. The book<br>will kill the edifice.”</p>\n<p>To our mind, this thought had two faces. In the first place, it<br>was a priestly thought. It was the affright of the priest in the<br>presence of a new agent, the printing press. It was the terror<br>and dazzled amazement of the men of the sanctuary, in the<br>presence of the luminous press of Gutenberg. It was the pulpit<br>and the manuscript taking the alarm at the printed word:<br>something similar to the stupor of a sparrow which should behold<br>the angel Legion unfold his six million wings. It was the cry of<br>the prophet who already hears emancipated humanity roaring and<br>swarming; who beholds in the future, intelligence sapping faith,<br>opinion dethroning belief, the world shaking off Rome. It was the<br>prognostication of the philosopher who sees human thought,<br>volatilized by the press, evaporating from the theocratic<br>recipient. It was the terror of the soldier who examines the<br>brazen battering ram, and says:—“The tower will crumble.” It<br>signified that one power was about to succeed another power. It<br>meant, “The press will kill the church.”</p>\n<p>But underlying this thought, the first and most simple one, no<br>doubt, there was in our opinion another, newer one, a corollary<br>of the first, less easy to perceive and more easy to contest, a<br>view as philosophical and belonging no longer to the priest alone<br>but to the savant and the artist. It was a presentiment that<br>human thought, in changing its form, was about to change its mode<br>of expression; that the dominant idea of each generation would no<br>longer be written with the same matter, and in the same manner;<br>that the book of stone, so solid and so durable, was about to<br>make way for the book of paper, more solid and still more<br>durable. In this connection the archdeacon’s vague formula had a<br>second sense. It meant, “Printing will kill architecture.”</p>\n<p>In fact, from the origin of things down to the fifteenth century<br>of the Christian era, inclusive, architecture is the great book<br>of humanity, the principal expression of man in his different<br>stages of development, either as a force or as an intelligence.</p>\n<p>When the memory of the first races felt itself overloaded, when<br>the mass of reminiscences of the human race became so heavy and<br>so confused that speech naked and flying, ran the risk of losing<br>them on the way, men transcribed them on the soil in a manner<br>which was at once the most visible, most durable, and most<br>natural. They sealed each tradition beneath a monument.</p>\n<p>The first monuments were simple masses of rock, “which the iron<br>had not touched,” as Moses says. Architecture began like all<br>writing. It was first an alphabet. Men planted a stone upright,<br>it was a letter, and each letter was a hieroglyph, and upon each<br>hieroglyph rested a group of ideas, like the capital on the<br>column. This is what the earliest races did everywhere, at the<br>same moment, on the surface of the entire world. We find the<br>“standing stones” of the Celts in Asian Siberia; in the pampas of<br>America.</p>\n<p>Later on, they made words; they placed stone upon stone, they<br>coupled those syllables of granite, and attempted some<br>combinations. The Celtic dolmen and cromlech, the Etruscan<br>tumulus, the Hebrew galgal, are words. Some, especially the<br>tumulus, are proper names. Sometimes even, when men had a great<br>deal of stone, and a vast plain, they wrote a phrase. The immense<br>pile of Karnac is a complete sentence.</p>\n<p>At last they made books. Traditions had brought forth symbols,<br>beneath which they disappeared like the trunk of a tree beneath<br>its foliage; all these symbols in which humanity placed faith<br>continued to grow, to multiply, to intersect, to become more and<br>more complicated; the first monuments no longer sufficed to<br>contain them, they were overflowing in every part; these<br>monuments hardly expressed now the primitive tradition, simple<br>like themselves, naked and prone upon the earth. The symbol felt<br>the need of expansion in the edifice. Then architecture was<br>developed in proportion with human thought; it became a giant<br>with a thousand heads and a thousand arms, and fixed all this<br>floating symbolism in an eternal, visible, palpable form. While<br>Dædalus, who is force, measured; while Orpheus, who is<br>intelligence, sang;—the pillar, which is a letter; the arcade,<br>which is a syllable; the pyramid, which is a word,—all set in<br>movement at once by a law of geometry and by a law of poetry,<br>grouped themselves, combined, amalgamated, descended, ascended,<br>placed themselves side by side on the soil, ranged themselves in<br>stories in the sky, until they had written under the dictation of<br>the general idea of an epoch, those marvellous books which were<br>also marvellous edifices: the Pagoda of Eklinga, the Rhamseion of<br>Egypt, the Temple of Solomon.</p>\n<p>The generating idea, the word, was not only at the foundation of<br>all these edifices, but also in the form. The temple of Solomon,<br>for example, was not alone the binding of the holy book; it was<br>the holy book itself. On each one of its concentric walls, the<br>priests could read the word translated and manifested to the eye,<br>and thus they followed its transformations from sanctuary to<br>sanctuary, until they seized it in its last tabernacle, under its<br>most concrete form, which still belonged to architecture: the<br>arch. Thus the word was enclosed in an edifice, but its image was<br>upon its envelope, like the human form on the coffin of a mummy.</p>\n<p>And not only the form of edifices, but the sites selected for<br>them, revealed the thought which they represented, according as<br>the symbol to be expressed was graceful or grave. Greece crowned<br>her mountains with a temple harmonious to the eye; India<br>disembowelled hers, to chisel therein those monstrous<br>subterranean pagodas, borne up by gigantic rows of granite<br>elephants.</p>\n<p>Thus, during the first six thousand years of the world, from the<br>most immemorial pagoda of Hindustan, to the cathedral of Cologne,<br>architecture was the great handwriting of the human race. And<br>this is so true, that not only every religious symbol, but every<br>human thought, has its page and its monument in that immense<br>book.</p>\n<p>All civilization begins in theocracy and ends in democracy. This<br>law of liberty following unity is written in architecture. For,<br>let us insist upon this point, masonry must not be thought to be<br>powerful only in erecting the temple and in expressing the myth<br>and sacerdotal symbolism; in inscribing in hieroglyphs upon its<br>pages of stone the mysterious tables of the law. If it were<br>thus,—as there comes in all human society a moment when the<br>sacred symbol is worn out and becomes obliterated under freedom<br>of thought, when man escapes from the priest, when the<br>excrescence of philosophies and systems devour the face of<br>religion,—architecture could not reproduce this new state of<br>human thought; its leaves, so crowded on the face, would be empty<br>on the back; its work would be mutilated; its book would be<br>incomplete. But no.</p>\n<p>Let us take as an example the Middle Ages, where we see more<br>clearly because it is nearer to us. During its first period,<br>while theocracy is organizing Europe, while the Vatican is<br>rallying and reclassing about itself the elements of a Rome made<br>from the Rome which lies in ruins around the Capitol, while<br>Christianity is seeking all the stages of society amid the<br>rubbish of anterior civilization, and rebuilding with its ruins a<br>new hierarchic universe, the keystone to whose vault is the<br>priest—one first hears a dull echo from that chaos, and then,<br>little by little, one sees, arising from beneath the breath of<br>Christianity, from beneath the hand of the barbarians, from the<br>fragments of the dead Greek and Roman architectures, that<br>mysterious Romanesque architecture, sister of the theocratic<br>masonry of Egypt and of India, inalterable emblem of pure<br>catholicism, unchangeable hieroglyph of the papal unity. All the<br>thought of that day is written, in fact, in this sombre,<br>Romanesque style. One feels everywhere in it authority, unity,<br>the impenetrable, the absolute, Gregory VII.; always the priest,<br>never the man; everywhere caste, never the people.</p>\n<p>But the Crusades arrive. They are a great popular movement, and<br>every great popular movement, whatever may be its cause and<br>object, always sets free the spirit of liberty from its final<br>precipitate. New things spring into life every day. Here opens<br>the stormy period of the Jacqueries, Pragueries, and Leagues.<br>Authority wavers, unity is divided. Feudalism demands to share<br>with theocracy, while awaiting the inevitable arrival of the<br>people, who will assume the part of the lion: <em>Quia nominor leo</em>.<br>Seignory pierces through sacerdotalism; the commonality, through<br>seignory. The face of Europe is changed. Well! the face of<br>architecture is changed also. Like civilization, it has turned a<br>page, and the new spirit of the time finds her ready to write at<br>its dictation. It returns from the crusades with the pointed<br>arch, like the nations with liberty.</p>\n<p>Then, while Rome is undergoing gradual dismemberment, Romanesque<br>architecture dies. The hieroglyph deserts the cathedral, and<br>betakes itself to blazoning the donjon keep, in order to lend<br>prestige to feudalism. The cathedral itself, that edifice<br>formerly so dogmatic, invaded henceforth by the <em>bourgeoisie</em>, by<br>the community, by liberty, escapes the priest and falls into the<br>power of the artist. The artist builds it after his own fashion.<br>Farewell to mystery, myth, law. Fancy and caprice, welcome.<br>Provided the priest has his basilica and his altar, he has<br>nothing to say. The four walls belong to the artist. The<br>architectural book belongs no longer to the priest, to religion,<br>to Rome; it is the property of poetry, of imagination, of the<br>people. Hence the rapid and innumerable transformations of that<br>architecture which owns but three centuries, so striking after<br>the stagnant immobility of the Romanesque architecture, which<br>owns six or seven. Nevertheless, art marches on with giant<br>strides. Popular genius amid originality accomplish the task<br>which the bishops formerly fulfilled. Each race writes its line<br>upon the book, as it passes; it erases the ancient Romanesque<br>hieroglyphs on the frontispieces of cathedrals, and at the most<br>one only sees dogma cropping out here and there, beneath the new<br>symbol which it has deposited. The popular drapery hardly permits<br>the religious skeleton to be suspected. One cannot even form an<br>idea of the liberties which the architects then take, even toward<br>the Church. There are capitals knitted of nuns and monks,<br>shamelessly coupled, as on the hall of chimney pieces in the<br>Palais de Justice, in Paris. There is Noah’s adventure carved to<br>the last detail, as under the great portal of Bourges. There is a<br>bacchanalian monk, with ass’s ears and glass in hand, laughing in<br>the face of a whole community, as on the lavatory of the Abbey of<br>Bocherville. There exists at that epoch, for thought written in<br>stone, a privilege exactly comparable to our present liberty of<br>the press. It is the liberty of architecture.</p>\n<p>This liberty goes very far. Sometimes a portal, a façade, an<br>entire church, presents a symbolical sense absolutely foreign to<br>worship, or even hostile to the Church. In the thirteenth<br>century, Guillaume de Paris, and Nicholas Flamel, in the<br>fifteenth, wrote such seditious pages. Saint-Jacques de la<br>Boucherie was a whole church of the opposition.</p>\n<p>Thought was then free only in this manner; hence it never wrote<br>itself out completely except on the books called edifices.<br>Thought, under the form of edifice, could have beheld itself<br>burned in the public square by the hands of the executioner, in<br>its manuscript form, if it had been sufficiently imprudent to<br>risk itself thus; thought, as the door of a church, would have<br>been a spectator of the punishment of thought as a book. Having<br>thus only this resource, masonry, in order to make its way to the<br>light, flung itself upon it from all quarters. Hence the immense<br>quantity of cathedrals which have covered Europe—a number so<br>prodigious that one can hardly believe it even after having<br>verified it. All the material forces, all the intellectual forces<br>of society converged towards the same point: architecture. In<br>this manner, under the pretext of building churches to God, art<br>was developed in its magnificent proportions.</p>\n<p>Then whoever was born a poet became an architect. Genius,<br>scattered in the masses, repressed in every quarter under<br>feudalism as under a <em>testudo</em> of brazen bucklers, finding no<br>issue except in the direction of architecture,—gushed forth<br>through that art, and its Iliads assumed the form of cathedrals.<br>All other arts obeyed, and placed themselves under the discipline<br>of architecture. They were the workmen of the great work. The<br>architect, the poet, the master, summed up in his person the<br>sculpture which carved his façades, painting which illuminated<br>his windows, music which set his bells to pealing, and breathed<br>into his organs. There was nothing down to poor poetry,—properly<br>speaking, that which persisted in vegetating in<br>manuscripts,—which was not forced, in order to make something of<br>itself, to come and frame itself in the edifice in the shape of a<br>hymn or of prose; the same part, after all, which the tragedies<br>of Æschylus had played in the sacerdotal festivals of Greece;<br>Genesis, in the temple of Solomon.</p>\n<p>Thus, down to the time of Gutenberg, architecture is the<br>principal writing, the universal writing. In that granite book,<br>begun by the Orient, continued by Greek and Roman antiquity, the<br>Middle Ages wrote the last page. Moreover, this phenomenon of an<br>architecture of the people following an architecture of caste,<br>which we have just been observing in the Middle Ages, is<br>reproduced with every analogous movement in the human<br>intelligence at the other great epochs of history. Thus, in order<br>to enunciate here only summarily, a law which it would require<br>volumes to develop: in the high Orient, the cradle of primitive<br>times, after Hindoo architecture came Phœnician architecture,<br>that opulent mother of Arabian architecture; in antiquity, after<br>Egyptian architecture, of which Etruscan style and cyclopean<br>monuments are but one variety, came Greek architecture (of which<br>the Roman style is only a continuation), surcharged with the<br>Carthaginian dome; in modern times, after Romanesque architecture<br>came Gothic architecture. And by separating there three series<br>into their component parts, we shall find in the three eldest<br>sisters, Hindoo architecture, Egyptian architecture, Romanesque<br>architecture, the same symbol; that is to say, theocracy, caste,<br>unity, dogma, myth, God: and for the three younger sisters,<br>Phœnician architecture, Greek architecture, Gothic architecture,<br>whatever, nevertheless, may be the diversity of form inherent in<br>their nature, the same signification also; that is to say,<br>liberty, the people, man.</p>\n<p>In the Hindu, Egyptian, or Romanesque architecture, one feels the<br>priest, nothing but the priest, whether he calls himself Brahmin,<br>Magian, or Pope. It is not the same in the architectures of the<br>people. They are richer and less sacred. In the Phœnician, one<br>feels the merchant; in the Greek, the republican; in the Gothic,<br>the citizen.</p>\n<p>The general characteristics of all theocratic architecture are<br>immutability, horror of progress, the preservation of traditional<br>lines, the consecration of the primitive types, the constant<br>bending of all the forms of men and of nature to the<br>incomprehensible caprices of the symbol. These are dark books,<br>which the initiated alone understand how to decipher. Moreover,<br>every form, every deformity even, has there a sense which renders<br>it inviolable. Do not ask of Hindoo, Egyptian, Romanesque masonry<br>to reform their design, or to improve their statuary. Every<br>attempt at perfecting is an impiety to them. In these<br>architectures it seems as though the rigidity of the dogma had<br>spread over the stone like a sort of second petrifaction. The<br>general characteristics of popular masonry, on the contrary, are<br>progress, originality, opulence, perpetual movement. They are<br>already sufficiently detached from religion to think of their<br>beauty, to take care of it, to correct without relaxation their<br>parure of statues or arabesques. They are of the age. They have<br>something human, which they mingle incessantly with the divine<br>symbol under which they still produce. Hence, edifices<br>comprehensible to every soul, to every intelligence, to every<br>imagination, symbolical still, but as easy to understand as<br>nature. Between theocratic architecture and this there is the<br>difference that lies between a sacred language and a vulgar<br>language, between hieroglyphics and art, between Solomon and<br>Phidias.</p>\n<p>If the reader will sum up what we have hitherto briefly, very<br>briefly, indicated, neglecting a thousand proofs and also a<br>thousand objections of detail, he will be led to this: that<br>architecture was, down to the fifteenth century, the chief<br>register of humanity; that in that interval not a thought which<br>is in any degree complicated made its appearance in the world,<br>which has not been worked into an edifice; that every popular<br>idea, and every religious law, has had its monumental records;<br>that the human race has, in short, had no important thought which<br>it has not written in stone. And why? Because every thought,<br>either philosophical or religious, is interested in perpetuating<br>itself; because the idea which has moved one generation wishes to<br>move others also, and leave a trace. Now, what a precarious<br>immortality is that of the manuscript! How much more solid,<br>durable, unyielding, is a book of stone! In order to destroy the<br>written word, a torch and a Turk are sufficient. To demolish the<br>constructed word, a social revolution, a terrestrial revolution<br>are required. The barbarians passed over the Coliseum; the<br>deluge, perhaps, passed over the Pyramids.</p>\n<p>In the fifteenth century everything changes.</p>\n<p>Human thought discovers a mode of perpetuating itself, not only<br>more durable and more resisting than architecture, but still more<br>simple and easy. Architecture is dethroned. Gutenberg’s letters<br>of lead are about to supersede Orpheus’s letters of stone.</p>\n<p><em>The book is about to kill the edifice</em>.</p>\n<p>The invention of printing is the greatest event in history. It is<br>the mother of revolution. It is the mode of expression of<br>humanity which is totally renewed; it is human thought stripping<br>off one form and donning another; it is the complete and<br>definitive change of skin of that symbolical serpent which since<br>the days of Adam has represented intelligence.</p>\n<p>In its printed form, thought is more imperishable than ever; it<br>is volatile, irresistible, indestructible. It is mingled with the<br>air. In the days of architecture it made a mountain of itself,<br>and took powerful possession of a century and a place. Now it<br>converts itself into a flock of birds, scatters itself to the<br>four winds, and occupies all points of air and space at once.</p>\n<p>We repeat, who does not perceive that in this form it is far more<br>indelible? It was solid, it has become alive. It passes from<br>duration in time to immortality. One can demolish a mass; how can<br>one extirpate ubiquity? If a flood comes, the mountains will have<br>long disappeared beneath the waves, while the birds will still be<br>flying about; and if a single ark floats on the surface of the<br>cataclysm, they will alight upon it, will float with it, will be<br>present with it at the ebbing of the waters; and the new world<br>which emerges from this chaos will behold, on its awakening, the<br>thought of the world which has been submerged soaring above it,<br>winged and living.</p>\n<p>And when one observes that this mode of expression is not only<br>the most conservative, but also the most simple, the most<br>convenient, the most practicable for all; when one reflects that<br>it does not drag after it bulky baggage, and does not set in<br>motion a heavy apparatus; when one compares thought forced, in<br>order to transform itself into an edifice, to put in motion four<br>or five other arts and tons of gold, a whole mountain of stones,<br>a whole forest of timber-work, a whole nation of workmen; when<br>one compares it to the thought which becomes a book, and for<br>which a little paper, a little ink, and a pen suffice,—how can<br>one be surprised that human intelligence should have quitted<br>architecture for printing? Cut the primitive bed of a river<br>abruptly with a canal hollowed out below its level, and the river<br>will desert its bed.</p>\n<p>Behold how, beginning with the discovery of printing,<br>architecture withers away little by little, becomes lifeless and<br>bare. How one feels the water sinking, the sap departing, the<br>thought of the times and of the people withdrawing from it! The<br>chill is almost imperceptible in the fifteenth century; the press<br>is, as yet, too weak, and, at the most, draws from powerful<br>architecture a superabundance of life. But practically beginning<br>with the sixteenth century, the malady of architecture is<br>visible; it is no longer the expression of society; it becomes<br>classic art in a miserable manner; from being Gallic, European,<br>indigenous, it becomes Greek and Roman; from being true and<br>modern, it becomes pseudo-classic. It is this decadence which is<br>called the Renaissance. A magnificent decadence, however, for the<br>ancient Gothic genius, that sun which sets behind the gigantic<br>press of Mayence, still penetrates for a while longer with its<br>rays that whole hybrid pile of Latin arcades and Corinthian<br>columns.</p>\n<p>It is that setting sun which we mistake for the dawn.</p>\n<p>Nevertheless, from the moment when architecture is no longer<br>anything but an art like any other; as soon as it is no longer<br>the total art, the sovereign art, the tyrant art,—it has no<br>longer the power to retain the other arts. So they emancipate<br>themselves, break the yoke of the architect, and take themselves<br>off, each one in its own direction. Each one of them gains by<br>this divorce. Isolation aggrandizes everything. Sculpture becomes<br>statuary, the image trade becomes painting, the canon becomes<br>music. One would pronounce it an empire dismembered at the death<br>of its Alexander, and whose provinces become kingdoms.</p>\n<p>Hence Raphael, Michael Angelo, Jean Goujon, Palestrina, those<br>splendors of the dazzling sixteenth century.</p>\n<p>Thought emancipates itself in all directions at the same time as<br>the arts. The arch-heretics of the Middle Ages had already made<br>large incisions into Catholicism. The sixteenth century breaks<br>religious unity. Before the invention of printing, reform would<br>have been merely a schism; printing converted it into a<br>revolution. Take away the press; heresy is enervated. Whether it<br>be Providence or Fate, Gutenburg is the precursor of Luther.</p>\n<p>Nevertheless, when the sun of the Middle Ages is completely set,<br>when the Gothic genius is forever extinct upon the horizon,<br>architecture grows dim, loses its color, becomes more and more<br>effaced. The printed book, the gnawing worm of the edifice, sucks<br>and devours it. It becomes bare, denuded of its foliage, and<br>grows visibly emaciated. It is petty, it is poor, it is nothing.<br>It no longer expresses anything, not even the memory of the art<br>of another time. Reduced to itself, abandoned by the other arts,<br>because human thought is abandoning it, it summons bunglers in<br>place of artists. Glass replaces the painted windows. The<br>stone-cutter succeeds the sculptor. Farewell all sap, all<br>originality, all life, all intelligence. It drags along, a<br>lamentable workshop mendicant, from copy to copy. Michael Angelo,<br>who, no doubt, felt even in the sixteenth century that it was<br>dying, had a last idea, an idea of despair. That Titan of art<br>piled the Pantheon on the Parthenon, and made Saint-Peter’s at<br>Rome. A great work, which deserved to remain unique, the last<br>originality of architecture, the signature of a giant artist at<br>the bottom of the colossal register of stone which was closed<br>forever. With Michael Angelo dead, what does this miserable<br>architecture, which survived itself in the state of a spectre,<br>do? It takes Saint-Peter in Rome, copies it and parodies it. It<br>is a mania. It is a pity. Each century has its Saint-Peter’s of<br>Rome; in the seventeenth century, the Val-de-Grâce; in the<br>eighteenth, Sainte-Geneviève. Each country has its Saint-Peter’s<br>of Rome. London has one; Petersburg has another; Paris has two or<br>three. The insignificant testament, the last dotage of a decrepit<br>grand art falling back into infancy before it dies.</p>\n<p>If, in place of the characteristic monuments which we have just<br>described, we examine the general aspect of art from the<br>sixteenth to the eighteenth century, we notice the same phenomena<br>of decay and phthisis. Beginning with François II., the<br>architectural form of the edifice effaces itself more and more,<br>and allows the geometrical form, like the bony structure of an<br>emaciated invalid, to become prominent. The fine lines of art<br>give way to the cold and inexorable lines of geometry. An edifice<br>is no longer an edifice; it is a polyhedron. Meanwhile,<br>architecture is tormented in her struggles to conceal this<br>nudity. Look at the Greek pediment inscribed upon the Roman<br>pediment, and vice versâ. It is still the Pantheon on the<br>Parthenon: Saint-Peter’s of Rome. Here are the brick houses of<br>Henri IV., with their stone corners; the Place Royale, the Place<br>Dauphine. Here are the churches of Louis XIII., heavy, squat,<br>thickset, crowded together, loaded with a dome like a hump. Here<br>is the Mazarin architecture, the wretched Italian pasticcio of<br>the Four Nations. Here are the palaces of Louis XIV., long<br>barracks for courtiers, stiff, cold, tiresome. Here, finally, is<br>Louis XV., with chiccory leaves and vermicelli, and all the<br>warts, and all the fungi, which disfigure that decrepit,<br>toothless, and coquettish old architecture. From François II. to<br>Louis XV., the evil has increased in geometrical progression. Art<br>has no longer anything but skin upon its bones. It is miserably<br>perishing.</p>\n<p>Meanwhile what becomes of printing? All the life which is leaving<br>architecture comes to it. In proportion as architecture ebbs,<br>printing swells and grows. That capital of forces which human<br>thought had been expending in edifices, it henceforth expends in<br>books. Thus, from the sixteenth century onward, the press, raised<br>to the level of decaying architecture, contends with it and kills<br>it. In the seventeenth century it is already sufficiently the<br>sovereign, sufficiently triumphant, sufficiently established in<br>its victory, to give to the world the feast of a great literary<br>century. In the eighteenth, having reposed for a long time at the<br>Court of Louis XIV., it seizes again the old sword of Luther,<br>puts it into the hand of Voltaire, and rushes impetuously to the<br>attack of that ancient Europe, whose architectural expression it<br>has already killed. At the moment when the eighteenth century<br>comes to an end, it has destroyed everything. In the nineteenth,<br>it begins to reconstruct.</p>\n<p>Now, we ask, which of the three arts has really represented human<br>thought for the last three centuries? which translates it? which<br>expresses not only its literary and scholastic vagaries, but its<br>vast, profound, universal movement? which constantly superposes<br>itself, without a break, without a gap, upon the human race,<br>which walks a monster with a thousand legs?—Architecture or<br>printing?</p>\n<p>It is printing. Let the reader make no mistake; architecture is<br>dead; irretrievably slain by the printed book,—slain because it<br>endures for a shorter time,—slain because it costs more. Every<br>cathedral represents millions. Let the reader now imagine what an<br>investment of funds it would require to rewrite the architectural<br>book; to cause thousands of edifices to swarm once more upon the<br>soil; to return to those epochs when the throng of monuments was<br>such, according to the statement of an eye witness, “that one<br>would have said that the world in shaking itself, had cast off<br>its old garments in order to cover itself with a white vesture of<br>churches.” _Erat enim ut si mundus, ipse excutiendo semet,<br>rejecta vetustate, candidam ecclesiarum vestem indueret_. (GLABER<br>RADOLPHUS.)</p>\n<p>A book is so soon made, costs so little, and can go so far! How<br>can it surprise us that all human thought flows in this channel?<br>This does not mean that architecture will not still have a fine<br>monument, an isolated masterpiece, here and there. We may still<br>have from time to time, under the reign of printing, a column<br>made I suppose, by a whole army from melted cannon, as we had<br>under the reign of architecture, Iliads and Romanceros,<br>Mahabâhrata, and Nibelungen Lieds, made by a whole people, with<br>rhapsodies piled up and melted together. The great accident of an<br>architect of genius may happen in the twentieth century, like<br>that of Dante in the thirteenth. But architecture will no longer<br>be the social art, the collective art, the dominating art. The<br>grand poem, the grand edifice, the grand work of humanity will no<br>longer be built: it will be printed.</p>\n<p>And henceforth, if architecture should arise again accidentally,<br>it will no longer be mistress. It will be subservient to the law<br>of literature, which formerly received the law from it. The<br>respective positions of the two arts will be inverted. It is<br>certain that in architectural epochs, the poems, rare it is true,<br>resemble the monuments. In India, Vyasa is branching, strange,<br>impenetrable as a pagoda. In Egyptian Orient, poetry has like the<br>edifices, grandeur and tranquillity of line; in antique Greece,<br>beauty, serenity, calm; in Christian Europe, the Catholic<br>majesty, the popular naïvete, the rich and luxuriant vegetation<br>of an epoch of renewal. The Bible resembles the Pyramids; the<br>Iliad, the Parthenon; Homer, Phidias. Dante in the thirteenth<br>century is the last Romanesque church; Shakespeare in the<br>sixteenth, the last Gothic cathedral.</p>\n<p>Thus, to sum up what we have hitherto said, in a fashion which is<br>necessarily incomplete and mutilated, the human race has two<br>books, two registers, two testaments: masonry and printing; the<br>Bible of stone and the Bible of paper. No doubt, when one<br>contemplates these two Bibles, laid so broadly open in the<br>centuries, it is permissible to regret the visible majesty of the<br>writing of granite, those gigantic alphabets formulated in<br>colonnades, in pylons, in obelisks, those sorts of human<br>mountains which cover the world and the past, from the pyramid to<br>the bell tower, from Cheops to Strasbourg. The past must be<br>reread upon these pages of marble. This book, written by<br>architecture, must be admired and perused incessantly; but the<br>grandeur of the edifice which printing erects in its turn must<br>not be denied.</p>\n<p>That edifice is colossal. Some compiler of statistics has<br>calculated, that if all the volumes which have issued from the<br>press since Gutenberg’s day were to be piled one upon another,<br>they would fill the space between the earth and the moon; but it<br>is not that sort of grandeur of which we wished to speak.<br>Nevertheless, when one tries to collect in one’s mind a<br>comprehensive image of the total products of printing down to our<br>own days, does not that total appear to us like an immense<br>construction, resting upon the entire world, at which humanity<br>toils without relaxation, and whose monstrous crest is lost in<br>the profound mists of the future? It is the anthill of<br>intelligence. It is the hive whither come all imaginations, those<br>golden bees, with their honey.</p>\n<p>The edifice has a thousand stories. Here and there one beholds on<br>its staircases the gloomy caverns of science which pierce its<br>interior. Everywhere upon its surface, art causes its arabesques,<br>rosettes, and laces to thrive luxuriantly before the eyes. There,<br>every individual work, however capricious and isolated it may<br>seem, has its place and its projection. Harmony results from the<br>whole. From the cathedral of Shakespeare to the mosque of Byron,<br>a thousand tiny bell towers are piled pell-mell above this<br>metropolis of universal thought. At its base are written some<br>ancient titles of humanity which architecture had not registered.<br>To the left of the entrance has been fixed the ancient<br>bas-relief, in white marble, of Homer; to the right, the polyglot<br>Bible rears its seven heads. The hydra of the Romancero and some<br>other hybrid forms, the Vedas and the Nibelungen bristle further<br>on.</p>\n<p>Nevertheless, the prodigious edifice still remains incomplete.<br>The press, that giant machine, which incessantly pumps all the<br>intellectual sap of society, belches forth without pause fresh<br>materials for its work. The whole human race is on the<br>scaffoldings. Each mind is a mason. The humblest fills his hole,<br>or places his stone. Rétif de La Bretonne brings his hod of<br>plaster. Every day a new course rises. Independently of the<br>original and individual contribution of each writer, there are<br>collective contingents. The eighteenth century gives the<br><em>Encyclopedia</em>, the revolution gives the <em>Moniteur</em>. Assuredly,<br>it is a construction which increases and piles up in endless<br>spirals; there also are confusion of tongues, incessant activity,<br>indefatigable labor, eager competition of all humanity, refuge<br>promised to intelligence, a new Flood against an overflow of<br>barbarians. It is the second tower of Babel of the human race.</p>\n<p>BOOK SIXTH.</p>\n<h1 class=\"chapter\" id=\"chapter-i-an-impartial-glance-at-the-ancient-mag\">Chapter I. AN IMPARTIAL GLANCE AT THE ANCIENT MAGISTRACY.</h1>\n<p>A very happy personage in the year of grace 1482, was the noble<br>gentleman Robert d’Estouteville, chevalier, Sieur de Beyne, Baron<br>d’Ivry and Saint Andry en la Marche, counsellor and chamberlain<br>to the king, and guard of the provostship of Paris. It was<br>already nearly seventeen years since he had received from the<br>king, on November 7, 1465, the comet year,[27] that fine charge<br>of the provostship of Paris, which was reputed rather a seigneury<br>than an office. <em>Dignitas</em>, says Joannes Lœmnœus, _quæ cum non<br>exigua potestate politiam concernente, atque prærogativis multis<br>et juribus conjuncta est_. A marvellous thing in ’82 was a<br>gentleman bearing the king’s commission, and whose letters of<br>institution ran back to the epoch of the marriage of the natural<br>daughter of Louis XI. with Monsieur the Bastard of Bourbon.</p>\n<p>The same day on which Robert d’Estouteville took the place of<br>Jacques de Villiers in the provostship of Paris, Master Jehan<br>Dauvet replaced Messire Helye de Thorrettes in the first<br>presidency of the Court of Parliament, Jehan Jouvenel des Ursins<br>supplanted Pierre de Morvilliers in the office of chancellor of<br>France, Regnault des Dormans ousted Pierre Puy from the charge of<br>master of requests in ordinary of the king’s household. Now, upon<br>how many heads had the presidency, the chancellorship, the<br>mastership passed since Robert d’Estouteville had held the<br>provostship of Paris. It had been “granted to him for<br>safekeeping,” as the letters patent said; and certainly he kept<br>it well. He had clung to it, he had incorporated himself with it,<br>he had so identified himself with it that he had escaped that<br>fury for change which possessed Louis XI., a tormenting and<br>industrious king, whose policy it was to maintain the elasticity<br>of his power by frequent appointments and revocations. More than<br>this; the brave chevalier had obtained the reversion of the<br>office for his son, and for two years already, the name of the<br>noble man Jacques d’Estouteville, equerry, had figured beside his<br>at the head of the register of the salary list of the provostship<br>of Paris. A rare and notable favor indeed! It is true that Robert<br>d’Estouteville was a good soldier, that he had loyally raised his<br>pennon against “the league of public good,” and that he had<br>presented to the queen a very marvellous stag in confectionery on<br>the day of her entrance to Paris in 14.... Moreover, he possessed<br>the good friendship of Messire Tristan l’Hermite, provost of the<br>marshals of the king’s household. Hence a very sweet and pleasant<br>existence was that of Messire Robert. In the first place, very<br>good wages, to which were attached, and from which hung, like<br>extra bunches of grapes on his vine, the revenues of the civil<br>and criminal registries of the provostship, plus the civil and<br>criminal revenues of the tribunals of Embas of the Châtelet,<br>without reckoning some little toll from the bridges of Mantes and<br>of Corbeil, and the profits on the craft of Shagreen-makers of<br>Paris, on the corders of firewood and the measurers of salt. Add<br>to this the pleasure of displaying himself in rides about the<br>city, and of making his fine military costume, which you may<br>still admire sculptured on his tomb in the abbey of Valmont in<br>Normandy, and his morion, all embossed at Montlhéry, stand out a<br>contrast against the parti-colored red and tawny robes of the<br>aldermen and police. And then, was it nothing to wield absolute<br>supremacy over the sergeants of the police, the porter and watch<br>of the Châtelet, the two auditors of the Châtelet, _auditores<br>castelleti_, the sixteen commissioners of the sixteen quarters,<br>the jailer of the Châtelet, the four enfeoffed sergeants, the<br>hundred and twenty mounted sergeants, with maces, the chevalier<br>of the watch with his watch, his sub-watch, his counter-watch and<br>his rear-watch? Was it nothing to exercise high and low justice,<br>the right to interrogate, to hang and to draw, without reckoning<br>petty jurisdiction in the first resort (<em>in prima instantia</em>, as<br>the charters say), on that viscomty of Paris, so nobly appanaged<br>with seven noble bailiwicks? Can anything sweeter be imagined<br>than rendering judgments and decisions, as Messire Robert<br>d’Estouteville daily did in the Grand Châtelet, under the large<br>and flattened arches of Philip Augustus? and going, as he was<br>wont to do every evening, to that charming house situated in the<br>Rue Galilée, in the enclosure of the royal palace, which he held<br>in right of his wife, Madame Ambroise de Loré, to repose after<br>the fatigue of having sent some poor wretch to pass the night in<br>“that little cell of the Rue de Escorcherie, which the provosts<br>and aldermen of Paris used to make their prison; the same being<br>eleven feet long, seven feet and four inches wide, and eleven<br>feet high?”[28]</p>\n<p>And not only had Messire Robert d’Estouteville his special court<br>as provost and vicomte of Paris; but in addition he had a share,<br>both for eye and tooth, in the grand court of the king. There was<br>no head in the least elevated which had not passed through his<br>hands before it came to the headsman. It was he who went to seek<br>M. de Nemours at the Bastille Saint Antoine, in order to conduct<br>him to the Halles; and to conduct to the Grève M. de Saint-Pol,<br>who clamored and resisted, to the great joy of the provost, who<br>did not love monsieur the constable.</p>\n<p>Here, assuredly, is more than sufficient to render a life happy<br>and illustrious, and to deserve some day a notable page in that<br>interesting history of the provosts of Paris, where one learns<br>that Oudard de Villeneuve had a house in the Rue des Boucheries,<br>that Guillaume de Hangest purchased the great and the little<br>Savoy, that Guillaume Thiboust gave the nuns of Sainte-Geneviève<br>his houses in the Rue Clopin, that Hugues Aubriot lived in the<br>Hôtel du Porc-Épic, and other domestic facts.</p>\n<p>Nevertheless, with so many reasons for taking life patiently and<br>joyously, Messire Robert d’Estouteville woke up on the morning of<br>the seventh of January, 1482, in a very surly and peevish mood.<br>Whence came this ill temper? He could not have told himself. Was<br>it because the sky was gray? or was the buckle of his old belt of<br>Montlhéry badly fastened, so that it confined his provostal<br>portliness too closely? had he beheld ribald fellows, marching in<br>bands of four, beneath his window, and setting him at defiance,<br>in doublets but no shirts, hats without crowns, with wallet and<br>bottle at their side? Was it a vague presentiment of the three<br>hundred and seventy livres, sixteen sous, eight farthings, which<br>the future King Charles VII. was to cut off from the provostship<br>in the following year? The reader can take his choice; we, for<br>our part, are much inclined to believe that he was in a bad<br>humor, simply because he was in a bad humor.</p>\n<p>Moreover, it was the day after a festival, a tiresome day for<br>every one, and above all for the magistrate who is charged with<br>sweeping away all the filth, properly and figuratively speaking,<br>which a festival day produces in Paris. And then he had to hold a<br>sitting at the Grand Châtelet. Now, we have noticed that judges<br>in general so arrange matters that their day of audience shall<br>also be their day of bad humor, so that they may always have some<br>one upon whom to vent it conveniently, in the name of the king,<br>law, and justice.</p>\n<p>However, the audience had begun without him. His lieutenants,<br>civil, criminal, and private, were doing his work, according to<br>usage; and from eight o’clock in the morning, some scores of<br><em>bourgeois</em> and <em>bourgeoises</em>, heaped and crowded into an obscure<br>corner of the audience chamber of Embas du Châtelet, between a<br>stout oaken barrier and the wall, had been gazing blissfully at<br>the varied and cheerful spectacle of civil and criminal justice<br>dispensed by Master Florian Barbedienne, auditor of the Châtelet,<br>lieutenant of monsieur the provost, in a somewhat confused and<br>utterly haphazard manner.</p>\n<p>The hall was small, low, vaulted. A table studded with<br>fleurs-de-lis stood at one end, with a large arm-chair of carved<br>oak, which belonged to the provost and was empty, and a stool on<br>the left for the auditor, Master Florian. Below sat the clerk of<br>the court, scribbling; opposite was the populace; and in front of<br>the door, and in front of the table were many sergeants of the<br>provostship in sleeveless jackets of violet camlet, with white<br>crosses. Two sergeants of the Parloir-aux-Bourgeois, clothed in<br>their jackets of Toussaint, half red, half blue, were posted as<br>sentinels before a low, closed door, which was visible at the<br>extremity of the hall, behind the table. A single pointed window,<br>narrowly encased in the thick wall, illuminated with a pale ray<br>of January sun two grotesque figures,—the capricious demon of<br>stone carved as a tail-piece in the keystone of the vaulted<br>ceiling, and the judge seated at the end of the hall on the<br>fleurs-de-lis.</p>\n<p>Imagine, in fact, at the provost’s table, leaning upon his elbows<br>between two bundles of documents of cases, with his foot on the<br>train of his robe of plain brown cloth, his face buried in his<br>hood of white lamb’s skin, of which his brows seemed to be of a<br>piece, red, crabbed, winking, bearing majestically the load of<br>fat on his cheeks which met under his chin, Master Florian<br>Barbedienne, auditor of the Châtelet.</p>\n<p>Now, the auditor was deaf. A slight defect in an auditor. Master<br>Florian delivered judgment, none the less, without appeal and<br>very suitably. It is certainly quite sufficient for a judge to<br>have the air of listening; and the venerable auditor fulfilled<br>this condition, the sole one in justice, all the better because<br>his attention could not be distracted by any noise.</p>\n<p>Moreover, he had in the audience, a pitiless censor of his deeds<br>and gestures, in the person of our friend Jehan Frollo du Moulin,<br>that little student of yesterday, that “stroller,” whom one was<br>sure of encountering all over Paris, anywhere except before the<br>rostrums of the professors.</p>\n<p>“Stay,” he said in a low tone to his companion, Robin Poussepain,<br>who was grinning at his side, while he was making his comments on<br>the scenes which were being unfolded before his eyes, “yonder is<br>Jehanneton du Buisson. The beautiful daughter of the lazy dog at<br>the Marché-Neuf!—Upon my soul, he is condemning her, the old<br>rascal! he has no more eyes than ears. Fifteen sous, four<br>farthings, parisian, for having worn two rosaries! ’Tis somewhat<br>dear. <em>Lex duri carminis</em>. Who’s that? Robin Chief-de-Ville,<br>hauberkmaker. For having been passed and received master of the<br>said trade! That’s his entrance money. He! two gentlemen among<br>these knaves! Aiglet de Soins, Hutin de Mailly Two equerries,<br><em>Corpus Christi!</em> Ah! they have been playing at dice. When shall<br>I see our rector here? A hundred livres parisian, fine to the<br>king! That Barbedienne strikes like a deaf man,—as he is! I’ll be<br>my brother the archdeacon, if that keeps me from gaming; gaming<br>by day, gaming by night, living at play, dying at play, and<br>gaming away my soul after my shirt. Holy Virgin, what damsels!<br>One after the other my lambs. Ambroise Lécuyère, Isabeau la<br>Paynette, Bérarde Gironin! I know them all, by Heavens! A fine! a<br>fine! That’s what will teach you to wear gilded girdles! ten sous<br>parisis! you coquettes! Oh! the old snout of a judge! deaf and<br>imbecile! Oh! Florian the dolt! Oh! Barbedienne the blockhead!<br>There he is at the table! He’s eating the plaintiff, he’s eating<br>the suits, he eats, he chews, he crams, he fills himself. Fines,<br>lost goods, taxes, expenses, loyal charges, salaries, damages,<br>and interests, gehenna, prison, and jail, and fetters with<br>expenses are Christmas spice cake and marchpanes of Saint-John to<br>him! Look at him, the pig!—Come! Good! Another amorous woman!<br>Thibaud-la-Thibaude, neither more nor less! For having come from<br>the Rue Glatigny! What fellow is this? Gieffroy Mabonne, gendarme<br>bearing the crossbow. He has cursed the name of the Father. A<br>fine for la Thibaude! A fine for Gieffroy! A fine for them both!<br>The deaf old fool! he must have mixed up the two cases! Ten to<br>one that he makes the wench pay for the oath and the gendarme for<br>the amour! Attention, Robin Poussepain! What are they going to<br>bring in? Here are many sergeants! By Jupiter! all the<br>bloodhounds of the pack are there. It must be the great beast of<br>the hunt—a wild boar. And ’tis one, Robin, ’tis one. And a fine<br>one too! <em>Hercle!</em> ’tis our prince of yesterday, our Pope of the<br>Fools, our bellringer, our one-eyed man, our hunchback, our<br>grimace! ’Tis Quasimodo!”</p>\n<p>It was he indeed.</p>\n<p>It was Quasimodo, bound, encircled, roped, pinioned, and under<br>good guard. The squad of policemen who surrounded him was<br>assisted by the chevalier of the watch in person, wearing the<br>arms of France embroidered on his breast, and the arms of the<br>city on his back. There was nothing, however, about Quasimodo,<br>except his deformity, which could justify the display of halberds<br>and arquebuses; he was gloomy, silent, and tranquil. Only now and<br>then did his single eye cast a sly and wrathful glance upon the<br>bonds with which he was loaded.</p>\n<p>He cast the same glance about him, but it was so dull and sleepy<br>that the women only pointed him out to each other in derision.</p>\n<p>Meanwhile Master Florian, the auditor, turned over attentively<br>the document in the complaint entered against Quasimodo, which<br>the clerk handed him, and, having thus glanced at it, appeared to<br>reflect for a moment. Thanks to this precaution, which he always<br>was careful to take at the moment when on the point of beginning<br>an examination, he knew beforehand the names, titles, and<br>misdeeds of the accused, made cut and dried responses to<br>questions foreseen, and succeeded in extricating himself from all<br>the windings of the interrogation without allowing his deafness<br>to be too apparent. The written charges were to him what the dog<br>is to the blind man. If his deafness did happen to betray him<br>here and there, by some incoherent apostrophe or some<br>unintelligible question, it passed for profundity with some, and<br>for imbecility with others. In neither case did the honor of the<br>magistracy sustain any injury; for it is far better that a judge<br>should be reputed imbecile or profound than deaf. Hence he took<br>great care to conceal his deafness from the eyes of all, and he<br>generally succeeded so well that he had reached the point of<br>deluding himself, which is, by the way, easier than is supposed.<br>All hunchbacks walk with their heads held high, all stutterers<br>harangue, all deaf people speak low. As for him, he believed, at<br>the most, that his ear was a little refractory. It was the sole<br>concession which he made on this point to public opinion, in his<br>moments of frankness and examination of his conscience.</p>\n<p>Having, then, thoroughly ruminated Quasimodo’s affair, he threw<br>back his head and half closed his eyes, for the sake of more<br>majesty and impartiality, so that, at that moment, he was both<br>deaf and blind. A double condition, without which no judge is<br>perfect. It was in this magisterial attitude that he began the<br>examination.</p>\n<p>“Your name?”</p>\n<p>Now this was a case which had not been “provided for by law,”<br>where a deaf man should be obliged to question a deaf man.</p>\n<p>Quasimodo, whom nothing warned that a question had been addressed<br>to him, continued to stare intently at the judge, and made no<br>reply. The judge, being deaf, and being in no way warned of the<br>deafness of the accused, thought that the latter had answered, as<br>all accused do in general, and therefore he pursued, with his<br>mechanical and stupid self-possession,—</p>\n<p>“Very well. And your age?”</p>\n<p>Again Quasimodo made no reply to this question. The judge<br>supposed that it had been replied to, and continued,—</p>\n<p>“Now, your profession?”</p>\n<p>Still the same silence. The spectators had begun, meanwhile, to<br>whisper together, and to exchange glances.</p>\n<p>“That will do,” went on the imperturbable auditor, when he<br>supposed that the accused had finished his third reply. “You are<br>accused before us, <em>primo</em>, of nocturnal disturbance; <em>secundo</em>,<br>of a dishonorable act of violence upon the person of a foolish<br>woman, <em>in præjudicium meretricis; tertio</em>, of rebellion and<br>disloyalty towards the archers of the police of our lord, the<br>king. Explain yourself upon all these points.—Clerk, have you<br>written down what the prisoner has said thus far?”</p>\n<p>At this unlucky question, a burst of laughter rose from the<br>clerk’s table caught by the audience, so violent, so wild, so<br>contagious, so universal, that the two deaf men were forced to<br>perceive it. Quasimodo turned round, shrugging his hump with<br>disdain, while Master Florian, equally astonished, and supposing<br>that the laughter of the spectators had been provoked by some<br>irreverent reply from the accused, rendered visible to him by<br>that shrug of the shoulders, apostrophized him indignantly,—</p>\n<p>“You have uttered a reply, knave, which deserves the halter. Do<br>you know to whom you are speaking?”</p>\n<p>This sally was not fitted to arrest the explosion of general<br>merriment. It struck all as so whimsical, and so ridiculous, that<br>the wild laughter even attacked the sergeants of the<br>Parloi-aux-Bourgeois, a sort of pikemen, whose stupidity was part<br>of their uniform. Quasimodo alone preserved his seriousness, for<br>the good reason that he understood nothing of what was going on<br>around him. The judge, more and more irritated, thought it his<br>duty to continue in the same tone, hoping thereby to strike the<br>accused with a terror which should react upon the audience, and<br>bring it back to respect.</p>\n<p>“So this is as much as to say, perverse and thieving knave that<br>you are, that you permit yourself to be lacking in respect<br>towards the Auditor of the Châtelet, to the magistrate committed<br>to the popular police of Paris, charged with searching out<br>crimes, delinquencies, and evil conduct; with controlling all<br>trades, and interdicting monopoly; with maintaining the<br>pavements; with debarring the hucksters of chickens, poultry, and<br>water-fowl; of superintending the measuring of fagots and other<br>sorts of wood; of purging the city of mud, and the air of<br>contagious maladies; in a word, with attending continually to<br>public affairs, without wages or hope of salary! Do you know that<br>I am called Florian Barbedienne, actual lieutenant to monsieur<br>the provost, and, moreover, commissioner, inquisitor,<br><em>controller</em>, and examiner, with equal power in provostship,<br>bailiwick, preservation, and inferior court of judicature?—”</p>\n<p>There is no reason why a deaf man talking to a deaf man should<br>stop. God knows where and when Master Florian would have landed,<br>when thus launched at full speed in lofty eloquence, if the low<br>door at the extreme end of the room had not suddenly opened, and<br>given entrance to the provost in person. At his entrance Master<br>Florian did not stop short, but, making a half-turn on his heels,<br>and aiming at the provost the harangue with which he had been<br>withering Quasimodo a moment before,—</p>\n<p>“Monseigneur,” said he, “I demand such penalty as you shall deem<br>fitting against the prisoner here present, for grave and<br>aggravated offence against the court.”</p>\n<p>And he seated himself, utterly breathless, wiping away the great<br>drops of sweat which fell from his brow and drenched, like tears,<br>the parchments spread out before him. Messire Robert<br>d’Estouteville frowned and made a gesture so imperious and<br>significant to Quasimodo, that the deaf man in some measure<br>understood it.</p>\n<p>The provost addressed him with severity, “What have you done that<br>you have been brought hither, knave?”</p>\n<p>The poor fellow, supposing that the provost was asking his name,<br>broke the silence which he habitually preserved, and replied, in<br>a harsh and guttural voice, “Quasimodo.”</p>\n<p>The reply matched the question so little that the wild laugh<br>began to circulate once more, and Messire Robert exclaimed, red<br>with wrath,—</p>\n<p>“Are you mocking me also, you arrant knave?”</p>\n<p>“Bellringer of Notre-Dame,” replied Quasimodo, supposing that<br>what was required of him was to explain to the judge who he was.</p>\n<p>“Bellringer!” interpolated the provost, who had waked up early<br>enough to be in a sufficiently bad temper, as we have said, not<br>to require to have his fury inflamed by such strange responses.<br>“Bellringer! I’ll play you a chime of rods on your back through<br>the squares of Paris! Do you hear, knave?”</p>\n<p>“If it is my age that you wish to know,” said Quasimodo, “I think<br>that I shall be twenty at Saint Martin’s day.”</p>\n<p>This was too much; the provost could no longer restrain himself.</p>\n<p>“Ah! you are scoffing at the provostship, wretch! Messieurs the<br>sergeants of the mace, you will take me this knave to the pillory<br>of the Grève, you will flog him, and turn him for an hour. He<br>shall pay me for it, <em>tête Dieu!</em> And I order that the present<br>judgment shall be cried, with the assistance of four sworn<br>trumpeters, in the seven castellanies of the viscomty of Paris.”</p>\n<p>The clerk set to work incontinently to draw up the account of the<br>sentence.</p>\n<p>“<em>Ventre Dieu!</em> ’tis well adjudged!” cried the little scholar,<br>Jehan Frollo du Moulin, from his corner.</p>\n<p>The provost turned and fixed his flashing eyes once more on<br>Quasimodo. “I believe the knave said ‘<em>Ventre Dieu!</em>’ Clerk, add<br>twelve deniers Parisian for the oath, and let the vestry of Saint<br>Eustache have the half of it; I have a particular devotion for<br>Saint Eustache.”</p>\n<p>In a few minutes the sentence was drawn up. Its tenor was simple<br>and brief. The customs of the provostship and the viscomty had<br>not yet been worked over by President Thibaut Baillet, and by<br>Roger Barmne, the king’s advocate; they had not been obstructed,<br>at that time, by that lofty hedge of quibbles and procedures,<br>which the two jurisconsults planted there at the beginning of the<br>sixteenth century. All was clear, expeditious, explicit. One went<br>straight to the point then, and at the end of every path there<br>was immediately visible, without thickets and without turnings;<br>the wheel, the gibbet, or the pillory. One at least knew whither<br>one was going.</p>\n<p>The clerk presented the sentence to the provost, who affixed his<br>seal to it, and departed to pursue his round of the audience<br>hall, in a frame of mind which seemed destined to fill all the<br>jails in Paris that day. Jehan Frollo and Robin Poussepain<br>laughed in their sleeves. Quasimodo gazed on the whole with an<br>indifferent and astonished air.</p>\n<p>However, at the moment when Master Florian Barbedienne was<br>reading the sentence in his turn, before signing it, the clerk<br>felt himself moved with pity for the poor wretch of a prisoner,<br>and, in the hope of obtaining some mitigation of the penalty, he<br>approached as near the auditor’s ear as possible, and said,<br>pointing to Quasimodo, “That man is deaf.”</p>\n<p>He hoped that this community of infirmity would awaken Master<br>Florian’s interest in behalf of the condemned man. But, in the<br>first place, we have already observed that Master Florian did not<br>care to have his deafness noticed. In the next place, he was so<br>hard of hearing that he did not catch a single word of what the<br>clerk said to him; nevertheless, he wished to have the appearance<br>of hearing, and replied, “Ah! ah! that is different; I did not<br>know that. An hour more of the pillory, in that case.”</p>\n<p>And he signed the sentence thus modified.</p>\n<p>“’Tis well done,” said Robin Poussepain, who cherished a grudge<br>against Quasimodo. “That will teach him to handle people<br>roughly.”</p>\n<h1 class=\"chapter\" id=\"chapter-ii-the-rat-hole\">Chapter II. THE RAT-HOLE.</h1>\n<p>The reader must permit us to take him back to the Place de Grève,<br>which we quitted yesterday with Gringoire, in order to follow la<br>Esmeralda.</p>\n<p>It is ten o’clock in the morning; everything is indicative of the<br>day after a festival. The pavement is covered with rubbish;<br>ribbons, rags, feathers from tufts of plumes, drops of wax from<br>the torches, crumbs of the public feast. A goodly number of<br><em>bourgeois</em> are “sauntering,” as we say, here and there, turning<br>over with their feet the extinct brands of the bonfire, going<br>into raptures in front of the Pillar House, over the memory of<br>the fine hangings of the day before, and to-day staring at the<br>nails that secured them a last pleasure. The venders of cider and<br>beer are rolling their barrels among the groups. Some busy<br>passers-by come and go. The merchants converse and call to each<br>other from the thresholds of their shops. The festival, the<br>ambassadors, Coppenole, the Pope of the Fools, are in all mouths;<br>they vie with each other, each trying to criticise it best and<br>laugh the most. And, meanwhile, four mounted sergeants, who have<br>just posted themselves at the four sides of the pillory, have<br>already concentrated around themselves a goodly proportion of the<br>populace scattered on the Place, who condemn themselves to<br>immobility and fatigue in the hope of a small execution.</p>\n<p>If the reader, after having contemplated this lively and noisy<br>scene which is being enacted in all parts of the Place, will now<br>transfer his gaze towards that ancient demi-Gothic,<br>demi-Romanesque house of the Tour-Roland, which forms the corner<br>on the quay to the west, he will observe, at the angle of the<br>façade, a large public breviary, with rich illuminations,<br>protected from the rain by a little penthouse, and from thieves<br>by a small grating, which, however, permits of the leaves being<br>turned. Beside this breviary is a narrow, arched window, closed<br>by two iron bars in the form of a cross, and looking on the<br>square; the only opening which admits a small quantity of light<br>and air to a little cell without a door, constructed on the<br>ground-floor, in the thickness of the walls of the old house, and<br>filled with a peace all the more profound, with a silence all the<br>more gloomy, because a public place, the most populous and most<br>noisy in Paris swarms and shrieks around it.</p>\n<p>This little cell had been celebrated in Paris for nearly three<br>centuries, ever since Madame Rolande de la Tour-Roland, in<br>mourning for her father who died in the Crusades, had caused it<br>to be hollowed out in the wall of her own house, in order to<br>immure herself there forever, keeping of all her palace only this<br>lodging whose door was walled up, and whose window stood open,<br>winter and summer, giving all the rest to the poor and to God.<br>The afflicted damsel had, in fact, waited twenty years for death<br>in this premature tomb, praying night and day for the soul of her<br>father, sleeping in ashes, without even a stone for a pillow,<br>clothed in a black sack, and subsisting on the bread and water<br>which the compassion of the passers-by led them to deposit on the<br>ledge of her window, thus receiving charity after having bestowed<br>it. At her death, at the moment when she was passing to the other<br>sepulchre, she had bequeathed this one in perpetuity to afflicted<br>women, mothers, widows, or maidens, who should wish to pray much<br>for others or for themselves, and who should desire to inter<br>themselves alive in a great grief or a great penance. The poor of<br>her day had made her a fine funeral, with tears and benedictions;<br>but, to their great regret, the pious maid had not been<br>canonized, for lack of influence. Those among them who were a<br>little inclined to impiety, had hoped that the matter might be<br>accomplished in Paradise more easily than at Rome, and had<br>frankly besought God, instead of the pope, in behalf of the<br>deceased. The majority had contented themselves with holding the<br>memory of Rolande sacred, and converting her rags into relics.<br>The city, on its side, had founded in honor of the damoiselle, a<br>public breviary, which had been fastened near the window of the<br>cell, in order that passers-by might halt there from time to<br>time, were it only to pray; that prayer might remind them of<br>alms, and that the poor recluses, heiresses of Madame Rolande’s<br>vault, might not die outright of hunger and forgetfulness.</p>\n<p>Moreover, this sort of tomb was not so very rare a thing in the<br>cities of the Middle Ages. One often encountered in the most<br>frequented street, in the most crowded and noisy market, in the<br>very middle, under the feet of the horses, under the wheels of<br>the carts, as it were, a cellar, a well, a tiny walled and grated<br>cabin, at the bottom of which a human being prayed night and day,<br>voluntarily devoted to some eternal lamentation, to some great<br>expiation. And all the reflections which that strange spectacle<br>would awaken in us to-day; that horrible cell, a sort of<br>intermediary link between a house and the tomb, the cemetery and<br>the city; that living being cut off from the human community, and<br>thenceforth reckoned among the dead; that lamp consuming its last<br>drop of oil in the darkness; that remnant of life flickering in<br>the grave; that breath, that voice, that eternal prayer in a box<br>of stone; that face forever turned towards the other world; that<br>eye already illuminated with another sun; that ear pressed to the<br>walls of a tomb; that soul a prisoner in that body; that body a<br>prisoner in that dungeon cell, and beneath that double envelope<br>of flesh and granite, the murmur of that soul in pain;—nothing of<br>all this was perceived by the crowd. The piety of that age, not<br>very subtle nor much given to reasoning, did not see so many<br>facets in an act of religion. It took the thing in the block,<br>honored, venerated, hallowed the sacrifice at need, but did not<br>analyze the sufferings, and felt but moderate pity for them. It<br>brought some pittance to the miserable penitent from time to<br>time, looked through the hole to see whether he were still<br>living, forgot his name, hardly knew how many years ago he had<br>begun to die, and to the stranger, who questioned them about the<br>living skeleton who was perishing in that cellar, the neighbors<br>replied simply, “It is the recluse.”</p>\n<p>Everything was then viewed without metaphysics, without<br>exaggeration, without magnifying glass, with the naked eye. The<br>microscope had not yet been invented, either for things of matter<br>or for things of the mind.</p>\n<p>Moreover, although people were but little surprised by it, the<br>examples of this sort of cloistration in the hearts of cities<br>were in truth frequent, as we have just said. There were in Paris<br>a considerable number of these cells, for praying to God and<br>doing penance; they were nearly all occupied. It is true that the<br>clergy did not like to have them empty, since that implied<br>lukewarmness in believers, and that lepers were put into them<br>when there were no penitents on hand. Besides the cell on the<br>Grève, there was one at Montfaucon, one at the Charnier des<br>Innocents, another I hardly know where,—at the Clichon House, I<br>think; others still at many spots where traces of them are found<br>in traditions, in default of memorials. The University had also<br>its own. On Mount Sainte-Geneviève a sort of Job of the Middle<br>Ages, for the space of thirty years, chanted the seven<br>penitential psalms on a dunghill at the bottom of a cistern,<br>beginning anew when he had finished, singing loudest at night,<br><em>magna voce per umbras</em>, and to-day, the antiquary fancies that<br>he hears his voice as he enters the Rue du Puits-qui-parle—the<br>street of the “Speaking Well.”</p>\n<p>To confine ourselves to the cell in the Tour-Roland, we must say<br>that it had never lacked recluses. After the death of Madame<br>Roland, it had stood vacant for a year or two, though rarely.<br>Many women had come thither to mourn, until their death, for<br>relatives, lovers, faults. Parisian malice, which thrusts its<br>finger into everything, even into things which concern it the<br>least, affirmed that it had beheld but few widows there.</p>\n<p>In accordance with the fashion of the epoch, a Latin inscription<br>on the wall indicated to the learned passer-by the pious purpose<br>of this cell. The custom was retained until the middle of the<br>sixteenth century of explaining an edifice by a brief device<br>inscribed above the door. Thus, one still reads in France, above<br>the wicket of the prison in the seignorial mansion of Tourville,<br><em>Sileto et spera</em>; in Ireland, beneath the armorial bearings<br>which surmount the grand door to Fortescue Castle, _Forte scutum,<br>salus ducum_; in England, over the principal entrance to the<br>hospitable mansion of the Earls Cowper: <em>Tuum est</em>. At that time<br>every edifice was a thought.</p>\n<p>As there was no door to the walled cell of the Tour-Roland, these<br>two words had been carved in large Roman capitals over the<br>window,—</p>\n<p>TU, ORA.</p>\n<p>And this caused the people, whose good sense does not perceive so<br>much refinement in things, and likes to translate _Ludovico<br>Magno<em> by </em>Porte Saint-Denis_, to give to this dark, gloomy, damp<br>cavity, the name of “The Rat-Hole.” An explanation less sublime,<br>perhaps, than the other; but, on the other hand, more<br>picturesque.</p>\n<h1 class=\"chapter\" id=\"chapter-iii-history-of-a-leavened-cake-of-maize\">Chapter III. HISTORY OF A LEAVENED CAKE OF MAIZE.</h1>\n<p>At the epoch of this history, the cell in the Tour-Roland was<br>occupied. If the reader desires to know by whom, he has only to<br>lend an ear to the conversation of three worthy gossips, who, at<br>the moment when we have directed his attention to the Rat-Hole,<br>were directing their steps towards the same spot, coming up along<br>the water’s edge from the Châtelet, towards the Grève.</p>\n<p>Two of these women were dressed like good <em>bourgeoises</em> of Paris.<br>Their fine white ruffs; their petticoats of linsey-woolsey,<br>striped red and blue; their white knitted stockings, with clocks<br>embroidered in colors, well drawn upon their legs; the<br>square-toed shoes of tawny leather with black soles, and, above<br>all, their headgear, that sort of tinsel horn, loaded down with<br>ribbons and laces, which the women of Champagne still wear, in<br>company with the grenadiers of the imperial guard of Russia,<br>announced that they belonged to that class wives which holds the<br>middle ground between what the lackeys call a woman and what they<br>term a lady. They wore neither rings nor gold crosses, and it was<br>easy to see that, in their ease, this did not proceed from<br>poverty, but simply from fear of being fined. Their companion was<br>attired in very much the same manner; but there was that<br>indescribable something about her dress and bearing which<br>suggested the wife of a provincial notary. One could see, by the<br>way in which her girdle rose above her hips, that she had not<br>been long in Paris. Add to this a plaited tucker, knots of ribbon<br>on her shoes—and that the stripes of her petticoat ran<br>horizontally instead of vertically, and a thousand other<br>enormities which shocked good taste.</p>\n<p>The two first walked with that step peculiar to Parisian ladies,<br>showing Paris to women from the country. The provincial held by<br>the hand a big boy, who held in his a large, flat cake.</p>\n<p>We regret to be obliged to add, that, owing to the rigor of the<br>season, he was using his tongue as a handkerchief.</p>\n<p>The child was making them drag him along, <em>non passibus æquis</em>,<br>as Virgil says, and stumbling at every moment, to the great<br>indignation of his mother. It is true that he was looking at his<br>cake more than at the pavement. Some serious motive, no doubt,<br>prevented his biting it (the cake), for he contented himself with<br>gazing tenderly at it. But the mother should have rather taken<br>charge of the cake. It was cruel to make a Tantalus of the<br>chubby-cheeked boy.</p>\n<p>Meanwhile, the three demoiselles (for the name of <em>dames</em> was<br>then reserved for noble women) were all talking at once.</p>\n<p>“Let us make haste, Demoiselle Mahiette,” said the youngest of<br>the three, who was also the largest, to the provincial, “I<br>greatly fear that we shall arrive too late; they told us at the<br>Châtelet that they were going to take him directly to the<br>pillory.”</p>\n<p>“Ah, bah! what are you saying, Demoiselle Oudarde Musnier?”<br>interposed the other Parisienne. “There are two hours yet to the<br>pillory. We have time enough. Have you ever seen any one<br>pilloried, my dear Mahiette?”</p>\n<p>“Yes,” said the provincial, “at Reims.”</p>\n<p>“Ah, bah! What is your pillory at Reims? A miserable cage into<br>which only peasants are turned. A great affair, truly!”</p>\n<p>“Only peasants!” said Mahiette, “at the cloth market in Reims! We<br>have seen very fine criminals there, who have killed their father<br>and mother! Peasants! For what do you take us, Gervaise?”</p>\n<p>It is certain that the provincial was on the point of taking<br>offence, for the honor of her pillory. Fortunately, that discreet<br>damoiselle, Oudarde Musnier, turned the conversation in time.</p>\n<p>“By the way, Damoiselle Mahiette, what say you to our Flemish<br>Ambassadors? Have you as fine ones at Reims?”</p>\n<p>“I admit,” replied Mahiette, “that it is only in Paris that such<br>Flemings can be seen.”</p>\n<p>“Did you see among the embassy, that big ambassador who is a<br>hosier?” asked Oudarde.</p>\n<p>“Yes,” said Mahiette. “He has the eye of a Saturn.”</p>\n<p>“And the big fellow whose face resembles a bare belly?” resumed<br>Gervaise. “And the little one, with small eyes framed in red<br>eyelids, pared down and slashed up like a thistle head?”</p>\n<p>“’Tis their horses that are worth seeing,” said Oudarde,<br>“caparisoned as they are after the fashion of their country!”</p>\n<p>“Ah my dear,” interrupted provincial Mahiette, assuming in her<br>turn an air of superiority, “what would you say then, if you had<br>seen in ’61, at the consecration at Reims, eighteen years ago,<br>the horses of the princes and of the king’s company? Housings and<br>caparisons of all sorts; some of damask cloth, of fine cloth of<br>gold, furred with sables; others of velvet, furred with ermine;<br>others all embellished with goldsmith’s work and large bells of<br>gold and silver! And what money that had cost! And what handsome<br>boy pages rode upon them!”</p>\n<p>“That,” replied Oudarde dryly, “does not prevent the Flemings<br>having very fine horses, and having had a superb supper yesterday<br>with monsieur, the provost of the merchants, at the<br>Hôtel-de-Ville, where they were served with comfits and<br>hippocras, and spices, and other singularities.”</p>\n<p>“What are you saying, neighbor!” exclaimed Gervaise. “It was with<br>monsieur the cardinal, at the Petit Bourbon that they supped.”</p>\n<p>“Not at all. At the Hôtel-de-Ville.</p>\n<p>“Yes, indeed. At the Petit Bourbon!”</p>\n<p>“It was at the Hôtel-de-Ville,” retorted Oudarde sharply, “and<br>Dr. Scourable addressed them a harangue in Latin, which pleased<br>them greatly. My husband, who is sworn bookseller told me so.”</p>\n<p>“It was at the Petit Bourbon,” replied Gervaise, with no less<br>spirit, “and this is what monsieur the cardinal’s procurator<br>presented to them: twelve double quarts of hippocras, white,<br>claret, and red; twenty-four boxes of double Lyons marchpane,<br>gilded; as many torches, worth two livres a piece; and six<br>demi-queues[29] of Beaune wine, white and claret, the best that<br>could be found. I have it from my husband, who is a<br>cinquantenier[30], at the Parloir-aux Bourgeois, and who was this<br>morning comparing the Flemish ambassadors with those of Prester<br>John and the Emperor of Trebizond, who came from Mesopotamia to<br>Paris, under the last king, and who wore rings in their ears.”</p>\n<p>“So true is it that they supped at the Hôtel-de-Ville,” replied<br>Oudarde but little affected by this catalogue, “that such a<br>triumph of viands and comfits has never been seen.”</p>\n<p>“I tell you that they were served by Le Sec, sergeant of the<br>city, at the Hôtel du Petit-Bourbon, and that that is where you<br>are mistaken.”</p>\n<p>“At the Hôtel-de-Ville, I tell you!”</p>\n<p>“At the Petit-Bourbon, my dear! and they had illuminated with<br>magic glasses the word <em>Hope</em>, which is written on the grand<br>portal.”</p>\n<p>“At the Hôtel-de-Ville! At the Hôtel-de-Ville! And Husson-le-Voir<br>played the flute!”</p>\n<p>“I tell you, no!”</p>\n<p>“I tell you, yes!”</p>\n<p>“I say, no!”</p>\n<p>Plump and worthy Oudarde was preparing to retort, and the quarrel<br>might, perhaps, have proceeded to a pulling of caps, had not<br>Mahiette suddenly exclaimed,—“Look at those people assembled<br>yonder at the end of the bridge! There is something in their<br>midst that they are looking at!”</p>\n<p>“In sooth,” said Gervaise, “I hear the sounds of a tambourine. I<br>believe ’tis the little Esmeralda, who plays her mummeries with<br>her goat. Eh, be quick, Mahiette! redouble your pace and drag<br>along your boy. You are come hither to visit the curiosities of<br>Paris. You saw the Flemings yesterday; you must see the gypsy<br>to-day.”</p>\n<p>“The gypsy!” said Mahiette, suddenly retracing her steps, and<br>clasping her son’s arm forcibly. “God preserve me from it! She<br>would steal my child from me! Come, Eustache!”</p>\n<p>And she set out on a run along the quay towards the Grève, until<br>she had left the bridge far behind her. In the meanwhile, the<br>child whom she was dragging after her fell upon his knees; she<br>halted breathless. Oudarde and Gervaise rejoined her.</p>\n<p>“That gypsy steal your child from you!” said Gervaise. “That’s a<br>singular freak of yours!”</p>\n<p>Mahiette shook her head with a pensive air.</p>\n<p>“The singular point is,” observed Oudarde, “that <em>la sachette</em><br>has the same idea about the Egyptian woman.”</p>\n<p>“What is <em>la sachette</em>?” asked Mahiette.</p>\n<p>“Hé!” said Oudarde, “Sister Gudule.”</p>\n<p>“And who is Sister Gudule?” persisted Mahiette.</p>\n<p>“You are certainly ignorant of all but your Reims, not to know<br>that!” replied Oudarde. “’Tis the recluse of the Rat-Hole.”</p>\n<p>“What!” demanded Mahiette, “that poor woman to whom we are<br>carrying this cake?”</p>\n<p>Oudarde nodded affirmatively.</p>\n<p>“Precisely. You will see her presently at her window on the<br>Grève. She has the same opinion as yourself of these vagabonds of<br>Egypt, who play the tambourine and tell fortunes to the public.<br>No one knows whence comes her horror of the gypsies and<br>Egyptians. But you, Mahiette—why do you run so at the mere sight<br>of them?”</p>\n<p>“Oh!” said Mahiette, seizing her child’s round head in both<br>hands, “I don’t want that to happen to me which happened to<br>Paquette la Chantefleurie.”</p>\n<p>“Oh! you must tell us that story, my good Mahiette,” said<br>Gervaise, taking her arm.</p>\n<p>“Gladly,” replied Mahiette, “but you must be ignorant of all but<br>your Paris not to know that! I will tell you then (but ’tis not<br>necessary for us to halt that I may tell you the tale), that<br>Paquette la Chantefleurie was a pretty maid of eighteen when I<br>was one myself, that is to say, eighteen years ago, and ’tis her<br>own fault if she is not to-day, like me, a good, plump, fresh<br>mother of six and thirty, with a husband and a son. However,<br>after the age of fourteen, it was too late! Well, she was the<br>daughter of Guybertant, minstrel of the barges at Reims, the same<br>who had played before King Charles VII., at his coronation, when<br>he descended our river Vesle from Sillery to Muison, when Madame<br>the Maid of Orleans was also in the boat. The old father died<br>when Paquette was still a mere child; she had then no one but her<br>mother, the sister of M. Pradon, master-brazier and coppersmith<br>in Paris, Rue Parin-Garlin, who died last year. You see she was<br>of good family. The mother was a good simple woman,<br>unfortunately, and she taught Paquette nothing but a bit of<br>embroidery and toy-making which did not prevent the little one<br>from growing very large and remaining very poor. They both dwelt<br>at Reims, on the river front, Rue de Folle-Peine. Mark this: For<br>I believe it was this which brought misfortune to Paquette. In<br>’61, the year of the coronation of our King Louis XI. whom God<br>preserve! Paquette was so gay and so pretty that she was called<br>everywhere by no other name than <em>la Chantefleurie</em>—blossoming<br>song. Poor girl! She had handsome teeth, she was fond of laughing<br>and displaying them. Now, a maid who loves to laugh is on the<br>road to weeping; handsome teeth ruin handsome eyes. So she was la<br>Chantefleurie. She and her mother earned a precarious living;<br>they had been very destitute since the death of the minstrel;<br>their embroidery did not bring them in more than six farthings a<br>week, which does not amount to quite two eagle liards. Where were<br>the days when Father Guybertant had earned twelve sous parisian,<br>in a single coronation, with a song? One winter (it was in that<br>same year of ’61), when the two women had neither fagots nor<br>firewood, it was very cold, which gave la Chantefleurie such a<br>fine color that the men called her Paquette![31] and many called<br>her Pâquerette![32] and she was ruined.—Eustache, just let me see<br>you bite that cake if you dare!—We immediately perceived that she<br>was ruined, one Sunday when she came to church with a gold cross<br>about her neck. At fourteen years of age! do you see? First it<br>was the young Vicomte de Cormontreuil, who has his bell tower<br>three leagues distant from Reims; then Messire Henri de<br>Triancourt, equerry to the King; then less than that, Chiart de<br>Beaulion, sergeant-at-arms; then, still descending, Guery<br>Aubergeon, carver to the King; then, Macé de Frépus, barber to<br>monsieur the dauphin; then, Thévenin le Moine, King’s cook; then,<br>the men growing continually younger and less noble, she fell to<br>Guillaume Racine, minstrel of the hurdy-gurdy and to Thierry de<br>Mer, lamplighter. Then, poor Chantefleurie, she belonged to every<br>one: she had reached the last sou of her gold piece. What shall I<br>say to you, my damoiselles? At the coronation, in the same year,<br>’61, ’twas she who made the bed of the king of the debauchees! In<br>the same year!”</p>\n<p>Mahiette sighed, and wiped away a tear which trickled from her<br>eyes.</p>\n<p>“This is no very extraordinary history,” said Gervaise, “and in<br>the whole of it I see nothing of any Egyptian women or children.”</p>\n<p>“Patience!” resumed Mahiette, “you will see one child.—In ’66,<br>’twill be sixteen years ago this month, at Sainte-Paule’s day,<br>Paquette was brought to bed of a little girl. The unhappy<br>creature! it was a great joy to her; she had long wished for a<br>child. Her mother, good woman, who had never known what to do<br>except to shut her eyes, her mother was dead. Paquette had no<br>longer any one to love in the world or any one to love her. La<br>Chantefleurie had been a poor creature during the five years<br>since her fall. She was alone, alone in this life, fingers were<br>pointed at her, she was hooted at in the streets, beaten by the<br>sergeants, jeered at by the little boys in rags. And then, twenty<br>had arrived: and twenty is an old age for amorous women. Folly<br>began to bring her in no more than her trade of embroidery in<br>former days; for every wrinkle that came, a crown fled; winter<br>became hard to her once more, wood became rare again in her<br>brazier, and bread in her cupboard. She could no longer work<br>because, in becoming voluptuous, she had grown lazy; and she<br>suffered much more because, in growing lazy, she had become<br>voluptuous. At least, that is the way in which monsieur the curé<br>of Saint-Remy explains why these women are colder and hungrier<br>than other poor women, when they are old.”</p>\n<p>“Yes,” remarked Gervaise, “but the gypsies?”</p>\n<p>“One moment, Gervaise!” said Oudarde, whose attention was less<br>impatient. “What would be left for the end if all were in the<br>beginning? Continue, Mahiette, I entreat you. That poor<br>Chantefleurie!”</p>\n<p>Mahiette went on.</p>\n<p>“So she was very sad, very miserable, and furrowed her cheeks<br>with tears. But in the midst of her shame, her folly, her<br>debauchery, it seemed to her that she should be less wild, less<br>shameful, less dissipated, if there were something or some one in<br>the world whom she could love, and who could love her. It was<br>necessary that it should be a child, because only a child could<br>be sufficiently innocent for that. She had recognized this fact<br>after having tried to love a thief, the only man who wanted her;<br>but after a short time, she perceived that the thief despised<br>her. Those women of love require either a lover or a child to<br>fill their hearts. Otherwise, they are very unhappy. As she could<br>not have a lover, she turned wholly towards a desire for a child,<br>and as she had not ceased to be pious, she made her constant<br>prayer to the good God for it. So the good God took pity on her,<br>and gave her a little daughter. I will not speak to you of her<br>joy; it was a fury of tears, and caresses, and kisses. She nursed<br>her child herself, made swaddling-bands for it out of her<br>coverlet, the only one which she had on her bed, and no longer<br>felt either cold or hunger. She became beautiful once more, in<br>consequence of it. An old maid makes a young mother. Gallantry<br>claimed her once more; men came to see la Chantefleurie; she<br>found customers again for her merchandise, and out of all these<br>horrors she made baby clothes, caps and bibs, bodices with<br>shoulder-straps of lace, and tiny bonnets of satin, without even<br>thinking of buying herself another coverlet.—Master Eustache, I<br>have already told you not to eat that cake.—It is certain that<br>little Agnès, that was the child’s name, a baptismal name, for it<br>was a long time since la Chantefleurie had had any surname—it is<br>certain that that little one was more swathed in ribbons and<br>embroideries than a dauphiness of Dauphiny! Among other things,<br>she had a pair of little shoes, the like of which King Louis XI.<br>certainly never had! Her mother had stitched and embroidered them<br>herself; she had lavished on them all the delicacies of her art<br>of embroideress, and all the embellishments of a robe for the<br>good Virgin. They certainly were the two prettiest little pink<br>shoes that could be seen. They were no longer than my thumb, and<br>one had to see the child’s little feet come out of them, in order<br>to believe that they had been able to get into them. ’Tis true<br>that those little feet were so small, so pretty, so rosy! rosier<br>than the satin of the shoes! When you have children, Oudarde, you<br>will find that there is nothing prettier than those little hands<br>and feet.”</p>\n<p>“I ask no better,” said Oudarde with a sigh, “but I am waiting<br>until it shall suit the good pleasure of M. Andry Musnier.”</p>\n<p>“However, Paquette’s child had more that was pretty about it<br>besides its feet. I saw her when she was only four months old;<br>she was a love! She had eyes larger than her mouth, and the most<br>charming black hair, which already curled. She would have been a<br>magnificent brunette at the age of sixteen! Her mother became<br>more crazy over her every day. She kissed her, caressed her,<br>tickled her, washed her, decked her out, devoured her! She lost<br>her head over her, she thanked God for her. Her pretty, little<br>rosy feet above all were an endless source of wonderment, they<br>were a delirium of joy! She was always pressing her lips to them,<br>and she could never recover from her amazement at their<br>smallness. She put them into the tiny shoes, took them out,<br>admired them, marvelled at them, looked at the light through<br>them, was curious to see them try to walk on her bed, and would<br>gladly have passed her life on her knees, putting on and taking<br>off the shoes from those feet, as though they had been those of<br>an Infant Jesus.”</p>\n<p>“The tale is fair and good,” said Gervaise in a low tone; “but<br>where do gypsies come into all that?”</p>\n<p>“Here,” replied Mahiette. “One day there arrived in Reims a very<br>queer sort of people. They were beggars and vagabonds who were<br>roaming over the country, led by their duke and their counts.<br>They were browned by exposure to the sun, they had closely<br>curling hair, and silver rings in their ears. The women were<br>still uglier than the men. They had blacker faces, which were<br>always uncovered, a miserable frock on their bodies, an old cloth<br>woven of cords bound upon their shoulder, and their hair hanging<br>like the tail of a horse. The children who scrambled between<br>their legs would have frightened as many monkeys. A band of<br>excommunicates. All these persons came direct from lower Egypt to<br>Reims through Poland. The Pope had confessed them, it was said,<br>and had prescribed to them as penance to roam through the world<br>for seven years, without sleeping in a bed; and so they were<br>called penancers, and smelt horribly. It appears that they had<br>formerly been Saracens, which was why they believed in Jupiter,<br>and claimed ten livres of Tournay from all archbishops, bishops,<br>and mitred abbots with croziers. A bull from the Pope empowered<br>them to do that. They came to Reims to tell fortunes in the name<br>of the King of Algiers, and the Emperor of Germany. You can<br>readily imagine that no more was needed to cause the entrance to<br>the town to be forbidden them. Then the whole band camped with<br>good grace outside the gate of Braine, on that hill where stands<br>a mill, beside the cavities of the ancient chalk pits. And<br>everybody in Reims vied with his neighbor in going to see them.<br>They looked at your hand, and told you marvellous prophecies;<br>they were equal to predicting to Judas that he would become Pope.<br>Nevertheless, ugly rumors were in circulation in regard to them;<br>about children stolen, purses cut, and human flesh devoured. The<br>wise people said to the foolish: “Don’t go there!” and then went<br>themselves on the sly. It was an infatuation. The fact is, that<br>they said things fit to astonish a cardinal. Mothers triumphed<br>greatly over their little ones after the Egyptians had read in<br>their hands all sorts of marvels written in pagan and in Turkish.<br>One had an emperor; another, a pope; another, a captain. Poor<br>Chantefleurie was seized with curiosity; she wished to know about<br>herself, and whether her pretty little Agnès would not become<br>some day Empress of Armenia, or something else. So she carried<br>her to the Egyptians; and the Egyptian women fell to admiring the<br>child, and to caressing it, and to kissing it with their black<br>mouths, and to marvelling over its little band, alas! to the<br>great joy of the mother. They were especially enthusiastic over<br>her pretty feet and shoes. The child was not yet a year old. She<br>already lisped a little, laughed at her mother like a little mad<br>thing, was plump and quite round, and possessed a thousand<br>charming little gestures of the angels of paradise.</p>\n<p>“She was very much frightened by the Egyptians, and wept. But her<br>mother kissed her more warmly and went away enchanted with the<br>good fortune which the soothsayers had foretold for her Agnès.<br>She was to be a beauty, virtuous, a queen. So she returned to her<br>attic in the Rue Folle-Peine, very proud of bearing with her a<br>queen. The next day she took advantage of a moment when the child<br>was asleep on her bed, (for they always slept together), gently<br>left the door a little way open, and ran to tell a neighbor in<br>the Rue de la Séchesserie, that the day would come when her<br>daughter Agnès would be served at table by the King of England<br>and the Archduke of Ethiopia, and a hundred other marvels. On her<br>return, hearing no cries on the staircase, she said to herself:<br>‘Good! the child is still asleep!’ She found her door wider open<br>than she had left it, but she entered, poor mother, and ran to<br>the bed.—The child was no longer there, the place was empty.<br>Nothing remained of the child, but one of her pretty little<br>shoes. She flew out of the room, dashed down the stairs, and<br>began to beat her head against the wall, crying: ‘My child! who<br>has my child? Who has taken my child?’ The street was deserted,<br>the house isolated; no one could tell her anything about it. She<br>went about the town, searched all the streets, ran hither and<br>thither the whole day long, wild, beside herself, terrible,<br>snuffing at doors and windows like a wild beast which has lost<br>its young. She was breathless, dishevelled, frightful to see, and<br>there was a fire in her eyes which dried her tears. She stopped<br>the passers-by and cried: ‘My daughter! my daughter! my pretty<br>little daughter! If any one will give me back my daughter, I will<br>be his servant, the servant of his dog, and he shall eat my heart<br>if he will.’ She met M. le Curé of Saint-Remy, and said to him:<br>‘Monsieur, I will till the earth with my finger-nails, but give<br>me back my child!’ It was heartrending, Oudarde; and I saw a very<br>hard man, Master Ponce Lacabre, the procurator, weep. Ah! poor<br>mother! In the evening she returned home. During her absence, a<br>neighbor had seen two gypsies ascend up to it with a bundle in<br>their arms, then descend again, after closing the door. After<br>their departure, something like the cries of a child were heard<br>in Paquette’s room. The mother, burst into shrieks of laughter,<br>ascended the stairs as though on wings, and entered.—A frightful<br>thing to tell, Oudarde! Instead of her pretty little Agnès, so<br>rosy and so fresh, who was a gift of the good God, a sort of<br>hideous little monster, lame, one-eyed, deformed, was crawling<br>and squalling over the floor. She hid her eyes in horror. ‘Oh!’<br>said she, ‘have the witches transformed my daughter into this<br>horrible animal?’ They hastened to carry away the little<br>club-foot; he would have driven her mad. It was the monstrous<br>child of some gypsy woman, who had given herself to the devil. He<br>appeared to be about four years old, and talked a language which<br>was no human tongue; there were words in it which were<br>impossible. La Chantefleurie flung herself upon the little shoe,<br>all that remained to her of all that she loved. She remained so<br>long motionless over it, mute, and without breath, that they<br>thought she was dead. Suddenly she trembled all over, covered her<br>relic with furious kisses, and burst out sobbing as though her<br>heart were broken. I assure you that we were all weeping also.<br>She said: ‘Oh, my little daughter! my pretty little daughter!<br>where art thou?’—and it wrung your very heart. I weep still when<br>I think of it. Our children are the marrow of our bones, you<br>see.—My poor Eustache! thou art so fair!—If you only knew how<br>nice he is! yesterday he said to me: ‘I want to be a gendarme,<br>that I do.’ Oh! my Eustache! if I were to lose thee!—All at once<br>la Chantefleurie rose, and set out to run through Reims,<br>screaming: ‘To the gypsies’ camp! to the gypsies’ camp! Police,<br>to burn the witches!’ The gypsies were gone. It was pitch dark.<br>They could not be followed. On the morrow, two leagues from<br>Reims, on a heath between Gueux and Tilloy, the remains of a<br>large fire were found, some ribbons which had belonged to<br>Paquette’s child, drops of blood, and the dung of a ram. The<br>night just past had been a Saturday. There was no longer any<br>doubt that the Egyptians had held their Sabbath on that heath,<br>and that they had devoured the child in company with Beelzebub,<br>as the practice is among the Mahometans. When La Chantefleurie<br>learned these horrible things, she did not weep, she moved her<br>lips as though to speak, but could not. On the morrow, her hair<br>was gray. On the second day, she had disappeared.</p>\n<p>“’Tis in truth, a frightful tale,” said Oudarde, “and one which<br>would make even a Burgundian weep.”</p>\n<p>“I am no longer surprised,” added Gervaise, “that fear of the<br>gypsies should spur you on so sharply.”</p>\n<p>“And you did all the better,” resumed Oudarde, “to flee with your<br>Eustache just now, since these also are gypsies from Poland.”</p>\n<p>“No,” said Gervais, “’tis said that they come from Spain and<br>Catalonia.”</p>\n<p>“Catalonia? ’tis possible,” replied Oudarde. “Pologne, Catalogne,<br>Valogne, I always confound those three provinces, One thing is<br>certain, that they are gypsies.”</p>\n<p>“Who certainly,” added Gervaise, “have teeth long enough to eat<br>little children. I should not be surprised if la Smeralda ate a<br>little of them also, though she pretends to be dainty. Her white<br>goat knows tricks that are too malicious for there not to be some<br>impiety underneath it all.”</p>\n<p>Mahiette walked on in silence. She was absorbed in that revery<br>which is, in some sort, the continuation of a mournful tale, and<br>which ends only after having communicated the emotion, from<br>vibration to vibration, even to the very last fibres of the<br>heart. Nevertheless, Gervaise addressed her, “And did they ever<br>learn what became of la Chantefleurie?” Mahiette made no reply.<br>Gervaise repeated her question, and shook her arm, calling her by<br>name. Mahiette appeared to awaken from her thoughts.</p>\n<p>“What became of la Chantefleurie?” she said, repeating<br>mechanically the words whose impression was still fresh in her<br>ear; then, making an effort to recall her attention to the<br>meaning of her words, “Ah!” she continued briskly, “no one ever<br>found out.”</p>\n<p>She added, after a pause,—</p>\n<p>“Some said that she had been seen to quit Reims at nightfall by<br>the Fléchembault gate; others, at daybreak, by the old Basée<br>gate. A poor man found her gold cross hanging on the stone cross<br>in the field where the fair is held. It was that ornament which<br>had wrought her ruin, in ’61. It was a gift from the handsome<br>Vicomte de Cormontreuil, her first lover. Paquette had never been<br>willing to part with it, wretched as she had been. She had clung<br>to it as to life itself. So, when we saw that cross abandoned, we<br>all thought that she was dead. Nevertheless, there were people of<br>the Cabaret les Vantes, who said that they had seen her pass<br>along the road to Paris, walking on the pebbles with her bare<br>feet. But, in that case, she must have gone out through the Porte<br>de Vesle, and all this does not agree. Or, to speak more truly, I<br>believe that she actually did depart by the Porte de Vesle, but<br>departed from this world.”</p>\n<p>“I do not understand you,” said Gervaise.</p>\n<p>“La Vesle,” replied Mahiette, with a melancholy smile, “is the<br>river.”</p>\n<p>“Poor Chantefleurie!” said Oudarde, with a shiver,—“drowned!”</p>\n<p>“Drowned!” resumed Mahiette, “who could have told good Father<br>Guybertant, when he passed under the bridge of Tingueux with the<br>current, singing in his barge, that one day his dear little<br>Paquette would also pass beneath that bridge, but without song or<br>boat.</p>\n<p>“And the little shoe?” asked Gervaise.</p>\n<p>“Disappeared with the mother,” replied Mahiette.</p>\n<p>“Poor little shoe!” said Oudarde.</p>\n<p>Oudarde, a big and tender woman, would have been well pleased to<br>sigh in company with Mahiette. But Gervaise, more curious, had<br>not finished her questions.</p>\n<p>“And the monster?” she said suddenly, to Mahiette.</p>\n<p>“What monster?” inquired the latter.</p>\n<p>“The little gypsy monster left by the sorceresses in<br>Chantefleurie’s chamber, in exchange for her daughter. What did<br>you do with it? I hope you drowned it also.”</p>\n<p>“No.” replied Mahiette.</p>\n<p>“What? You burned it then? In sooth, that is more just. A witch<br>child!”</p>\n<p>“Neither the one nor the other, Gervaise. Monseigneur the<br>archbishop interested himself in the child of Egypt, exorcised<br>it, blessed it, removed the devil carefully from its body, and<br>sent it to Paris, to be exposed on the wooden bed at Notre-Dame,<br>as a foundling.”</p>\n<p>“Those bishops!” grumbled Gervaise, “because they are learned,<br>they do nothing like anybody else. I just put it to you, Oudarde,<br>the idea of placing the devil among the foundlings! For that<br>little monster was assuredly the devil. Well, Mahiette, what did<br>they do with it in Paris? I am quite sure that no charitable<br>person wanted it.”</p>\n<p>“I do not know,” replied the Rémoise, “’twas just at that time<br>that my husband bought the office of notary, at Beru, two leagues<br>from the town, and we were no longer occupied with that story;<br>besides, in front of Beru, stand the two hills of Cernay, which<br>hide the towers of the cathedral in Reims from view.”</p>\n<p>While chatting thus, the three worthy <em>bourgeoises</em> had arrived<br>at the Place de Grève. In their absorption, they had passed the<br>public breviary of the Tour-Roland without stopping, and took<br>their way mechanically towards the pillory around which the<br>throng was growing more dense with every moment. It is probable<br>that the spectacle which at that moment attracted all looks in<br>that direction, would have made them forget completely the<br>Rat-Hole, and the halt which they intended to make there, if big<br>Eustache, six years of age, whom Mahiette was dragging along by<br>the hand, had not abruptly recalled the object to them: “Mother,”<br>said he, as though some instinct warned him that the Rat-Hole was<br>behind him, “can I eat the cake now?”</p>\n<p>If Eustache had been more adroit, that is to say, less greedy, he<br>would have continued to wait, and would only have hazarded that<br>simple question, “Mother, can I eat the cake, now?” on their<br>return to the University, to Master Andry Musnier’s, Rue Madame<br>la Valence, when he had the two arms of the Seine and the five<br>bridges of the city between the Rat-Hole and the cake.</p>\n<p>This question, highly imprudent at the moment when Eustache put<br>it, aroused Mahiette’s attention.</p>\n<p>“By the way,” she exclaimed, “we are forgetting the recluse! Show<br>me the Rat-Hole, that I may carry her her cake.”</p>\n<p>“Immediately,” said Oudarde, “’tis a charity.”</p>\n<p>But this did not suit Eustache.</p>\n<p>“Stop! my cake!” said he, rubbing both ears alternatively with<br>his shoulders, which, in such cases, is the supreme sign of<br>discontent.</p>\n<p>The three women retraced their steps, and, on arriving in the<br>vicinity of the Tour-Roland, Oudarde said to the other two,—</p>\n<p>“We must not all three gaze into the hole at once, for fear of<br>alarming the recluse. Do you two pretend to read the <em>Dominus</em> in<br>the breviary, while I thrust my nose into the aperture; the<br>recluse knows me a little. I will give you warning when you can<br>approach.”</p>\n<p>She proceeded alone to the window. At the moment when she looked<br>in, a profound pity was depicted on all her features, and her<br>frank, gay visage altered its expression and color as abruptly as<br>though it had passed from a ray of sunlight to a ray of<br>moonlight; her eye became humid; her mouth contracted, like that<br>of a person on the point of weeping. A moment later, she laid her<br>finger on her lips, and made a sign to Mahiette to draw near and<br>look.</p>\n<p>Mahiette, much touched, stepped up in silence, on tiptoe, as<br>though approaching the bedside of a dying person.</p>\n<p>It was, in fact, a melancholy spectacle which presented itself to<br>the eyes of the two women, as they gazed through the grating of<br>the Rat-Hole, neither stirring nor breathing.</p>\n<p>The cell was small, broader than it was long, with an arched<br>ceiling, and viewed from within, it bore a considerable<br>resemblance to the interior of a huge bishop’s mitre. On the bare<br>flagstones which formed the floor, in one corner, a woman was<br>sitting, or rather, crouching. Her chin rested on her knees,<br>which her crossed arms pressed forcibly to her breast. Thus<br>doubled up, clad in a brown sack, which enveloped her entirely in<br>large folds, her long, gray hair pulled over in front, falling<br>over her face and along her legs nearly to her feet, she<br>presented, at the first glance, only a strange form outlined<br>against the dark background of the cell, a sort of dusky<br>triangle, which the ray of daylight falling through the opening,<br>cut roughly into two shades, the one sombre, the other<br>illuminated. It was one of those spectres, half light, half<br>shadow, such as one beholds in dreams and in the extraordinary<br>work of Goya, pale, motionless, sinister, crouching over a tomb,<br>or leaning against the grating of a prison cell.</p>\n<p>It was neither a woman, nor a man, nor a living being, nor a<br>definite form; it was a figure, a sort of vision, in which the<br>real and the fantastic intersected each other, like darkness and<br>day. It was with difficulty that one distinguished, beneath her<br>hair which spread to the ground, a gaunt and severe profile; her<br>dress barely allowed the extremity of a bare foot to escape,<br>which contracted on the hard, cold pavement. The little of human<br>form of which one caught a sight beneath this envelope of<br>mourning, caused a shudder.</p>\n<p>That figure, which one might have supposed to be riveted to the<br>flagstones, appeared to possess neither movement, nor thought,<br>nor breath. Lying, in January, in that thin, linen sack, lying on<br>a granite floor, without fire, in the gloom of a cell whose<br>oblique air-hole allowed only the cold breeze, but never the sun,<br>to enter from without, she did not appear to suffer or even to<br>think. One would have said that she had turned to stone with the<br>cell, ice with the season. Her hands were clasped, her eyes<br>fixed. At first sight one took her for a spectre; at the second,<br>for a statue.</p>\n<p>Nevertheless, at intervals, her blue lips half opened to admit a<br>breath, and trembled, but as dead and as mechanical as the leaves<br>which the wind sweeps aside.</p>\n<p>Nevertheless, from her dull eyes there escaped a look, an<br>ineffable look, a profound, lugubrious, imperturbable look,<br>incessantly fixed upon a corner of the cell which could not be<br>seen from without; a gaze which seemed to fix all the sombre<br>thoughts of that soul in distress upon some mysterious object.</p>\n<p>Such was the creature who had received, from her habitation, the<br>name of the “recluse”; and, from her garment, the name of “the<br>sacked nun.”</p>\n<p>The three women, for Gervaise had rejoined Mahiette and Oudarde,<br>gazed through the window. Their heads intercepted the feeble<br>light in the cell, without the wretched being whom they thus<br>deprived of it seeming to pay any attention to them. “Do not let<br>us trouble her,” said Oudarde, in a low voice, “she is in her<br>ecstasy; she is praying.”</p>\n<p>Meanwhile, Mahiette was gazing with ever-increasing anxiety at<br>that wan, withered, dishevelled head, and her eyes filled with<br>tears. “This is very singular,” she murmured.</p>\n<p>She thrust her head through the bars, and succeeded in casting a<br>glance at the corner where the gaze of the unhappy woman was<br>immovably riveted.</p>\n<p>When she withdrew her head from the window, her countenance was<br>inundated with tears.</p>\n<p>“What do you call that woman?” she asked Oudarde.</p>\n<p>Oudarde replied,—</p>\n<p>“We call her Sister Gudule.”</p>\n<p>“And I,” returned Mahiette, “call her Paquette la Chantefleurie.”</p>\n<p>Then, laying her finger on her lips, she motioned to the<br>astounded Oudarde to thrust her head through the window and look.</p>\n<p>Oudarde looked and beheld, in the corner where the eyes of the<br>recluse were fixed in that sombre ecstasy, a tiny shoe of pink<br>satin, embroidered with a thousand fanciful designs in gold and<br>silver.</p>\n<p>Gervaise looked after Oudarde, and then the three women, gazing<br>upon the unhappy mother, began to weep.</p>\n<p>But neither their looks nor their tears disturbed the recluse.<br>Her hands remained clasped; her lips mute; her eyes fixed; and<br>that little shoe, thus gazed at, broke the heart of any one who<br>knew her history.</p>\n<p>The three women had not yet uttered a single word; they dared not<br>speak, even in a low voice. This deep silence, this deep grief,<br>this profound oblivion in which everything had disappeared except<br>one thing, produced upon them the effect of the grand altar at<br>Christmas or Easter. They remained silent, they meditated, they<br>were ready to kneel. It seemed to them that they were ready to<br>enter a church on the day of Tenebræ.</p>\n<p>At length Gervaise, the most curious of the three, and<br>consequently the least sensitive, tried to make the recluse<br>speak:</p>\n<p>“Sister! Sister Gudule!”</p>\n<p>She repeated this call three times, raising her voice each time.<br>The recluse did not move; not a word, not a glance, not a sigh,<br>not a sign of life.</p>\n<p>Oudarde, in her turn, in a sweeter, more caressing<br>voice,—“Sister!” said she, “Sister Sainte-Gudule!”</p>\n<p>The same silence; the same immobility.</p>\n<p>“A singular woman!” exclaimed Gervaise, “and one not to be moved<br>by a catapult!”</p>\n<p>“Perchance she is deaf,” said Oudarde.</p>\n<p>“Perhaps she is blind,” added Gervaise.</p>\n<p>“Dead, perchance,” returned Mahiette.</p>\n<p>It is certain that if the soul had not already quitted this<br>inert, sluggish, lethargic body, it had at least retreated and<br>concealed itself in depths whither the perceptions of the<br>exterior organs no longer penetrated.</p>\n<p>“Then we must leave the cake on the window,” said Oudarde; “some<br>scamp will take it. What shall we do to rouse her?”</p>\n<p>Eustache, who, up to that moment had been diverted by a little<br>carriage drawn by a large dog, which had just passed, suddenly<br>perceived that his three conductresses were gazing at something<br>through the window, and, curiosity taking possession of him in<br>his turn, he climbed upon a stone post, elevated himself on<br>tiptoe, and applied his fat, red face to the opening, shouting,<br>“Mother, let me see too!”</p>\n<p>At the sound of this clear, fresh, ringing child’s voice, the<br>recluse trembled; she turned her head with the sharp, abrupt<br>movement of a steel spring, her long, fleshless hands cast aside<br>the hair from her brow, and she fixed upon the child, bitter,<br>astonished, desperate eyes. This glance was but a lightning<br>flash.</p>\n<p>“Oh my God!” she suddenly exclaimed, hiding her head on her<br>knees, and it seemed as though her hoarse voice tore her chest as<br>it passed from it, “do not show me those of others!”</p>\n<p>“Good day, madam,” said the child, gravely.</p>\n<p>Nevertheless, this shock had, so to speak, awakened the recluse.<br>A long shiver traversed her frame from head to foot; her teeth<br>chattered; she half raised her head and said, pressing her elbows<br>against her hips, and clasping her feet in her hands as though to<br>warm them,—</p>\n<p>“Oh, how cold it is!”</p>\n<p>“Poor woman!” said Oudarde, with great compassion, “would you<br>like a little fire?”</p>\n<p>She shook her head in token of refusal.</p>\n<p>“Well,” resumed Oudarde, presenting her with a flagon; “here is<br>some hippocras which will warm you; drink it.”</p>\n<p>Again she shook her head, looked at Oudarde fixedly and replied,<br>“Water.”</p>\n<p>Oudarde persisted,—“No, sister, that is no beverage for January.<br>You must drink a little hippocras and eat this leavened cake of<br>maize, which we have baked for you.”</p>\n<p>She refused the cake which Mahiette offered to her, and said,<br>“Black bread.”</p>\n<p>“Come,” said Gervaise, seized in her turn with an impulse of<br>charity, and unfastening her woolen cloak, “here is a cloak which<br>is a little warmer than yours.”</p>\n<p>She refused the cloak as she had refused the flagon and the cake,<br>and replied, “A sack.”</p>\n<p>“But,” resumed the good Oudarde, “you must have perceived to some<br>extent, that yesterday was a festival.”</p>\n<p>“I do perceive it,” said the recluse; “’tis two days now since I<br>have had any water in my crock.”</p>\n<p>She added, after a silence, “’Tis a festival, I am forgotten.<br>People do well. Why should the world think of me, when I do not<br>think of it? Cold charcoal makes cold ashes.”</p>\n<p>And as though fatigued with having said so much, she dropped her<br>head on her knees again. The simple and charitable Oudarde, who<br>fancied that she understood from her last words that she was<br>complaining of the cold, replied innocently, “Then you would like<br>a little fire?”</p>\n<p>“Fire!” said the sacked nun, with a strange accent; “and will you<br>also make a little for the poor little one who has been beneath<br>the sod for these fifteen years?”</p>\n<p>Every limb was trembling, her voice quivered, her eyes flashed,<br>she had raised herself upon her knees; suddenly she extended her<br>thin, white hand towards the child, who was regarding her with a<br>look of astonishment. “Take away that child!” she cried. “The<br>Egyptian woman is about to pass by.”</p>\n<p>Then she fell face downward on the earth, and her forehead struck<br>the stone, with the sound of one stone against another stone. The<br>three women thought her dead. A moment later, however, she moved,<br>and they beheld her drag herself, on her knees and elbows, to the<br>corner where the little shoe was. Then they dared not look; they<br>no longer saw her; but they heard a thousand kisses and a<br>thousand sighs, mingled with heartrending cries, and dull blows<br>like those of a head in contact with a wall. Then, after one of<br>these blows, so violent that all three of them staggered, they<br>heard no more.</p>\n<p>“Can she have killed herself?” said Gervaise, venturing to pass<br>her head through the air-hole. “Sister! Sister Gudule!”</p>\n<p>“Sister Gudule!” repeated Oudarde.</p>\n<p>“Ah! good heavens! she no longer moves!” resumed Gervaise; “is<br>she dead? Gudule! Gudule!”</p>\n<p>Mahiette, choked to such a point that she could not speak, made<br>an effort. “Wait,” said she. Then bending towards the window,<br>“Paquette!” she said, “Paquette le Chantefleurie!”</p>\n<p>A child who innocently blows upon the badly ignited fuse of a<br>bomb, and makes it explode in his face, is no more terrified than<br>was Mahiette at the effect of that name, abruptly launched into<br>the cell of Sister Gudule.</p>\n<p>The recluse trembled all over, rose erect on her bare feet, and<br>leaped at the window with eyes so glaring that Mahiette and<br>Oudarde, and the other woman and the child recoiled even to the<br>parapet of the quay.</p>\n<p>Meanwhile, the sinister face of the recluse appeared pressed to<br>the grating of the air-hole. “Oh! oh!” she cried, with an<br>appalling laugh; “’tis the Egyptian who is calling me!”</p>\n<p>At that moment, a scene which was passing at the pillory caught<br>her wild eye. Her brow contracted with horror, she stretched her<br>two skeleton arms from her cell, and shrieked in a voice which<br>resembled a death-rattle, “So ’tis thou once more, daughter of<br>Egypt! ’Tis thou who callest me, stealer of children! Well! Be<br>thou accursed! accursed! accursed! accursed!”</p>\n<h1 class=\"chapter\" id=\"chapter-iv-a-tear-for-a-drop-of-water\">Chapter IV. A TEAR FOR A DROP OF WATER.</h1>\n<p>These words were, so to speak, the point of union of two scenes,<br>which had, up to that time, been developed in parallel lines at<br>the same moment, each on its particular theatre; one, that which<br>the reader has just perused, in the Rat-Hole; the other, which he<br>is about to read, on the ladder of the pillory. The first had for<br>witnesses only the three women with whom the reader has just made<br>acquaintance; the second had for spectators all the public which<br>we have seen above, collecting on the Place de Grève, around the<br>pillory and the gibbet.</p>\n<p>That crowd which the four sergeants posted at nine o’clock in the<br>morning at the four corners of the pillory had inspired with the<br>hope of some sort of an execution, no doubt, not a hanging, but a<br>whipping, a cropping of ears, something, in short,—that crowd had<br>increased so rapidly that the four policemen, too closely<br>besieged, had had occasion to “press” it, as the expression then<br>ran, more than once, by sound blows of their whips, and the<br>haunches of their horses.</p>\n<p>This populace, disciplined to waiting for public executions, did<br>not manifest very much impatience. It amused itself with watching<br>the pillory, a very simple sort of monument, composed of a cube<br>of masonry about six feet high and hollow in the interior. A very<br>steep staircase, of unhewn stone, which was called by distinction<br>“the ladder,” led to the upper platform, upon which was visible a<br>horizontal wheel of solid oak. The victim was bound upon this<br>wheel, on his knees, with his hands behind his back. A wooden<br>shaft, which set in motion a capstan concealed in the interior of<br>the little edifice, imparted a rotatory motion to the wheel,<br>which always maintained its horizontal position, and in this<br>manner presented the face of the condemned man to all quarters of<br>the square in succession. This was what was called “turning” a<br>criminal.</p>\n<p>As the reader perceives, the pillory of the Grève was far from<br>presenting all the recreations of the pillory of the Halles.<br>Nothing architectural, nothing monumental. No roof to the iron<br>cross, no octagonal lantern, no frail, slender columns spreading<br>out on the edge of the roof into capitals of acanthus leaves and<br>flowers, no waterspouts of chimeras and monsters, on carved<br>woodwork, no fine sculpture, deeply sunk in the stone.</p>\n<p>They were forced to content themselves with those four stretches<br>of rubble work, backed with sandstone, and a wretched stone<br>gibbet, meagre and bare, on one side.</p>\n<p>The entertainment would have been but a poor one for lovers of<br>Gothic architecture. It is true that nothing was ever less<br>curious on the score of architecture than the worthy gapers of<br>the Middle Ages, and that they cared very little for the beauty<br>of a pillory.</p>\n<p>The victim finally arrived, bound to the tail of a cart, and when<br>he had been hoisted upon the platform, where he could be seen<br>from all points of the Place, bound with cords and straps upon<br>the wheel of the pillory, a prodigious hoot, mingled with<br>laughter and acclamations, burst forth upon the Place. They had<br>recognized Quasimodo.</p>\n<p>It was he, in fact. The change was singular. Pilloried on the<br>very place where, on the day before, he had been saluted,<br>acclaimed, and proclaimed Pope and Prince of Fools, in the<br>cortège of the Duke of Egypt, the King of Thunes, and the Emperor<br>of Galilee! One thing is certain, and that is, that there was not<br>a soul in the crowd, not even himself, though in turn triumphant<br>and the sufferer, who set forth this combination clearly in his<br>thought. Gringoire and his philosophy were missing at this<br>spectacle.</p>\n<p>Soon Michel Noiret, sworn trumpeter to the king, our lord,<br>imposed silence on the louts, and proclaimed the sentence, in<br>accordance with the order and command of monsieur the provost.<br>Then he withdrew behind the cart, with his men in livery<br>surcoats.</p>\n<p>Quasimodo, impassible, did not wince. All resistance had been<br>rendered impossible to him by what was then called, in the style<br>of the criminal chancellery, “the vehemence and firmness of the<br>bonds” which means that the thongs and chains probably cut into<br>his flesh; moreover, it is a tradition of jail and wardens, which<br>has not been lost, and which the handcuffs still preciously<br>preserve among us, a civilized, gentle, humane people (the<br>galleys and the guillotine in parentheses).</p>\n<p>He had allowed himself to be led, pushed, carried, lifted, bound,<br>and bound again. Nothing was to be seen upon his countenance but<br>the astonishment of a savage or an idiot. He was known to be<br>deaf; one might have pronounced him to be blind.</p>\n<p>They placed him on his knees on the circular plank; he made no<br>resistance. They removed his shirt and doublet as far as his<br>girdle; he allowed them to have their way. They entangled him<br>under a fresh system of thongs and buckles; he allowed them to<br>bind and buckle him. Only from time to time he snorted noisily,<br>like a calf whose head is hanging and bumping over the edge of a<br>butcher’s cart.</p>\n<p>“The dolt,” said Jehan Frollo of the Mill, to his friend Robin<br>Poussepain (for the two students had followed the culprit, as was<br>to have been expected), “he understands no more than a cockchafer<br>shut up in a box!”</p>\n<p>There was wild laughter among the crowd when they beheld<br>Quasimodo’s hump, his camel’s breast, his callous and hairy<br>shoulders laid bare. During this gayety, a man in the livery of<br>the city, short of stature and robust of mien, mounted the<br>platform and placed himself near the victim. His name speedily<br>circulated among the spectators. It was Master Pierrat Torterue,<br>official torturer to the Châtelet.</p>\n<p>He began by depositing on an angle of the pillory a black<br>hour-glass, the upper lobe of which was filled with red sand,<br>which it allowed to glide into the lower receptacle; then he<br>removed his parti-colored surtout, and there became visible,<br>suspended from his right hand, a thin and tapering whip of long,<br>white, shining, knotted, plaited thongs, armed with metal nails.<br>With his left hand, he negligently folded back his shirt around<br>his right arm, to the very armpit.</p>\n<p>In the meantime, Jehan Frollo, elevating his curly blonde head<br>above the crowd (he had mounted upon the shoulders of Robin<br>Poussepain for the purpose), shouted: “Come and look, gentle<br>ladies and men! they are going to peremptorily flagellate Master<br>Quasimodo, the bellringer of my brother, monsieur the archdeacon<br>of Josas, a knave of oriental architecture, who has a back like a<br>dome, and legs like twisted columns!”</p>\n<p>And the crowd burst into a laugh, especially the boys and young<br>girls.</p>\n<p>At length the torturer stamped his foot. The wheel began to turn.<br>Quasimodo wavered beneath his bonds. The amazement which was<br>suddenly depicted upon his deformed face caused the bursts of<br>laughter to redouble around him.</p>\n<p>All at once, at the moment when the wheel in its revolution<br>presented to Master Pierrat, the humped back of Quasimodo, Master<br>Pierrat raised his arm; the fine thongs whistled sharply through<br>the air, like a handful of adders, and fell with fury upon the<br>wretch’s shoulders.</p>\n<p>Quasimodo leaped as though awakened with a start. He began to<br>understand. He writhed in his bonds; a violent contraction of<br>surprise and pain distorted the muscles of his face, but he<br>uttered not a single sigh. He merely turned his head backward, to<br>the right, then to the left, balancing it as a bull does who has<br>been stung in the flanks by a gadfly.</p>\n<p>A second blow followed the first, then a third, and another and<br>another, and still others. The wheel did not cease to turn, nor<br>the blows to rain down.</p>\n<p>Soon the blood burst forth, and could be seen trickling in a<br>thousand threads down the hunchback’s black shoulders; and the<br>slender thongs, in their rotatory motion which rent the air,<br>sprinkled drops of it upon the crowd.</p>\n<p>Quasimodo had resumed, to all appearance, his first<br>imperturbability. He had at first tried, in a quiet way and<br>without much outward movement, to break his bonds. His eye had<br>been seen to light up, his muscles to stiffen, his members to<br>concentrate their force, and the straps to stretch. The effort<br>was powerful, prodigious, desperate; but the provost’s seasoned<br>bonds resisted. They cracked, and that was all. Quasimodo fell<br>back exhausted. Amazement gave way, on his features, to a<br>sentiment of profound and bitter discouragement. He closed his<br>single eye, allowed his head to droop upon his breast, and<br>feigned death.</p>\n<p>From that moment forth, he stirred no more. Nothing could force a<br>movement from him. Neither his blood, which did not cease to<br>flow, nor the blows which redoubled in fury, nor the wrath of the<br>torturer, who grew excited himself and intoxicated with the<br>execution, nor the sound of the horrible thongs, more sharp and<br>whistling than the claws of scorpions.</p>\n<p>At length a bailiff from the Châtelet clad in black, mounted on a<br>black horse, who had been stationed beside the ladder since the<br>beginning of the execution, extended his ebony wand towards the<br>hour-glass. The torturer stopped. The wheel stopped. Quasimodo’s<br>eye opened slowly.</p>\n<p>The scourging was finished. Two lackeys of the official torturer<br>bathed the bleeding shoulders of the patient, anointed them with<br>some unguent which immediately closed all the wounds, and threw<br>upon his back a sort of yellow vestment, in cut like a chasuble.<br>In the meanwhile, Pierrat Torterue allowed the thongs, red and<br>gorged with blood, to drip upon the pavement.</p>\n<p>All was not over for Quasimodo. He had still to undergo that hour<br>of pillory which Master Florian Barbedienne had so judiciously<br>added to the sentence of Messire Robert d’Estouteville; all to<br>the greater glory of the old physiological and psychological play<br>upon words of Jean de Cumène, <em>Surdus absurdus</em>: a deaf man is<br>absurd.</p>\n<p>So the hour-glass was turned over once more, and they left the<br>hunchback fastened to the plank, in order that justice might be<br>accomplished to the very end.</p>\n<p>The populace, especially in the Middle Ages, is in society what<br>the child is in the family. As long as it remains in its state of<br>primitive ignorance, of moral and intellectual minority, it can<br>be said of it as of the child,—</p>\n<p>’Tis the pitiless age.</p>\n<p>We have already shown that Quasimodo was generally hated, for<br>more than one good reason, it is true. There was hardly a<br>spectator in that crowd who had not or who did not believe that<br>he had reason to complain of the malevolent hunchback of<br>Notre-Dame. The joy at seeing him appear thus in the pillory had<br>been universal; and the harsh punishment which he had just<br>suffered, and the pitiful condition in which it had left him, far<br>from softening the populace had rendered its hatred more<br>malicious by arming it with a touch of mirth.</p>\n<p>Hence, the “public prosecution” satisfied, as the bigwigs of the<br>law still express it in their jargon, the turn came of a thousand<br>private vengeances. Here, as in the Grand Hall, the women<br>rendered themselves particularly prominent. All cherished some<br>rancor against him, some for his malice, others for his ugliness.<br>The latter were the most furious.</p>\n<p>“Oh! mask of Antichrist!” said one.</p>\n<p>“Rider on a broom handle!” cried another.</p>\n<p>“What a fine tragic grimace,” howled a third, “and who would make<br>him Pope of the Fools if to-day were yesterday?”</p>\n<p>“’Tis well,” struck in an old woman. “This is the grimace of the<br>pillory. When shall we have that of the gibbet?”</p>\n<p>“When will you be coiffed with your big bell a hundred feet under<br>ground, cursed bellringer?”</p>\n<p>“But ’tis the devil who rings the Angelus!”</p>\n<p>“Oh! the deaf man! the one-eyed creature! the hunch-back! the<br>monster!”</p>\n<p>“A face to make a woman miscarry better than all the drugs and<br>medicines!”</p>\n<p>And the two scholars, Jehan du Moulin, and Robin Poussepain, sang<br>at the top of their lungs, the ancient refrain,—</p>\n<p>“Une hart<br>Pour le pendard!<br>Un fagot<br>Pour le magot!”[33]</p>\n<p>A thousand other insults rained down upon him, and hoots and<br>imprecations, and laughter, and now and then, stones.</p>\n<p>Quasimodo was deaf but his sight was clear, and the public fury<br>was no less energetically depicted on their visages than in their<br>words. Moreover, the blows from the stones explained the bursts<br>of laughter.</p>\n<p>At first he held his ground. But little by little that patience<br>which had borne up under the lash of the torturer, yielded and<br>gave way before all these stings of insects. The bull of the<br>Asturias who has been but little moved by the attacks of the<br>picador grows irritated with the dogs and banderilleras.</p>\n<p>He first cast around a slow glance of hatred upon the crowd. But<br>bound as he was, his glance was powerless to drive away those<br>flies which were stinging his wound. Then he moved in his bonds,<br>and his furious exertions made the ancient wheel of the pillory<br>shriek on its axle. All this only increased the derision and<br>hooting.</p>\n<p>Then the wretched man, unable to break his collar, like that of a<br>chained wild beast, became tranquil once more; only at intervals<br>a sigh of rage heaved the hollows of his chest. There was neither<br>shame nor redness on his face. He was too far from the state of<br>society, and too near the state of nature to know what shame was.<br>Moreover, with such a degree of deformity, is infamy a thing that<br>can be felt? But wrath, hatred, despair, slowly lowered over that<br>hideous visage a cloud which grew ever more and more sombre, ever<br>more and more charged with electricity, which burst forth in a<br>thousand lightning flashes from the eye of the cyclops.</p>\n<p>Nevertheless, that cloud cleared away for a moment, at the<br>passage of a mule which traversed the crowd, bearing a priest. As<br>far away as he could see that mule and that priest, the poor<br>victim’s visage grew gentler. The fury which had contracted it<br>was followed by a strange smile full of ineffable sweetness,<br>gentleness, and tenderness. In proportion as the priest<br>approached, that smile became more clear, more distinct, more<br>radiant. It was like the arrival of a Saviour, which the unhappy<br>man was greeting. But as soon as the mule was near enough to the<br>pillory to allow of its rider recognizing the victim, the priest<br>dropped his eyes, beat a hasty retreat, spurred on rigorously, as<br>though in haste to rid himself of humiliating appeals, and not at<br>all desirous of being saluted and recognized by a poor fellow in<br>such a predicament.</p>\n<p>This priest was Archdeacon Dom Claude Frollo.</p>\n<p>The cloud descended more blackly than ever upon Quasimodo’s brow.<br>The smile was still mingled with it for a time, but was bitter,<br>discouraged, profoundly sad.</p>\n<p>Time passed on. He had been there at least an hour and a half,<br>lacerated, maltreated, mocked incessantly, and almost stoned.</p>\n<p>All at once he moved again in his chains with redoubled despair,<br>which made the whole framework that bore him tremble, and,<br>breaking the silence which he had obstinately preserved hitherto,<br>he cried in a hoarse and furious voice, which resembled a bark<br>rather than a human cry, and which was drowned in the noise of<br>the hoots—“Drink!”</p>\n<p>This exclamation of distress, far from exciting compassion, only<br>added amusement to the good Parisian populace who surrounded the<br>ladder, and who, it must be confessed, taken in the mass and as a<br>multitude, was then no less cruel and brutal than that horrible<br>tribe of robbers among whom we have already conducted the reader,<br>and which was simply the lower stratum of the populace. Not a<br>voice was raised around the unhappy victim, except to jeer at his<br>thirst. It is certain that at that moment he was more grotesque<br>and repulsive than pitiable, with his face purple and dripping,<br>his eye wild, his mouth foaming with rage and pain, and his<br>tongue lolling half out. It must also be stated that if a<br>charitable soul of a <em>bourgeois</em> or <em>bourgeoise</em>, in the rabble,<br>had attempted to carry a glass of water to that wretched creature<br>in torment, there reigned around the infamous steps of the<br>pillory such a prejudice of shame and ignominy, that it would<br>have sufficed to repulse the good Samaritan.</p>\n<p>At the expiration of a few moments, Quasimodo cast a desperate<br>glance upon the crowd, and repeated in a voice still more<br>heartrending: “Drink!”</p>\n<p>And all began to laugh.</p>\n<p>“Drink this!” cried Robin Poussepain, throwing in his face a<br>sponge which had been soaked in the gutter. “There, you deaf<br>villain, I’m your debtor.”</p>\n<p>A woman hurled a stone at his head,—</p>\n<p>“That will teach you to wake us up at night with your peal of a<br>dammed soul.”</p>\n<p>“He, good, my son!” howled a cripple, making an effort to reach<br>him with his crutch, “will you cast any more spells on us from<br>the top of the towers of Notre-Dame?”</p>\n<p>“Here’s a drinking cup!” chimed in a man, flinging a broken jug<br>at his breast. “’Twas you that made my wife, simply because she<br>passed near you, give birth to a child with two heads!”</p>\n<p>“And my cat bring forth a kitten with six paws!” yelped an old<br>crone, launching a brick at him.</p>\n<p>“Drink!” repeated Quasimodo panting, and for the third time.</p>\n<p>At that moment he beheld the crowd give way. A young girl,<br>fantastically dressed, emerged from the throng. She was<br>accompanied by a little white goat with gilded horns, and carried<br>a tambourine in her hand.</p>\n<p>Quasimodo’s eyes sparkled. It was the gypsy whom he had attempted<br>to carry off on the preceding night, a misdeed for which he was<br>dimly conscious that he was being punished at that very moment;<br>which was not in the least the case, since he was being chastised<br>only for the misfortune of being deaf, and of having been judged<br>by a deaf man. He doubted not that she had come to wreak her<br>vengeance also, and to deal her blow like the rest.</p>\n<p>He beheld her, in fact, mount the ladder rapidly. Wrath and spite<br>suffocate him. He would have liked to make the pillory crumble<br>into ruins, and if the lightning of his eye could have dealt<br>death, the gypsy would have been reduced to powder before she<br>reached the platform.</p>\n<p>She approached, without uttering a syllable, the victim who<br>writhed in a vain effort to escape her, and detaching a gourd<br>from her girdle, she raised it gently to the parched lips of the<br>miserable man.</p>\n<p>Then, from that eye which had been, up to that moment, so dry and<br>burning, a big tear was seen to fall, and roll slowly down that<br>deformed visage so long contracted with despair. It was the<br>first, in all probability, that the unfortunate man had ever<br>shed.</p>\n<p>Meanwhile, he had forgotten to drink. The gypsy made her little<br>pout, from impatience, and pressed the spout to the tusked month<br>of Quasimodo, with a smile.</p>\n<p>He drank with deep draughts. His thirst was burning.</p>\n<p>When he had finished, the wretch protruded his black lips, no<br>doubt, with the object of kissing the beautiful hand which had<br>just succoured him. But the young girl, who was, perhaps,<br>somewhat distrustful, and who remembered the violent attempt of<br>the night, withdrew her hand with the frightened gesture of a<br>child who is afraid of being bitten by a beast.</p>\n<p>Then the poor deaf man fixed on her a look full of reproach and<br>inexpressible sadness.</p>\n<p>It would have been a touching spectacle anywhere,—this beautiful,<br>fresh, pure, and charming girl, who was at the same time so weak,<br>thus hastening to the relief of so much misery, deformity, and<br>malevolence. On the pillory, the spectacle was sublime.</p>\n<p>The very populace were captivated by it, and began to clap their<br>hands, crying,—</p>\n<p>“Noël! Noël!”</p>\n<p>It was at that moment that the recluse caught sight, from the<br>window of her bole, of the gypsy on the pillory, and hurled at<br>her her sinister imprecation,—</p>\n<p>“Accursed be thou, daughter of Egypt! Accursed! accursed!”</p>\n<h1 class=\"chapter\" id=\"chapter-v-end-of-the-story-of-the-cake\">Chapter V. END OF THE STORY OF THE CAKE.</h1>\n<p>La Esmeralda turned pale and descended from the pillory,<br>staggering as she went. The voice of the recluse still pursued<br>her,—</p>\n<p>“Descend! descend! Thief of Egypt! thou shalt ascend it once<br>more!”</p>\n<p>“The sacked nun is in one of her tantrums,” muttered the<br>populace; and that was the end of it. For that sort of woman was<br>feared; which rendered them sacred. People did not then willingly<br>attack one who prayed day and night.</p>\n<p>The hour had arrived for removing Quasimodo. He was unbound, the<br>crowd dispersed.</p>\n<p>Near the Grand Pont, Mahiette, who was returning with her two<br>companions, suddenly halted,—</p>\n<p>“By the way, Eustache! what did you do with that cake?”</p>\n<p>“Mother,” said the child, “while you were talking with that lady<br>in the bole, a big dog took a bite of my cake, and then I bit it<br>also.”</p>\n<p>“What, sir, did you eat the whole of it?” she went on.</p>\n<p>“Mother, it was the dog. I told him, but he would not listen to<br>me. Then I bit into it, also.”</p>\n<p>“’Tis a terrible child!” said the mother, smiling and scolding at<br>one and the same time. “Do you see, Oudarde? He already eats all<br>the fruit from the cherry-tree in our orchard of Charlerange. So<br>his grandfather says that he will be a captain. Just let me catch<br>you at it again, Master Eustache. Come along, you greedy fellow!”</p>\n<p>VOLUME II.</p>\n<p>BOOK SEVENTH.</p>\n<h1 class=\"chapter\" id=\"chapter-i-the-danger-of-confiding-ones-secret-to\">Chapter I. THE DANGER OF CONFIDING ONE’S SECRET TO A GOAT.</h1>\n<p>Many weeks had elapsed.</p>\n<p>The first of March had arrived. The sun, which Dubartas, that<br>classic ancestor of periphrase, had not yet dubbed the<br>“Grand-duke of Candles,” was none the less radiant and joyous on<br>that account. It was one of those spring days which possesses so<br>much sweetness and beauty, that all Paris turns out into the<br>squares and promenades and celebrates them as though they were<br>Sundays. In those days of brilliancy, warmth, and serenity, there<br>is a certain hour above all others, when the façade of Notre-Dame<br>should be admired. It is the moment when the sun, already<br>declining towards the west, looks the cathedral almost full in<br>the face. Its rays, growing more and more horizontal, withdraw<br>slowly from the pavement of the square, and mount up the<br>perpendicular façade, whose thousand bosses in high relief they<br>cause to start out from the shadows, while the great central rose<br>window flames like the eye of a cyclops, inflamed with the<br>reflections of the forge.</p>\n<p>This was the hour.</p>\n<p>Opposite the lofty cathedral, reddened by the setting sun, on the<br>stone balcony built above the porch of a rich Gothic house, which<br>formed the angle of the square and the Rue du Parvis, several<br>young girls were laughing and chatting with every sort of grace<br>and mirth. From the length of the veil which fell from their<br>pointed coif, twined with pearls, to their heels, from the<br>fineness of the embroidered chemisette which covered their<br>shoulders and allowed a glimpse, according to the pleasing custom<br>of the time, of the swell of their fair virgin bosoms, from the<br>opulence of their under-petticoats still more precious than their<br>overdress (marvellous refinement), from the gauze, the silk, the<br>velvet, with which all this was composed, and, above all, from<br>the whiteness of their hands, which certified to their leisure<br>and idleness, it was easy to divine they were noble and wealthy<br>heiresses. They were, in fact, Damoiselle Fleur-de-Lys de<br>Gondelaurier and her companions, Diane de Christeuil, Amelotte de<br>Montmichel, Colombe de Gaillefontaine, and the little de<br>Champchevrier maiden; all damsels of good birth, assembled at<br>that moment at the house of the dame widow de Gondelaurier, on<br>account of Monseigneur de Beaujeu and Madame his wife, who were<br>to come to Paris in the month of April, there to choose maids of<br>honor for the Dauphiness Marguerite, who was to be received in<br>Picardy from the hands of the Flemings. Now, all the squires for<br>twenty leagues around were intriguing for this favor for their<br>daughters, and a goodly number of the latter had been already<br>brought or sent to Paris. These four maidens had been confided to<br>the discreet and venerable charge of Madame Aloïse de<br>Gondelaurier, widow of a former commander of the king’s<br>cross-bowmen, who had retired with her only daughter to her house<br>in the Place du Parvis, Notre-Dame, in Paris.</p>\n<p>The balcony on which these young girls stood opened from a<br>chamber richly tapestried in fawn-colored Flanders leather,<br>stamped with golden foliage. The beams, which cut the ceiling in<br>parallel lines, diverted the eye with a thousand eccentric<br>painted and gilded carvings. Splendid enamels gleamed here and<br>there on carved chests; a boar’s head in faïence crowned a<br>magnificent dresser, whose two shelves announced that the<br>mistress of the house was the wife or widow of a knight banneret.<br>At the end of the room, by the side of a lofty chimney blazoned<br>with arms from top to bottom, in a rich red velvet arm-chair, sat<br>Dame de Gondelaurier, whose five and fifty years were written<br>upon her garments no less distinctly than upon her face.</p>\n<p>Beside her stood a young man of imposing mien, although partaking<br>somewhat of vanity and bravado—one of those handsome fellows whom<br>all women agree to admire, although grave men learned in<br>physiognomy shrug their shoulders at them. This young man wore<br>the garb of a captain of the king’s unattached archers, which<br>bears far too much resemblance to the costume of Jupiter, which<br>the reader has already been enabled to admire in the first book<br>of this history, for us to inflict upon him a second description.</p>\n<p>The damoiselles were seated, a part in the chamber, a part in the<br>balcony, some on square cushions of Utrecht velvet with golden<br>corners, others on stools of oak carved in flowers and figures.<br>Each of them held on her knee a section of a great needlework<br>tapestry, on which they were working in company, while one end of<br>it lay upon the rush mat which covered the floor.</p>\n<p>They were chatting together in that whispering tone and with the<br>half-stifled laughs peculiar to an assembly of young girls in<br>whose midst there is a young man. The young man whose presence<br>served to set in play all these feminine self-conceits, appeared<br>to pay very little heed to the matter, and, while these pretty<br>damsels were vying with one another to attract his attention, he<br>seemed to be chiefly absorbed in polishing the buckle of his<br>sword belt with his doeskin glove. From time to time, the old<br>lady addressed him in a very low tone, and he replied as well as<br>he was able, with a sort of awkward and constrained politeness.</p>\n<p>From the smiles and significant gestures of Dame Aloïse, from the<br>glances which she threw towards her daughter, Fleur-de-Lys, as<br>she spoke low to the captain, it was easy to see that there was<br>here a question of some betrothal concluded, some marriage near<br>at hand no doubt, between the young man and Fleur-de-Lys. From<br>the embarrassed coldness of the officer, it was easy to see that<br>on his side, at least, love had no longer any part in the matter.<br>His whole air was expressive of constraint and weariness, which<br>our lieutenants of the garrison would to-day translate admirably<br>as, “What a beastly bore!”</p>\n<p>The poor dame, very much infatuated with her daughter, like any<br>other silly mother, did not perceive the officer’s lack of<br>enthusiasm, and strove in low tones to call his attention to the<br>infinite grace with which Fleur-de-Lys used her needle or wound<br>her skein.</p>\n<p>“Come, little cousin,” she said to him, plucking him by the<br>sleeve, in order to speak in his ear, “Look at her, do! see her<br>stoop.”</p>\n<p>“Yes, truly,” replied the young man, and fell back into his<br>glacial and absent-minded silence.</p>\n<p>A moment later, he was obliged to bend down again, and Dame<br>Aloïse said to him,—</p>\n<p>“Have you ever beheld a more gay and charming face than that of<br>your betrothed? Can one be more white and blonde? are not her<br>hands perfect? and that neck—does it not assume all the curves of<br>the swan in ravishing fashion? How I envy you at times! and how<br>happy you are to be a man, naughty libertine that you are! Is not<br>my Fleur-de-Lys adorably beautiful, and are you not desperately<br>in love with her?”</p>\n<p>“Of course,” he replied, still thinking of something else.</p>\n<p>“But do say something,” said Madame Aloïse, suddenly giving his<br>shoulder a push; “you have grown very timid.”</p>\n<p>We can assure our readers that timidity was neither the captain’s<br>virtue nor his defect. But he made an effort to do what was<br>demanded of him.</p>\n<p>“Fair cousin,” he said, approaching Fleur-de-Lys, “what is the<br>subject of this tapestry work which you are fashioning?”</p>\n<p>“Fair cousin,” responded Fleur-de-Lys, in an offended tone, “I<br>have already told you three times. ’Tis the grotto of Neptune.”</p>\n<p>It was evident that Fleur-de-Lys saw much more clearly than her<br>mother through the captain’s cold and absent-minded manner. He<br>felt the necessity of making some conversation.</p>\n<p>“And for whom is this Neptunerie destined?”</p>\n<p>“For the Abbey of Saint-Antoine des Champs,” answered<br>Fleur-de-Lys, without raising her eyes.</p>\n<p>The captain took up a corner of the tapestry.</p>\n<p>“Who, my fair cousin, is this big gendarme, who is puffing out<br>his cheeks to their full extent and blowing a trumpet?”</p>\n<p>“’Tis Triton,” she replied.</p>\n<p>There was a rather pettish intonation in Fleur-de-Lys’s laconic<br>words. The young man understood that it was indispensable that he<br>should whisper something in her ear, a commonplace, a gallant<br>compliment, no matter what. Accordingly he bent down, but he<br>could find nothing in his imagination more tender and personal<br>than this,—</p>\n<p>“Why does your mother always wear that surcoat with armorial<br>designs, like our grandmothers of the time of Charles VII.? Tell<br>her, fair cousin, that ’tis no longer the fashion, and that the<br>hinge (<em>gond</em>) and the laurel (<em>laurier</em>) embroidered on her robe<br>give her the air of a walking mantlepiece. In truth, people no<br>longer sit thus on their banners, I assure you.”</p>\n<p>Fleur-de-Lys raised her beautiful eyes, full of reproach, “Is<br>that all of which you can assure me?” she said, in a low voice.</p>\n<p>In the meantime, Dame Aloïse, delighted to see them thus bending<br>towards each other and whispering, said as she toyed with the<br>clasps of her prayer-book,—</p>\n<p>“Touching picture of love!”</p>\n<p>The captain, more and more embarrassed, fell back upon the<br>subject of the tapestry,—“’Tis, in sooth, a charming work!” he<br>exclaimed.</p>\n<p>Whereupon Colombe de Gaillefontaine, another beautiful blonde,<br>with a white skin, dressed to the neck in blue damask, ventured a<br>timid remark which she addressed to Fleur-de-Lys, in the hope<br>that the handsome captain would reply to it, “My dear<br>Gondelaurier, have you seen the tapestries of the Hôtel de la<br>Roche-Guyon?”</p>\n<p>“Is not that the hôtel in which is enclosed the garden of the<br>Lingère du Louvre?” asked Diane de Christeuil with a laugh; for<br>she had handsome teeth, and consequently laughed on every<br>occasion.</p>\n<p>“And where there is that big, old tower of the ancient wall of<br>Paris,” added Amelotte de Montmichel, a pretty fresh and<br>curly-headed brunette, who had a habit of sighing just as the<br>other laughed, without knowing why.</p>\n<p>“My dear Colombe,” interpolated Dame Aloïse, “do you not mean the<br>hôtel which belonged to Monsieur de Bacqueville, in the reign of<br>King Charles VI.? there are indeed many superb high warp<br>tapestries there.”</p>\n<p>“Charles VI.! Charles VI.!” muttered the young captain, twirling<br>his moustache. “Good heavens! what old things the good dame does<br>remember!”</p>\n<p>Madame de Gondelaurier continued, “Fine tapestries, in truth. A<br>work so esteemed that it passes as unrivalled.”</p>\n<p>At that moment Bérangère de Champchevrier, a slender little maid<br>of seven years, who was peering into the square through the<br>trefoils of the balcony, exclaimed, “Oh! look, fair Godmother<br>Fleur-de-Lys, at that pretty dancer who is dancing on the<br>pavement and playing the tambourine in the midst of the loutish<br><em>bourgeois!</em>”</p>\n<p>The sonorous vibration of a tambourine was, in fact, audible.<br>“Some gypsy from Bohemia,” said Fleur-de-Lys, turning carelessly<br>toward the square.</p>\n<p>“Look! look!” exclaimed her lively companions; and they all ran<br>to the edge of the balcony, while Fleur-de-Lys, rendered<br>thoughtful by the coldness of her betrothed, followed them<br>slowly, and the latter, relieved by this incident, which put an<br>end to an embarrassing conversation, retreated to the farther end<br>of the room, with the satisfied air of a soldier released from<br>duty. Nevertheless, the fair Fleur-de-Lys’s was a charming and<br>noble service, and such it had formerly appeared to him; but the<br>captain had gradually become <em>blasé;</em> the prospect of a speedy<br>marriage cooled him more every day. Moreover, he was of a fickle<br>disposition, and, must we say it, rather vulgar in taste.<br>Although of very noble birth, he had contracted in his official<br>harness more than one habit of the common trooper. The tavern and<br>its accompaniments pleased him. He was only at his ease amid<br>gross language, military gallantries, facile beauties, and<br>successes yet more easy. He had, nevertheless, received from his<br>family some education and some politeness of manner; but he had<br>been thrown on the world too young, he had been in garrison at<br>too early an age, and every day the polish of a gentleman became<br>more and more effaced by the rough friction of his gendarme’s<br>cross-belt. While still continuing to visit her from time to<br>time, from a remnant of common respect, he felt doubly<br>embarrassed with Fleur-de-Lys; in the first place, because, in<br>consequence of having scattered his love in all sorts of places,<br>he had reserved very little for her; in the next place, because,<br>amid so many stiff, formal, and decent ladies, he was in constant<br>fear lest his mouth, habituated to oaths, should suddenly take<br>the bit in its teeth, and break out into the language of the<br>tavern. The effect can be imagined!</p>\n<p>Moreover, all this was mingled in him, with great pretentions to<br>elegance, toilet, and a fine appearance. Let the reader reconcile<br>these things as best he can. I am simply the historian.</p>\n<p>He had remained, therefore, for several minutes, leaning in<br>silence against the carved jamb of the chimney, and thinking or<br>not thinking, when Fleur-de-Lys suddenly turned and addressed<br>him. After all, the poor young girl was pouting against the<br>dictates of her heart.</p>\n<p>“Fair cousin, did you not speak to us of a little Bohemian whom<br>you saved a couple of months ago, while making the patrol with<br>the watch at night, from the hands of a dozen robbers?”</p>\n<p>“I believe so, fair cousin,” said the captain.</p>\n<p>“Well,” she resumed, “perchance ’tis that same gypsy girl who is<br>dancing yonder, on the church square. Come and see if you<br>recognize her, fair Cousin Phœbus.”</p>\n<p>A secret desire for reconciliation was apparent in this gentle<br>invitation which she gave him to approach her, and in the care<br>which she took to call him by name. Captain Phœbus de Châteaupers<br>(for it is he whom the reader has had before his eyes since the<br>beginning of this chapter) slowly approached the balcony. “Stay,”<br>said Fleur-de-Lys, laying her hand tenderly on Phœbus’s arm;<br>“look at that little girl yonder, dancing in that circle. Is she<br>your Bohemian?”</p>\n<p>Phœbus looked, and said,—</p>\n<p>“Yes, I recognize her by her goat.”</p>\n<p>“Oh! in fact, what a pretty little goat!” said Amelotte, clasping<br>her hands in admiration.</p>\n<p>“Are his horns of real gold?” inquired Bérangère.</p>\n<p>Without moving from her arm-chair, Dame Aloïse interposed, “Is<br>she not one of those gypsy girls who arrived last year by the<br>Gibard gate?”</p>\n<p>“Madame my mother,” said Fleur-de-Lys gently, “that gate is now<br>called the Porte d’Enfer.”</p>\n<p>Mademoiselle de Gondelaurier knew how her mother’s antiquated<br>mode of speech shocked the captain. In fact, he began to sneer,<br>and muttered between his teeth: “Porte Gibard! Porte Gibard! ’Tis<br>enough to make King Charles VI. pass by.”</p>\n<p>“Godmother!” exclaimed Bérangère, whose eyes, incessantly in<br>motion, had suddenly been raised to the summit of the towers of<br>Notre-Dame, “who is that black man up yonder?”</p>\n<p>All the young girls raised their eyes. A man was, in truth,<br>leaning on the balustrade which surmounted the northern tower,<br>looking on the Grève. He was a priest. His costume could be<br>plainly discerned, and his face resting on both his hands. But he<br>stirred no more than if he had been a statue. His eyes, intently<br>fixed, gazed into the Place.</p>\n<p>It was something like the immobility of a bird of prey, who has<br>just discovered a nest of sparrows, and is gazing at it.</p>\n<p>“’Tis monsieur the archdeacon of Josas,” said Fleur-de-Lys.</p>\n<p>“You have good eyes if you can recognize him from here,” said the<br>Gaillefontaine.</p>\n<p>“How he is staring at the little dancer!” went on Diane de<br>Christeuil.</p>\n<p>“Let the gypsy beware!” said Fleur-de-Lys, “for he loves not<br>Egypt.”</p>\n<p>“’Tis a great shame for that man to look upon her thus,” added<br>Amelotte de Montmichel, “for she dances delightfully.”</p>\n<p>“Fair cousin Phœbus,” said Fleur-de-Lys suddenly, “Since you know<br>this little gypsy, make her a sign to come up here. It will amuse<br>us.”</p>\n<p>“Oh, yes!” exclaimed all the young girls, clapping their hands.</p>\n<p>“Why! ’tis not worth while,” replied Phœbus. “She has forgotten<br>me, no doubt, and I know not so much as her name. Nevertheless,<br>as you wish it, young ladies, I will make the trial.” And leaning<br>over the balustrade of the balcony, he began to shout, “Little<br>one!”</p>\n<p>The dancer was not beating her tambourine at the moment. She<br>turned her head towards the point whence this call proceeded, her<br>brilliant eyes rested on Phœbus, and she stopped short.</p>\n<p>“Little one!” repeated the captain; and he beckoned her to<br>approach.</p>\n<p>The young girl looked at him again, then she blushed as though a<br>flame had mounted into her cheeks, and, taking her tambourine<br>under her arm, she made her way through the astonished spectators<br>towards the door of the house where Phœbus was calling her, with<br>slow, tottering steps, and with the troubled look of a bird which<br>is yielding to the fascination of a serpent.</p>\n<p>A moment later, the tapestry portière was raised, and the gypsy<br>appeared on the threshold of the chamber, blushing, confused,<br>breathless, her large eyes drooping, and not daring to advance<br>another step.</p>\n<p>Bérangère clapped her hands.</p>\n<p>Meanwhile, the dancer remained motionless upon the threshold. Her<br>appearance had produced a singular effect upon these young girls.<br>It is certain that a vague and indistinct desire to please the<br>handsome officer animated them all, that his splendid uniform was<br>the target of all their coquetries, and that from the moment he<br>presented himself, there existed among them a secret, suppressed<br>rivalry, which they hardly acknowledged even to themselves, but<br>which broke forth, none the less, every instant, in their<br>gestures and remarks. Nevertheless, as they were all very nearly<br>equal in beauty, they contended with equal arms, and each could<br>hope for the victory. The arrival of the gypsy suddenly destroyed<br>this equilibrium. Her beauty was so rare, that, at the moment<br>when she appeared at the entrance of the apartment, it seemed as<br>though she diffused a sort of light which was peculiar to<br>herself. In that narrow chamber, surrounded by that sombre frame<br>of hangings and woodwork, she was incomparably more beautiful and<br>more radiant than on the public square. She was like a torch<br>which has suddenly been brought from broad daylight into the<br>dark. The noble damsels were dazzled by her in spite of<br>themselves. Each one felt herself, in some sort, wounded in her<br>beauty. Hence, their battle front (may we be allowed the<br>expression,) was immediately altered, although they exchanged not<br>a single word. But they understood each other perfectly. Women’s<br>instincts comprehend and respond to each other more quickly than<br>the intelligences of men. An enemy had just arrived; all felt<br>it—all rallied together. One drop of wine is sufficient to tinge<br>a glass of water red; to diffuse a certain degree of ill temper<br>throughout a whole assembly of pretty women, the arrival of a<br>prettier woman suffices, especially when there is but one man<br>present.</p>\n<p>Hence the welcome accorded to the gypsy was marvellously glacial.<br>They surveyed her from head to foot, then exchanged glances, and<br>all was said; they understood each other. Meanwhile, the young<br>girl was waiting to be spoken to, in such emotion that she dared<br>not raise her eyelids.</p>\n<p>The captain was the first to break the silence. “Upon my word,”<br>said he, in his tone of intrepid fatuity, “here is a charming<br>creature! What think you of her, fair cousin?”</p>\n<p>This remark, which a more delicate admirer would have uttered in<br>a lower tone, at least was not of a nature to dissipate the<br>feminine jealousies which were on the alert before the gypsy.</p>\n<p>Fleur-de-Lys replied to the captain with a bland affectation of<br>disdain;—“Not bad.”</p>\n<p>The others whispered.</p>\n<p>At length, Madame Aloïse, who was not the less jealous because<br>she was so for her daughter, addressed the dancer,—“Approach,<br>little one.”</p>\n<p>“Approach, little one!” repeated, with comical dignity, little<br>Bérangère, who would have reached about as high as her hips.</p>\n<p>The gypsy advanced towards the noble dame.</p>\n<p>“Fair child,” said Phœbus, with emphasis, taking several steps<br>towards her, “I do not know whether I have the supreme honor of<br>being recognized by you.”</p>\n<p>She interrupted him, with a smile and a look full of infinite<br>sweetness,—</p>\n<p>“Oh! yes,” said she.</p>\n<p>“She has a good memory,” remarked Fleur-de-Lys.</p>\n<p>“Come, now,” resumed Phœbus, “you escaped nimbly the other<br>evening. Did I frighten you!”</p>\n<p>“Oh! no,” said the gypsy.</p>\n<p>There was in the intonation of that “Oh! no,” uttered after that<br>“Oh! yes,” an ineffable something which wounded Fleur-de-Lys.</p>\n<p>“You left me in your stead, my beauty,” pursued the captain,<br>whose tongue was unloosed when speaking to a girl out of the<br>street, “a crabbed knave, one-eyed and hunchbacked, the bishop’s<br>bellringer, I believe. I have been told that by birth he is the<br>bastard of an archdeacon and a devil. He has a pleasant name: he<br>is called <em>Quatre-Temps</em> (Ember Days), <em>Pâques-Fleuries</em> (Palm<br>Sunday), <em>Mardi-Gras</em> (Shrove Tuesday), I know not what! The name<br>of some festival when the bells are pealed! So he took the<br>liberty of carrying you off, as though you were made for beadles!<br>’Tis too much. What the devil did that screech-owl want with you?<br>Hey, tell me!”</p>\n<p>“I do not know,” she replied.</p>\n<p>“The inconceivable impudence! A bellringer carrying off a wench,<br>like a vicomte! a lout poaching on the game of gentlemen! that is<br>a rare piece of assurance. However, he paid dearly for it. Master<br>Pierrat Torterue is the harshest groom that ever curried a knave;<br>and I can tell you, if it will be agreeable to you, that your<br>bellringer’s hide got a thorough dressing at his hands.”</p>\n<p>“Poor man!” said the gypsy, in whom these words revived the<br>memory of the pillory.</p>\n<p>The captain burst out laughing.</p>\n<p>“Corne-de-bœuf! here’s pity as well placed as a feather in a<br>pig’s tail! May I have as big a belly as a pope, if—”</p>\n<p>He stopped short. “Pardon me, ladies; I believe that I was on the<br>point of saying something foolish.”</p>\n<p>“Fie, sir” said la Gaillefontaine.</p>\n<p>“He talks to that creature in her own tongue!” added<br>Fleur-de-Lys, in a low tone, her irritation increasing every<br>moment. This irritation was not diminished when she beheld the<br>captain, enchanted with the gypsy, and, most of all, with<br>himself, execute a pirouette on his heel, repeating with coarse,<br>naïve, and soldierly gallantry,—</p>\n<p>“A handsome wench, upon my soul!”</p>\n<p>“Rather savagely dressed,” said Diane de Christeuil, laughing to<br>show her fine teeth.</p>\n<p>This remark was a flash of light to the others. Not being able to<br>impugn her beauty, they attacked her costume.</p>\n<p>“That is true,” said la Montmichel; “what makes you run about the<br>streets thus, without guimpe or ruff?”</p>\n<p>“That petticoat is so short that it makes one tremble,” added la<br>Gaillefontaine.</p>\n<p>“My dear,” continued Fleur-de-Lys, with decided sharpness, “You<br>will get yourself taken up by the sumptuary police for your<br>gilded girdle.”</p>\n<p>“Little one, little one;” resumed la Christeuil, with an<br>implacable smile, “if you were to put respectable sleeves upon<br>your arms they would get less sunburned.”</p>\n<p>It was, in truth, a spectacle worthy of a more intelligent<br>spectator than Phœbus, to see how these beautiful maidens, with<br>their envenomed and angry tongues, wound, serpent-like, and<br>glided and writhed around the street dancer. They were cruel and<br>graceful; they searched and rummaged maliciously in her poor and<br>silly toilet of spangles and tinsel. There was no end to their<br>laughter, irony, and humiliation. Sarcasms rained down upon the<br>gypsy, and haughty condescension and malevolent looks. One would<br>have thought they were young Roman dames thrusting golden pins<br>into the breast of a beautiful slave. One would have pronounced<br>them elegant grayhounds, circling, with inflated nostrils, round<br>a poor woodland fawn, whom the glance of their master forbade<br>them to devour.</p>\n<p>After all, what was a miserable dancer on the public squares in<br>the presence of these high-born maidens? They seemed to take no<br>heed of her presence, and talked of her aloud, to her face, as of<br>something unclean, abject, and yet, at the same time, passably<br>pretty.</p>\n<p>The gypsy was not insensible to these pin-pricks. From time to<br>time a flush of shame, a flash of anger inflamed her eyes or her<br>cheeks; with disdain she made that little grimace with which the<br>reader is already familiar, but she remained motionless; she<br>fixed on Phœbus a sad, sweet, resigned look. There was also<br>happiness and tenderness in that gaze. One would have said that<br>she endured for fear of being expelled.</p>\n<p>Phœbus laughed, and took the gypsy’s part with a mixture of<br>impertinence and pity.</p>\n<p>“Let them talk, little one!” he repeated, jingling his golden<br>spurs. “No doubt your toilet is a little extravagant and wild,<br>but what difference does that make with such a charming damsel as<br>yourself?”</p>\n<p>“Good gracious!” exclaimed the blonde Gaillefontaine, drawing up<br>her swan-like throat, with a bitter smile. “I see that messieurs<br>the archers of the king’s police easily take fire at the handsome<br>eyes of gypsies!”</p>\n<p>“Why not?” said Phœbus.</p>\n<p>At this reply uttered carelessly by the captain, like a stray<br>stone, whose fall one does not even watch, Colombe began to<br>laugh, as well as Diane, Amelotte, and Fleur-de-Lys, into whose<br>eyes at the same time a tear started.</p>\n<p>The gypsy, who had dropped her eyes on the floor at the words of<br>Colombe de Gaillefontaine, raised them beaming with joy and pride<br>and fixed them once more on Phœbus. She was very beautiful at<br>that moment.</p>\n<p>The old dame, who was watching this scene, felt offended, without<br>understanding why.</p>\n<p>“Holy Virgin!” she suddenly exclaimed, “what is it moving about<br>my legs? Ah! the villanous beast!”</p>\n<p>It was the goat, who had just arrived, in search of his mistress,<br>and who, in dashing towards the latter, had begun by entangling<br>his horns in the pile of stuffs which the noble dame’s garments<br>heaped up on her feet when she was seated.</p>\n<p>This created a diversion. The gypsy disentangled his horns<br>without uttering a word.</p>\n<p>“Oh! here’s the little goat with golden hoofs!” exclaimed<br>Bérangère, dancing with joy.</p>\n<p>The gypsy crouched down on her knees and leaned her cheek against<br>the fondling head of the goat. One would have said that she was<br>asking pardon for having quitted it thus.</p>\n<p>Meanwhile, Diane had bent down to Colombe’s ear.</p>\n<p>“Ah! good heavens! why did not I think of that sooner? ’Tis the<br>gypsy with the goat. They say she is a sorceress, and that her<br>goat executes very miraculous tricks.”</p>\n<p>“Well!” said Colombe, “the goat must now amuse us in its turn,<br>and perform a miracle for us.”</p>\n<p>Diane and Colombe eagerly addressed the gypsy.</p>\n<p>“Little one, make your goat perform a miracle.”</p>\n<p>“I do not know what you mean,” replied the dancer.</p>\n<p>“A miracle, a piece of magic, a bit of sorcery, in short.”</p>\n<p>“I do not understand.” And she fell to caressing the pretty<br>animal, repeating, “Djali! Djali!”</p>\n<p>At that moment Fleur-de-Lys noticed a little bag of embroidered<br>leather suspended from the neck of the goat,—</p>\n<p>“What is that?” she asked of the gypsy.</p>\n<p>The gypsy raised her large eyes upon her and replied gravely,—</p>\n<p>“That is my secret.”</p>\n<p>“I should really like to know what your secret is,” thought<br>Fleur-de-Lys.</p>\n<p>Meanwhile, the good dame had risen angrily,—“Come now, gypsy, if<br>neither you nor your goat can dance for us, what are you doing<br>here?”</p>\n<p>The gypsy walked slowly towards the door, without making any<br>reply. But the nearer she approached it, the more her pace<br>slackened. An irresistible magnet seemed to hold her. Suddenly<br>she turned her eyes, wet with tears, towards Phœbus, and halted.</p>\n<p>“True God!” exclaimed the captain, “that’s not the way to depart.<br>Come back and dance something for us. By the way, my sweet love,<br>what is your name?”</p>\n<p>“La Esmeralda,” said the dancer, never taking her eyes from him.</p>\n<p>At this strange name, a burst of wild laughter broke from the<br>young girls.</p>\n<p>“Here’s a terrible name for a young lady,” said Diane.</p>\n<p>“You see well enough,” retorted Amelotte, “that she is an<br>enchantress.”</p>\n<p>“My dear,” exclaimed Dame Aloïse solemnly, “your parents did not<br>commit the sin of giving you that name at the baptismal font.”</p>\n<p>In the meantime, several minutes previously, Bérangère had coaxed<br>the goat into a corner of the room with a marchpane cake, without<br>any one having noticed her. In an instant they had become good<br>friends. The curious child had detached the bag from the goat’s<br>neck, had opened it, and had emptied out its contents on the rush<br>matting; it was an alphabet, each letter of which was separately<br>inscribed on a tiny block of boxwood. Hardly had these playthings<br>been spread out on the matting, when the child, with surprise,<br>beheld the goat (one of whose “miracles” this was no doubt), draw<br>out certain letters with its golden hoof, and arrange them, with<br>gentle pushes, in a certain order. In a moment they constituted a<br>word, which the goat seemed to have been trained to write, so<br>little hesitation did it show in forming it, and Bérangère<br>suddenly exclaimed, clasping her hands in admiration,—</p>\n<p>“Godmother Fleur-de-Lys, see what the goat has just done!”</p>\n<p>Fleur-de-Lys ran up and trembled. The letters arranged upon the<br>floor formed this word,—</p>\n<p>PHŒBUS.</p>\n<p>“Was it the goat who wrote that?” she inquired in a changed<br>voice.</p>\n<p>“Yes, godmother,” replied Bérangêre.</p>\n<p>It was impossible to doubt it; the child did not know how to<br>write.</p>\n<p>“This is the secret!” thought Fleur-de-Lys.</p>\n<p>Meanwhile, at the child’s exclamation, all had hastened up, the<br>mother, the young girls, the gypsy, and the officer.</p>\n<p>The gypsy beheld the piece of folly which the goat had committed.<br>She turned red, then pale, and began to tremble like a culprit<br>before the captain, who gazed at her with a smile of satisfaction<br>and amazement.</p>\n<p>“Phœbus!” whispered the young girls, stupefied: “’tis the<br>captain’s name!”</p>\n<p>“You have a marvellous memory!” said Fleur-de-Lys, to the<br>petrified gypsy. Then, bursting into sobs: “Oh!” she stammered<br>mournfully, hiding her face in both her beautiful hands, “she is<br>a magician!” And she heard another and a still more bitter voice<br>at the bottom of her heart, saying,—“She is a rival!”</p>\n<p>She fell fainting.</p>\n<p>“My daughter! my daughter!” cried the terrified mother. “Begone,<br>you gypsy of hell!”</p>\n<p>In a twinkling, La Esmeralda gathered up the unlucky letters,<br>made a sign to Djali, and went out through one door, while<br>Fleur-de-Lys was being carried out through the other.</p>\n<p>Captain Phœbus, on being left alone, hesitated for a moment<br>between the two doors, then he followed the gypsy.</p>\n<h1 class=\"chapter\" id=\"chapter-ii-a-priest-and-a-philosopher-are-two-di\">Chapter II. A PRIEST AND A PHILOSOPHER ARE TWO DIFFERENT THINGS.</h1>\n<p>The priest whom the young girls had observed at the top of the<br>North tower, leaning over the Place and so attentive to the dance<br>of the gypsy, was, in fact, Archdeacon Claude Frollo.</p>\n<p>Our readers have not forgotten the mysterious cell which the<br>archdeacon had reserved for himself in that tower. (I do not<br>know, by the way be it said, whether it be not the same, the<br>interior of which can be seen to-day through a little square<br>window, opening to the east at the height of a man above the<br>platform from which the towers spring; a bare and dilapidated<br>den, whose badly plastered walls are ornamented here and there,<br>at the present day, with some wretched yellow engravings<br>representing the façades of cathedrals. I presume that this hole<br>is jointly inhabited by bats and spiders, and that, consequently,<br>it wages a double war of extermination on the flies).</p>\n<p>Every day, an hour before sunset, the archdeacon ascended the<br>staircase to the tower, and shut himself up in this cell, where<br>he sometimes passed whole nights. That day, at the moment when,<br>standing before the low door of his retreat, he was fitting into<br>the lock the complicated little key which he always carried about<br>him in the purse suspended to his side, a sound of tambourine and<br>castanets had reached his ear. These sounds came from the Place<br>du Parvis. The cell, as we have already said, had only one window<br>opening upon the rear of the church. Claude Frollo had hastily<br>withdrawn the key, and an instant later, he was on the top of the<br>tower, in the gloomy and pensive attitude in which the maidens<br>had seen him.</p>\n<p>There he stood, grave, motionless, absorbed in one look and one<br>thought. All Paris lay at his feet, with the thousand spires of<br>its edifices and its circular horizon of gentle hills—with its<br>river winding under its bridges, and its people moving to and fro<br>through its streets,—with the clouds of its smoke,—with the<br>mountainous chain of its roofs which presses Notre-Dame in its<br>doubled folds; but out of all the city, the archdeacon gazed at<br>one corner only of the pavement, the Place du Parvis; in all that<br>throng at but one figure,—the gypsy.</p>\n<p>It would have been difficult to say what was the nature of this<br>look, and whence proceeded the flame that flashed from it. It was<br>a fixed gaze, which was, nevertheless, full of trouble and<br>tumult. And, from the profound immobility of his whole body,<br>barely agitated at intervals by an involuntary shiver, as a tree<br>is moved by the wind; from the stiffness of his elbows, more<br>marble than the balustrade on which they leaned; or the sight of<br>the petrified smile which contracted his face,—one would have<br>said that nothing living was left about Claude Frollo except his<br>eyes.</p>\n<p>The gypsy was dancing; she was twirling her tambourine on the tip<br>of her finger, and tossing it into the air as she danced<br>Provençal sarabands; agile, light, joyous, and unconscious of the<br>formidable gaze which descended perpendicularly upon her head.</p>\n<p>The crowd was swarming around her; from time to time, a man<br>accoutred in red and yellow made them form into a circle, and<br>then returned, seated himself on a chair a few paces from the<br>dancer, and took the goat’s head on his knees. This man seemed to<br>be the gypsy’s companion. Claude Frollo could not distinguish his<br>features from his elevated post.</p>\n<p>From the moment when the archdeacon caught sight of this<br>stranger, his attention seemed divided between him and the<br>dancer, and his face became more and more gloomy. All at once he<br>rose upright, and a quiver ran through his whole body: “Who is<br>that man?” he muttered between his teeth: “I have always seen her<br>alone before!”</p>\n<p>Then he plunged down beneath the tortuous vault of the spiral<br>staircase, and once more descended. As he passed the door of the<br>bell chamber, which was ajar, he saw something which struck him;<br>he beheld Quasimodo, who, leaning through an opening of one of<br>those slate penthouses which resemble enormous blinds, appeared<br>also to be gazing at the Place. He was engaged in so profound a<br>contemplation, that he did not notice the passage of his adopted<br>father. His savage eye had a singular expression; it was a<br>charmed, tender look. “This is strange!” murmured Claude. “Is it<br>the gypsy at whom he is thus gazing?” He continued his descent.<br>At the end of a few minutes, the anxious archdeacon entered upon<br>the Place from the door at the base of the tower.</p>\n<p>“What has become of the gypsy girl?” he said, mingling with the<br>group of spectators which the sound of the tambourine had<br>collected.</p>\n<p>“I know not,” replied one of his neighbors, “I think that she has<br>gone to make some of her fandangoes in the house opposite,<br>whither they have called her.”</p>\n<p>In the place of the gypsy, on the carpet, whose arabesques had<br>seemed to vanish but a moment previously by the capricious<br>figures of her dance, the archdeacon no longer beheld any one but<br>the red and yellow man, who, in order to earn a few testers in<br>his turn, was walking round the circle, with his elbows on his<br>hips, his head thrown back, his face red, his neck outstretched,<br>with a chair between his teeth. To the chair he had fastened a<br>cat, which a neighbor had lent, and which was spitting in great<br>affright.</p>\n<p>“Notre-Dame!” exclaimed the archdeacon, at the moment when the<br>juggler, perspiring heavily, passed in front of him with his<br>pyramid of chair and his cat, “What is Master Pierre Gringoire<br>doing here?”</p>\n<p>The harsh voice of the archdeacon threw the poor fellow into such<br>a commotion that he lost his equilibrium, together with his whole<br>edifice, and the chair and the cat tumbled pell-mell upon the<br>heads of the spectators, in the midst of inextinguishable<br>hootings.</p>\n<p>It is probable that Master Pierre Gringoire (for it was indeed<br>he) would have had a sorry account to settle with the neighbor<br>who owned the cat, and all the bruised and scratched faces which<br>surrounded him, if he had not hastened to profit by the tumult to<br>take refuge in the church, whither Claude Frollo had made him a<br>sign to follow him.</p>\n<p>The cathedral was already dark and deserted; the side-aisles were<br>full of shadows, and the lamps of the chapels began to shine out<br>like stars, so black had the vaulted ceiling become. Only the<br>great rose window of the façade, whose thousand colors were<br>steeped in a ray of horizontal sunlight, glittered in the gloom<br>like a mass of diamonds, and threw its dazzling reflection to the<br>other end of the nave.</p>\n<p>When they had advanced a few paces, Dom Claude placed his back<br>against a pillar, and gazed intently at Gringoire. The gaze was<br>not the one which Gringoire feared, ashamed as he was of having<br>been caught by a grave and learned person in the costume of a<br>buffoon. There was nothing mocking or ironical in the priest’s<br>glance, it was serious, tranquil, piercing. The archdeacon was<br>the first to break the silence.</p>\n<p>“Come now, Master Pierre. You are to explain many things to me.<br>And first of all, how comes it that you have not been seen for<br>two months, and that now one finds you in the public squares, in<br>a fine equipment in truth! Motley red and yellow, like a Caudebec<br>apple?”</p>\n<p>“Messire,” said Gringoire, piteously, “it is, in fact, an amazing<br>accoutrement. You see me no more comfortable in it than a cat<br>coiffed with a calabash. ’Tis very ill done, I am conscious, to<br>expose messieurs the sergeants of the watch to the liability of<br>cudgelling beneath this cassock the humerus of a Pythagorean<br>philosopher. But what would you have, my reverend master? ’tis<br>the fault of my ancient jerkin, which abandoned me in cowardly<br>wise, at the beginning of the winter, under the pretext that it<br>was falling into tatters, and that it required repose in the<br>basket of a rag-picker. What is one to do? Civilization has not<br>yet arrived at the point where one can go stark naked, as ancient<br>Diogenes wished. Add that a very cold wind was blowing, and ’tis<br>not in the month of January that one can successfully attempt to<br>make humanity take this new step. This garment presented itself,<br>I took it, and I left my ancient black smock, which, for a<br>hermetic like myself, was far from being hermetically closed.<br>Behold me then, in the garments of a stage-player, like Saint<br>Genest. What would you have? ’tis an eclipse. Apollo himself<br>tended the flocks of Admetus.”</p>\n<p>“’Tis a fine profession that you are engaged in!” replied the<br>archdeacon.</p>\n<p>“I agree, my master, that ’tis better to philosophize and<br>poetize, to blow the flame in the furnace, or to receive it from<br>carry cats on a shield. So, when you addressed me, I was as<br>foolish as an ass before a turnspit. But what would you have,<br>messire? One must eat every day, and the finest Alexandrine<br>verses are not worth a bit of Brie cheese. Now, I made for Madame<br>Marguerite of Flanders, that famous epithalamium, as you know,<br>and the city will not pay me, under the pretext that it was not<br>excellent; as though one could give a tragedy of Sophocles for<br>four crowns! Hence, I was on the point of dying with hunger.<br>Happily, I found that I was rather strong in the jaw; so I said<br>to this jaw,—perform some feats of strength and of equilibrium:<br>nourish thyself. <em>Ale te ipsam</em>. A pack of beggars who have<br>become my good friends, have taught me twenty sorts of herculean<br>feats, and now I give to my teeth every evening the bread which<br>they have earned during the day by the sweat of my brow. After<br>all, <em>concedo</em>, I grant that it is a sad employment for my<br>intellectual faculties, and that man is not made to pass his life<br>in beating the tambourine and biting chairs. But, reverend<br>master, it is not sufficient to pass one’s life, one must earn<br>the means for life.”</p>\n<p>Dom Claude listened in silence. All at once his deep-set eye<br>assumed so sagacious and penetrating an expression, that<br>Gringoire felt himself, so to speak, searched to the bottom of<br>the soul by that glance.</p>\n<p>“Very good, Master Pierre; but how comes it that you are now in<br>company with that gypsy dancer?”</p>\n<p>“In faith!” said Gringoire, “’tis because she is my wife and I am<br>her husband.”</p>\n<p>The priest’s gloomy eyes flashed into flame.</p>\n<p>“Have you done that, you wretch!” he cried, seizing Gringoire’s<br>arm with fury; “have you been so abandoned by God as to raise<br>your hand against that girl?”</p>\n<p>“On my chance of paradise, monseigneur,” replied Gringoire,<br>trembling in every limb, “I swear to you that I have never<br>touched her, if that is what disturbs you.”</p>\n<p>“Then why do you talk of husband and wife?” said the priest.<br>Gringoire made haste to relate to him as succinctly as possible,<br>all that the reader already knows, his adventure in the Court of<br>Miracles and the broken-crock marriage. It appeared, moreover,<br>that this marriage had led to no results whatever, and that each<br>evening the gypsy girl cheated him of his nuptial right as on the<br>first day. “’Tis a mortification,” he said in conclusion, “but<br>that is because I have had the misfortune to wed a virgin.”</p>\n<p>“What do you mean?” demanded the archdeacon, who had been<br>gradually appeased by this recital.</p>\n<p>“’Tis very difficult to explain,” replied the poet. “It is a<br>superstition. My wife is, according to what an old thief, who is<br>called among us the Duke of Egypt, has told me, a foundling or a<br>lost child, which is the same thing. She wears on her neck an<br>amulet which, it is affirmed, will cause her to meet her parents<br>some day, but which will lose its virtue if the young girl loses<br>hers. Hence it follows that both of us remain very virtuous.”</p>\n<p>“So,” resumed Claude, whose brow cleared more and more, “you<br>believe, Master Pierre, that this creature has not been<br>approached by any man?”</p>\n<p>“What would you have a man do, Dom Claude, as against a<br>superstition? She has got that in her head. I assuredly esteem as<br>a rarity this nunlike prudery which is preserved untamed amid<br>those Bohemian girls who are so easily brought into subjection.<br>But she has three things to protect her: the Duke of Egypt, who<br>has taken her under his safeguard, reckoning, perchance, on<br>selling her to some gay abbé; all his tribe, who hold her in<br>singular veneration, like a Notre-Dame; and a certain tiny<br>poignard, which the buxom dame always wears about her, in some<br>nook, in spite of the ordinances of the provost, and which one<br>causes to fly out into her hands by squeezing her waist. ’Tis a<br>proud wasp, I can tell you!”</p>\n<p>The archdeacon pressed Gringoire with questions.</p>\n<p>La Esmeralda, in the judgment of Gringoire, was an inoffensive<br>and charming creature, pretty, with the exception of a pout which<br>was peculiar to her; a naïve and passionate damsel, ignorant of<br>everything and enthusiastic about everything; not yet aware of<br>the difference between a man and a woman, even in her dreams;<br>made like that; wild especially over dancing, noise, the open<br>air; a sort of woman bee, with invisible wings on her feet, and<br>living in a whirlwind. She owed this nature to the wandering life<br>which she had always led. Gringoire had succeeded in learning<br>that, while a mere child, she had traversed Spain and Catalonia,<br>even to Sicily; he believed that she had even been taken by the<br>caravan of Zingari, of which she formed a part, to the kingdom of<br>Algiers, a country situated in Achaia, which country adjoins, on<br>one side Albania and Greece; on the other, the Sicilian Sea,<br>which is the road to Constantinople. The Bohemians, said<br>Gringoire, were vassals of the King of Algiers, in his quality of<br>chief of the White Moors. One thing is certain, that la Esmeralda<br>had come to France while still very young, by way of Hungary.<br>From all these countries the young girl had brought back<br>fragments of queer jargons, songs, and strange ideas, which made<br>her language as motley as her costume, half Parisian, half<br>African. However, the people of the quarters which she frequented<br>loved her for her gayety, her daintiness, her lively manners, her<br>dances, and her songs. She believed herself to be hated, in all<br>the city, by but two persons, of whom she often spoke in terror:<br>the sacked nun of the Tour-Roland, a villanous recluse who<br>cherished some secret grudge against these gypsies, and who<br>cursed the poor dancer every time that the latter passed before<br>her window; and a priest, who never met her without casting at<br>her looks and words which frightened her.</p>\n<p>The mention of this last circumstance disturbed the archdeacon<br>greatly, though Gringoire paid no attention to his perturbation;<br>to such an extent had two months sufficed to cause the heedless<br>poet to forget the singular details of the evening on which he<br>had met the gypsy, and the presence of the archdeacon in it all.<br>Otherwise, the little dancer feared nothing; she did not tell<br>fortunes, which protected her against those trials for magic<br>which were so frequently instituted against gypsy women. And<br>then, Gringoire held the position of her brother, if not of her<br>husband. After all, the philosopher endured this sort of platonic<br>marriage very patiently. It meant a shelter and bread at least.<br>Every morning, he set out from the lair of the thieves, generally<br>with the gypsy; he helped her make her collections of targes[34]<br>and little blanks[35] in the squares; each evening he returned to<br>the same roof with her, allowed her to bolt herself into her<br>little chamber, and slept the sleep of the just. A very sweet<br>existence, taking it all in all, he said, and well adapted to<br>revery. And then, on his soul and conscience, the philosopher was<br>not very sure that he was madly in love with the gypsy. He loved<br>her goat almost as dearly. It was a charming animal, gentle,<br>intelligent, clever; a learned goat. Nothing was more common in<br>the Middle Ages than these learned animals, which amazed people<br>greatly, and often led their instructors to the stake. But the<br>witchcraft of the goat with the golden hoofs was a very innocent<br>species of magic. Gringoire explained them to the archdeacon,<br>whom these details seemed to interest deeply. In the majority of<br>cases, it was sufficient to present the tambourine to the goat in<br>such or such a manner, in order to obtain from him the trick<br>desired. He had been trained to this by the gypsy, who possessed,<br>in these delicate arts, so rare a talent that two months had<br>sufficed to teach the goat to write, with movable letters, the<br>word “Phœbus.”</p>\n<p>“‘Phœbus!’” said the priest; “why ‘Phœbus’?”</p>\n<p>“I know not,” replied Gringoire. “Perhaps it is a word which she<br>believes to be endowed with some magic and secret virtue. She<br>often repeats it in a low tone when she thinks that she is<br>alone.”</p>\n<p>“Are you sure,” persisted Claude, with his penetrating glance,<br>“that it is only a word and not a name?”</p>\n<p>“The name of whom?” said the poet.</p>\n<p>“How should I know?” said the priest.</p>\n<p>“This is what I imagine, messire. These Bohemians are something<br>like Guebrs, and adore the sun. Hence, Phœbus.”</p>\n<p>“That does not seem so clear to me as to you, Master Pierre.”</p>\n<p>“After all, that does not concern me. Let her mumble her Phœbus<br>at her pleasure. One thing is certain, that Djali loves me almost<br>as much as he does her.”</p>\n<p>“Who is Djali?”</p>\n<p>“The goat.”</p>\n<p>The archdeacon dropped his chin into his hand, and appeared to<br>reflect for a moment. All at once he turned abruptly to Gringoire<br>once more.</p>\n<p>“And do you swear to me that you have not touched her?”</p>\n<p>“Whom?” said Gringoire; “the goat?”</p>\n<p>“No, that woman.”</p>\n<p>“My wife? I swear to you that I have not.”</p>\n<p>“You are often alone with her?”</p>\n<p>“A good hour every evening.”</p>\n<p>Dom Claude frowned.</p>\n<p>“Oh! oh! <em>Solus cum sola non cogitabuntur orare Pater Noster</em>.”</p>\n<p>“Upon my soul, I could say the <em>Pater</em>, and the <em>Ave Maria</em>, and<br>the <em>Credo in Deum patrem omnipotentem</em> without her paying any<br>more attention to me than a chicken to a church.”</p>\n<p>“Swear to me, by the body of your mother,” repeated the<br>archdeacon violently, “that you have not touched that creature<br>with even the tip of your finger.”</p>\n<p>“I will also swear it by the head of my father, for the two<br>things have more affinity between them. But, my reverend master,<br>permit me a question in my turn.”</p>\n<p>“Speak, sir.”</p>\n<p>“What concern is it of yours?”</p>\n<p>The archdeacon’s pale face became as crimson as the cheek of a<br>young girl. He remained for a moment without answering; then,<br>with visible embarrassment,—</p>\n<p>“Listen, Master Pierre Gringoire. You are not yet damned, so far<br>as I know. I take an interest in you, and wish you well. Now the<br>least contact with that Egyptian of the demon would make you the<br>vassal of Satan. You know that ’tis always the body which ruins<br>the soul. Woe to you if you approach that woman! That is all.”</p>\n<p>“I tried once,” said Gringoire, scratching his ear; “it was the<br>first day: but I got stung.”</p>\n<p>“You were so audacious, Master Pierre?” and the priest’s brow<br>clouded over again.</p>\n<p>“On another occasion,” continued the poet, with a smile, “I<br>peeped through the keyhole, before going to bed, and I beheld the<br>most delicious dame in her shift that ever made a bed creak under<br>her bare foot.”</p>\n<p>“Go to the devil!” cried the priest, with a terrible look; and,<br>giving the amazed Gringoire a push on the shoulders, he plunged,<br>with long strides, under the gloomiest arcades of the cathedral.</p>\n<h1 class=\"chapter\" id=\"chapter-iii-the-bells\">Chapter III. THE BELLS.</h1>\n<p>After the morning in the pillory, the neighbors of Notre-Dame<br>thought they noticed that Quasimodo’s ardor for ringing had grown<br>cool. Formerly, there had been peals for every occasion, long<br>morning serenades, which lasted from prime to compline; peals<br>from the belfry for a high mass, rich scales drawn over the<br>smaller bells for a wedding, for a christening, and mingling in<br>the air like a rich embroidery of all sorts of charming sounds.<br>The old church, all vibrating and sonorous, was in a perpetual<br>joy of bells. One was constantly conscious of the presence of a<br>spirit of noise and caprice, who sang through all those mouths of<br>brass. Now that spirit seemed to have departed; the cathedral<br>seemed gloomy, and gladly remained silent; festivals and funerals<br>had the simple peal, dry and bare, demanded by the ritual,<br>nothing more. Of the double noise which constitutes a church, the<br>organ within, the bell without, the organ alone remained. One<br>would have said that there was no longer a musician in the<br>belfry. Quasimodo was always there, nevertheless; what, then, had<br>happened to him? Was it that the shame and despair of the pillory<br>still lingered in the bottom of his heart, that the lashes of his<br>tormentor’s whip reverberated unendingly in his soul, and that<br>the sadness of such treatment had wholly extinguished in him even<br>his passion for the bells? or was it that Marie had a rival in<br>the heart of the bellringer of Notre-Dame, and that the great<br>bell and her fourteen sisters were neglected for something more<br>amiable and more beautiful?</p>\n<p>It chanced that, in the year of grace 1482, Annunciation Day fell<br>on Tuesday, the twenty-fifth of March. That day the air was so<br>pure and light that Quasimodo felt some returning affection for<br>his bells. He therefore ascended the northern tower while the<br>beadle below was opening wide the doors of the church, which were<br>then enormous panels of stout wood, covered with leather,<br>bordered with nails of gilded iron, and framed in carvings “very<br>artistically elaborated.”</p>\n<p>On arriving in the lofty bell chamber, Quasimodo gazed for some<br>time at the six bells and shook his head sadly, as though<br>groaning over some foreign element which had interposed itself in<br>his heart between them and him. But when he had set them to<br>swinging, when he felt that cluster of bells moving under his<br>hand, when he saw, for he did not hear it, the palpitating octave<br>ascend and descend that sonorous scale, like a bird hopping from<br>branch to branch; when the demon Music, that demon who shakes a<br>sparkling bundle of strette, trills and arpeggios, had taken<br>possession of the poor deaf man, he became happy once more, he<br>forgot everything, and his heart expanding, made his face beam.</p>\n<p>He went and came, he beat his hands together, he ran from rope to<br>rope, he animated the six singers with voice and gesture, like<br>the leader of an orchestra who is urging on intelligent<br>musicians.</p>\n<p>“Go on,” said he, “go on, go on, Gabrielle, pour out all thy<br>noise into the Place, ’tis a festival to-day. No laziness,<br>Thibauld; thou art relaxing; go on, go on, then, art thou rusted,<br>thou sluggard? That is well! quick! quick! let not thy clapper be<br>seen! Make them all deaf like me. That’s it, Thibauld, bravely<br>done! Guillaume! Guillaume! thou art the largest, and Pasquier is<br>the smallest, and Pasquier does best. Let us wager that those who<br>hear him will understand him better than they understand thee.<br>Good! good! my Gabrielle, stoutly, more stoutly! Eli! what are<br>you doing up aloft there, you two Moineaux (sparrows)? I do not<br>see you making the least little shred of noise. What is the<br>meaning of those beaks of copper which seem to be gaping when<br>they should sing? Come, work now, ’tis the Feast of the<br>Annunciation. The sun is fine, the chime must be fine also. Poor<br>Guillaume! thou art all out of breath, my big fellow!”</p>\n<p>He was wholly absorbed in spurring on his bells, all six of which<br>vied with each other in leaping and shaking their shining<br>haunches, like a noisy team of Spanish mules, pricked on here and<br>there by the apostrophes of the muleteer.</p>\n<p>All at once, on letting his glance fall between the large slate<br>scales which cover the perpendicular wall of the bell tower at a<br>certain height, he beheld on the square a young girl,<br>fantastically dressed, stop, spread out on the ground a carpet,<br>on which a small goat took up its post, and a group of spectators<br>collect around her. This sight suddenly changed the course of his<br>ideas, and congealed his enthusiasm as a breath of air congeals<br>melted rosin. He halted, turned his back to the bells, and<br>crouched down behind the projecting roof of slate, fixing upon<br>the dancer that dreamy, sweet, and tender look which had already<br>astonished the archdeacon on one occasion. Meanwhile, the<br>forgotten bells died away abruptly and all together, to the great<br>disappointment of the lovers of bell ringing, who were listening<br>in good faith to the peal from above the Pont du Change, and who<br>went away dumbfounded, like a dog who has been offered a bone and<br>given a stone.</p>\n<h1 class=\"chapter\" id=\"chapter-iv\">Chapter IV. ἈΝÁΓΚΗ.</h1>\n<p>It chanced that upon a fine morning in this same month of March,<br>I think it was on Saturday the 29th, Saint Eustache’s day, our<br>young friend the student, Jehan Frollo du Moulin, perceived, as<br>he was dressing himself, that his breeches, which contained his<br>purse, gave out no metallic ring. “Poor purse,” he said, drawing<br>it from his fob, “what! not the smallest parisis! how cruelly the<br>dice, beer-pots, and Venus have depleted thee! How empty,<br>wrinkled, limp, thou art! Thou resemblest the throat of a fury! I<br>ask you, Messer Cicero, and Messer Seneca, copies of whom, all<br>dog’s-eared, I behold scattered on the floor, what profits it me<br>to know, better than any governor of the mint, or any Jew on the<br>Pont aux Changeurs, that a golden crown stamped with a crown is<br>worth thirty-five unzains of twenty-five sous, and eight deniers<br>parisis apiece, and that a crown stamped with a crescent is worth<br>thirty-six unzains of twenty-six sous, six deniers tournois<br>apiece, if I have not a single wretched black liard to risk on<br>the double-six! Oh! Consul Cicero! this is no calamity from which<br>one extricates one’s self with periphrases, <em>quemadmodum</em>, and<br><em>verum enim vero!</em>”</p>\n<p>He dressed himself sadly. An idea had occurred to him as he laced<br>his boots, but he rejected it at first; nevertheless, it<br>returned, and he put on his waistcoat wrong side out, an evident<br>sign of violent internal combat. At last he dashed his cap<br>roughly on the floor, and exclaimed: “So much the worse! Let come<br>of it what may. I am going to my brother! I shall catch a sermon,<br>but I shall catch a crown.”</p>\n<p>Then he hastily donned his long jacket with furred half-sleeves,<br>picked up his cap, and went out like a man driven to desperation.</p>\n<p>He descended the Rue de la Harpe toward the City. As he passed<br>the Rue de la Huchette, the odor of those admirable spits, which<br>were incessantly turning, tickled his olfactory apparatus, and he<br>bestowed a loving glance toward the Cyclopean roast, which one<br>day drew from the Franciscan friar, Calatagirone, this pathetic<br>exclamation: _Veramente, queste rotisserie sono cosa<br>stupenda!_[36] But Jehan had not the wherewithal to buy a<br>breakfast, and he plunged, with a profound sigh, under the<br>gateway of the Petit-Châtelet, that enormous double trefoil of<br>massive towers which guarded the entrance to the City.</p>\n<p>He did not even take the trouble to cast a stone in passing, as<br>was the usage, at the miserable statue of that Périnet Leclerc<br>who had delivered up the Paris of Charles VI. to the English, a<br>crime which his effigy, its face battered with stones and soiled<br>with mud, expiated for three centuries at the corner of the Rue<br>de la Harpe and the Rue de Buci, as in an eternal pillory.</p>\n<p>The Petit-Pont traversed, the Rue Neuve-Sainte-Geneviève crossed,<br>Jehan de Molendino found himself in front of Notre-Dame. Then<br>indecision seized upon him once more, and he paced for several<br>minutes round the statue of M. Legris, repeating to himself with<br>anguish: “The sermon is sure, the crown is doubtful.”</p>\n<p>He stopped a beadle who emerged from the cloister,—“Where is<br>monsieur the archdeacon of Josas?”</p>\n<p>“I believe that he is in his secret cell in the tower,” said the<br>beadle; “I should advise you not to disturb him there, unless you<br>come from some one like the pope or monsieur the king.”</p>\n<p>Jehan clapped his hands.</p>\n<p>“<em>Bédiable!</em> here’s a magnificent chance to see the famous<br>sorcery cell!”</p>\n<p>This reflection having brought him to a decision, he plunged<br>resolutely into the small black doorway, and began the ascent of<br>the spiral of Saint-Gilles, which leads to the upper stories of<br>the tower. “I am going to see,” he said to himself on the way.<br>“By the ravens of the Holy Virgin! it must needs be a curious<br>thing, that cell which my reverend brother hides so secretly!<br>’Tis said that he lights up the kitchens of hell there, and that<br>he cooks the philosopher’s stone there over a hot fire. <em>Bédieu!</em><br>I care no more for the philosopher’s stone than for a pebble, and<br>I would rather find over his furnace an omelette of Easter eggs<br>and bacon, than the biggest philosopher’s stone in the world.”’</p>\n<p>On arriving at the gallery of slender columns, he took breath for<br>a moment, and swore against the interminable staircase by I know<br>not how many million cartloads of devils; then he resumed his<br>ascent through the narrow door of the north tower, now closed to<br>the public. Several moments after passing the bell chamber, he<br>came upon a little landing-place, built in a lateral niche, and<br>under the vault of a low, pointed door, whose enormous lock and<br>strong iron bars he was enabled to see through a loophole pierced<br>in the opposite circular wall of the staircase. Persons desirous<br>of visiting this door at the present day will recognize it by<br>this inscription engraved in white letters on the black wall:<br>“J’ADORE CORALIE, 1823. SIGNÉ UGÈNE.” “Signé” stands in the text.</p>\n<p>“Ugh!” said the scholar; “’tis here, no doubt.”</p>\n<p>The key was in the lock, the door was very close to him; he gave<br>it a gentle push and thrust his head through the opening.</p>\n<p>The reader cannot have failed to turn over the admirable works of<br>Rembrandt, that Shakespeare of painting. Amid so many marvellous<br>engravings, there is one etching in particular, which is supposed<br>to represent Doctor Faust, and which it is impossible to<br>contemplate without being dazzled. It represents a gloomy cell;<br>in the centre is a table loaded with hideous objects; skulls,<br>spheres, alembics, compasses, hieroglyphic parchments. The doctor<br>is before this table clad in his large coat and covered to the<br>very eyebrows with his furred cap. He is visible only to his<br>waist. He has half risen from his immense arm-chair, his clenched<br>fists rest on the table, and he is gazing with curiosity and<br>terror at a large luminous circle, formed of magic letters, which<br>gleams from the wall beyond, like the solar spectrum in a dark<br>chamber. This cabalistic sun seems to tremble before the eye, and<br>fills the wan cell with its mysterious radiance. It is horrible<br>and it is beautiful.</p>\n<p>Something very similar to Faust’s cell presented itself to<br>Jehan’s view, when he ventured his head through the half-open<br>door. It also was a gloomy and sparsely lighted retreat. There<br>also stood a large arm-chair and a large table, compasses,<br>alembics, skeletons of animals suspended from the ceiling, a<br>globe rolling on the floor, hippocephali mingled promiscuously<br>with drinking cups, in which quivered leaves of gold, skulls<br>placed upon vellum checkered with figures and characters, huge<br>manuscripts piled up wide open, without mercy on the cracking<br>corners of the parchment; in short, all the rubbish of science,<br>and everywhere on this confusion dust and spiders’ webs; but<br>there was no circle of luminous letters, no doctor in an ecstasy<br>contemplating the flaming vision, as the eagle gazes upon the<br>sun.</p>\n<p>Nevertheless, the cell was not deserted. A man was seated in the<br>arm-chair, and bending over the table. Jehan, to whom his back<br>was turned, could see only his shoulders and the back of his<br>skull; but he had no difficulty in recognizing that bald head,<br>which nature had provided with an eternal tonsure, as though<br>desirous of marking, by this external symbol, the archdeacon’s<br>irresistible clerical vocation.</p>\n<p>Jehan accordingly recognized his brother; but the door had been<br>opened so softly, that nothing warned Dom Claude of his presence.<br>The inquisitive scholar took advantage of this circumstance to<br>examine the cell for a few moments at his leisure. A large<br>furnace, which he had not at first observed, stood to the left of<br>the arm-chair, beneath the window. The ray of light which<br>penetrated through this aperture made its way through a spider’s<br>circular web, which tastefully inscribed its delicate rose in the<br>arch of the window, and in the centre of which the insect<br>architect hung motionless, like the hub of this wheel of lace.<br>Upon the furnace were accumulated in disorder, all sorts of<br>vases, earthenware bottles, glass retorts, and mattresses of<br>charcoal. Jehan observed, with a sigh, that there was no<br>frying-pan. “How cold the kitchen utensils are!” he said to<br>himself.</p>\n<p>In fact, there was no fire in the furnace, and it seemed as<br>though none had been lighted for a long time. A glass mask, which<br>Jehan noticed among the utensils of alchemy, and which served no<br>doubt, to protect the archdeacon’s face when he was working over<br>some substance to be dreaded, lay in one corner covered with dust<br>and apparently forgotten. Beside it lay a pair of bellows no less<br>dusty, the upper side of which bore this inscription incrusted in<br>copper letters: SPIRA SPERA.</p>\n<p>Other inscriptions were written, in accordance with the fashion<br>of the hermetics, in great numbers on the walls; some traced with<br>ink, others engraved with a metal point. There were, moreover,<br>Gothic letters, Hebrew letters, Greek letters, and Roman letters,<br>pell-mell; the inscriptions overflowed at haphazard, on top of<br>each other, the more recent effacing the more ancient, and all<br>entangled with each other, like the branches in a thicket, like<br>pikes in an affray. It was, in fact, a strangely confused<br>mingling of all human philosophies, all reveries, all human<br>wisdom. Here and there one shone out from among the rest like a<br>banner among lance heads. Generally, it was a brief Greek or<br>Roman device, such as the Middle Ages knew so well how to<br>formulate.—_Unde? Inde?—Homo homini monstrum—Astra, castra,<br>nomen, numen.<em>—Μέγα βιβλίον, μέγα κακόν.—</em>Sapere aude. Fiat ubi<br>vult_—etc.; sometimes a word devoid of all apparent sense,<br>Ἀναγκοφαγία, which possibly contained a bitter allusion to the<br>regime of the cloister; sometimes a simple maxim of clerical<br>discipline formulated in a regular hexameter _Cœlestem dominum<br>terrestrem dicite dominum_. There was also Hebrew jargon, of<br>which Jehan, who as yet knew but little Greek, understood<br>nothing; and all were traversed in every direction by stars, by<br>figures of men or animals, and by intersecting triangles; and<br>this contributed not a little to make the scrawled wall of the<br>cell resemble a sheet of paper over which a monkey had drawn back<br>and forth a pen filled with ink.</p>\n<p>The whole chamber, moreover, presented a general aspect of<br>abandonment and dilapidation; and the bad state of the utensils<br>induced the supposition that their owner had long been distracted<br>from his labors by other preoccupations. Meanwhile, this master,<br>bent over a vast manuscript, ornamented with fantastical<br>illustrations, appeared to be tormented by an idea which<br>incessantly mingled with his meditations. That at least was<br>Jehan’s idea, when he heard him exclaim, with the thoughtful<br>breaks of a dreamer thinking aloud,—</p>\n<p>“Yes, Manou said it, and Zoroaster taught it! the sun is born<br>from fire, the moon from the sun; fire is the soul of the<br>universe; its elementary atoms pour forth and flow incessantly<br>upon the world through infinite channels! At the point where<br>these currents intersect each other in the heavens, they produce<br>light; at their points of intersection on earth, they produce<br>gold. Light, gold; the same thing! From fire to the concrete<br>state. The difference between the visible and the palpable,<br>between the fluid and the solid in the same substance, between<br>water and ice, nothing more. These are no dreams; it is the<br>general law of nature. But what is one to do in order to extract<br>from science the secret of this general law? What! this light<br>which inundates my hand is gold! These same atoms dilated in<br>accordance with a certain law need only be condensed in<br>accordance with another law. How is it to be done? Some have<br>fancied by burying a ray of sunlight, Averroës,—yes, ’tis<br>Averroës,—Averroës buried one under the first pillar on the left<br>of the sanctuary of the Koran, in the great Mahometan mosque of<br>Cordova; but the vault cannot be opened for the purpose of<br>ascertaining whether the operation has succeeded, until after the<br>lapse of eight thousand years.</p>\n<p>“The devil!” said Jehan, to himself, “’tis a long while to wait<br>for a crown!”</p>\n<p>“Others have thought,” continued the dreamy archdeacon, “that it<br>would be better worth while to operate upon a ray of Sirius. But<br>’tis exceeding hard to obtain this ray pure, because of the<br>simultaneous presence of other stars whose rays mingle with it.<br>Flamel esteemed it more simple to operate upon terrestrial fire.<br>Flamel! there’s predestination in the name! <em>Flamma!</em> yes, fire.<br>All lies there. The diamond is contained in the carbon, gold is<br>in the fire. But how to extract it? Magistri affirms that there<br>are certain feminine names, which possess a charm so sweet and<br>mysterious, that it suffices to pronounce them during the<br>operation. Let us read what Manon says on the matter: ‘Where<br>women are honored, the divinities are rejoiced; where they are<br>despised, it is useless to pray to God. The mouth of a woman is<br>constantly pure; it is a running water, it is a ray of sunlight.<br>The name of a woman should be agreeable, sweet, fanciful; it<br>should end in long vowels, and resemble words of benediction.’<br>Yes, the sage is right; in truth, Maria, Sophia, la<br>Esmeral—Damnation! always that thought!”</p>\n<p>And he closed the book violently.</p>\n<p>He passed his hand over his brow, as though to brush away the<br>idea which assailed him; then he took from the table a nail and a<br>small hammer, whose handle was curiously painted with cabalistic<br>letters.</p>\n<p>“For some time,” he said with a bitter smile, “I have failed in<br>all my experiments! one fixed idea possesses me, and sears my<br>brain like fire. I have not even been able to discover the secret<br>of Cassiodorus, whose lamp burned without wick and without oil. A<br>simple matter, nevertheless—”</p>\n<p>“The deuce!” muttered Jehan in his beard.</p>\n<p>“Hence,” continued the priest, “one wretched thought is<br>sufficient to render a man weak and beside himself! Oh! how<br>Claude Pernelle would laugh at me. She who could not turn<br>Nicholas Flamel aside, for one moment, from his pursuit of the<br>great work! What! I hold in my hand the magic hammer of Zéchiélé!<br>at every blow dealt by the formidable rabbi, from the depths of<br>his cell, upon this nail, that one of his enemies whom he had<br>condemned, were he a thousand leagues away, was buried a cubit<br>deep in the earth which swallowed him. The King of France<br>himself, in consequence of once having inconsiderately knocked at<br>the door of the thermaturgist, sank to the knees through the<br>pavement of his own Paris. This took place three centuries ago.<br>Well! I possess the hammer and the nail, and in my hands they are<br>utensils no more formidable than a club in the hands of a maker<br>of edge tools. And yet all that is required is to find the magic<br>word which Zéchiélé pronounced when he struck his nail.”</p>\n<p>“What nonsense!” thought Jehan.</p>\n<p>“Let us see, let us try!” resumed the archdeacon briskly. “Were I<br>to succeed, I should behold the blue spark flash from the head of<br>the nail. Emen-Hétan! Emen-Hétan! That’s not it. Sigéani!<br>Sigéani! May this nail open the tomb to any one who bears the<br>name of Phœbus! A curse upon it! Always and eternally the same<br>idea!”</p>\n<p>And he flung away the hammer in a rage. Then he sank down so<br>deeply on the arm-chair and the table, that Jehan lost him from<br>view behind the great pile of manuscripts. For the space of<br>several minutes, all that he saw was his fist convulsively<br>clenched on a book. Suddenly, Dom Claude sprang up, seized a<br>compass and engraved in silence upon the wall in capital letters,<br>this Greek word</p>\n<p>ἈΝÁΓΚΗ.</p>\n<p>“My brother is mad,” said Jehan to himself; “it would have been<br>far more simple to write <em>Fatum</em>, every one is not obliged to<br>know Greek.”</p>\n<p>The archdeacon returned and seated himself in his armchair, and<br>placed his head on both his hands, as a sick man does, whose head<br>is heavy and burning.</p>\n<p>The student watched his brother with surprise. He did not know,<br>he who wore his heart on his sleeve, he who observed only the<br>good old law of Nature in the world, he who allowed his passions<br>to follow their inclinations, and in whom the lake of great<br>emotions was always dry, so freely did he let it off each day by<br>fresh drains,—he did not know with what fury the sea of human<br>passions ferments and boils when all egress is denied to it, how<br>it accumulates, how it swells, how it overflows, how it hollows<br>out the heart; how it breaks in inward sobs, and dull<br>convulsions, until it has rent its dikes and burst its bed. The<br>austere and glacial envelope of Claude Frollo, that cold surface<br>of steep and inaccessible virtue, had always deceived Jehan. The<br>merry scholar had never dreamed that there was boiling lava,<br>furious and profound, beneath the snowy brow of Ætna.</p>\n<p>We do not know whether he suddenly became conscious of these<br>things; but, giddy as he was, he understood that he had seen what<br>he ought not to have seen, that he had just surprised the soul of<br>his elder brother in one of its most secret altitudes, and that<br>Claude must not be allowed to know it. Seeing that the archdeacon<br>had fallen back into his former immobility, he withdrew his head<br>very softly, and made some noise with his feet outside the door,<br>like a person who has just arrived and is giving warning of his<br>approach.</p>\n<p>“Enter!” cried the archdeacon, from the interior of his cell; “I<br>was expecting you. I left the door unlocked expressly; enter<br>Master Jacques!”</p>\n<p>The scholar entered boldly. The archdeacon, who was very much<br>embarrassed by such a visit in such a place, trembled in his<br>arm-chair. “What! ’tis you, Jehan?”</p>\n<p>“’Tis a J, all the same,” said the scholar, with his ruddy,<br>merry, and audacious face.</p>\n<p>Dom Claude’s visage had resumed its severe expression.</p>\n<p>“What are you come for?”</p>\n<p>“Brother,” replied the scholar, making an effort to assume a<br>decent, pitiful, and modest mien, and twirling his cap in his<br>hands with an innocent air; “I am come to ask of you—”</p>\n<p>“What?”</p>\n<p>“A little lecture on morality, of which I stand greatly in need,”<br>Jehan did not dare to add aloud,—“and a little money of which I<br>am in still greater need.” This last member of his phrase<br>remained unuttered.</p>\n<p>“Monsieur,” said the archdeacon, in a cold tone, “I am greatly<br>displeased with you.”</p>\n<p>“Alas!” sighed the scholar.</p>\n<p>Dom Claude made his arm-chair describe a quarter circle, and<br>gazed intently at Jehan.</p>\n<p>“I am very glad to see you.”</p>\n<p>This was a formidable exordium. Jehan braced himself for a rough<br>encounter.</p>\n<p>“Jehan, complaints are brought me about you every day. What<br>affray was that in which you bruised with a cudgel a little<br>vicomte, Albert de Ramonchamp?”</p>\n<p>“Oh!” said Jehan, “a vast thing that! A malicious page amused<br>himself by splashing the scholars, by making his horse gallop<br>through the mire!”</p>\n<p>“Who,” pursued the archdeacon, “is that Mahiet Fargel, whose gown<br>you have torn? <em>Tunicam dechiraverunt</em>, saith the complaint.”</p>\n<p>“Ah bah! a wretched cap of a Montaigu! Isn’t that it?”</p>\n<p>“The complaint says <em>tunicam</em> and not <em>cappettam</em>. Do you know<br>Latin?”</p>\n<p>Jehan did not reply.</p>\n<p>“Yes,” pursued the priest shaking his head, “that is the state of<br>learning and letters at the present day. The Latin tongue is<br>hardly understood, Syriac is unknown, Greek so odious that ’tis<br>accounted no ignorance in the most learned to skip a Greek word<br>without reading it, and to say, ‘<em>Græcum est non legitur</em>.’”</p>\n<p>The scholar raised his eyes boldly. “Monsieur my brother, doth it<br>please you that I shall explain in good French vernacular that<br>Greek word which is written yonder on the wall?”</p>\n<p>“What word?”</p>\n<p>“ἈΝÁΓΚΗ.”</p>\n<p>A slight flush spread over the cheeks of the priest with their<br>high bones, like the puff of smoke which announces on the outside<br>the secret commotions of a volcano. The student hardly noticed<br>it.</p>\n<p>“Well, Jehan,” stammered the elder brother with an effort, “What<br>is the meaning of yonder word?”</p>\n<p>“FATE.”</p>\n<p>Dom Claude turned pale again, and the scholar pursued carelessly.</p>\n<p>“And that word below it, graved by the same hand, <em>Ἀνάγνεία</em>,<br>signifies ‘impurity.’ You see that people do know their Greek.”</p>\n<p>And the archdeacon remained silent. This Greek lesson had<br>rendered him thoughtful.</p>\n<p>Master Jehan, who possessed all the artful ways of a spoiled<br>child, judged that the moment was a favorable one in which to<br>risk his request. Accordingly, he assumed an extremely soft tone<br>and began,—</p>\n<p>“My good brother, do you hate me to such a degree as to look<br>savagely upon me because of a few mischievous cuffs and blows<br>distributed in a fair war to a pack of lads and brats, _quibusdam<br>marmosetis_? You see, good Brother Claude, that people know their<br>Latin.”</p>\n<p>But all this caressing hypocrisy did not have its usual effect on<br>the severe elder brother. Cerberus did not bite at the honey<br>cake. The archdeacon’s brow did not lose a single wrinkle.</p>\n<p>“What are you driving at?” he said dryly.</p>\n<p>“Well, in point of fact, this!” replied Jehan bravely, “I stand<br>in need of money.”</p>\n<p>At this audacious declaration, the archdeacon’s visage assumed a<br>thoroughly pedagogical and paternal expression.</p>\n<p>“You know, Monsieur Jehan, that our fief of Tirechappe, putting<br>the direct taxes and the rents of the nine and twenty houses in a<br>block, yields only nine and thirty livres, eleven sous, six<br>deniers, Parisian. It is one half more than in the time of the<br>brothers Paclet, but it is not much.”</p>\n<p>“I need money,” said Jehan stoically.</p>\n<p>“You know that the official has decided that our twenty-one<br>houses should be moved full into the fief of the Bishopric, and<br>that we could redeem this homage only by paying the reverend<br>bishop two marks of silver gilt of the price of six livres<br>parisis. Now, these two marks I have not yet been able to get<br>together. You know it.”</p>\n<p>“I know that I stand in need of money,” repeated Jehan for the<br>third time.</p>\n<p>“And what are you going to do with it?”</p>\n<p>This question caused a flash of hope to gleam before Jehan’s<br>eyes. He resumed his dainty, caressing air.</p>\n<p>“Stay, dear Brother Claude, I should not come to you, with any<br>evil motive. There is no intention of cutting a dash in the<br>taverns with your unzains, and of strutting about the streets of<br>Paris in a caparison of gold brocade, with a lackey, _cum meo<br>laquasio_. No, brother, ’tis for a good work.”</p>\n<p>“What good work?” demanded Claude, somewhat surprised.</p>\n<p>“Two of my friends wish to purchase an outfit for the infant of a<br>poor Haudriette widow. It is a charity. It will cost three<br>florins, and I should like to contribute to it.”</p>\n<p>“What are names of your two friends?”</p>\n<p>“Pierre l’Assommeur and Baptiste Croque-Oison.”[37]</p>\n<p>“Hum,” said the archdeacon; “those are names as fit for a good<br>work as a catapult for the chief altar.”</p>\n<p>It is certain that Jehan had made a very bad choice of names for<br>his two friends. He realized it too late.</p>\n<p>“And then,” pursued the sagacious Claude, “what sort of an<br>infant’s outfit is it that is to cost three florins, and that for<br>the child of a Haudriette? Since when have the Haudriette widows<br>taken to having babes in swaddling-clothes?”</p>\n<p>Jehan broke the ice once more.</p>\n<p>“Eh, well! yes! I need money in order to go and see Isabeau la<br>Thierrye to-night; in the Val-d’ Amour!”</p>\n<p>“Impure wretch!” exclaimed the priest.</p>\n<p>“Ἀναγνεία!” said Jehan.</p>\n<p>This quotation, which the scholar borrowed with malice,<br>perchance, from the wall of the cell, produced a singular effect<br>on the archdeacon. He bit his lips and his wrath was drowned in a<br>crimson flush.</p>\n<p>“Begone,” he said to Jehan. “I am expecting some one.”</p>\n<p>The scholar made one more effort.</p>\n<p>“Brother Claude, give me at least one little parisis to buy<br>something to eat.”</p>\n<p>“How far have you gone in the Decretals of Gratian?” demanded Dom<br>Claude.</p>\n<p>“I have lost my copy books.</p>\n<p>“Where are you in your Latin humanities?”</p>\n<p>“My copy of Horace has been stolen.”</p>\n<p>“Where are you in Aristotle?”</p>\n<p>“I’ faith! brother what father of the church is it, who says that<br>the errors of heretics have always had for their lurking place<br>the thickets of Aristotle’s metaphysics? A plague on Aristotle! I<br>care not to tear my religion on his metaphysics.”</p>\n<p>“Young man,” resumed the archdeacon, “at the king’s last entry,<br>there was a young gentleman, named Philippe de Comines, who wore<br>embroidered on the housings of his horse this device, upon which<br>I counsel you to meditate: <em>Qui non laborat, non manducet</em>.”</p>\n<p>The scholar remained silent for a moment, with his finger in his<br>ear, his eyes on the ground, and a discomfited mien.</p>\n<p>All at once he turned round to Claude with the agile quickness of<br>a wagtail.</p>\n<p>“So, my good brother, you refuse me a sou parisis, wherewith to<br>buy a crust at a baker’s shop?”</p>\n<p>“<em>Qui non laborat, non manducet</em>.”</p>\n<p>At this response of the inflexible archdeacon, Jehan hid his head<br>in his hands, like a woman sobbing, and exclaimed with an<br>expression of despair: “Ὀτοτοτοτοτοῖ.”</p>\n<p>“What is the meaning of this, sir?” demanded Claude, surprised at<br>this freak.</p>\n<p>“What indeed!” said the scholar; and he lifted to Claude his<br>impudent eyes into which he had just thrust his fists in order to<br>communicate to them the redness of tears; “’tis Greek! ’tis an<br>anapæst of Æschylus which expresses grief perfectly.”</p>\n<p>And here he burst into a laugh so droll and violent that it made<br>the archdeacon smile. It was Claude’s fault, in fact: why had he<br>so spoiled that child?</p>\n<p>“Oh! good Brother Claude,” resumed Jehan, emboldened by this<br>smile, “look at my worn out boots. Is there a cothurnus in the<br>world more tragic than these boots, whose soles are hanging out<br>their tongues?”</p>\n<p>The archdeacon promptly returned to his original severity.</p>\n<p>“I will send you some new boots, but no money.”</p>\n<p>“Only a poor little parisis, brother,” continued the suppliant<br>Jehan. “I will learn Gratian by heart, I will believe firmly in<br>God, I will be a regular Pythagoras of science and virtue. But<br>one little parisis, in mercy! Would you have famine bite me with<br>its jaws which are gaping in front of me, blacker, deeper, and<br>more noisome than a Tartarus or the nose of a monk?”</p>\n<p>Dom Claude shook his wrinkled head: “<em>Qui non laborat</em>—”</p>\n<p>Jehan did not allow him to finish.</p>\n<p>“Well,” he exclaimed, “to the devil then! Long live joy! I will<br>live in the tavern, I will fight, I will break pots and I will go<br>and see the wenches.” And thereupon, he hurled his cap at the<br>wall, and snapped his fingers like castanets.</p>\n<p>The archdeacon surveyed him with a gloomy air.</p>\n<p>“Jehan, you have no soul.”</p>\n<p>“In that case, according to Epicurius, I lack a something made of<br>another something which has no name.”</p>\n<p>“Jehan, you must think seriously of amending your ways.”</p>\n<p>“Oh, come now,” cried the student, gazing in turn at his brother<br>and the alembics on the furnace, “everything is preposterous<br>here, both ideas and bottles!”</p>\n<p>“Jehan, you are on a very slippery downward road. Do you know<br>whither you are going?”</p>\n<p>“To the wine-shop,” said Jehan.</p>\n<p>“The wine-shop leads to the pillory.”</p>\n<p>“’Tis as good a lantern as any other, and perchance with that<br>one, Diogenes would have found his man.”</p>\n<p>“The pillory leads to the gallows.”</p>\n<p>“The gallows is a balance which has a man at one end and the<br>whole earth at the other. ’Tis fine to be the man.”</p>\n<p>“The gallows leads to hell.”</p>\n<p>“’Tis a big fire.”</p>\n<p>“Jehan, Jehan, the end will be bad.”</p>\n<p>“The beginning will have been good.”</p>\n<p>At that moment, the sound of a footstep was heard on the<br>staircase.</p>\n<p>“Silence!” said the archdeacon, laying his finger on his mouth,<br>“here is Master Jacques. Listen, Jehan,” he added, in a low<br>voice; “have a care never to speak of what you shall have seen or<br>heard here. Hide yourself quickly under the furnace, and do not<br>breathe.”</p>\n<p>The scholar concealed himself; just then a happy idea occurred to<br>him.</p>\n<p>“By the way, Brother Claude, a form for not breathing.”</p>\n<p>“Silence! I promise.”</p>\n<p>“You must give it to me.”</p>\n<p>“Take it, then!” said the archdeacon angrily, flinging his purse<br>at him.</p>\n<p>Jehan darted under the furnace again, and the door opened.</p>\n<h1 class=\"chapter\" id=\"chapter-v-the-two-men-clothed-in-black\">Chapter V. THE TWO MEN CLOTHED IN BLACK.</h1>\n<p>The personage who entered wore a black gown and a gloomy mien.<br>The first point which struck the eye of our Jehan (who, as the<br>reader will readily surmise, had ensconced himself in his nook in<br>such a manner as to enable him to see and hear everything at his<br>good pleasure) was the perfect sadness of the garments and the<br>visage of this new-corner. There was, nevertheless, some<br>sweetness diffused over that face, but it was the sweetness of a<br>cat or a judge, an affected, treacherous sweetness. He was very<br>gray and wrinkled, and not far from his sixtieth year, his eyes<br>blinked, his eyebrows were white, his lip pendulous, and his<br>hands large. When Jehan saw that it was only this, that is to<br>say, no doubt a physician or a magistrate, and that this man had<br>a nose very far from his mouth, a sign of stupidity, he nestled<br>down in his hole, in despair at being obliged to pass an<br>indefinite time in such an uncomfortable attitude, and in such<br>bad company.</p>\n<p>The archdeacon, in the meantime, had not even risen to receive<br>this personage. He had made the latter a sign to seat himself on<br>a stool near the door, and, after several moments of a silence<br>which appeared to be a continuation of a preceding meditation, he<br>said to him in a rather patronizing way, “Good day, Master<br>Jacques.”</p>\n<p>“Greeting, master,” replied the man in black.</p>\n<p>There was in the two ways in which “Master Jacques” was<br>pronounced on the one hand, and the “master” by preeminence on<br>the other, the difference between monseigneur and monsieur,<br>between <em>domine</em> and <em>domne</em>. It was evidently the meeting of a<br>teacher and a disciple.</p>\n<p>“Well!” resumed the archdeacon, after a fresh silence which<br>Master Jacques took good care not to disturb, “how are you<br>succeeding?”</p>\n<p>“Alas! master,” said the other, with a sad smile, “I am still<br>seeking the stone. Plenty of ashes. But not a spark of gold.”</p>\n<p>Dom Claude made a gesture of impatience. “I am not talking to you<br>of that, Master Jacques Charmolue, but of the trial of your<br>magician. Is it not Marc Cenaine that you call him? the butler of<br>the Court of Accounts? Does he confess his witchcraft? Have you<br>been successful with the torture?”</p>\n<p>“Alas! no,” replied Master Jacques, still with his sad smile; “we<br>have not that consolation. That man is a stone. We might have him<br>boiled in the Marché aux Pourceaux, before he would say anything.<br>Nevertheless, we are sparing nothing for the sake of getting at<br>the truth; he is already thoroughly dislocated, we are applying<br>all the herbs of Saint John’s day; as saith the old comedian<br>Plautus,—</p>\n<p>‘Advorsum stimulos, laminas, crucesque, compedesque,<br>Nervos, catenas, carceres, numellas, pedicas, boias.’</p>\n<p>Nothing answers; that man is terrible. I am at my wit’s end over<br>him.”</p>\n<p>“You have found nothing new in his house?”</p>\n<p>“I’ faith, yes,” said Master Jacques, fumbling in his pouch;<br>“this parchment. There are words in it which we cannot<br>comprehend. The criminal advocate, Monsieur Philippe Lheulier,<br>nevertheless, knows a little Hebrew, which he learned in that<br>matter of the Jews of the Rue Kantersten, at Brussels.”</p>\n<p>So saying, Master Jacques unrolled a parchment. “Give it here,”<br>said the archdeacon. And casting his eyes upon this writing:<br>“Pure magic, Master Jacques!” he exclaimed. “‘Emen-Hétan!’ ’Tis<br>the cry of the vampires when they arrive at the witches’ sabbath.<br><em>Per ipsum, et cum ipso, et in ipso!</em> ’Tis the command which<br>chains the devil in hell. <em>Hax, pax, max!</em> that refers to<br>medicine. A formula against the bite of mad dogs. Master Jacques!<br>you are procurator to the king in the Ecclesiastical Courts: this<br>parchment is abominable.”</p>\n<p>“We will put the man to the torture once more. Here again,” added<br>Master Jacques, fumbling afresh in his pouch, “is something that<br>we have found at Marc Cenaine’s house.”</p>\n<p>It was a vessel belonging to the same family as those which<br>covered Dom Claude’s furnace.</p>\n<p>“Ah!” said the archdeacon, “a crucible for alchemy.”</p>\n<p>“I will confess to you,” continued Master Jacques, with his timid<br>and awkward smile, “that I have tried it over the furnace, but I<br>have succeeded no better than with my own.”</p>\n<p>The archdeacon began an examination of the vessel. “What has he<br>engraved on his crucible? <em>Och! och!</em> the word which expels<br>fleas! That Marc Cenaine is an ignoramus! I verily believe that<br>you will never make gold with this! ’Tis good to set in your<br>bedroom in summer and that is all!”</p>\n<p>“Since we are talking about errors,” said the king’s procurator,<br>“I have just been studying the figures on the portal below before<br>ascending hither; is your reverence quite sure that the opening<br>of the work of physics is there portrayed on the side towards the<br>Hôtel-Dieu, and that among the seven nude figures which stand at<br>the feet of Notre-Dame, that which has wings on his heels is<br>Mercurius?”</p>\n<p>“Yes,” replied the priest; “’tis Augustin Nypho who writes it,<br>that Italian doctor who had a bearded demon who acquainted him<br>with all things. However, we will descend, and I will explain it<br>to you with the text before us.”</p>\n<p>“Thanks, master,” said Charmolue, bowing to the earth. “By the<br>way, I was on the point of forgetting. When doth it please you<br>that I shall apprehend the little sorceress?”</p>\n<p>“What sorceress?”</p>\n<p>“That gypsy girl you know, who comes every day to dance on the<br>church square, in spite of the official’s prohibition! She hath a<br>demoniac goat with horns of the devil, which reads, which writes,<br>which knows mathematics like Picatrix, and which would suffice to<br>hang all Bohemia. The prosecution is all ready; ’twill soon be<br>finished, I assure you! A pretty creature, on my soul, that<br>dancer! The handsomest black eyes! Two Egyptian carbuncles! When<br>shall we begin?”</p>\n<p>The archdeacon was excessively pale.</p>\n<p>“I will tell you that hereafter,” he stammered, in a voice that<br>was barely articulate; then he resumed with an effort, “Busy<br>yourself with Marc Cenaine.”</p>\n<p>“Be at ease,” said Charmolue with a smile; “I’ll buckle him down<br>again for you on the leather bed when I get home. But ’tis a<br>devil of a man; he wearies even Pierrat Torterue himself, who<br>hath hands larger than my own. As that good Plautus saith,—</p>\n<p>‘Nudus vinctus, centum pondo, es quando pendes per pedes.’</p>\n<p>The torture of the wheel and axle! ’Tis the most effectual! He<br>shall taste it!”</p>\n<p>Dom Claude seemed absorbed in gloomy abstraction. He turned to<br>Charmolue,—</p>\n<p>“Master Pierrat—Master Jacques, I mean, busy yourself with Marc<br>Cenaine.”</p>\n<p>“Yes, yes, Dom Claude. Poor man! he will have suffered like<br>Mummol. What an idea to go to the witches’ sabbath! a butler of<br>the Court of Accounts, who ought to know Charlemagne’s text;<br><em>Stryga vel masca!</em>—In the matter of the little girl,—Smelarda,<br>as they call her,—I will await your orders. Ah! as we pass<br>through the portal, you will explain to me also the meaning of<br>the gardener painted in relief, which one sees as one enters the<br>church. Is it not the Sower? Hé! master, of what are you<br>thinking, pray?”</p>\n<p>Dom Claude, buried in his own thoughts, no longer listened to<br>him. Charmolue, following the direction of his glance, perceived<br>that it was fixed mechanically on the great spider’s web which<br>draped the window. At that moment, a bewildered fly which was<br>seeking the March sun, flung itself through the net and became<br>entangled there. On the agitation of his web, the enormous spider<br>made an abrupt move from his central cell, then with one bound,<br>rushed upon the fly, which he folded together with his fore<br>antennæ, while his hideous proboscis dug into the victim’s head.<br>“Poor fly!” said the king’s procurator in the ecclesiastical<br>court; and he raised his hand to save it. The archdeacon, as<br>though roused with a start, withheld his arm with convulsive<br>violence.</p>\n<p>“Master Jacques,” he cried, “let fate take its course!” The<br>procurator wheeled round in affright; it seemed to him that<br>pincers of iron had clutched his arm. The priest’s eye was<br>staring, wild, flaming, and remained riveted on the horrible<br>little group of the spider and the fly.</p>\n<p>“Oh, yes!” continued the priest, in a voice which seemed to<br>proceed from the depths of his being, “behold here a symbol of<br>all. She flies, she is joyous, she is just born; she seeks the<br>spring, the open air, liberty: oh, yes! but let her come in<br>contact with the fatal network, and the spider issues from it,<br>the hideous spider! Poor dancer! poor, predestined fly! Let<br>things take their course, Master Jacques, ’tis fate! Alas!<br>Claude, thou art the spider! Claude, thou art the fly also! Thou<br>wert flying towards learning, light, the sun. Thou hadst no other<br>care than to reach the open air, the full daylight of eternal<br>truth; but in precipitating thyself towards the dazzling window<br>which opens upon the other world,—upon the world of brightness,<br>intelligence, and science—blind fly! senseless, learned man! thou<br>hast not perceived that subtle spider’s web, stretched by destiny<br>betwixt the light and thee—thou hast flung thyself headlong into<br>it, and now thou art struggling with head broken and mangled<br>wings between the iron antennæ of fate! Master Jacques! Master<br>Jacques! let the spider work its will!”</p>\n<p>“I assure you,” said Charmolue, who was gazing at him without<br>comprehending him, “that I will not touch it. But release my arm,<br>master, for pity’s sake! You have a hand like a pair of pincers.”</p>\n<p>The archdeacon did not hear him. “Oh, madman!” he went on,<br>without removing his gaze from the window. “And even couldst thou<br>have broken through that formidable web, with thy gnat’s wings,<br>thou believest that thou couldst have reached the light? Alas!<br>that pane of glass which is further on, that transparent<br>obstacle, that wall of crystal, harder than brass, which<br>separates all philosophies from the truth, how wouldst thou have<br>overcome it? Oh, vanity of science! how many wise men come flying<br>from afar, to dash their heads against thee! How many systems<br>vainly fling themselves buzzing against that eternal pane!”</p>\n<p>He became silent. These last ideas, which had gradually led him<br>back from himself to science, appeared to have calmed him.<br>Jacques Charmolue recalled him wholly to a sense of reality by<br>addressing to him this question: “Come, now, master, when will<br>you come to aid me in making gold? I am impatient to succeed.”</p>\n<p>The archdeacon shook his head, with a bitter smile. “Master<br>Jacques read Michel Psellus’ ‘_Dialogus de Energia et Operatione<br>Dæmonum_.’ What we are doing is not wholly innocent.”</p>\n<p>“Speak lower, master! I have my suspicions of it,” said Jacques<br>Charmolue. “But one must practise a bit of hermetic science when<br>one is only procurator of the king in the ecclesiastical court,<br>at thirty crowns tournois a year. Only speak low.”</p>\n<p>At that moment the sound of jaws in the act of mastication, which<br>proceeded from beneath the furnace, struck Charmolue’s uneasy<br>ear.</p>\n<p>“What’s that?” he inquired.</p>\n<p>It was the scholar, who, ill at ease, and greatly bored in his<br>hiding-place, had succeeded in discovering there a stale crust<br>and a triangle of mouldy cheese, and had set to devouring the<br>whole without ceremony, by way of consolation and breakfast. As<br>he was very hungry, he made a great deal of noise, and he<br>accented each mouthful strongly, which startled and alarmed the<br>procurator.</p>\n<p>“’Tis a cat of mine,” said the archdeacon, quickly, “who is<br>regaling herself under there with a mouse.”</p>\n<p>This explanation satisfied Charmolue.</p>\n<p>“In fact, master,” he replied, with a respectful smile, “all<br>great philosophers have their familiar animal. You know what<br>Servius saith: ‘<em>Nullus enim locus sine genio est</em>,—for there is<br>no place that hath not its spirit.’”</p>\n<p>But Dom Claude, who stood in terror of some new freak on the part<br>of Jehan, reminded his worthy disciple that they had some figures<br>on the façade to study together, and the two quitted the cell, to<br>the accompaniment of a great “ouf!” from the scholar, who began<br>to seriously fear that his knee would acquire the imprint of his<br>chin.</p>\n<h1 class=\"chapter\" id=\"chapter-vi-the-effect-which-seven-oaths-in-the-o\">Chapter VI. THE EFFECT WHICH SEVEN OATHS IN THE OPEN AIR CAN</h1>\n<p>PRODUCE.</p>\n<p>“<em>Te Deum laudamus</em>!” exclaimed Master Jehan, creeping out from<br>his hole, “the screech-owls have departed. Och! och! Hax! pax!<br>max! fleas! mad dogs! the devil! I have had enough of their<br>conversation! My head is humming like a bell tower. And mouldy<br>cheese to boot! Come on! Let us descend, take the big brother’s<br>purse and convert all these coins into bottles!”</p>\n<p>He cast a glance of tenderness and admiration into the interior<br>of the precious pouch, readjusted his toilet, rubbed up his<br>boots, dusted his poor half sleeves, all gray with ashes,<br>whistled an air, indulged in a sportive pirouette, looked about<br>to see whether there were not something more in the cell to take,<br>gathered up here and there on the furnace some amulet in glass<br>which might serve to bestow, in the guise of a trinket, on<br>Isabeau la Thierrye, finally pushed open the door which his<br>brother had left unfastened, as a last indulgence, and which he,<br>in his turn, left open as a last piece of malice, and descended<br>the circular staircase, skipping like a bird.</p>\n<p>In the midst of the gloom of the spiral staircase, he elbowed<br>something which drew aside with a growl; he took it for granted<br>that it was Quasimodo, and it struck him as so droll that he<br>descended the remainder of the staircase holding his sides with<br>laughter. On emerging upon the Place, he laughed yet more<br>heartily.</p>\n<p>He stamped his foot when he found himself on the ground once<br>again. “Oh!” said he, “good and honorable pavement of Paris,<br>cursed staircase, fit to put the angels of Jacob’s ladder out of<br>breath! What was I thinking of to thrust myself into that stone<br>gimlet which pierces the sky; all for the sake of eating bearded<br>cheese, and looking at the bell-towers of Paris through a hole in<br>the wall!”</p>\n<p>He advanced a few paces, and caught sight of the two screech<br>owls, that is to say, Dom Claude and Master Jacques Charmolue,<br>absorbed in contemplation before a carving on the façade. He<br>approached them on tiptoe, and heard the archdeacon say in a low<br>tone to Charmolue: “’Twas Guillaume de Paris who caused a Job to<br>be carved upon this stone of the hue of lapis-lazuli, gilded on<br>the edges. Job represents the philosopher’s stone, which must<br>also be tried and martyrized in order to become perfect, as saith<br>Raymond Lulle: <em>Sub conservatione formæ specificæ salva anima</em>.”</p>\n<p>“That makes no difference to me,” said Jehan, “’tis I who have<br>the purse.”</p>\n<p>At that moment he heard a powerful and sonorous voice articulate<br>behind him a formidable series of oaths. “_Sang Dieu!<br>Ventre-Dieu! Bédieu! Corps de Dieu! Nombril de Belzébuth! Nom<br>d’un pape! Corne et tonnerre_.”</p>\n<p>“Upon my soul!” exclaimed Jehan, “that can only be my friend,<br>Captain Phœbus!”</p>\n<p>This name of Phœbus reached the ears of the archdeacon at the<br>moment when he was explaining to the king’s procurator the dragon<br>which is hiding its tail in a bath, from which issue smoke and<br>the head of a king. Dom Claude started, interrupted himself and,<br>to the great amazement of Charmolue, turned round and beheld his<br>brother Jehan accosting a tall officer at the door of the<br>Gondelaurier mansion.</p>\n<p>It was, in fact, Captain Phœbus de Châteaupers. He was backed up<br>against a corner of the house of his betrothed and swearing like<br>a heathen.</p>\n<p>“By my faith! Captain Phœbus,” said Jehan, taking him by the<br>hand, “you are cursing with admirable vigor.”</p>\n<p>“Horns and thunder!” replied the captain.</p>\n<p>“Horns and thunder yourself!” replied the student. “Come now,<br>fair captain, whence comes this overflow of fine words?”</p>\n<p>“Pardon me, good comrade Jehan,” exclaimed Phœbus, shaking his<br>hand, “a horse going at a gallop cannot halt short. Now, I was<br>swearing at a hard gallop. I have just been with those prudes,<br>and when I come forth, I always find my throat full of curses, I<br>must spit them out or strangle, <em>ventre et tonnerre!</em>”</p>\n<p>“Will you come and drink?” asked the scholar.</p>\n<p>This proposition calmed the captain.</p>\n<p>“I’m willing, but I have no money.”</p>\n<p>“But I have!”</p>\n<p>“Bah! let’s see it!”</p>\n<p>Jehan spread out the purse before the captain’s eyes, with<br>dignity and simplicity. Meanwhile, the archdeacon, who had<br>abandoned the dumbfounded Charmolue where he stood, had<br>approached them and halted a few paces distant, watching them<br>without their noticing him, so deeply were they absorbed in<br>contemplation of the purse.</p>\n<p>Phœbus exclaimed: “A purse in your pocket, Jehan! ’tis the moon<br>in a bucket of water, one sees it there but ’tis not there. There<br>is nothing but its shadow. Pardieu! let us wager that these are<br>pebbles!”</p>\n<p>Jehan replied coldly: “Here are the pebbles wherewith I pave my<br>fob!”</p>\n<p>And without adding another word, he emptied the purse on a<br>neighboring post, with the air of a Roman saving his country.</p>\n<p>“True God!” muttered Phœbus, “targes, big-blanks, little blanks,<br>mailles,[38] every two worth one of Tournay, farthings of Paris,<br>real eagle liards! ’Tis dazzling!”</p>\n<p>Jehan remained dignified and immovable. Several liards had rolled<br>into the mud; the captain in his enthusiasm stooped to pick them<br>up. Jehan restrained him.</p>\n<p>“Fye, Captain Phœbus de Châteaupers!”</p>\n<p>Phœbus counted the coins, and turning towards Jehan with<br>solemnity, “Do you know, Jehan, that there are three and twenty<br>sous parisis! whom have you plundered to-night, in the Street<br>Cut-Weazand?”</p>\n<p>Jehan flung back his blonde and curly head, and said,<br>half-closing his eyes disdainfully,—</p>\n<p>“We have a brother who is an archdeacon and a fool.”</p>\n<p>“<em>Corne de Dieu!</em>” exclaimed Phœbus, “the worthy man!”</p>\n<p>“Let us go and drink,” said Jehan.</p>\n<p>“Where shall we go?” said Phœbus; “‘To Eve’s Apple.’”</p>\n<p>“No, captain, to ‘Ancient Science.’ An old woman sawing a basket<br>handle;[39] ’tis a rebus, and I like that.”</p>\n<p>“A plague on rebuses, Jehan! the wine is better at ‘Eve’s Apple’;<br>and then, beside the door there is a vine in the sun which cheers<br>me while I am drinking.”</p>\n<p>“Well! here goes for Eve and her apple,” said the student, and<br>taking Phœbus’s arm. “By the way, my dear captain, you just<br>mentioned the Rue Coupe-Gueule[40] That is a very bad form of<br>speech; people are no longer so barbarous. They say,<br>Coupe-Gorge[41].”</p>\n<p>The two friends set out towards “Eve’s Apple.” It is unnecessary<br>to mention that they had first gathered up the money, and that<br>the archdeacon followed them.</p>\n<p>The archdeacon followed them, gloomy and haggard. Was this the<br>Phœbus whose accursed name had been mingled with all his thoughts<br>ever since his interview with Gringoire? He did not know it, but<br>it was at least a Phœbus, and that magic name sufficed to make<br>the archdeacon follow the two heedless comrades with the stealthy<br>tread of a wolf, listening to their words and observing their<br>slightest gestures with anxious attention. Moreover, nothing was<br>easier than to hear everything they said, as they talked loudly,<br>not in the least concerned that the passers-by were taken into<br>their confidence. They talked of duels, wenches, wine pots, and<br>folly.</p>\n<p>At the turning of a street, the sound of a tambourine reached<br>them from a neighboring square. Dom Claude heard the officer say<br>to the scholar,—</p>\n<p>“Thunder! Let us hasten our steps!”</p>\n<p>“Why, Phœbus?”</p>\n<p>“I’m afraid lest the Bohemian should see me.”</p>\n<p>“What Bohemian?”</p>\n<p>“The little girl with the goat.”</p>\n<p>“La Smeralda?”</p>\n<p>“That’s it, Jehan. I always forget her devil of a name. Let us<br>make haste, she will recognize me. I don’t want to have that girl<br>accost me in the street.”</p>\n<p>“Do you know her, Phœbus?”</p>\n<p>Here the archdeacon saw Phœbus sneer, bend down to Jehan’s ear,<br>and say a few words to him in a low voice; then Phœbus burst into<br>a laugh, and shook his head with a triumphant air.</p>\n<p>“Truly?” said Jehan.</p>\n<p>“Upon my soul!” said Phœbus.</p>\n<p>“This evening?”</p>\n<p>“This evening.”</p>\n<p>“Are you sure that she will come?”</p>\n<p>“Are you a fool, Jehan? Does one doubt such things?”</p>\n<p>“Captain Phœbus, you are a happy gendarme!”</p>\n<p>The archdeacon heard the whole of this conversation. His teeth<br>chattered; a visible shiver ran through his whole body. He halted<br>for a moment, leaned against a post like a drunken man, then<br>followed the two merry knaves.</p>\n<p>At the moment when he overtook them once more, they had changed<br>their conversation. He heard them singing at the top of their<br>lungs the ancient refrain,—</p>\n<p>Les enfants des Petits-Carreaux<br>Se font pendre comme des veaux[42].</p>\n<h1 class=\"chapter\" id=\"chapter-vii-the-mysterious-monk\">Chapter VII. THE MYSTERIOUS MONK.</h1>\n<p>The illustrious wine shop of “Eve’s Apple” was situated in the<br>University, at the corner of the Rue de la Rondelle and the Rue<br>de la Bâtonnier. It was a very spacious and very low hall on the<br>ground floor, with a vaulted ceiling whose central spring rested<br>upon a huge pillar of wood painted yellow; tables everywhere,<br>shining pewter jugs hanging on the walls, always a large number<br>of drinkers, a plenty of wenches, a window on the street, a vine<br>at the door, and over the door a flaring piece of sheet-iron,<br>painted with an apple and a woman, rusted by the rain and turning<br>with the wind on an iron pin. This species of weather-vane which<br>looked upon the pavement was the signboard.</p>\n<p>Night was falling; the square was dark; the wine-shop, full of<br>candles, flamed afar like a forge in the gloom; the noise of<br>glasses and feasting, of oaths and quarrels, which escaped<br>through the broken panes, was audible. Through the mist which the<br>warmth of the room spread over the window in front, a hundred<br>confused figures could be seen swarming, and from time to time a<br>burst of noisy laughter broke forth from it. The passers-by who<br>were going about their business, slipped past this tumultuous<br>window without glancing at it. Only at intervals did some little<br>ragged boy raise himself on tiptoe as far as the ledge, and hurl<br>into the drinking-shop, that ancient, jeering hoot, with which<br>drunken men were then pursued: “Aux Houls, saouls, saouls,<br>saouls!”</p>\n<p>Nevertheless, one man paced imperturbably back and forth in front<br>of the tavern, gazing at it incessantly, and going no further<br>from it than a pikeman from his sentry-box. He was enveloped in a<br>mantle to his very nose. This mantle he had just purchased of the<br>old-clothes man, in the vicinity of the “Eve’s Apple,” no doubt<br>to protect himself from the cold of the March evening, possibly<br>also, to conceal his costume. From time to time he paused in<br>front of the dim window with its leaden lattice, listened,<br>looked, and stamped his foot.</p>\n<p>At length the door of the dram-shop opened. This was what he<br>appeared to be waiting for. Two boon companions came forth. The<br>ray of light which escaped from the door crimsoned for a moment<br>their jovial faces.</p>\n<p>The man in the mantle went and stationed himself on the watch<br>under a porch on the other side of the street.</p>\n<p>“<em>Corne et tonnerre!</em>” said one of the comrades. “Seven o’clock<br>is on the point of striking. ’Tis the hour of my appointed<br>meeting.”</p>\n<p>“I tell you,” repeated his companion, with a thick tongue, “that<br>I don’t live in the Rue des Mauvaises Paroles, _indignus qui<br>inter mala verba habitat_. I have a lodging in the Rue<br>Jean-Pain-Mollet, <em>in vico Johannis Pain-Mollet</em>. You are more<br>horned than a unicorn if you assert the contrary. Every one knows<br>that he who once mounts astride a bear is never after afraid; but<br>you have a nose turned to dainties like Saint-Jacques of the<br>hospital.”</p>\n<p>“Jehan, my friend, you are drunk,” said the other.</p>\n<p>The other replied staggering, “It pleases you to say so, Phœbus;<br>but it hath been proved that Plato had the profile of a hound.”</p>\n<p>The reader has, no doubt, already recognized our two brave<br>friends, the captain and the scholar. It appears that the man who<br>was lying in wait for them had also recognized them, for he<br>slowly followed all the zigzags that the scholar caused the<br>captain to make, who being a more hardened drinker had retained<br>all his self-possession. By listening to them attentively, the<br>man in the mantle could catch in its entirety the following<br>interesting conversation,—</p>\n<p>“<em>Corbacque!</em> Do try to walk straight, master bachelor; you know<br>that I must leave you. Here it is seven o’clock. I have an<br>appointment with a woman.”</p>\n<p>“Leave me then! I see stars and lances of fire. You are like the<br>Château de Dampmartin, which is bursting with laughter.”</p>\n<p>“By the warts of my grandmother, Jehan, you are raving with too<br>much rabidness. By the way, Jehan, have you any money left?”</p>\n<p>“Monsieur Rector, there is no mistake; the little butcher’s shop,<br><em>parva boucheria</em>.”</p>\n<p>“Jehan! my friend Jehan! You know that I made an appointment with<br>that little girl at the end of the Pont Saint-Michel, and I can<br>only take her to the Falourdel’s, the old crone of the bridge,<br>and that I must pay for a chamber. The old witch with a white<br>moustache would not trust me. Jehan! for pity’s sake! Have we<br>drunk up the whole of the curé’s purse? Have you not a single<br>parisis left?”</p>\n<p>“The consciousness of having spent the other hours well is a just<br>and savory condiment for the table.”</p>\n<p>“Belly and guts! a truce to your whimsical nonsense! Tell me,<br>Jehan of the devil! have you any money left? Give it to me,<br><em>bédieu!</em> or I will search you, were you as leprous as Job, and<br>as scabby as Cæsar!”</p>\n<p>“Monsieur, the Rue Galiache is a street which hath at one end the<br>Rue de la Verrerie, and at the other the Rue de la Tixeranderie.”</p>\n<p>“Well, yes! my good friend Jehan, my poor comrade, the Rue<br>Galiache is good, very good. But in the name of heaven collect<br>your wits. I must have a sou parisis, and the appointment is for<br>seven o’clock.”</p>\n<p>“Silence for the rondo, and attention to the refrain,—</p>\n<p>“Quand les rats mangeront les cas,<br>Le roi sera seigneur d’Arras;<br>Quand la mer, qui est grande et lée<br>Sera à la Saint-Jean gelée,<br>On verra, par-dessus la glace,<br>Sortir ceux d’Arras de leur place.”[43]</p>\n<p>“Well, scholar of Antichrist, may you be strangled with the<br>entrails of your mother!” exclaimed Phœbus, and he gave the<br>drunken scholar a rough push; the latter slipped against the<br>wall, and slid flabbily to the pavement of Philip Augustus. A<br>remnant of fraternal pity, which never abandons the heart of a<br>drinker, prompted Phœbus to roll Jehan with his foot upon one of<br>those pillows of the poor, which Providence keeps in readiness at<br>the corner of all the street posts of Paris, and which the rich<br>blight with the name of “a rubbish-heap.” The captain adjusted<br>Jehan’s head upon an inclined plane of cabbage-stumps, and on the<br>very instant, the scholar fell to snoring in a magnificent bass.<br>Meanwhile, all malice was not extinguished in the captain’s<br>heart. “So much the worse if the devil’s cart picks you up on its<br>passage!” he said to the poor, sleeping clerk; and he strode off.</p>\n<p>The man in the mantle, who had not ceased to follow him, halted<br>for a moment before the prostrate scholar, as though agitated by<br>indecision; then, uttering a profound sigh, he also strode off in<br>pursuit of the captain.</p>\n<p>We, like them, will leave Jehan to slumber beneath the open sky,<br>and will follow them also, if it pleases the reader.</p>\n<p>On emerging into the Rue Saint-André-des-Arcs, Captain Phœbus<br>perceived that some one was following him. On glancing sideways<br>by chance, he perceived a sort of shadow crawling after him along<br>the walls. He halted, it halted; he resumed his march, it resumed<br>its march. This disturbed him not overmuch. “Ah, bah!” he said to<br>himself, “I have not a sou.”</p>\n<p>He paused in front of the College d’Autun. It was at this college<br>that he had sketched out what he called his studies, and, through<br>a scholar’s teasing habit which still lingered in him, he never<br>passed the façade without inflicting on the statue of Cardinal<br>Pierre Bertrand, sculptured to the right of the portal, the<br>affront of which Priapus complains so bitterly in the satire of<br>Horace, <em>Olim truncus eram ficulnus</em>. He had done this with so<br>much unrelenting animosity that the inscription, _Eduensis<br>episcopus_, had become almost effaced. Therefore, he halted<br>before the statue according to his wont. The street was utterly<br>deserted. At the moment when he was coolly retying his shoulder<br>knots, with his nose in the air, he saw the shadow approaching<br>him with slow steps, so slow that he had ample time to observe<br>that this shadow wore a cloak and a hat. On arriving near him, it<br>halted and remained more motionless than the statue of Cardinal<br>Bertrand. Meanwhile, it riveted upon Phœbus two intent eyes, full<br>of that vague light which issues in the night time from the<br>pupils of a cat.</p>\n<p>The captain was brave, and would have cared very little for a<br>highwayman, with a rapier in his hand. But this walking statue,<br>this petrified man, froze his blood. There were then in<br>circulation, strange stories of a surly monk, a nocturnal prowler<br>about the streets of Paris, and they recurred confusedly to his<br>memory. He remained for several minutes in stupefaction, and<br>finally broke the silence with a forced laugh.</p>\n<p>“Monsieur, if you are a robber, as I hope you are, you produce<br>upon me the effect of a heron attacking a nutshell. I am the son<br>of a ruined family, my dear fellow. Try your hand near by here.<br>In the chapel of this college there is some wood of the true<br>cross set in silver.”</p>\n<p>The hand of the shadow emerged from beneath its mantle and<br>descended upon the arm of Phœbus with the grip of an eagle’s<br>talon; at the same time the shadow spoke,—</p>\n<p>“Captain Phœbus de Châteaupers!”</p>\n<p>“What, the devil!” said Phœbus, “you know my name!”</p>\n<p>“I know not your name alone,” continued the man in the mantle,<br>with his sepulchral voice. “You have a <em>rendezvous</em> this<br>evening.”</p>\n<p>“Yes,” replied Phœbus in amazement.</p>\n<p>“At seven o’clock.”</p>\n<p>“In a quarter of an hour.”</p>\n<p>“At la Falourdel’s.”</p>\n<p>“Precisely.”</p>\n<p>“The lewd hag of the Pont Saint-Michel.”</p>\n<p>“Of Saint Michel the archangel, as the Pater Noster saith.”</p>\n<p>“Impious wretch!” muttered the spectre. “With a woman?”</p>\n<p>“<em>Confiteor</em>,—I confess—.”</p>\n<p>“Who is called—?”</p>\n<p>“La Smeralda,” said Phœbus, gayly. All his heedlessness had<br>gradually returned.</p>\n<p>At this name, the shadow’s grasp shook the arm of Phœbus in a<br>fury.</p>\n<p>“Captain Phœbus de Châteaupers, thou liest!”</p>\n<p>Any one who could have beheld at that moment the captain’s<br>inflamed countenance, his leap backwards, so violent that he<br>disengaged himself from the grip which held him, the proud air<br>with which he clapped his hand on his swordhilt, and, in the<br>presence of this wrath the gloomy immobility of the man in the<br>cloak,—any one who could have beheld this would have been<br>frightened. There was in it a touch of the combat of Don Juan and<br>the statue.</p>\n<p>“Christ and Satan!” exclaimed the captain. “That is a word which<br>rarely strikes the ear of a Châteaupers! Thou wilt not dare<br>repeat it.”</p>\n<p>“Thou liest!” said the shadow coldly.</p>\n<p>The captain gnashed his teeth. Surly monk, phantom,<br>superstitions,—he had forgotten all at that moment. He no longer<br>beheld anything but a man, and an insult.</p>\n<p>“Ah! this is well!” he stammered, in a voice stifled with rage.<br>He drew his sword, then stammering, for anger as well as fear<br>makes a man tremble: “Here! On the spot! Come on! Swords! Swords!<br>Blood on the pavement!”</p>\n<p>But the other never stirred. When he beheld his adversary on<br>guard and ready to parry,—</p>\n<p>“Captain Phœbus,” he said, and his tone vibrated with bitterness,<br>“you forget your appointment.”</p>\n<p>The rages of men like Phœbus are milk-soups, whose ebullition is<br>calmed by a drop of cold water. This simple remark caused the<br>sword which glittered in the captain’s hand to be lowered.</p>\n<p>“Captain,” pursued the man, “to-morrow, the day after to-morrow,<br>a month hence, ten years hence, you will find me ready to cut<br>your throat; but go first to your rendezvous.”</p>\n<p>“In sooth,” said Phœbus, as though seeking to capitulate with<br>himself, “these are two charming things to be encountered in a<br>rendezvous,—a sword and a wench; but I do not see why I should<br>miss the one for the sake of the other, when I can have both.”</p>\n<p>He replaced his sword in its scabbard.</p>\n<p>“Go to your rendezvous,” said the man.</p>\n<p>“Monsieur,” replied Phœbus with some embarrassment, “many thanks<br>for your courtesy. In fact, there will be ample time to-morrow<br>for us to chop up father Adam’s doublet into slashes and<br>buttonholes. I am obliged to you for allowing me to pass one more<br>agreeable quarter of an hour. I certainly did hope to put you in<br>the gutter, and still arrive in time for the fair one, especially<br>as it has a better appearance to make the women wait a little in<br>such cases. But you strike me as having the air of a gallant man,<br>and it is safer to defer our affair until to-morrow. So I will<br>betake myself to my rendezvous; it is for seven o’clock, as you<br>know.” Here Phœbus scratched his ear. “Ah. <em>Corne Dieu!</em> I had<br>forgotten! I haven’t a sou to discharge the price of the garret,<br>and the old crone will insist on being paid in advance. She<br>distrusts me.”</p>\n<p>“Here is the wherewithal to pay.”</p>\n<p>Phœbus felt the stranger’s cold hand slip into his a large piece<br>of money. He could not refrain from taking the money and pressing<br>the hand.</p>\n<p>“<em>Vrai Dieu!</em>” he exclaimed, “you are a good fellow!”</p>\n<p>“One condition,” said the man. “Prove to me that I have been<br>wrong and that you were speaking the truth. Hide me in some<br>corner whence I can see whether this woman is really the one<br>whose name you uttered.”</p>\n<p>“Oh!” replied Phœbus, “’tis all one to me. We will take, the<br>Sainte-Marthe chamber; you can look at your ease from the kennel<br>hard by.”</p>\n<p>“Come then,” said the shadow.</p>\n<p>“At your service,” said the captain, “I know not whether you are<br>Messer Diavolus in person; but let us be good friends for this<br>evening; to-morrow I will repay you all my debts, both of purse<br>and sword.”</p>\n<p>They set out again at a rapid pace. At the expiration of a few<br>minutes, the sound of the river announced to them that they were<br>on the Pont Saint-Michel, then loaded with houses.</p>\n<p>“I will first show you the way,” said Phœbus to his companion, “I<br>will then go in search of the fair one who is awaiting me near<br>the Petit-Châtelet.”</p>\n<p>His companion made no reply; he had not uttered a word since they<br>had been walking side by side. Phœbus halted before a low door,<br>and knocked roughly; a light made its appearance through the<br>cracks of the door.</p>\n<p>“Who is there?” cried a toothless voice.</p>\n<p>“<em>Corps-Dieu! Tête-Dieu! Ventre-Dieu!</em>” replied the captain.</p>\n<p>The door opened instantly, and allowed the new-comers to see an<br>old woman and an old lamp, both of which trembled. The old woman<br>was bent double, clad in tatters, with a shaking head, pierced<br>with two small eyes, and coiffed with a dish clout; wrinkled<br>everywhere, on hands and face and neck; her lips retreated under<br>her gums, and about her mouth she had tufts of white hairs which<br>gave her the whiskered look of a cat.</p>\n<p>The interior of the den was no less dilapitated than she; there<br>were chalk walls, blackened beams in the ceiling, a dismantled<br>chimney-piece, spiders’ webs in all the corners, in the middle a<br>staggering herd of tables and lame stools, a dirty child among<br>the ashes, and at the back a staircase, or rather, a wooden<br>ladder, which ended in a trapdoor in the ceiling.</p>\n<p>On entering this lair, Phœbus’s mysterious companion raised his<br>mantle to his very eyes. Meanwhile, the captain, swearing like a<br>Saracen, hastened to “make the sun shine in a crown” as saith our<br>admirable Régnier.</p>\n<p>“The Sainte-Marthe chamber,” said he.</p>\n<p>The old woman addressed him as monseigneur, and shut up the crown<br>in a drawer. It was the coin which the man in the black mantle<br>had given to Phœbus. While her back was turned, the bushy-headed<br>and ragged little boy who was playing in the ashes, adroitly<br>approached the drawer, abstracted the crown, and put in its place<br>a dry leaf which he had plucked from a fagot.</p>\n<p>The old crone made a sign to the two gentlemen, as she called<br>them, to follow her, and mounted the ladder in advance of them.<br>On arriving at the upper story, she set her lamp on a coffer,<br>and, Phœbus, like a frequent visitor of the house, opened a door<br>which opened on a dark hole. “Enter here, my dear fellow,” he<br>said to his companion. The man in the mantle obeyed without a<br>word in reply, the door closed upon him; he heard Phœbus bolt it,<br>and a moment later descend the stairs again with the aged hag.<br>The light had disappeared.</p>\n<h1 class=\"chapter\" id=\"chapter-viii-the-utility-of-windows-which-open-o\">Chapter VIII. THE UTILITY OF WINDOWS WHICH OPEN ON THE RIVER.</h1>\n<p>Claude Frollo (for we presume that the reader, more intelligent<br>than Phœbus, has seen in this whole adventure no other surly monk<br>than the archdeacon), Claude Frollo groped about for several<br>moments in the dark lair into which the captain had bolted him.<br>It was one of those nooks which architects sometimes reserve at<br>the point of junction between the roof and the supporting wall. A<br>vertical section of this kennel, as Phœbus had so justly styled<br>it, would have made a triangle. Moreover, there was neither<br>window nor air-hole, and the slope of the roof prevented one from<br>standing upright. Accordingly, Claude crouched down in the dust,<br>and the plaster which cracked beneath him; his head was on fire;<br>rummaging around him with his hands, he found on the floor a bit<br>of broken glass, which he pressed to his brow, and whose coolness<br>afforded him some relief.</p>\n<p>What was taking place at that moment in the gloomy soul of the<br>archdeacon? God and himself could alone know.</p>\n<p>In what order was he arranging in his mind la Esmeralda, Phœbus,<br>Jacques Charmolue, his young brother so beloved, yet abandoned by<br>him in the mire, his archdeacon’s cassock, his reputation perhaps<br>dragged to la Falourdel’s, all these adventures, all these<br>images? I cannot say. But it is certain that these ideas formed<br>in his mind a horrible group.</p>\n<p>He had been waiting a quarter of an hour; it seemed to him that<br>he had grown a century older. All at once he heard the creaking<br>of the boards of the stairway; some one was ascending. The<br>trapdoor opened once more; a light reappeared. There was a<br>tolerably large crack in the worm-eaten door of his den; he put<br>his face to it. In this manner he could see all that went on in<br>the adjoining room. The cat-faced old crone was the first to<br>emerge from the trap-door, lamp in hand; then Phœbus, twirling<br>his moustache, then a third person, that beautiful and graceful<br>figure, la Esmeralda. The priest beheld her rise from below like<br>a dazzling apparition. Claude trembled, a cloud spread over his<br>eyes, his pulses beat violently, everything rustled and whirled<br>around him; he no longer saw nor heard anything.</p>\n<p>When he recovered himself, Phœbus and Esmeralda were alone seated<br>on the wooden coffer beside the lamp which made these two<br>youthful figures and a miserable pallet at the end of the attic<br>stand out plainly before the archdeacon’s eyes.</p>\n<p>Beside the pallet was a window, whose panes broken like a<br>spider’s web upon which rain has fallen, allowed a view, through<br>its rent meshes, of a corner of the sky, and the moon lying far<br>away on an eiderdown bed of soft clouds.</p>\n<p>The young girl was blushing, confused, palpitating. Her long,<br>drooping lashes shaded her crimson cheeks. The officer, to whom<br>she dared not lift her eyes, was radiant. Mechanically, and with<br>a charmingly unconscious gesture, she traced with the tip of her<br>finger incoherent lines on the bench, and watched her finger. Her<br>foot was not visible. The little goat was nestling upon it.</p>\n<p>The captain was very gallantly clad; he had tufts of embroidery<br>at his neck and wrists; a great elegance at that day.</p>\n<p>It was not without difficulty that Dom Claude managed to hear<br>what they were saying, through the humming of the blood, which<br>was boiling in his temples.</p>\n<p>(A conversation between lovers is a very commonplace affair. It<br>is a perpetual “I love you.” A musical phrase which is very<br>insipid and very bald for indifferent listeners, when it is not<br>ornamented with some <em>fioriture;</em> but Claude was not an<br>indifferent listener.)</p>\n<p>“Oh!” said the young girl, without raising her eyes, “do not<br>despise me, monseigneur Phœbus. I feel that what I am doing is<br>not right.”</p>\n<p>“Despise you, my pretty child!” replied the officer with an air<br>of superior and distinguished gallantry, “despise you,<br><em>tête-Dieu!</em> and why?”</p>\n<p>“For having followed you!”</p>\n<p>“On that point, my beauty, we don’t agree. I ought not to despise<br>you, but to hate you.”</p>\n<p>The young girl looked at him in affright: “Hate me! what have I<br>done?”</p>\n<p>“For having required so much urging.”</p>\n<p>“Alas!” said she, “’tis because I am breaking a vow. I shall not<br>find my parents! The amulet will lose its virtue. But what<br>matters it? What need have I of father or mother now?”</p>\n<p>So saying, she fixed upon the captain her great black eyes, moist<br>with joy and tenderness.</p>\n<p>“Devil take me if I understand you!” exclaimed Phœbus. La<br>Esmeralda remained silent for a moment, then a tear dropped from<br>her eyes, a sigh from her lips, and she said,—“Oh! monseigneur, I<br>love you.”</p>\n<p>Such a perfume of chastity, such a charm of virtue surrounded the<br>young girl, that Phœbus did not feel completely at his ease<br>beside her. But this remark emboldened him: “You love me!” he<br>said with rapture, and he threw his arm round the gypsy’s waist.<br>He had only been waiting for this opportunity.</p>\n<p>The priest saw it, and tested with the tip of his finger the<br>point of a poniard which he wore concealed in his breast.</p>\n<p>“Phœbus,” continued the Bohemian, gently releasing her waist from<br>the captain’s tenacious hands, “You are good, you are generous,<br>you are handsome; you saved me, me who am only a poor child lost<br>in Bohemia. I had long been dreaming of an officer who should<br>save my life. ’Twas of you that I was dreaming, before I knew<br>you, my Phœbus; the officer of my dream had a beautiful uniform<br>like yours, a grand look, a sword; your name is Phœbus; ’tis a<br>beautiful name. I love your name; I love your sword. Draw your<br>sword, Phœbus, that I may see it.”</p>\n<p>“Child!” said the captain, and he unsheathed his sword with a<br>smile.</p>\n<p>The gypsy looked at the hilt, the blade; examined the cipher on<br>the guard with adorable curiosity, and kissed the sword, saying,—</p>\n<p>“You are the sword of a brave man. I love my captain.” Phœbus<br>again profited by the opportunity to impress upon her beautiful<br>bent neck a kiss which made the young girl straighten herself up<br>as scarlet as a poppy. The priest gnashed his teeth over it in<br>the dark.</p>\n<p>“Phœbus,” resumed the gypsy, “let me talk to you. Pray walk a<br>little, that I may see you at full height, and that I may hear<br>your spurs jingle. How handsome you are!”</p>\n<p>The captain rose to please her, chiding her with a smile of<br>satisfaction,—</p>\n<p>“What a child you are! By the way, my charmer, have you seen me<br>in my archer’s ceremonial doublet?”</p>\n<p>“Alas! no,” she replied.</p>\n<p>“It is very handsome!”</p>\n<p>Phœbus returned and seated himself beside her, but much closer<br>than before.</p>\n<p>“Listen, my dear—”</p>\n<p>The gypsy gave him several little taps with her pretty hand on<br>his mouth, with a childish mirth and grace and gayety.</p>\n<p>“No, no, I will not listen to you. Do you love me? I want you to<br>tell me whether you love me.”</p>\n<p>“Do I love thee, angel of my life!” exclaimed the captain, half<br>kneeling. “My body, my blood, my soul, all are thine; all are for<br>thee. I love thee, and I have never loved any one but thee.”</p>\n<p>The captain had repeated this phrase so many times, in many<br>similar conjunctures, that he delivered it all in one breath,<br>without committing a single mistake. At this passionate<br>declaration, the gypsy raised to the dirty ceiling which served<br>for the skies a glance full of angelic happiness.</p>\n<p>“Oh!” she murmured, “this is the moment when one should die!”</p>\n<p>Phœbus found “the moment” favorable for robbing her of another<br>kiss, which went to torture the unhappy archdeacon in his nook.<br>“Die!” exclaimed the amorous captain, “What are you saying, my<br>lovely angel? ’Tis a time for living, or Jupiter is only a scamp!<br>Die at the beginning of so sweet a thing! <em>Corne-de-bœuf</em>, what a<br>jest! It is not that. Listen, my dear Similar, Esmenarda—Pardon!<br>you have so prodigiously Saracen a name that I never can get it<br>straight. ’Tis a thicket which stops me short.”</p>\n<p>“Good heavens!” said the poor girl, “and I thought my name pretty<br>because of its singularity! But since it displeases you, I would<br>that I were called Goton.”</p>\n<p>“Ah! do not weep for such a trifle, my graceful maid! ’tis a name<br>to which one must get accustomed, that is all. When I once know<br>it by heart, all will go smoothly. Listen then, my dear Similar;<br>I adore you passionately. I love you so that ’tis simply<br>miraculous. I know a girl who is bursting with rage over it—”</p>\n<p>The jealous girl interrupted him: “Who?”</p>\n<p>“What matters that to us?” said Phœbus; “do you love me?”</p>\n<p>“Oh!”—said she.</p>\n<p>“Well! that is all. You shall see how I love you also. May the<br>great devil Neptunus spear me if I do not make you the happiest<br>woman in the world. We will have a pretty little house somewhere.<br>I will make my archers parade before your windows. They are all<br>mounted, and set at defiance those of Captain Mignon. There are<br><em>voulgiers, cranequiniers</em> and hand <em>couleveiniers</em>[44]. I will<br>take you to the great sights of the Parisians at the storehouse<br>of Rully. Eighty thousand armed men, thirty thousand white<br>harnesses, short coats or coats of mail; the sixty-seven banners<br>of the trades; the standards of the parliaments, of the chamber<br>of accounts, of the treasury of the generals, of the aides of the<br>mint; a devilish fine array, in short! I will conduct you to see<br>the lions of the Hôtel du Roi, which are wild beasts. All women<br>love that.”</p>\n<p>For several moments the young girl, absorbed in her charming<br>thoughts, was dreaming to the sound of his voice, without<br>listening to the sense of his words.</p>\n<p>“Oh! how happy you will be!” continued the captain, and at the<br>same time he gently unbuckled the gypsy’s girdle.</p>\n<p>“What are you doing?” she said quickly. This “act of violence”<br>had roused her from her revery.</p>\n<p>“Nothing,” replied Phœbus, “I was only saying that you must<br>abandon all this garb of folly, and the street corner when you<br>are with me.”</p>\n<p>“When I am with you, Phœbus!” said the young girl tenderly.</p>\n<p>She became pensive and silent once more.</p>\n<p>The captain, emboldened by her gentleness, clasped her waist<br>without resistance; then began softly to unlace the poor child’s<br>corsage, and disarranged her tucker to such an extent that the<br>panting priest beheld the gypsy’s beautiful shoulder emerge from<br>the gauze, as round and brown as the moon rising through the<br>mists of the horizon.</p>\n<p>The young girl allowed Phœbus to have his way. She did not appear<br>to perceive it. The eye of the bold captain flashed.</p>\n<p>Suddenly she turned towards him,—</p>\n<p>“Phœbus,” she said, with an expression of infinite love,<br>“instruct me in thy religion.”</p>\n<p>“My religion!” exclaimed the captain, bursting with laughter, “I<br>instruct you in my religion! <em>Corne et tonnerre!</em> What do you<br>want with my religion?”</p>\n<p>“In order that we may be married,” she replied.</p>\n<p>The captain’s face assumed an expression of mingled surprise and<br>disdain, of carelessness and libertine passion.</p>\n<p>“Ah, bah!” said he, “do people marry?”</p>\n<p>The Bohemian turned pale, and her head drooped sadly on her<br>breast.</p>\n<p>“My beautiful love,” resumed Phœbus, tenderly, “what nonsense is<br>this? A great thing is marriage, truly! one is none the less<br>loving for not having spit Latin into a priest’s shop!”</p>\n<p>While speaking thus in his softest voice, he approached extremely<br>near the gypsy; his caressing hands resumed their place around<br>her supple and delicate waist, his eye flashed more and more, and<br>everything announced that Monsieur Phœbus was on the verge of one<br>of those moments when Jupiter himself commits so many follies<br>that Homer is obliged to summon a cloud to his rescue.</p>\n<p>But Dom Claude saw everything. The door was made of thoroughly<br>rotten cask staves, which left large apertures for the passage of<br>his hawklike gaze. This brown-skinned, broad-shouldered priest,<br>hitherto condemned to the austere virginity of the cloister, was<br>quivering and boiling in the presence of this night scene of love<br>and voluptuousness. This young and beautiful girl given over in<br>disarray to the ardent young man, made melted lead flow in<br>his-veins; his eyes darted with sensual jealousy beneath all<br>those loosened pins. Any one who could, at that moment, have seen<br>the face of the unhappy man glued to the wormeaten bars, would<br>have thought that he beheld the face of a tiger glaring from the<br>depths of a cage at some jackal devouring a gazelle. His eye<br>shone like a candle through the cracks of the door.</p>\n<p>All at once, Phœbus, with a rapid gesture, removed the gypsy’s<br>gorgerette. The poor child, who had remained pale and dreamy,<br>awoke with a start; she recoiled hastily from the enterprising<br>officer, and, casting a glance at her bare neck and shoulders,<br>red, confused, mute with shame, she crossed her two beautiful<br>arms on her breast to conceal it. Had it not been for the flame<br>which burned in her cheeks, at the sight of her so silent and<br>motionless, one would have declared her a statue of Modesty. Her<br>eyes were lowered.</p>\n<p>But the captain’s gesture had revealed the mysterious amulet<br>which she wore about her neck.</p>\n<p>“What is that?” he said, seizing this pretext to approach once<br>more the beautiful creature whom he had just alarmed.</p>\n<p>“Don’t touch it!” she replied, quickly, “’tis my guardian. It<br>will make me find my family again, if I remain worthy to do so.<br>Oh, leave me, monsieur le capitaine! My mother! My poor mother!<br>My mother! Where art thou? Come to my rescue! Have pity, Monsieur<br>Phœbus, give me back my gorgerette!”</p>\n<p>Phœbus retreated amid said in a cold tone,—</p>\n<p>“Oh, mademoiselle! I see plainly that you do not love me!”</p>\n<p>“I do not love him!” exclaimed the unhappy child, and at the same<br>time she clung to the captain, whom she drew to a seat beside<br>her. “I do not love thee, my Phœbus? What art thou saying, wicked<br>man, to break my heart? Oh, take me! take all! do what you will<br>with me, I am thine. What matters to me the amulet! What matters<br>to me my mother! ’Tis thou who art my mother since I love thee!<br>Phœbus, my beloved Phœbus, dost thou see me? ’Tis I. Look at me;<br>’tis the little one whom thou wilt surely not repulse, who comes,<br>who comes herself to seek thee. My soul, my life, my body, my<br>person, all is one thing—which is thine, my captain. Well, no! We<br>will not marry, since that displeases thee; and then, what am I?<br>a miserable girl of the gutters; whilst thou, my Phœbus, art a<br>gentleman. A fine thing, truly! A dancer wed an officer! I was<br>mad. No, Phœbus, no; I will be thy mistress, thy amusement, thy<br>pleasure, when thou wilt; a girl who shall belong to thee. I was<br>only made for that, soiled, despised, dishonored, but what<br>matters it?—beloved. I shall be the proudest and the most joyous<br>of women. And when I grow old or ugly, Phœbus, when I am no<br>longer good to love you, you will suffer me to serve you still.<br>Others will embroider scarfs for you; ’tis I, the servant, who<br>will care for them. You will let me polish your spurs, brush your<br>doublet, dust your riding-boots. You will have that pity, will<br>you not, Phœbus? Meanwhile, take me! here, Phœbus, all this<br>belongs to thee, only love me! We gypsies need only air and<br>love.”</p>\n<p>So saying, she threw her arms round the officer’s neck; she<br>looked up at him, supplicatingly, with a beautiful smile, and all<br>in tears. Her delicate neck rubbed against his cloth doublet with<br>its rough embroideries. She writhed on her knees, her beautiful<br>body half naked. The intoxicated captain pressed his ardent lips<br>to those lovely African shoulders. The young girl, her eyes bent<br>on the ceiling, as she leaned backwards, quivered, all<br>palpitating, beneath this kiss.</p>\n<p>All at once, above Phœbus’s head she beheld another head; a<br>green, livid, convulsed face, with the look of a lost soul; near<br>this face was a hand grasping a poniard. It was the face and hand<br>of the priest; he had broken the door and he was there. Phœbus<br>could not see him. The young girl remained motionless, frozen<br>with terror, dumb, beneath that terrible apparition, like a dove<br>which should raise its head at the moment when the hawk is gazing<br>into her nest with its round eyes.</p>\n<p>She could not even utter a cry. She saw the poniard descend upon<br>Phœbus, and rise again, reeking.</p>\n<p>“Maledictions!” said the captain, and fell.</p>\n<p>She fainted.</p>\n<p>At the moment when her eyes closed, when all feeling vanished in<br>her, she thought that she felt a touch of fire imprinted upon her<br>lips, a kiss more burning than the red-hot iron of the<br>executioner.</p>\n<p>When she recovered her senses, she was surrounded by soldiers of<br>the watch they were carrying away the captain, bathed in his<br>blood the priest had disappeared; the window at the back of the<br>room which opened on the river was wide open; they picked up a<br>cloak which they supposed to belong to the officer and she heard<br>them saying around her,</p>\n<p>“’Tis a sorceress who has stabbed a captain.”</p>\n<p>BOOK EIGHTH.</p>\n<h1 class=\"chapter\" id=\"chapter-i-the-crown-changed-into-a-dry-leaf\">Chapter I. THE CROWN CHANGED INTO A DRY LEAF.</h1>\n<p>Gringoire and the entire Court of Miracles were suffering mortal<br>anxiety. For a whole month they had not known what had become of<br>la Esmeralda, which greatly pained the Duke of Egypt and his<br>friends the vagabonds, nor what had become of the goat, which<br>redoubled Gringoire’s grief. One evening the gypsy had<br>disappeared, and since that time had given no signs of life. All<br>search had proved fruitless. Some tormenting bootblacks had told<br>Gringoire about meeting her that same evening near the Pont<br>Saint-Michel, going off with an officer; but this husband, after<br>the fashion of Bohemia, was an incredulous philosopher, and<br>besides, he, better than any one else, knew to what a point his<br>wife was virginal. He had been able to form a judgment as to the<br>unconquerable modesty resulting from the combined virtues of the<br>amulet and the gypsy, and he had mathematically calculated the<br>resistance of that chastity to the second power. Accordingly, he<br>was at ease on that score.</p>\n<p>Still he could not understand this disappearance. It was a<br>profound sorrow. He would have grown thin over it, had that been<br>possible. He had forgotten everything, even his literary tastes,<br>even his great work, <em>De figuris regularibus et irregularibus</em>,<br>which it was his intention to have printed with the first money<br>which he should procure (for he had raved over printing, ever<br>since he had seen the “Didascalon” of Hugues de Saint Victor,<br>printed with the celebrated characters of Vindelin de Spire).</p>\n<p>One day, as he was passing sadly before the criminal Tournelle,<br>he perceived a considerable crowd at one of the gates of the<br>Palais de Justice.</p>\n<p>“What is this?” he inquired of a young man who was coming out.</p>\n<p>“I know not, sir,” replied the young man. “’Tis said that they<br>are trying a woman who hath assassinated a gendarme. It appears<br>that there is sorcery at the bottom of it, the archbishop and the<br>official have intervened in the case, and my brother, who is the<br>archdeacon of Josas, can think of nothing else. Now, I wished to<br>speak with him, but I have not been able to reach him because of<br>the throng, which vexes me greatly, as I stand in need of money.”</p>\n<p>“Alas! sir,” said Gringoire, “I would that I could lend you some,<br>but, my breeches are worn to holes, and ’tis not crowns which<br>have done it.”</p>\n<p>He dared not tell the young man that he was acquainted with his<br>brother the archdeacon, to whom he had not returned after the<br>scene in the church; a negligence which embarrassed him.</p>\n<p>The scholar went his way, and Gringoire set out to follow the<br>crowd which was mounting the staircase of the great chamber. In<br>his opinion, there was nothing like the spectacle of a criminal<br>process for dissipating melancholy, so exhilaratingly stupid are<br>judges as a rule. The populace which he had joined walked and<br>elbowed in silence. After a slow and tiresome march through a<br>long, gloomy corridor, which wound through the court-house like<br>the intestinal canal of the ancient edifice, he arrived near a<br>low door, opening upon a hall which his lofty stature permitted<br>him to survey with a glance over the waving heads of the rabble.</p>\n<p>The hall was vast and gloomy, which latter fact made it appear<br>still more spacious. The day was declining; the long, pointed<br>windows permitted only a pale ray of light to enter, which was<br>extinguished before it reached the vaulted ceiling, an enormous<br>trellis-work of sculptured beams, whose thousand figures seemed<br>to move confusedly in the shadows, many candles were already<br>lighted here and there on tables, and beaming on the heads of<br>clerks buried in masses of documents. The anterior portion of the<br>hall was occupied by the crowd; on the right and left were<br>magistrates and tables; at the end, upon a platform, a number of<br>judges, whose rear rank sank into the shadows, sinister and<br>motionless faces. The walls were sown with innumerable<br>fleurs-de-lis. A large figure of Christ might be vaguely descried<br>above the judges, and everywhere there were pikes and halberds,<br>upon whose points the reflection of the candles placed tips of<br>fire.</p>\n<p>“Monsieur,” Gringoire inquired of one of his neighbors, “who are<br>all those persons ranged yonder, like prelates in council?”</p>\n<p>“Monsieur,” replied the neighbor, “those on the right are the<br>counsellors of the grand chamber; those on the left, the<br>councillors of inquiry; the masters in black gowns, the messires<br>in red.”</p>\n<p>“Who is that big red fellow, yonder above them, who is sweating?”<br>pursued Gringoire.</p>\n<p>“It is monsieur the president.”</p>\n<p>“And those sheep behind him?” continued Gringoire, who as we have<br>seen, did not love the magistracy, which arose, possibly, from<br>the grudge which he cherished against the Palais de Justice since<br>his dramatic misadventure.</p>\n<p>“They are messieurs the masters of requests of the king’s<br>household.”</p>\n<p>“And that boar in front of him?”</p>\n<p>“He is monsieur the clerk of the Court of Parliament.”</p>\n<p>“And that crocodile on the right?”</p>\n<p>“Master Philippe Lheulier, advocate extraordinary of the king.”</p>\n<p>“And that big, black tom-cat on the left?”</p>\n<p>“Master Jacques Charmolue, procurator of the king in the<br>Ecclesiastical Court, with the gentlemen of the officialty.”</p>\n<p>“Come now, monsieur,” said Gringoire, “pray what are all those<br>fine fellows doing yonder?”</p>\n<p>“They are judging.”</p>\n<p>“Judging whom? I do not see the accused.”</p>\n<p>“’Tis a woman, sir. You cannot see her. She has her back turned<br>to us, and she is hidden from us by the crowd. Stay, yonder she<br>is, where you see a group of partisans.”</p>\n<p>“Who is the woman?” asked Gringoire. “Do you know her name?”</p>\n<p>“No, monsieur, I have but just arrived. I merely assume that<br>there is some sorcery about it, since the official is present at<br>the trial.”</p>\n<p>“Come!” said our philosopher, “we are going to see all these<br>magistrates devour human flesh. ’Tis as good a spectacle as any<br>other.”</p>\n<p>“Monsieur,” remarked his neighbor, “think you not, that Master<br>Jacques Charmolue has a very sweet air?”</p>\n<p>“Hum!” replied Gringoire. “I distrust a sweetness which hath<br>pinched nostrils and thin lips.”</p>\n<p>Here the bystanders imposed silence upon the two chatterers. They<br>were listening to an important deposition.</p>\n<p>“Messeigneurs,” said an old woman in the middle of the hall,<br>whose form was so concealed beneath her garments that one would<br>have pronounced her a walking heap of rags; “Messeigneurs, the<br>thing is as true as that I am la Falourdel, established these<br>forty years at the Pont Saint Michel, and paying regularly my<br>rents, lord’s dues, and quit rents; at the gate opposite the<br>house of Tassin-Caillart, the dyer, which is on the side up the<br>river—a poor old woman now, but a pretty maid in former days, my<br>lords. Some one said to me lately, ‘La Falourdel, don’t use your<br>spinning-wheel too much in the evening; the devil is fond of<br>combing the distaffs of old women with his horns. ’Tis certain<br>that the surly monk who was round about the temple last year, now<br>prowls in the City. Take care, La Falourdel, that he doth not<br>knock at your door.’ One evening I was spinning on my wheel,<br>there comes a knock at my door; I ask who it is. They swear. I<br>open. Two men enter. A man in black and a handsome officer. Of<br>the black man nothing could be seen but his eyes, two coals of<br>fire. All the rest was hat and cloak. They say to me,—‘The<br>Sainte-Marthe chamber.’—’Tis my upper chamber, my lords, my<br>cleanest. They give me a crown. I put the crown in my drawer, and<br>I say: ‘This shall go to buy tripe at the slaughter-house of la<br>Gloriette to-morrow.’ We go up stairs. On arriving at the upper<br>chamber, and while my back is turned, the black man disappears.<br>That dazed me a bit. The officer, who was as handsome as a great<br>lord, goes down stairs again with me. He goes out. In about the<br>time it takes to spin a quarter of a handful of flax, he returns<br>with a beautiful young girl, a doll who would have shone like the<br>sun had she been coiffed. She had with her a goat; a big<br>billy-goat, whether black or white, I no longer remember. That<br>set me to thinking. The girl does not concern me, but the goat! I<br>love not those beasts, they have a beard and horns. They are so<br>like a man. And then, they smack of the witches, sabbath.<br>However, I say nothing. I had the crown. That is right, is it<br>not, Monsieur Judge? I show the captain and the wench to the<br>upper chamber, and I leave them alone; that is to say, with the<br>goat. I go down and set to spinning again—I must inform you that<br>my house has a ground floor and story above. I know not why I<br>fell to thinking of the surly monk whom the goat had put into my<br>head again, and then the beautiful girl was rather strangely<br>decked out. All at once, I hear a cry upstairs, and something<br>falls on the floor and the window opens. I run to mine which is<br>beneath it, and I behold a black mass pass before my eyes and<br>fall into the water. It was a phantom clad like a priest. It was<br>a moonlight night. I saw him quite plainly. He was swimming in<br>the direction of the city. Then, all of a tremble, I call the<br>watch. The gentlemen of the police enter, and not knowing just at<br>the first moment what the matter was, and being merry, they beat<br>me. I explain to them. We go up stairs, and what do we find? my<br>poor chamber all blood, the captain stretched out at full length<br>with a dagger in his neck, the girl pretending to be dead, and<br>the goat all in a fright. ‘Pretty work!’ I say, ‘I shall have to<br>wash that floor for more than a fortnight. It will have to be<br>scraped; it will be a terrible job.’ They carried off the<br>officer, poor young man, and the wench with her bosom all bare.<br>But wait, the worst is that on the next day, when I wanted to<br>take the crown to buy tripe, I found a dead leaf in its place.”</p>\n<p>The old woman ceased. A murmur of horror ran through the<br>audience.</p>\n<p>“That phantom, that goat,—all smacks of magic,” said one of<br>Gringoire’s neighbors.</p>\n<p>“And that dry leaf!” added another.</p>\n<p>“No doubt about it,” joined in a third, “she is a witch who has<br>dealings with the surly monk, for the purpose of plundering<br>officers.”</p>\n<p>Gringoire himself was not disinclined to regard this as<br>altogether alarming and probable.</p>\n<p>“Goody Falourdel,” said the president majestically, “have you<br>nothing more to communicate to the court?”</p>\n<p>“No, monseigneur,” replied the crone, “except that the report has<br>described my house as a hovel and stinking; which is an<br>outrageous fashion of speaking. The houses on the bridge are not<br>imposing, because there are such multitudes of people; but,<br>nevertheless, the butchers continue to dwell there, who are<br>wealthy folk, and married to very proper and handsome women.”</p>\n<p>The magistrate who had reminded Gringoire of a crocodile rose,—</p>\n<p>“Silence!” said he. “I pray the gentlemen not to lose sight of<br>the fact that a dagger was found on the person of the accused.<br>Goody Falourdel, have you brought that leaf into which the crown<br>which the demon gave you was transformed?</p>\n<p>“Yes, monseigneur,” she replied; “I found it again. Here it is.”</p>\n<p>A bailiff handed the dead leaf to the crocodile, who made a<br>doleful shake of the head, and passed it on to the president, who<br>gave it to the procurator of the king in the ecclesiastical<br>court, and thus it made the circuit of the hall.</p>\n<p>“It is a birch leaf,” said Master Jacques Charmolue. “A fresh<br>proof of magic.”</p>\n<p>A counsellor took up the word.</p>\n<p>“Witness, two men went upstairs together in your house: the black<br>man, whom you first saw disappear and afterwards swimming in the<br>Seine, with his priestly garments, and the officer. Which of the<br>two handed you the crown?” The old woman pondered for a moment<br>and then said,—</p>\n<p>“The officer.”</p>\n<p>A murmur ran through the crowd.</p>\n<p>“Ah!” thought Gringoire, “this makes some doubt in my mind.”</p>\n<p>But Master Philippe Lheulier, advocate extraordinary to the king,<br>interposed once more.</p>\n<p>“I will recall to these gentlemen, that in the deposition taken<br>at his bedside, the assassinated officer, while declaring that he<br>had a vague idea when the black man accosted him that the latter<br>might be the surly monk, added that the phantom had pressed him<br>eagerly to go and make acquaintance with the accused; and upon<br>his, the captain’s, remarking that he had no money, he had given<br>him the crown which the said officer paid to la Falourdel. Hence,<br>that crown is the money of hell.”</p>\n<p>This conclusive observation appeared to dissipate all the doubts<br>of Gringoire and the other sceptics in the audience.</p>\n<p>“You have the documents, gentlemen,” added the king’s advocate,<br>as he took his seat; “you can consult the testimony of Phœbus de<br>Châteaupers.”</p>\n<p>At that name, the accused sprang up, her head rose above the<br>throng. Gringoire with horror recognized la Esmeralda.</p>\n<p>She was pale; her tresses, formerly so gracefully braided and<br>spangled with sequins, hung in disorder; her lips were blue, her<br>hollow eyes were terrible. Alas!</p>\n<p>“Phœbus!” she said, in bewilderment; “where is he? O<br>messeigneurs! before you kill me, tell me, for pity sake, whether<br>he still lives?”</p>\n<p>“Hold your tongue, woman,” replied the president, “that is no<br>affair of ours.”</p>\n<p>“Oh! for mercy’s sake, tell me if he is alive!” she repeated,<br>clasping her beautiful emaciated hands; and the sound of her<br>chains in contact with her dress, was heard.</p>\n<p>“Well!” said the king’s advocate roughly, “he is dying. Are you<br>satisfied?”</p>\n<p>The unhappy girl fell back on her criminal’s seat, speechless,<br>tearless, white as a wax figure.</p>\n<p>The president bent down to a man at his feet, who wore a gold cap<br>and a black gown, a chain on his neck and a wand in his hand.</p>\n<p>“Bailiff, bring in the second accused.”</p>\n<p>All eyes turned towards a small door, which opened, and, to the<br>great agitation of Gringoire, gave passage to a pretty goat with<br>horns and hoofs of gold. The elegant beast halted for a moment on<br>the threshold, stretching out its neck as though, perched on the<br>summit of a rock, it had before its eyes an immense horizon.<br>Suddenly it caught sight of the gypsy girl, and leaping over the<br>table and the head of a clerk, in two bounds it was at her knees;<br>then it rolled gracefully on its mistress’s feet, soliciting a<br>word or a caress; but the accused remained motionless, and poor<br>Djali himself obtained not a glance.</p>\n<p>“Eh, why—’tis my villanous beast,” said old Falourdel, “I<br>recognize the two perfectly!”</p>\n<p>Jacques Charmolue interfered.</p>\n<p>“If the gentlemen please, we will proceed to the examination of<br>the goat.” He was, in fact, the second criminal. Nothing more<br>simple in those days than a suit of sorcery instituted against an<br>animal. We find, among others in the accounts of the provost’s<br>office for 1466, a curious detail concerning the expenses of the<br>trial of Gillet-Soulart and his sow, “executed for their<br>demerits,” at Corbeil. Everything is there, the cost of the pens<br>in which to place the sow, the five hundred bundles of brushwood<br>purchased at the port of Morsant, the three pints of wine and the<br>bread, the last repast of the victim fraternally shared by the<br>executioner, down to the eleven days of guard and food for the<br>sow, at eight deniers parisis each. Sometimes, they went even<br>further than animals. The capitularies of Charlemagne and of<br>Louis le Débonnaire impose severe penalties on fiery phantoms<br>which presume to appear in the air.</p>\n<p>Meanwhile the procurator had exclaimed: “If the demon which<br>possesses this goat, and which has resisted all exorcisms,<br>persists in its deeds of witchcraft, if it alarms the court with<br>them, we warn it that we shall be forced to put in requisition<br>against it the gallows or the stake. Gringoire broke out into a<br>cold perspiration. Charmolue took from the table the gypsy’s<br>tambourine, and presenting it to the goat, in a certain manner,<br>asked the latter,—</p>\n<p>“What o’clock is it?”</p>\n<p>The goat looked at it with an intelligent eye, raised its gilded<br>hoof, and struck seven blows.</p>\n<p>It was, in fact, seven o’clock. A movement of terror ran through<br>the crowd.</p>\n<p>Gringoire could not endure it.</p>\n<p>“He is destroying himself!” he cried aloud; “You see well that he<br>does not know what he is doing.”</p>\n<p>“Silence among the louts at the end of the hall!” said the<br>bailiff sharply.</p>\n<p>Jacques Charmolue, by the aid of the same manœuvres of the<br>tambourine, made the goat perform many other tricks connected<br>with the date of the day, the month of the year, etc., which the<br>reader has already witnessed. And, by virtue of an optical<br>illusion peculiar to judicial proceedings, these same spectators<br>who had, probably, more than once applauded in the public square<br>Djali’s innocent magic were terrified by it beneath the roof of<br>the Palais de Justice. The goat was undoubtedly the devil.</p>\n<p>It was far worse when the procurator of the king, having emptied<br>upon a floor a certain bag filled with movable letters, which<br>Djali wore round his neck, they beheld the goat extract with his<br>hoof from the scattered alphabet the fatal name of <em>Phœbus</em>. The<br>witchcraft of which the captain had been the victim appeared<br>irresistibly demonstrated, and in the eyes of all, the gypsy,<br>that ravishing dancer, who had so often dazzled the passers-by<br>with her grace, was no longer anything but a frightful vampire.</p>\n<p>However, she betrayed no sign of life; neither Djali’s graceful<br>evolutions, nor the menaces of the court, nor the suppressed<br>imprecations of the spectators any longer reached her mind.</p>\n<p>In order to arouse her, a police officer was obliged to shake her<br>unmercifully, and the president had to raise his voice,—</p>\n<p>“Girl, you are of the Bohemian race, addicted to deeds of<br>witchcraft. You, in complicity with the bewitched goat implicated<br>in this suit, during the night of the twenty-ninth of March last,<br>murdered and stabbed, in concert with the powers of darkness, by<br>the aid of charms and underhand practices, a captain of the<br>king’s arches of the watch, Phœbus de Châteaupers. Do you persist<br>in denying it?”</p>\n<p>“Horror!” exclaimed the young girl, hiding her face in her hands.<br>“My Phœbus! Oh, this is hell!”</p>\n<p>“Do you persist in your denial?” demanded the president coldly.</p>\n<p>“Do I deny it?” she said with terrible accents; and she rose with<br>flashing eyes.</p>\n<p>The president continued squarely,—</p>\n<p>“Then how do you explain the facts laid to your charge?”</p>\n<p>She replied in a broken voice,—</p>\n<p>“I have already told you. I do not know. ’Twas a priest, a priest<br>whom I do not know; an infernal priest who pursues me!”</p>\n<p>“That is it,” retorted the judge; “the surly monk.”</p>\n<p>“Oh, gentlemen! have mercy! I am but a poor girl—”</p>\n<p>“Of Egypt,” said the judge.</p>\n<p>Master Jacques Charmolue interposed sweetly,—</p>\n<p>“In view of the sad obstinacy of the accused, I demand the<br>application of the torture.”</p>\n<p>“Granted,” said the president.</p>\n<p>The unhappy girl quivered in every limb. But she rose at the<br>command of the men with partisans, and walked with a tolerably<br>firm step, preceded by Charmolue and the priests of the<br>officiality, between two rows of halberds, towards a medium-sized<br>door which suddenly opened and closed again behind her, and which<br>produced upon the grief-stricken Gringoire the effect of a<br>horrible mouth which had just devoured her.</p>\n<p>When she disappeared, they heard a plaintive bleating; it was the<br>little goat mourning.</p>\n<p>The sitting of the court was suspended. A counsellor having<br>remarked that the gentlemen were fatigued, and that it would be a<br>long time to wait until the torture was at an end, the president<br>replied that a magistrate must know how to sacrifice himself to<br>his duty.</p>\n<p>“What an annoying and vexatious hussy,” said an aged judge, “to<br>get herself put to the question when one has not supped!”</p>\n<h1 class=\"chapter\" id=\"chapter-ii-continuation-of-the-crown-which-was-c\">Chapter II. CONTINUATION OF THE CROWN WHICH WAS CHANGED INTO A</h1>\n<p>DRY LEAF.</p>\n<p>After ascending and descending several steps in the corridors,<br>which were so dark that they were lighted by lamps at midday, La<br>Esmeralda, still surrounded by her lugubrious escort, was thrust<br>by the police into a gloomy chamber. This chamber, circular in<br>form, occupied the ground floor of one of those great towers,<br>which, even in our own century, still pierce through the layer of<br>modern edifices with which modern Paris has covered ancient<br>Paris. There were no windows to this cellar; no other opening<br>than the entrance, which was low, and closed by an enormous iron<br>door. Nevertheless, light was not lacking; a furnace had been<br>constructed in the thickness of the wall; a large fire was<br>lighted there, which filled the vault with its crimson<br>reflections and deprived a miserable candle, which stood in one<br>corner, of all radiance. The iron grating which served to close<br>the oven, being raised at that moment, allowed only a view at the<br>mouth of the flaming vent-hole in the dark wall, the lower<br>extremity of its bars, like a row of black and pointed teeth, set<br>flat apart; which made the furnace resemble one of those mouths<br>of dragons which spout forth flames in ancient legends. By the<br>light which escaped from it, the prisoner beheld, all about the<br>room, frightful instruments whose use she did not understand. In<br>the centre lay a leather mattress, placed almost flat upon the<br>ground, over which hung a strap provided with a buckle, attached<br>to a brass ring in the mouth of a flat-nosed monster carved in<br>the keystone of the vault. Tongs, pincers, large ploughshares,<br>filled the interior of the furnace, and glowed in a confused heap<br>on the coals. The sanguine light of the furnace illuminated in<br>the chamber only a confused mass of horrible things.</p>\n<p>This Tartarus was called simply, The Question Chamber.</p>\n<p>On the bed, in a negligent attitude, sat Pierrat Torterue, the<br>official torturer. His underlings, two gnomes with square faces,<br>leather aprons, and linen breeches, were moving the iron<br>instruments on the coals.</p>\n<p>In vain did the poor girl summon up her courage; on entering this<br>chamber she was stricken with horror.</p>\n<p>The sergeants of the bailiff of the courts drew up in line on one<br>side, the priests of the officiality on the other. A clerk,<br>inkhorn, and a table were in one corner.</p>\n<p>Master Jacques Charmolue approached the gypsy with a very sweet<br>smile.</p>\n<p>“My dear child,” said he, “do you still persist in your denial?”</p>\n<p>“Yes,” she replied, in a dying voice.</p>\n<p>“In that case,” replied Charmolue, “it will be very painful for<br>us to have to question you more urgently than we should like.<br>Pray take the trouble to seat yourself on this bed. Master<br>Pierrat, make room for mademoiselle, and close the door.”</p>\n<p>Pierrat rose with a growl.</p>\n<p>“If I shut the door,” he muttered, “my fire will go out.”</p>\n<p>“Well, my dear fellow,” replied Charmolue, “leave it open then.”</p>\n<p>Meanwhile, la Esmeralda had remained standing. That leather bed<br>on which so many unhappy wretches had writhed, frightened her.<br>Terror chilled the very marrow of her bones; she stood there<br>bewildered and stupefied. At a sign from Charmolue, the two<br>assistants took her and placed her in a sitting posture on the<br>bed. They did her no harm; but when these men touched her, when<br>that leather touched her, she felt all her blood retreat to her<br>heart. She cast a frightened look around the chamber. It seemed<br>to her as though she beheld advancing from all quarters towards<br>her, with the intention of crawling up her body and biting and<br>pinching her, all those hideous implements of torture, which as<br>compared to the instruments of all sorts she had hitherto seen,<br>were like what bats, centipedes, and spiders are among insects<br>and birds.</p>\n<p>“Where is the physician?” asked Charmolue.</p>\n<p>“Here,” replied a black gown whom she had not before noticed.</p>\n<p>She shuddered.</p>\n<p>“Mademoiselle,” resumed the caressing voice of the procucrator of<br>the Ecclesiastical court, “for the third time, do you persist in<br>denying the deeds of which you are accused?”</p>\n<p>This time she could only make a sign with her head.</p>\n<p>“You persist?” said Jacques Charmolue. “Then it grieves me<br>deeply, but I must fulfil my office.”</p>\n<p>“Monsieur le Procureur du Roi,” said Pierrat abruptly, “How shall<br>we begin?”</p>\n<p>Charmolue hesitated for a moment with the ambiguous grimace of a<br>poet in search of a rhyme.</p>\n<p>“With the boot,” he said at last.</p>\n<p>The unfortunate girl felt herself so utterly abandoned by God and<br>men, that her head fell upon her breast like an inert thing which<br>has no power in itself.</p>\n<p>The tormentor and the physician approached her simultaneously. At<br>the same time, the two assistants began to fumble among their<br>hideous arsenal.</p>\n<p>At the clanking of their frightful irons, the unhappy child<br>quivered like a dead frog which is being galvanized. “Oh!” she<br>murmured, so low that no one heard her; “Oh, my Phœbus!” Then she<br>fell back once more into her immobility and her marble silence.<br>This spectacle would have rent any other heart than those of her<br>judges. One would have pronounced her a poor sinful soul, being<br>tortured by Satan beneath the scarlet wicket of hell. The<br>miserable body which that frightful swarm of saws, wheels, and<br>racks were about to clasp in their clutches, the being who was<br>about to be manipulated by the harsh hands of executioners and<br>pincers, was that gentle, white, fragile creature, a poor grain<br>of millet which human justice was handing over to the terrible<br>mills of torture to grind. Meanwhile, the callous hands of<br>Pierrat Torterue’s assistants had bared that charming leg, that<br>tiny foot, which had so often amazed the passers-by with their<br>delicacy and beauty, in the squares of Paris.</p>\n<p>“’Tis a shame!” muttered the tormentor, glancing at these<br>graceful and delicate forms.</p>\n<p>Had the archdeacon been present, he certainly would have recalled<br>at that moment his symbol of the spider and the fly. Soon the<br>unfortunate girl, through a mist which spread before her eyes,<br>beheld the boot approach; she soon beheld her foot encased<br>between iron plates disappear in the frightful apparatus. Then<br>terror restored her strength.</p>\n<p>“Take that off!” she cried angrily; and drawing herself up, with<br>her hair all dishevelled: “Mercy!”</p>\n<p>She darted from the bed to fling herself at the feet of the<br>king’s procurator, but her leg was fast in the heavy block of oak<br>and iron, and she sank down upon the boot, more crushed than a<br>bee with a lump of lead on its wing.</p>\n<p>At a sign from Charmolue, she was replaced on the bed, and two<br>coarse hands adjusted to her delicate waist the strap which hung<br>from the ceiling.</p>\n<p>“For the last time, do you confess the facts in the case?”<br>demanded Charmolue, with his imperturbable benignity.</p>\n<p>“I am innocent.”</p>\n<p>“Then, mademoiselle, how do you explain the circumstance laid to<br>your charge?”</p>\n<p>“Alas, monseigneur, I do not know.”</p>\n<p>“So you deny them?”</p>\n<p>“All!”</p>\n<p>“Proceed,” said Charmolue to Pierrat.</p>\n<p>Pierrat turned the handle of the screw-jack, the boot was<br>contracted, and the unhappy girl uttered one of those horrible<br>cries which have no orthography in any human language.</p>\n<p>“Stop!” said Charmolue to Pierrat. “Do you confess?” he said to<br>the gypsy.</p>\n<p>“All!” cried the wretched girl. “I confess! I confess! Mercy!”</p>\n<p>She had not calculated her strength when she faced the torture.<br>Poor child, whose life up to that time had been so joyous, so<br>pleasant, so sweet, the first pain had conquered her!</p>\n<p>“Humanity forces me to tell you,” remarked the king’s procurator,<br>“that in confessing, it is death that you must expect.”</p>\n<p>“I certainly hope so!” said she. And she fell back upon the<br>leather bed, dying, doubled up, allowing herself to hang<br>suspended from the strap buckled round her waist.</p>\n<p>“Come, fair one, hold up a little,” said Master Pierrat, raising<br>her. “You have the air of the lamb of the Golden Fleece which<br>hangs from Monsieur de Bourgogne’s neck.”</p>\n<p>Jacques Charmolue raised his voice,</p>\n<p>“Clerk, write. Young Bohemian maid, you confess your<br>participation in the feasts, witches’ sabbaths, and witchcrafts<br>of hell, with ghosts, hags, and vampires? Answer.”</p>\n<p>“Yes,” she said, so low that her words were lost in her<br>breathing.</p>\n<p>“You confess to having seen the ram which Beelzebub causes to<br>appear in the clouds to call together the witches’ sabbath, and<br>which is beheld by socerers alone?”</p>\n<p>“Yes.”</p>\n<p>“You confess to having adored the heads of Bophomet, those<br>abominable idols of the Templars?”</p>\n<p>“Yes.”</p>\n<p>“To having had habitual dealings with the devil under the form of<br>a goat familiar, joined with you in the suit?”</p>\n<p>“Yes.”</p>\n<p>“Lastly, you avow and confess to having, with the aid of the<br>demon, and of the phantom vulgarly known as the surly monk, on<br>the night of the twenty-ninth of March last, murdered and<br>assassinated a captain named Phœbus de Châteaupers?”</p>\n<p>She raised her large, staring eyes to the magistrate, and<br>replied, as though mechanically, without convulsion or<br>agitation,—</p>\n<p>“Yes.”</p>\n<p>It was evident that everything within her was broken.</p>\n<p>“Write, clerk,” said Charmolue. And, addressing the torturers,<br>“Release the prisoner, and take her back to the court.”</p>\n<p>When the prisoner had been “unbooted,” the procurator of the<br>ecclesiastical court examined her foot, which was still swollen<br>with pain. “Come,” said he, “there’s no great harm done. You<br>shrieked in good season. You could still dance, my beauty!”</p>\n<p>Then he turned to his acolytes of the officiality,—</p>\n<p>“Behold justice enlightened at last! This is a solace, gentlemen!<br>Madamoiselle will bear us witness that we have acted with all<br>possible gentleness.”</p>\n<h1 class=\"chapter\" id=\"chapter-iii-end-of-the-crown-which-was-turned-in\">Chapter III. END OF THE CROWN WHICH WAS TURNED INTO A DRY LEAF.</h1>\n<p>When she re-entered the audience hall, pale and limping, she was<br>received with a general murmur of pleasure. On the part of the<br>audience there was the feeling of impatience gratified which one<br>experiences at the theatre at the end of the last entr’acte of<br>the comedy, when the curtain rises and the conclusion is about to<br>begin. On the part of the judges, it was the hope of getting<br>their suppers sooner.</p>\n<p>The little goat also bleated with joy. He tried to run towards<br>his mistress, but they had tied him to the bench.</p>\n<p>Night was fully set in. The candles, whose number had not been<br>increased, cast so little light, that the walls of the hall could<br>not be seen. The shadows there enveloped all objects in a sort of<br>mist. A few apathetic faces of judges alone could be dimly<br>discerned. Opposite them, at the extremity of the long hall, they<br>could see a vaguely white point standing out against the sombre<br>background. This was the accused.</p>\n<p>She had dragged herself to her place. When Charmolue had<br>installed himself in a magisterial manner in his own, he seated<br>himself, then rose and said, without exhibiting too much<br>self-complacency at his success,—“The accused has confessed all.”</p>\n<p>“Bohemian girl,” the president continued, “have you avowed all<br>your deeds of magic, prostitution, and assassination on Phœbus de<br>Châteaupers.”</p>\n<p>Her heart contracted. She was heard to sob amid the darkness.</p>\n<p>“Anything you like,” she replied feebly, “but kill me quickly!”</p>\n<p>“Monsieur, procurator of the king in the ecclesiastical courts,”<br>said the president, “the chamber is ready to hear you in your<br>charge.”</p>\n<p>Master Charmolue exhibited an alarming note book, and began to<br>read, with many gestures and the exaggerated accentuation of the<br>pleader, an oration in Latin, wherein all the proofs of the suit<br>were piled up in Ciceronian periphrases, flanked with quotations<br>from Plautus, his favorite comic author. We regret that we are<br>not able to offer to our readers this remarkable piece. The<br>orator pronounced it with marvellous action. Before he had<br>finished the exordium, the perspiration was starting from his<br>brow, and his eyes from his head.</p>\n<p>All at once, in the middle of a fine period, he interrupted<br>himself, and his glance, ordinarily so gentle and even stupid,<br>became menacing.</p>\n<p>“Gentlemen,” he exclaimed (this time in French, for it was not in<br>his copy book), “Satan is so mixed up in this affair, that here<br>he is present at our debates, and making sport of their majesty.<br>Behold!”</p>\n<p>So saying, he pointed to the little goat, who, on seeing<br>Charmolue gesticulating, had, in point of fact, thought it<br>appropriate to do the same, and had seated himself on his<br>haunches, reproducing to the best of his ability, with his<br>forepaws and his bearded head the pathetic pantomine of the<br>king’s procurator in the ecclesiastical court. This was, if the<br>reader remembers, one of his prettiest accomplishments. This<br>incident, this last proof, produced a great effect. The goat’s<br>hoofs were tied, and the king’s procurator resumed the thread of<br>his eloquence.</p>\n<p>It was very long, but the peroration was admirable. Here is the<br>concluding phrase; let the reader add the hoarse voice and the<br>breathless gestures of Master Charmolue,</p>\n<p>“_Ideo, domni, coram stryga demonstrata, crimine patente,<br>intentione criminis existente, in nomine sanctæ ecclesiæ<br>Nostræ-Dominæ Parisiensis quæ est in saisina habendi omnimodam<br>altam et bassam justitiam in illa hac intemerata Civitatis<br>insula, tenore præsentium declaremus nos requirere, primo,<br>aliquamdam pecuniariam indemnitatem; secundo, amendationem<br>honorabilem ante portalium maximum Nostræ-Dominæ, ecclesiæ<br>cathedralis; tertio, sententiam in virtute cujus ista styrga cum<br>sua capella, seu in trivio vulgariter dicto<em> la Grève, </em>seu in<br>insula exeunte in fluvio Secanæ, juxta pointam juardini regalis,<br>executatæ sint!_”[45]</p>\n<p>He put on his cap again and seated himself.</p>\n<p>“<em>Eheu!</em>” sighed the broken-hearted Gringoire, “_bassa<br>latinitas_—bastard latin!”</p>\n<p>Another man in a black gown rose near the accused; he was her<br>lawyer. The judges, who were fasting, began to grumble.</p>\n<p>“Advocate, be brief,” said the president.</p>\n<p>“Monsieur the President,” replied the advocate, “since the<br>defendant has confessed the crime, I have only one word to say to<br>these gentlemen. Here is a text from the Salic law; ‘If a witch<br>hath eaten a man, and if she be convicted of it, she shall pay a<br>fine of eight thousand deniers, which amount to two hundred sous<br>of gold.’ May it please the chamber to condemn my client to the<br>fine?”</p>\n<p>“An abrogated text,” said the advocate extraordinary of the king.</p>\n<p>“<em>Nego</em>, I deny it,” replied the advocate.</p>\n<p>“Put it to the vote!” said one of the councillors; “the crime is<br>manifest, and it is late.”</p>\n<p>They proceeded to take a vote without leaving the room. The<br>judges signified their assent without giving their reasons, they<br>were in a hurry. Their capped heads were seen uncovering one<br>after the other, in the gloom, at the lugubrious question<br>addressed to them by the president in a low voice. The poor<br>accused had the appearance of looking at them, but her troubled<br>eye no longer saw.</p>\n<p>Then the clerk began to write; then he handed a long parchment to<br>the president.</p>\n<p>Then the unhappy girl heard the people moving, the pikes<br>clashing, and a freezing voice saying to her,—</p>\n<p>“Bohemian wench, on the day when it shall seem good to our lord<br>the king, at the hour of noon, you will be taken in a tumbrel, in<br>your shift, with bare feet, and a rope about your neck, before<br>the grand portal of Notre-Dame, and you will there make an<br>apology with a wax torch of the weight of two pounds in your<br>hand, and thence you will be conducted to the Place de Grève,<br>where you will be hanged and strangled on the town gibbet; and<br>likewise your goat; and you will pay to the official three lions<br>of gold, in reparation of the crimes by you committed and by you<br>confessed, of sorcery and magic, debauchery and murder, upon the<br>person of the Sieur Phœbus de Châteaupers. May God have mercy on<br>your soul!”</p>\n<p>“Oh! ’tis a dream!” she murmured; and she felt rough hands<br>bearing her away.</p>\n<h1 class=\"chapter\" id=\"chapter-iv-lasciate-ogni-speranza-leave-all-hope\">Chapter IV. _LASCIATE OGNI SPERANZA_—LEAVE ALL HOPE BEHIND, YE</h1>\n<p>WHO ENTER HERE.</p>\n<p>In the Middle Ages, when an edifice was complete, there was<br>almost as much of it in the earth as above it. Unless built upon<br>piles, like Notre-Dame, a palace, a fortress, a church, had<br>always a double bottom. In cathedrals, it was, in some sort,<br>another subterranean cathedral, low, dark, mysterious, blind, and<br>mute, under the upper nave which was overflowing with light and<br>reverberating with organs and bells day and night. Sometimes it<br>was a sepulchre. In palaces, in fortresses, it was a prison,<br>sometimes a sepulchre also, sometimes both together. These mighty<br>buildings, whose mode of formation and <em>vegetation</em> we have<br>elsewhere explained, had not simply <em>foundations</em>, but, so to<br>speak, roots which ran branching through the soil in chambers,<br>galleries, and staircases, like the construction above. Thus<br>churches, palaces, fortresses, had the earth half way up their<br>bodies. The cellars of an edifice formed another edifice, into<br>which one descended instead of ascending, and which extended its<br>subterranean grounds under the external piles of the monument,<br>like those forests and mountains which are reversed in the<br>mirror-like waters of a lake, beneath the forests and mountains<br>of the banks.</p>\n<p>At the fortress of Saint-Antoine, at the Palais de Justice of<br>Paris, at the Louvre, these subterranean edifices were prisons.<br>The stories of these prisons, as they sank into the soil, grew<br>constantly narrower and more gloomy. They were so many zones,<br>where the shades of horror were graduated. Dante could never<br>imagine anything better for his hell. These tunnels of cells<br>usually terminated in a sack of a lowest dungeon, with a vat-like<br>bottom, where Dante placed Satan, where society placed those<br>condemned to death. A miserable human existence, once interred<br>there; farewell light, air, life, <em>ogni speranza</em>—every hope; it<br>only came forth to the scaffold or the stake. Sometimes it rotted<br>there; human justice called this <em>forgetting</em>. Between men and<br>himself, the condemned man felt a pile of stones and jailers<br>weighing down upon his head; and the entire prison, the massive<br>bastille was nothing more than an enormous, complicated lock,<br>which barred him off from the rest of the world.</p>\n<p>It was in a sloping cavity of this description, in the<br><em>oubliettes</em> excavated by Saint-Louis, in the <em>inpace</em> of the<br>Tournelle, that la Esmeralda had been placed on being condemned<br>to death, through fear of her escape, no doubt, with the colossal<br>court-house over her head. Poor fly, who could not have lifted<br>even one of its blocks of stone!</p>\n<p>Assuredly, Providence and society had been equally unjust; such<br>an excess of unhappiness and of torture was not necessary to<br>break so frail a creature.</p>\n<p>There she lay, lost in the shadows, buried, hidden, immured. Any<br>one who could have beheld her in this state, after having seen<br>her laugh and dance in the sun, would have shuddered. Cold as<br>night, cold as death, not a breath of air in her tresses, not a<br>human sound in her ear, no longer a ray of light in her eyes;<br>snapped in twain, crushed with chains, crouching beside a jug and<br>a loaf, on a little straw, in a pool of water, which was formed<br>under her by the sweating of the prison walls; without motion,<br>almost without breath, she had no longer the power to suffer;<br>Phœbus, the sun, midday, the open air, the streets of Paris, the<br>dances with applause, the sweet babblings of love with the<br>officer; then the priest, the old crone, the poignard, the blood,<br>the torture, the gibbet; all this did, indeed, pass before her<br>mind, sometimes as a charming and golden vision, sometimes as a<br>hideous nightmare; but it was no longer anything but a vague and<br>horrible struggle, lost in the gloom, or distant music played up<br>above ground, and which was no longer audible at the depth where<br>the unhappy girl had fallen.</p>\n<p>Since she had been there, she had neither waked nor slept. In<br>that misfortune, in that cell, she could no longer distinguish<br>her waking hours from slumber, dreams from reality, any more than<br>day from night. All this was mixed, broken, floating,<br>disseminated confusedly in her thought. She no longer felt, she<br>no longer knew, she no longer thought; at the most, she only<br>dreamed. Never had a living creature been thrust more deeply into<br>nothingness.</p>\n<p>Thus benumbed, frozen, petrified, she had barely noticed on two<br>or three occasions, the sound of a trapdoor opening somewhere<br>above her, without even permitting the passage of a little light,<br>and through which a hand had tossed her a bit of black bread.<br>Nevertheless, this periodical visit of the jailer was the sole<br>communication which was left her with mankind.</p>\n<p>A single thing still mechanically occupied her ear; above her<br>head, the dampness was filtering through the mouldy stones of the<br>vault, and a drop of water dropped from them at regular<br>intervals. She listened stupidly to the noise made by this drop<br>of water as it fell into the pool beside her.</p>\n<p>This drop of water falling from time to time into that pool, was<br>the only movement which still went on around her, the only clock<br>which marked the time, the only noise which reached her of all<br>the noise made on the surface of the earth.</p>\n<p>To tell the whole, however, she also felt, from time to time, in<br>that cesspool of mire and darkness, something cold passing over<br>her foot or her arm, and she shuddered.</p>\n<p>How long had she been there? She did not know. She had a<br>recollection of a sentence of death pronounced somewhere, against<br>some one, then of having been herself carried away, and of waking<br>up in darkness and silence, chilled to the heart. She had dragged<br>herself along on her hands. Then iron rings that cut her ankles,<br>and chains had rattled. She had recognized the fact that all<br>around her was wall, that below her there was a pavement covered<br>with moisture and a truss of straw; but neither lamp nor<br>air-hole. Then she had seated herself on that straw and,<br>sometimes, for the sake of changing her attitude, on the last<br>stone step in her dungeon. For a while she had tried to count the<br>black minutes measured off for her by the drop of water; but that<br>melancholy labor of an ailing brain had broken off of itself in<br>her head, and had left her in stupor.</p>\n<p>At length, one day, or one night, (for midnight and midday were<br>of the same color in that sepulchre), she heard above her a<br>louder noise than was usually made by the turnkey when he brought<br>her bread and jug of water. She raised her head, and beheld a ray<br>of reddish light passing through the crevices in the sort of<br>trapdoor contrived in the roof of the <em>inpace</em>.</p>\n<p>At the same time, the heavy lock creaked, the trap grated on its<br>rusty hinges, turned, and she beheld a lantern, a hand, and the<br>lower portions of the bodies of two men, the door being too low<br>to admit of her seeing their heads. The light pained her so<br>acutely that she shut her eyes.</p>\n<p>When she opened them again the door was closed, the lantern was<br>deposited on one of the steps of the staircase; a man alone stood<br>before her. A monk’s black cloak fell to his feet, a cowl of the<br>same color concealed his face. Nothing was visible of his person,<br>neither face nor hands. It was a long, black shroud standing<br>erect, and beneath which something could be felt moving. She<br>gazed fixedly for several minutes at this sort of spectre. But<br>neither he nor she spoke. One would have pronounced them two<br>statues confronting each other. Two things only seemed alive in<br>that cavern; the wick of the lantern, which sputtered on account<br>of the dampness of the atmosphere, and the drop of water from the<br>roof, which cut this irregular sputtering with its monotonous<br>splash, and made the light of the lantern quiver in concentric<br>waves on the oily water of the pool.</p>\n<p>At last the prisoner broke the silence.</p>\n<p>“Who are you?”</p>\n<p>“A priest.”</p>\n<p>The words, the accent, the sound of his voice made her tremble.</p>\n<p>The priest continued, in a hollow voice,—</p>\n<p>“Are you prepared?”</p>\n<p>“For what?”</p>\n<p>“To die.”</p>\n<p>“Oh!” said she, “will it be soon?”</p>\n<p>“To-morrow.”</p>\n<p>Her head, which had been raised with joy, fell back upon her<br>breast.</p>\n<p>“’Tis very far away yet!” she murmured; “why could they not have<br>done it to-day?”</p>\n<p>“Then you are very unhappy?” asked the priest, after a silence.</p>\n<p>“I am very cold,” she replied.</p>\n<p>She took her feet in her hands, a gesture habitual with unhappy<br>wretches who are cold, as we have already seen in the case of the<br>recluse of the Tour-Roland, and her teeth chattered.</p>\n<p>The priest appeared to cast his eyes around the dungeon from<br>beneath his cowl.</p>\n<p>“Without light! without fire! in the water! it is horrible!”</p>\n<p>“Yes,” she replied, with the bewildered air which unhappiness had<br>given her. “The day belongs to every one, why do they give me<br>only night?”</p>\n<p>“Do you know,” resumed the priest, after a fresh silence, “why<br>you are here?”</p>\n<p>“I thought I knew once,” she said, passing her thin fingers over<br>her eyelids, as though to aid her memory, “but I know no longer.”</p>\n<p>All at once she began to weep like a child.</p>\n<p>“I should like to get away from here, sir. I am cold, I am<br>afraid, and there are creatures which crawl over my body.”</p>\n<p>“Well, follow me.”</p>\n<p>So saying, the priest took her arm. The unhappy girl was frozen<br>to her very soul. Yet that hand produced an impression of cold<br>upon her.</p>\n<p>“Oh!” she murmured, “’tis the icy hand of death. Who are you?”</p>\n<p>The priest threw back his cowl; she looked. It was the sinister<br>visage which had so long pursued her; that demon’s head which had<br>appeared at la Falourdel’s, above the head of her adored Phœbus;<br>that eye which she last had seen glittering beside a dagger.</p>\n<p>This apparition, always so fatal for her, and which had thus<br>driven her on from misfortune to misfortune, even to torture,<br>roused her from her stupor. It seemed to her that the sort of<br>veil which had lain thick upon her memory was rent away. All the<br>details of her melancholy adventure, from the nocturnal scene at<br>la Falourdel’s to her condemnation to the Tournelle, recurred to<br>her memory, no longer vague and confused as heretofore, but<br>distinct, harsh, clear, palpitating, terrible. These souvenirs,<br>half effaced and almost obliterated by excess of suffering, were<br>revived by the sombre figure which stood before her, as the<br>approach of fire causes letters traced upon white paper with<br>invisible ink, to start out perfectly fresh. It seemed to her<br>that all the wounds of her heart opened and bled simultaneously.</p>\n<p>“Hah!” she cried, with her hands on her eyes, and a convulsive<br>trembling, “’tis the priest!”</p>\n<p>Then she dropped her arms in discouragement, and remained seated,<br>with lowered head, eyes fixed on the ground, mute and still<br>trembling.</p>\n<p>The priest gazed at her with the eye of a hawk which has long<br>been soaring in a circle from the heights of heaven over a poor<br>lark cowering in the wheat, and has long been silently<br>contracting the formidable circles of his flight, and has<br>suddenly swooped down upon his prey like a flash of lightning,<br>and holds it panting in his talons.</p>\n<p>She began to murmur in a low voice,—</p>\n<p>“Finish! finish! the last blow!” and she drew her head down in<br>terror between her shoulders, like the lamb awaiting the blow of<br>the butcher’s axe.</p>\n<p>“So I inspire you with horror?” he said at length.</p>\n<p>She made no reply.</p>\n<p>“Do I inspire you with horror?” he repeated.</p>\n<p>Her lips contracted, as though with a smile.</p>\n<p>“Yes,” said she, “the headsman scoffs at the condemned. Here he<br>has been pursuing me, threatening me, terrifying me for months!<br>Had it not been for him, my God, how happy it should have been!<br>It was he who cast me into this abyss! Oh heavens! it was he who<br>killed him! my Phœbus!”</p>\n<p>Here, bursting into sobs, and raising her eyes to the priest,—</p>\n<p>“Oh! wretch, who are you? What have I done to you? Do you then,<br>hate me so? Alas! what have you against me?”</p>\n<p>“I love thee!” cried the priest.</p>\n<p>Her tears suddenly ceased, she gazed at him with the look of an<br>idiot. He had fallen on his knees and was devouring her with eyes<br>of flame.</p>\n<p>“Dost thou understand? I love thee!” he cried again.</p>\n<p>“What love!” said the unhappy girl with a shudder.</p>\n<p>He resumed,—</p>\n<p>“The love of a damned soul.”</p>\n<p>Both remained silent for several minutes, crushed beneath the<br>weight of their emotions; he maddened, she stupefied.</p>\n<p>“Listen,” said the priest at last, and a singular calm had come<br>over him; “you shall know all I am about to tell you that which I<br>have hitherto hardly dared to say to myself, when furtively<br>interrogating my conscience at those deep hours of the night when<br>it is so dark that it seems as though God no longer saw us.<br>Listen. Before I knew you, young girl, I was happy.”</p>\n<p>“So was I!” she sighed feebly.</p>\n<p>“Do not interrupt me. Yes, I was happy, at least I believed<br>myself to be so. I was pure, my soul was filled with limpid<br>light. No head was raised more proudly and more radiantly than<br>mine. Priests consulted me on chastity; doctors, on doctrines.<br>Yes, science was all in all to me; it was a sister to me, and a<br>sister sufficed. Not but that with age other ideas came to me.<br>More than once my flesh had been moved as a woman’s form passed<br>by. That force of sex and blood which, in the madness of youth, I<br>had imagined that I had stifled forever had, more than once,<br>convulsively raised the chain of iron vows which bind me, a<br>miserable wretch, to the cold stones of the altar. But fasting,<br>prayer, study, the mortifications of the cloister, rendered my<br>soul mistress of my body once more, and then I avoided women.<br>Moreover, I had but to open a book, and all the impure mists of<br>my brain vanished before the splendors of science. In a few<br>moments, I felt the gross things of earth flee far away, and I<br>found myself once more calm, quieted, and serene, in the presence<br>of the tranquil radiance of eternal truth. As long as the demon<br>sent to attack me only vague shadows of women who passed<br>occasionally before my eyes in church, in the streets, in the<br>fields, and who hardly recurred to my dreams, I easily vanquished<br>him. Alas! if the victory has not remained with me, it is the<br>fault of God, who has not created man and the demon of equal<br>force. Listen. One day—”</p>\n<p>Here the priest paused, and the prisoner heard sighs of anguish<br>break from his breast with a sound of the death rattle.</p>\n<p>He resumed,—</p>\n<p>“One day I was leaning on the window of my cell. What book was I<br>reading then? Oh! all that is a whirlwind in my head. I was<br>reading. The window opened upon a Square. I heard a sound of<br>tambourine and music. Annoyed at being thus disturbed in my<br>revery, I glanced into the Square. What I beheld, others saw<br>beside myself, and yet it was not a spectacle made for human<br>eyes. There, in the middle of the pavement,—it was midday, the<br>sun was shining brightly,—a creature was dancing. A creature so<br>beautiful that God would have preferred her to the Virgin and<br>have chosen her for his mother and have wished to be born of her<br>if she had been in existence when he was made man! Her eyes were<br>black and splendid; in the midst of her black locks, some hairs<br>through which the sun shone glistened like threads of gold. Her<br>feet disappeared in their movements like the spokes of a rapidly<br>turning wheel. Around her head, in her black tresses, there were<br>disks of metal, which glittered in the sun, and formed a coronet<br>of stars on her brow. Her dress thick set with spangles, blue,<br>and dotted with a thousand sparks, gleamed like a summer night.<br>Her brown, supple arms twined and untwined around her waist, like<br>two scarfs. The form of her body was surprisingly beautiful. Oh!<br>what a resplendent figure stood out, like something luminous even<br>in the sunlight! Alas, young girl, it was thou! Surprised,<br>intoxicated, charmed, I allowed myself to gaze upon thee. I<br>looked so long that I suddenly shuddered with terror; I felt that<br>fate was seizing hold of me.”</p>\n<p>The priest paused for a moment, overcome with emotion. Then he<br>continued,—</p>\n<p>“Already half fascinated, I tried to cling fast to something and<br>hold myself back from falling. I recalled the snares which Satan<br>had already set for me. The creature before my eyes possessed<br>that superhuman beauty which can come only from heaven or hell.<br>It was no simple girl made with a little of our earth, and dimly<br>lighted within by the vacillating ray of a woman’s soul. It was<br>an angel! but of shadows and flame, and not of light. At the<br>moment when I was meditating thus, I beheld beside you a goat, a<br>beast of witches, which smiled as it gazed at me. The midday sun<br>gave him golden horns. Then I perceived the snare of the demon,<br>and I no longer doubted that you had come from hell and that you<br>had come thence for my perdition. I believed it.”</p>\n<p>Here the priest looked the prisoner full in the face, and added,<br>coldly,—</p>\n<p>“I believe it still. Nevertheless, the charm operated little by<br>little; your dancing whirled through my brain; I felt the<br>mysterious spell working within me. All that should have awakened<br>was lulled to sleep; and like those who die in the snow, I felt<br>pleasure in allowing this sleep to draw on. All at once, you<br>began to sing. What could I do, unhappy wretch? Your song was<br>still more charming than your dancing. I tried to flee.<br>Impossible. I was nailed, rooted to the spot. It seemed to me<br>that the marble of the pavement had risen to my knees. I was<br>forced to remain until the end. My feet were like ice, my head<br>was on fire. At last you took pity on me, you ceased to sing, you<br>disappeared. The reflection of the dazzling vision, the<br>reverberation of the enchanting music disappeared by degrees from<br>my eyes and my ears. Then I fell back into the embrasure of the<br>window, more rigid, more feeble than a statue torn from its base.<br>The vesper bell roused me. I drew myself up; I fled; but alas!<br>something within me had fallen never to rise again, something had<br>come upon me from which I could not flee.”</p>\n<p>He made another pause and went on,—</p>\n<p>“Yes, dating from that day, there was within me a man whom I did<br>not know. I tried to make use of all my remedies. The cloister,<br>the altar, work, books,—follies! Oh, how hollow does science<br>sound when one in despair dashes against it a head full of<br>passions! Do you know, young girl, what I saw thenceforth between<br>my book and me? You, your shade, the image of the luminous<br>apparition which had one day crossed the space before me. But<br>this image had no longer the same color; it was sombre, funereal,<br>gloomy as the black circle which long pursues the vision of the<br>imprudent man who has gazed intently at the sun.</p>\n<p>“Unable to rid myself of it, since I heard your song humming ever<br>in my head, beheld your feet dancing always on my breviary, felt<br>even at night, in my dreams, your form in contact with my own, I<br>desired to see you again, to touch you, to know who you were, to<br>see whether I should really find you like the ideal image which I<br>had retained of you, to shatter my dream, perchance, with<br>reality. At all events, I hoped that a new impression would<br>efface the first, and the first had become insupportable. I<br>sought you. I saw you once more. Calamity! When I had seen you<br>twice, I wanted to see you a thousand times, I wanted to see you<br>always. Then—how stop myself on that slope of hell?—then I no<br>longer belonged to myself. The other end of the thread which the<br>demon had attached to my wings he had fastened to his foot. I<br>became vagrant and wandering like yourself. I waited for you<br>under porches, I stood on the lookout for you at the street<br>corners, I watched for you from the summit of my tower. Every<br>evening I returned to myself more charmed, more despairing, more<br>bewitched, more lost!</p>\n<p>“I had learned who you were; an Egyptian, Bohemian, gypsy,<br>zingara. How could I doubt the magic? Listen. I hoped that a<br>trial would free me from the charm. A witch enchanted Bruno<br>d’Ast; he had her burned, and was cured. I knew it. I wanted to<br>try the remedy. First I tried to have you forbidden the square in<br>front of Notre-Dame, hoping to forget you if you returned no<br>more. You paid no heed to it. You returned. Then the idea of<br>abducting you occurred to me. One night I made the attempt. There<br>were two of us. We already had you in our power, when that<br>miserable officer came up. He delivered you. Thus did he begin<br>your unhappiness, mine, and his own. Finally, no longer knowing<br>what to do, and what was to become of me, I denounced you to the<br>official.</p>\n<p>“I thought that I should be cured like Bruno d’Ast. I also had a<br>confused idea that a trial would deliver you into my hands; that,<br>as a prisoner I should hold you, I should have you; that there<br>you could not escape from me; that you had already possessed me a<br>sufficiently long time to give me the right to possess you in my<br>turn. When one does wrong, one must do it thoroughly. ’Tis<br>madness to halt midway in the monstrous! The extreme of crime has<br>its deliriums of joy. A priest and a witch can mingle in delight<br>upon the truss of straw in a dungeon!</p>\n<p>“Accordingly, I denounced you. It was then that I terrified you<br>when we met. The plot which I was weaving against you, the storm<br>which I was heaping up above your head, burst from me in threats<br>and lightning glances. Still, I hesitated. My project had its<br>terrible sides which made me shrink back.</p>\n<p>“Perhaps I might have renounced it; perhaps my hideous thought<br>would have withered in my brain, without bearing fruit. I thought<br>that it would always depend upon me to follow up or discontinue<br>this prosecution. But every evil thought is inexorable, and<br>insists on becoming a deed; but where I believed myself to be all<br>powerful, fate was more powerful than I. Alas! ’tis fate which<br>has seized you and delivered you to the terrible wheels of the<br>machine which I had constructed doubly. Listen. I am nearing the<br>end.</p>\n<p>“One day,—again the sun was shining brilliantly—I behold a man<br>pass me uttering your name and laughing, who carries sensuality<br>in his eyes. Damnation! I followed him; you know the rest.”</p>\n<p>He ceased.</p>\n<p>The young girl could find but one word:</p>\n<p>“Oh, my Phœbus!”</p>\n<p>“Not that name!” said the priest, grasping her arm violently.<br>“Utter not that name! Oh! miserable wretches that we are, ’tis<br>that name which has ruined us! or, rather we have ruined each<br>other by the inexplicable play of fate! you are suffering, are<br>you not? you are cold; the night makes you blind, the dungeon<br>envelops you; but perhaps you still have some light in the bottom<br>of your soul, were it only your childish love for that empty man<br>who played with your heart, while I bear the dungeon within me;<br>within me there is winter, ice, despair; I have night in my soul.</p>\n<p>“Do you know what I have suffered? I was present at your trial. I<br>was seated on the official’s bench. Yes, under one of the<br>priests’ cowls, there were the contortions of the damned. When<br>you were brought in, I was there; when you were questioned, I was<br>there.—Den of wolves!—It was my crime, it was my gallows that I<br>beheld being slowly reared over your head. I was there for every<br>witness, every proof, every plea; I could count each of your<br>steps in the painful path; I was still there when that ferocious<br>beast—oh! I had not foreseen torture! Listen. I followed you to<br>that chamber of anguish. I beheld you stripped and handled, half<br>naked, by the infamous hands of the tormentor. I beheld your<br>foot, that foot which I would have given an empire to kiss and<br>die, that foot, beneath which to have had my head crushed I<br>should have felt such rapture,—I beheld it encased in that<br>horrible boot, which converts the limbs of a living being into<br>one bloody clod. Oh, wretch! while I looked on at that, I held<br>beneath my shroud a dagger, with which I lacerated my breast.<br>When you uttered that cry, I plunged it into my flesh; at a<br>second cry, it would have entered my heart. Look! I believe that<br>it still bleeds.”</p>\n<p>He opened his cassock. His breast was in fact, mangled as by the<br>claw of a tiger, and on his side he had a large and badly healed<br>wound.</p>\n<p>The prisoner recoiled with horror.</p>\n<p>“Oh!” said the priest, “young girl, have pity upon me! You think<br>yourself unhappy; alas! alas! you know not what unhappiness is.<br>Oh! to love a woman! to be a priest! to be hated! to love with<br>all the fury of one’s soul; to feel that one would give for the<br>least of her smiles, one’s blood, one’s vitals, one’s fame, one’s<br>salvation, one’s immortality and eternity, this life and the<br>other; to regret that one is not a king, emperor, archangel, God,<br>in order that one might place a greater slave beneath her feet;<br>to clasp her night and day in one’s dreams and one’s thoughts,<br>and to behold her in love with the trappings of a soldier and to<br>have nothing to offer her but a priest’s dirty cassock, which<br>will inspire her with fear and disgust! To be present with one’s<br>jealousy and one’s rage, while she lavishes on a miserable,<br>blustering imbecile, treasures of love and beauty! To behold that<br>body whose form burns you, that bosom which possesses so much<br>sweetness, that flesh palpitate and blush beneath the kisses of<br>another! Oh heaven! to love her foot, her arm, her shoulder, to<br>think of her blue veins, of her brown skin, until one writhes for<br>whole nights together on the pavement of one’s cell, and to<br>behold all those caresses which one has dreamed of, end in<br>torture! To have succeeded only in stretching her upon the<br>leather bed! Oh! these are the veritable pincers, reddened in the<br>fires of hell. Oh! blessed is he who is sawn between two planks,<br>or torn in pieces by four horses! Do you know what that torture<br>is, which is imposed upon you for long nights by your burning<br>arteries, your bursting heart, your breaking head, your<br>teeth-knawed hands; mad tormentors which turn you incessantly, as<br>upon a red-hot gridiron, to a thought of love, of jealousy, and<br>of despair! Young girl, mercy! a truce for a moment! a few ashes<br>on these live coals! Wipe away, I beseech you, the perspiration<br>which trickles in great drops from my brow! Child! torture me<br>with one hand, but caress me with the other! Have pity, young<br>girl! Have pity upon me!”</p>\n<p>The priest writhed on the wet pavement, beating his head against<br>the corners of the stone steps. The young girl gazed at him, and<br>listened to him.</p>\n<p>When he ceased, exhausted and panting, she repeated in a low<br>voice,—</p>\n<p>“Oh my Phœbus!”</p>\n<p>The priest dragged himself towards her on his knees.</p>\n<p>“I beseech you,” he cried, “if you have any heart, do not repulse<br>me! Oh! I love you! I am a wretch! When you utter that name,<br>unhappy girl, it is as though you crushed all the fibres of my<br>heart between your teeth. Mercy! If you come from hell I will go<br>thither with you. I have done everything to that end. The hell<br>where you are, shall be paradise; the sight of you is more<br>charming than that of God! Oh! speak! you will have none of me? I<br>should have thought the mountains would be shaken in their<br>foundations on the day when a woman would repulse such a love.<br>Oh! if you only would! Oh! how happy we might be. We would flee—I<br>would help you to flee,—we would go somewhere, we would seek that<br>spot on earth, where the sun is brightest, the sky the bluest,<br>where the trees are most luxuriant. We would love each other, we<br>would pour our two souls into each other, and we would have a<br>thirst for ourselves which we would quench in common and<br>incessantly at that fountain of inexhaustible love.”</p>\n<p>She interrupted with a terrible and thrilling laugh.</p>\n<p>“Look, father, you have blood on your fingers!”</p>\n<p>The priest remained for several moments as though petrified, with<br>his eyes fixed upon his hand.</p>\n<p>“Well, yes!” he resumed at last, with strange gentleness, “insult<br>me, scoff at me, overwhelm me with scorn! but come, come. Let us<br>make haste. It is to be to-morrow, I tell you. The gibbet on the<br>Grève, you know it? it stands always ready. It is horrible! to<br>see you ride in that tumbrel! Oh mercy! Until now I have never<br>felt the power of my love for you.—Oh! follow me. You shall take<br>your time to love me after I have saved you. You shall hate me as<br>long as you will. But come. To-morrow! to-morrow! the gallows!<br>your execution! Oh! save yourself! spare me!”</p>\n<p>He seized her arm, he was beside himself, he tried to drag her<br>away.</p>\n<p>She fixed her eye intently on him.</p>\n<p>“What has become of my Phœbus?”</p>\n<p>“Ah!” said the priest, releasing her arm, “you are pitiless.”</p>\n<p>“What has become of Phœbus?” she repeated coldly.</p>\n<p>“He is dead!” cried the priest.</p>\n<p>“Dead!” said she, still icy and motionless “then why do you talk<br>to me of living?”</p>\n<p>He was not listening to her.</p>\n<p>“Oh! yes,” said he, as though speaking to himself, “he certainly<br>must be dead. The blade pierced deeply. I believe I touched his<br>heart with the point. Oh! my very soul was at the end of the<br>dagger!”</p>\n<p>The young girl flung herself upon him like a raging tigress, and<br>pushed him upon the steps of the staircase with supernatural<br>force.</p>\n<p>“Begone, monster! Begone, assassin! Leave me to die! May the<br>blood of both of us make an eternal stain upon your brow! Be<br>thine, priest! Never! never! Nothing shall unite us! not hell<br>itself! Go, accursed man! Never!”</p>\n<p>The priest had stumbled on the stairs. He silently disentangled<br>his feet from the folds of his robe, picked up his lantern again,<br>and slowly began the ascent of the steps which led to the door;<br>he opened the door and passed through it.</p>\n<p>All at once, the young girl beheld his head reappear; it wore a<br>frightful expression, and he cried, hoarse with rage and<br>despair,—</p>\n<p>“I tell you he is dead!”</p>\n<p>She fell face downwards upon the floor, and there was no longer<br>any sound audible in the cell than the sob of the drop of water<br>which made the pool palpitate amid the darkness.</p>\n<h1 class=\"chapter\" id=\"chapter-v-the-mother\">Chapter V. THE MOTHER.</h1>\n<p>I do not believe that there is anything sweeter in the world than<br>the ideas which awake in a mother’s heart at the sight of her<br>child’s tiny shoe; especially if it is a shoe for festivals, for<br>Sunday, for baptism, the shoe embroidered to the very sole, a<br>shoe in which the infant has not yet taken a step. That shoe has<br>so much grace and daintiness, it is so impossible for it to walk,<br>that it seems to the mother as though she saw her child. She<br>smiles upon it, she kisses it, she talks to it; she asks herself<br>whether there can actually be a foot so tiny; and if the child be<br>absent, the pretty shoe suffices to place the sweet and fragile<br>creature before her eyes. She thinks she sees it, she does see<br>it, complete, living, joyous, with its delicate hands, its round<br>head, its pure lips, its serene eyes whose white is blue. If it<br>is in winter, it is yonder, crawling on the carpet, it is<br>laboriously climbing upon an ottoman, and the mother trembles<br>lest it should approach the fire. If it is summer time, it crawls<br>about the yard, in the garden, plucks up the grass between the<br>paving-stones, gazes innocently at the big dogs, the big horses,<br>without fear, plays with the shells, with the flowers, and makes<br>the gardener grumble because he finds sand in the flower-beds and<br>earth in the paths. Everything laughs, and shines and plays<br>around it, like it, even the breath of air and the ray of sun<br>which vie with each other in disporting among the silky ringlets<br>of its hair. The shoe shows all this to the mother, and makes her<br>heart melt as fire melts wax.</p>\n<p>But when the child is lost, these thousand images of joy, of<br>charms, of tenderness, which throng around the little shoe,<br>become so many horrible things. The pretty broidered shoe is no<br>longer anything but an instrument of torture which eternally<br>crushes the heart of the mother. It is always the same fibre<br>which vibrates, the tenderest and most sensitive; but instead of<br>an angel caressing it, it is a demon who is wrenching at it.</p>\n<p>One May morning, when the sun was rising on one of those dark<br>blue skies against which Garofolo loves to place his Descents<br>from the Cross, the recluse of the Tour-Roland heard a sound of<br>wheels, of horses and irons in the Place de Grève. She was<br>somewhat aroused by it, knotted her hair upon her ears in order<br>to deafen herself, and resumed her contemplation, on her knees,<br>of the inanimate object which she had adored for fifteen years.<br>This little shoe was the universe to her, as we have already<br>said. Her thought was shut up in it, and was destined never more<br>to quit it except at death. The sombre cave of the Tour-Roland<br>alone knew how many bitter imprecations, touching complaints,<br>prayers and sobs she had wafted to heaven in connection with that<br>charming bauble of rose-colored satin. Never was more despair<br>bestowed upon a prettier and more graceful thing.</p>\n<p>It seemed as though her grief were breaking forth more violently<br>than usual; and she could be heard outside lamenting in a loud<br>and monotonous voice which rent the heart.</p>\n<p>“Oh my daughter!” she said, “my daughter, my poor, dear little<br>child, so I shall never see thee more! It is over! It always<br>seems to me that it happened yesterday! My God! my God! it would<br>have been better not to give her to me than to take her away so<br>soon. Did you not know that our children are part of ourselves,<br>and that a mother who has lost her child no longer believes in<br>God? Ah! wretch that I am to have gone out that day! Lord! Lord!<br>to have taken her from me thus; you could never have looked at me<br>with her, when I was joyously warming her at my fire, when she<br>laughed as she suckled, when I made her tiny feet creep up my<br>breast to my lips? Oh! if you had looked at that, my God, you<br>would have taken pity on my joy; you would not have taken from me<br>the only love which lingered, in my heart! Was I then, Lord, so<br>miserable a creature, that you could not look at me before<br>condemning me?—Alas! Alas! here is the shoe; where is the foot?<br>where is the rest? Where is the child? My daughter! my daughter!<br>what did they do with thee? Lord, give her back to me. My knees<br>have been worn for fifteen years in praying to thee, my God! Is<br>not that enough? Give her back to me one day, one hour, one<br>minute; one minute, Lord! and then cast me to the demon for all<br>eternity! Oh! if I only knew where the skirt of your garment<br>trails, I would cling to it with both hands, and you would be<br>obliged to give me back my child! Have you no pity on her pretty<br>little shoe? Could you condemn a poor mother to this torture for<br>fifteen years? Good Virgin! good Virgin of heaven! my infant<br>Jesus has been taken from me, has been stolen from me; they<br>devoured her on a heath, they drank her blood, they cracked her<br>bones! Good Virgin, have pity upon me. My daughter, I want my<br>daughter! What is it to me that she is in paradise? I do not want<br>your angel, I want my child! I am a lioness, I want my whelp. Oh!<br>I will writhe on the earth, I will break the stones with my<br>forehead, and I will damn myself, and I will curse you, Lord, if<br>you keep my child from me! you see plainly that my arms are all<br>bitten, Lord! Has the good God no mercy?—Oh! give me only salt<br>and black bread, only let me have my daughter to warm me like a<br>sun! Alas! Lord my God. Alas! Lord my God, I am only a vile<br>sinner; but my daughter made me pious. I was full of religion for<br>the love of her, and I beheld you through her smile as through an<br>opening into heaven. Oh! if I could only once, just once more, a<br>single time, put this shoe on her pretty little pink foot, I<br>would die blessing you, good Virgin. Ah! fifteen years! she will<br>be grown up now!—Unhappy child! what! it is really true then I<br>shall never see her more, not even in heaven, for I shall not go<br>there myself. Oh! what misery to think that here is her shoe, and<br>that that is all!”</p>\n<p>The unhappy woman flung herself upon that shoe; her consolation<br>and her despair for so many years, and her vitals were rent with<br>sobs as on the first day; because, for a mother who has lost her<br>child, it is always the first day. That grief never grows old.<br>The mourning garments may grow white and threadbare, the heart<br>remains dark.</p>\n<p>At that moment, the fresh and joyous cries of children passed in<br>front of the cell. Every time that children crossed her vision or<br>struck her ear, the poor mother flung herself into the darkest<br>corner of her sepulchre, and one would have said, that she sought<br>to plunge her head into the stone in order not to hear them. This<br>time, on the contrary, she drew herself upright with a start, and<br>listened eagerly. One of the little boys had just said,—</p>\n<p>“They are going to hang a gypsy to-day.”</p>\n<p>With the abrupt leap of that spider which we have seen fling<br>itself upon a fly at the trembling of its web, she rushed to her<br>air-hole, which opened as the reader knows, on the Place de<br>Grève. A ladder had, in fact, been raised up against the<br>permanent gibbet, and the hangman’s assistant was busying himself<br>with adjusting the chains which had been rusted by the rain.<br>There were some people standing about.</p>\n<p>The laughing group of children was already far away. The sacked<br>nun sought with her eyes some passer-by whom she might question.<br>All at once, beside her cell, she perceived a priest making a<br>pretext of reading the public breviary, but who was much less<br>occupied with the “lectern of latticed iron,” than with the<br>gallows, toward which he cast a fierce and gloomy glance from<br>time to time. She recognized monsieur the archdeacon of Josas, a<br>holy man.</p>\n<p>“Father,” she inquired, “whom are they about to hang yonder?”</p>\n<p>The priest looked at her and made no reply; she repeated her<br>question. Then he said,—</p>\n<p>“I know not.”</p>\n<p>“Some children said that it was a gypsy,” went on the recluse.</p>\n<p>“I believe so,” said the priest.</p>\n<p>Then Paquette la Chantefleurie burst into hyena-like laughter.</p>\n<p>“Sister,” said the archdeacon, “do you then hate the gypsies<br>heartily?”</p>\n<p>“Do I hate them!” exclaimed the recluse, “they are vampires,<br>stealers of children! They devoured my little daughter, my child,<br>my only child! I have no longer any heart, they devoured it!”</p>\n<p>She was frightful. The priest looked at her coldly.</p>\n<p>“There is one in particular whom I hate, and whom I have cursed,”<br>she resumed; “it is a young one, of the age which my daughter<br>would be if her mother had not eaten my daughter. Every time that<br>that young viper passes in front of my cell, she sets my blood in<br>a ferment.”</p>\n<p>“Well, sister, rejoice,” said the priest, icy as a sepulchral<br>statue; “that is the one whom you are about to see die.”</p>\n<p>His head fell upon his bosom and he moved slowly away.</p>\n<p>The recluse writhed her arms with joy.</p>\n<p>“I predicted it for her, that she would ascend thither! Thanks,<br>priest!” she cried.</p>\n<p>And she began to pace up and down with long strides before the<br>grating of her window, her hair dishevelled, her eyes flashing,<br>with her shoulder striking against the wall, with the wild air of<br>a female wolf in a cage, who has long been famished, and who<br>feels the hour for her repast drawing near.</p>\n<h1 class=\"chapter\" id=\"chapter-vi-three-human-hearts-differently-constr\">Chapter VI. THREE HUMAN HEARTS DIFFERENTLY CONSTRUCTED.</h1>\n<p>Phœbus was not dead, however. Men of that stamp die hard. When<br>Master Philippe Lheulier, advocate extraordinary of the king, had<br>said to poor Esmeralda; “He is dying,” it was an error or a jest.<br>When the archdeacon had repeated to the condemned girl; “He is<br>dead,” the fact is that he knew nothing about it, but that he<br>believed it, that he counted on it, that he did not doubt it,<br>that he devoutly hoped it. It would have been too hard for him to<br>give favorable news of his rival to the woman whom he loved. Any<br>man would have done the same in his place.</p>\n<p>It was not that Phœbus’s wound had not been serious, but it had<br>not been as much so as the archdeacon believed. The physician, to<br>whom the soldiers of the watch had carried him at the first<br>moment, had feared for his life during the space of a week, and<br>had even told him so in Latin. But youth had gained the upper<br>hand; and, as frequently happens, in spite of prognostications<br>and diagnoses, nature had amused herself by saving the sick man<br>under the physician’s very nose. It was while he was still lying<br>on the leech’s pallet that he had submitted to the interrogations<br>of Philippe Lheulier and the official inquisitors, which had<br>annoyed him greatly. Hence, one fine morning, feeling himself<br>better, he had left his golden spurs with the leech as payment,<br>and had slipped away. This had not, however, interfered with the<br>progress of the affair. Justice, at that epoch, troubled itself<br>very little about the clearness and definiteness of a criminal<br>suit. Provided that the accused was hung, that was all that was<br>necessary. Now the judge had plenty of proofs against la<br>Esmeralda. They had supposed Phœbus to be dead, and that was the<br>end of the matter.</p>\n<p>Phœbus, on his side, had not fled far. He had simply rejoined his<br>company in garrison at Queue-en-Brie, in the Isle-de-France, a<br>few stages from Paris.</p>\n<p>After all, it did not please him in the least to appear in this<br>suit. He had a vague feeling that he should play a ridiculous<br>figure in it. On the whole, he did not know what to think of the<br>whole affair. Superstitious, and not given to devoutness, like<br>every soldier who is only a soldier, when he came to question<br>himself about this adventure, he did not feel assured as to the<br>goat, as to the singular fashion in which he had met La<br>Esmeralda, as to the no less strange manner in which she had<br>allowed him to divine her love, as to her character as a gypsy,<br>and lastly, as to the surly monk. He perceived in all these<br>incidents much more magic than love, probably a sorceress,<br>perhaps the devil; a comedy, in short, or to speak in the<br>language of that day, a very disagreeable mystery, in which he<br>played a very awkward part, the role of blows and derision. The<br>captain was quite put out of countenance about it; he experienced<br>that sort of shame which our La Fontaine has so admirably<br>defined,—</p>\n<p>Ashamed as a fox who has been caught by a fowl.</p>\n<p>Moreover, he hoped that the affair would not get noised abroad,<br>that his name would hardly be pronounced in it, and that in any<br>case it would not go beyond the courts of the Tournelle. In this<br>he was not mistaken, there was then no <em>Gazette des Tribunaux;</em><br>and as not a week passed which had not its counterfeiter to boil,<br>or its witch to hang, or its heretic to burn, at some one of the<br>innumerable justices of Paris, people were so accustomed to<br>seeing in all the squares the ancient feudal Themis, bare armed,<br>with sleeves stripped up, performing her duty at the gibbets, the<br>ladders, and the pillories, that they hardly paid any heed to it.<br>Fashionable society of that day hardly knew the name of the<br>victim who passed by at the corner of the street, and it was the<br>populace at the most who regaled themselves with this coarse<br>fare. An execution was an habitual incident of the public<br>highways, like the braising-pan of the baker or the<br>slaughter-house of the knacker. The executioner was only a sort<br>of butcher of a little deeper dye than the rest.</p>\n<p>Hence Phœbus’s mind was soon at ease on the score of the<br>enchantress Esmeralda, or Similar, as he called her, concerning<br>the blow from the dagger of the Bohemian or of the surly monk (it<br>mattered little which to him), and as to the issue of the trial.<br>But as soon as his heart was vacant in that direction,<br>Fleur-de-Lys returned to it. Captain Phœbus’s heart, like the<br>physics of that day, abhorred a vacuum.</p>\n<p>Queue-en-Brie was a very insipid place to stay at then, a village<br>of farriers, and cow-girls with chapped hands, a long line of<br>poor dwellings and thatched cottages, which borders the grand<br>road on both sides for half a league; a tail (queue), in short,<br>as its name imports.</p>\n<p>Fleur-de-Lys was his last passion but one, a pretty girl, a<br>charming dowry; accordingly, one fine morning, quite cured, and<br>assuming that, after the lapse of two months, the Bohemian affair<br>must be completely finished and forgotten, the amorous cavalier<br>arrived on a prancing horse at the door of the Gondelaurier<br>mansion.</p>\n<p>He paid no attention to a tolerably numerous rabble which had<br>assembled in the Place du Parvis, before the portal of<br>Notre-Dame; he remembered that it was the month of May; he<br>supposed that it was some procession, some Pentecost, some<br>festival, hitched his horse to the ring at the door, and gayly<br>ascended the stairs to his beautiful betrothed.</p>\n<p>She was alone with her mother.</p>\n<p>The scene of the witch, her goat, her cursed alphabet, and<br>Phœbus’s long absences, still weighed on Fleur-de-Lys’s heart.<br>Nevertheless, when she beheld her captain enter, she thought him<br>so handsome, his doublet so new, his baldrick so shining, and his<br>air so impassioned, that she blushed with pleasure. The noble<br>damsel herself was more charming than ever. Her magnificent blond<br>hair was plaited in a ravishing manner, she was dressed entirely<br>in that sky blue which becomes fair people so well, a bit of<br>coquetry which she had learned from Colombe, and her eyes were<br>swimming in that languor of love which becomes them still better.</p>\n<p>Phœbus, who had seen nothing in the line of beauty, since he left<br>the village maids of Queue-en-Brie, was intoxicated with<br>Fleur-de-Lys, which imparted to our officer so eager and gallant<br>an air, that his peace was immediately made. Madame de<br>Gondelaurier herself, still maternally seated in her big<br>arm-chair, had not the heart to scold him. As for Fleur-de-Lys’s<br>reproaches, they expired in tender cooings.</p>\n<p>The young girl was seated near the window still embroidering her<br>grotto of Neptune. The captain was leaning over the back of her<br>chair, and she was addressing her caressing reproaches to him in<br>a low voice.</p>\n<p>“What has become of you these two long months, wicked man?”</p>\n<p>“I swear to you,” replied Phœbus, somewhat embarrassed by the<br>question, “that you are beautiful enough to set an archbishop to<br>dreaming.”</p>\n<p>She could not repress a smile.</p>\n<p>“Good, good, sir. Let my beauty alone and answer my question. A<br>fine beauty, in sooth!”</p>\n<p>“Well, my dear cousin, I was recalled to the garrison.</p>\n<p>“And where is that, if you please? and why did not you come to<br>say farewell?”</p>\n<p>“At Queue-en-Brie.”</p>\n<p>Phœbus was delighted with the first question, which helped him to<br>avoid the second.</p>\n<p>“But that is quite close by, monsieur. Why did you not come to<br>see me a single time?”</p>\n<p>Here Phœbus was rather seriously embarrassed.</p>\n<p>“Because—the service—and then, charming cousin, I have been ill.”</p>\n<p>“Ill!” she repeated in alarm.</p>\n<p>“Yes, wounded!”</p>\n<p>“Wounded!”</p>\n<p>The poor child was completely upset.</p>\n<p>“Oh! do not be frightened at that,” said Phœbus, carelessly, “it<br>was nothing. A quarrel, a sword cut; what is that to you?”</p>\n<p>“What is that to me?” exclaimed Fleur-de-Lys, raising her<br>beautiful eyes filled with tears. “Oh! you do not say what you<br>think when you speak thus. What sword cut was that? I wish to<br>know all.”</p>\n<p>“Well, my dear fair one, I had a falling out with Mahé Fédy, you<br>know? the lieutenant of Saint-Germain-en-Laye, and we ripped open<br>a few inches of skin for each other. That is all.”</p>\n<p>The mendacious captain was perfectly well aware that an affair of<br>honor always makes a man stand well in the eyes of a woman. In<br>fact, Fleur-de-Lys looked him full in the face, all agitated with<br>fear, pleasure, and admiration. Still, she was not completely<br>reassured.</p>\n<p>“Provided that you are wholly cured, my Phœbus!” said she. “I do<br>not know your Mahé Fédy, but he is a villanous man. And whence<br>arose this quarrel?”</p>\n<p>Here Phœbus, whose imagination was endowed with but mediocre<br>power of creation, began to find himself in a quandary as to a<br>means of extricating himself for his prowess.</p>\n<p>“Oh! how do I know?—a mere nothing, a horse, a remark! Fair<br>cousin,” he exclaimed, for the sake of changing the conversation,<br>“what noise is this in the Cathedral Square?”</p>\n<p>He approached the window.</p>\n<p>“Oh! <em>Mon Dieu</em>, fair cousin, how many people there are on the<br>Place!”</p>\n<p>“I know not,” said Fleur-de-Lys; “it appears that a witch is to<br>do penance this morning before the church, and thereafter to be<br>hung.”</p>\n<p>The captain was so thoroughly persuaded that la Esmeralda’s<br>affair was concluded, that he was but little disturbed by<br>Fleur-de-Lys’s words. Still, he asked her one or two questions.</p>\n<p>“What is the name of this witch?”</p>\n<p>“I do not know,” she replied.</p>\n<p>“And what is she said to have done?”</p>\n<p>She shrugged her white shoulders.</p>\n<p>“I know not.”</p>\n<p>“Oh, <em>mon Dieu Jésus!</em>” said her mother; “there are so many<br>witches nowadays that I dare say they burn them without knowing<br>their names. One might as well seek the name of every cloud in<br>the sky. After all, one may be tranquil. The good God keeps his<br>register.” Here the venerable dame rose and came to the window.<br>“Good Lord! you are right, Phœbus,” said she. “The rabble is<br>indeed great. There are people on all the roofs, blessed be God!<br>Do you know, Phœbus, this reminds me of my best days. The<br>entrance of King Charles VII., when, also, there were many<br>people. I no longer remember in what year that was. When I speak<br>of this to you, it produces upon you the effect,—does it not?—the<br>effect of something very old, and upon me of something very<br>young. Oh! the crowd was far finer than at the present day. They<br>even stood upon the machicolations of the Porte Sainte-Antoine.<br>The king had the queen on a pillion, and after their highnesses<br>came all the ladies mounted behind all the lords. I remember that<br>they laughed loudly, because beside Amanyon de Garlande, who was<br>very short of stature, there rode the Sire Matefelon, a chevalier<br>of gigantic size, who had killed heaps of English. It was very<br>fine. A procession of all the gentlemen of France, with their<br>oriflammes waving red before the eye. There were some with<br>pennons and some with banners. How can I tell? the Sire de Calan<br>with a pennon; Jean de Châteaumorant with a banner; the Sire de<br>Courcy with a banner, and a more ample one than any of the others<br>except the Duc de Bourbon. Alas! ’tis a sad thing to think that<br>all that has existed and exists no longer!”</p>\n<p>The two lovers were not listening to the venerable dowager.<br>Phœbus had returned and was leaning on the back of his<br>betrothed’s chair, a charming post whence his libertine glance<br>plunged into all the openings of Fleur-de-Lys’s gorget. This<br>gorget gaped so conveniently, and allowed him to see so many<br>exquisite things and to divine so many more, that Phœbus, dazzled<br>by this skin with its gleams of satin, said to himself, “How can<br>any one love anything but a fair skin?”</p>\n<p>Both were silent. The young girl raised sweet, enraptured eyes to<br>him from time to time, and their hair mingled in a ray of spring<br>sunshine.</p>\n<p>“Phœbus,” said Fleur-de-Lys suddenly, in a low voice, “we are to<br>be married three months hence; swear to me that you have never<br>loved any other woman than myself.”</p>\n<p>“I swear it, fair angel!” replied Phœbus, and his passionate<br>glances aided the sincere tone of his voice in convincing<br>Fleur-de-Lys.</p>\n<p>Meanwhile, the good mother, charmed to see the betrothed pair on<br>terms of such perfect understanding, had just quitted the<br>apartment to attend to some domestic matter; Phœbus observed it,<br>and this so emboldened the adventurous captain that very strange<br>ideas mounted to his brain. Fleur-de-Lys loved him, he was her<br>betrothed; she was alone with him; his former taste for her had<br>re-awakened, not with all its freshness but with all its ardor;<br>after all, there is no great harm in tasting one’s wheat while it<br>is still in the blade; I do not know whether these ideas passed<br>through his mind, but one thing is certain, that Fleur-de-Lys was<br>suddenly alarmed by the expression of his glance. She looked<br>round and saw that her mother was no longer there.</p>\n<p>“Good heavens!” said she, blushing and uneasy, “how very warm I<br>am!”</p>\n<p>“I think, in fact,” replied Phœbus, “that it cannot be far from<br>midday. The sun is troublesome. We need only lower the curtains.”</p>\n<p>“No, no,” exclaimed the poor little thing, “on the contrary, I<br>need air.”</p>\n<p>And like a fawn who feels the breath of the pack of hounds, she<br>rose, ran to the window, opened it, and rushed upon the balcony.</p>\n<p>Phœbus, much discomfited, followed her.</p>\n<p>The Place du Parvis Notre-Dame, upon which the balcony looked, as<br>the reader knows, presented at that moment a singular and<br>sinister spectacle which caused the fright of the timid<br>Fleur-de-Lys to change its nature.</p>\n<p>An immense crowd, which overflowed into all the neighboring<br>streets, encumbered the Place, properly speaking. The little<br>wall, breast high, which surrounded the Place, would not have<br>sufficed to keep it free had it not been lined with a thick hedge<br>of sergeants and hackbuteers, culverines in hand. Thanks to this<br>thicket of pikes and arquebuses, the Parvis was empty. Its<br>entrance was guarded by a force of halberdiers with the armorial<br>bearings of the bishop. The large doors of the church were<br>closed, and formed a contrast with the innumerable windows on the<br>Place, which, open to their very gables, allowed a view of<br>thousands of heads heaped up almost like the piles of bullets in<br>a park of artillery.</p>\n<p>The surface of this rabble was dingy, dirty, earthy. The<br>spectacle which it was expecting was evidently one of the sort<br>which possess the privilege of bringing out and calling together<br>the vilest among the populace. Nothing is so hideous as the noise<br>which was made by that swarm of yellow caps and dirty heads. In<br>that throng there were more laughs than cries, more women than<br>men.</p>\n<p>From time to time, a sharp and vibrating voice pierced the<br>general clamor.</p>\n<p>“Ohé! Mahiet Baliffre! Is she to be hung yonder?”</p>\n<p>“Fool! ’tis here that she is to make her apology in her shift!<br>the good God is going to cough Latin in her face! That is always<br>done here, at midday. If ’tis the gallows that you wish, go to<br>the Grève.”</p>\n<p>“I will go there, afterwards.”</p>\n<p>“Tell me, la Boucanbry? Is it true that she has refused a<br>confessor?”</p>\n<p>“It appears so, La Bechaigne.”</p>\n<p>“You see what a pagan she is!”</p>\n<p>“’Tis the custom, monsieur. The bailiff of the courts is bound to<br>deliver the malefactor ready judged for execution if he be a<br>layman, to the provost of Paris; if a clerk, to the official of<br>the bishopric.”</p>\n<p>“Thank you, sir.”</p>\n<p>“Oh, God!” said Fleur-de-Lys, “the poor creature!”</p>\n<p>This thought filled with sadness the glance which she cast upon<br>the populace. The captain, much more occupied with her than with<br>that pack of the rabble, was amorously rumpling her girdle<br>behind. She turned round, entreating and smiling.</p>\n<p>“Please let me alone, Phœbus! If my mother were to return, she<br>would see your hand!”</p>\n<p>At that moment, midday rang slowly out from the clock of<br>Notre-Dame. A murmur of satisfaction broke out in the crowd. The<br>last vibration of the twelfth stroke had hardly died away when<br>all heads surged like the waves beneath a squall, and an immense<br>shout went up from the pavement, the windows, and the roofs,</p>\n<p>“There she is!”</p>\n<p>Fleur-de-Lys pressed her hands to her eyes, that she might not<br>see.</p>\n<p>“Charming girl,” said Phœbus, “do you wish to withdraw?”</p>\n<p>“No,” she replied; and she opened through curiosity, the eyes<br>which she had closed through fear.</p>\n<p>A tumbrel drawn by a stout Norman horse, and all surrounded by<br>cavalry in violet livery with white crosses, had just debouched<br>upon the Place through the Rue Saint-Pierre-aux-Bœufs. The<br>sergeants of the watch were clearing a passage for it through the<br>crowd, by stout blows from their clubs. Beside the cart rode<br>several officers of justice and police, recognizable by their<br>black costume and their awkwardness in the saddle. Master Jacques<br>Charmolue paraded at their head.</p>\n<p>In the fatal cart sat a young girl with her arms tied behind her<br>back, and with no priest beside her. She was in her shift; her<br>long black hair (the fashion then was to cut it off only at the<br>foot of the gallows) fell in disorder upon her half-bared throat<br>and shoulders.</p>\n<p>Athwart that waving hair, more glossy than the plumage of a<br>raven, a thick, rough, gray rope was visible, twisted and<br>knotted, chafing her delicate collar-bones and twining round the<br>charming neck of the poor girl, like an earthworm round a flower.<br>Beneath that rope glittered a tiny amulet ornamented with bits of<br>green glass, which had been left to her no doubt, because nothing<br>is refused to those who are about to die. The spectators in the<br>windows could see in the bottom of the cart her naked legs which<br>she strove to hide beneath her, as by a final feminine instinct.<br>At her feet lay a little goat, bound. The condemned girl held<br>together with her teeth her imperfectly fastened shift. One would<br>have said that she suffered still more in her misery from being<br>thus exposed almost naked to the eyes of all. Alas! modesty is<br>not made for such shocks.</p>\n<p>“Jesus!” said Fleur-de-Lys hastily to the captain. “Look fair<br>cousin, ’tis that wretched Bohemian with the goat.”</p>\n<p>So saying, she turned to Phœbus. His eyes were fixed on the<br>tumbrel. He was very pale.</p>\n<p>“What Bohemian with the goat?” he stammered.</p>\n<p>“What!” resumed Fleur-de-Lys, “do you not remember?”</p>\n<p>Phœbus interrupted her.</p>\n<p>“I do not know what you mean.”</p>\n<p>He made a step to re-enter the room, but Fleur-de-Lys, whose<br>jealousy, previously so vividly aroused by this same gypsy, had<br>just been re-awakened, Fleur-de-Lys gave him a look full of<br>penetration and distrust. She vaguely recalled at that moment<br>having heard of a captain mixed up in the trial of that witch.</p>\n<p>“What is the matter with you?” she said to Phœbus, “one would<br>say, that this woman had disturbed you.”</p>\n<p>Phœbus forced a sneer,—</p>\n<p>“Me! Not the least in the world! Ah! yes, certainly!”</p>\n<p>“Remain, then!” she continued imperiously, “and let us see the<br>end.”</p>\n<p>The unlucky captain was obliged to remain. He was somewhat<br>reassured by the fact that the condemned girl never removed her<br>eyes from the bottom of the cart. It was but too surely la<br>Esmeralda. In this last stage of opprobrium and misfortune, she<br>was still beautiful; her great black eyes appeared still larger,<br>because of the emaciation of her cheeks; her pale profile was<br>pure and sublime. She resembled what she had been, in the same<br>degree that a virgin by Masaccio, resembles a virgin of<br>Raphael,—weaker, thinner, more delicate.</p>\n<p>Moreover, there was nothing in her which was not shaken in some<br>sort, and which with the exception of her modesty, she did not<br>let go at will, so profoundly had she been broken by stupor and<br>despair. Her body bounded at every jolt of the tumbrel like a<br>dead or broken thing; her gaze was dull and imbecile. A tear was<br>still visible in her eyes, but motionless and frozen, so to<br>speak.</p>\n<p>Meanwhile, the lugubrious cavalcade has traversed the crowd amid<br>cries of joy and curious attitudes. But as a faithful historian,<br>we must state that on beholding her so beautiful, so depressed,<br>many were moved with pity, even among the hardest of them.</p>\n<p>The tumbrel had entered the Parvis.</p>\n<p>It halted before the central portal. The escort ranged themselves<br>in line on both sides. The crowd became silent, and, in the midst<br>of this silence full of anxiety and solemnity, the two leaves of<br>the grand door swung back, as of themselves, on their hinges,<br>which gave a creak like the sound of a fife. Then there became<br>visible in all its length, the deep, gloomy church, hung in<br>black, sparely lighted with a few candles gleaming afar off on<br>the principal altar, opened in the midst of the Place which was<br>dazzling with light, like the mouth of a cavern. At the very<br>extremity, in the gloom of the apse, a gigantic silver cross was<br>visible against a black drapery which hung from the vault to the<br>pavement. The whole nave was deserted. But a few heads of priests<br>could be seen moving confusedly in the distant choir stalls, and,<br>at the moment when the great door opened, there escaped from the<br>church a loud, solemn, and monotonous chanting, which cast over<br>the head of the condemned girl, in gusts, fragments of melancholy<br>psalms,—</p>\n<p>“_Non timebo millia populi circumdantis me: exsurge, Domine;<br>salvum me fac, Deus!_”</p>\n<p>“_Salvum me fac, Deus, quoniam intraverunt aquæ usque ad animam<br>meam_.</p>\n<p>“<em>Infixus sum in limo profundi; et non est substantia</em>.”</p>\n<p>At the same time, another voice, separate from the choir, intoned<br>upon the steps of the chief altar, this melancholy offertory,—</p>\n<p>“_Qui verbum meum audit, et credit ei qui misit me, habet vitam<br>æternam et in judicium non venit; sed transit a morte in<br>vitam._”[46]</p>\n<p>This chant, which a few old men buried in the gloom sang from<br>afar over that beautiful creature, full of youth and life,<br>caressed by the warm air of spring, inundated with sunlight was<br>the mass for the dead.</p>\n<p>The people listened devoutly.</p>\n<p>The unhappy girl seemed to lose her sight and her consciousness<br>in the obscure interior of the church. Her white lips moved as<br>though in prayer, and the headsman’s assistant who approached to<br>assist her to alight from the cart, heard her repeating this word<br>in a low tone,—“Phœbus.”</p>\n<p>They untied her hands, made her alight, accompanied by her goat,<br>which had also been unbound, and which bleated with joy at<br>finding itself free: and they made her walk barefoot on the hard<br>pavement to the foot of the steps leading to the door. The rope<br>about her neck trailed behind her. One would have said it was a<br>serpent following her.</p>\n<p>Then the chanting in the church ceased. A great golden cross and<br>a row of wax candles began to move through the gloom. The<br>halberds of the motley beadles clanked; and, a few moments later,<br>a long procession of priests in chasubles, and deacons in<br>dalmatics, marched gravely towards the condemned girl, as they<br>drawled their song, spread out before her view and that of the<br>crowd. But her glance rested on the one who marched at the head,<br>immediately after the cross-bearer.</p>\n<p>“Oh!” she said in a low voice, and with a shudder, “’tis he<br>again! the priest!”</p>\n<p>It was in fact, the archdeacon. On his left he had the<br>sub-chanter, on his right, the chanter, armed with his official<br>wand. He advanced with head thrown back, his eyes fixed and wide<br>open, intoning in a strong voice,—</p>\n<p>“<em>De ventre inferi clamavi, et exaudisti vocem meam</em>.</p>\n<p>“_Et projecisti me in profundum in corde maris, et flumem<br>circumdedit me._”[47]</p>\n<p>At the moment when he made his appearance in the full daylight<br>beneath the lofty arched portal, enveloped in an ample cope of<br>silver barred with a black cross, he was so pale that more than<br>one person in the crowd thought that one of the marble bishops<br>who knelt on the sepulchral stones of the choir had risen and was<br>come to receive upon the brink of the tomb, the woman who was<br>about to die.</p>\n<p>She, no less pale, no less like a statue, had hardly noticed that<br>they had placed in her hand a heavy, lighted candle of yellow<br>wax; she had not heard the yelping voice of the clerk reading the<br>fatal contents of the apology; when they told her to respond with<br><em>Amen</em>, she responded <em>Amen</em>. She only recovered life and force<br>when she beheld the priest make a sign to her guards to withdraw,<br>and himself advance alone towards her.</p>\n<p>Then she felt her blood boil in her head, and a remnant of<br>indignation flashed up in that soul already benumbed and cold.</p>\n<p>The archdeacon approached her slowly; even in that extremity, she<br>beheld him cast an eye sparkling with sensuality, jealousy, and<br>desire, over her exposed form. Then he said aloud,—</p>\n<p>“Young girl, have you asked God’s pardon for your faults and<br>shortcomings?”</p>\n<p>He bent down to her ear, and added (the spectators supposed that<br>he was receiving her last confession): “Will you have me? I can<br>still save you!”</p>\n<p>She looked intently at him: “Begone, demon, or I will denounce<br>you!”</p>\n<p>He gave vent to a horrible smile: “You will not be believed. You<br>will only add a scandal to a crime. Reply quickly! Will you have<br>me?”</p>\n<p>“What have you done with my Phœbus?”</p>\n<p>“He is dead!” said the priest.</p>\n<p>At that moment the wretched archdeacon raised his head<br>mechanically and beheld at the other end of the Place, in the<br>balcony of the Gondelaurier mansion, the captain standing beside<br>Fleur-de-Lys. He staggered, passed his hand across his eyes,<br>looked again, muttered a curse, and all his features were<br>violently contorted.</p>\n<p>“Well, die then!” he hissed between his teeth. “No one shall have<br>you.” Then, raising his hand over the gypsy, he exclaimed in a<br>funereal voice:—“_I nunc, anima anceps, et sit tibi Deus<br>misericors!_”[48]</p>\n<p>This was the dread formula with which it was the custom to<br>conclude these gloomy ceremonies. It was the signal agreed upon<br>between the priest and the executioner.</p>\n<p>The crowd knelt.</p>\n<p>“<em>Kyrie eleison</em>,”[49] said the priests, who had remained beneath<br>the arch of the portal.</p>\n<p>“<em>Kyrie eleison</em>,” repeated the throng in that murmur which runs<br>over all heads, like the waves of a troubled sea.</p>\n<p>“<em>Amen</em>,” said the archdeacon.</p>\n<p>He turned his back on the condemned girl, his head sank upon his<br>breast once more, he crossed his hands and rejoined his escort of<br>priests, and a moment later he was seen to disappear, with the<br>cross, the candles, and the copes, beneath the misty arches of<br>the cathedral, and his sonorous voice was extinguished by degrees<br>in the choir, as he chanted this verse of despair,—</p>\n<p>“<em>Omnes gurgites tui et fluctus tui super me transierunt</em>.”[50]</p>\n<p>At the same time, the intermittent clash of the iron butts of the<br>beadles’ halberds, gradually dying away among the columns of the<br>nave, produced the effect of a clock hammer striking the last<br>hour of the condemned.</p>\n<p>The doors of Notre-Dame remained open, allowing a view of the<br>empty desolate church, draped in mourning, without candles, and<br>without voices.</p>\n<p>The condemned girl remained motionless in her place, waiting to<br>be disposed of. One of the sergeants of police was obliged to<br>notify Master Charmolue of the fact, as the latter, during this<br>entire scene, had been engaged in studying the bas-relief of the<br>grand portal which represents, according to some, the sacrifice<br>of Abraham; according to others, the philosopher’s alchemical<br>operation: the sun being figured forth by the angel; the fire, by<br>the fagot; the artisan, by Abraham.</p>\n<p>There was considerable difficulty in drawing him away from that<br>contemplation, but at length he turned round; and, at a signal<br>which he gave, two men clad in yellow, the executioner’s<br>assistants, approached the gypsy to bind her hands once more.</p>\n<p>The unhappy creature, at the moment of mounting once again the<br>fatal cart, and proceeding to her last halting-place, was seized,<br>possibly, with some poignant clinging to life. She raised her<br>dry, red eyes to heaven, to the sun, to the silvery clouds, cut<br>here and there by a blue trapezium or triangle; then she lowered<br>them to objects around her, to the earth, the throng, the houses;<br>all at once, while the yellow man was binding her elbows, she<br>uttered a terrible cry, a cry of joy. Yonder, on that balcony, at<br>the corner of the Place, she had just caught sight of him, of her<br>friend, her lord, Phœbus, the other apparition of her life!</p>\n<p>The judge had lied! the priest had lied! it was certainly he, she<br>could not doubt it; he was there, handsome, alive, dressed in his<br>brilliant uniform, his plume on his head, his sword by his side!</p>\n<p>“Phœbus!” she cried, “my Phœbus!”</p>\n<p>And she tried to stretch towards him arms trembling with love and<br>rapture, but they were bound.</p>\n<p>Then she saw the captain frown, a beautiful young girl who was<br>leaning against him gazed at him with disdainful lips and<br>irritated eyes; then Phœbus uttered some words which did not<br>reach her, and both disappeared precipitately behind the window<br>opening upon the balcony, which closed after them.</p>\n<p>“Phœbus!” she cried wildly, “can it be you believe it?” A<br>monstrous thought had just presented itself to her. She<br>remembered that she had been condemned to death for murder<br>committed on the person of Phœbus de Châteaupers.</p>\n<p>She had borne up until that moment. But this last blow was too<br>harsh. She fell lifeless on the pavement.</p>\n<p>“Come,” said Charmolue, “carry her to the cart, and make an end<br>of it.”</p>\n<p>No one had yet observed in the gallery of the statues of the<br>kings, carved directly above the arches of the portal, a strange<br>spectator, who had, up to that time, observed everything with<br>such impassiveness, with a neck so strained, a visage so hideous<br>that, in his motley accoutrement of red and violet, he might have<br>been taken for one of those stone monsters through whose mouths<br>the long gutters of the cathedral have discharged their waters<br>for six hundred years. This spectator had missed nothing that had<br>taken place since midday in front of the portal of Notre-Dame.<br>And at the very beginning he had securely fastened to one of the<br>small columns a large knotted rope, one end of which trailed on<br>the flight of steps below. This being done, he began to look on<br>tranquilly, whistling from time to time when a blackbird flitted<br>past. Suddenly, at the moment when the superintendent’s<br>assistants were preparing to execute Charmolue’s phlegmatic<br>order, he threw his leg over the balustrade of the gallery,<br>seized the rope with his feet, his knees and his hands; then he<br>was seen to glide down the façade, as a drop of rain slips down a<br>window-pane, rush to the two executioners with the swiftness of a<br>cat which has fallen from a roof, knock them down with two<br>enormous fists, pick up the gypsy with one hand, as a child would<br>her doll, and dash back into the church with a single bound,<br>lifting the young girl above his head and crying in a formidable<br>voice,—</p>\n<p>“Sanctuary!”</p>\n<p>This was done with such rapidity, that had it taken place at<br>night, the whole of it could have been seen in the space of a<br>single flash of lightning.</p>\n<p>“Sanctuary! Sanctuary!” repeated the crowd; and the clapping of<br>ten thousand hands made Quasimodo’s single eye sparkle with joy<br>and pride.</p>\n<p>This shock restored the condemned girl to her senses. She raised<br>her eyelids, looked at Quasimodo, then closed them again<br>suddenly, as though terrified by her deliverer.</p>\n<p>Charmolue was stupefied, as well as the executioners and the<br>entire escort. In fact, within the bounds of Notre-Dame, the<br>condemned girl could not be touched. The cathedral was a place of<br>refuge. All temporal jurisdiction expired upon its threshold.</p>\n<p>Quasimodo had halted beneath the great portal, his huge feet<br>seemed as solid on the pavement of the church as the heavy Roman<br>pillars. His great, bushy head sat low between his shoulders,<br>like the heads of lions, who also have a mane and no neck. He<br>held the young girl, who was quivering all over, suspended from<br>his horny hands like a white drapery; but he carried her with as<br>much care as though he feared to break her or blight her. One<br>would have said that he felt that she was a delicate, exquisite,<br>precious thing, made for other hands than his. There were moments<br>when he looked as if not daring to touch her, even with his<br>breath. Then, all at once, he would press her forcibly in his<br>arms, against his angular bosom, like his own possession, his<br>treasure, as the mother of that child would have done. His<br>gnome’s eye, fastened upon her, inundated her with tenderness,<br>sadness, and pity, and was suddenly raised filled with<br>lightnings. Then the women laughed and wept, the crowd stamped<br>with enthusiasm, for, at that moment Quasimodo had a beauty of<br>his own. He was handsome; he, that orphan, that foundling, that<br>outcast, he felt himself august and strong, he gazed in the face<br>of that society from which he was banished, and in which he had<br>so powerfully intervened, of that human justice from which he had<br>wrenched its prey, of all those tigers whose jaws were forced to<br>remain empty, of those policemen, those judges, those<br>executioners, of all that force of the king which he, the meanest<br>of creatures, had just broken, with the force of God.</p>\n<p>And then, it was touching to behold this protection which had<br>fallen from a being so hideous upon a being so unhappy, a<br>creature condemned to death saved by Quasimodo. They were two<br>extremes of natural and social wretchedness, coming into contact<br>and aiding each other.</p>\n<p>Meanwhile, after several moments of triumph, Quasimodo had<br>plunged abruptly into the church with his burden. The populace,<br>fond of all prowess, sought him with their eyes, beneath the<br>gloomy nave, regretting that he had so speedily disappeared from<br>their acclamations. All at once, he was seen to re-appear at one<br>of the extremities of the gallery of the kings of France; he<br>traversed it, running like a madman, raising his conquest high in<br>his arms and shouting: “Sanctuary!” The crowd broke forth into<br>fresh applause. The gallery passed, he plunged once more into the<br>interior of the church. A moment later, he re-appeared upon the<br>upper platform, with the gypsy still in his arms, still running<br>madly, still crying, “Sanctuary!” and the throng applauded.<br>Finally, he made his appearance for the third time upon the<br>summit of the tower where hung the great bell; from that point he<br>seemed to be showing to the entire city the girl whom he had<br>saved, and his voice of thunder, that voice which was so rarely<br>heard, and which he never heard himself, repeated thrice with<br>frenzy, even to the clouds: “Sanctuary! Sanctuary! Sanctuary!”</p>\n<p>“Noël! Noël!” shouted the populace in its turn; and that immense<br>acclamation flew to astonish the crowd assembled at the Grève on<br>the other bank, and the recluse who was still waiting with her<br>eyes riveted on the gibbet.</p>\n<p>BOOK NINTH.</p>\n<h1 class=\"chapter\" id=\"chapter-i-delirium\">Chapter I. DELIRIUM.</h1>\n<p>Claude Frollo was no longer in Notre-Dame when his adopted son so<br>abruptly cut the fatal web in which the archdeacon and the gypsy<br>were entangled. On returning to the sacristy he had torn off his<br>alb, cope, and stole, had flung all into the hands of the<br>stupefied beadle, had made his escape through the private door of<br>the cloister, had ordered a boatman of the Terrain to transport<br>him to the left bank of the Seine, and had plunged into the hilly<br>streets of the University, not knowing whither he was going,<br>encountering at every step groups of men and women who were<br>hurrying joyously towards the Pont Saint-Michel, in the hope of<br>still arriving in time to see the witch hung there,—pale, wild,<br>more troubled, more blind and more fierce than a night bird let<br>loose and pursued by a troop of children in broad daylight. He no<br>longer knew where he was, what he thought, or whether he were<br>dreaming. He went forward, walking, running, taking any street at<br>haphazard, making no choice, only urged ever onward away from the<br>Grève, the horrible Grève, which he felt confusedly, to be behind<br>him.</p>\n<p>In this manner he skirted Mount Sainte-Geneviève, and finally<br>emerged from the town by the Porte Saint-Victor. He continued his<br>flight as long as he could see, when he turned round, the<br>turreted enclosure of the University, and the rare houses of the<br>suburb; but, when, at length, a rise of ground had completely<br>concealed from him that odious Paris, when he could believe<br>himself to be a hundred leagues distant from it, in the fields,<br>in the desert, he halted, and it seemed to him that he breathed<br>more freely.</p>\n<p>Then frightful ideas thronged his mind. Once more he could see<br>clearly into his soul, and he shuddered. He thought of that<br>unhappy girl who had destroyed him, and whom he had destroyed. He<br>cast a haggard eye over the double, tortuous way which fate had<br>caused their two destinies to pursue up to their point of<br>intersection, where it had dashed them against each other without<br>mercy. He meditated on the folly of eternal vows, on the vanity<br>of chastity, of science, of religion, of virtue, on the<br>uselessness of God. He plunged to his heart’s content in evil<br>thoughts, and in proportion as he sank deeper, he felt a Satanic<br>laugh burst forth within him.</p>\n<p>And as he thus sifted his soul to the bottom, when he perceived<br>how large a space nature had prepared there for the passions, he<br>sneered still more bitterly. He stirred up in the depths of his<br>heart all his hatred, all his malevolence; and, with the cold<br>glance of a physician who examines a patient, he recognized the<br>fact that this malevolence was nothing but vitiated love; that<br>love, that source of every virtue in man, turned to horrible<br>things in the heart of a priest, and that a man constituted like<br>himself, in making himself a priest, made himself a demon. Then<br>he laughed frightfully, and suddenly became pale again, when he<br>considered the most sinister side of his fatal passion, of that<br>corrosive, venomous malignant, implacable love, which had ended<br>only in the gibbet for one of them and in hell for the other;<br>condemnation for her, damnation for him.</p>\n<p>And then his laughter came again, when he reflected that Phœbus<br>was alive; that after all, the captain lived, was gay and happy,<br>had handsomer doublets than ever, and a new mistress whom he was<br>conducting to see the old one hanged. His sneer redoubled its<br>bitterness when he reflected that out of the living beings whose<br>death he had desired, the gypsy, the only creature whom he did<br>not hate, was the only one who had not escaped him.</p>\n<p>Then from the captain, his thought passed to the people, and<br>there came to him a jealousy of an unprecedented sort. He<br>reflected that the people also, the entire populace, had had<br>before their eyes the woman whom he loved exposed almost naked.<br>He writhed his arms with agony as he thought that the woman whose<br>form, caught by him alone in the darkness would have been supreme<br>happiness, had been delivered up in broad daylight at full<br>noonday, to a whole people, clad as for a night of<br>voluptuousness. He wept with rage over all these mysteries of<br>love, profaned, soiled, laid bare, withered forever. He wept with<br>rage as he pictured to himself how many impure looks had been<br>gratified at the sight of that badly fastened shift, and that<br>this beautiful girl, this virgin lily, this cup of modesty and<br>delight, to which he would have dared to place his lips only<br>trembling, had just been transformed into a sort of public bowl,<br>whereat the vilest populace of Paris, thieves, beggars, lackeys,<br>had come to quaff in common an audacious, impure, and depraved<br>pleasure.</p>\n<p>And when he sought to picture to himself the happiness which he<br>might have found upon earth, if she had not been a gypsy, and if<br>he had not been a priest, if Phœbus had not existed and if she<br>had loved him; when he pictured to himself that a life of<br>serenity and love would have been possible to him also, even to<br>him; that there were at that very moment, here and there upon the<br>earth, happy couples spending the hours in sweet converse beneath<br>orange trees, on the banks of brooks, in the presence of a<br>setting sun, of a starry night; and that if God had so willed, he<br>might have formed with her one of those blessed couples,—his<br>heart melted in tenderness and despair.</p>\n<p>Oh! she! still she! It was this fixed idea which returned<br>incessantly, which tortured him, which ate into his brain, and<br>rent his vitals. He did not regret, he did not repent; all that<br>he had done he was ready to do again; he preferred to behold her<br>in the hands of the executioner rather than in the arms of the<br>captain. But he suffered; he suffered so that at intervals he<br>tore out handfuls of his hair to see whether it were not turning<br>white.</p>\n<p>Among other moments there came one, when it occurred to him that<br>it was perhaps the very minute when the hideous chain which he<br>had seen that morning, was pressing its iron noose closer about<br>that frail and graceful neck. This thought caused the<br>perspiration to start from every pore.</p>\n<p>There was another moment when, while laughing diabolically at<br>himself, he represented to himself la Esmeralda as he had seen<br>her on that first day, lively, careless, joyous, gayly attired,<br>dancing, winged, harmonious, and la Esmeralda of the last day, in<br>her scanty shift, with a rope about her neck, mounting slowly<br>with her bare feet, the angular ladder of the gallows; he figured<br>to himself this double picture in such a manner that he gave vent<br>to a terrible cry.</p>\n<p>While this hurricane of despair overturned, broke, tore up, bent,<br>uprooted everything in his soul, he gazed at nature around him.<br>At his feet, some chickens were searching the thickets and<br>pecking, enamelled beetles ran about in the sun; overhead, some<br>groups of dappled gray clouds were floating across the blue sky;<br>on the horizon, the spire of the Abbey Saint-Victor pierced the<br>ridge of the hill with its slate obelisk; and the miller of the<br>Copeaue hillock was whistling as he watched the laborious wings<br>of his mill turning. All this active, organized, tranquil life,<br>recurring around him under a thousand forms, hurt him. He resumed<br>his flight.</p>\n<p>He sped thus across the fields until evening. This flight from<br>nature, life, himself, man, God, everything, lasted all day long.<br>Sometimes he flung himself face downward on the earth, and tore<br>up the young blades of wheat with his nails. Sometimes he halted<br>in the deserted street of a village, and his thoughts were so<br>intolerable that he grasped his head in both hands and tried to<br>tear it from his shoulders in order to dash it upon the pavement.</p>\n<p>Towards the hour of sunset, he examined himself again, and found<br>himself nearly mad. The tempest which had raged within him ever<br>since the instant when he had lost the hope and the will to save<br>the gypsy,—that tempest had not left in his conscience a single<br>healthy idea, a single thought which maintained its upright<br>position. His reason lay there almost entirely destroyed. There<br>remained but two distinct images in his mind, la Esmeralda and<br>the gallows; all the rest was blank. Those two images united,<br>presented to him a frightful group; and the more he concentrated<br>what attention and thought was left to him, the more he beheld<br>them grow, in accordance with a fantastic progression, the one in<br>grace, in charm, in beauty, in light, the other in deformity and<br>horror; so that at last la Esmeralda appeared to him like a star,<br>the gibbet like an enormous, fleshless arm.</p>\n<p>One remarkable fact is, that during the whole of this torture,<br>the idea of dying did not seriously occur to him. The wretch was<br>made so. He clung to life. Perhaps he really saw hell beyond it.</p>\n<p>Meanwhile, the day continued to decline. The living being which<br>still existed in him reflected vaguely on retracing its steps. He<br>believed himself to be far away from Paris; on taking his<br>bearings, he perceived that he had only circled the enclosure of<br>the University. The spire of Saint-Sulpice, and the three lofty<br>needles of Saint Germain-des-Prés, rose above the horizon on his<br>right. He turned his steps in that direction. When he heard the<br>brisk challenge of the men-at-arms of the abbey, around the<br>crenelated, circumscribing wall of Saint-Germain, he turned<br>aside, took a path which presented itself between the abbey and<br>the lazar-house of the bourg, and at the expiration of a few<br>minutes found himself on the verge of the Pré-aux-Clercs. This<br>meadow was celebrated by reason of the brawls which went on there<br>night and day; it was the hydra of the poor monks of<br>Saint-Germain: _quod monachis Sancti-Germaini pratensis hydra<br>fuit, clericis nova semper dissidiorum capita suscitantibus_. The<br>archdeacon was afraid of meeting some one there; he feared every<br>human countenance; he had just avoided the University and the<br>Bourg Saint-Germain; he wished to re-enter the streets as late as<br>possible. He skirted the Pré-aux-Clercs, took the deserted path<br>which separated it from the Dieu-Neuf, and at last reached the<br>water’s edge. There Dom Claude found a boatman, who, for a few<br>farthings in Parisian coinage, rowed him up the Seine as far as<br>the point of the city, and landed him on that tongue of abandoned<br>land where the reader has already beheld Gringoire dreaming, and<br>which was prolonged beyond the king’s gardens, parallel to the<br>Ile du Passeur-aux-Vaches.</p>\n<p>The monotonous rocking of the boat and the ripple of the water<br>had, in some sort, quieted the unhappy Claude. When the boatman<br>had taken his departure, he remained standing stupidly on the<br>strand, staring straight before him and perceiving objects only<br>through magnifying oscillations which rendered everything a sort<br>of phantasmagoria to him. The fatigue of a great grief not<br>infrequently produces this effect on the mind.</p>\n<p>The sun had set behind the lofty Tour-de-Nesle. It was the<br>twilight hour. The sky was white, the water of the river was<br>white. Between these two white expanses, the left bank of the<br>Seine, on which his eyes were fixed, projected its gloomy mass<br>and, rendered ever thinner and thinner by perspective, it plunged<br>into the gloom of the horizon like a black spire. It was loaded<br>with houses, of which only the obscure outline could be<br>distinguished, sharply brought out in shadows against the light<br>background of the sky and the water. Here and there windows began<br>to gleam, like the holes in a brazier. That immense black obelisk<br>thus isolated between the two white expanses of the sky and the<br>river, which was very broad at this point, produced upon Dom<br>Claude a singular effect, comparable to that which would be<br>experienced by a man who, reclining on his back at the foot of<br>the tower of Strasbourg, should gaze at the enormous spire<br>plunging into the shadows of the twilight above his head. Only,<br>in this case, it was Claude who was erect and the obelisk which<br>was lying down; but, as the river, reflecting the sky, prolonged<br>the abyss below him, the immense promontory seemed to be as<br>boldly launched into space as any cathedral spire; and the<br>impression was the same. This impression had even one stronger<br>and more profound point about it, that it was indeed the tower of<br>Strasbourg, but the tower of Strasbourg two leagues in height;<br>something unheard of, gigantic, immeasurable; an edifice such as<br>no human eye has ever seen; a tower of Babel. The chimneys of the<br>houses, the battlements of the walls, the faceted gables of the<br>roofs, the spire of the Augustines, the tower of Nesle, all these<br>projections which broke the profile of the colossal obelisk added<br>to the illusion by displaying in eccentric fashion to the eye the<br>indentations of a luxuriant and fantastic sculpture.</p>\n<p>Claude, in the state of hallucination in which he found himself,<br>believed that he saw, that he saw with his actual eyes, the bell<br>tower of hell; the thousand lights scattered over the whole<br>height of the terrible tower seemed to him so many porches of the<br>immense interior furnace; the voices and noises which escaped<br>from it seemed so many shrieks, so many death groans. Then he<br>became alarmed, he put his hands on his ears that he might no<br>longer hear, turned his back that he might no longer see, and<br>fled from the frightful vision with hasty strides.</p>\n<p>But the vision was in himself.</p>\n<p>When he re-entered the streets, the passers-by elbowing each<br>other by the light of the shop-fronts, produced upon him the<br>effect of a constant going and coming of spectres about him.<br>There were strange noises in his ears; extraordinary fancies<br>disturbed his brain. He saw neither houses, nor pavements, nor<br>chariots, nor men and women, but a chaos of indeterminate objects<br>whose edges melted into each other. At the corner of the Rue de<br>la Barillerie, there was a grocer’s shop whose porch was<br>garnished all about, according to immemorial custom, with hoops<br>of tin from which hung a circle of wooden candles, which came in<br>contact with each other in the wind, and rattled like castanets.<br>He thought he heard a cluster of skeletons at Montfaucon clashing<br>together in the gloom.</p>\n<p>“Oh!” he muttered, “the night breeze dashes them against each<br>other, and mingles the noise of their chains with the rattle of<br>their bones! Perhaps she is there among them!”</p>\n<p>In his state of frenzy, he knew not whither he was going. After a<br>few strides he found himself on the Pont Saint-Michel. There was<br>a light in the window of a ground-floor room; he approached.<br>Through a cracked window he beheld a mean chamber which recalled<br>some confused memory to his mind. In that room, badly lighted by<br>a meagre lamp, there was a fresh, light-haired young man, with a<br>merry face, who amid loud bursts of laughter was embracing a very<br>audaciously attired young girl; and near the lamp sat an old<br>crone spinning and singing in a quavering voice. As the young man<br>did not laugh constantly, fragments of the old woman’s ditty<br>reached the priest; it was something unintelligible yet<br>frightful,—</p>\n<p>“Grève, aboie, Grève, grouille!<br>File, file, ma quenouille,<br>File sa corde au bourreau,<br>Qui siffle dans le préau,<br>Grève, aboie, Grève, grouille!</p>\n<p>“La belle corde de chanvre!<br>Semez d’Issy jusqu’à Vanvre<br>Du chanvre et non pas du blé.<br>Le voleur n’a pas volé<br>La belle corde de chanvre.</p>\n<p>“Grève, grouille, Grève, aboie!<br>Pour voir la fille de joie,<br>Prendre au gibet chassieux,<br>Les fenêtres sont des yeux.<br>Grève, grouille, Grève, aboie!”[51]</p>\n<p>Thereupon the young man laughed and caressed the wench. The crone<br>was la Falourdel; the girl was a courtesan; the young man was his<br>brother Jehan.</p>\n<p>He continued to gaze. That spectacle was as good as any other.</p>\n<p>He saw Jehan go to a window at the end of the room, open it, cast<br>a glance on the quay, where in the distance blazed a thousand<br>lighted casements, and he heard him say as he closed the sash,—</p>\n<p>“’Pon my soul! How dark it is; the people are lighting their<br>candles, and the good God his stars.”</p>\n<p>Then Jehan came back to the hag, smashed a bottle standing on the<br>table, exclaiming,—</p>\n<p>“Already empty, <em>cor-bœuf!</em> and I have no more money! Isabeau, my<br>dear, I shall not be satisfied with Jupiter until he has changed<br>your two white nipples into two black bottles, where I may suck<br>wine of Beaune day and night.”</p>\n<p>This fine pleasantry made the courtesan laugh, and Jehan left the<br>room.</p>\n<p>Dom Claude had barely time to fling himself on the ground in<br>order that he might not be met, stared in the face and recognized<br>by his brother. Luckily, the street was dark, and the scholar was<br>tipsy. Nevertheless, he caught sight of the archdeacon prone upon<br>the earth in the mud.</p>\n<p>“Oh! oh!” said he; “here’s a fellow who has been leading a jolly<br>life, to-day.”</p>\n<p>He stirred up Dom Claude with his foot, and the latter held his<br>breath.</p>\n<p>“Dead drunk,” resumed Jehan. “Come, he’s full. A regular leech<br>detached from a hogshead. He’s bald,” he added, bending down,<br>“’tis an old man! <em>Fortunate senex!</em>”</p>\n<p>Then Dom Claude heard him retreat, saying,—</p>\n<p>“’Tis all the same, reason is a fine thing, and my brother the<br>archdeacon is very happy in that he is wise and has money.”</p>\n<p>Then the archdeacon rose to his feet, and ran without halting,<br>towards Notre-Dame, whose enormous towers he beheld rising above<br>the houses through the gloom.</p>\n<p>At the instant when he arrived, panting, on the Place du Parvis,<br>he shrank back and dared not raise his eyes to the fatal edifice.</p>\n<p>“Oh!” he said, in a low voice, “is it really true that such a<br>thing took place here, to-day, this very morning?”</p>\n<p>Still, he ventured to glance at the church. The front was sombre;<br>the sky behind was glittering with stars. The crescent of the<br>moon, in her flight upward from the horizon, had paused at the<br>moment, on the summit of the light hand tower, and seemed to have<br>perched itself, like a luminous bird, on the edge of the<br>balustrade, cut out in black trefoils.</p>\n<p>The cloister door was shut; but the archdeacon always carried<br>with him the key of the tower in which his laboratory was<br>situated. He made use of it to enter the church.</p>\n<p>In the church he found the gloom and silence of a cavern. By the<br>deep shadows which fell in broad sheets from all directions, he<br>recognized the fact that the hangings for the ceremony of the<br>morning had not yet been removed. The great silver cross shone<br>from the depths of the gloom, powdered with some sparkling<br>points, like the milky way of that sepulchral night. The long<br>windows of the choir showed the upper extremities of their arches<br>above the black draperies, and their painted panes, traversed by<br>a ray of moonlight had no longer any hues but the doubtful colors<br>of night, a sort of violet, white and blue, whose tint is found<br>only on the faces of the dead. The archdeacon, on perceiving<br>these wan spots all around the choir, thought he beheld the<br>mitres of damned bishops. He shut his eyes, and when he opened<br>them again, he thought they were a circle of pale visages gazing<br>at him.</p>\n<p>He started to flee across the church. Then it seemed to him that<br>the church also was shaking, moving, becoming endued with<br>animation, that it was alive; that each of the great columns was<br>turning into an enormous paw, which was beating the earth with<br>its big stone spatula, and that the gigantic cathedral was no<br>longer anything but a sort of prodigious elephant, which was<br>breathing and marching with its pillars for feet, its two towers<br>for trunks and the immense black cloth for its housings.</p>\n<p>This fever or madness had reached such a degree of intensity that<br>the external world was no longer anything more for the unhappy<br>man than a sort of Apocalypse,—visible, palpable, terrible.</p>\n<p>For one moment, he was relieved. As he plunged into the side<br>aisles, he perceived a reddish light behind a cluster of pillars.<br>He ran towards it as to a star. It was the poor lamp which<br>lighted the public breviary of Notre-Dame night and day, beneath<br>its iron grating. He flung himself eagerly upon the holy book in<br>the hope of finding some consolation, or some encouragement<br>there. The hook lay open at this passage of Job, over which his<br>staring eye glanced,—</p>\n<p>“And a spirit passed before my face, and I heard a small voice,<br>and the hair of my flesh stood up.”</p>\n<p>On reading these gloomy words, he felt that which a blind man<br>feels when he feels himself pricked by the staff which he has<br>picked up. His knees gave way beneath him, and he sank upon the<br>pavement, thinking of her who had died that day. He felt so many<br>monstrous vapors pass and discharge themselves in his brain, that<br>it seemed to him that his head had become one of the chimneys of<br>hell.</p>\n<p>It would appear that he remained a long time in this attitude, no<br>longer thinking, overwhelmed and passive beneath the hand of the<br>demon. At length some strength returned to him; it occurred to<br>him to take refuge in his tower beside his faithful Quasimodo. He<br>rose; and, as he was afraid, he took the lamp from the breviary<br>to light his way. It was a sacrilege; but he had got beyond<br>heeding such a trifle now.</p>\n<p>He slowly climbed the stairs of the towers, filled with a secret<br>fright which must have been communicated to the rare passers-by<br>in the Place du Parvis by the mysterious light of his lamp,<br>mounting so late from loophole to loophole of the bell tower.</p>\n<p>All at once, he felt a freshness on his face, and found himself<br>at the door of the highest gallery. The air was cold; the sky was<br>filled with hurrying clouds, whose large, white flakes drifted<br>one upon another like the breaking up of river ice after the<br>winter. The crescent of the moon, stranded in the midst of the<br>clouds, seemed a celestial vessel caught in the ice-cakes of the<br>air.</p>\n<p>He lowered his gaze, and contemplated for a moment, through the<br>railing of slender columns which unites the two towers, far away,<br>through a gauze of mists and smoke, the silent throng of the<br>roofs of Paris, pointed, innumerable, crowded and small like the<br>waves of a tranquil sea on a sum-mer night.</p>\n<p>The moon cast a feeble ray, which imparted to earth and heaven an<br>ashy hue.</p>\n<p>At that moment the clock raised its shrill, cracked voice.<br>Midnight rang out. The priest thought of midday; twelve o’clock<br>had come back again.</p>\n<p>“Oh!” he said in a very low tone, “she must be cold now.”</p>\n<p>All at once, a gust of wind extinguished his lamp, and almost at<br>the same instant, he beheld a shade, a whiteness, a form, a<br>woman, appear from the opposite angle of the tower. He started.<br>Beside this woman was a little goat, which mingled its bleat with<br>the last bleat of the clock.</p>\n<p>He had strength enough to look. It was she.</p>\n<p>She was pale, she was gloomy. Her hair fell over her shoulders as<br>in the morning; but there was no longer a rope on her neck, her<br>hands were no longer bound; she was free, she was dead.</p>\n<p>She was dressed in white and had a white veil on her head.</p>\n<p>She came towards him, slowly, with her gaze fixed on the sky. The<br>supernatural goat followed her. He felt as though made of stone<br>and too heavy to flee. At every step which she took in advance,<br>he took one backwards, and that was all. In this way he retreated<br>once more beneath the gloomy arch of the stairway. He was chilled<br>by the thought that she might enter there also; had she done so,<br>he would have died of terror.</p>\n<p>She did arrive, in fact, in front of the door to the stairway,<br>and paused there for several minutes, stared intently into the<br>darkness, but without appearing to see the priest, and passed on.<br>She seemed taller to him than when she had been alive; he saw the<br>moon through her white robe; he heard her breath.</p>\n<p>When she had passed on, he began to descend the staircase again,<br>with the slowness which he had observed in the spectre, believing<br>himself to be a spectre too, haggard, with hair on end, his<br>extinguished lamp still in his hand; and as he descended the<br>spiral steps, he distinctly heard in his ear a voice laughing and<br>repeating,—</p>\n<p>“A spirit passed before my face, and I heard a small voice, and<br>the hair of my flesh stood up.”</p>\n<h1 class=\"chapter\" id=\"chapter-ii-hunchbacked-one-eyed-lame\">Chapter II. HUNCHBACKED, ONE EYED, LAME.</h1>\n<p>Every city during the Middle Ages, and every city in France down<br>to the time of Louis XII. had its places of asylum. These<br>sanctuaries, in the midst of the deluge of penal and barbarous<br>jurisdictions which inundated the city, were a species of islands<br>which rose above the level of human justice. Every criminal who<br>landed there was safe. There were in every suburb almost as many<br>places of asylum as gallows. It was the abuse of impunity by the<br>side of the abuse of punishment; two bad things which strove to<br>correct each other. The palaces of the king, the hôtels of the<br>princes, and especially churches, possessed the right of asylum.<br>Sometimes a whole city which stood in need of being repeopled was<br>temporarily created a place of refuge. Louis XI. made all Paris a<br>refuge in 1467.</p>\n<p>His foot once within the asylum, the criminal was sacred; but he<br>must beware of leaving it; one step outside the sanctuary, and he<br>fell back into the flood. The wheel, the gibbet, the strappado,<br>kept good guard around the place of refuge, and lay in watch<br>incessantly for their prey, like sharks around a vessel. Hence,<br>condemned men were to be seen whose hair had grown white in a<br>cloister, on the steps of a palace, in the enclosure of an abbey,<br>beneath the porch of a church; in this manner the asylum was a<br>prison as much as any other. It sometimes happened that a solemn<br>decree of parliament violated the asylum and restored the<br>condemned man to the executioner; but this was of rare<br>occurrence. Parliaments were afraid of the bishops, and when<br>there was friction between these two robes, the gown had but a<br>poor chance against the cassock. Sometimes, however, as in the<br>affair of the assassins of Petit-Jean, the headsman of Paris, and<br>in that of Emery Rousseau, the murderer of Jean Valleret, justice<br>overleaped the church and passed on to the execution of its<br>sentences; but unless by virtue of a decree of Parliament, woe to<br>him who violated a place of asylum with armed force! The reader<br>knows the manner of death of Robert de Clermont, Marshal of<br>France, and of Jean de Châlons, Marshal of Champagne; and yet the<br>question was only of a certain Perrin Marc, the clerk of a<br>money-changer, a miserable assassin; but the two marshals had<br>broken the doors of St. Méry. Therein lay the enormity.</p>\n<p>Such respect was cherished for places of refuge that, according<br>to tradition, animals even felt it at times. Aymoire relates that<br>a stag, being chased by Dagobert, having taken refuge near the<br>tomb of Saint-Denis, the pack of hounds stopped short and barked.</p>\n<p>Churches generally had a small apartment prepared for the<br>reception of supplicants. In 1407, Nicolas Flamel caused to be<br>built on the vaults of Saint-Jacques de la Boucherie, a chamber<br>which cost him four livres six sous, sixteen farthings, parisis.</p>\n<p>At Notre-Dame it was a tiny cell situated on the roof of the side<br>aisle, beneath the flying buttresses, precisely at the spot where<br>the wife of the present janitor of the towers has made for<br>herself a garden, which is to the hanging gardens of Babylon what<br>a lettuce is to a palm-tree, what a porter’s wife is to a<br>Semiramis.</p>\n<p>It was here that Quasimodo had deposited la Esmeralda, after his<br>wild and triumphant course. As long as that course lasted, the<br>young girl had been unable to recover her senses, half<br>unconscious, half awake, no longer feeling anything, except that<br>she was mounting through the air, floating in it, flying in it,<br>that something was raising her above the earth. From time to time<br>she heard the loud laughter, the noisy voice of Quasimodo in her<br>ear; she half opened her eyes; then below her she confusedly<br>beheld Paris checkered with its thousand roofs of slate and<br>tiles, like a red and blue mosaic, above her head the frightful<br>and joyous face of Quasimodo. Then her eyelids drooped again; she<br>thought that all was over, that they had executed her during her<br>swoon, and that the misshapen spirit which had presided over her<br>destiny, had laid hold of her and was bearing her away. She dared<br>not look at him, and she surrendered herself to her fate. But<br>when the bellringer, dishevelled and panting, had deposited her<br>in the cell of refuge, when she felt his huge hands gently<br>detaching the cord which bruised her arms, she felt that sort of<br>shock which awakens with a start the passengers of a vessel which<br>runs aground in the middle of a dark night. Her thoughts awoke<br>also, and returned to her one by one. She saw that she was in<br>Notre-Dame; she remembered having been torn from the hands of the<br>executioner; that Phœbus was alive, that Phœbus loved her no<br>longer; and as these two ideas, one of which shed so much<br>bitterness over the other, presented themselves simultaneously to<br>the poor condemned girl; she turned to Quasimodo, who was<br>standing in front of her, and who terrified her; she said to<br>him,—</p>\n<p>“Why have you saved me?”</p>\n<p>He gazed at her with anxiety, as though seeking to divine what<br>she was saying to him. She repeated her question. Then he gave<br>her a profoundly sorrowful glance and fled. She was astonished.</p>\n<p>A few moments later he returned, bearing a package which he cast<br>at her feet. It was clothing which some charitable women had left<br>on the threshold of the church for her.</p>\n<p>Then she dropped her eyes upon herself and saw that she was<br>almost naked, and blushed. Life had returned.</p>\n<p>Quasimodo appeared to experience something of this modesty. He<br>covered his eyes with his large hand and retired once more, but<br>slowly.</p>\n<p>She made haste to dress herself. The robe was a white one with a<br>white veil,—the garb of a novice of the Hôtel-Dieu.</p>\n<p>She had barely finished when she beheld Quasimodo returning. He<br>carried a basket under one arm and a mattress under the other. In<br>the basket there was a bottle, bread, and some provisions. He set<br>the basket on the floor and said, “Eat!” He spread the mattress<br>on the flagging and said, “Sleep.”</p>\n<p>It was his own repast, it was his own bed, which the bellringer<br>had gone in search of.</p>\n<p>The gypsy raised her eyes to thank him, but she could not<br>articulate a word. She dropped her head with a quiver of terror.</p>\n<p>Then he said to her.—</p>\n<p>“I frighten you. I am very ugly, am I not? Do not look at me;<br>only listen to me. During the day you will remain here; at night<br>you can walk all over the church. But do not leave the church<br>either by day or by night. You would be lost. They would kill<br>you, and I should die.”</p>\n<p>She was touched and raised her head to answer him. He had<br>disappeared. She found herself alone once more, meditating upon<br>the singular words of this almost monstrous being, and struck by<br>the sound of his voice, which was so hoarse yet so gentle.</p>\n<p>Then she examined her cell. It was a chamber about six feet<br>square, with a small window and a door on the slightly sloping<br>plane of the roof formed of flat stones. Many gutters with the<br>figures of animals seemed to be bending down around her, and<br>stretching their necks in order to stare at her through the<br>window. Over the edge of her roof she perceived the tops of<br>thousands of chimneys which caused the smoke of all the fires in<br>Paris to rise beneath her eyes. A sad sight for the poor gypsy, a<br>foundling, condemned to death, an unhappy creature, without<br>country, without family, without a hearthstone.</p>\n<p>At the moment when the thought of her isolation thus appeared to<br>her more poignant than ever, she felt a bearded and hairy head<br>glide between her hands, upon her knees. She started (everything<br>alarmed her now) and looked. It was the poor goat, the agile<br>Djali, which had made its escape after her, at the moment when<br>Quasimodo had put to flight Charmolue’s brigade, and which had<br>been lavishing caresses on her feet for nearly an hour past,<br>without being able to win a glance. The gypsy covered him with<br>kisses.</p>\n<p>“Oh! Djali!” she said, “how I have forgotten thee! And so thou<br>still thinkest of me! Oh! thou art not an ingrate!”</p>\n<p>At the same time, as though an invisible hand had lifted the<br>weight which had repressed her tears in her heart for so long,<br>she began to weep, and, in proportion as her tears flowed, she<br>felt all that was most acrid and bitter in her grief depart with<br>them.</p>\n<p>Evening came, she thought the night so beautiful that she made<br>the circuit of the elevated gallery which surrounds the church.<br>It afforded her some relief, so calm did the earth appear when<br>viewed from that height.</p>\n<h1 class=\"chapter\" id=\"chapter-iii-deaf\">Chapter III. DEAF.</h1>\n<p>On the following morning, she perceived on awaking, that she had<br>been asleep. This singular thing astonished her. She had been so<br>long unaccustomed to sleep! A joyous ray of the rising sun<br>entered through her window and touched her face. At the same time<br>with the sun, she beheld at that window an object which<br>frightened her, the unfortunate face of Quasimodo. She<br>involuntarily closed her eyes again, but in vain; she fancied<br>that she still saw through the rosy lids that gnome’s mask,<br>one-eyed and gap-toothed. Then, while she still kept her eyes<br>closed, she heard a rough voice saying, very gently,—</p>\n<p>“Be not afraid. I am your friend. I came to watch you sleep. It<br>does not hurt you if I come to see you sleep, does it? What<br>difference does it make to you if I am here when your eyes are<br>closed! Now I am going. Stay, I have placed myself behind the<br>wall. You can open your eyes again.”</p>\n<p>There was something more plaintive than these words, and that was<br>the accent in which they were uttered. The gypsy, much touched,<br>opened her eyes. He was, in fact, no longer at the window. She<br>approached the opening, and beheld the poor hunchback crouching<br>in an angle of the wall, in a sad and resigned attitude. She made<br>an effort to surmount the repugnance with which he inspired her.<br>“Come,” she said to him gently. From the movement of the gypsy’s<br>lips, Quasimodo thought that she was driving him away; then he<br>rose and retired limping, slowly, with drooping head, without<br>even daring to raise to the young girl his gaze full of despair.<br>“Do come,” she cried, but he continued to retreat. Then she<br>darted from her cell, ran to him, and grasped his arm. On feeling<br>her touch him, Quasimodo trembled in every limb. He raised his<br>suppliant eye, and seeing that she was leading him back to her<br>quarters, his whole face beamed with joy and tenderness. She<br>tried to make him enter the cell; but he persisted in remaining<br>on the threshold. “No, no,” said he; “the owl enters not the nest<br>of the lark.”</p>\n<p>Then she crouched down gracefully on her couch, with her goat<br>asleep at her feet. Both remained motionless for several moments,<br>considering in silence, she so much grace, he so much ugliness.<br>Every moment she discovered some fresh deformity in Quasimodo.<br>Her glance travelled from his knock knees to his humped back,<br>from his humped back to his only eye. She could not comprehend<br>the existence of a being so awkwardly fashioned. Yet there was so<br>much sadness and so much gentleness spread over all this, that<br>she began to become reconciled to it.</p>\n<p>He was the first to break the silence. “So you were telling me to<br>return?”</p>\n<p>She made an affirmative sign of the head, and said, “Yes.”</p>\n<p>He understood the motion of the head. “Alas!” he said, as though<br>hesitating whether to finish, “I am—I am deaf.”</p>\n<p>“Poor man!” exclaimed the Bohemian, with an expression of kindly<br>pity.</p>\n<p>He began to smile sadly.</p>\n<p>“You think that that was all that I lacked, do you not? Yes, I am<br>deaf, that is the way I am made. ’Tis horrible, is it not? You<br>are so beautiful!”</p>\n<p>There lay in the accents of the wretched man so profound a<br>consciousness of his misery, that she had not the strength to say<br>a word. Besides, he would not have heard her. He went on,—</p>\n<p>“Never have I seen my ugliness as at the present moment. When I<br>compare myself to you, I feel a very great pity for myself, poor<br>unhappy monster that I am! Tell me, I must look to you like a<br>beast. You, you are a ray of sunshine, a drop of dew, the song of<br>a bird! I am something frightful, neither man nor animal, I know<br>not what, harder, more trampled under foot, and more unshapely<br>than a pebble stone!”</p>\n<p>Then he began to laugh, and that laugh was the most heartbreaking<br>thing in the world. He continued,—</p>\n<p>“Yes, I am deaf; but you shall talk to me by gestures, by signs.<br>I have a master who talks with me in that way. And then, I shall<br>very soon know your wish from the movement of your lips, from<br>your look.”</p>\n<p>“Well!” she interposed with a smile, “tell me why you saved me.”</p>\n<p>He watched her attentively while she was speaking.</p>\n<p>“I understand,” he replied. “You ask me why I saved you. You have<br>forgotten a wretch who tried to abduct you one night, a wretch to<br>whom you rendered succor on the following day on their infamous<br>pillory. A drop of water and a little pity,—that is more than I<br>can repay with my life. You have forgotten that wretch; but he<br>remembers it.”</p>\n<p>She listened to him with profound tenderness. A tear swam in the<br>eye of the bellringer, but did not fall. He seemed to make it a<br>sort of point of honor to retain it.</p>\n<p>“Listen,” he resumed, when he was no longer afraid that the tear<br>would escape; “our towers here are very high, a man who should<br>fall from them would be dead before touching the pavement; when<br>it shall please you to have me fall, you will not have to utter<br>even a word, a glance will suffice.”</p>\n<p>Then he rose. Unhappy as was the Bohemian, this eccentric being<br>still aroused some compassion in her. She made him a sign to<br>remain.</p>\n<p>“No, no,” said he; “I must not remain too long. I am not at my<br>ease. It is out of pity that you do not turn away your eyes. I<br>shall go to some place where I can see you without your seeing<br>me: it will be better so.”</p>\n<p>He drew from his pocket a little metal whistle.</p>\n<p>“Here,” said he, “when you have need of me, when you wish me to<br>come, when you will not feel too much horror at the sight of me,<br>use this whistle. I can hear this sound.”</p>\n<p>He laid the whistle on the floor and fled.</p>\n<h1 class=\"chapter\" id=\"chapter-iv-earthenware-and-crystal\">Chapter IV. EARTHENWARE AND CRYSTAL.</h1>\n<p>Day followed day. Calm gradually returned to the soul of la<br>Esmeralda. Excess of grief, like excess of joy is a violent thing<br>which lasts but a short time. The heart of man cannot remain long<br>in one extremity. The gypsy had suffered so much, that nothing<br>was left her but astonishment. With security, hope had returned<br>to her. She was outside the pale of society, outside the pale of<br>life, but she had a vague feeling that it might not be impossible<br>to return to it. She was like a dead person, who should hold in<br>reserve the key to her tomb.</p>\n<p>She felt the terrible images which had so long persecuted her,<br>gradually departing. All the hideous phantoms, Pierrat Torterue,<br>Jacques Charmolue, were effaced from her mind, all, even the<br>priest.</p>\n<p>And then, Phœbus was alive; she was sure of it, she had seen him.<br>To her the fact of Phœbus being alive was everything. After the<br>series of fatal shocks which had overturned everything within<br>her, she had found but one thing intact in her soul, one<br>sentiment,—her love for the captain. Love is like a tree; it<br>sprouts forth of itself, sends its roots out deeply through our<br>whole being, and often continues to flourish greenly over a heart<br>in ruins.</p>\n<p>And the inexplicable point about it is that the more blind is<br>this passion, the more tenacious it is. It is never more solid<br>than when it has no reason in it.</p>\n<p>La Esmeralda did not think of the captain without bitterness, no<br>doubt. No doubt it was terrible that he also should have been<br>deceived; that he should have believed that impossible thing,<br>that he could have conceived of a stab dealt by her who would<br>have given a thousand lives for him. But, after all, she must not<br>be too angry with him for it; had she not confessed her crime?<br>had she not yielded, weak woman that she was, to torture? The<br>fault was entirely hers. She should have allowed her finger nails<br>to be torn out rather than such a word to be wrenched from her.<br>In short, if she could but see Phœbus once more, for a single<br>minute, only one word would be required, one look, in order to<br>undeceive him, to bring him back. She did not doubt it. She was<br>astonished also at many singular things, at the accident of<br>Phœbus’s presence on the day of the penance, at the young girl<br>with whom he had been. She was his sister, no doubt. An<br>unreasonable explanation, but she contented herself with it,<br>because she needed to believe that Phœbus still loved her, and<br>loved her alone. Had he not sworn it to her? What more was<br>needed, simple and credulous as she was? And then, in this<br>matter, were not appearances much more against her than against<br>him? Accordingly, she waited. She hoped.</p>\n<p>Let us add that the church, that vast church, which surrounded<br>her on every side, which guarded her, which saved her, was itself<br>a sovereign tranquillizer. The solemn lines of that architecture,<br>the religious attitude of all the objects which surrounded the<br>young girl, the serene and pious thoughts which emanated, so to<br>speak, from all the pores of that stone, acted upon her without<br>her being aware of it. The edifice had also sounds fraught with<br>such benediction and such majesty, that they soothed this ailing<br>soul. The monotonous chanting of the celebrants, the responses of<br>the people to the priest, sometimes inarticulate, sometimes<br>thunderous, the harmonious trembling of the painted windows, the<br>organ, bursting forth like a hundred trumpets, the three<br>belfries, humming like hives of huge bees, that whole orchestra<br>on which bounded a gigantic scale, ascending, descending<br>incessantly from the voice of a throng to that of one bell,<br>dulled her memory, her imagination, her grief. The bells, in<br>particular, lulled her. It was something like a powerful<br>magnetism which those vast instruments shed over her in great<br>waves.</p>\n<p>Thus every sunrise found her more calm, breathing better, less<br>pale. In proportion as her inward wounds closed, her grace and<br>beauty blossomed once more on her countenance, but more<br>thoughtful, more reposeful. Her former character also returned to<br>her, somewhat even of her gayety, her pretty pout, her love for<br>her goat, her love for singing, her modesty. She took care to<br>dress herself in the morning in the corner of her cell for fear<br>some inhabitants of the neighboring attics might see her through<br>the window.</p>\n<p>When the thought of Phœbus left her time, the gypsy sometimes<br>thought of Quasimodo. He was the sole bond, the sole connection,<br>the sole communication which remained to her with men, with the<br>living. Unfortunate girl! she was more outside the world than<br>Quasimodo. She understood not in the least the strange friend<br>whom chance had given her. She often reproached herself for not<br>feeling a gratitude which should close her eyes, but decidedly,<br>she could not accustom herself to the poor bellringer. He was too<br>ugly.</p>\n<p>She had left the whistle which he had given her lying on the<br>ground. This did not prevent Quasimodo from making his appearance<br>from time to time during the first few days. She did her best not<br>to turn aside with too much repugnance when he came to bring her<br>her basket of provisions or her jug of water, but he always<br>perceived the slightest movement of this sort, and then he<br>withdrew sadly.</p>\n<p>Once he came at the moment when she was caressing Djali. He stood<br>pensively for several minutes before this graceful group of the<br>goat and the gypsy; at last he said, shaking his heavy and<br>ill-formed head,—</p>\n<p>“My misfortune is that I still resemble a man too much. I should<br>like to be wholly a beast like that goat.”</p>\n<p>She gazed at him in amazement.</p>\n<p>He replied to the glance,—</p>\n<p>“Oh! I well know why,” and he went away.</p>\n<p>On another occasion he presented himself at the door of the cell<br>(which he never entered) at the moment when la Esmeralda was<br>singing an old Spanish ballad, the words of which she did not<br>understand, but which had lingered in her ear because the gypsy<br>women had lulled her to sleep with it when she was a little<br>child. At the sight of that villanous form which made its<br>appearance so abruptly in the middle of her song, the young girl<br>paused with an involuntary gesture of alarm. The unhappy<br>bellringer fell upon his knees on the threshold, and clasped his<br>large, misshapen hands with a suppliant air. “Oh!” he said,<br>sorrowfully, “continue, I implore you, and do not drive me away.”<br>She did not wish to pain him, and resumed her lay, trembling all<br>over. By degrees, however, her terror disappeared, and she<br>yielded herself wholly to the slow and melancholy air which she<br>was singing. He remained on his knees with hands clasped, as in<br>prayer, attentive, hardly breathing, his gaze riveted upon the<br>gypsy’s brilliant eyes.</p>\n<p>On another occasion, he came to her with an awkward and timid<br>air. “Listen,” he said, with an effort; “I have something to say<br>to you.” She made him a sign that she was listening. Then he<br>began to sigh, half opened his lips, appeared for a moment to be<br>on the point of speaking, then he looked at her again, shook his<br>head, and withdrew slowly, with his brow in his hand, leaving the<br>gypsy stupefied. Among the grotesque personages sculptured on the<br>wall, there was one to whom he was particularly attached, and<br>with which he often seemed to exchange fraternal glances. Once<br>the gypsy heard him saying to it,—</p>\n<p>“Oh! why am not I of stone, like you!”</p>\n<p>At last, one morning, la Esmeralda had advanced to the edge of<br>the roof, and was looking into the Place over the pointed roof of<br>Saint-Jean le Rond. Quasimodo was standing behind her. He had<br>placed himself in that position in order to spare the young girl,<br>as far as possible, the displeasure of seeing him. All at once<br>the gypsy started, a tear and a flash of joy gleamed<br>simultaneously in her eyes, she knelt on the brink of the roof<br>and extended her arms towards the Place with anguish, exclaiming:<br>“Phœbus! come! come! a word, a single word in the name of heaven!<br>Phœbus! Phœbus!” Her voice, her face, her gesture, her whole<br>person bore the heartrending expression of a shipwrecked man who<br>is making a signal of distress to the joyous vessel which is<br>passing afar off in a ray of sunlight on the horizon.</p>\n<p>Quasimodo leaned over the Place, and saw that the object of this<br>tender and agonizing prayer was a young man, a captain, a<br>handsome cavalier all glittering with arms and decorations,<br>prancing across the end of the Place, and saluting with his plume<br>a beautiful lady who was smiling at him from her balcony.<br>However, the officer did not hear the unhappy girl calling him;<br>he was too far away.</p>\n<p>But the poor deaf man heard. A profound sigh heaved his breast;<br>he turned round; his heart was swollen with all the tears which<br>he was swallowing; his convulsively-clenched fists struck against<br>his head, and when he withdrew them there was a bunch of red hair<br>in each hand.</p>\n<p>The gypsy paid no heed to him. He said in a low voice as he<br>gnashed his teeth,—</p>\n<p>“Damnation! That is what one should be like! ’Tis only necessary<br>to be handsome on the outside!”</p>\n<p>Meanwhile, she remained kneeling, and cried with extraordinary<br>agitation,—</p>\n<p>“Oh! there he is alighting from his horse! He is about to enter<br>that house!—Phœbus!—He does not hear me! Phœbus!—How wicked that<br>woman is to speak to him at the same time with me! Phœbus!<br>Phœbus!”</p>\n<p>The deaf man gazed at her. He understood this pantomime. The poor<br>bellringer’s eye filled with tears, but he let none fall. All at<br>once he pulled her gently by the border of her sleeve. She turned<br>round. He had assumed a tranquil air; he said to her,—</p>\n<p>“Would you like to have me bring him to you?”</p>\n<p>She uttered a cry of joy.</p>\n<p>“Oh! go! hasten! run! quick! that captain! that captain! bring<br>him to me! I will love you for it!”</p>\n<p>She clasped his knees. He could not refrain from shaking his head<br>sadly.</p>\n<p>“I will bring him to you,” he said, in a weak voice. Then he<br>turned his head and plunged down the staircase with great<br>strides, stifling with sobs.</p>\n<p>When he reached the Place, he no longer saw anything except the<br>handsome horse hitched at the door of the Gondelaurier house; the<br>captain had just entered there.</p>\n<p>He raised his eyes to the roof of the church. La Esmeralda was<br>there in the same spot, in the same attitude. He made her a sad<br>sign with his head; then he planted his back against one of the<br>stone posts of the Gondelaurier porch, determined to wait until<br>the captain should come forth.</p>\n<p>In the Gondelaurier house it was one of those gala days which<br>precede a wedding. Quasimodo beheld many people enter, but no one<br>come out. He cast a glance towards the roof from time to time;<br>the gypsy did not stir any more than himself. A groom came and<br>unhitched the horse and led it to the stable of the house.</p>\n<p>The entire day passed thus, Quasimodo at his post, la Esmeralda<br>on the roof, Phœbus, no doubt, at the feet of Fleur-de-Lys.</p>\n<p>At length night came, a moonless night, a dark night. Quasimodo<br>fixed his gaze in vain upon la Esmeralda; soon she was no more<br>than a whiteness amid the twilight; then nothing. All was<br>effaced, all was black.</p>\n<p>Quasimodo beheld the front windows from top to bottom of the<br>Gondelaurier mansion illuminated; he saw the other casements in<br>the Place lighted one by one, he also saw them extinguished to<br>the very last, for he remained the whole evening at his post. The<br>officer did not come forth. When the last passers-by had returned<br>home, when the windows of all the other houses were extinguished,<br>Quasimodo was left entirely alone, entirely in the dark. There<br>were at that time no lamps in the square before Notre-Dame.</p>\n<p>Meanwhile, the windows of the Gondelaurier mansion remained<br>lighted, even after midnight. Quasimodo, motionless and<br>attentive, beheld a throng of lively, dancing shadows pass<br>athwart the many-colored painted panes. Had he not been deaf, he<br>would have heard more and more distinctly, in proportion as the<br>noise of sleeping Paris died away, a sound of feasting, laughter,<br>and music in the Gondelaurier mansion.</p>\n<p>Towards one o’clock in the morning, the guests began to take<br>their leave. Quasimodo, shrouded in darkness watched them all<br>pass out through the porch illuminated with torches. None of them<br>was the captain.</p>\n<p>He was filled with sad thoughts; at times he looked upwards into<br>the air, like a person who is weary of waiting. Great black<br>clouds, heavy, torn, split, hung like crape hammocks beneath the<br>starry dome of night. One would have pronounced them spiders’<br>webs of the vault of heaven.</p>\n<p>In one of these moments he suddenly beheld the long window on the<br>balcony, whose stone balustrade projected above his head, open<br>mysteriously. The frail glass door gave passage to two persons,<br>and closed noiselessly behind them; it was a man and a woman.</p>\n<p>It was not without difficulty that Quasimodo succeeded in<br>recognizing in the man the handsome captain, in the woman the<br>young lady whom he had seen welcome the officer in the morning<br>from that very balcony. The place was perfectly dark, and a<br>double crimson curtain which had fallen across the door the very<br>moment it closed again, allowed no light to reach the balcony<br>from the apartment.</p>\n<p>The young man and the young girl, so far as our deaf man could<br>judge, without hearing a single one of their words, appeared to<br>abandon themselves to a very tender tête-à-tête. The young girl<br>seemed to have allowed the officer to make a girdle for her of<br>his arm, and gently repulsed a kiss.</p>\n<p>Quasimodo looked on from below at this scene which was all the<br>more pleasing to witness because it was not meant to be seen. He<br>contemplated with bitterness that beauty, that happiness. After<br>all, nature was not dumb in the poor fellow, and his human<br>sensibility, all maliciously contorted as it was, quivered no<br>less than any other. He thought of the miserable portion which<br>Providence had allotted to him; that woman and the pleasure of<br>love, would pass forever before his eyes, and that he should<br>never do anything but behold the felicity of others. But that<br>which rent his heart most in this sight, that which mingled<br>indignation with his anger, was the thought of what the gypsy<br>would suffer could she behold it. It is true that the night was<br>very dark, that la Esmeralda, if she had remained at her post<br>(and he had no doubt of this), was very far away, and that it was<br>all that he himself could do to distinguish the lovers on the<br>balcony. This consoled him.</p>\n<p>Meanwhile, their conversation grew more and more animated. The<br>young lady appeared to be entreating the officer to ask nothing<br>more of her. Of all this Quasimodo could distinguish only the<br>beautiful clasped hands, the smiles mingled with tears, the young<br>girl’s glances directed to the stars, the eyes of the captain<br>lowered ardently upon her.</p>\n<p>Fortunately, for the young girl was beginning to resist but<br>feebly, the door of the balcony suddenly opened once more and an<br>old dame appeared; the beauty seemed confused, the officer<br>assumed an air of displeasure, and all three withdrew.</p>\n<p>A moment later, a horse was champing his bit under the porch, and<br>the brilliant officer, enveloped in his night cloak, passed<br>rapidly before Quasimodo.</p>\n<p>The bellringer allowed him to turn the corner of the street, then<br>he ran after him with his ape-like agility, shouting: “Hey there!<br>captain!”</p>\n<p>The captain halted.</p>\n<p>“What wants this knave with me?” he said, catching sight through<br>the gloom of that hipshot form which ran limping after him.</p>\n<p>Meanwhile, Quasimodo had caught up with him, and had boldly<br>grasped his horse’s bridle: “Follow me, captain; there is one<br>here who desires to speak with you!</p>\n<p>“<em>Cornemahom</em>!” grumbled Phœbus, “here’s a villanous; ruffled<br>bird which I fancy I have seen somewhere. Holà master, will you<br>let my horse’s bridle alone?”</p>\n<p>“Captain,” replied the deaf man, “do you not ask me who it is?”</p>\n<p>“I tell you to release my horse,” retorted Phœbus, impatiently.<br>“What means the knave by clinging to the bridle of my steed? Do<br>you take my horse for a gallows?”</p>\n<p>Quasimodo, far from releasing the bridle, prepared to force him<br>to retrace his steps. Unable to comprehend the captain’s<br>resistance, he hastened to say to him,—</p>\n<p>“Come, captain, ’tis a woman who is waiting for you.” He added<br>with an effort: “A woman who loves you.”</p>\n<p>“A rare rascal!” said the captain, “who thinks me obliged to go<br>to all the women who love me! or who say they do. And what if, by<br>chance, she should resemble you, you face of a screech-owl? Tell<br>the woman who has sent you that I am about to marry, and that she<br>may go to the devil!”</p>\n<p>“Listen,” exclaimed Quasimodo, thinking to overcome his<br>hesitation with a word, “come, monseigneur! ’tis the gypsy whom<br>you know!”</p>\n<p>This word did, indeed, produce a great effect on Phœbus, but not<br>of the kind which the deaf man expected. It will be remembered<br>that our gallant officer had retired with Fleur-de-Lys several<br>moments before Quasimodo had rescued the condemned girl from the<br>hands of Charmolue. Afterwards, in all his visits to the<br>Gondelaurier mansion he had taken care not to mention that woman,<br>the memory of whom was, after all, painful to him; and on her<br>side, Fleur-de-Lys had not deemed it politic to tell him that the<br>gypsy was alive. Hence Phœbus believed poor “Similar” to be dead,<br>and that a month or two had elapsed since her death. Let us add<br>that for the last few moments the captain had been reflecting on<br>the profound darkness of the night, the supernatural ugliness,<br>the sepulchral voice of the strange messenger; that it was past<br>midnight; that the street was deserted, as on the evening when<br>the surly monk had accosted him; and that his horse snorted as it<br>looked at Quasimodo.</p>\n<p>“The gypsy!” he exclaimed, almost frightened. “Look here, do you<br>come from the other world?”</p>\n<p>And he laid his hand on the hilt of his dagger.</p>\n<p>“Quick, quick,” said the deaf man, endeavoring to drag the horse<br>along; “this way!”</p>\n<p>Phœbus dealt him a vigorous kick in the breast.</p>\n<p>Quasimodo’s eye flashed. He made a motion to fling himself on the<br>captain. Then he drew himself up stiffly and said,—</p>\n<p>“Oh! how happy you are to have some one who loves you!”</p>\n<p>He emphasized the words “some one,” and loosing the horse’s<br>bridle,—</p>\n<p>“Begone!”</p>\n<p>Phœbus spurred on in all haste, swearing. Quasimodo watched him<br>disappear in the shades of the street.</p>\n<p>“Oh!” said the poor deaf man, in a very low voice; “to refuse<br>that!”</p>\n<p>He re-entered Notre-Dame, lighted his lamp and climbed to the<br>tower again. The gypsy was still in the same place, as he had<br>supposed.</p>\n<p>She flew to meet him as far off as she could see him. “Alone!”<br>she cried, clasping her beautiful hands sorrowfully.</p>\n<p>“I could not find him,” said Quasimodo coldly.</p>\n<p>“You should have waited all night,” she said angrily.</p>\n<p>He saw her gesture of wrath, and understood the reproach.</p>\n<p>“I will lie in wait for him better another time,” he said,<br>dropping his head.</p>\n<p>“Begone!” she said to him.</p>\n<p>He left her. She was displeased with him. He preferred to have<br>her abuse him rather than to have afflicted her. He had kept all<br>the pain to himself.</p>\n<p>From that day forth, the gypsy no longer saw him. He ceased to<br>come to her cell. At the most she occasionally caught a glimpse<br>at the summit of the towers, of the bellringer’s face turned<br>sadly to her. But as soon as she perceived him, he disappeared.</p>\n<p>We must admit that she was not much grieved by this voluntary<br>absence on the part of the poor hunchback. At the bottom of her<br>heart she was grateful to him for it. Moreover, Quasimodo did not<br>deceive himself on this point.</p>\n<p>She no longer saw him, but she felt the presence of a good genius<br>about her. Her provisions were replenished by an invisible hand<br>during her slumbers. One morning she found a cage of birds on her<br>window. There was a piece of sculpture above her window which<br>frightened her. She had shown this more than once in Quasimodo’s<br>presence. One morning, for all these things happened at night,<br>she no longer saw it, it had been broken. The person who had<br>climbed up to that carving must have risked his life.</p>\n<p>Sometimes, in the evening, she heard a voice, concealed beneath<br>the wind screen of the bell tower, singing a sad, strange song,<br>as though to lull her to sleep. The lines were unrhymed, such as<br>a deaf person can make.</p>\n<p>Ne regarde pas la figure,<br>Jeune fille, regarde le cœur.<br>Le cœur d’un beau jeune homme est souvent difforme.<br>Il y a des cœurs où l’amour ne se conserve pas.</p>\n<p>Jeune fille, le sapin n’est pas beau,<br>N’est pas beau comme le peuplier,<br>Mais il garde son feuillage l’hiver.</p>\n<p>Hélas! à quoi bon dire cela?<br>Ce qui n’est pas beau a tort d’être;<br>La beauté n’aime que la beauté,<br>Avril tourne le dos à janvier.</p>\n<p>La beauté est parfaite,<br>La beauté peut tout,<br>La beauté est la seule chose qui n’existe pas à demi.</p>\n<p>Le corbeau ne vole que le jour,<br>Le hibou ne vole que la nuit,<br>Le cygne vole la nuit et le jour.[52]</p>\n<p>One morning, on awaking, she saw on her window two vases filled<br>with flowers. One was a very beautiful and very brilliant but<br>cracked vase of glass. It had allowed the water with which it had<br>been filled to escape, and the flowers which it contained were<br>withered. The other was an earthenware pot, coarse and common,<br>but which had preserved all its water, and its flowers remained<br>fresh and crimson.</p>\n<p>I know not whether it was done intentionally, but La Esmeralda<br>took the faded nosegay and wore it all day long upon her breast.</p>\n<p>That day she did not hear the voice singing in the tower.</p>\n<p>She troubled herself very little about it. She passed her days in<br>caressing Djali, in watching the door of the Gondelaurier house,<br>in talking to herself about Phœbus, and in crumbling up her bread<br>for the swallows.</p>\n<p>She had entirely ceased to see or hear Quasimodo. The poor<br>bellringer seemed to have disappeared from the church. One night,<br>nevertheless, when she was not asleep, but was thinking of her<br>handsome captain, she heard something breathing near her cell.<br>She rose in alarm, and saw by the light of the moon, a shapeless<br>mass lying across her door on the outside. It was Quasimodo<br>asleep there upon the stones.</p>\n<h1 class=\"chapter\" id=\"chapter-v-the-key-to-the-red-door\">Chapter V. THE KEY TO THE RED DOOR.</h1>\n<p>In the meantime, public rumor had informed the archdeacon of the<br>miraculous manner in which the gypsy had been saved. When he<br>learned it, he knew not what his sensations were. He had<br>reconciled himself to la Esmeralda’s death. In that matter he was<br>tranquil; he had reached the bottom of personal suffering. The<br>human heart (Dom Claude had meditated upon these matters) can<br>contain only a certain quantity of despair. When the sponge is<br>saturated, the sea may pass over it without causing a single drop<br>more to enter it.</p>\n<p>Now, with la Esmeralda dead, the sponge was soaked, all was at an<br>end on this earth for Dom Claude. But to feel that she was alive,<br>and Phœbus also, meant that tortures, shocks, alternatives, life,<br>were beginning again. And Claude was weary of all this.</p>\n<p>When he heard this news, he shut himself in his cell in the<br>cloister. He appeared neither at the meetings of the chapter nor<br>at the services. He closed his door against all, even against the<br>bishop. He remained thus immured for several weeks. He was<br>believed to be ill. And so he was, in fact.</p>\n<p>What did he do while thus shut up? With what thoughts was the<br>unfortunate man contending? Was he giving final battle to his<br>formidable passion? Was he concocting a final plan of death for<br>her and of perdition for himself?</p>\n<p>His Jehan, his cherished brother, his spoiled child, came once to<br>his door, knocked, swore, entreated, gave his name half a score<br>of times. Claude did not open.</p>\n<p>He passed whole days with his face close to the panes of his<br>window. From that window, situated in the cloister, he could see<br>la Esmeralda’s chamber. He often saw herself with her goat,<br>sometimes with Quasimodo. He remarked the little attentions of<br>the ugly deaf man, his obedience, his delicate and submissive<br>ways with the gypsy. He recalled, for he had a good memory, and<br>memory is the tormentor of the jealous, he recalled the singular<br>look of the bellringer, bent on the dancer upon a certain<br>evening. He asked himself what motive could have impelled<br>Quasimodo to save her. He was the witness of a thousand little<br>scenes between the gypsy and the deaf man, the pantomime of<br>which, viewed from afar and commented on by his passion, appeared<br>very tender to him. He distrusted the capriciousness of women.<br>Then he felt a jealousy which he could never have believed<br>possible awakening within him, a jealousy which made him redden<br>with shame and indignation: “One might condone the captain, but<br>this one!” This thought upset him.</p>\n<p>His nights were frightful. As soon as he learned that the gypsy<br>was alive, the cold ideas of spectre and tomb which had<br>persecuted him for a whole day vanished, and the flesh returned<br>to goad him. He turned and twisted on his couch at the thought<br>that the dark-skinned maiden was so near him.</p>\n<p>Every night his delirious imagination represented la Esmeralda to<br>him in all the attitudes which had caused his blood to boil most.<br>He beheld her outstretched upon the poniarded captain, her eyes<br>closed, her beautiful bare throat covered with Phœbus’s blood, at<br>that moment of bliss when the archdeacon had imprinted on her<br>pale lips that kiss whose burn the unhappy girl, though half<br>dead, had felt. He beheld her, again, stripped by the savage<br>hands of the torturers, allowing them to bare and to enclose in<br>the boot with its iron screw, her tiny foot, her delicate rounded<br>leg, her white and supple knee. Again he beheld that ivory knee<br>which alone remained outside of Torterue’s horrible apparatus.<br>Lastly, he pictured the young girl in her shift, with the rope<br>about her neck, shoulders bare, feet bare, almost nude, as he had<br>seen her on that last day. These images of voluptuousness made<br>him clench his fists, and a shiver run along his spine.</p>\n<p>One night, among others, they heated so cruelly his virgin and<br>priestly blood, that he bit his pillow, leaped from his bed,<br>flung on a surplice over his shirt, and left his cell, lamp in<br>hand, half naked, wild, his eyes aflame.</p>\n<p>He knew where to find the key to the red door, which connected<br>the cloister with the church, and he always had about him, as the<br>reader knows, the key of the staircase leading to the towers.</p>\n<h1 class=\"chapter\" id=\"chapter-vi-continuation-of-the-key-to-the-red-do\">Chapter VI. CONTINUATION OF THE KEY TO THE RED DOOR.</h1>\n<p>That night, la Esmeralda had fallen asleep in her cell, full of<br>oblivion, of hope, and of sweet thoughts. She had already been<br>asleep for some time, dreaming as always, of Phœbus, when it<br>seemed to her that she heard a noise near her. She slept lightly<br>and uneasily, the sleep of a bird; a mere nothing waked her. She<br>opened her eyes. The night was very dark. Nevertheless, she saw a<br>figure gazing at her through the window; a lamp lighted up this<br>apparition. The moment that the figure saw that la Esmeralda had<br>perceived it, it blew out the lamp. But the young girl had had<br>time to catch a glimpse of it; her eyes closed again with terror.</p>\n<p>“Oh!” she said in a faint voice, “the priest!”</p>\n<p>All her past unhappiness came back to her like a flash of<br>lightning. She fell back on her bed, chilled.</p>\n<p>A moment later she felt a touch along her body which made her<br>shudder so that she straightened herself up in a sitting posture,<br>wide awake and furious.</p>\n<p>The priest had just slipped in beside her. He encircled her with<br>both arms.</p>\n<p>She tried to scream and could not.</p>\n<p>“Begone, monster! begone assassin!” she said, in a voice which<br>was low and trembling with wrath and terror.</p>\n<p>“Mercy! mercy!” murmured the priest, pressing his lips to her<br>shoulder.</p>\n<p>She seized his bald head by its remnant of hair and tried to<br>thrust aside his kisses as though they had been bites.</p>\n<p>“Mercy!” repeated the unfortunate man. “If you but knew what my<br>love for you is! ’Tis fire, melted lead, a thousand daggers in my<br>heart.”</p>\n<p>She stopped his two arms with superhuman force.</p>\n<p>“Let me go,” she said, “or I will spit in your face!”</p>\n<p>He released her. “Vilify me, strike me, be malicious! Do what you<br>will! But have mercy! love me!”</p>\n<p>Then she struck him with the fury of a child. She made her<br>beautiful hands stiff to bruise his face. “Begone, demon!”</p>\n<p>“Love me! love me! pity!” cried the poor priest returning her<br>blows with caresses.</p>\n<p>All at once she felt him stronger than herself.</p>\n<p>“There must be an end to this!” he said, gnashing his teeth.</p>\n<p>She was conquered, palpitating in his arms, and in his power. She<br>felt a wanton hand straying over her. She made a last effort, and<br>began to cry: “Help! Help! A vampire! a vampire!”</p>\n<p>Nothing came. Djali alone was awake and bleating with anguish.</p>\n<p>“Hush!” said the panting priest.</p>\n<p>All at once, as she struggled and crawled on the floor, the<br>gypsy’s hand came in contact with something cold and metallic—it<br>was Quasimodo’s whistle. She seized it with a convulsive hope,<br>raised it to her lips and blew with all the strength that she had<br>left. The whistle gave a clear, piercing sound.</p>\n<p>“What is that?” said the priest.</p>\n<p>Almost at the same instant he felt himself raised by a vigorous<br>arm. The cell was dark; he could not distinguish clearly who it<br>was that held him thus; but he heard teeth chattering with rage,<br>and there was just sufficient light scattered among the gloom to<br>allow him to see above his head the blade of a large knife.</p>\n<p>The priest fancied that he perceived the form of Quasimodo. He<br>assumed that it could be no one but he. He remembered to have<br>stumbled, as he entered, over a bundle which was stretched across<br>the door on the outside. But, as the newcomer did not utter a<br>word, he knew not what to think. He flung himself on the arm<br>which held the knife, crying: “Quasimodo!” He forgot, at that<br>moment of distress, that Quasimodo was deaf.</p>\n<p>In a twinkling, the priest was overthrown and a leaden knee<br>rested on his breast.</p>\n<p>From the angular imprint of that knee he recognized Quasimodo;<br>but what was to be done? how could he make the other recognize<br>him? the darkness rendered the deaf man blind.</p>\n<p>He was lost. The young girl, pitiless as an enraged tigress, did<br>not intervene to save him. The knife was approaching his head;<br>the moment was critical. All at once, his adversary seemed<br>stricken with hesitation.</p>\n<p>“No blood on her!” he said in a dull voice.</p>\n<p>It was, in fact, Quasimodo’s voice.</p>\n<p>Then the priest felt a large hand dragging him feet first out of<br>the cell; it was there that he was to die. Fortunately for him,<br>the moon had risen a few moments before.</p>\n<p>When they had passed through the door of the cell, its pale rays<br>fell upon the priest’s countenance. Quasimodo looked him full in<br>the face, a trembling seized him, and he released the priest and<br>shrank back.</p>\n<p>The gypsy, who had advanced to the threshold of her cell, beheld<br>with surprise their roles abruptly changed. It was now the priest<br>who menaced, Quasimodo who was the suppliant.</p>\n<p>The priest, who was overwhelming the deaf man with gestures of<br>wrath and reproach, made the latter a violent sign to retire.</p>\n<p>The deaf man dropped his head, then he came and knelt at the<br>gypsy’s door,—“Monseigneur,” he said, in a grave and resigned<br>voice, “you shall do all that you please afterwards, but kill me<br>first.”</p>\n<p>So saying, he presented his knife to the priest. The priest,<br>beside himself, was about to seize it. But the young girl was<br>quicker than he; she wrenched the knife from Quasimodo’s hands<br>and burst into a frantic laugh,—“Approach,” she said to the<br>priest.</p>\n<p>She held the blade high. The priest remained undecided.</p>\n<p>She would certainly have struck him.</p>\n<p>Then she added with a pitiless expression, well aware that she<br>was about to pierce the priest’s heart with thousands of red-hot<br>irons,—</p>\n<p>“Ah! I know that Phœbus is not dead!”</p>\n<p>The priest overturned Quasimodo on the floor with a kick, and,<br>quivering with rage, darted back under the vault of the<br>staircase.</p>\n<p>When he was gone, Quasimodo picked up the whistle which had just<br>saved the gypsy.</p>\n<p>“It was getting rusty,” he said, as he handed it back to her;<br>then he left her alone.</p>\n<p>The young girl, deeply agitated by this violent scene, fell back<br>exhausted on her bed, and began to sob and weep. Her horizon was<br>becoming gloomy once more.</p>\n<p>The priest had groped his way back to his cell.</p>\n<p>It was settled. Dom Claude was jealous of Quasimodo!</p>\n<p>He repeated with a thoughtful air his fatal words: “No one shall<br>have her.”</p>\n<p>BOOK TENTH.</p>\n<h1 class=\"chapter\" id=\"chapter-i-gringoire-has-many-good-ideas-in-succe\">Chapter I. GRINGOIRE HAS MANY GOOD IDEAS IN SUCCESSION.—RUE DES</h1>\n<p>BERNARDINS.</p>\n<p>As soon as Pierre Gringoire had seen how this whole affair was<br>turning, and that there would decidedly be the rope, hanging, and<br>other disagreeable things for the principal personages in this<br>comedy, he had not cared to identify himself with the matter<br>further. The outcasts with whom he had remained, reflecting that,<br>after all, it was the best company in Paris,—the outcasts had<br>continued to interest themselves in behalf of the gypsy. He had<br>thought it very simple on the part of people who had, like<br>herself, nothing else in prospect but Charmolue and Torterue, and<br>who, unlike himself, did not gallop through the regions of<br>imagination between the wings of Pegasus. From their remarks, he<br>had learned that his wife of the broken crock had taken refuge in<br>Notre-Dame, and he was very glad of it. But he felt no temptation<br>to go and see her there. He meditated occasionally on the little<br>goat, and that was all. Moreover, he was busy executing feats of<br>strength during the day for his living, and at night he was<br>engaged in composing a memorial against the Bishop of Paris, for<br>he remembered having been drenched by the wheels of his mills,<br>and he cherished a grudge against him for it. He also occupied<br>himself with annotating the fine work of Baudry-le-Rouge, Bishop<br>of Noyon and Tournay, <em>De Cupa Petrarum</em>, which had given him a<br>violent passion for architecture, an inclination which had<br>replaced in his heart his passion for hermeticism, of which it<br>was, moreover, only a natural corollary, since there is an<br>intimate relation between hermeticism and masonry. Gringoire had<br>passed from the love of an idea to the love of the form of that<br>idea.</p>\n<p>One day he had halted near Saint Germain-l’Auxerrois, at the<br>corner of a mansion called “For-l’Évêque” (the Bishop’s<br>Tribunal), which stood opposite another called “For-le-Roi” (the<br>King’s Tribunal). At this For-l’Évêque, there was a charming<br>chapel of the fourteenth century, whose apse was on the street.<br>Gringoire was devoutly examining its exterior sculptures. He was<br>in one of those moments of egotistical, exclusive, supreme,<br>enjoyment when the artist beholds nothing in the world but art,<br>and the world in art. All at once he feels a hand laid gravely on<br>his shoulder. He turns round. It was his old friend, his former<br>master, monsieur the archdeacon.</p>\n<p>He was stupefied. It was a long time since he had seen the<br>archdeacon, and Dom Claude was one of those solemn and<br>impassioned men, a meeting with whom always upsets the<br>equilibrium of a sceptical philosopher.</p>\n<p>The archdeacon maintained silence for several minutes, during<br>which Gringoire had time to observe him. He found Dom Claude<br>greatly changed; pale as a winter’s morning, with hollow eyes,<br>and hair almost white. The priest broke the silence at length, by<br>saying, in a tranquil but glacial tone,—</p>\n<p>“How do you do, Master Pierre?”</p>\n<p>“My health?” replied Gringoire. “Eh! eh! one can say both one<br>thing and another on that score. Still, it is good, on the whole.<br>I take not too much of anything. You know, master, that the<br>secret of keeping well, according to Hippocrates; _id est: cibi,<br>potus, somni, venus, omnia moderata sint_.”</p>\n<p>“So you have no care, Master Pierre?” resumed the archdeacon,<br>gazing intently at Gringoire.</p>\n<p>“None, i’ faith!”</p>\n<p>“And what are you doing now?”</p>\n<p>“You see, master. I am examining the chiselling of these stones,<br>and the manner in which yonder bas-relief is thrown out.”</p>\n<p>The priest began to smile with that bitter smile which raises<br>only one corner of the mouth.</p>\n<p>“And that amuses you?”</p>\n<p>“’Tis paradise!” exclaimed Gringoire. And leaning over the<br>sculptures with the fascinated air of a demonstrator of living<br>phenomena: “Do you not think, for instance, that yon<br>metamorphosis in bas-relief is executed with much adroitness,<br>delicacy and patience? Observe that slender column. Around what<br>capital have you seen foliage more tender and better caressed by<br>the chisel. Here are three raised bosses of Jean Maillevin. They<br>are not the finest works of this great master. Nevertheless, the<br>naïvete, the sweetness of the faces, the gayety of the attitudes<br>and draperies, and that inexplicable charm which is mingled with<br>all the defects, render the little figures very diverting and<br>delicate, perchance, even too much so. You think that it is not<br>diverting?”</p>\n<p>“Yes, certainly!” said the priest.</p>\n<p>“And if you were to see the interior of the chapel!” resumed the<br>poet, with his garrulous enthusiasm. “Carvings everywhere. ’Tis<br>as thickly clustered as the head of a cabbage! The apse is of a<br>very devout, and so peculiar a fashion that I have never beheld<br>anything like it elsewhere!”</p>\n<p>Dom Claude interrupted him,—</p>\n<p>“You are happy, then?”</p>\n<p>Gringoire replied warmly;—</p>\n<p>“On my honor, yes! First I loved women, then animals. Now I love<br>stones. They are quite as amusing as women and animals, and less<br>treacherous.”</p>\n<p>The priest laid his hand on his brow. It was his habitual<br>gesture.</p>\n<p>“Really?”</p>\n<p>“Stay!” said Gringoire, “one has one’s pleasures!” He took the<br>arm of the priest, who let him have his way, and made him enter<br>the staircase turret of For-l’Évêque. “Here is a staircase! every<br>time that I see it I am happy. It is of the simplest and rarest<br>manner of steps in Paris. All the steps are bevelled underneath.<br>Its beauty and simplicity consist in the interspacing of both,<br>being a foot or more wide, which are interlaced, interlocked,<br>fitted together, enchained enchased, interlined one upon another,<br>and bite into each other in a manner that is truly firm and<br>graceful.”</p>\n<p>“And you desire nothing?”</p>\n<p>“No.”</p>\n<p>“And you regret nothing?”</p>\n<p>“Neither regret nor desire. I have arranged my mode of life.”</p>\n<p>“What men arrange,” said Claude, “things disarrange.”</p>\n<p>“I am a Pyrrhonian philosopher,” replied Gringoire, “and I hold<br>all things in equilibrium.”</p>\n<p>“And how do you earn your living?”</p>\n<p>“I still make epics and tragedies now and then; but that which<br>brings me in most is the industry with which you are acquainted,<br>master; carrying pyramids of chairs in my teeth.”</p>\n<p>“The trade is but a rough one for a philosopher.”</p>\n<p>“’Tis still equilibrium,” said Gringoire. “When one has an idea,<br>one encounters it in everything.”</p>\n<p>“I know that,” replied the archdeacon.</p>\n<p>After a silence, the priest resumed,—</p>\n<p>“You are, nevertheless, tolerably poor?”</p>\n<p>“Poor, yes; unhappy, no.”</p>\n<p>At that moment, a trampling of horses was heard, and our two<br>interlocutors beheld defiling at the end of the street, a company<br>of the king’s unattached archers, their lances borne high, an<br>officer at their head. The cavalcade was brilliant, and its march<br>resounded on the pavement.</p>\n<p>“How you gaze at that officer!” said Gringoire, to the<br>archdeacon.</p>\n<p>“Because I think I recognize him.”</p>\n<p>“What do you call him?”</p>\n<p>“I think,” said Claude, “that his name is Phœbus de Châteaupers.”</p>\n<p>“Phœbus! A curious name! There is also a Phœbus, Comte de Foix. I<br>remember having known a wench who swore only by the name of<br>Phœbus.”</p>\n<p>“Come away from here,” said the priest. “I have something to say<br>to you.”</p>\n<p>From the moment of that troop’s passing, some agitation had<br>pierced through the archdeacon’s glacial envelope. He walked on.<br>Gringoire followed him, being accustomed to obey him, like all<br>who had once approached that man so full of ascendency. They<br>reached in silence the Rue des Bernardins, which was nearly<br>deserted. Here Dom Claude paused.</p>\n<p>“What have you to say to me, master?” Gringoire asked him.</p>\n<p>“Do you not think that the dress of those cavaliers whom we have<br>just seen is far handsomer than yours and mine?”</p>\n<p>Gringoire tossed his head.</p>\n<p>“I’ faith! I love better my red and yellow jerkin, than those<br>scales of iron and steel. A fine pleasure to produce, when you<br>walk, the same noise as the Quay of Old Iron, in an earthquake!”</p>\n<p>“So, Gringoire, you have never cherished envy for those handsome<br>fellows in their military doublets?”</p>\n<p>“Envy for what, monsieur the archdeacon? their strength, their<br>armor, their discipline? Better philosophy and independence in<br>rags. I prefer to be the head of a fly rather than the tail of a<br>lion.”</p>\n<p>“That is singular,” said the priest dreamily. “Yet a handsome<br>uniform is a beautiful thing.”</p>\n<p>Gringoire, perceiving that he was in a pensive mood, quitted him<br>to go and admire the porch of a neighboring house. He came back<br>clapping his hands.</p>\n<p>“If you were less engrossed with the fine clothes of men of war,<br>monsieur the archdeacon, I would entreat you to come and see this<br>door. I have always said that the house of the Sieur Aubry had<br>the most superb entrance in the world.”</p>\n<p>“Pierre Gringoire,” said the archdeacon, “What have you done with<br>that little gypsy dancer?”</p>\n<p>“La Esmeralda? You change the conversation very abruptly.”</p>\n<p>“Was she not your wife?”</p>\n<p>“Yes, by virtue of a broken crock. We were to have four years of<br>it. By the way,” added Gringoire, looking at the archdeacon in a<br>half bantering way, “are you still thinking of her?”</p>\n<p>“And you think of her no longer?”</p>\n<p>“Very little. I have so many things. Good heavens, how pretty<br>that little goat was!”</p>\n<p>“Had she not saved your life?”</p>\n<p>“’Tis true, pardieu!”</p>\n<p>“Well, what has become of her? What have you done with her?”</p>\n<p>“I cannot tell you. I believe that they have hanged her.”</p>\n<p>“You believe so?”</p>\n<p>“I am not sure. When I saw that they wanted to hang people, I<br>retired from the game.”</p>\n<p>“That is all you know of it?”</p>\n<p>“Wait a bit. I was told that she had taken refuge in Notre-Dame,<br>and that she was safe there, and I am delighted to hear it, and I<br>have not been able to discover whether the goat was saved with<br>her, and that is all I know.”</p>\n<p>“I will tell you more,” cried Dom Claude; and his voice, hitherto<br>low, slow, and almost indistinct, turned to thunder. “She has in<br>fact, taken refuge in Notre-Dame. But in three days justice will<br>reclaim her, and she will be hanged on the Grève. There is a<br>decree of parliament.”</p>\n<p>“That’s annoying,” said Gringoire.</p>\n<p>The priest, in an instant, became cold and calm again.</p>\n<p>“And who the devil,” resumed the poet, “has amused himself with<br>soliciting a decree of reintegration? Why couldn’t they leave<br>parliament in peace? What harm does it do if a poor girl takes<br>shelter under the flying buttresses of Notre-Dame, beside the<br>swallows’ nests?”</p>\n<p>“There are satans in this world,” remarked the archdeacon.</p>\n<p>“’Tis devilish badly done,” observed Gringoire.</p>\n<p>The archdeacon resumed after a silence,—</p>\n<p>“So, she saved your life?”</p>\n<p>“Among my good friends the outcasts. A little more or a little<br>less and I should have been hanged. They would have been sorry<br>for it to-day.”</p>\n<p>“Would not you like to do something for her?”</p>\n<p>“I ask nothing better, Dom Claude; but what if I entangle myself<br>in some villanous affair?”</p>\n<p>“What matters it?”</p>\n<p>“Bah! what matters it? You are good, master, that you are! I have<br>two great works already begun.”</p>\n<p>The priest smote his brow. In spite of the calm which he<br>affected, a violent gesture betrayed his internal convulsions<br>from time to time.</p>\n<p>“How is she to be saved?”</p>\n<p>Gringoire said to him; “Master, I will reply to you; <em>Il padelt</em>,<br>which means in Turkish, ‘God is our hope.’”</p>\n<p>“How is she to be saved?” repeated Claude dreamily.</p>\n<p>Gringoire smote his brow in his turn.</p>\n<p>“Listen, master. I have imagination; I will devise expedients for<br>you. What if one were to ask her pardon from the king?”</p>\n<p>“Of Louis XI.! A pardon!”</p>\n<p>“Why not?”</p>\n<p>“To take the tiger’s bone from him!”</p>\n<p>Gringoire began to seek fresh expedients.</p>\n<p>“Well, stay! Shall I address to the midwives a request<br>accompanied by the declaration that the girl is with child!”</p>\n<p>This made the priest’s hollow eye flash.</p>\n<p>“With child! knave! do you know anything of this?”</p>\n<p>Gringoire was alarmed by his air. He hastened to say, “Oh, no,<br>not I! Our marriage was a real <em>forismaritagium</em>. I stayed<br>outside. But one might obtain a respite, all the same.”</p>\n<p>“Madness! Infamy! Hold your tongue!”</p>\n<p>“You do wrong to get angry,” muttered Gringoire. “One obtains a<br>respite; that does no harm to any one, and allows the midwives,<br>who are poor women, to earn forty deniers parisis.”</p>\n<p>The priest was not listening to him!</p>\n<p>“But she must leave that place, nevertheless!” he murmured, “the<br>decree is to be executed within three days. Moreover, there will<br>be no decree; that Quasimodo! Women have very depraved tastes!”<br>He raised his voice: “Master Pierre, I have reflected well; there<br>is but one means of safety for her.”</p>\n<p>“What? I see none myself.”</p>\n<p>“Listen, Master Pierre, remember that you owe your life to her. I<br>will tell you my idea frankly. The church is watched night and<br>day; only those are allowed to come out, who have been seen to<br>enter. Hence you can enter. You will come. I will lead you to<br>her. You will change clothes with her. She will take your<br>doublet; you will take her petticoat.”</p>\n<p>“So far, it goes well,” remarked the philosopher, “and then?”</p>\n<p>“And then? she will go forth in your garments; you will remain<br>with hers. You will be hanged, perhaps, but she will be saved.”</p>\n<p>Gringoire scratched his ear, with a very serious air. “Stay!”<br>said he, “that is an idea which would never have occurred to me<br>unaided.”</p>\n<p>At Dom Claude’s proposition, the open and benign face of the poet<br>had abruptly clouded over, like a smiling Italian landscape, when<br>an unlucky squall comes up and dashes a cloud across the sun.</p>\n<p>“Well! Gringoire, what say you to the means?”</p>\n<p>“I say, master, that I shall not be hanged, perchance, but that I<br>shall be hanged indubitably.</p>\n<p>“That concerns us not.”</p>\n<p>“The deuce!” said Gringoire.</p>\n<p>“She has saved your life. ’Tis a debt that you are discharging.”</p>\n<p>“There are a great many others which I do not discharge.”</p>\n<p>“Master Pierre, it is absolutely necessary.”</p>\n<p>The archdeacon spoke imperiously.</p>\n<p>“Listen, Dom Claude,” replied the poet in utter consternation.<br>“You cling to that idea, and you are wrong. I do not see why I<br>should get myself hanged in some one else’s place.”</p>\n<p>“What have you, then, which attaches you so strongly to life?”</p>\n<p>“Oh! a thousand reasons!”</p>\n<p>“What reasons, if you please?”</p>\n<p>“What? The air, the sky, the morning, the evening, the moonlight,<br>my good friends the thieves, our jeers with the old hags of<br>go-betweens, the fine architecture of Paris to study, three great<br>books to make, one of them being against the bishops and his<br>mills; and how can I tell all? Anaxagoras said that he was in the<br>world to admire the sun. And then, from morning till night, I<br>have the happiness of passing all my days with a man of genius,<br>who is myself, which is very agreeable.”</p>\n<p>“A head fit for a mule bell!” muttered the archdeacon. “Oh! tell<br>me who preserved for you that life which you render so charming<br>to yourself? To whom do you owe it that you breathe that air,<br>behold that sky, and can still amuse your lark’s mind with your<br>whimsical nonsense and madness? Where would you be, had it not<br>been for her? Do you then desire that she through whom you are<br>alive, should die? that she should die, that beautiful, sweet,<br>adorable creature, who is necessary to the light of the world and<br>more divine than God, while you, half wise, and half fool, a vain<br>sketch of something, a sort of vegetable, which thinks that it<br>walks, and thinks that it thinks, you will continue to live with<br>the life which you have stolen from her, as useless as a candle<br>in broad daylight? Come, have a little pity, Gringoire; be<br>generous in your turn; it was she who set the example.”</p>\n<p>The priest was vehement. Gringoire listened to him at first with<br>an undecided air, then he became touched, and wound up with a<br>grimace which made his pallid face resemble that of a new-born<br>infant with an attack of the colic.</p>\n<p>“You are pathetic!” said he, wiping away a tear. “Well! I will<br>think about it. That’s a queer idea of yours.—After all,” he<br>continued after a pause, “who knows? perhaps they will not hang<br>me. He who becomes betrothed does not always marry. When they<br>find me in that little lodging so grotesquely muffled in<br>petticoat and coif, perchance they will burst with laughter. And<br>then, if they do hang me,—well! the halter is as good a death as<br>any. ’Tis a death worthy of a sage who has wavered all his life;<br>a death which is neither flesh nor fish, like the mind of a<br>veritable sceptic; a death all stamped with Pyrrhonism and<br>hesitation, which holds the middle station betwixt heaven and<br>earth, which leaves you in suspense. ’Tis a philosopher’s death,<br>and I was destined thereto, perchance. It is magnificent to die<br>as one has lived.”</p>\n<p>The priest interrupted him: “Is it agreed.”</p>\n<p>“What is death, after all?” pursued Gringoire with exaltation. “A<br>disagreeable moment, a toll-gate, the passage of little to<br>nothingness. Some one having asked Cercidas, the Megalopolitan,<br>if he were willing to die: ‘Why not?’ he replied; ‘for after my<br>death I shall see those great men, Pythagoras among the<br>philosophers, Hecatæus among historians, Homer among poets,<br>Olympus among musicians.’”</p>\n<p>The archdeacon gave him his hand: “It is settled, then? You will<br>come to-morrow?”</p>\n<p>This gesture recalled Gringoire to reality.</p>\n<p>“Ah! i’ faith no!” he said in the tone of a man just waking up.<br>“Be hanged! ’tis too absurd. I will not.”</p>\n<p>“Farewell, then!” and the archdeacon added between his teeth:<br>“I’ll find you again!”</p>\n<p>“I do not want that devil of a man to find me,” thought<br>Gringoire; and he ran after Dom Claude. “Stay, monsieur the<br>archdeacon, no ill-feeling between old friends! You take an<br>interest in that girl, my wife, I mean, and ’tis well. You have<br>devised a scheme to get her out of Notre-Dame, but your way is<br>extremely disagreeable to me, Gringoire. If I had only another<br>one myself! I beg to say that a luminous inspiration has just<br>occurred to me. If I possessed an expedient for extricating her<br>from a dilemma, without compromising my own neck to the extent of<br>a single running knot, what would you say to it? Will not that<br>suffice you? Is it absolutely necessary that I should be hanged,<br>in order that you may be content?”</p>\n<p>The priest tore out the buttons of his cassock with impatience:<br>“Stream of words! What is your plan?”</p>\n<p>“Yes,” resumed Gringoire, talking to himself and touching his<br>nose with his forefinger in sign of meditation,—“that’s it!—The<br>thieves are brave fellows!—The tribe of Egypt love her!—They will<br>rise at the first word!—Nothing easier!—A sudden stroke.—Under<br>cover of the disorder, they will easily carry her off!—Beginning<br>to-morrow evening. They will ask nothing better.</p>\n<p>“The plan! speak,” cried the archdeacon shaking him.</p>\n<p>Gringoire turned majestically towards him: “Leave me! You see<br>that I am composing.” He meditated for a few moments more, then<br>began to clap his hands over his thought, crying: “Admirable!<br>success is sure!”</p>\n<p>“The plan!” repeated Claude in wrath.</p>\n<p>Gringoire was radiant.</p>\n<p>“Come, that I may tell you that very softly. ’Tis a truly gallant<br>counter-plot, which will extricate us all from the matter.<br>Pardieu, it must be admitted that I am no fool.”</p>\n<p>He broke off.</p>\n<p>“Oh, by the way! is the little goat with the wench?”</p>\n<p>“Yes. The devil take you!”</p>\n<p>“They would have hanged it also, would they not?”</p>\n<p>“What is that to me?”</p>\n<p>“Yes, they would have hanged it. They hanged a sow last month.<br>The headsman loveth that; he eats the beast afterwards. Take my<br>pretty Djali! Poor little lamb!”</p>\n<p>“Malediction!” exclaimed Dom Claude. “You are the executioner.<br>What means of safety have you found, knave? Must your idea be<br>extracted with the forceps?”</p>\n<p>“Very fine, master, this is it.”</p>\n<p>Gringoire bent his head to the archdeacon’s head and spoke to him<br>in a very low voice, casting an uneasy glance the while from one<br>end to the other of the street, though no one was passing. When<br>he had finished, Dom Claude took his hand and said coldly: “’Tis<br>well. Farewell until to-morrow.”</p>\n<p>“Until to-morrow,” repeated Gringoire. And, while the archdeacon<br>was disappearing in one direction, he set off in the other,<br>saying to himself in a low voice: “Here’s a grand affair,<br>Monsieur Pierre Gringoire. Never mind! ’Tis not written that<br>because one is of small account one should take fright at a great<br>enterprise. Bitou carried a great bull on his shoulders; the<br>water-wagtails, the warblers, and the buntings traverse the<br>ocean.”</p>\n<h1 class=\"chapter\" id=\"chapter-ii-turn-vagabond\">Chapter II. TURN VAGABOND.</h1>\n<p>On re-entering the cloister, the archdeacon found at the door of<br>his cell his brother Jehan du Moulin, who was waiting for him,<br>and who had beguiled the tedium of waiting by drawing on the wall<br>with a bit of charcoal, a profile of his elder brother, enriched<br>with a monstrous nose.</p>\n<p>Dom Claude hardly looked at his brother; his thoughts were<br>elsewhere. That merry scamp’s face whose beaming had so often<br>restored serenity to the priest’s sombre physiognomy, was now<br>powerless to melt the gloom which grew more dense every day over<br>that corrupted, mephitic, and stagnant soul.</p>\n<p>“Brother,” said Jehan timidly, “I am come to see you.”</p>\n<p>The archdeacon did not even raise his eyes.</p>\n<p>“What then?”</p>\n<p>“Brother,” resumed the hypocrite, “you are so good to me, and you<br>give me such wise counsels that I always return to you.”</p>\n<p>“What next?”</p>\n<p>“Alas! brother, you were perfectly right when you said to<br>me,—“Jehan! Jehan! _cessat doctorum doctrina, discipulorum<br>disciplina_. Jehan, be wise, Jehan, be learned, Jehan, pass not<br>the night outside of the college without lawful occasion and due<br>leave of the master. Cudgel not the Picards: _noli, Joannes,<br>verberare Picardos<em>. Rot not like an unlettered ass, </em>quasi<br>asinus illitteratus_, on the straw seats of the school. Jehan,<br>allow yourself to be punished at the discretion of the master.<br>Jehan go every evening to chapel, and sing there an anthem with<br>verse and orison to Madame the glorious Virgin Mary.”—Alas! what<br>excellent advice was that!”</p>\n<p>“And then?”</p>\n<p>“Brother, you behold a culprit, a criminal, a wretch, a<br>libertine, a man of enormities! My dear brother, Jehan hath made<br>of your counsels straw and dung to trample under foot. I have<br>been well chastised for it, and God is extraordinarily just. As<br>long as I had money, I feasted, I lead a mad and joyous life. Oh!<br>how ugly and crabbed behind is debauch which is so charming in<br>front! Now I have no longer a blank; I have sold my napery, my<br>shirt and my towels; no more merry life! The beautiful candle is<br>extinguished and I have henceforth, only a wretched tallow dip<br>which smokes in my nose. The wenches jeer at me. I drink water. I<br>am overwhelmed with remorse and with creditors.”</p>\n<p>“The rest?” said the archdeacon.</p>\n<p>“Alas! my very dear brother, I should like to settle down to a<br>better life. I come to you full of contrition, I am penitent. I<br>make my confession. I beat my breast violently. You are quite<br>right in wishing that I should some day become a licentiate and<br>sub-monitor in the college of Torchi. At the present moment I<br>feel a magnificent vocation for that profession. But I have no<br>more ink and I must buy some; I have no more paper, I have no<br>more books, and I must buy some. For this purpose, I am greatly<br>in need of a little money, and I come to you, brother, with my<br>heart full of contrition.”</p>\n<p>“Is that all?”</p>\n<p>“Yes,” said the scholar. “A little money.”</p>\n<p>“I have none.”</p>\n<p>Then the scholar said, with an air which was both grave and<br>resolute: “Well, brother, I am sorry to be obliged to tell you<br>that very fine offers and propositions are being made to me in<br>another quarter. You will not give me any money? No. In that case<br>I shall become a professional vagabond.”</p>\n<p>As he uttered these monstrous words, he assumed the mien of Ajax,<br>expecting to see the lightnings descend upon his head.</p>\n<p>The archdeacon said coldly to him,—</p>\n<p>“Become a vagabond.”</p>\n<p>Jehan made him a deep bow, and descended the cloister stairs,<br>whistling.</p>\n<p>At the moment when he was passing through the courtyard of the<br>cloister, beneath his brother’s window, he heard that window<br>open, raised his eyes and beheld the archdeacon’s severe head<br>emerge.</p>\n<p>“Go to the devil!” said Dom Claude; “here is the last money which<br>you will get from me?”</p>\n<p>At the same time, the priest flung Jehan a purse, which gave the<br>scholar a big bump on the forehead, and with which Jehan<br>retreated, both vexed and content, like a dog who had been stoned<br>with marrow bones.</p>\n<h1 class=\"chapter\" id=\"chapter-iii-long-live-mirth\">Chapter III. LONG LIVE MIRTH.</h1>\n<p>The reader has probably not forgotten that a part of the Cour de<br>Miracles was enclosed by the ancient wall which surrounded the<br>city, a goodly number of whose towers had begun, even at that<br>epoch, to fall to ruin. One of these towers had been converted<br>into a pleasure resort by the vagabonds. There was a dram-shop in<br>the underground story, and the rest in the upper stories. This<br>was the most lively, and consequently the most hideous, point of<br>the whole outcast den. It was a sort of monstrous hive, which<br>buzzed there night and day. At night, when the remainder of the<br>beggar horde slept, when there was no longer a window lighted in<br>the dingy façades of the Place, when not a cry was any longer to<br>be heard proceeding from those innumerable families, those<br>ant-hills of thieves, of wenches, and stolen or bastard children,<br>the merry tower was still recognizable by the noise which it<br>made, by the scarlet light which, flashing simultaneously from<br>the air-holes, the windows, the fissures in the cracked walls,<br>escaped, so to speak, from its every pore.</p>\n<p>The cellar then, was the dram-shop. The descent to it was through<br>a low door and by a staircase as steep as a classic Alexandrine.<br>Over the door, by way of a sign there hung a marvellous daub,<br>representing new sous and dead chickens,[53] with this, pun<br>below: <em>Aux sonneurs pour les trépassés</em>,—The ringers for the<br>dead.</p>\n<p>One evening when the curfew was sounding from all the belfries in<br>Paris, the sergeants of the watch might have observed, had it<br>been granted to them to enter the formidable Court of Miracles,<br>that more tumult than usual was in progress in the vagabonds’<br>tavern, that more drinking was being done, and louder swearing.<br>Outside in the Place, there, were many groups conversing in low<br>tones, as when some great plan is being framed, and here and<br>there a knave crouching down engaged in sharpening a villanous<br>iron blade on a paving-stone.</p>\n<p>Meanwhile, in the tavern itself, wine and gaming offered such a<br>powerful diversion to the ideas which occupied the vagabonds’<br>lair that evening, that it would have been difficult to divine<br>from the remarks of the drinkers, what was the matter in hand.<br>They merely wore a gayer air than was their wont, and some weapon<br>could be seen glittering between the legs of each of them,—a<br>sickle, an axe, a big two-edged sword or the hook of an old<br>hackbut.</p>\n<p>The room, circular in form, was very spacious; but the tables<br>were so thickly set and the drinkers so numerous, that all that<br>the tavern contained, men, women, benches, beer-jugs, all that<br>were drinking, all that were sleeping, all that were playing, the<br>well, the lame, seemed piled up pell-mell, with as much order and<br>harmony as a heap of oyster shells. There were a few tallow dips<br>lighted on the tables; but the real luminary of this tavern, that<br>which played the part in this dram-shop of the chandelier of an<br>opera house, was the fire. This cellar was so damp that the fire<br>was never allowed to go out, even in midsummer; an immense<br>chimney with a sculptured mantel, all bristling with heavy iron<br>andirons and cooking utensils, with one of those huge fires of<br>mixed wood and peat which at night, in village streets make the<br>reflection of forge windows stand out so red on the opposite<br>walls. A big dog gravely seated in the ashes was turning a spit<br>loaded with meat before the coals.</p>\n<p>Great as was the confusion, after the first glance one could<br>distinguish in that multitude, three principal groups which<br>thronged around three personages already known to the reader. One<br>of these personages, fantastically accoutred in many an oriental<br>rag, was Mathias Hungadi Spicali, Duke of Egypt and Bohemia. The<br>knave was seated on a table with his legs crossed, and in a loud<br>voice was bestowing his knowledge of magic, both black and white,<br>on many a gaping face which surrounded him. Another rabble<br>pressed close around our old friend, the valiant King of Thunes,<br>armed to the teeth. Clopin Trouillefou, with a very serious air<br>and in a low voice, was regulating the distribution of an<br>enormous cask of arms, which stood wide open in front of him and<br>from whence poured out in profusion, axes, swords, bassinets,<br>coats of mail, broadswords, lance-heads, arrows, and<br>viretons,[54] like apples and grapes from a horn of plenty. Every<br>one took something from the cask, one a morion, another a long,<br>straight sword, another a dagger with a cross-shaped hilt. The<br>very children were arming themselves, and there were even<br>cripples in bowls who, in armor and cuirass, made their way<br>between the legs of the drinkers, like great beetles.</p>\n<p>Finally, a third audience, the most noisy, the most jovial, and<br>the most numerous, encumbered benches and tables, in the midst of<br>which harangued and swore a flute-like voice, which escaped from<br>beneath a heavy armor, complete from casque to spurs. The<br>individual who had thus screwed a whole outfit upon his body, was<br>so hidden by his warlike accoutrements that nothing was to be<br>seen of his person save an impertinent, red, snub nose, a rosy<br>mouth, and bold eyes. His belt was full of daggers and poniards,<br>a huge sword on his hip, a rusted cross-bow at his left, and a<br>vast jug of wine in front of him, without reckoning on his right,<br>a fat wench with her bosom uncovered. All mouths around him were<br>laughing, cursing, and drinking.</p>\n<p>Add twenty secondary groups, the waiters, male and female,<br>running with jugs on their heads, gamblers squatting over taws,<br>merelles,[55] dice, vachettes, the ardent game of tringlet,<br>quarrels in one corner, kisses in another, and the reader will<br>have some idea of this whole picture, over which flickered the<br>light of a great, flaming fire, which made a thousand huge and<br>grotesque shadows dance over the walls of the drinking shop.</p>\n<p>As for the noise, it was like the inside of a bell at full peal.</p>\n<p>The dripping-pan, where crackled a rain of grease, filled with<br>its continual sputtering the intervals of these thousand<br>dialogues, which intermingled from one end of the apartment to<br>the other.</p>\n<p>In the midst of this uproar, at the extremity of the tavern, on<br>the bench inside the chimney, sat a philosopher meditating with<br>his feet in the ashes and his eyes on the brands. It was Pierre<br>Gringoire.</p>\n<p>“Be quick! make haste, arm yourselves! we set out on the march in<br>an hour!” said Clopin Trouillefou to his thieves.</p>\n<p>A wench was humming,—</p>\n<p>“Bonsoir mon père et ma mère,<br>Les derniers couvrent le feu.”[56]</p>\n<p>Two card players were disputing,—</p>\n<p>“Knave!” cried the reddest faced of the two, shaking his fist at<br>the other; “I’ll mark you with the club. You can take the place<br>of Mistigri in the pack of cards of monseigneur the king.”</p>\n<p>“Ugh!” roared a Norman, recognizable by his nasal accent; “we are<br>packed in here like the saints of Caillouville!”</p>\n<p>“My sons,” the Duke of Egypt was saying to his audience, in a<br>falsetto voice, “sorceresses in France go to the witches’ sabbath<br>without broomsticks, or grease, or steed, merely by means of some<br>magic words. The witches of Italy always have a buck waiting for<br>them at their door. All are bound to go out through the chimney.”</p>\n<p>The voice of the young scamp armed from head to foot, dominated<br>the uproar.</p>\n<p>“Hurrah! hurrah!” he was shouting. “My first day in armor!<br>Outcast! I am an outcast. Give me something to drink. My friends,<br>my name is Jehan Frollo du Moulin, and I am a gentleman. My<br>opinion is that if God were a <em>gendarme</em>, he would turn robber.<br>Brothers, we are about to set out on a fine expedition. Lay siege<br>to the church, burst in the doors, drag out the beautiful girl,<br>save her from the judges, save her from the priests, dismantle<br>the cloister, burn the bishop in his palace—all this we will do<br>in less time than it takes for a burgomaster to eat a spoonful of<br>soup. Our cause is just, we will plunder Notre-Dame and that will<br>be the end of it. We will hang Quasimodo. Do you know Quasimodo,<br>ladies? Have you seen him make himself breathless on the big bell<br>on a grand Pentecost festival! <em>Corne du Père!</em> ’tis very fine!<br>One would say he was a devil mounted on a man. Listen to me, my<br>friends; I am a vagabond to the bottom of my heart, I am a member<br>of the slang thief gang in my soul, I was born an independent<br>thief. I have been rich, and I have devoured all my property. My<br>mother wanted to make an officer of me; my father, a sub-deacon;<br>my aunt, a councillor of inquests; my grandmother, prothonotary<br>to the king; my great aunt, a treasurer of the short robe,—and I<br>have made myself an outcast. I said this to my father, who spit<br>his curse in my face; to my mother, who set to weeping and<br>chattering, poor old lady, like yonder fagot on the and-irons.<br>Long live mirth! I am a real Bicêtre. Waitress, my dear, more<br>wine. I have still the wherewithal to pay. I want no more Surène<br>wine. It distresses my throat. I’d as lief, <em>corbœuf!</em> gargle my<br>throat with a basket.”</p>\n<p>Meanwhile, the rabble applauded with shouts of laughter; and<br>seeing that the tumult was increasing around him, the scholar<br>cried,—.</p>\n<p>“Oh! what a fine noise! _Populi debacchantis populosa<br>debacchatio!_” Then he began to sing, his eye swimming in<br>ecstasy, in the tone of a canon intoning vespers, _Quæ cantica!<br>quæ organa! quæ cantilenæ! quæ melodiæ hic sine fine decantantur!<br>Sonant melliflua hymnorum organa, suavissima angelorum melodia,<br>cantica canticorum mira!_ He broke off: “Tavern-keeper of the<br>devil, give me some supper!”</p>\n<p>There was a moment of partial silence, during which the sharp<br>voice of the Duke of Egypt rose, as he gave instructions to his<br>Bohemians.</p>\n<p>“The weasel is called Adrune; the fox, Blue-foot, or the Racer of<br>the Woods; the wolf, Gray-foot, or Gold-foot; the bear the Old<br>Man, or Grandfather. The cap of a gnome confers invisibility, and<br>causes one to behold invisible things. Every toad that is<br>baptized must be clad in red or black velvet, a bell on its neck,<br>a bell on its feet. The godfather holds its head, the godmother<br>its hinder parts. ’Tis the demon Sidragasum who hath the power to<br>make wenches dance stark naked.”</p>\n<p>“By the mass!” interrupted Jehan, “I should like to be the demon<br>Sidragasum.”</p>\n<p>Meanwhile, the vagabonds continued to arm themselves and whisper<br>at the other end of the dram-shop.</p>\n<p>“That poor Esmeralda!” said a Bohemian. “She is our sister. She<br>must be taken away from there.”</p>\n<p>“Is she still at Notre-Dame?” went on a merchant with the<br>appearance of a Jew.</p>\n<p>“Yes, pardieu!”</p>\n<p>“Well! comrades!” exclaimed the merchant, “to Notre-Dame! So much<br>the better, since there are in the chapel of Saints Féréol and<br>Ferrution two statues, the one of John the Baptist, the other of<br>Saint-Antoine, of solid gold, weighing together seven marks of<br>gold and fifteen estellins; and the pedestals are of silver-gilt,<br>of seventeen marks, five ounces. I know that; I am a goldsmith.”</p>\n<p>Here they served Jehan with his supper. As he threw himself back<br>on the bosom of the wench beside him, he exclaimed,—</p>\n<p>“By Saint Voult-de-Lucques, whom people call Saint Goguelu, I am<br>perfectly happy. I have before me a fool who gazes at me with the<br>smooth face of an archduke. Here is one on my left whose teeth<br>are so long that they hide his chin. And then, I am like the<br>Marshal de Gié at the siege of Pontoise, I have my right resting<br>on a hillock. <em>Ventre-Mahom!</em> Comrade! you have the air of a<br>merchant of tennis-balls; and you come and sit yourself beside<br>me! I am a nobleman, my friend! Trade is incompatible with<br>nobility. Get out of that! Holà hé! You others, don’t fight!<br>What, Baptiste Croque-Oison, you who have such a fine nose are<br>going to risk it against the big fists of that lout! Fool! _Non<br>cuiquam datum est habere nasum_—not every one is favored with a<br>nose. You are really divine, Jacqueline Ronge-Oreille! ’tis a<br>pity that you have no hair! Holà! my name is Jehan Frollo, and my<br>brother is an archdeacon. May the devil fly off with him! All<br>that I tell you is the truth. In turning vagabond, I have gladly<br>renounced the half of a house situated in paradise, which my<br>brother had promised me. <em>Dimidiam domum in paradiso</em>. I quote<br>the text. I have a fief in the Rue Tirechappe, and all the women<br>are in love with me, as true as Saint Éloy was an excellent<br>goldsmith, and that the five trades of the good city of Paris are<br>the tanners, the tawers, the makers of cross-belts, the<br>purse-makers, and the sweaters, and that Saint Laurent was burnt<br>with eggshells. I swear to you, comrades.</p>\n<p>“Que je ne beuvrai de piment,<br>Devant un an, si je cy ment![57]</p>\n<p>“’Tis moonlight, my charmer; see yonder through the window how<br>the wind is tearing the clouds to tatters! Even thus will I do to<br>your gorget.—Wenches, wipe the children’s noses and snuff the<br>candles.—Christ and Mahom! What am I eating here, Jupiter? Ohé!<br>innkeeper! the hair which is not on the heads of your hussies one<br>finds in your omelettes. Old woman! I like bald omelettes. May<br>the devil confound you!—A fine hostelry of Beelzebub, where the<br>hussies comb their heads with the forks!</p>\n<p>“Et je n’ai moi,<br>Par la sang-Dieu!<br>Ni foi, ni loi,<br>Ni feu, ni lieu,<br>Ni roi,<br>Ni Dieu.”[58]</p>\n<p>In the meantime, Clopin Trouillefou had finished the distribution<br>of arms. He approached Gringoire, who appeared to be plunged in a<br>profound revery, with his feet on an andiron.</p>\n<p>“Friend Pierre,” said the King of Thunes, “what the devil are you<br>thinking about?”</p>\n<p>Gringoire turned to him with a melancholy smile.</p>\n<p>“I love the fire, my dear lord. Not for the trivial reason that<br>fire warms the feet or cooks our soup, but because it has sparks.<br>Sometimes I pass whole hours in watching the sparks. I discover a<br>thousand things in those stars which are sprinkled over the black<br>background of the hearth. Those stars are also worlds.”</p>\n<p>“Thunder, if I understand you!” said the outcast. “Do you know<br>what o’clock it is?”</p>\n<p>“I do not know,” replied Gringoire.</p>\n<p>Clopin approached the Duke of Egypt.</p>\n<p>“Comrade Mathias, the time we have chosen is not a good one. King<br>Louis XI. is said to be in Paris.”</p>\n<p>“Another reason for snatching our sister from his claws,” replied<br>the old Bohemian.</p>\n<p>“You speak like a man, Mathias,” said the King of Thunes.<br>“Moreover, we will act promptly. No resistance is to be feared in<br>the church. The canons are hares, and we are in force. The people<br>of the parliament will be well balked to-morrow when they come to<br>seek her! Guts of the pope I don’t want them to hang the pretty<br>girl!”</p>\n<p>Clopin quitted the dram-shop.</p>\n<p>Meanwhile, Jehan was shouting in a hoarse voice:</p>\n<p>“I eat, I drink, I am drunk, I am Jupiter! Eh! Pierre, the<br>Slaughterer, if you look at me like that again, I’ll fillip the<br>dust off your nose for you.”</p>\n<p>Gringoire, torn from his meditations, began to watch the wild and<br>noisy scene which surrounded him, muttering between his teeth:<br>“<em>Luxuriosa res vinum et tumultuosa ebrietas</em>. Alas! what good<br>reason I have not to drink, and how excellently spoke<br>Saint-Benoît: ‘<em>Vinum apostatare facit etiam sapientes!</em>’”</p>\n<p>At that moment, Clopin returned and shouted in a voice of<br>thunder: “Midnight!”</p>\n<p>At this word, which produced the effect of the call to boot and<br>saddle on a regiment at a halt, all the outcasts, men, women,<br>children, rushed in a mass from the tavern, with great noise of<br>arms and old iron implements.</p>\n<p>The moon was obscured.</p>\n<p>The Cour des Miracles was entirely dark. There was not a single<br>light. One could make out there a throng of men and women<br>conversing in low tones. They could be heard buzzing, and a gleam<br>of all sorts of weapons was visible in the darkness. Clopin<br>mounted a large stone.</p>\n<p>“To your ranks, Argot!”[59] he cried. “Fall into line, Egypt!<br>Form ranks, Galilee!”</p>\n<p>A movement began in the darkness. The immense multitude appeared<br>to form in a column. After a few minutes, the King of Thunes<br>raised his voice once more,—</p>\n<p>“Now, silence to march through Paris! The password is, ‘Little<br>sword in pocket!’ The torches will not be lighted till we reach<br>Notre-Dame! Forward, march!”</p>\n<p>Ten minutes later, the cavaliers of the watch fled in terror<br>before a long procession of black and silent men which was<br>descending towards the Pont au Change, through the tortuous<br>streets which pierce the close-built neighborhood of the markets<br>in every direction.</p>\n<h1 class=\"chapter\" id=\"chapter-iv-an-awkward-friend\">Chapter IV. AN AWKWARD FRIEND.</h1>\n<p>That night, Quasimodo did not sleep. He had just made his last<br>round of the church. He had not noticed, that at the moment when<br>he was closing the doors, the archdeacon had passed close to him<br>and betrayed some displeasure on seeing him bolting and barring<br>with care the enormous iron locks which gave to their large<br>leaves the solidity of a wall. Dom Claude’s air was even more<br>preoccupied than usual. Moreover, since the nocturnal adventure<br>in the cell, he had constantly abused Quasimodo, but in vain did<br>he ill treat, and even beat him occasionally, nothing disturbed<br>the submission, patience, the devoted resignation of the faithful<br>bellringer. He endured everything on the part of the archdeacon,<br>insults, threats, blows, without murmuring a complaint. At the<br>most, he gazed uneasily after Dom Claude when the latter ascended<br>the staircase of the tower; but the archdeacon had abstained from<br>presenting himself again before the gypsy’s eyes.</p>\n<p>On that night, accordingly, Quasimodo, after having cast a glance<br>at his poor bells which he so neglected now, Jacqueline, Marie,<br>and Thibauld, mounted to the summit of the Northern tower, and<br>there setting his dark lanturn, well closed, upon the leads, he<br>began to gaze at Paris. The night, as we have already said, was<br>very dark. Paris which, so to speak was not lighted at that<br>epoch, presented to the eye a confused collection of black<br>masses, cut here and there by the whitish curve of the Seine.<br>Quasimodo no longer saw any light with the exception of one<br>window in a distant edifice, whose vague and sombre profile was<br>outlined well above the roofs, in the direction of the Porte<br>Sainte-Antoine. There also, there was some one awake.</p>\n<p>As the only eye of the bellringer peered into that horizon of<br>mist and night, he felt within him an inexpressible uneasiness.<br>For several days he had been upon his guard. He had perceived men<br>of sinister mien, who never took their eyes from the young girl’s<br>asylum, prowling constantly about the church. He fancied that<br>some plot might be in process of formation against the unhappy<br>refugee. He imagined that there existed a popular hatred against<br>her, as against himself, and that it was very possible that<br>something might happen soon. Hence he remained upon his tower on<br>the watch, “dreaming in his dream-place,” as Rabelais says, with<br>his eye directed alternately on the cell and on Paris, keeping<br>faithful guard, like a good dog, with a thousand suspicions in<br>his mind.</p>\n<p>All at once, while he was scrutinizing the great city with that<br>eye which nature, by a sort of compensation, had made so piercing<br>that it could almost supply the other organs which Quasimodo<br>lacked, it seemed to him that there was something singular about<br>the Quay de la Vieille-Pelleterie, that there was a movement at<br>that point, that the line of the parapet, standing out blackly<br>against the whiteness of the water was not straight and tranquil,<br>like that of the other quays, but that it undulated to the eye,<br>like the waves of a river, or like the heads of a crowd in<br>motion.</p>\n<p>This struck him as strange. He redoubled his attention. The<br>movement seemed to be advancing towards the City. There was no<br>light. It lasted for some time on the quay; then it gradually<br>ceased, as though that which was passing were entering the<br>interior of the island; then it stopped altogether, and the line<br>of the quay became straight and motionless again.</p>\n<p>At the moment when Quasimodo was lost in conjectures, it seemed<br>to him that the movement had re-appeared in the Rue du Parvis,<br>which is prolonged into the city perpendicularly to the façade of<br>Notre-Dame. At length, dense as was the darkness, he beheld the<br>head of a column debouch from that street, and in an instant a<br>crowd—of which nothing could be distinguished in the gloom except<br>that it was a crowd—spread over the Place.</p>\n<p>This spectacle had a terror of its own. It is probable that this<br>singular procession, which seemed so desirous of concealing<br>itself under profound darkness, maintained a silence no less<br>profound. Nevertheless, some noise must have escaped it, were it<br>only a trampling. But this noise did not even reach our deaf man,<br>and this great multitude, of which he saw hardly anything, and of<br>which he heard nothing, though it was marching and moving so near<br>him, produced upon him the effect of a rabble of dead men, mute,<br>impalpable, lost in a smoke. It seemed to him, that he beheld<br>advancing towards him a fog of men, and that he saw shadows<br>moving in the shadow.</p>\n<p>Then his fears returned to him, the idea of an attempt against<br>the gypsy presented itself once more to his mind. He was<br>conscious, in a confused way, that a violent crisis was<br>approaching. At that critical moment he took counsel with<br>himself, with better and prompter reasoning than one would have<br>expected from so badly organized a brain. Ought he to awaken the<br>gypsy? to make her escape? Whither? The streets were invested,<br>the church backed on the river. No boat, no issue!—There was but<br>one thing to be done; to allow himself to be killed on the<br>threshold of Notre-Dame, to resist at least until succor arrived,<br>if it should arrive, and not to trouble la Esmeralda’s sleep.<br>This resolution once taken, he set to examining the enemy with<br>more tranquillity.</p>\n<p>The throng seemed to increase every moment in the church square.<br>Only, he presumed that it must be making very little noise, since<br>the windows on the Place remained closed. All at once, a flame<br>flashed up, and in an instant seven or eight lighted torches<br>passed over the heads of the crowd, shaking their tufts of flame<br>in the deep shade. Quasimodo then beheld distinctly surging in<br>the Parvis a frightful herd of men and women in rags, armed with<br>scythes, pikes, billhooks and partisans, whose thousand points<br>glittered. Here and there black pitchforks formed horns to the<br>hideous faces. He vaguely recalled this populace, and thought<br>that he recognized all the heads who had saluted him as Pope of<br>the Fools some months previously. One man who held a torch in one<br>hand and a club in the other, mounted a stone post and seemed to<br>be haranguing them. At the same time the strange army executed<br>several evolutions, as though it were taking up its post around<br>the church. Quasimodo picked up his lantern and descended to the<br>platform between the towers, in order to get a nearer view, and<br>to spy out a means of defence.</p>\n<p>Clopin Trouillefou, on arriving in front of the lofty portal of<br>Notre-Dame had, in fact, ranged his troops in order of battle.<br>Although he expected no resistance, he wished, like a prudent<br>general, to preserve an order which would permit him to face, at<br>need, a sudden attack of the watch or the police. He had<br>accordingly stationed his brigade in such a manner that, viewed<br>from above and from a distance, one would have pronounced it the<br>Roman triangle of the battle of Ecnomus, the boar’s head of<br>Alexander or the famous wedge of Gustavus Adolphus. The base of<br>this triangle rested on the back of the Place in such a manner as<br>to bar the entrance of the Rue du Parvis; one of its sides faced<br>Hôtel-Dieu, the other the Rue Saint-Pierre-aux-Bœufs. Clopin<br>Trouillefou had placed himself at the apex with the Duke of<br>Egypt, our friend Jehan, and the most daring of the scavengers.</p>\n<p>An enterprise like that which the vagabonds were now undertaking<br>against Notre-Dame was not a very rare thing in the cities of the<br>Middle Ages. What we now call the “police” did not exist then. In<br>populous cities, especially in capitals, there existed no single,<br>central, regulating power. Feudalism had constructed these great<br>communities in a singular manner. A city was an assembly of a<br>thousand seigneuries, which divided it into compartments of all<br>shapes and sizes. Hence, a thousand conflicting establishments of<br>police; that is to say, no police at all. In Paris, for example,<br>independently of the hundred and forty-one lords who laid claim<br>to a manor, there were five and twenty who laid claim to a manor<br>and to administering justice, from the Bishop of Paris, who had<br>five hundred streets, to the Prior of Notre-Dame des Champs, who<br>had four. All these feudal justices recognized the suzerain<br>authority of the king only in name. All possessed the right of<br>control over the roads. All were at home. Louis XI., that<br>indefatigable worker, who so largely began the demolition of the<br>feudal edifice, continued by Richelieu and Louis XIV. for the<br>profit of royalty, and finished by Mirabeau for the benefit of<br>the people,—Louis XI. had certainly made an effort to break this<br>network of seignories which covered Paris, by throwing violently<br>across them all two or three troops of general police. Thus, in<br>1465, an order to the inhabitants to light candles in their<br>windows at nightfall, and to shut up their dogs under penalty of<br>death; in the same year, an order to close the streets in the<br>evening with iron chains, and a prohibition to wear daggers or<br>weapons of offence in the streets at night. But in a very short<br>time, all these efforts at communal legislation fell into<br>abeyance. The <em>bourgeois</em> permitted the wind to blow out their<br>candles in the windows, and their dogs to stray; the iron chains<br>were stretched only in a state of siege; the prohibition to wear<br>daggers wrought no other changes than from the name of the Rue<br>Coupe-Gueule to the name of the Rue-Coupe-Gorge[60] which is an<br>evident progress. The old scaffolding of feudal jurisdictions<br>remained standing; an immense aggregation of bailiwicks and<br>seignories crossing each other all over the city, interfering<br>with each other, entangled in one another, enmeshing each other,<br>trespassing on each other; a useless thicket of watches,<br>sub-watches and counter-watches, over which, with armed force,<br>passed brigandage, rapine, and sedition. Hence, in this disorder,<br>deeds of violence on the part of the populace directed against a<br>palace, a hôtel, or house in the most thickly populated quarters,<br>were not unheard-of occurrences. In the majority of such cases,<br>the neighbors did not meddle with the matter unless the pillaging<br>extended to themselves. They stopped up their ears to the musket<br>shots, closed their shutters, barricaded their doors, allowed the<br>matter to be concluded with or without the watch, and the next<br>day it was said in Paris, “Étienne Barbette was broken open last<br>night. The Marshal de Clermont was seized last night, etc.”<br>Hence, not only the royal habitations, the Louvre, the Palace,<br>the Bastille, the Tournelles, but simply seignorial residences,<br>the Petit-Bourbon, the Hôtel de Sens, the Hôtel d’Angoulême,<br>etc., had battlements on their walls, and machicolations over<br>their doors. Churches were guarded by their sanctity. Some, among<br>the number Notre-Dame, were fortified. The Abbey of<br>Saint-Germain-des-Prés was castellated like a baronial mansion,<br>and more brass expended about it in bombards than in bells. Its<br>fortress was still to be seen in 1610. To-day, barely its church<br>remains.</p>\n<p>Let us return to Notre-Dame.</p>\n<p>When the first arrangements were completed, and we must say, to<br>the honor of vagabond discipline, that Clopin’s orders were<br>executed in silence, and with admirable precision, the worthy<br>chief of the band, mounted on the parapet of the church square,<br>and raised his hoarse and surly voice, turning towards<br>Notre-Dame, and brandishing his torch whose light, tossed by the<br>wind, and veiled every moment by its own smoke, made the reddish<br>façade of the church appear and disappear before the eye.</p>\n<p>“To you, Louis de Beaumont, bishop of Paris, counsellor in the<br>Court of Parliament, I, Clopin Trouillefou, king of Thunes, grand<br>Coësre, prince of Argot, bishop of fools, I say: Our sister,<br>falsely condemned for magic, hath taken refuge in your church,<br>you owe her asylum and safety. Now the Court of Parliament wishes<br>to seize her once more there, and you consent to it; so that she<br>would be hanged to-morrow in the Grève, if God and the outcasts<br>were not here. If your church is sacred, so is our sister; if our<br>sister is not sacred, neither is your church. That is why we call<br>upon you to return the girl if you wish to save your church, or<br>we will take possession of the girl again and pillage the church,<br>which will be a good thing. In token of which I here plant my<br>banner, and may God preserve you, bishop of Paris.”</p>\n<p>Quasimodo could not, unfortunately, hear these words uttered with<br>a sort of sombre and savage majesty. A vagabond presented his<br>banner to Clopin, who planted it solemnly between two<br>paving-stones. It was a pitchfork from whose points hung a<br>bleeding quarter of carrion meat.</p>\n<p>That done, the King of Thunes turned round and cast his eyes over<br>his army, a fierce multitude whose glances flashed almost equally<br>with their pikes. After a momentary pause,—“Forward, my Sons!” he<br>cried; “to work, locksmiths!”</p>\n<p>Thirty bold men, square shouldered, and with pick-lock faces,<br>stepped from the ranks, with hammers, pincers, and bars of iron<br>on their shoulders. They betook themselves to the principal door<br>of the church, ascended the steps, and were soon to be seen<br>squatting under the arch, working at the door with pincers and<br>levers; a throng of vagabonds followed them to help or look on.<br>The eleven steps before the portal were covered with them.</p>\n<p>But the door stood firm. “The devil! ’tis hard and obstinate!”<br>said one. “It is old, and its gristles have become bony,” said<br>another. “Courage, comrades!” resumed Clopin. “I wager my head<br>against a dipper that you will have opened the door, rescued the<br>girl, and despoiled the chief altar before a single beadle is<br>awake. Stay! I think I hear the lock breaking up.”</p>\n<p>Clopin was interrupted by a frightful uproar which re-sounded<br>behind him at that moment. He wheeled round. An enormous beam had<br>just fallen from above; it had crushed a dozen vagabonds on the<br>pavement with the sound of a cannon, breaking in addition, legs<br>here and there in the crowd of beggars, who sprang aside with<br>cries of terror. In a twinkling, the narrow precincts of the<br>church parvis were cleared. The locksmiths, although protected by<br>the deep vaults of the portal, abandoned the door and Clopin<br>himself retired to a respectful distance from the church.</p>\n<p>“I had a narrow escape!” cried Jehan. “I felt the wind, of it,<br><em>tête-de-bœuf!</em> but Pierre the Slaughterer is slaughtered!”</p>\n<p>It is impossible to describe the astonishment mingled with fright<br>which fell upon the ruffians in company with this beam.</p>\n<p>They remained for several minutes with their eyes in the air,<br>more dismayed by that piece of wood than by the king’s twenty<br>thousand archers.</p>\n<p>“Satan!” muttered the Duke of Egypt, “this smacks of magic!”</p>\n<p>“’Tis the moon which threw this log at us,” said Andry the Red.</p>\n<p>“Call the moon the friend of the Virgin, after that!” went on<br>François Chanteprune.</p>\n<p>“A thousand popes!” exclaimed Clopin, “you are all fools!” But he<br>did not know how to explain the fall of the beam.</p>\n<p>Meanwhile, nothing could be distinguished on the façade, to whose<br>summit the light of the torches did not reach. The heavy beam lay<br>in the middle of the enclosure, and groans were heard from the<br>poor wretches who had received its first shock, and who had been<br>almost cut in twain, on the angle of the stone steps.</p>\n<p>The King of Thunes, his first amazement passed, finally found an<br>explanation which appeared plausible to his companions.</p>\n<p>“Throat of God! are the canons defending themselves? To the sack,<br>then! to the sack!”</p>\n<p>“To the sack!” repeated the rabble, with a furious hurrah. A<br>discharge of crossbows and hackbuts against the front of the<br>church followed.</p>\n<p>At this detonation, the peaceable inhabitants of the surrounding<br>houses woke up; many windows were seen to open, and nightcaps and<br>hands holding candles appeared at the casements.</p>\n<p>“Fire at the windows,” shouted Clopin. The windows were<br>immediately closed, and the poor <em>bourgeois</em>, who had hardly had<br>time to cast a frightened glance on this scene of gleams and<br>tumult, returned, perspiring with fear to their wives, asking<br>themselves whether the witches’ sabbath was now being held in the<br>parvis of Notre-Dame, or whether there was an assault of<br>Burgundians, as in ’64. Then the husbands thought of theft; the<br>wives, of rape; and all trembled.</p>\n<p>“To the sack!” repeated the thieves’ crew; but they dared not<br>approach. They stared at the beam, they stared at the church. The<br>beam did not stir, the edifice preserved its calm and deserted<br>air; but something chilled the outcasts.</p>\n<p>“To work, locksmiths!” shouted Trouillefou. “Let the door be<br>forced!”</p>\n<p>No one took a step.</p>\n<p>“Beard and belly!” said Clopin, “here be men afraid of a beam.”</p>\n<p>An old locksmith addressed him—</p>\n<p>“Captain, ’tis not the beam which bothers us, ’tis the door,<br>which is all covered with iron bars. Our pincers are powerless<br>against it.”</p>\n<p>“What more do you want to break it in?” demanded Clopin.</p>\n<p>“Ah! we ought to have a battering ram.”</p>\n<p>The King of Thunes ran boldly to the formidable beam, and placed<br>his foot upon it: “Here is one!” he exclaimed; “’tis the canons<br>who send it to you.” And, making a mocking salute in the<br>direction of the church, “Thanks, canons!”</p>\n<p>This piece of bravado produced its effects,—the spell of the beam<br>was broken. The vagabonds recovered their courage; soon the heavy<br>joist, raised like a feather by two hundred vigorous arms, was<br>flung with fury against the great door which they had tried to<br>batter down. At the sight of that long beam, in the half-light<br>which the infrequent torches of the brigands spread over the<br>Place, thus borne by that crowd of men who dashed it at a run<br>against the church, one would have thought that he beheld a<br>monstrous beast with a thousand feet attacking with lowered head<br>the giant of stone.</p>\n<p>At the shock of the beam, the half metallic door sounded like an<br>immense drum; it was not burst in, but the whole cathedral<br>trembled, and the deepest cavities of the edifice were heard to<br>echo.</p>\n<p>At the same moment, a shower of large stones began to fall from<br>the top of the façade on the assailants.</p>\n<p>“The devil!” cried Jehan, “are the towers shaking their<br>balustrades down on our heads?”</p>\n<p>But the impulse had been given, the King of Thunes had set the<br>example. Evidently, the bishop was defending himself, and they<br>only battered the door with the more rage, in spite of the stones<br>which cracked skulls right and left.</p>\n<p>It was remarkable that all these stones fell one by one; but they<br>followed each other closely. The thieves always felt two at a<br>time, one on their legs and one on their heads. There were few<br>which did not deal their blow, and a large layer of dead and<br>wounded lay bleeding and panting beneath the feet of the<br>assailants who, now grown furious, replaced each other without<br>intermission. The long beam continued to belabor the door, at<br>regular intervals, like the clapper of a bell, the stones to rain<br>down, the door to groan.</p>\n<p>The reader has no doubt divined that this unexpected resistance<br>which had exasperated the outcasts came from Quasimodo.</p>\n<p>Chance had, unfortunately, favored the brave deaf man.</p>\n<p>When he had descended to the platform between the towers, his<br>ideas were all in confusion. He had run up and down along the<br>gallery for several minutes like a madman, surveying from above,<br>the compact mass of vagabonds ready to hurl itself on the church,<br>demanding the safety of the gypsy from the devil or from God. The<br>thought had occurred to him of ascending to the southern belfry<br>and sounding the alarm, but before he could have set the bell in<br>motion, before Marie’s voice could have uttered a single clamor,<br>was there not time to burst in the door of the church ten times<br>over? It was precisely the moment when the locksmiths were<br>advancing upon it with their tools. What was to be done?</p>\n<p>All at once, he remembered that some masons had been at work all<br>day repairing the wall, the timber-work, and the roof of the<br>south tower. This was a flash of light. The wall was of stone,<br>the roof of lead, the timber-work of wood. (That prodigious<br>timber-work, so dense that it was called “the forest.”)</p>\n<p>Quasimodo hastened to that tower. The lower chambers were, in<br>fact, full of materials. There were piles of rough blocks of<br>stone, sheets of lead in rolls, bundles of laths, heavy beams<br>already notched with the saw, heaps of plaster.</p>\n<p>Time was pressing, The pikes and hammers were at work below. With<br>a strength which the sense of danger increased tenfold, he seized<br>one of the beams—the longest and heaviest; he pushed it out<br>through a loophole, then, grasping it again outside of the tower,<br>he made it slide along the angle of the balustrade which<br>surrounds the platform, and let it fly into the abyss. The<br>enormous timber, during that fall of a hundred and sixty feet,<br>scraping the wall, breaking the carvings, turned many times on<br>its centre, like the arm of a windmill flying off alone through<br>space. At last it reached the ground, the horrible cry arose, and<br>the black beam, as it rebounded from the pavement, resembled a<br>serpent leaping.</p>\n<p>Quasimodo beheld the outcasts scatter at the fall of the beam,<br>like ashes at the breath of a child. He took advantage of their<br>fright, and while they were fixing a superstitious glance on the<br>club which had fallen from heaven, and while they were putting<br>out the eyes of the stone saints on the front with a discharge of<br>arrows and buckshot, Quasimodo was silently piling up plaster,<br>stones, and rough blocks of stone, even the sacks of tools<br>belonging to the masons, on the edge of the balustrade from which<br>the beam had already been hurled.</p>\n<p>Thus, as soon as they began to batter the grand door, the shower<br>of rough blocks of stone began to fall, and it seemed to them<br>that the church itself was being demolished over their heads.</p>\n<p>Any one who could have beheld Quasimodo at that moment would have<br>been frightened. Independently of the projectiles which he had<br>piled upon the balustrade, he had collected a heap of stones on<br>the platform itself. As fast as the blocks on the exterior edge<br>were exhausted, he drew on the heap. Then he stooped and rose,<br>stooped and rose again with incredible activity. His huge gnome’s<br>head bent over the balustrade, then an enormous stone fell, then<br>another, then another. From time to time, he followed a fine<br>stone with his eye, and when it did good execution, he said,<br>“Hum!”</p>\n<p>Meanwhile, the beggars did not grow discouraged. The thick door<br>on which they were venting their fury had already trembled more<br>than twenty times beneath the weight of their oaken<br>battering-ram, multiplied by the strength of a hundred men. The<br>panels cracked, the carved work flew into splinters, the hinges,<br>at every blow, leaped from their pins, the planks yawned, the<br>wood crumbled to powder, ground between the iron sheathing.<br>Fortunately for Quasimodo, there was more iron than wood.</p>\n<p>Nevertheless, he felt that the great door was yielding. Although<br>he did not hear it, every blow of the ram reverberated<br>simultaneously in the vaults of the church and within it. From<br>above he beheld the vagabonds, filled with triumph and rage,<br>shaking their fists at the gloomy façade; and both on the gypsy’s<br>account and his own he envied the wings of the owls which flitted<br>away above his head in flocks.</p>\n<p>His shower of stone blocks was not sufficient to repel the<br>assailants.</p>\n<p>At this moment of anguish, he noticed, a little lower down than<br>the balustrade whence he was crushing the thieves, two long stone<br>gutters which discharged immediately over the great door; the<br>internal orifice of these gutters terminated on the pavement of<br>the platform. An idea occurred to him; he ran in search of a<br>fagot in his bellringer’s den, placed on this fagot a great many<br>bundles of laths, and many rolls of lead, munitions which he had<br>not employed so far, and having arranged this pile in front of<br>the hole to the two gutters, he set it on fire with his lantern.</p>\n<p>During this time, since the stones no longer fell, the outcasts<br>ceased to gaze into the air. The bandits, panting like a pack of<br>hounds who are forcing a boar into his lair, pressed tumultuously<br>round the great door, all disfigured by the battering ram, but<br>still standing. They were waiting with a quiver for the great<br>blow which should split it open. They vied with each other in<br>pressing as close as possible, in order to dash among the first,<br>when it should open, into that opulent cathedral, a vast<br>reservoir where the wealth of three centuries had been piled up.<br>They reminded each other with roars of exultation and greedy<br>lust, of the beautiful silver crosses, the fine copes of brocade,<br>the beautiful tombs of silver gilt, the great magnificences of<br>the choir, the dazzling festivals, the Christmasses sparkling<br>with torches, the Easters sparkling with sunshine,—all those<br>splendid solemneties wherein chandeliers, ciboriums, tabernacles,<br>and reliquaries, studded the altars with a crust of gold and<br>diamonds. Certainly, at that fine moment, thieves and pseudo<br>sufferers, doctors in stealing, and vagabonds, were thinking much<br>less of delivering the gypsy than of pillaging Notre-Dame. We<br>could even easily believe that for a goodly number among them la<br>Esmeralda was only a pretext, if thieves needed pretexts.</p>\n<p>All at once, at the moment when they were grouping themselves<br>round the ram for a last effort, each one holding his breath and<br>stiffening his muscles in order to communicate all his force to<br>the decisive blow, a howl more frightful still than that which<br>had burst forth and expired beneath the beam, rose among them.<br>Those who did not cry out, those who were still alive, looked.<br>Two streams of melted lead were falling from the summit of the<br>edifice into the thickest of the rabble. That sea of men had just<br>sunk down beneath the boiling metal, which had made, at the two<br>points where it fell, two black and smoking holes in the crowd,<br>such as hot water would make in snow. Dying men, half consumed<br>and groaning with anguish, could be seen writhing there. Around<br>these two principal streams there were drops of that horrible<br>rain, which scattered over the assailants and entered their<br>skulls like gimlets of fire. It was a heavy fire which<br>overwhelmed these wretches with a thousand hailstones.</p>\n<p>The outcry was heartrending. They fled pell-mell, hurling the<br>beam upon the bodies, the boldest as well as the most timid, and<br>the parvis was cleared a second time.</p>\n<p>All eyes were raised to the top of the church. They beheld there<br>an extraordinary sight. On the crest of the highest gallery,<br>higher than the central rose window, there was a great flame<br>rising between the two towers with whirlwinds of sparks, a vast,<br>disordered, and furious flame, a tongue of which was borne into<br>the smoke by the wind, from time to time. Below that fire, below<br>the gloomy balustrade with its trefoils showing darkly against<br>its glare, two spouts with monster throats were vomiting forth<br>unceasingly that burning rain, whose silvery stream stood out<br>against the shadows of the lower façade. As they approached the<br>earth, these two jets of liquid lead spread out in sheaves, like<br>water springing from the thousand holes of a watering-pot. Above<br>the flame, the enormous towers, two sides of each of which were<br>visible in sharp outline, the one wholly black, the other wholly<br>red, seemed still more vast with all the immensity of the shadow<br>which they cast even to the sky.</p>\n<p>Their innumerable sculptures of demons and dragons assumed a<br>lugubrious aspect. The restless light of the flame made them move<br>to the eye. There were griffins which had the air of laughing,<br>gargoyles which one fancied one heard yelping, salamanders which<br>puffed at the fire, tarasques[61] which sneezed in the smoke. And<br>among the monsters thus roused from their sleep of stone by this<br>flame, by this noise, there was one who walked about, and who was<br>seen, from time to time, to pass across the glowing face of the<br>pile, like a bat in front of a candle.</p>\n<p>Without doubt, this strange beacon light would awaken far away,<br>the woodcutter of the hills of Bicêtre, terrified to behold the<br>gigantic shadow of the towers of Notre-Dame quivering over his<br>heaths.</p>\n<p>A terrified silence ensued among the outcasts, during which<br>nothing was heard, but the cries of alarm of the canons shut up<br>in their cloister, and more uneasy than horses in a burning<br>stable, the furtive sound of windows hastily opened and still<br>more hastily closed, the internal hurly-burly of the houses and<br>of the Hôtel-Dieu, the wind in the flame, the last death-rattle<br>of the dying, and the continued crackling of the rain of lead<br>upon the pavement.</p>\n<p>In the meanwhile, the principal vagabonds had retired beneath the<br>porch of the Gondelaurier mansion, and were holding a council of<br>war.</p>\n<p>The Duke of Egypt, seated on a stone post, contemplated the<br>phantasmagorical bonfire, glowing at a height of two hundred feet<br>in the air, with religious terror. Clopin Trouillefou bit his<br>huge fists with rage.</p>\n<p>“Impossible to get in!” he muttered between his teeth.</p>\n<p>“An old, enchanted church!” grumbled the aged Bohemian, Mathias<br>Hungadi Spicali.</p>\n<p>“By the Pope’s whiskers!” went on a sham soldier, who had once<br>been in service, “here are church gutters spitting melted lead at<br>you better than the machicolations of Lectoure.”</p>\n<p>“Do you see that demon passing and repassing in front of the<br>fire?” exclaimed the Duke of Egypt.</p>\n<p>“Pardieu, ’tis that damned bellringer, ’tis Quasimodo,” said<br>Clopin.</p>\n<p>The Bohemian tossed his head. “I tell you, that ’tis the spirit<br>Sabnac, the grand marquis, the demon of fortifications. He has<br>the form of an armed soldier, the head of a lion. Sometimes he<br>rides a hideous horse. He changes men into stones, of which he<br>builds towers. He commands fifty legions ’Tis he indeed; I<br>recognize him. Sometimes he is clad in a handsome golden robe,<br>figured after the Turkish fashion.”</p>\n<p>“Where is Bellevigne de l’Étoile?” demanded Clopin.</p>\n<p>“He is dead.”</p>\n<p>Andry the Red laughed in an idiotic way: “Notre-Dame is making<br>work for the hospital,” said he.</p>\n<p>“Is there, then, no way of forcing this door,” exclaimed the King<br>of Thunes, stamping his foot.</p>\n<p>The Duke of Egypt pointed sadly to the two streams of boiling<br>lead which did not cease to streak the black façade, like two<br>long distaffs of phosphorus.</p>\n<p>“Churches have been known to defend themselves thus all by<br>themselves,” he remarked with a sigh. “Saint-Sophia at<br>Constantinople, forty years ago, hurled to the earth three times<br>in succession, the crescent of Mahom, by shaking her domes, which<br>are her heads. Guillaume de Paris, who built this one was a<br>magician.”</p>\n<p>“Must we then retreat in pitiful fashion, like highwaymen?” said<br>Clopin. “Must we leave our sister here, whom those hooded wolves<br>will hang to-morrow.”</p>\n<p>“And the sacristy, where there are wagon-loads of gold!” added a<br>vagabond, whose name, we regret to say, we do not know.</p>\n<p>“Beard of Mahom!” cried Trouillefou.</p>\n<p>“Let us make another trial,” resumed the vagabond.</p>\n<p>Mathias Hungadi shook his head.</p>\n<p>“We shall never get in by the door. We must find the defect in<br>the armor of the old fairy; a hole, a false postern, some joint<br>or other.”</p>\n<p>“Who will go with me?” said Clopin. “I shall go at it again. By<br>the way, where is the little scholar Jehan, who is so encased in<br>iron?”</p>\n<p>“He is dead, no doubt,” some one replied; “we no longer hear his<br>laugh.”</p>\n<p>The King of Thunes frowned: “So much the worse. There was a brave<br>heart under that ironmongery. And Master Pierre Gringoire?”</p>\n<p>“Captain Clopin,” said Andry the Red, “he slipped away before we<br>reached the Pont-aux-Changeurs.”</p>\n<p>Clopin stamped his foot. “<em>Gueule-Dieu!</em> ’twas he who pushed us<br>on hither, and he has deserted us in the very middle of the job!<br>Cowardly chatterer, with a slipper for a helmet!”</p>\n<p>“Captain Clopin,” said Andry the Red, who was gazing down Rue du<br>Parvis, “yonder is the little scholar.”</p>\n<p>“Praised be Pluto!” said Clopin. “But what the devil is he<br>dragging after him?”</p>\n<p>It was, in fact, Jehan, who was running as fast as his heavy<br>outfit of a Paladin, and a long ladder which trailed on the<br>pavement, would permit, more breathless than an ant harnessed to<br>a blade of grass twenty times longer than itself.</p>\n<p>“Victory! <em>Te Deum!</em>” cried the scholar. “Here is the ladder of<br>the longshoremen of Port Saint-Landry.”</p>\n<p>Clopin approached him.</p>\n<p>“Child, what do you mean to do, <em>corne-dieu!</em> with this ladder?”</p>\n<p>“I have it,” replied Jehan, panting. “I knew where it was under<br>the shed of the lieutenant’s house. There’s a wench there whom I<br>know, who thinks me as handsome as Cupido. I made use of her to<br>get the ladder, and I have the ladder, <em>Pasque-Mahom!</em> The poor<br>girl came to open the door to me in her shift.”</p>\n<p>“Yes,” said Clopin, “but what are you going to do with that<br>ladder?”</p>\n<p>Jehan gazed at him with a malicious, knowing look, and cracked<br>his fingers like castanets. At that moment he was sublime. On his<br>head he wore one of those overloaded helmets of the fifteenth<br>century, which frightened the enemy with their fanciful crests.<br>His bristled with ten iron beaks, so that Jehan could have<br>disputed with Nestor’s Homeric vessel the redoubtable title of<br>δεκέμβολος.</p>\n<p>“What do I mean to do with it, august king of Thunes? Do you see<br>that row of statues which have such idiotic expressions, yonder,<br>above the three portals?”</p>\n<p>“Yes. Well?”</p>\n<p>“’Tis the gallery of the kings of France.”</p>\n<p>“What is that to me?” said Clopin.</p>\n<p>“Wait! At the end of that gallery there is a door which is never<br>fastened otherwise than with a latch, and with this ladder I<br>ascend, and I am in the church.”</p>\n<p>“Child let me be the first to ascend.”</p>\n<p>“No, comrade, the ladder is mine. Come, you shall be the second.”</p>\n<p>“May Beelzebub strangle you!” said surly Clopin, “I won’t be<br>second to anybody.”</p>\n<p>“Then find a ladder, Clopin!”</p>\n<p>Jehan set out on a run across the Place, dragging his ladder and<br>shouting: “Follow me, lads!”</p>\n<p>In an instant the ladder was raised, and propped against the<br>balustrade of the lower gallery, above one of the lateral doors.<br>The throng of vagabonds, uttering loud acclamations, crowded to<br>its foot to ascend. But Jehan maintained his right, and was the<br>first to set foot on the rungs. The passage was tolerably long.<br>The gallery of the kings of France is to-day about sixty feet<br>above the pavement. The eleven steps of the flight before the<br>door, made it still higher. Jehan mounted slowly, a good deal<br>incommoded by his heavy armor, holding his crossbow in one hand,<br>and clinging to a rung with the other. When he reached the middle<br>of the ladder, he cast a melancholy glance at the poor dead<br>outcasts, with which the steps were strewn. “Alas!” said he,<br>“here is a heap of bodies worthy of the fifth book of the Iliad!”<br>Then he continued his ascent. The vagabonds followed him. There<br>was one on every rung. At the sight of this line of cuirassed<br>backs, undulating as they rose through the gloom, one would have<br>pronounced it a serpent with steel scales, which was raising<br>itself erect in front of the church. Jehan who formed the head,<br>and who was whistling, completed the illusion.</p>\n<p>The scholar finally reached the balcony of the gallery, and<br>climbed over it nimbly, to the applause of the whole vagabond<br>tribe. Thus master of the citadel, he uttered a shout of joy, and<br>suddenly halted, petrified. He had just caught sight of Quasimodo<br>concealed in the dark, with flashing eye, behind one of the<br>statues of the kings.</p>\n<p>Before a second assailant could gain a foothold on the gallery,<br>the formidable hunchback leaped to the head of the ladder,<br>without uttering a word, seized the ends of the two uprights with<br>his powerful hands, raised them, pushed them out from the wall,<br>balanced the long and pliant ladder, loaded with vagabonds from<br>top to bottom for a moment, in the midst of shrieks of anguish,<br>then suddenly, with superhuman force, hurled this cluster of men<br>backward into the Place. There was a moment when even the most<br>resolute trembled. The ladder, launched backwards, remained erect<br>and standing for an instant, and seemed to hesitate, then<br>wavered, then suddenly, describing a frightful arc of a circle<br>eighty feet in radius, crashed upon the pavement with its load of<br>ruffians, more rapidly than a drawbridge when its chains break.<br>There arose an immense imprecation, then all was still, and a few<br>mutilated wretches were seen, crawling over the heap of dead.</p>\n<p>A sound of wrath and grief followed the first cries of triumph<br>among the besiegers. Quasimodo, impassive, with both elbows<br>propped on the balustrade, looked on. He had the air of an old,<br>bushy-headed king at his window.</p>\n<p>As for Jehan Frollo, he was in a critical position. He found<br>himself in the gallery with the formidable bellringer, alone,<br>separated from his companions by a vertical wall eighty feet<br>high. While Quasimodo was dealing with the ladder, the scholar<br>had run to the postern which he believed to be open. It was not.<br>The deaf man had closed it behind him when he entered the<br>gallery. Jehan had then concealed himself behind a stone king,<br>not daring to breathe, and fixing upon the monstrous hunchback a<br>frightened gaze, like the man, who, when courting the wife of the<br>guardian of a menagerie, went one evening to a love rendezvous,<br>mistook the wall which he was to climb, and suddenly found<br>himself face to face with a white bear.</p>\n<p>For the first few moments, the deaf man paid no heed to him; but<br>at last he turned his head, and suddenly straightened up. He had<br>just caught sight of the scholar.</p>\n<p>Jehan prepared himself for a rough shock, but the deaf man<br>remained motionless; only he had turned towards the scholar and<br>was looking at him.</p>\n<p>“Ho ho!” said Jehan, “what do you mean by staring at me with that<br>solitary and melancholy eye?”</p>\n<p>As he spoke thus, the young scamp stealthily adjusted his<br>crossbow.</p>\n<p>“Quasimodo!” he cried, “I am going to change your surname: you<br>shall be called the blind man.”</p>\n<p>The shot sped. The feathered vireton[62] whizzed and entered the<br>hunchback’s left arm. Quasimodo appeared no more moved by it than<br>by a scratch to King Pharamond. He laid his hand on the arrow,<br>tore it from his arm, and tranquilly broke it across his big<br>knee; then he let the two pieces drop on the floor, rather than<br>threw them down. But Jehan had no opportunity to fire a second<br>time. The arrow broken, Quasimodo breathing heavily, bounded like<br>a grasshopper, and he fell upon the scholar, whose armor was<br>flattened against the wall by the blow.</p>\n<p>Then in that gloom, wherein wavered the light of the torches, a<br>terrible thing was seen.</p>\n<p>Quasimodo had grasped with his left hand the two arms of Jehan,<br>who did not offer any resistance, so thoroughly did he feel that<br>he was lost. With his right hand, the deaf man detached one by<br>one, in silence, with sinister slowness, all the pieces of his<br>armor, the sword, the daggers, the helmet, the cuirass, the leg<br>pieces. One would have said that it was a monkey taking the shell<br>from a nut. Quasimodo flung the scholar’s iron shell at his feet,<br>piece by piece. When the scholar beheld himself disarmed,<br>stripped, weak, and naked in those terrible hands, he made no<br>attempt to speak to the deaf man, but began to laugh audaciously<br>in his face, and to sing with his intrepid heedlessness of a<br>child of sixteen, the then popular ditty:—</p>\n<p>“Elle est bien habillée,<br>La ville de Cambrai;<br>Marafin l’a pillée....”[63]</p>\n<p>He did not finish. Quasimodo was seen on the parapet of the<br>gallery, holding the scholar by the feet with one hand and<br>whirling him over the abyss like a sling; then a sound like that<br>of a bony structure in contact with a wall was heard, and<br>something was seen to fall which halted a third of the way down<br>in its fall, on a projection in the architecture. It was a dead<br>body which remained hanging there, bent double, its loins broken,<br>its skull empty.</p>\n<p>A cry of horror rose among the vagabonds.</p>\n<p>“Vengeance!” shouted Clopin. “To the sack!” replied the<br>multitude. “Assault! assault!”</p>\n<p>There came a tremendous howl, in which were mingled all tongues,<br>all dialects, all accents. The death of the poor scholar imparted<br>a furious ardor to that crowd. It was seized with shame, and the<br>wrath of having been held so long in check before a church by a<br>hunchback. Rage found ladders, multiplied the torches, and, at<br>the expiration of a few minutes, Quasimodo, in despair, beheld<br>that terrible ant heap mount on all sides to the assault of<br>Notre-Dame. Those who had no ladders had knotted ropes; those who<br>had no ropes climbed by the projections of the carvings. They<br>hung from each other’s rags. There were no means of resisting<br>that rising tide of frightful faces; rage made these fierce<br>countenances ruddy; their clayey brows were dripping with sweat;<br>their eyes darted lightnings; all these grimaces, all these<br>horrors laid siege to Quasimodo. One would have said that some<br>other church had despatched to the assault of Notre-Dame its<br>gorgons, its dogs, its drées, its demons, its most fantastic<br>sculptures. It was like a layer of living monsters on the stone<br>monsters of the façade.</p>\n<p>Meanwhile, the Place was studded with a thousand torches. This<br>scene of confusion, till now hid in darkness, was suddenly<br>flooded with light. The parvis was resplendent, and cast a<br>radiance on the sky; the bonfire lighted on the lofty platform<br>was still burning, and illuminated the city far away. The<br>enormous silhouette of the two towers, projected afar on the<br>roofs of Paris, and formed a large notch of black in this light.<br>The city seemed to be aroused. Alarm bells wailed in the<br>distance. The vagabonds howled, panted, swore, climbed; and<br>Quasimodo, powerless against so many enemies, shuddering for the<br>gypsy, beholding the furious faces approaching ever nearer and<br>nearer to his gallery, entreated heaven for a miracle, and wrung<br>his arms in despair.</p>\n<h1 class=\"chapter\" id=\"chapter-v-the-retreat-in-which-monsieur-louis-of\">Chapter V. THE RETREAT IN WHICH MONSIEUR LOUIS OF FRANCE SAYS HIS</h1>\n<p>PRAYERS.</p>\n<p>The reader has not, perhaps, forgotten that one moment before<br>catching sight of the nocturnal band of vagabonds, Quasimodo, as<br>he inspected Paris from the heights of his bell tower, perceived<br>only one light burning, which gleamed like a star from a window<br>on the topmost story of a lofty edifice beside the Porte<br>Saint-Antoine. This edifice was the Bastille. That star was the<br>candle of Louis XI. King Louis XI. had, in fact, been two days in<br>Paris. He was to take his departure on the next day but one for<br>his citadel of Montilz-les-Tours. He made but seldom and brief<br>appearance in his good city of Paris, since there he did not feel<br>about him enough pitfalls, gibbets, and Scotch archers.</p>\n<p>He had come, that day, to sleep at the Bastille. The great<br>chamber five toises[64] square, which he had at the Louvre, with<br>its huge chimney-piece loaded with twelve great beasts and<br>thirteen great prophets, and his grand bed, eleven feet by<br>twelve, pleased him but little. He felt himself lost amid all<br>this grandeur. This good <em>bourgeois</em> king preferred the Bastille<br>with a tiny chamber and couch. And then, the Bastille was<br>stronger than the Louvre.</p>\n<p>This little chamber, which the king reserved for himself in the<br>famous state prison, was also tolerably spacious and occupied the<br>topmost story of a turret rising from the donjon keep. It was<br>circular in form, carpeted with mats of shining straw, ceiled<br>with beams, enriched with fleurs-de-lis of gilded metal with<br>interjoists in color; wainscoated with rich woods sown with<br>rosettes of white metal, and with others painted a fine, bright<br>green, made of orpiment and fine indigo.</p>\n<p>There was only one window, a long pointed casement, latticed with<br>brass wire and bars of iron, further darkened by fine colored<br>panes with the arms of the king and of the queen, each pane being<br>worth two and twenty sols.</p>\n<p>There was but one entrance, a modern door, with a flat arch,<br>garnished with a piece of tapestry on the inside, and on the<br>outside by one of those porches of Irish wood, frail edifices of<br>cabinet-work curiously wrought, numbers of which were still to be<br>seen in old houses a hundred and fifty years ago. “Although they<br>disfigure and embarrass the places,” says Sauvel in despair, “our<br>old people are still unwilling to get rid of them, and keep them<br>in spite of everybody.”</p>\n<p>In this chamber, nothing was to be found of what furnishes<br>ordinary apartments, neither benches, nor trestles, nor forms,<br>nor common stools in the form of a chest, nor fine stools<br>sustained by pillars and counter-pillars, at four sols a piece.<br>Only one easy arm-chair, very magnificent, was to be seen; the<br>wood was painted with roses on a red ground, the seat was of ruby<br>Cordovan leather, ornamented with long silken fringes, and<br>studded with a thousand golden nails. The loneliness of this<br>chair made it apparent that only one person had a right to sit<br>down in this apartment. Beside the chair, and quite close to the<br>window, there was a table covered with a cloth with a pattern of<br>birds. On this table stood an inkhorn spotted with ink, some<br>parchments, several pens, and a large goblet of chased silver. A<br>little further on was a brazier, a praying stool in crimson<br>velvet, relieved with small bosses of gold. Finally, at the<br>extreme end of the room, a simple bed of scarlet and yellow<br>damask, without either tinsel or lace; having only an ordinary<br>fringe. This bed, famous for having borne the sleep or the<br>sleeplessness of Louis XI., was still to be seen two hundred<br>years ago, at the house of a councillor of state, where it was<br>seen by old Madame Pilou, celebrated in <em>Cyrus</em> under the name<br><em>Arricidie</em> and of <em>la Morale Vivante</em>.</p>\n<p>Such was the chamber which was called “the retreat where Monsieur<br>Louis de France says his prayers.”</p>\n<p>At the moment when we have introduced the reader into it, this<br>retreat was very dark. The curfew bell had sounded an hour<br>before; night was come, and there was only one flickering wax<br>candle set on the table to light five persons variously grouped<br>in the chamber.</p>\n<p>The first on which the light fell was a seigneur superbly clad in<br>breeches and jerkin of scarlet striped with silver, and a loose<br>coat with half sleeves of cloth of gold with black figures. This<br>splendid costume, on which the light played, seemed glazed with<br>flame on every fold. The man who wore it had his armorial<br>bearings embroidered on his breast in vivid colors; a chevron<br>accompanied by a deer passant. The shield was flanked, on the<br>right by an olive branch, on the left by a deer’s antlers. This<br>man wore in his girdle a rich dagger whose hilt, of silver gilt,<br>was chased in the form of a helmet, and surmounted by a count’s<br>coronet. He had a forbidding air, a proud mien, and a head held<br>high. At the first glance one read arrogance on his visage; at<br>the second, craft.</p>\n<p>He was standing bareheaded, a long roll of parchment in his hand,<br>behind the arm-chair in which was seated, his body ungracefully<br>doubled up, his knees crossed, his elbow on the table, a very<br>badly accoutred personage. Let the reader imagine in fact, on the<br>rich seat of Cordova leather, two crooked knees, two thin thighs,<br>poorly clad in black worsted tricot, a body enveloped in a cloak<br>of fustian, with fur trimming of which more leather than hair was<br>visible; lastly, to crown all, a greasy old hat of the worst sort<br>of black cloth, bordered with a circular string of leaden<br>figures. This, in company with a dirty skull-cap, which hardly<br>allowed a hair to escape, was all that distinguished the seated<br>personage. He held his head so bent upon his breast, that nothing<br>was to be seen of his face thus thrown into shadow, except the<br>tip of his nose, upon which fell a ray of light, and which must<br>have been long. From the thinness of his wrinkled hand, one<br>divined that he was an old man. It was Louis XI. At some distance<br>behind them, two men dressed in garments of Flemish style were<br>conversing, who were not sufficiently lost in the shadow to<br>prevent any one who had been present at the performance of<br>Gringoire’s mystery from recognizing in them two of the principal<br>Flemish envoys, Guillaume Rym, the sagacious pensioner of Ghent,<br>and Jacques Coppenole, the popular hosier. The reader will<br>remember that these men were mixed up in the secret politics of<br>Louis XI. Finally, quite at the end of the room, near the door,<br>in the dark, stood, motionless as a statue, a vigorous man with<br>thickset limbs, a military harness, with a surcoat of armorial<br>bearings, whose square face pierced with staring eyes, slit with<br>an immense mouth, his ears concealed by two large screens of flat<br>hair, had something about it both of the dog and the tiger.</p>\n<p>All were uncovered except the king.</p>\n<p>The gentleman who stood near the king was reading him a sort of<br>long memorial to which his majesty seemed to be listening<br>attentively. The two Flemings were whispering together.</p>\n<p>“Cross of God!” grumbled Coppenole, “I am tired of standing; is<br>there no chair here?”</p>\n<p>Rym replied by a negative gesture, accompanied by a discreet<br>smile.</p>\n<p>“Croix-Dieu!” resumed Coppenole, thoroughly unhappy at being<br>obliged to lower his voice thus, “I should like to sit down on<br>the floor, with my legs crossed, like a hosier, as I do in my<br>shop.”</p>\n<p>“Take good care that you do not, Master Jacques.”</p>\n<p>“Ouais! Master Guillaume! can one only remain here on his feet?”</p>\n<p>“Or on his knees,” said Rym.</p>\n<p>At that moment the king’s voice was uplifted. They held their<br>peace.</p>\n<p>“Fifty sols for the robes of our valets, and twelve livres for<br>the mantles of the clerks of our crown! That’s it! Pour out gold<br>by the ton! Are you mad, Olivier?”</p>\n<p>As he spoke thus, the old man raised his head. The golden shells<br>of the collar of Saint-Michael could be seen gleaming on his<br>neck. The candle fully illuminated his gaunt and morose profile.<br>He tore the papers from the other’s hand.</p>\n<p>“You are ruining us!” he cried, casting his hollow eyes over the<br>scroll. “What is all this? What need have we of so prodigious a<br>household? Two chaplains at ten livres a month each, and, a<br>chapel clerk at one hundred sols! A valet-de-chambre at ninety<br>livres a year. Four head cooks at six score livres a year each! A<br>spit-cook, an herb-cook, a sauce-cook, a butler, two<br>sumpter-horse lackeys, at ten livres a month each! Two scullions<br>at eight livres! A groom of the stables and his two aids at four<br>and twenty livres a month! A porter, a pastry-cook, a baker, two<br>carters, each sixty livres a year! And the farrier six score<br>livres! And the master of the chamber of our funds, twelve<br>hundred livres! And the comptroller five hundred. And how do I<br>know what else? ’Tis ruinous. The wages of our servants are<br>putting France to the pillage! All the ingots of the Louvre will<br>melt before such a fire of expenses! We shall have to sell our<br>plate! And next year, if God and our Lady (here he raised his<br>hat) lend us life, we shall drink our potions from a pewter pot!”</p>\n<p>So saying, he cast a glance at the silver goblet which gleamed<br>upon the table. He coughed and continued,—</p>\n<p>“Master Olivier, the princes who reign over great lordships, like<br>kings and emperors, should not allow sumptuousness in their<br>houses; for the fire spreads thence through the province. Hence,<br>Master Olivier, consider this said once for all. Our expenditure<br>increases every year. The thing displease us. How, <em>pasque-Dieu!</em><br>when in ’79 it did not exceed six and thirty thousand livres, did<br>it attain in ’80, forty-three thousand six hundred and nineteen<br>livres? I have the figures in my head. In ’81, sixty-six thousand<br>six hundred and eighty livres, and this year, by the faith of my<br>body, it will reach eighty thousand livres! Doubled in four<br>years! Monstrous!”</p>\n<p>He paused breathless, then resumed energetically,—</p>\n<p>“I behold around me only people who fatten on my leanness! you<br>suck crowns from me at every pore.”</p>\n<p>All remained silent. This was one of those fits of wrath which<br>are allowed to take their course. He continued,—</p>\n<p>“’Tis like that request in Latin from the gentlemen of France,<br>that we should re-establish what they call the grand charges of<br>the Crown! Charges in very deed! Charges which crush! Ah!<br>gentlemen! you say that we are not a king to reign _dapifero<br>nullo, buticulario nullo!<em> We will let you see, </em>pasque-Dieu!_<br>whether we are not a king!”</p>\n<p>Here he smiled, in the consciousness of his power; this softened<br>his bad humor, and he turned towards the Flemings,—</p>\n<p>“Do you see, Gossip Guillaume? the grand warden of the keys, the<br>grand butler, the grand chamberlain, the grand seneschal are not<br>worth the smallest valet. Remember this, Gossip Coppenole. They<br>serve no purpose, as they stand thus useless round the king; they<br>produce upon me the effect of the four Evangelists who surround<br>the face of the big clock of the palace, and which Philippe<br>Brille has just set in order afresh. They are gilt, but they do<br>not indicate the hour; and the hands can get on without them.”</p>\n<p>He remained in thought for a moment, then added, shaking his aged<br>head,—</p>\n<p>“Ho! ho! by our Lady, I am not Philippe Brille, and I shall not<br>gild the great vassals anew. Continue, Olivier.”</p>\n<p>The person whom he designated by this name, took the papers into<br>his hands again, and began to read aloud,—</p>\n<p>“To Adam Tenon, clerk of the warden of the seals of the<br>provostship of Paris; for the silver, making, and engraving of<br>said seals, which have been made new because the others<br>preceding, by reason of their antiquity and their worn condition,<br>could no longer be successfully used, twelve livres parisis.</p>\n<p>“To Guillaume Frère, the sum of four livres, four sols parisis,<br>for his trouble and salary, for having nourished and fed the<br>doves in the two dove-cots of the Hôtel des Tournelles, during<br>the months of January, February, and March of this year; and for<br>this he hath given seven sextiers of barley.</p>\n<p>“To a gray friar for confessing a criminal, four sols parisis.”</p>\n<p>The king listened in silence. From time to time he coughed; then<br>he raised the goblet to his lips and drank a draught with a<br>grimace.</p>\n<p>“During this year there have been made by the ordinance of<br>justice, to the sound of the trumpet, through the squares of<br>Paris, fifty-six proclamations. Account to be regulated.</p>\n<p>“For having searched and ransacked in certain places, in Paris as<br>well as elsewhere, for money said to be there concealed; but<br>nothing hath been found: forty-five livres parisis.”</p>\n<p>“Bury a crown to unearth a sou!” said the king.</p>\n<p>“For having set in the Hôtel des Tournelles six panes of white<br>glass in the place where the iron cage is, thirteen sols; for<br>having made and delivered by command of the king, on the day of<br>the musters, four shields with the escutcheons of the said<br>seigneur, encircled with garlands of roses all about, six livres;<br>for two new sleeves to the king’s old doublet, twenty sols; for a<br>box of grease to grease the boots of the king, fifteen deniers; a<br>stable newly made to lodge the king’s black pigs, thirty livres<br>parisis; many partitions, planks, and trap-doors, for the<br>safekeeping of the lions at Saint-Paul, twenty-two livres.”</p>\n<p>“These be dear beasts,” said Louis XI. “It matters not; it is a<br>fine magnificence in a king. There is a great red lion whom I<br>love for his pleasant ways. Have you seen him, Master Guillaume?<br>Princes must have these terrific animals; for we kings must have<br>lions for our dogs and tigers for our cats. The great befits a<br>crown. In the days of the pagans of Jupiter, when the people<br>offered the temples a hundred oxen and a hundred sheep, the<br>emperors gave a hundred lions and a hundred eagles. This was wild<br>and very fine. The kings of France have always had roarings round<br>their throne. Nevertheless, people must do me this justice, that<br>I spend still less money on it than they did, and that I possess<br>a greater modesty of lions, bears, elephants, and leopards.—Go<br>on, Master Olivier. We wished to say thus much to our Flemish<br>friends.”</p>\n<p>Guillaume Rym bowed low, while Coppenole, with his surly mien,<br>had the air of one of the bears of which his majesty was<br>speaking. The king paid no heed. He had just dipped his lips into<br>the goblet, and he spat out the beverage, saying: “Foh! what a<br>disagreeable potion!” The man who was reading continued:—</p>\n<p>“For feeding a rascally footpad, locked up these six months in<br>the little cell of the flayer, until it should be determined what<br>to do with him, six livres, four sols.”</p>\n<p>“What’s that?” interrupted the king; “feed what ought to be<br>hanged! <em>Pasque-Dieu!</em> I will give not a sou more for that<br>nourishment. Olivier, come to an understanding about the matter<br>with Monsieur d’Estouteville, and prepare me this very evening<br>the wedding of the gallant and the gallows. Resume.”</p>\n<p>Olivier made a mark with his thumb against the article of the<br>“rascally foot soldier,” and passed on.</p>\n<p>“To Henriet Cousin, master executor of the high works of justice<br>in Paris, the sum of sixty sols parisis, to him assessed and<br>ordained by monseigneur the provost of Paris, for having bought,<br>by order of the said sieur the provost, a great broad sword,<br>serving to execute and decapitate persons who are by justice<br>condemned for their demerits, and he hath caused the same to be<br>garnished with a sheath and with all things thereto appertaining;<br>and hath likewise caused to be repointed and set in order the old<br>sword, which had become broken and notched in executing justice<br>on Messire Louis de Luxembourg, as will more fully appear....”</p>\n<p>The king interrupted: “That suffices. I allow the sum with great<br>good will. Those are expenses which I do not begrudge. I have<br>never regretted that money. Continue.”</p>\n<p>“For having made over a great cage....”</p>\n<p>“Ah!” said the king, grasping the arms of his chair in both<br>hands, “I knew well that I came hither to this Bastille for some<br>purpose. Hold, Master Olivier; I desire to see that cage myself.<br>You shall read me the cost while I am examining it. Messieurs<br>Flemings, come and see this; ’tis curious.”</p>\n<p>Then he rose, leaned on the arm of his interlocutor, made a sign<br>to the sort of mute who stood before the door to precede him, to<br>the two Flemings to follow him, and quitted the room.</p>\n<p>The royal company was recruited, at the door of the retreat, by<br>men of arms, all loaded down with iron, and by slender pages<br>bearing flambeaux. It marched for some time through the interior<br>of the gloomy donjon, pierced with staircases and corridors even<br>in the very thickness of the walls. The captain of the Bastille<br>marched at their head, and caused the wickets to be opened before<br>the bent and aged king, who coughed as he walked.</p>\n<p>At each wicket, all heads were obliged to stoop, except that of<br>the old man bent double with age. “Hum,” said he between his<br>gums, for he had no longer any teeth, “we are already quite<br>prepared for the door of the sepulchre. For a low door, a bent<br>passer.”</p>\n<p>At length, after having passed a final wicket, so loaded with<br>locks that a quarter of an hour was required to open it, they<br>entered a vast and lofty vaulted hall, in the centre of which<br>they could distinguish by the light of the torches, a huge cubic<br>mass of masonry, iron, and wood. The interior was hollow. It was<br>one of those famous cages of prisoners of state, which were<br>called “the little daughters of the king.” In its walls there<br>were two or three little windows so closely trellised with stout<br>iron bars; that the glass was not visible. The door was a large<br>flat slab of stone, as on tombs; the sort of door which serves<br>for entrance only. Only here, the occupant was alive.</p>\n<p>The king began to walk slowly round the little edifice, examining<br>it carefully, while Master Olivier, who followed him, read aloud<br>the note.</p>\n<p>“For having made a great cage of wood of solid beams, timbers and<br>wall-plates, measuring nine feet in length by eight in breadth,<br>and of the height of seven feet between the partitions, smoothed<br>and clamped with great bolts of iron, which has been placed in a<br>chamber situated in one of the towers of the Bastille<br>Saint-Antoine, in which cage is placed and detained, by command<br>of the king our lord, a prisoner who formerly inhabited an old,<br>decrepit, and ruined cage. There have been employed in making the<br>said new cage, ninety-six horizontal beams, and fifty-two upright<br>joists, ten wall plates three toises long; there have been<br>occupied nineteen carpenters to hew, work, and fit all the said<br>wood in the courtyard of the Bastille during twenty days.”</p>\n<p>“Very fine heart of oak,” said the king, striking the woodwork<br>with his fist.</p>\n<p>“There have been used in this cage,” continued the other, “two<br>hundred and twenty great bolts of iron, of nine feet, and of<br>eight, the rest of medium length, with the rowels, caps and<br>counterbands appertaining to the said bolts; weighing, the said<br>iron in all, three thousand, seven hundred and thirty-five<br>pounds; beside eight great squares of iron, serving to attach the<br>said cage in place with clamps and nails weighing in all two<br>hundred and eighteen pounds, not reckoning the iron of the<br>trellises for the windows of the chamber wherein the cage hath<br>been placed, the bars of iron for the door of the cage and other<br>things.”</p>\n<p>“’Tis a great deal of iron,” said the king, “to contain the light<br>of a spirit.”</p>\n<p>“The whole amounts to three hundred and seventeen livres, five<br>sols, seven deniers.”</p>\n<p>“<em>Pasque-Dieu!</em>” exclaimed the king.</p>\n<p>At this oath, which was the favorite of Louis XI., some one<br>seemed to awaken in the interior of the cage; the sound of chains<br>was heard, grating on the floor, and a feeble voice, which seemed<br>to issue from the tomb was uplifted. “Sire! sire! mercy!” The one<br>who spoke thus could not be seen.</p>\n<p>“Three hundred and seventeen livres, five sols, seven deniers,”<br>repeated Louis XI. The lamentable voice which had proceeded from<br>the cage had frozen all present, even Master Olivier himself. The<br>king alone wore the air of not having heard. At his order, Master<br>Olivier resumed his reading, and his majesty coldly continued his<br>inspection of the cage.</p>\n<p>“In addition to this there hath been paid to a mason who hath<br>made the holes wherein to place the gratings of the windows, and<br>the floor of the chamber where the cage is, because that floor<br>could not support this cage by reason of its weight, twenty-seven<br>livres fourteen sols parisis.”</p>\n<p>The voice began to moan again.</p>\n<p>“Mercy, sire! I swear to you that ’twas Monsieur the Cardinal<br>d’Angers and not I, who was guilty of treason.”</p>\n<p>“The mason is bold!” said the king. “Continue, Olivier.”</p>\n<p>Olivier continued,—</p>\n<p>“To a joiner for window frames, bedstead, hollow stool, and other<br>things, twenty livres, two sols parisis.”</p>\n<p>The voice also continued.</p>\n<p>“Alas, sire! will you not listen to me? I protest to you that<br>’twas not I who wrote the matter to Monseigneur de Guyenne, but<br>Monsieur le Cardinal Balue.”</p>\n<p>“The joiner is dear,” quoth the king. “Is that all?”</p>\n<p>“No, sire. To a glazier, for the windows of the said chamber,<br>forty-six sols, eight deniers parisis.”</p>\n<p>“Have mercy, sire! Is it not enough to have given all my goods to<br>my judges, my plate to Monsieur de Torcy, my library to Master<br>Pierre Doriolle, my tapestry to the governor of the Roussillon? I<br>am innocent. I have been shivering in an iron cage for fourteen<br>years. Have mercy, sire! You will find your reward in heaven.”</p>\n<p>“Master Olivier,” said the king, “the total?”</p>\n<p>“Three hundred sixty-seven livres, eight sols, three deniers<br>parisis.</p>\n<p>“Notre-Dame!” cried the king. “This is an outrageous cage!”</p>\n<p>He tore the book from Master Olivier’s hands, and set to<br>reckoning it himself upon his fingers, examining the paper and<br>the cage alternately. Meanwhile, the prisoner could be heard<br>sobbing. This was lugubrious in the darkness, and their faces<br>turned pale as they looked at each other.</p>\n<p>“Fourteen years, sire! Fourteen years now! since the month of<br>April, 1469. In the name of the Holy Mother of God, sire, listen<br>to me! During all this time you have enjoyed the heat of the sun.<br>Shall I, frail creature, never more behold the day? Mercy, sire!<br>Be pitiful! Clemency is a fine, royal virtue, which turns aside<br>the currents of wrath. Does your majesty believe that in the hour<br>of death it will be a great cause of content for a king never to<br>have left any offence unpunished? Besides, sire, I did not betray<br>your majesty, ’twas Monsieur d’Angers; and I have on my foot a<br>very heavy chain, and a great ball of iron at the end, much<br>heavier than it should be in reason. Eh! sire! Have pity on me!”</p>\n<p>“Olivier,” cried the king, throwing back his head, “I observe<br>that they charge me twenty sols a hogshead for plaster, while it<br>is worth but twelve. You will refer back this account.”</p>\n<p>He turned his back on the cage, and set out to leave the room.<br>The miserable prisoner divined from the removal of the torches<br>and the noise, that the king was taking his departure.</p>\n<p>“Sire! sire!” he cried in despair.</p>\n<p>The door closed again. He no longer saw anything, and heard only<br>the hoarse voice of the turnkey, singing in his ears this ditty,—</p>\n<p>“Maître Jean Balue,<br>A perdu la vue<br>De ses évêchés.<br>Monsieur de Verdun.<br>N’en a plus pas un;<br>Tous sont dépêchés.”[65]</p>\n<p>The king reascended in silence to his retreat, and his suite<br>followed him, terrified by the last groans of the condemned man.<br>All at once his majesty turned to the Governor of the Bastille,—</p>\n<p>“By the way,” said he, “was there not some one in that cage?”</p>\n<p>“Pardieu, yes sire!” replied the governor, astounded by the<br>question.</p>\n<p>“And who was it?”</p>\n<p>“Monsieur the Bishop of Verdun.”</p>\n<p>The king knew this better than any one else. But it was a mania<br>of his.</p>\n<p>“Ah!” said he, with the innocent air of thinking of it for the<br>first time, “Guillaume de Harancourt, the friend of Monsieur the<br>Cardinal Balue. A good devil of a bishop!”</p>\n<p>At the expiration of a few moments, the door of the retreat had<br>opened again, then closed upon the five personages whom the<br>reader has seen at the beginning of this chapter, and who resumed<br>their places, their whispered conversations, and their attitudes.</p>\n<p>During the king’s absence, several despatches had been placed on<br>his table, and he broke the seals himself. Then he began to read<br>them promptly, one after the other, made a sign to Master Olivier<br>who appeared to exercise the office of minister, to take a pen,<br>and without communicating to him the contents of the despatches,<br>he began to dictate in a low voice, the replies which the latter<br>wrote, on his knees, in an inconvenient attitude before the<br>table.</p>\n<p>Guillaume Rym was on the watch.</p>\n<p>The king spoke so low that the Flemings heard nothing of his<br>dictation, except some isolated and rather unintelligible scraps,<br>such as,—</p>\n<p>“To maintain the fertile places by commerce, and the sterile by<br>manufactures....—To show the English lords our four bombards,<br>London, Brabant, Bourg-en-Bresse, Saint-Omer....—Artillery is the<br>cause of war being made more judiciously now....—To Monsieur de<br>Bressuire, our friend....—Armies cannot be maintained without<br>tribute, etc.”</p>\n<p>Once he raised his voice,—</p>\n<p>“<em>Pasque Dieu!</em> Monsieur the King of Sicily seals his letters<br>with yellow wax, like a king of France. Perhaps we are in the<br>wrong to permit him so to do. My fair cousin of Burgundy granted<br>no armorial bearings with a field of gules. The grandeur of<br>houses is assured by the integrity of prerogatives. Note this,<br>friend Olivier.”</p>\n<p>Again,—</p>\n<p>“Oh! oh!” said he, “What a long message! What doth our brother<br>the emperor claim?” And running his eye over the missive and<br>breaking his reading with interjection: “Surely! the Germans are<br>so great and powerful, that it is hardly credible—But let us not<br>forget the old proverb: ‘The finest county is Flanders; the<br>finest duchy, Milan; the finest kingdom, France.’ Is it not so,<br>Messieurs Flemings?”</p>\n<p>This time Coppenole bowed in company with Guillaume Rym. The<br>hosier’s patriotism was tickled.</p>\n<p>The last despatch made Louis XI. frown.</p>\n<p>“What is this?” he said, “Complaints and fault finding against<br>our garrisons in Picardy! Olivier, write with diligence to M. the<br>Marshal de Rouault:—That discipline is relaxed. That the<br>gendarmes of the unattached troops, the feudal nobles, the free<br>archers, and the Swiss inflict infinite evils on the<br>rustics.—That the military, not content with what they find in<br>the houses of the rustics, constrain them with violent blows of<br>cudgel or of lash to go and get wine, spices, and other<br>unreasonable things in the town.—That monsieur the king knows<br>this. That we undertake to guard our people against<br>inconveniences, larcenies and pillage.—That such is our will, by<br>our Lady!—That in addition, it suits us not that any fiddler,<br>barber, or any soldier varlet should be clad like a prince, in<br>velvet, cloth of silk, and rings of gold.—That these vanities are<br>hateful to God.—That we, who are gentlemen, content ourselves<br>with a doublet of cloth at sixteen sols the ell, of Paris.—That<br>messieurs the camp-followers can very well come down to that,<br>also.—Command and ordain.—To Monsieur de Rouault, our<br>friend.—Good.”</p>\n<p>He dictated this letter aloud, in a firm tone, and in jerks. At<br>the moment when he finished it, the door opened and gave passage<br>to a new personage, who precipitated himself into the chamber,<br>crying in affright,—</p>\n<p>“Sire! sire! there is a sedition of the populace in Paris!” Louis<br>XI.’s grave face contracted; but all that was visible of his<br>emotion passed away like a flash of lightning. He controlled<br>himself and said with tranquil severity,—</p>\n<p>“Gossip Jacques, you enter very abruptly!”</p>\n<p>“Sire! sire! there is a revolt!” repeated Gossip Jacques<br>breathlessly.</p>\n<p>The king, who had risen, grasped him roughly by the arm, and said<br>in his ear, in such a manner as to be heard by him alone, with<br>concentrated rage and a sidelong glance at the Flemings,—</p>\n<p>“Hold your tongue! or speak low!”</p>\n<p>The new comer understood, and began in a low tone to give a very<br>terrified account, to which the king listened calmly, while<br>Guillaume Rym called Coppenole’s attention to the face and dress<br>of the new arrival, to his furred cowl, (<em>caputia fourrata</em>), his<br>short cape, (<em>epitogia curta</em>), his robe of black velvet, which<br>bespoke a president of the court of accounts.</p>\n<p>Hardly had this personage given the king some explanations, when<br>Louis XI. exclaimed, bursting into a laugh,—</p>\n<p>“In truth? Speak aloud, Gossip Coictier! What call is there for<br>you to talk so low? Our Lady knoweth that we conceal nothing from<br>our good friends the Flemings.”</p>\n<p>“But sire...”</p>\n<p>“Speak loud!”</p>\n<p>Gossip Coictier was struck dumb with surprise.</p>\n<p>“So,” resumed the king,—“speak sir,—there is a commotion among<br>the louts in our good city of Paris?”</p>\n<p>“Yes, sire.”</p>\n<p>“And which is moving you say, against monsieur the bailiff of the<br>Palais-de-Justice?”</p>\n<p>“So it appears,” said the gossip, who still stammered, utterly<br>astounded by the abrupt and inexplicable change which had just<br>taken place in the king’s thoughts.</p>\n<p>Louis XI. continued: “Where did the watch meet the rabble?”</p>\n<p>“Marching from the Grand Truanderie, towards the<br>Pont-aux-Changeurs. I met it myself as I was on my way hither to<br>obey your majesty’s commands. I heard some of them shouting:<br>‘Down with the bailiff of the palace!’”</p>\n<p>“And what complaints have they against the bailiff?”</p>\n<p>“Ah!” said Gossip Jacques, “because he is their lord.”</p>\n<p>“Really?”</p>\n<p>“Yes, sire. They are knaves from the Cour-des-Miracles. They have<br>been complaining this long while, of the bailiff, whose vassals<br>they are. They do not wish to recognize him either as judge or as<br>voyer?”[66]</p>\n<p>“Yes, certainly!” retorted the king with a smile of satisfaction<br>which he strove in vain to disguise.</p>\n<p>“In all their petitions to the Parliament, they claim to have but<br>two masters. Your majesty and their God, who is the devil, I<br>believe.”</p>\n<p>“Eh! eh!” said the king.</p>\n<p>He rubbed his hands, he laughed with that inward mirth which<br>makes the countenance beam; he was unable to dissimulate his joy,<br>although he endeavored at moments to compose himself. No one<br>understood it in the least, not even Master Olivier. He remained<br>silent for a moment, with a thoughtful but contented air.</p>\n<p>“Are they in force?” he suddenly inquired.</p>\n<p>“Yes, assuredly, sire,” replied Gossip Jacques.</p>\n<p>“How many?”</p>\n<p>“Six thousand at the least.”</p>\n<p>The king could not refrain from saying: “Good!” he went on,—</p>\n<p>“Are they armed?”</p>\n<p>“With scythes, pikes, hackbuts, pickaxes. All sorts of very<br>violent weapons.”</p>\n<p>The king did not appear in the least disturbed by this list.<br>Jacques considered it his duty to add,—</p>\n<p>“If your majesty does not send prompt succor to the bailiff, he<br>is lost.”</p>\n<p>“We will send,” said the king with an air of false seriousness.<br>“It is well. Assuredly we will send. Monsieur the bailiff is our<br>friend. Six thousand! They are desperate scamps! Their audacity<br>is marvellous, and we are greatly enraged at it. But we have only<br>a few people about us to-night. To-morrow morning will be time<br>enough.”</p>\n<p>Gossip Jacques exclaimed, “Instantly, sire! there will be time to<br>sack the bailiwick a score of times, to violate the seignory, to<br>hang the bailiff. For God’s sake, sire! send before to-morrow<br>morning.”</p>\n<p>The king looked him full in the face. “I have told you to-morrow<br>morning.”</p>\n<p>It was one of those looks to which one does not reply. After a<br>silence, Louis XI. raised his voice once more,—</p>\n<p>“You should know that, Gossip Jacques. What was—”</p>\n<p>He corrected himself. “What is the bailiff’s feudal<br>jurisdiction?”</p>\n<p>“Sire, the bailiff of the palace has the Rue Calendre as far as<br>the Rue de l’Herberie, the Place Saint-Michel, and the localities<br>vulgarly known as the Mureaux, situated near the church of<br>Notre-Dame des Champs (here Louis XI. raised the brim of his<br>hat), which hotels number thirteen, plus the Cour des Miracles,<br>plus the Maladerie, called the Banlieue, plus the whole highway<br>which begins at that Maladerie and ends at the Porte<br>Sainte-Jacques. Of these divers places he is voyer, high, middle,<br>and low, justiciary, full seigneur.”</p>\n<p>“Bless me!” said the king, scratching his left ear with his right<br>hand, “that makes a goodly bit of my city! Ah! monsieur the<br>bailiff was king of all that.”</p>\n<p>This time he did not correct himself. He continued dreamily, and<br>as though speaking to himself,—</p>\n<p>“Very fine, monsieur the bailiff! You had there between your<br>teeth a pretty slice of our Paris.”</p>\n<p>All at once he broke out explosively, “<em>Pasque-Dieu!</em> What people<br>are those who claim to be voyers, justiciaries, lords and masters<br>in our domains? who have their tollgates at the end of every<br>field? their gallows and their hangman at every cross-road among<br>our people? So that as the Greek believed that he had as many<br>gods as there were fountains, and the Persian as many as he<br>beheld stars, the Frenchman counts as many kings as he sees<br>gibbets! Pardieu! ’tis an evil thing, and the confusion of it<br>displeases me. I should greatly like to know whether it be the<br>mercy of God that there should be in Paris any other lord than<br>the king, any other judge than our parliament, any other emperor<br>than ourselves in this empire! By the faith of my soul! the day<br>must certainly come when there shall exist in France but one<br>king, one lord, one judge, one headsman, as there is in paradise<br>but one God!”</p>\n<p>He lifted his cap again, and continued, still dreamily, with the<br>air and accent of a hunter who is cheering on his pack of hounds:<br>“Good, my people! bravely done! break these false lords! do your<br>duty! at them! have at them! pillage them! take them! sack<br>them!... Ah! you want to be kings, messeigneurs? On, my people<br>on!”</p>\n<p>Here he interrupted himself abruptly, bit his lips as though to<br>take back his thought which had already half escaped, bent his<br>piercing eyes in turn on each of the five persons who surrounded<br>him, and suddenly grasping his hat with both hands and staring<br>full at it, he said to it: “Oh! I would burn you if you knew what<br>there was in my head.”</p>\n<p>Then casting about him once more the cautious and uneasy glance<br>of the fox re-entering his hole,—</p>\n<p>“No matter! we will succor monsieur the bailiff. Unfortunately,<br>we have but few troops here at the present moment, against so<br>great a populace. We must wait until to-morrow. The order will be<br>transmitted to the City and every one who is caught will be<br>immediately hung.”</p>\n<p>“By the way, sire,” said Gossip Coictier, “I had forgotten that<br>in the first agitation, the watch have seized two laggards of the<br>band. If your majesty desires to see these men, they are here.”</p>\n<p>“If I desire to see them!” cried the king. “What! <em>Pasque-Dieu!</em><br>You forget a thing like that! Run quick, you, Olivier! Go, seek<br>them!”</p>\n<p>Master Olivier quitted the room and returned a moment later with<br>the two prisoners, surrounded by archers of the guard. The first<br>had a coarse, idiotic, drunken and astonished face. He was<br>clothed in rags, and walked with one knee bent and dragging his<br>leg. The second had a pallid and smiling countenance, with which<br>the reader is already acquainted.</p>\n<p>The king surveyed them for a moment without uttering a word, then<br>addressing the first one abruptly,—</p>\n<p>“What’s your name?”</p>\n<p>“Gieffroy Pincebourde.”</p>\n<p>“Your trade.”</p>\n<p>“Outcast.”</p>\n<p>“What were you going to do in this damnable sedition?”</p>\n<p>The outcast stared at the king, and swung his arms with a stupid<br>air.</p>\n<p>He had one of those awkwardly shaped heads where intelligence is<br>about as much at its ease as a light beneath an extinguisher.</p>\n<p>“I know not,” said he. “They went, I went.”</p>\n<p>“Were you not going to outrageously attack and pillage your lord,<br>the bailiff of the palace?”</p>\n<p>“I know that they were going to take something from some one.<br>That is all.”</p>\n<p>A soldier pointed out to the king a billhook which he had seized<br>on the person of the vagabond.</p>\n<p>“Do you recognize this weapon?” demanded the king.</p>\n<p>“Yes; ’tis my billhook; I am a vine-dresser.”</p>\n<p>“And do you recognize this man as your companion?” added Louis<br>XI., pointing to the other prisoner.</p>\n<p>“No, I do not know him.”</p>\n<p>“That will do,” said the king, making a sign with his finger to<br>the silent personage who stood motionless beside the door, to<br>whom we have already called the reader’s attention.</p>\n<p>“Gossip Tristan, here is a man for you.”</p>\n<p>Tristan l’Hermite bowed. He gave an order in a low voice to two<br>archers, who led away the poor vagabond.</p>\n<p>In the meantime, the king had approached the second prisoner, who<br>was perspiring in great drops: “Your name?”</p>\n<p>“Sire, Pierre Gringoire.”</p>\n<p>“Your trade?”</p>\n<p>“Philosopher, sire.”</p>\n<p>“How do you permit yourself, knave, to go and besiege our friend,<br>monsieur the bailiff of the palace, and what have you to say<br>concerning this popular agitation?”</p>\n<p>“Sire, I had nothing to do with it.”</p>\n<p>“Come, now! you wanton wretch, were not you apprehended by the<br>watch in that bad company?”</p>\n<p>“No, sire, there is a mistake. ’Tis a fatality. I make tragedies.<br>Sire, I entreat your majesty to listen to me. I am a poet. ’Tis<br>the melancholy way of men of my profession to roam the streets by<br>night. I was passing there. It was mere chance. I was unjustly<br>arrested; I am innocent of this civil tempest. Your majesty sees<br>that the vagabond did not recognize me. I conjure your majesty—”</p>\n<p>“Hold your tongue!” said the king, between two swallows of his<br>ptisan. “You split our head!”</p>\n<p>Tristan l’Hermite advanced and pointing to Gringoire,—</p>\n<p>“Sire, can this one be hanged also?”</p>\n<p>This was the first word that he had uttered.</p>\n<p>“Phew!” replied the king, “I see no objection.”</p>\n<p>“I see a great many!” said Gringoire.</p>\n<p>At that moment, our philosopher was greener than an olive. He<br>perceived from the king’s cold and indifferent mien that there<br>was no other resource than something very pathetic, and he flung<br>himself at the feet of Louis XI., exclaiming, with gestures of<br>despair:—</p>\n<p>“Sire! will your majesty deign to hear me. Sire! break not in<br>thunder over so small a thing as myself. God’s great lightning<br>doth not bombard a lettuce. Sire, you are an august and, very<br>puissant monarch; have pity on a poor man who is honest, and who<br>would find it more difficult to stir up a revolt than a cake of<br>ice would to give out a spark! Very gracious sire, kindness is<br>the virtue of a lion and a king. Alas! rigor only frightens<br>minds; the impetuous gusts of the north wind do not make the<br>traveller lay aside his cloak; the sun, bestowing his rays little<br>by little, warms him in such ways that it will make him strip to<br>his shirt. Sire, you are the sun. I protest to you, my sovereign<br>lord and master, that I am not an outcast, thief, and disorderly<br>fellow. Revolt and brigandage belong not to the outfit of Apollo.<br>I am not the man to fling myself into those clouds which break<br>out into seditious clamor. I am your majesty’s faithful vassal.<br>That same jealousy which a husband cherisheth for the honor of<br>his wife, the resentment which the son hath for the love of his<br>father, a good vassal should feel for the glory of his king; he<br>should pine away for the zeal of this house, for the<br>aggrandizement of his service. Every other passion which should<br>transport him would be but madness. These, sire, are my maxims of<br>state: then do not judge me to be a seditious and thieving rascal<br>because my garment is worn at the elbows. If you will grant me<br>mercy, sire, I will wear it out on the knees in praying to God<br>for you night and morning! Alas! I am not extremely rich, ’tis<br>true. I am even rather poor. But not vicious on that account. It<br>is not my fault. Every one knoweth that great wealth is not to be<br>drawn from literature, and that those who are best posted in good<br>books do not always have a great fire in winter. The advocate’s<br>trade taketh all the grain, and leaveth only straw to the other<br>scientific professions. There are forty very excellent proverbs<br>anent the hole-ridden cloak of the philosopher. Oh, sire!<br>clemency is the only light which can enlighten the interior of so<br>great a soul. Clemency beareth the torch before all the other<br>virtues. Without it they are but blind men groping after God in<br>the dark. Compassion, which is the same thing as clemency,<br>causeth the love of subjects, which is the most powerful<br>bodyguard to a prince. What matters it to your majesty, who<br>dazzles all faces, if there is one poor man more on earth, a poor<br>innocent philosopher spluttering amid the shadows of calamity,<br>with an empty pocket which resounds against his hollow belly?<br>Moreover, sire, I am a man of letters. Great kings make a pearl<br>for their crowns by protecting letters. Hercules did not disdain<br>the title of Musagetes. Mathias Corvin favored Jean de Monroyal,<br>the ornament of mathematics. Now, ’tis an ill way to protect<br>letters to hang men of letters. What a stain on Alexander if he<br>had hung Aristoteles! This act would not be a little patch on the<br>face of his reputation to embellish it, but a very malignant<br>ulcer to disfigure it. Sire! I made a very proper epithalamium<br>for Mademoiselle of Flanders and Monseigneur the very august<br>Dauphin. That is not a firebrand of rebellion. Your majesty sees<br>that I am not a scribbler of no reputation, that I have studied<br>excellently well, and that I possess much natural eloquence. Have<br>mercy upon me, sire! In so doing you will perform a gallant deed<br>to our Lady, and I swear to you that I am greatly terrified at<br>the idea of being hanged!”</p>\n<p>So saying, the unhappy Gringoire kissed the king’s slippers, and<br>Guillaume Rym said to Coppenole in a low tone: “He doth well to<br>drag himself on the earth. Kings are like the Jupiter of Crete,<br>they have ears only in their feet.” And without troubling himself<br>about the Jupiter of Crete, the hosier replied with a heavy<br>smile, and his eyes fixed on Gringoire: “Oh! that’s it exactly! I<br>seem to hear Chancellor Hugonet craving mercy of me.”</p>\n<p>When Gringoire paused at last, quite out of breath, he raised his<br>head tremblingly towards the king, who was engaged in scratching<br>a spot on the knee of his breeches with his finger-nail; then his<br>majesty began to drink from the goblet of ptisan. But he uttered<br>not a word, and this silence tortured Gringoire. At last the king<br>looked at him. “Here is a terrible bawler!” said, he. Then,<br>turning to Tristan l’Hermite, “Bah! let him go!”</p>\n<p>Gringoire fell backwards, quite thunderstruck with joy.</p>\n<p>“At liberty!” growled Tristan “Doth not your majesty wish to have<br>him detained a little while in a cage?”</p>\n<p>“Gossip,” retorted Louis XI., “think you that ’tis for birds of<br>this feather that we cause to be made cages at three hundred and<br>sixty-seven livres, eight sous, three deniers apiece? Release him<br>at once, the wanton (Louis XI. was fond of this word which<br>formed, with <em>Pasque-Dieu</em>, the foundation of his joviality), and<br>put him out with a buffet.”</p>\n<p>“Ugh!” cried Gringoire, “what a great king is here!”</p>\n<p>And for fear of a counter order, he rushed towards the door,<br>which Tristan opened for him with a very bad grace. The soldiers<br>left the room with him, pushing him before them with stout<br>thwacks, which Gringoire bore like a true stoical philosopher.</p>\n<p>The king’s good humor since the revolt against the bailiff had<br>been announced to him, made itself apparent in every way. This<br>unwonted clemency was no small sign of it. Tristan l’Hermite in<br>his corner wore the surly look of a dog who has had a bone<br>snatched away from him.</p>\n<p>Meanwhile, the king thrummed gayly with his fingers on the arm of<br>his chair, the March of Pont-Audemer. He was a dissembling<br>prince, but one who understood far better how to hide his<br>troubles than his joys. These external manifestations of joy at<br>any good news sometimes proceeded to very great lengths thus, on<br>the death, of Charles the Bold, to the point of vowing silver<br>balustrades to Saint Martin of Tours; on his advent to the<br>throne, so far as forgetting to order his father’s obsequies.</p>\n<p>“Hé! sire!” suddenly exclaimed Jacques Coictier, “what has become<br>of the acute attack of illness for which your majesty had me<br>summoned?”</p>\n<p>“Oh!” said the king, “I really suffer greatly, my gossip. There<br>is a hissing in my ear and fiery rakes rack my chest.”</p>\n<p>Coictier took the king’s hand, and begun to feel of his pulse<br>with a knowing air.</p>\n<p>“Look, Coppenole,” said Rym, in a low voice. “Behold him between<br>Coictier and Tristan. They are his whole court. A physician for<br>himself, a headsman for others.”</p>\n<p>As he felt the king’s pulse, Coictier assumed an air of greater<br>and greater alarm. Louis XI. watched him with some anxiety.<br>Coictier grew visibly more gloomy. The brave man had no other<br>farm than the king’s bad health. He speculated on it to the best<br>of his ability.</p>\n<p>“Oh! oh!” he murmured at length, “this is serious indeed.”</p>\n<p>“Is it not?” said the king, uneasily.</p>\n<p>“<em>Pulsus creber, anhelans, crepitans, irregularis</em>,” continued<br>the leech.</p>\n<p>“<em>Pasque-Dieu!</em>”</p>\n<p>“This may carry off its man in less than three days.”</p>\n<p>“Our Lady!” exclaimed the king. “And the remedy, gossip?”</p>\n<p>“I am meditating upon that, sire.”</p>\n<p>He made Louis XI. put out his tongue, shook his head, made a<br>grimace, and in the very midst of these affectations,—</p>\n<p>“Pardieu, sire,” he suddenly said, “I must tell you that there is<br>a receivership of the royal prerogatives vacant, and that I have<br>a nephew.”</p>\n<p>“I give the receivership to your nephew, Gossip Jacques,” replied<br>the king; “but draw this fire from my breast.”</p>\n<p>“Since your majesty is so clement,” replied the leech, “you will<br>not refuse to aid me a little in building my house, Rue<br>Saint-André-des-Arcs.”</p>\n<p>“Heugh!” said the king.</p>\n<p>“I am at the end of my finances,” pursued the doctor; “and it<br>would really be a pity that the house should not have a roof; not<br>on account of the house, which is simple and thoroughly<br><em>bourgeois</em>, but because of the paintings of Jehan Fourbault,<br>which adorn its wainscoating. There is a Diana flying in the air,<br>but so excellent, so tender, so delicate, of so ingenuous an<br>action, her hair so well coiffed and adorned with a crescent, her<br>flesh so white, that she leads into temptation those who regard<br>her too curiously. There is also a Ceres. She is another very<br>fair divinity. She is seated on sheaves of wheat and crowned with<br>a gallant garland of wheat ears interlaced with salsify and other<br>flowers. Never were seen more amorous eyes, more rounded limbs, a<br>nobler air, or a more gracefully flowing skirt. She is one of the<br>most innocent and most perfect beauties whom the brush has ever<br>produced.”</p>\n<p>“Executioner!” grumbled Louis XI., “what are you driving at?”</p>\n<p>“I must have a roof for these paintings, sire, and, although ’tis<br>but a small matter, I have no more money.”</p>\n<p>“How much doth your roof cost?”</p>\n<p>“Why a roof of copper, embellished and gilt, two thousand livres<br>at the most.”</p>\n<p>“Ah, assassin!” cried the king, “He never draws out one of my<br>teeth which is not a diamond.”</p>\n<p>“Am I to have my roof?” said Coictier.</p>\n<p>“Yes; and go to the devil, but cure me.”</p>\n<p>Jacques Coictier bowed low and said,—</p>\n<p>“Sire, it is a repellent which will save you. We will apply to<br>your loins the great defensive composed of cerate, Armenian bole,<br>white of egg, oil, and vinegar. You will continue your ptisan and<br>we will answer for your majesty.”</p>\n<p>A burning candle does not attract one gnat alone. Master Olivier,<br>perceiving the king to be in a liberal mood, and judging the<br>moment to be propitious, approached in his turn.</p>\n<p>“Sire—”</p>\n<p>“What is it now?” said Louis XI. “Sire, your majesty knoweth that<br>Simon Radin is dead?”</p>\n<p>“Well?”</p>\n<p>“He was councillor to the king in the matter of the courts of the<br>treasury.”</p>\n<p>“Well?”</p>\n<p>“Sire, his place is vacant.”</p>\n<p>As he spoke thus, Master Olivier’s haughty face quitted its<br>arrogant expression for a lowly one. It is the only change which<br>ever takes place in a courtier’s visage. The king looked him well<br>in the face and said in a dry tone,—“I understand.”</p>\n<p>He resumed,—</p>\n<p>“Master Olivier, the Marshal de Boucicaut was wont to say,<br>‘There’s no master save the king, there are no fishes save in the<br>sea.’ I see that you agree with Monsieur de Boucicaut. Now listen<br>to this; we have a good memory. In ’68 we made you valet of our<br>chamber: in ’69, guardian of the fortress of the bridge of<br>Saint-Cloud, at a hundred livres of Tournay in wages (you wanted<br>them of Paris). In November, ’73, by letters given to Gergeole,<br>we instituted you keeper of the Wood of Vincennes, in the place<br>of Gilbert Acle, equerry; in ’75, gruyer[67] of the forest of<br>Rouvray-lez-Saint-Cloud, in the place of Jacques le Maire; in<br>’78, we graciously settled on you, by letters patent sealed<br>doubly with green wax, an income of ten livres parisis, for you<br>and your wife, on the Place of the Merchants, situated at the<br>School Saint-Germain; in ’79, we made you gruyer of the forest of<br>Senart, in place of that poor Jehan Daiz; then captain of the<br>Château of Loches; then governor of Saint-Quentin; then captain<br>of the bridge of Meulan, of which you cause yourself to be called<br>comte. Out of the five sols fine paid by every barber who shaves<br>on a festival day, there are three sols for you and we have the<br>rest. We have been good enough to change your name of Le Mauvais<br>(The Evil), which resembled your face too closely. In ’76, we<br>granted you, to the great displeasure of our nobility, armorial<br>bearings of a thousand colors, which give you the breast of a<br>peacock. <em>Pasque-Dieu!</em> Are not you surfeited? Is not the draught<br>of fishes sufficiently fine and miraculous? Are you not afraid<br>that one salmon more will make your boat sink? Pride will be your<br>ruin, gossip. Ruin and disgrace always press hard on the heels of<br>pride. Consider this and hold your tongue.”</p>\n<p>These words, uttered with severity, made Master Olivier’s face<br>revert to its insolence.</p>\n<p>“Good!” he muttered, almost aloud, “’tis easy to see that the<br>king is ill to-day; he giveth all to the leech.”</p>\n<p>Louis XI. far from being irritated by this petulant insult,<br>resumed with some gentleness, “Stay, I was forgetting that I made<br>you my ambassador to Madame Marie, at Ghent. Yes, gentlemen,”<br>added the king turning to the Flemings, “this man hath been an<br>ambassador. There, my gossip,” he pursued, addressing Master<br>Olivier, “let us not get angry; we are old friends. ’Tis very<br>late. We have terminated our labors. Shave me.”</p>\n<p>Our readers have not, without doubt, waited until the present<br>moment to recognize in Master Olivier that terrible Figaro whom<br>Providence, the great maker of dramas, mingled so artistically in<br>the long and bloody comedy of the reign of Louis XI. We will not<br>here undertake to develop that singular figure. This barber of<br>the king had three names. At court he was politely called Olivier<br>le Daim (the Deer); among the people Olivier the Devil. His real<br>name was Olivier le Mauvais.</p>\n<p>Accordingly, Olivier le Mauvais remained motionless, sulking at<br>the king, and glancing askance at Jacques Coictier.</p>\n<p>“Yes, yes, the physician!” he said between his teeth.</p>\n<p>“Ah, yes, the physician!” retorted Louis XI., with singular good<br>humor; “the physician has more credit than you. ’Tis very simple;<br>he has taken hold upon us by the whole body, and you hold us only<br>by the chin. Come, my poor barber, all will come right. What<br>would you say and what would become of your office if I were a<br>king like Chilperic, whose gesture consisted in holding his beard<br>in one hand? Come, gossip mine, fulfil your office, shave me. Go<br>get what you need therefor.”</p>\n<p>Olivier perceiving that the king had made up his mind to laugh,<br>and that there was no way of even annoying him, went off<br>grumbling to execute his orders.</p>\n<p>The king rose, approached the window, and suddenly opening it<br>with extraordinary agitation,—</p>\n<p>“Oh! yes!” he exclaimed, clapping his hands, “yonder is a redness<br>in the sky over the City. ’Tis the bailiff burning. It can be<br>nothing else but that. Ah! my good people! here you are aiding me<br>at last in tearing down the rights of lordship!”</p>\n<p>Then turning towards the Flemings: “Come, look at this,<br>gentlemen. Is it not a fire which gloweth yonder?”</p>\n<p>The two men of Ghent drew near.</p>\n<p>“A great fire,” said Guillaume Rym.</p>\n<p>“Oh!” exclaimed Coppenole, whose eyes suddenly flashed, “that<br>reminds me of the burning of the house of the Seigneur<br>d’Hymbercourt. There must be a goodly revolt yonder.”</p>\n<p>“You think so, Master Coppenole?” And Louis XI.’s glance was<br>almost as joyous as that of the hosier. “Will it not be difficult<br>to resist?”</p>\n<p>“Cross of God! Sire! Your majesty will damage many companies of<br>men of war thereon.”</p>\n<p>“Ah! I! ’tis different,” returned the king. “If I willed.”</p>\n<p>The hosier replied hardily,—</p>\n<p>“If this revolt be what I suppose, sire, you might will in vain.”</p>\n<p>“Gossip,” said Louis XI., “with the two companies of my<br>unattached troops and one discharge of a serpentine, short work<br>is made of a populace of louts.”</p>\n<p>The hosier, in spite of the signs made to him by Guillaume Rym,<br>appeared determined to hold his own against the king.</p>\n<p>“Sire, the Swiss were also louts. Monsieur the Duke of Burgundy<br>was a great gentleman, and he turned up his nose at that rabble<br>rout. At the battle of Grandson, sire, he cried: ‘Men of the<br>cannon! Fire on the villains!’ and he swore by Saint-George. But<br>Advoyer Scharnachtal hurled himself on the handsome duke with his<br>battle-club and his people, and when the glittering Burgundian<br>army came in contact with these peasants in bull hides, it flew<br>in pieces like a pane of glass at the blow of a pebble. Many<br>lords were then slain by low-born knaves; and Monsieur de<br>Château-Guyon, the greatest seigneur in Burgundy, was found dead,<br>with his gray horse, in a little marsh meadow.”</p>\n<p>“Friend,” returned the king, “you are speaking of a battle. The<br>question here is of a mutiny. And I will gain the upper hand of<br>it as soon as it shall please me to frown.”</p>\n<p>The other replied indifferently,—</p>\n<p>“That may be, sire; in that case, ’tis because the people’s hour<br>hath not yet come.”</p>\n<p>Guillaume Rym considered it incumbent on him to intervene,—</p>\n<p>“Master Coppenole, you are speaking to a puissant king.”</p>\n<p>“I know it,” replied the hosier, gravely.</p>\n<p>“Let him speak, Monsieur Rym, my friend,” said the king; “I love<br>this frankness of speech. My father, Charles the Seventh, was<br>accustomed to say that the truth was ailing; I thought her dead,<br>and that she had found no confessor. Master Coppenole undeceiveth<br>me.”</p>\n<p>Then, laying his hand familiarly on Coppenole’s shoulder,—</p>\n<p>“You were saying, Master Jacques?”</p>\n<p>“I say, sire, that you may possibly be in the right, that the<br>hour of the people may not yet have come with you.”</p>\n<p>Louis XI. gazed at him with his penetrating eye,—</p>\n<p>“And when will that hour come, master?”</p>\n<p>“You will hear it strike.”</p>\n<p>“On what clock, if you please?”</p>\n<p>Coppenole, with his tranquil and rustic countenance, made the<br>king approach the window.</p>\n<p>“Listen, sire! There is here a donjon keep, a belfry, cannons,<br><em>bourgeois</em>, soldiers; when the belfry shall hum, when the<br>cannons shall roar, when the donjon shall fall in ruins amid<br>great noise, when <em>bourgeois</em> and soldiers shall howl and slay<br>each other, the hour will strike.”</p>\n<p>Louis’s face grew sombre and dreamy. He remained silent for a<br>moment, then he gently patted with his hand the thick wall of the<br>donjon, as one strokes the haunches of a steed.</p>\n<p>“Oh! no!” said he. “You will not crumble so easily, will you, my<br>good Bastille?”</p>\n<p>And turning with an abrupt gesture towards the sturdy Fleming,—</p>\n<p>“Have you never seen a revolt, Master Jacques?”</p>\n<p>“I have made them,” said the hosier.</p>\n<p>“How do you set to work to make a revolt?” said the king.</p>\n<p>“Ah!” replied Coppenole, “’tis not very difficult. There are a<br>hundred ways. In the first place, there must be discontent in the<br>city. The thing is not uncommon. And then, the character of the<br>inhabitants. Those of Ghent are easy to stir into revolt. They<br>always love the prince’s son; the prince, never. Well! One<br>morning, I will suppose, some one enters my shop, and says to me:<br>‘Father Coppenole, there is this and there is that, the<br>Demoiselle of Flanders wishes to save her ministers, the grand<br>bailiff is doubling the impost on shagreen, or something<br>else,’—what you will. I leave my work as it stands, I come out of<br>my hosier’s stall, and I shout: ‘To the sack?’ There is always<br>some smashed cask at hand. I mount it, and I say aloud, in the<br>first words that occur to me, what I have on my heart; and when<br>one is of the people, sire, one always has something on the<br>heart. Then people troop up, they shout, they ring the alarm<br>bell, they arm the louts with what they take from the soldiers,<br>the market people join in, and they set out. And it will always<br>be thus, so long as there are lords in the seignories,<br><em>bourgeois</em> in the bourgs, and peasants in the country.”</p>\n<p>“And against whom do you thus rebel?” inquired the king; “against<br>your bailiffs? against your lords?”</p>\n<p>“Sometimes; that depends. Against the duke, also, sometimes.”</p>\n<p>Louis XI. returned and seated himself, saying, with a smile,—</p>\n<p>“Ah! here they have only got as far as the bailiffs.”</p>\n<p>At that instant Olivier le Daim returned. He was followed by two<br>pages, who bore the king’s toilet articles; but what struck Louis<br>XI. was that he was also accompanied by the provost of Paris and<br>the chevalier of the watch, who appeared to be in consternation.<br>The spiteful barber also wore an air of consternation, which was<br>one of contentment beneath, however. It was he who spoke first.</p>\n<p>“Sire, I ask your majesty’s pardon for the calamitous news which<br>I bring.”</p>\n<p>The king turned quickly and grazed the mat on the floor with the<br>feet of his chair,—</p>\n<p>“What does this mean?”</p>\n<p>“Sire,” resumed Olivier le Daim, with the malicious air of a man<br>who rejoices that he is about to deal a violent blow, “’tis not<br>against the bailiff of the courts that this popular sedition is<br>directed.”</p>\n<p>“Against whom, then?”</p>\n<p>“Against you, sire?’</p>\n<p>The aged king rose erect and straight as a young man,—</p>\n<p>“Explain yourself, Olivier! And guard your head well, gossip; for<br>I swear to you by the cross of Saint-Lô that, if you lie to us at<br>this hour, the sword which severed the head of Monsieur de<br>Luxembourg is not so notched that it cannot yet sever yours!”</p>\n<p>The oath was formidable; Louis XI. had only sworn twice in the<br>course of his life by the cross of Saint-Lô.</p>\n<p>Olivier opened his mouth to reply.</p>\n<p>“Sire—”</p>\n<p>“On your knees!” interrupted the king violently. “Tristan, have<br>an eye to this man.”</p>\n<p>Olivier knelt down and said coldly,—</p>\n<p>“Sire, a sorceress was condemned to death by your court of<br>parliament. She took refuge in Notre-Dame. The people are trying<br>to take her from thence by main force. Monsieur the provost and<br>monsieur the chevalier of the watch, who have just come from the<br>riot, are here to give me the lie if this is not the truth. The<br>populace is besieging Notre-Dame.”</p>\n<p>“Yes, indeed!” said the king in a low voice, all pale and<br>trembling with wrath. “Notre-Dame! They lay siege to our Lady, my<br>good mistress in her cathedral!—Rise, Olivier. You are right. I<br>give you Simon Radin’s charge. You are right. ’Tis I whom they<br>are attacking. The witch is under the protection of this church,<br>the church is under my protection. And I thought that they were<br>acting against the bailiff! ’Tis against myself!”</p>\n<p>Then, rendered young by fury, he began to walk up and down with<br>long strides. He no longer laughed, he was terrible, he went and<br>came; the fox was changed into a hyæna. He seemed suffocated to<br>such a degree that he could not speak; his lips moved, and his<br>fleshless fists were clenched. All at once he raised his head,<br>his hollow eye appeared full of light, and his voice burst forth<br>like a clarion: “Down with them, Tristan! A heavy hand for these<br>rascals! Go, Tristan, my friend! slay! slay!”</p>\n<p>This eruption having passed, he returned to his seat, and said<br>with cold and concentrated wrath,—</p>\n<p>“Here, Tristan! There are here with us in the Bastille the fifty<br>lances of the Vicomte de Gif, which makes three hundred horse:<br>you will take them. There is also the company of our unattached<br>archers of Monsieur de Châteaupers: you will take it. You are<br>provost of the marshals; you have the men of your provostship:<br>you will take them. At the Hôtel Saint-Pol you will find forty<br>archers of monsieur the dauphin’s new guard: you will take them.<br>And, with all these, you will hasten to Notre-Dame. Ah!<br>messieurs, louts of Paris, do you fling yourselves thus against<br>the crown of France, the sanctity of Notre-Dame, and the peace of<br>this commonwealth! Exterminate, Tristan! exterminate! and let not<br>a single one escape, except it be for Montfaucon.”</p>\n<p>Tristan bowed. “’Tis well, sire.”</p>\n<p>He added, after a silence, “And what shall I do with the<br>sorceress?”</p>\n<p>This question caused the king to meditate.</p>\n<p>“Ah!” said he, “the sorceress! Monsieur d’Estouteville, what did<br>the people wish to do with her?”</p>\n<p>“Sire,” replied the provost of Paris, “I imagine that since the<br>populace has come to tear her from her asylum in Notre-Dame, ’tis<br>because that impunity wounds them, and they desire to hang her.”</p>\n<p>The king appeared to reflect deeply: then, addressing Tristan<br>l’Hermite, “Well! gossip, exterminate the people and hang the<br>sorceress.”</p>\n<p>“That’s it,” said Rym in a low tone to Coppenole, “punish the<br>people for willing a thing, and then do what they wish.”</p>\n<p>“Enough, sire,” replied Tristan. “If the sorceress is still in<br>Notre-Dame, must she be seized in spite of the sanctuary?”</p>\n<p>“<em>Pasque-Dieu!</em> the sanctuary!” said the king, scratching his<br>ear. “But the woman must be hung, nevertheless.”</p>\n<p>Here, as though seized with a sudden idea, he flung himself on<br>his knees before his chair, took off his hat, placed it on the<br>seat, and gazing devoutly at one of the leaden amulets which<br>loaded it down, “Oh!” said he, with clasped hands, “our Lady of<br>Paris, my gracious patroness, pardon me. I will only do it this<br>once. This criminal must be punished. I assure you, madame the<br>virgin, my good mistress, that she is a sorceress who is not<br>worthy of your amiable protection. You know, madame, that many<br>very pious princes have overstepped the privileges of the<br>churches for the glory of God and the necessities of the State.<br>Saint Hugues, bishop of England, permitted King Edward to hang a<br>witch in his church. Saint-Louis of France, my master,<br>transgressed, with the same object, the church of Monsieur<br>Saint-Paul; and Monsieur Alphonse, son of the king of Jerusalem,<br>the very church of the Holy Sepulchre. Pardon me, then, for this<br>once. Our Lady of Paris, I will never do so again, and I will<br>give you a fine statue of silver, like the one which I gave last<br>year to Our Lady of Écouys. So be it.”</p>\n<p>He made the sign of the cross, rose, donned his hat once more,<br>and said to Tristan,—</p>\n<p>“Be diligent, gossip. Take Monsieur Châteaupers with you. You<br>will cause the tocsin to be sounded. You will crush the populace.<br>You will seize the witch. ’Tis said. And I mean the business of<br>the execution to be done by you. You will render me an account of<br>it. Come, Olivier, I shall not go to bed this night. Shave me.”</p>\n<p>Tristan l’Hermite bowed and departed. Then the king, dismissing<br>Rym and Coppenole with a gesture,—</p>\n<p>“God guard you, messieurs, my good friends the Flemings. Go, take<br>a little repose. The night advances, and we are nearer the<br>morning than the evening.”</p>\n<p>Both retired and gained their apartments under the guidance of<br>the captain of the Bastille. Coppenole said to Guillaume Rym,—</p>\n<p>“Hum! I have had enough of that coughing king! I have seen<br>Charles of Burgundy drunk, and he was less malignant than Louis<br>XI. when ailing.”</p>\n<p>“Master Jacques,” replied Rym, “’tis because wine renders kings<br>less cruel than does barley water.”</p>\n<h1 class=\"chapter\" id=\"chapter-vi-little-sword-in-pocket\">Chapter VI. LITTLE SWORD IN POCKET.</h1>\n<p>On emerging from the Bastille, Gringoire descended the Rue<br>Saint-Antoine with the swiftness of a runaway horse. On arriving<br>at the Baudoyer gate, he walked straight to the stone cross which<br>rose in the middle of that place, as though he were able to<br>distinguish in the darkness the figure of a man clad and cloaked<br>in black, who was seated on the steps of the cross.</p>\n<p>“Is it you, master?” said Gringoire.</p>\n<p>The personage in black rose.</p>\n<p>“Death and passion! You make me boil, Gringoire. The man on the<br>tower of Saint-Gervais has just cried half-past one o’clock in<br>the morning.”</p>\n<p>“Oh,” retorted Gringoire, “’tis no fault of mine, but of the<br>watch and the king. I have just had a narrow escape. I always<br>just miss being hung. ’Tis my predestination.”</p>\n<p>“You lack everything,” said the other. “But come quickly. Have<br>you the password?”</p>\n<p>“Fancy, master, I have seen the king. I come from him. He wears<br>fustian breeches. ’Tis an adventure.”</p>\n<p>“Oh! distaff of words! what is your adventure to me! Have you the<br>password of the outcasts?”</p>\n<p>“I have it. Be at ease. ‘Little sword in pocket.’”</p>\n<p>“Good. Otherwise, we could not make our way as far as the church.<br>The outcasts bar the streets. Fortunately, it appears that they<br>have encountered resistance. We may still arrive in time.”</p>\n<p>“Yes, master, but how are we to get into Notre-Dame?”</p>\n<p>“I have the key to the tower.”</p>\n<p>“And how are we to get out again?”</p>\n<p>“Behind the cloister there is a little door which opens on the<br>Terrain and the water. I have taken the key to it, and I moored a<br>boat there this morning.”</p>\n<p>“I have had a beautiful escape from being hung!” Gringoire<br>repeated.</p>\n<p>“Eh, quick! come!” said the other.</p>\n<p>Both descended towards the city with long strides.</p>\n<h1 class=\"chapter\" id=\"chapter-vii-chateaupers-to-the-rescue\">Chapter VII. CHATEAUPERS TO THE RESCUE.</h1>\n<p>The reader will, perhaps, recall the critical situation in which<br>we left Quasimodo. The brave deaf man, assailed on all sides, had<br>lost, if not all courage, at least all hope of saving, not<br>himself (he was not thinking of himself), but the gypsy. He ran<br>distractedly along the gallery. Notre-Dame was on the point of<br>being taken by storm by the outcasts. All at once, a great<br>galloping of horses filled the neighboring streets, and, with a<br>long file of torches and a thick column of cavaliers, with free<br>reins and lances in rest, these furious sounds debouched on the<br>Place like a hurricane,—</p>\n<p>“France! France! cut down the louts! Châteaupers to the rescue!<br>Provostship! Provostship!”</p>\n<p>The frightened vagabonds wheeled round.</p>\n<p>Quasimodo who did not hear, saw the naked swords, the torches,<br>the irons of the pikes, all that cavalry, at the head of which he<br>recognized Captain Phœbus; he beheld the confusion of the<br>outcasts, the terror of some, the disturbance among the bravest<br>of them, and from this unexpected succor he recovered so much<br>strength, that he hurled from the church the first assailants who<br>were already climbing into the gallery.</p>\n<p>It was, in fact, the king’s troops who had arrived. The vagabonds<br>behaved bravely. They defended themselves like desperate men.<br>Caught on the flank, by the Rue Saint-Pierre-aux-Bœufs, and in<br>the rear through the Rue du Parvis, driven to bay against<br>Notre-Dame, which they still assailed and Quasimodo defended, at<br>the same time besiegers and besieged, they were in the singular<br>situation in which Comte Henri Harcourt, _Taurinum obsessor idem<br>et obsessus_, as his epitaph says, found himself later on, at the<br>famous siege of Turin, in 1640, between Prince Thomas of Savoy,<br>whom he was besieging, and the Marquis de Leganez, who was<br>blockading him.</p>\n<p>The battle was frightful. There was a dog’s tooth for wolf’s<br>flesh, as P. Mathieu says. The king’s cavaliers, in whose midst<br>Phœbus de Châteaupers bore himself valiantly, gave no quarter,<br>and the slash of the sword disposed of those who escaped the<br>thrust of the lance. The outcasts, badly armed foamed and bit<br>with rage. Men, women, children, hurled themselves on the<br>cruppers and the breasts of the horses, and hung there like cats,<br>with teeth, finger nails and toe nails. Others struck the<br>archers’ in the face with their torches. Others thrust iron hooks<br>into the necks of the cavaliers and dragged them down. They<br>slashed in pieces those who fell.</p>\n<p>One was noticed who had a large, glittering scythe, and who, for<br>a long time, mowed the legs of the horses. He was frightful. He<br>was singing a ditty, with a nasal intonation, he swung and drew<br>back his scythe incessantly. At every blow he traced around him a<br>great circle of severed limbs. He advanced thus into the very<br>thickest of the cavalry, with the tranquil slowness, the lolling<br>of the head and the regular breathing of a harvester attacking a<br>field of wheat. It was Clopin Trouillefou. A shot from an<br>arquebus laid him low.</p>\n<p>In the meantime, windows had been opened again. The neighbors<br>hearing the war cries of the king’s troops, had mingled in the<br>affray, and bullets rained upon the outcasts from every story.<br>The Parvis was filled with a thick smoke, which the musketry<br>streaked with flame. Through it one could confusedly distinguish<br>the front of Notre-Dame, and the decrepit Hôtel-Dieu with some<br>wan invalids gazing down from the heights of its roof all<br>checkered with dormer windows.</p>\n<p>At length the vagabonds gave way. Weariness, the lack of good<br>weapons, the fright of this surprise, the musketry from the<br>windows, the valiant attack of the king’s troops, all overwhelmed<br>them. They forced the line of assailants, and fled in every<br>direction, leaving the Parvis encumbered with dead.</p>\n<p>When Quasimodo, who had not ceased to fight for a moment, beheld<br>this rout, he fell on his knees and raised his hands to heaven;<br>then, intoxicated with joy, he ran, he ascended with the<br>swiftness of a bird to that cell, the approaches to which he had<br>so intrepidly defended. He had but one thought now; it was to<br>kneel before her whom he had just saved for the second time.</p>\n<p>When he entered the cell, he found it empty.</p>\n<p>BOOK ELEVENTH.</p>\n<h1 class=\"chapter\" id=\"chapter-i-the-little-shoe\">Chapter I. THE LITTLE SHOE.</h1>\n<p>La Esmeralda was sleeping at the moment when the outcasts<br>assailed the church.</p>\n<p>Soon the ever-increasing uproar around the edifice, and the<br>uneasy bleating of her goat which had been awakened, had roused<br>her from her slumbers. She had sat up, she had listened, she had<br>looked; then, terrified by the light and noise, she had rushed<br>from her cell to see. The aspect of the Place, the vision which<br>was moving in it, the disorder of that nocturnal assault, that<br>hideous crowd, leaping like a cloud of frogs, half seen in the<br>gloom, the croaking of that hoarse multitude, those few red<br>torches running and crossing each other in the darkness like the<br>meteors which streak the misty surfaces of marshes, this whole<br>scene produced upon her the effect of a mysterious battle between<br>the phantoms of the witches’ sabbath and the stone monsters of<br>the church. Imbued from her very infancy with the superstitions<br>of the Bohemian tribe, her first thought was that she had caught<br>the strange beings peculiar to the night, in their deeds of<br>witchcraft. Then she ran in terror to cower in her cell, asking<br>of her pallet some less terrible nightmare.</p>\n<p>But little by little the first vapors of terror had been<br>dissipated; from the constantly increasing noise, and from many<br>other signs of reality, she felt herself besieged not by<br>spectres, but by human beings. Then her fear, though it did not<br>increase, changed its character. She had dreamed of the<br>possibility of a popular mutiny to tear her from her asylum. The<br>idea of once more recovering life, hope, Phœbus, who was ever<br>present in her future, the extreme helplessness of her condition,<br>flight cut off, no support, her abandonment, her isolation,—these<br>thoughts and a thousand others overwhelmed her. She fell upon her<br>knees, with her head on her bed, her hands clasped over her head,<br>full of anxiety and tremors, and, although a gypsy, an idolater,<br>and a pagan, she began to entreat with sobs, mercy from the good<br>Christian God, and to pray to our Lady, her hostess. For even if<br>one believes in nothing, there are moments in life when one is<br>always of the religion of the temple which is nearest at hand.</p>\n<p>She remained thus prostrate for a very long time, trembling in<br>truth, more than praying, chilled by the ever-closer breath of<br>that furious multitude, understanding nothing of this outburst,<br>ignorant of what was being plotted, what was being done, what<br>they wanted, but foreseeing a terrible issue.</p>\n<p>In the midst of this anguish, she heard some one walking near<br>her. She turned round. Two men, one of whom carried a lantern,<br>had just entered her cell. She uttered a feeble cry.</p>\n<p>“Fear nothing,” said a voice which was not unknown to her, “it is<br>I.”</p>\n<p>“Who are you?” she asked.</p>\n<p>“Pierre Gringoire.”</p>\n<p>This name reassured her. She raised her eyes once more, and<br>recognized the poet in very fact. But there stood beside him a<br>black figure veiled from head to foot, which struck her by its<br>silence.</p>\n<p>“Oh!” continued Gringoire in a tone of reproach, “Djali<br>recognized me before you!”</p>\n<p>The little goat had not, in fact, waited for Gringoire to<br>announce his name. No sooner had he entered than it rubbed itself<br>gently against his knees, covering the poet with caresses and<br>with white hairs, for it was shedding its hair. Gringoire<br>returned the caresses.</p>\n<p>“Who is this with you?” said the gypsy, in a low voice.</p>\n<p>“Be at ease,” replied Gringoire. “’Tis one of my friends.” Then<br>the philosopher setting his lantern on the ground, crouched upon<br>the stones, and exclaimed enthusiastically, as he pressed Djali<br>in his arms,—</p>\n<p>“Oh! ’tis a graceful beast, more considerable no doubt, for it’s<br>neatness than for its size, but ingenious, subtle, and lettered<br>as a grammarian! Let us see, my Djali, hast thou forgotten any of<br>thy pretty tricks? How does Master Jacques Charmolue?...”</p>\n<p>The man in black did not allow him to finish. He approached<br>Gringoire and shook him roughly by the shoulder.</p>\n<p>Gringoire rose.</p>\n<p>“’Tis true,” said he: “I forgot that we are in haste. But that is<br>no reason master, for getting furious with people in this manner.<br>My dear and lovely child, your life is in danger, and Djali’s<br>also. They want to hang you again. We are your friends, and we<br>have come to save you. Follow us.”</p>\n<p>“Is it true?” she exclaimed in dismay.</p>\n<p>“Yes, perfectly true. Come quickly!”</p>\n<p>“I am willing,” she stammered. “But why does not your friend<br>speak?”</p>\n<p>“Ah!” said Gringoire, “’tis because his father and mother were<br>fantastic people who made him of a taciturn temperament.”</p>\n<p>She was obliged to content herself with this explanation.<br>Gringoire took her by the hand; his companion picked up the<br>lantern and walked on in front. Fear stunned the young girl. She<br>allowed herself to be led away. The goat followed them, frisking,<br>so joyous at seeing Gringoire again that it made him stumble<br>every moment by thrusting its horns between his legs.</p>\n<p>“Such is life,” said the philosopher, every time that he came<br>near falling down; “’tis often our best friends who cause us to<br>be overthrown.”</p>\n<p>They rapidly descended the staircase of the towers, crossed the<br>church, full of shadows and solitude, and all reverberating with<br>uproar, which formed a frightful contrast, and emerged into the<br>courtyard of the cloister by the red door. The cloister was<br>deserted; the canons had fled to the bishop’s palace in order to<br>pray together; the courtyard was empty, a few frightened lackeys<br>were crouching in dark corners. They directed their steps towards<br>the door which opened from this court upon the Terrain. The man<br>in black opened it with a key which he had about him. Our readers<br>are aware that the Terrain was a tongue of land enclosed by walls<br>on the side of the City and belonging to the chapter of<br>Notre-Dame, which terminated the island on the east, behind the<br>church. They found this enclosure perfectly deserted. There was<br>here less tumult in the air. The roar of the outcasts’ assault<br>reached them more confusedly and less clamorously. The fresh<br>breeze which follows the current of a stream, rustled the leaves<br>of the only tree planted on the point of the Terrain, with a<br>noise that was already perceptible. But they were still very<br>close to danger. The nearest edifices to them were the bishop’s<br>palace and the church. It was plainly evident that there was<br>great internal commotion in the bishop’s palace. Its shadowy mass<br>was all furrowed with lights which flitted from window to window;<br>as, when one has just burned paper, there remains a sombre<br>edifice of ashes in which bright sparks run a thousand eccentric<br>courses. Beside them, the enormous towers of Notre-Dame, thus<br>viewed from behind, with the long nave above which they rise cut<br>out in black against the red and vast light which filled the<br>Parvis, resembled two gigantic andirons of some cyclopean<br>fire-grate.</p>\n<p>What was to be seen of Paris on all sides wavered before the eye<br>in a gloom mingled with light. Rembrandt has such backgrounds to<br>his pictures.</p>\n<p>The man with the lantern walked straight to the point of the<br>Terrain. There, at the very brink of the water, stood the<br>wormeaten remains of a fence of posts latticed with laths,<br>whereon a low vine spread out a few thin branches like the<br>fingers of an outspread hand. Behind, in the shadow cast by this<br>trellis, a little boat lay concealed. The man made a sign to<br>Gringoire and his companion to enter. The goat followed them. The<br>man was the last to step in. Then he cut the boat’s moorings,<br>pushed it from the shore with a long boat-hook, and, seizing two<br>oars, seated himself in the bow, rowing with all his might<br>towards midstream. The Seine is very rapid at this point, and he<br>had a good deal of trouble in leaving the point of the island.</p>\n<p>Gringoire’s first care on entering the boat was to place the goat<br>on his knees. He took a position in the stern; and the young<br>girl, whom the stranger inspired with an indefinable uneasiness,<br>seated herself close to the poet.</p>\n<p>When our philosopher felt the boat sway, he clapped his hands and<br>kissed Djali between the horns.</p>\n<p>“Oh!” said he, “now we are safe, all four of us.”</p>\n<p>He added with the air of a profound thinker, “One is indebted<br>sometimes to fortune, sometimes to ruse, for the happy issue of<br>great enterprises.”</p>\n<p>The boat made its way slowly towards the right shore. The young<br>girl watched the unknown man with secret terror. He had carefully<br>turned off the light of his dark lantern. A glimpse could be<br>caught of him in the obscurity, in the bow of the boat, like a<br>spectre. His cowl, which was still lowered, formed a sort of<br>mask; and every time that he spread his arms, upon which hung<br>large black sleeves, as he rowed, one would have said they were<br>two huge bat’s wings. Moreover, he had not yet uttered a word or<br>breathed a syllable. No other noise was heard in the boat than<br>the splashing of the oars, mingled with the rippling of the water<br>along her sides.</p>\n<p>“On my soul!” exclaimed Gringoire suddenly, “we are as cheerful<br>and joyous as young owls! We preserve the silence of Pythagoreans<br>or fishes! <em>Pasque-Dieu!</em> my friends, I should greatly like to<br>have some one speak to me. The human voice is music to the human<br>ear. ’Tis not I who say that, but Didymus of Alexandria, and they<br>are illustrious words. Assuredly, Didymus of Alexandria is no<br>mediocre philosopher.—One word, my lovely child! say but one word<br>to me, I entreat you. By the way, you had a droll and peculiar<br>little pout; do you still make it? Do you know, my dear, that<br>parliament hath full jurisdiction over all places of asylum, and<br>that you were running a great risk in your little chamber at<br>Notre-Dame? Alas! the little bird trochylus maketh its nest in<br>the jaws of the crocodile.—Master, here is the moon re-appearing.<br>If only they do not perceive us. We are doing a laudable thing in<br>saving mademoiselle, and yet we should be hung by order of the<br>king if we were caught. Alas! human actions are taken by two<br>handles. That is branded with disgrace in one which is crowned in<br>another. He admires Cicero who blames Catiline. Is it not so,<br>master? What say you to this philosophy? I possess philosophy by<br>instinct, by nature, <em>ut apes geometriam</em>.—Come! no one answers<br>me. What unpleasant moods you two are in! I must do all the<br>talking alone. That is what we call a monologue in<br>tragedy.—<em>Pasque-Dieu!</em> I must inform you that I have just seen<br>the king, Louis XI., and that I have caught this oath from<br>him,—<em>Pasque-Dieu!</em> They are still making a hearty howl in the<br>city.—’Tis a villanous, malicious old king. He is all swathed in<br>furs. He still owes me the money for my epithalamium, and he came<br>within a nick of hanging me this evening, which would have been<br>very inconvenient to me.—He is niggardly towards men of merit. He<br>ought to read the four books of Salvien of Cologne, _Adversus<br>Avaritiam_. In truth! ’Tis a paltry king in his ways with men of<br>letters, and one who commits very barbarous cruelties. He is a<br>sponge, to soak money raised from the people. His saving is like<br>the spleen which swelleth with the leanness of all the other<br>members. Hence complaints against the hardness of the times<br>become murmurs against the prince. Under this gentle and pious<br>sire, the gallows crack with the hung, the blocks rot with blood,<br>the prisons burst like over full bellies. This king hath one hand<br>which grasps, and one which hangs. He is the procurator of Dame<br>Tax and Monsieur Gibbet. The great are despoiled of their<br>dignities, and the little incessantly overwhelmed with fresh<br>oppressions. He is an exorbitant prince. I love not this monarch.<br>And you, master?”</p>\n<p>The man in black let the garrulous poet chatter on. He continued<br>to struggle against the violent and narrow current, which<br>separates the prow of the City and the stem of the island of<br>Notre-Dame, which we call to-day the Isle St. Louis.</p>\n<p>“By the way, master!” continued Gringoire suddenly. “At the<br>moment when we arrived on the Parvis, through the enraged<br>outcasts, did your reverence observe that poor little devil whose<br>skull your deaf man was just cracking on the railing of the<br>gallery of the kings? I am near sighted and I could not recognize<br>him. Do you know who he could be?”</p>\n<p>The stranger answered not a word. But he suddenly ceased rowing,<br>his arms fell as though broken, his head sank on his breast, and<br>la Esmeralda heard him sigh convulsively. She shuddered. She had<br>heard such sighs before.</p>\n<p>The boat, abandoned to itself, floated for several minutes with<br>the stream. But the man in black finally recovered himself,<br>seized the oars once more and began to row against the current.<br>He doubled the point of the Isle of Notre Dame, and made for the<br>landing-place of the Port au Foin.</p>\n<p>“Ah!” said Gringoire, “yonder is the Barbeau mansion.—Stay,<br>master, look: that group of black roofs which make such singular<br>angles yonder, above that heap of black, fibrous grimy, dirty<br>clouds, where the moon is completely crushed and spread out like<br>the yolk of an egg whose shell is broken.—’Tis a fine mansion.<br>There is a chapel crowned with a small vault full of very well<br>carved enrichments. Above, you can see the bell tower, very<br>delicately pierced. There is also a pleasant garden, which<br>consists of a pond, an aviary, an echo, a mall, a labyrinth, a<br>house for wild beasts, and a quantity of leafy alleys very<br>agreeable to Venus. There is also a rascal of a tree which is<br>called ‘the lewd,’ because it favored the pleasures of a famous<br>princess and a constable of France, who was a gallant and a<br>wit.—Alas! we poor philosophers are to a constable as a plot of<br>cabbages or a radish bed to the garden of the Louvre. What<br>matters it, after all? human life, for the great as well as for<br>us, is a mixture of good and evil. Pain is always by the side of<br>joy, the spondee by the dactyl.—Master, I must relate to you the<br>history of the Barbeau mansion. It ends in tragic fashion. It was<br>in 1319, in the reign of Philippe V., the longest reign of the<br>kings of France. The moral of the story is that the temptations<br>of the flesh are pernicious and malignant. Let us not rest our<br>glance too long on our neighbor’s wife, however gratified our<br>senses may be by her beauty. Fornication is a very libertine<br>thought. Adultery is a prying into the pleasures of others—Ohé!<br>the noise yonder is redoubling!”</p>\n<p>The tumult around Notre-Dame was, in fact, increasing. They<br>listened. Cries of victory were heard with tolerable<br>distinctness. All at once, a hundred torches, the light of which<br>glittered upon the helmets of men at arms, spread over the church<br>at all heights, on the towers, on the galleries, on the flying<br>buttresses. These torches seemed to be in search of something;<br>and soon distant clamors reached the fugitives distinctly:—“The<br>gypsy! the sorceress! death to the gypsy!”</p>\n<p>The unhappy girl dropped her head upon her hands, and the unknown<br>began to row furiously towards the shore. Meanwhile our<br>philosopher reflected. He clasped the goat in his arms, and<br>gently drew away from the gypsy, who pressed closer and closer to<br>him, as though to the only asylum which remained to her.</p>\n<p>It is certain that Gringoire was enduring cruel perplexity. He<br>was thinking that the goat also, “according to existing law,”<br>would be hung if recaptured; which would be a great pity, poor<br>Djali! that he had thus two condemned creatures attached to him;<br>that his companion asked no better than to take charge of the<br>gypsy. A violent combat began between his thoughts, in which,<br>like the Jupiter of the Iliad, he weighed in turn the gypsy and<br>the goat; and he looked at them alternately with eyes moist with<br>tears, saying between his teeth:</p>\n<p>“But I cannot save you both!”</p>\n<p>A shock informed them that the boat had reached the land at last.<br>The uproar still filled the city. The unknown rose, approached<br>the gypsy, and endeavored to take her arm to assist her to<br>alight. She repulsed him and clung to the sleeve of Gringoire,<br>who, in his turn, absorbed in the goat, almost repulsed her. Then<br>she sprang alone from the boat. She was so troubled that she did<br>not know what she did or whither she was going. Thus she remained<br>for a moment, stunned, watching the water flow past; when she<br>gradually returned to her senses, she found herself alone on the<br>wharf with the unknown. It appears that Gringoire had taken<br>advantage of the moment of debarcation to slip away with the goat<br>into the block of houses of the Rue Grenier-sur-l’Eau.</p>\n<p>The poor gypsy shivered when she beheld herself alone with this<br>man. She tried to speak, to cry out, to call Gringoire; her<br>tongue was dumb in her mouth, and no sound left her lips. All at<br>once she felt the stranger’s hand on hers. It was a strong, cold<br>hand. Her teeth chattered, she turned paler than the ray of<br>moonlight which illuminated her. The man spoke not a word. He<br>began to ascend towards the Place de Grève, holding her by the<br>hand.</p>\n<p>At that moment, she had a vague feeling that destiny is an<br>irresistible force. She had no more resistance left in her, she<br>allowed herself to be dragged along, running while he walked. At<br>this spot the quay ascended. But it seemed to her as though she<br>were descending a slope.</p>\n<p>She gazed about her on all sides. Not a single passer-by. The<br>quay was absolutely deserted. She heard no sound, she felt no<br>people moving save in the tumultuous and glowing city, from which<br>she was separated only by an arm of the Seine, and whence her<br>name reached her, mingled with cries of “Death!” The rest of<br>Paris was spread around her in great blocks of shadows.</p>\n<p>Meanwhile, the stranger continued to drag her along with the same<br>silence and the same rapidity. She had no recollection of any of<br>the places where she was walking. As she passed before a lighted<br>window, she made an effort, drew up suddenly, and cried out,<br>“Help!”</p>\n<p>The <em>bourgeois</em> who was standing at the window opened it,<br>appeared there in his shirt with his lamp, stared at the quay<br>with a stupid air, uttered some words which she did not<br>understand, and closed his shutter again. It was her last gleam<br>of hope extinguished.</p>\n<p>The man in black did not utter a syllable; he held her firmly,<br>and set out again at a quicker pace. She no longer resisted, but<br>followed him, completely broken.</p>\n<p>From time to time she called together a little strength, and<br>said, in a voice broken by the unevenness of the pavement and the<br>breathlessness of their flight, “Who are you? Who are you?” He<br>made no reply.</p>\n<p>They arrived thus, still keeping along the quay, at a tolerably<br>spacious square. It was the Grève. In the middle, a sort of<br>black, erect cross was visible; it was the gallows. She<br>recognized all this, and saw where she was.</p>\n<p>The man halted, turned towards her and raised his cowl.</p>\n<p>“Oh!” she stammered, almost petrified, “I knew well that it was<br>he again!”</p>\n<p>It was the priest. He looked like the ghost of himself; that is<br>an effect of the moonlight, it seems as though one beheld only<br>the spectres of things in that light.</p>\n<p>“Listen!” he said to her; and she shuddered at the sound of that<br>fatal voice which she had not heard for a long time. He continued<br>speaking with those brief and panting jerks, which betoken deep<br>internal convulsions. “Listen! we are here. I am going to speak<br>to you. This is the Grève. This is an extreme point. Destiny<br>gives us to one another. I am going to decide as to your life;<br>you will decide as to my soul. Here is a place, here is a night<br>beyond which one sees nothing. Then listen to me. I am going to<br>tell you.... In the first place, speak not to me of your Phœbus.<br>(As he spoke thus he paced to and fro, like a man who cannot<br>remain in one place, and dragged her after him.) Do not speak to<br>me of him. Do you see? If you utter that name, I know not what I<br>shall do, but it will be terrible.”</p>\n<p>Then, like a body which recovers its centre of gravity, he became<br>motionless once more, but his words betrayed no less agitation.<br>His voice grew lower and lower.</p>\n<p>“Do not turn your head aside thus. Listen to me. It is a serious<br>matter. In the first place, here is what has happened.—All this<br>will not be laughed at. I swear it to you.—What was I saying?<br>Remind me! Oh!—There is a decree of Parliament which gives you<br>back to the scaffold. I have just rescued you from their hands.<br>But they are pursuing you. Look!”</p>\n<p>He extended his arm toward the City. The search seemed, in fact,<br>to be still in progress there. The uproar drew nearer; the tower<br>of the lieutenant’s house, situated opposite the Grève, was full<br>of clamors and light, and soldiers could be seen running on the<br>opposite quay with torches and these cries, “The gypsy! Where is<br>the gypsy! Death! Death!”</p>\n<p>“You see that they are in pursuit of you, and that I am not lying<br>to you. I love you.—Do not open your mouth; refrain from speaking<br>to me rather, if it be only to tell me that you hate me. I have<br>made up my mind not to hear that again.—I have just saved<br>you.—Let me finish first. I can save you wholly. I have prepared<br>everything. It is yours at will. If you wish, I can do it.”</p>\n<p>He broke off violently. “No, that is not what I should say!”</p>\n<p>As he went with hurried step and made her hurry also, for he did<br>not release her, he walked straight to the gallows, and pointed<br>to it with his finger,—</p>\n<p>“Choose between us two,” he said, coldly.</p>\n<p>She tore herself from his hands and fell at the foot of the<br>gibbet, embracing that funereal support, then she half turned her<br>beautiful head, and looked at the priest over her shoulder. One<br>would have said that she was a Holy Virgin at the foot of the<br>cross. The priest remained motionless, his finger still raised<br>toward the gibbet, preserving his attitude like a statue. At<br>length the gypsy said to him,—</p>\n<p>“It causes me less horror than you do.”</p>\n<p>Then he allowed his arm to sink slowly, and gazed at the pavement<br>in profound dejection.</p>\n<p>“If these stones could speak,” he murmured, “yes, they would say<br>that a very unhappy man stands here.”</p>\n<p>He went on. The young girl, kneeling before the gallows,<br>enveloped in her long flowing hair, let him speak on without<br>interruption. He now had a gentle and plaintive accent which<br>contrasted sadly with the haughty harshness of his features.</p>\n<p>“I love you. Oh! how true that is! So nothing comes of that fire<br>which burns my heart! Alas! young girl, night and day—yes, night<br>and day I tell you,—it is torture. Oh! I suffer too much, my poor<br>child. ’Tis a thing deserving of compassion, I assure you. You<br>see that I speak gently to you. I really wish that you should no<br>longer cherish this horror of me.—After all, if a man loves a<br>woman, ’tis not his fault!—Oh, my God!—What! So you will never<br>pardon me? You will always hate me? All is over then. It is that<br>which renders me evil, do you see? and horrible to myself.—You<br>will not even look at me! You are thinking of something else,<br>perchance, while I stand here and talk to you, shuddering on the<br>brink of eternity for both of us! Above all things, do not speak<br>to me of the officer!—I would cast myself at your knees, I would<br>kiss not your feet, but the earth which is under your feet; I<br>would sob like a child, I would tear from my breast not words,<br>but my very heart and vitals, to tell you that I love you;—all<br>would be useless, all!—And yet you have nothing in your heart but<br>what is tender and merciful. You are radiant with the most<br>beautiful mildness; you are wholly sweet, good, pitiful, and<br>charming. Alas! You cherish no ill will for any one but me alone!<br>Oh! what a fatality!”</p>\n<p>He hid his face in his hands. The young girl heard him weeping.<br>It was for the first time. Thus erect and shaken by sobs, he was<br>more miserable and more suppliant than when on his knees. He wept<br>thus for a considerable time.</p>\n<p>“Come!” he said, these first tears passed, “I have no more words.<br>I had, however, thought well as to what you would say. Now I<br>tremble and shiver and break down at the decisive moment, I feel<br>conscious of something supreme enveloping us, and I stammer. Oh!<br>I shall fall upon the pavement if you do not take pity on me,<br>pity on yourself. Do not condemn us both. If you only knew how<br>much I love you! What a heart is mine! Oh! what desertion of all<br>virtue! What desperate abandonment of myself! A doctor, I mock at<br>science; a gentleman, I tarnish my own name; a priest, I make of<br>the missal a pillow of sensuality, I spit in the face of my God!<br>all this for thee, enchantress! to be more worthy of thy hell!<br>And you will not have the apostate! Oh! let me tell you all! more<br>still, something more horrible, oh! Yet more horrible!...”</p>\n<p>As he uttered these last words, his air became utterly<br>distracted. He was silent for a moment, and resumed, as though<br>speaking to himself, and in a strong voice,—</p>\n<p>“Cain, what hast thou done with thy brother?”</p>\n<p>There was another silence, and he went on—</p>\n<p>“What have I done with him, Lord? I received him, I reared him, I<br>nourished him, I loved him, I idolized him, and I have slain him!<br>Yes, Lord, they have just dashed his head before my eyes on the<br>stone of thine house, and it is because of me, because of this<br>woman, because of her.”</p>\n<p>His eye was wild. His voice grew ever weaker; he repeated many<br>times, yet, mechanically, at tolerably long intervals, like a<br>bell prolonging its last vibration: “Because of her.—Because of<br>her.”</p>\n<p>Then his tongue no longer articulated any perceptible sound; but<br>his lips still moved. All at once he sank together, like<br>something crumbling, and lay motionless on the earth, with his<br>head on his knees.</p>\n<p>A touch from the young girl, as she drew her foot from under him,<br>brought him to himself. He passed his hand slowly over his hollow<br>cheeks, and gazed for several moments at his fingers, which were<br>wet, “What!” he murmured, “I have wept!”</p>\n<p>And turning suddenly to the gypsy with unspeakable anguish,—</p>\n<p>“Alas! you have looked coldly on at my tears! Child, do you know<br>that those tears are of lava? Is it indeed true? Nothing touches<br>when it comes from the man whom one does not love. If you were to<br>see me die, you would laugh. Oh! I do not wish to see you die!<br>One word! A single word of pardon! Say not that you love me, say<br>only that you will do it; that will suffice; I will save you. If<br>not—oh! the hour is passing. I entreat you by all that is sacred,<br>do not wait until I shall have turned to stone again, like that<br>gibbet which also claims you! Reflect that I hold the destinies<br>of both of us in my hand, that I am mad,—it is terrible,—that I<br>may let all go to destruction, and that there is beneath us a<br>bottomless abyss, unhappy girl, whither my fall will follow yours<br>to all eternity! One word of kindness! Say one word! only one<br>word!”</p>\n<p>She opened her mouth to answer him. He flung himself on his knees<br>to receive with adoration the word, possibly a tender one, which<br>was on the point of issuing from her lips. She said to him, “You<br>are an assassin!”</p>\n<p>The priest clasped her in his arms with fury, and began to laugh<br>with an abominable laugh.</p>\n<p>“Well, yes, an assassin!” he said, “and I will have you. You will<br>not have me for your slave, you shall have me for your master. I<br>will have you! I have a den, whither I will drag you. You will<br>follow me, you will be obliged to follow me, or I will deliver<br>you up! You must die, my beauty, or be mine! belong to the<br>priest! belong to the apostate! belong to the assassin! this very<br>night, do you hear? Come! joy; kiss me, mad girl! The tomb or my<br>bed!”</p>\n<p>His eyes sparkled with impurity and rage. His lewd lips reddened<br>the young girl’s neck. She struggled in his arms. He covered her<br>with furious kisses.</p>\n<p>“Do not bite me, monster!” she cried. “Oh! the foul, odious monk!<br>leave me! I will tear out thy ugly gray hair and fling it in thy<br>face by the handful!”</p>\n<p>He reddened, turned pale, then released her and gazed at her with<br>a gloomy air. She thought herself victorious, and continued,—</p>\n<p>“I tell you that I belong to my Phœbus, that ’tis Phœbus whom I<br>love, that ’tis Phœbus who is handsome! you are old, priest! you<br>are ugly! Begone!”</p>\n<p>He gave vent to a horrible cry, like the wretch to whom a hot<br>iron is applied. “Die, then!” he said, gnashing his teeth. She<br>saw his terrible look and tried to fly. He caught her once more,<br>he shook her, he flung her on the ground, and walked with rapid<br>strides towards the corner of the Tour-Roland, dragging her after<br>him along the pavement by her beautiful hands.</p>\n<p>On arriving there, he turned to her,—</p>\n<p>“For the last time, will you be mine?”</p>\n<p>She replied with emphasis,—</p>\n<p>“No!”</p>\n<p>Then he cried in a loud voice,—</p>\n<p>“Gudule! Gudule! here is the gypsy! take your vengeance!”</p>\n<p>The young girl felt herself seized suddenly by the elbow. She<br>looked. A fleshless arm was stretched from an opening in the<br>wall, and held her like a hand of iron.</p>\n<p>“Hold her well,” said the priest; “’tis the gypsy escaped.<br>Release her not. I will go in search of the sergeants. You shall<br>see her hanged.”</p>\n<p>A guttural laugh replied from the interior of the wall to these<br>bloody words—“Hah! hah! hah!”—The gypsy watched the priest retire<br>in the direction of the Pont Notre-Dame. A cavalcade was heard in<br>that direction.</p>\n<p>The young girl had recognized the spiteful recluse. Panting with<br>terror, she tried to disengage herself. She writhed, she made<br>many starts of agony and despair, but the other held her with<br>incredible strength. The lean and bony fingers which bruised her,<br>clenched on her flesh and met around it. One would have said that<br>this hand was riveted to her arm. It was more than a chain, more<br>than a fetter, more than a ring of iron, it was a living pair of<br>pincers endowed with intelligence, which emerged from the wall.</p>\n<p>She fell back against the wall exhausted, and then the fear of<br>death took possession of her. She thought of the beauty of life,<br>of youth, of the view of heaven, the aspects of nature, of her<br>love for Phœbus, of all that was vanishing and all that was<br>approaching, of the priest who was denouncing her, of the<br>headsman who was to come, of the gallows which was there. Then<br>she felt terror mount to the very roots of her hair and she heard<br>the mocking laugh of the recluse, saying to her in a very low<br>tone: “Hah! hah! hah! you are going to be hanged!”</p>\n<p>She turned a dying look towards the window, and she beheld the<br>fierce face of the sacked nun through the bars.</p>\n<p>“What have I done to you?” she said, almost lifeless.</p>\n<p>The recluse did not reply, but began to mumble with a singsong<br>irritated, mocking intonation: “Daughter of Egypt! daughter of<br>Egypt! daughter of Egypt!”</p>\n<p>The unhappy Esmeralda dropped her head beneath her flowing hair,<br>comprehending that it was no human being she had to deal with.</p>\n<p>All at once the recluse exclaimed, as though the gypsy’s question<br>had taken all this time to reach her brain,—“‘What have you done<br>to me?’ you say! Ah! what have you done to me, gypsy! Well!<br>listen.—I had a child! you see! I had a child! a child, I tell<br>you!—a pretty little girl!—my Agnès!” she went on wildly, kissing<br>something in the dark.—“Well! do you see, daughter of Egypt? they<br>took my child from me; they stole my child; they ate my child.<br>That is what you have done to me.”</p>\n<p>The young girl replied like a lamb,—</p>\n<p>“Alas! perchance I was not born then!”</p>\n<p>“Oh! yes!” returned the recluse, “you must have been born. You<br>were among them. She would be the same age as you! so!—I have<br>been here fifteen years; fifteen years have I suffered; fifteen<br>years have I prayed; fifteen years have I beat my head against<br>these four walls—I tell you that ’twas the gypsies who stole her<br>from me, do you hear that? and who ate her with their teeth.—Have<br>you a heart? imagine a child playing, a child sucking; a child<br>sleeping. It is so innocent a thing!—Well! that, that is what<br>they took from me, what they killed. The good God knows it well!<br>To-day, it is my turn; I am going to eat the gypsy.—Oh! I would<br>bite you well, if the bars did not prevent me! My head is too<br>large!—Poor little one! while she was asleep! And if they woke<br>her up when they took her, in vain she might cry; I was not<br>there!—Ah! gypsy mothers, you devoured my child! come see your<br>own.”</p>\n<p>Then she began to laugh or to gnash her teeth, for the two things<br>resembled each other in that furious face. The day was beginning<br>to dawn. An ashy gleam dimly lighted this scene, and the gallows<br>grew more and more distinct in the square. On the other side, in<br>the direction of the bridge of Notre-Dame, the poor condemned<br>girl fancied that she heard the sound of cavalry approaching.</p>\n<p>“Madam,” she cried, clasping her hands and falling on her knees,<br>dishevelled, distracted, mad with fright; “madam! have pity! They<br>are coming. I have done nothing to you. Would you wish to see me<br>die in this horrible fashion before your very eyes? You are<br>pitiful, I am sure. It is too frightful. Let me make my escape.<br>Release me! Mercy. I do not wish to die like that!”</p>\n<p>“Give me back my child!” said the recluse.</p>\n<p>“Mercy! Mercy!”</p>\n<p>“Give me back my child!”</p>\n<p>“Release me, in the name of heaven!”</p>\n<p>“Give me back my child!”</p>\n<p>Again the young girl fell; exhausted, broken, and having already<br>the glassy eye of a person in the grave.</p>\n<p>“Alas!” she faltered, “you seek your child, I seek my parents.”</p>\n<p>“Give me back my little Agnès!” pursued Gudule. “You do not know<br>where she is? Then die!—I will tell you. I was a woman of the<br>town, I had a child, they took my child. It was the gypsies. You<br>see plainly that you must die. When your mother, the gypsy, comes<br>to reclaim you, I shall say to her: ‘Mother, look at that<br>gibbet!—Or, give me back my child. Do you know where she is, my<br>little daughter? Stay! I will show you. Here is her shoe, all<br>that is left me of her. Do you know where its mate is? If you<br>know, tell me, and if it is only at the other end of the world, I<br>will crawl to it on my knees.”</p>\n<p>As she spoke thus, with her other arm extended through the<br>window, she showed the gypsy the little embroidered shoe. It was<br>already light enough to distinguish its shape and its colors.</p>\n<p>“Let me see that shoe,” said the gypsy, quivering. “God! God!”</p>\n<p>And at the same time, with her hand which was at liberty, she<br>quickly opened the little bag ornamented with green glass, which<br>she wore about her neck.</p>\n<p>“Go on, go on!” grumbled Gudule, “search your demon’s amulet!”</p>\n<p>All at once, she stopped short, trembled in every limb, and cried<br>in a voice which proceeded from the very depths of her being: “My<br>daughter!”</p>\n<p>The gypsy had just drawn from the bag a little shoe absolutely<br>similar to the other. To this little shoe was attached a<br>parchment on which was inscribed this charm,—</p>\n<p>Quand le pareil retrouveras<br>Ta mère te tendras les bras.[68]</p>\n<p>Quicker than a flash of lightning, the recluse had laid the two<br>shoes together, had read the parchment and had put close to the<br>bars of the window her face beaming with celestial joy as she<br>cried,—</p>\n<p>“My daughter! my daughter!”</p>\n<p>“My mother!” said the gypsy.</p>\n<p>Here we are unequal to the task of depicting the scene. The wall<br>and the iron bars were between them. “Oh! the wall!” cried the<br>recluse. “Oh! to see her and not to embrace her! Your hand! your<br>hand!”</p>\n<p>The young girl passed her arm through the opening; the recluse<br>threw herself on that hand, pressed her lips to it and there<br>remained, buried in that kiss, giving no other sign of life than<br>a sob which heaved her breast from time to time. In the<br>meanwhile, she wept in torrents, in silence, in the dark, like a<br>rain at night. The poor mother poured out in floods upon that<br>adored hand the dark and deep well of tears, which lay within<br>her, and into which her grief had filtered, drop by drop, for<br>fifteen years.</p>\n<p>All at once she rose, flung aside her long gray hair from her<br>brow, and without uttering a word, began to shake the bars of her<br>cage cell, with both hands, more furiously than a lioness. The<br>bars held firm. Then she went to seek in the corner of her cell a<br>huge paving stone, which served her as a pillow, and launched it<br>against them with such violence that one of the bars broke,<br>emitting thousands of sparks. A second blow completely shattered<br>the old iron cross which barricaded the window. Then with her two<br>hands, she finished breaking and removing the rusted stumps of<br>the bars. There are moments when woman’s hands possess superhuman<br>strength.</p>\n<p>A passage broken, less than a minute was required for her to<br>seize her daughter by the middle of her body, and draw her into<br>her cell. “Come let me draw you out of the abyss,” she murmured.</p>\n<p>When her daughter was inside the cell, she laid her gently on the<br>ground, then raised her up again, and bearing her in her arms as<br>though she were still only her little Agnès, she walked to and<br>fro in her little room, intoxicated, frantic, joyous, crying out,<br>singing, kissing her daughter, talking to her, bursting into<br>laughter, melting into tears, all at once and with vehemence.</p>\n<p>“My daughter! my daughter!” she said. “I have my daughter! here<br>she is! The good God has given her back to me! Ha you! come all<br>of you! Is there any one there to see that I have my daughter?<br>Lord Jesus, how beautiful she is! You have made me wait fifteen<br>years, my good God, but it was in order to give her back to me<br>beautiful.—Then the gypsies did not eat her! Who said so? My<br>little daughter! my little daughter! Kiss me. Those good gypsies!<br>I love the gypsies!—It is really you! That was what made my heart<br>leap every time that you passed by. And I took that for hatred!<br>Forgive me, my Agnès, forgive me. You thought me very malicious,<br>did you not? I love you. Have you still the little mark on your<br>neck? Let us see. She still has it. Oh! you are beautiful! It was<br>I who gave you those big eyes, mademoiselle. Kiss me. I love you.<br>It is nothing to me that other mothers have children; I scorn<br>them now. They have only to come and see. Here is mine. See her<br>neck, her eyes, her hair, her hands. Find me anything as<br>beautiful as that! Oh! I promise you she will have lovers, that<br>she will! I have wept for fifteen years. All my beauty has<br>departed and has fallen to her. Kiss me.”</p>\n<p>She addressed to her a thousand other extravagant remarks, whose<br>accent constituted their sole beauty, disarranged the poor girl’s<br>garments even to the point of making her blush, smoothed her<br>silky hair with her hand, kissed her foot, her knee, her brow,<br>her eyes, was in raptures over everything. The young girl let her<br>have her way, repeating at intervals and very low and with<br>infinite tenderness, “My mother!”</p>\n<p>“Do you see, my little girl,” resumed the recluse, interspersing<br>her words with kisses, “I shall love you dearly? We will go away<br>from here. We are going to be very happy. I have inherited<br>something in Reims, in our country. You know Reims? Ah! no, you<br>do not know it; you were too small! If you only knew how pretty<br>you were at the age of four months! Tiny feet that people came<br>even from Epernay, which is seven leagues away, to see! We shall<br>have a field, a house. I will put you to sleep in my bed. My God!<br>my God! who would believe this? I have my daughter!”</p>\n<p>“Oh, my mother!” said the young girl, at length finding strength<br>to speak in her emotion, “the gypsy woman told me so. There was a<br>good gypsy of our band who died last year, and who always cared<br>for me like a nurse. It was she who placed this little bag about<br>my neck. She always said to me: ‘Little one, guard this jewel<br>well! ’Tis a treasure. It will cause thee to find thy mother once<br>again. Thou wearest thy mother about thy neck.’—The gypsy<br>predicted it!”</p>\n<p>The sacked nun again pressed her daughter in her arms.</p>\n<p>“Come, let me kiss you! You say that prettily. When we are in the<br>country, we will place these little shoes on an infant Jesus in<br>the church. We certainly owe that to the good, holy Virgin. What<br>a pretty voice you have! When you spoke to me just now, it was<br>music! Ah! my Lord God! I have found my child again! But is this<br>story credible? Nothing will kill one—or I should have died of<br>joy.”</p>\n<p>And then she began to clap her hands again and to laugh and to<br>cry out: “We are going to be so happy!”</p>\n<p>At that moment, the cell resounded with the clang of arms and a<br>galloping of horses which seemed to be coming from the Pont<br>Notre-Dame, amid advancing farther and farther along the quay.<br>The gypsy threw herself with anguish into the arms of the sacked<br>nun.</p>\n<p>“Save me! save me! mother! they are coming!”</p>\n<p>“Oh, heaven! what are you saying? I had forgotten! They are in<br>pursuit of you! What have you done?”</p>\n<p>“I know not,” replied the unhappy child; “but I am condemned to<br>die.”</p>\n<p>“To die!” said Gudule, staggering as though struck by lightning;<br>“to die!” she repeated slowly, gazing at her daughter with<br>staring eyes.</p>\n<p>“Yes, mother,” replied the frightened young girl, “they want to<br>kill me. They are coming to seize me. That gallows is for me!<br>Save me! save me! They are coming! Save me!”</p>\n<p>The recluse remained for several moments motionless and<br>petrified, then she moved her head in sign of doubt, and suddenly<br>giving vent to a burst of laughter, but with that terrible laugh<br>which had come back to her,—</p>\n<p>“Ho! ho! no! ’tis a dream of which you are telling me. Ah, yes! I<br>lost her, that lasted fifteen years, and then I found her again,<br>and that lasted a minute! And they would take her from me again!<br>And now, when she is beautiful, when she is grown up, when she<br>speaks to me, when she loves me; it is now that they would come<br>to devour her, before my very eyes, and I her mother! Oh! no!<br>these things are not possible. The good God does not permit such<br>things as that.”</p>\n<p>Here the cavalcade appeared to halt, and a voice was heard to say<br>in the distance,—</p>\n<p>“This way, Messire Tristan! The priest says that we shall find<br>her at the Rat-Hole.” The noise of the horses began again.</p>\n<p>The recluse sprang to her feet with a shriek of despair. “Fly!<br>fly! my child! All comes back to me. You are right. It is your<br>death! Horror! Maledictions! Fly!”</p>\n<p>She thrust her head through the window, and withdrew it again<br>hastily.</p>\n<p>“Remain,” she said, in a low, curt, and lugubrious tone, as she<br>pressed the hand of the gypsy, who was more dead than alive.<br>“Remain! Do not breathe! There are soldiers everywhere. You<br>cannot get out. It is too light.”</p>\n<p>Her eyes were dry and burning. She remained silent for a moment;<br>but she paced the cell hurriedly, and halted now and then to<br>pluck out handfuls of her gray hairs, which she afterwards tore<br>with her teeth.</p>\n<p>Suddenly she said: “They draw near. I will speak with them. Hide<br>yourself in this corner. They will not see you. I will tell them<br>that you have made your escape. That I released you, i’ faith!”</p>\n<p>She set her daughter (down for she was still carrying her), in<br>one corner of the cell which was not visible from without. She<br>made her crouch down, arranged her carefully so that neither foot<br>nor hand projected from the shadow, untied her black hair which<br>she spread over her white robe to conceal it, placed in front of<br>her her jug and her paving stone, the only articles of furniture<br>which she possessed, imagining that this jug and stone would hide<br>her. And when this was finished she became more tranquil, and<br>knelt down to pray. The day, which was only dawning, still left<br>many shadows in the Rat-Hole.</p>\n<p>At that moment, the voice of the priest, that infernal voice,<br>passed very close to the cell, crying,—</p>\n<p>“This way, Captain Phœbus de Châteaupers.”</p>\n<p>At that name, at that voice, la Esmeralda, crouching in her<br>corner, made a movement.</p>\n<p>“Do not stir!” said Gudule.</p>\n<p>She had barely finished when a tumult of men, swords, and horses<br>halted around the cell. The mother rose quickly and went to post<br>herself before her window, in order to stop it up. She beheld a<br>large troop of armed men, both horse and foot, drawn up on the<br>Grève.</p>\n<p>The commander dismounted, and came toward her.</p>\n<p>“Old woman!” said this man, who had an atrocious face, “we are in<br>search of a witch to hang her; we were told that you had her.”</p>\n<p>The poor mother assumed as indifferent an air as she could, and<br>replied,—</p>\n<p>“I know not what you mean.”</p>\n<p>The other resumed, “<em>Tête Dieu!</em> What was it that frightened<br>archdeacon said? Where is he?”</p>\n<p>“Monseigneur,” said a soldier, “he has disappeared.”</p>\n<p>“Come, now, old madwoman,” began the commander again, “do not<br>lie. A sorceress was given in charge to you. What have you done<br>with her?”</p>\n<p>The recluse did not wish to deny all, for fear of awakening<br>suspicion, and replied in a sincere and surly tone,—</p>\n<p>“If you are speaking of a big young girl who was put into my<br>hands a while ago, I will tell you that she bit me, and that I<br>released her. There! Leave me in peace.”</p>\n<p>The commander made a grimace of disappointment. “Don’t lie to me,<br>old spectre!” said he. “My name is Tristan l’Hermite, and I am<br>the king’s gossip. Tristan the Hermit, do you hear?” He added, as<br>he glanced at the Place de Grève around him, “’Tis a name which<br>has an echo here.”</p>\n<p>“You might be Satan the Hermit,” replied Gudule, who was<br>regaining hope, “but I should have nothing else to say to you,<br>and I should never be afraid of you.”</p>\n<p>“<em>Tête-Dieu</em>,” said Tristan, “here is a crone! Ah! So the witch<br>girl hath fled! And in which direction did she go?” Gudule<br>replied in a careless tone,—</p>\n<p>“Through the Rue du Mouton, I believe.”</p>\n<p>Tristan turned his head and made a sign to his troop to prepare<br>to set out on the march again. The recluse breathed freely once<br>more.</p>\n<p>“Monseigneur,” suddenly said an archer, “ask the old elf why the<br>bars of her window are broken in this manner.”</p>\n<p>This question brought anguish again to the heart of the miserable<br>mother. Nevertheless, she did not lose all presence of mind.</p>\n<p>“They have always been thus,” she stammered.</p>\n<p>“Bah!” retorted the archer, “only yesterday they still formed a<br>fine black cross, which inspired devotion.”</p>\n<p>Tristan cast a sidelong glance at the recluse.</p>\n<p>“I think the old dame is getting confused!”</p>\n<p>The unfortunate woman felt that all depended on her<br>self-possession, and, although with death in her soul, she began<br>to grin. Mothers possess such strength.</p>\n<p>“Bah!” said she, “the man is drunk. ’Tis more than a year since<br>the tail of a stone cart dashed against my window and broke in<br>the grating. And how I cursed the carter, too.”</p>\n<p>“’Tis true,” said another archer, “I was there.”</p>\n<p>Always and everywhere people are to be found who have seen<br>everything. This unexpected testimony from the archer<br>re-encouraged the recluse, whom this interrogatory was forcing to<br>cross an abyss on the edge of a knife. But she was condemned to a<br>perpetual alternative of hope and alarm.</p>\n<p>“If it was a cart which did it,” retorted the first soldier, “the<br>stumps of the bars should be thrust inwards, while they actually<br>are pushed outwards.”</p>\n<p>“Hé! hé!” said Tristan to the soldier, “you have the nose of an<br>inquisitor of the Châtelet. Reply to what he says, old woman.”</p>\n<p>“Good heavens!” she exclaimed, driven to bay, and in a voice that<br>was full of tears in despite of her efforts, “I swear to you,<br>monseigneur, that ’twas a cart which broke those bars. You hear<br>the man who saw it. And then, what has that to do with your<br>gypsy?”</p>\n<p>“Hum!” growled Tristan.</p>\n<p>“The devil!” went on the soldier, flattered by the provost’s<br>praise, “these fractures of the iron are perfectly fresh.”</p>\n<p>Tristan tossed his head. She turned pale.</p>\n<p>“How long ago, say you, did the cart do it?”</p>\n<p>“A month, a fortnight, perhaps, monseigneur, I know not.”</p>\n<p>“She first said more than a year,” observed the soldier.</p>\n<p>“That is suspicious,” said the provost.</p>\n<p>“Monseigneur!” she cried, still pressed against the opening, and<br>trembling lest suspicion should lead them to thrust their heads<br>through and look into her cell; “monseigneur, I swear to you that<br>’twas a cart which broke this grating. I swear it to you by the<br>angels of paradise. If it was not a cart, may I be eternally<br>damned, and I reject God!”</p>\n<p>“You put a great deal of heat into that oath;” said Tristan, with<br>his inquisitorial glance.</p>\n<p>The poor woman felt her assurance vanishing more and more. She<br>had reached the point of blundering, and she comprehended with<br>terror that she was saying what she ought not to have said.</p>\n<p>Here another soldier came up, crying,—</p>\n<p>“Monsieur, the old hag lies. The sorceress did not flee through<br>the Rue de Mouton. The street chain has remained stretched all<br>night, and the chain guard has seen no one pass.”</p>\n<p>Tristan, whose face became more sinister with every moment,<br>addressed the recluse,—</p>\n<p>“What have you to say to that?”</p>\n<p>She tried to make head against this new incident,</p>\n<p>“That I do not know, monseigneur; that I may have been mistaken.<br>I believe, in fact, that she crossed the water.”</p>\n<p>“That is in the opposite direction,” said the provost, “and it is<br>not very likely that she would wish to re-enter the city, where<br>she was being pursued. You are lying, old woman.”</p>\n<p>“And then,” added the first soldier, “there is no boat either on<br>this side of the stream or on the other.”</p>\n<p>“She swam across,” replied the recluse, defending her ground foot<br>by foot.</p>\n<p>“Do women swim?” said the soldier.</p>\n<p>“<em>Tête Dieu!</em> old woman! You are lying!” repeated Tristan<br>angrily. “I have a good mind to abandon that sorceress and take<br>you. A quarter of an hour of torture will, perchance, draw the<br>truth from your throat. Come! You are to follow us.”</p>\n<p>She seized on these words with avidity.</p>\n<p>“As you please, monseigneur. Do it. Do it. Torture. I am willing.<br>Take me away. Quick, quick! let us set out at once!—During that<br>time,” she said to herself, “my daughter will make her escape.”</p>\n<p>“’S death!” said the provost, “what an appetite for the rack! I<br>understand not this madwoman at all.”</p>\n<p>An old, gray-haired sergeant of the guard stepped out of the<br>ranks, and addressing the provost,—</p>\n<p>“Mad in sooth, monseigneur. If she released the gypsy, it was not<br>her fault, for she loves not the gypsies. I have been of the<br>watch these fifteen years, and I hear her every evening cursing<br>the Bohemian women with endless imprecations. If the one of whom<br>we are in pursuit is, as I suppose, the little dancer with the<br>goat, she detests that one above all the rest.”</p>\n<p>Gudule made an effort and said,—</p>\n<p>“That one above all.”</p>\n<p>The unanimous testimony of the men of the watch confirmed the old<br>sergeant’s words to the provost. Tristan l’Hermite, in despair at<br>extracting anything from the recluse, turned his back on her, and<br>with unspeakable anxiety she beheld him direct his course slowly<br>towards his horse.</p>\n<p>“Come!” he said, between his teeth, “March on! let us set out<br>again on the quest. I shall not sleep until that gypsy is<br>hanged.”</p>\n<p>But he still hesitated for some time before mounting his horse.<br>Gudule palpitated between life and death, as she beheld him cast<br>about the Place that uneasy look of a hunting dog which<br>instinctively feels that the lair of the beast is close to him,<br>and is loath to go away. At length he shook his head and leaped<br>into his saddle. Gudule’s horribly compressed heart now dilated,<br>and she said in a low voice, as she cast a glance at her<br>daughter, whom she had not ventured to look at while they were<br>there, “Saved!”</p>\n<p>The poor child had remained all this time in her corner, without<br>breathing, without moving, with the idea of death before her. She<br>had lost nothing of the scene between Gudule and Tristan, and the<br>anguish of her mother had found its echo in her heart. She had<br>heard all the successive snappings of the thread by which she<br>hung suspended over the gulf; twenty times she had fancied that<br>she saw it break, and at last she began to breathe again and to<br>feel her foot on firm ground. At that moment she heard a voice<br>saying to the provost: “<em>Corbœuf!</em> Monsieur le Prevôt, ’tis no<br>affair of mine, a man of arms, to hang witches. The rabble of the<br>populace is suppressed. I leave you to attend to the matter<br>alone. You will allow me to rejoin my company, who are waiting<br>for their captain.”</p>\n<p>The voice was that of Phœbus de Châteaupers; that which took<br>place within her was ineffable. He was there, her friend, her<br>protector, her support, her refuge, her Phœbus. She rose, and<br>before her mother could prevent her, she had rushed to the<br>window, crying,—</p>\n<p>“Phœbus! aid me, my Phœbus!”</p>\n<p>Phœbus was no longer there. He had just turned the corner of the<br>Rue de la Coutellerie at a gallop. But Tristan had not yet taken<br>his departure.</p>\n<p>The recluse rushed upon her daughter with a roar of agony. She<br>dragged her violently back, digging her nails into her neck. A<br>tigress mother does not stand on trifles. But it was too late.<br>Tristan had seen.</p>\n<p>“Hé! hé!” he exclaimed with a laugh which laid bare all his teeth<br>and made his face resemble the muzzle of a wolf, “two mice in the<br>trap!”</p>\n<p>“I suspected as much,” said the soldier.</p>\n<p>Tristan clapped him on the shoulder,—</p>\n<p>“You are a good cat! Come!” he added, “where is Henriet Cousin?”</p>\n<p>A man who had neither the garments nor the air of a soldier,<br>stepped from the ranks. He wore a costume half gray, half brown,<br>flat hair, leather sleeves, and carried a bundle of ropes in his<br>huge hand. This man always attended Tristan, who always attended<br>Louis XI. “Friend,” said Tristan l’Hermite, “I presume that this<br>is the sorceress of whom we are in search. You will hang me this<br>one. Have you your ladder?”</p>\n<p>“There is one yonder, under the shed of the Pillar-House,”<br>replied the man. “Is it on this justice that the thing is to be<br>done?” he added, pointing to the stone gibbet.</p>\n<p>“Yes.”</p>\n<p>“Ho, hé!” continued the man with a huge laugh, which was still<br>more brutal than that of the provost, “we shall not have far to<br>go.”</p>\n<p>“Make haste!” said Tristan, “you shall laugh afterwards.”</p>\n<p>In the meantime, the recluse had not uttered another word since<br>Tristan had seen her daughter and all hope was lost. She had<br>flung the poor gypsy, half dead, into the corner of the cellar,<br>and had placed herself once more at the window with both hands<br>resting on the angle of the sill like two claws. In this attitude<br>she was seen to cast upon all those soldiers her glance which had<br>become wild and frantic once more. At the moment when Rennet<br>Cousin approached her cell, she showed him so savage a face that<br>he shrank back.</p>\n<p>“Monseigneur,” he said, returning to the provost, “which am I to<br>take?”</p>\n<p>“The young one.”</p>\n<p>“So much the better, for the old one seemeth difficult.”</p>\n<p>“Poor little dancer with the goat!” said the old sergeant of the<br>watch.</p>\n<p>Rennet Cousin approached the window again. The mother’s eyes made<br>his own droop. He said with a good deal of timidity,—</p>\n<p>“Madam”—</p>\n<p>She interrupted him in a very low but furious voice,—</p>\n<p>“What do you ask?”</p>\n<p>“It is not you,” he said, “it is the other.”</p>\n<p>“What other?”</p>\n<p>“The young one.”</p>\n<p>She began to shake her head, crying,—</p>\n<p>“There is no one! there is no one! there is no one!”</p>\n<p>“Yes, there is!” retorted the hangman, “and you know it well. Let<br>me take the young one. I have no wish to harm you.”</p>\n<p>She said, with a strange sneer,—</p>\n<p>“Ah! so you have no wish to harm me!”</p>\n<p>“Let me have the other, madam; ’tis monsieur the provost who<br>wills it.”</p>\n<p>She repeated with a look of madness,—</p>\n<p>“There is no one here.”</p>\n<p>“I tell you that there is!” replied the executioner. “We have all<br>seen that there are two of you.”</p>\n<p>“Look then!” said the recluse, with a sneer. “Thrust your head<br>through the window.”</p>\n<p>The executioner observed the mother’s finger-nails and dared not.</p>\n<p>“Make haste!” shouted Tristan, who had just ranged his troops in<br>a circle round the Rat-Hole, and who sat on his horse beside the<br>gallows.</p>\n<p>Rennet returned once more to the provost in great embarrassment.<br>He had flung his rope on the ground, and was twisting his hat<br>between his hands with an awkward air.</p>\n<p>“Monseigneur,” he asked, “where am I to enter?”</p>\n<p>“By the door.”</p>\n<p>“There is none.”</p>\n<p>“By the window.”</p>\n<p>“’Tis too small.”</p>\n<p>“Make it larger,” said Tristan angrily. “Have you not pickaxes?”</p>\n<p>The mother still looked on steadfastly from the depths of her<br>cavern. She no longer hoped for anything, she no longer knew what<br>she wished, except that she did not wish them to take her<br>daughter.</p>\n<p>Rennet Cousin went in search of the chest of tools for the night<br>man, under the shed of the Pillar-House. He drew from it also the<br>double ladder, which he immediately set up against the gallows.<br>Five or six of the provost’s men armed themselves with picks and<br>crowbars, and Tristan betook himself, in company with them,<br>towards the window.</p>\n<p>“Old woman,” said the provost, in a severe tone, “deliver up to<br>us that girl quietly.”</p>\n<p>She looked at him like one who does not understand.</p>\n<p>“<em>Tête Dieu!</em>” continued Tristan, “why do you try to prevent this<br>sorceress being hung as it pleases the king?”</p>\n<p>The wretched woman began to laugh in her wild way.</p>\n<p>“Why? She is my daughter.”</p>\n<p>The tone in which she pronounced these words made even Henriet<br>Cousin shudder.</p>\n<p>“I am sorry for that,” said the provost, “but it is the king’s<br>good pleasure.”</p>\n<p>She cried, redoubling her terrible laugh,—</p>\n<p>“What is your king to me? I tell you that she is my daughter!”</p>\n<p>“Pierce the wall,” said Tristan.</p>\n<p>In order to make a sufficiently wide opening, it sufficed to<br>dislodge one course of stone below the window. When the mother<br>heard the picks and crowbars mining her fortress, she uttered a<br>terrible cry; then she began to stride about her cell with<br>frightful swiftness, a wild beasts’ habit which her cage had<br>imparted to her. She no longer said anything, but her eyes<br>flamed. The soldiers were chilled to the very soul.</p>\n<p>All at once she seized her paving stone, laughed, and hurled it<br>with both fists upon the workmen. The stone, badly flung (for her<br>hands trembled), touched no one, and fell short under the feet of<br>Tristan’s horse. She gnashed her teeth.</p>\n<p>In the meantime, although the sun had not yet risen, it was broad<br>daylight; a beautiful rose color enlivened the ancient, decayed<br>chimneys of the Pillar-House. It was the hour when the earliest<br>windows of the great city open joyously on the roofs. Some<br>workmen, a few fruit-sellers on their way to the markets on their<br>asses, began to traverse the Grève; they halted for a moment<br>before this group of soldiers clustered round the Rat-Hole,<br>stared at it with an air of astonishment and passed on.</p>\n<p>The recluse had gone and seated herself by her daughter, covering<br>her with her body, in front of her, with staring eyes, listening<br>to the poor child, who did not stir, but who kept murmuring in a<br>low voice, these words only, “Phœbus! Phœbus!” In proportion as<br>the work of the demolishers seemed to advance, the mother<br>mechanically retreated, and pressed the young girl closer and<br>closer to the wall. All at once, the recluse beheld the stone<br>(for she was standing guard and never took her eyes from it),<br>move, and she heard Tristan’s voice encouraging the workers. Then<br>she aroused from the depression into which she had fallen during<br>the last few moments, cried out, and as she spoke, her voice now<br>rent the ear like a saw, then stammered as though all kind of<br>maledictions were pressing to her lips to burst forth at once.</p>\n<p>“Ho! ho! ho! Why this is terrible! You are ruffians! Are you<br>really going to take my daughter? Oh! the cowards! Oh! the<br>hangman lackeys! the wretched, blackguard assassins! Help! help!<br>fire! Will they take my child from me like this? Who is it then<br>who is called the good God?”</p>\n<p>Then, addressing Tristan, foaming at the mouth, with wild eyes,<br>all bristling and on all fours like a female panther,—</p>\n<p>“Draw near and take my daughter! Do not you understand that this<br>woman tells you that she is my daughter? Do you know what it is<br>to have a child? Eh! lynx, have you never lain with your female?<br>have you never had a cub? and if you have little ones, when they<br>howl have you nothing in your vitals that moves?”</p>\n<p>“Throw down the stone,” said Tristan; “it no longer holds.”</p>\n<p>The crowbars raised the heavy course. It was, as we have said,<br>the mother’s last bulwark.</p>\n<p>She threw herself upon it, she tried to hold it back; she<br>scratched the stone with her nails, but the massive block, set in<br>movement by six men, escaped her and glided gently to the ground<br>along the iron levers.</p>\n<p>The mother, perceiving an entrance effected, fell down in front<br>of the opening, barricading the breach with her body, beating the<br>pavement with her head, and shrieking with a voice rendered so<br>hoarse by fatigue that it was hardly audible,—</p>\n<p>“Help! fire! fire!”</p>\n<p>“Now take the wench,” said Tristan, still impassive.</p>\n<p>The mother gazed at the soldiers in such formidable fashion that<br>they were more inclined to retreat than to advance.</p>\n<p>“Come, now,” repeated the provost. “Here you, Rennet Cousin!”</p>\n<p>No one took a step.</p>\n<p>The provost swore,—</p>\n<p>“<em>Tête de Christ!</em> my men of war! afraid of a woman!”</p>\n<p>“Monseigneur,” said Rennet, “do you call that a woman?”</p>\n<p>“She has the mane of a lion,” said another.</p>\n<p>“Come!” repeated the provost, “the gap is wide enough. Enter<br>three abreast, as at the breach of Pontoise. Let us make an end<br>of it, death of Mahom! I will make two pieces of the first man<br>who draws back!”</p>\n<p>Placed between the provost and the mother, both threatening, the<br>soldiers hesitated for a moment, then took their resolution, and<br>advanced towards the Rat-Hole.</p>\n<p>When the recluse saw this, she rose abruptly on her knees, flung<br>aside her hair from her face, then let her thin flayed hands fall<br>by her side. Then great tears fell, one by one, from her eyes;<br>they flowed down her cheeks through a furrow, like a torrent<br>through a bed which it has hollowed for itself.</p>\n<p>At the same time she began to speak, but in a voice so<br>supplicating, so gentle, so submissive, so heartrending, that<br>more than one old convict-warder around Tristan who must have<br>devoured human flesh wiped his eyes.</p>\n<p>“Messeigneurs! messieurs the sergeants, one word. There is one<br>thing which I must say to you. She is my daughter, do you see? my<br>dear little daughter whom I had lost! Listen. It is quite a<br>history. Consider that I knew the sergeants very well. They were<br>always good to me in the days when the little boys threw stones<br>at me, because I led a life of pleasure. Do you see? You will<br>leave me my child when you know! I was a poor woman of the town.<br>It was the Bohemians who stole her from me. And I kept her shoe<br>for fifteen years. Stay, here it is. That was the kind of foot<br>which she had. At Reims! La Chantefleurie! Rue Folle-Peine!<br>Perchance, you knew about that. It was I. In your youth, then,<br>there was a merry time, when one passed good hours. You will take<br>pity on me, will you not, gentlemen? The gypsies stole her from<br>me; they hid her from me for fifteen years. I thought her dead.<br>Fancy, my good friends, believed her to be dead. I have passed<br>fifteen years here in this cellar, without a fire in winter. It<br>is hard. The poor, dear little shoe! I have cried so much that<br>the good God has heard me. This night he has given my daughter<br>back to me. It is a miracle of the good God. She was not dead.<br>You will not take her from me, I am sure. If it were myself, I<br>would say nothing; but she, a child of sixteen! Leave her time to<br>see the sun! What has she done to you? nothing at all. Nor have<br>I. If you did but know that she is all I have, that I am old,<br>that she is a blessing which the Holy Virgin has sent to me! And<br>then, you are all so good! You did not know that she was my<br>daughter; but now you do know it. Oh! I love her! Monsieur, the<br>grand provost. I would prefer a stab in my own vitals to a<br>scratch on her finger! You have the air of such a good lord! What<br>I have told you explains the matter, does it not? Oh! if you have<br>had a mother, monseigneur! you are the captain, leave me my<br>child! Consider that I pray you on my knees, as one prays to<br>Jesus Christ! I ask nothing of any one; I am from Reims,<br>gentlemen; I own a little field inherited from my uncle, Mahiet<br>Pradon. I am no beggar. I wish nothing, but I do want my child!<br>oh! I want to keep my child! The good God, who is the master, has<br>not given her back to me for nothing! The king! you say the king!<br>It would not cause him much pleasure to have my little daughter<br>killed! And then, the king is good! she is my daughter! she is my<br>own daughter! She belongs not to the king! she is not yours! I<br>want to go away! we want to go away! and when two women pass, one<br>a mother and the other a daughter, one lets them go! Let us pass!<br>we belong in Reims. Oh! you are very good, messieurs the<br>sergeants, I love you all. You will not take my dear little one,<br>it is impossible! It is utterly impossible, is it not? My child,<br>my child!”</p>\n<p>We will not try to give an idea of her gestures, her tone, of the<br>tears which she swallowed as she spoke, of the hands which she<br>clasped and then wrung, of the heart-breaking smiles, of the<br>swimming glances, of the groans, the sighs, the miserable and<br>affecting cries which she mingled with her disordered, wild, and<br>incoherent words. When she became silent Tristan l’Hermite<br>frowned, but it was to conceal a tear which welled up in his<br>tiger’s eye. He conquered this weakness, however, and said in a<br>curt tone,—</p>\n<p>“The king wills it.”</p>\n<p>Then he bent down to the ear of Rennet Cousin, and said to him in<br>a very low tone,—</p>\n<p>“Make an end of it quickly!” Possibly, the redoubtable provost<br>felt his heart also failing him.</p>\n<p>The executioner and the sergeants entered the cell. The mother<br>offered no resistance, only she dragged herself towards her<br>daughter and threw herself bodily upon her. The gypsy beheld the<br>soldiers approach. The horror of death reanimated her,—</p>\n<p>“Mother!” she shrieked, in a tone of indescribable distress,<br>“Mother! they are coming! defend me!”</p>\n<p>“Yes, my love, I am defending you!” replied the mother, in a<br>dying voice; and clasping her closely in her arms, she covered<br>her with kisses. The two lying thus on the earth, the mother upon<br>the daughter, presented a spectacle worthy of pity.</p>\n<p>Rennet Cousin grasped the young girl by the middle of her body,<br>beneath her beautiful shoulders. When she felt that hand, she<br>cried, “Heuh!” and fainted. The executioner who was shedding<br>large tears upon her, drop by drop, was about to bear her away in<br>his arms. He tried to detach the mother, who had, so to speak,<br>knotted her hands around her daughter’s waist; but she clung so<br>strongly to her child, that it was impossible to separate them.<br>Then Rennet Cousin dragged the young girl outside the cell, and<br>the mother after her. The mother’s eyes were also closed.</p>\n<p>At that moment, the sun rose, and there was already on the Place<br>a fairly numerous assembly of people who looked on from a<br>distance at what was being thus dragged along the pavement to the<br>gibbet. For that was Provost Tristan’s way at executions. He had<br>a passion for preventing the approach of the curious.</p>\n<p>There was no one at the windows. Only at a distance, at the<br>summit of that one of the towers of Notre-Dame which commands the<br>Grève, two men outlined in black against the light morning sky,<br>and who seemed to be looking on, were visible.</p>\n<p>Rennet Cousin paused at the foot of the fatal ladder, with that<br>which he was dragging, and, barely breathing, with so much pity<br>did the thing inspire him, he passed the rope around the lovely<br>neck of the young girl. The unfortunate child felt the horrible<br>touch of the hemp. She raised her eyelids, and saw the fleshless<br>arm of the stone gallows extended above her head. Then she shook<br>herself and shrieked in a loud and heartrending voice: “No! no! I<br>will not!” Her mother, whose head was buried and concealed in her<br>daughter’s garments, said not a word; only her whole body could<br>be seen to quiver, and she was heard to redouble her kisses on<br>her child. The executioner took advantage of this moment to<br>hastily loose the arms with which she clasped the condemned girl.<br>Either through exhaustion or despair, she let him have his way.<br>Then he took the young girl on his shoulder, from which the<br>charming creature hung, gracefully bent over his large head. Then<br>he set his foot on the ladder in order to ascend.</p>\n<p>At that moment, the mother who was crouching on the pavement,<br>opened her eyes wide. Without uttering a cry, she raised herself<br>erect with a terrible expression; then she flung herself upon the<br>hand of the executioner, like a beast on its prey, and bit it. It<br>was done like a flash of lightning. The headsman howled with<br>pain. Those near by rushed up. With difficulty they withdrew his<br>bleeding hand from the mother’s teeth. She preserved a profound<br>silence. They thrust her back with much brutality, and noticed<br>that her head fell heavily on the pavement. They raised her, she<br>fell back again. She was dead.</p>\n<p>The executioner, who had not loosed his hold on the young girl,<br>began to ascend the ladder once more.</p>\n<h1 class=\"chapter\" id=\"chapter-ii-the-beautiful-creature-clad-in-white-\">Chapter II. THE BEAUTIFUL CREATURE CLAD IN WHITE. (Dante.)</h1>\n<p>When Quasimodo saw that the cell was empty, that the gypsy was no<br>longer there, that while he had been defending her she had been<br>abducted, he grasped his hair with both hands and stamped with<br>surprise and pain; then he set out to run through the entire<br>church seeking his Bohemian, howling strange cries to all the<br>corners of the walls, strewing his red hair on the pavement. It<br>was just at the moment when the king’s archers were making their<br>victorious entrance into Notre-Dame, also in search of the gypsy.<br>Quasimodo, poor, deaf fellow, aided them in their fatal<br>intentions, without suspecting it; he thought that the outcasts<br>were the gypsy’s enemies. He himself conducted Tristan l’Hermite<br>to all possible hiding-places, opened to him the secret doors,<br>the double bottoms of the altars, the rear sacristries. If the<br>unfortunate girl had still been there, it would have been he<br>himself who would have delivered her up.</p>\n<p>When the fatigue of finding nothing had disheartened Tristan, who<br>was not easily discouraged, Quasimodo continued the search alone.<br>He made the tour of the church twenty times, length and breadth,<br>up and down, ascending and descending, running, calling,<br>shouting, peeping, rummaging, ransacking, thrusting his head into<br>every hole, pushing a torch under every vault, despairing, mad. A<br>male who has lost his female is no more roaring nor more haggard.</p>\n<p>At last when he was sure, perfectly sure that she was no longer<br>there, that all was at an end, that she had been snatched from<br>him, he slowly mounted the staircase to the towers, that<br>staircase which he had ascended with so much eagerness and<br>triumph on the day when he had saved her. He passed those same<br>places once more with drooping head, voiceless, tearless, almost<br>breathless. The church was again deserted, and had fallen back<br>into its silence. The archers had quitted it to track the<br>sorceress in the city. Quasimodo, left alone in that vast<br>Notre-Dame, so besieged and tumultuous but a short time before,<br>once more betook himself to the cell where the gypsy had slept<br>for so many weeks under his guardianship.</p>\n<p>As he approached it, he fancied that he might, perhaps, find her<br>there. When, at the turn of the gallery which opens on the roof<br>of the side aisles, he perceived the tiny cell with its little<br>window and its little door crouching beneath a great flying<br>buttress like a bird’s nest under a branch, the poor man’s heart<br>failed him, and he leaned against a pillar to keep from falling.<br>He imagined that she might have returned thither, that some good<br>genius had, no doubt, brought her back, that this chamber was too<br>tranquil, too safe, too charming for her not to be there, and he<br>dared not take another step for fear of destroying his illusion.<br>“Yes,” he said to himself, “perchance she is sleeping, or<br>praying. I must not disturb her.”</p>\n<p>At length he summoned up courage, advanced on tiptoe, looked,<br>entered. Empty. The cell was still empty. The unhappy deaf man<br>walked slowly round it, lifted the bed and looked beneath it, as<br>though she might be concealed between the pavement and the<br>mattress, then he shook his head and remained stupefied. All at<br>once, he crushed his torch under his foot, and, without uttering<br>a word, without giving vent to a sigh, he flung himself at full<br>speed, head foremost against the wall, and fell fainting on the<br>floor.</p>\n<p>When he recovered his senses, he threw himself on the bed and<br>rolling about, he kissed frantically the place where the young<br>girl had slept and which was still warm; he remained there for<br>several moments as motionless as though he were about to expire;<br>then he rose, dripping with perspiration, panting, mad, and began<br>to beat his head against the wall with the frightful regularity<br>of the clapper of his bells, and the resolution of a man<br>determined to kill himself. At length he fell a second time,<br>exhausted; he dragged himself on his knees outside the cell, and<br>crouched down facing the door, in an attitude of astonishment.</p>\n<p>He remained thus for more than an hour without making a movement,<br>with his eye fixed on the deserted cell, more gloomy, and more<br>pensive than a mother seated between an empty cradle and a full<br>coffin. He uttered not a word; only at long intervals, a sob<br>heaved his body violently, but it was a tearless sob, like summer<br>lightning which makes no noise.</p>\n<p>It appears to have been then, that, seeking at the bottom of his<br>lonely thoughts for the unexpected abductor of the gypsy, he<br>thought of the archdeacon. He remembered that Dom Claude alone<br>possessed a key to the staircase leading to the cell; he recalled<br>his nocturnal attempts on the young girl, in the first of which<br>he, Quasimodo, had assisted, the second of which he had<br>prevented. He recalled a thousand details, and soon he no longer<br>doubted that the archdeacon had taken the gypsy. Nevertheless,<br>such was his respect for the priest, such his gratitude, his<br>devotion, his love for this man had taken such deep root in his<br>heart, that they resisted, even at this moment, the talons of<br>jealousy and despair.</p>\n<p>He reflected that the archdeacon had done this thing, and the<br>wrath of blood and death which it would have evoked in him<br>against any other person, turned in the poor deaf man, from the<br>moment when Claude Frollo was in question, into an increase of<br>grief and sorrow.</p>\n<p>At the moment when his thought was thus fixed upon the priest,<br>while the daybreak was whitening the flying buttresses, he<br>perceived on the highest story of Notre-Dame, at the angle formed<br>by the external balustrade as it makes the turn of the chancel, a<br>figure walking. This figure was coming towards him. He recognized<br>it. It was the archdeacon.</p>\n<p>Claude was walking with a slow, grave step. He did not look<br>before him as he walked, he was directing his course towards the<br>northern tower, but his face was turned aside towards the right<br>bank of the Seine, and he held his head high, as though trying to<br>see something over the roofs. The owl often assumes this oblique<br>attitude. It flies towards one point and looks towards another.<br>In this manner the priest passed above Quasimodo without seeing<br>him.</p>\n<p>The deaf man, who had been petrified by this sudden apparition,<br>beheld him disappear through the door of the staircase to the<br>north tower. The reader is aware that this is the tower from<br>which the Hôtel-de-Ville is visible. Quasimodo rose and followed<br>the archdeacon.</p>\n<p>Quasimodo ascended the tower staircase for the sake of ascending<br>it, for the sake of seeing why the priest was ascending it.<br>Moreover, the poor bellringer did not know what he (Quasimodo)<br>should do, what he should say, what he wished. He was full of<br>fury and full of fear. The archdeacon and the gypsy had come into<br>conflict in his heart.</p>\n<p>When he reached the summit of the tower, before emerging from the<br>shadow of the staircase and stepping upon the platform, he<br>cautiously examined the position of the priest. The priest’s back<br>was turned to him. There is an openwork balustrade which<br>surrounds the platform of the bell tower. The priest, whose eyes<br>looked down upon the town, was resting his breast on that one of<br>the four sides of the balustrades which looks upon the Pont<br>Notre-Dame.</p>\n<p>Quasimodo, advancing with the tread of a wolf behind him, went to<br>see what he was gazing at thus.</p>\n<p>The priest’s attention was so absorbed elsewhere that he did not<br>hear the deaf man walking behind him.</p>\n<p>Paris is a magnificent and charming spectacle, and especially at<br>that day, viewed from the top of the towers of Notre-Dame, in the<br>fresh light of a summer dawn. The day might have been in July.<br>The sky was perfectly serene. Some tardy stars were fading away<br>at various points, and there was a very brilliant one in the<br>east, in the brightest part of the heavens. The sun was about to<br>appear; Paris was beginning to move. A very white and very pure<br>light brought out vividly to the eye all the outlines that its<br>thousands of houses present to the east. The giant shadow of the<br>towers leaped from roof to roof, from one end of the great city<br>to the other. There were several quarters from which were already<br>heard voices and noisy sounds. Here the stroke of a bell, there<br>the stroke of a hammer, beyond, the complicated clatter of a cart<br>in motion.</p>\n<p>Already several columns of smoke were being belched forth from<br>the chimneys scattered over the whole surface of roofs, as<br>through the fissures of an immense sulphurous crater. The river,<br>which ruffles its waters against the arches of so many bridges,<br>against the points of so many islands, was wavering with silvery<br>folds. Around the city, outside the ramparts, sight was lost in a<br>great circle of fleecy vapors through which one confusedly<br>distinguished the indefinite line of the plains, and the graceful<br>swell of the heights. All sorts of floating sounds were dispersed<br>over this half-awakened city. Towards the east, the morning<br>breeze chased a few soft white bits of wool torn from the misty<br>fleece of the hills.</p>\n<p>In the Parvis, some good women, who had their milk jugs in their<br>hands, were pointing out to each other, with astonishment, the<br>singular dilapidation of the great door of Notre-Dame, and the<br>two solidified streams of lead in the crevices of the stone. This<br>was all that remained of the tempest of the night. The bonfire<br>lighted between the towers by Quasimodo had died out. Tristan had<br>already cleared up the Place, and had the dead thrown into the<br>Seine. Kings like Louis XI. are careful to clean the pavement<br>quickly after a massacre.</p>\n<p>Outside the balustrade of the tower, directly under the point<br>where the priest had paused, there was one of those fantastically<br>carved stone gutters with which Gothic edifices bristle, and, in<br>a crevice of that gutter, two pretty wallflowers in blossom,<br>shaken out and vivified, as it were, by the breath of air, made<br>frolicsome salutations to each other. Above the towers, on high,<br>far away in the depths of the sky, the cries of little birds were<br>heard.</p>\n<p>But the priest was not listening to, was not looking at, anything<br>of all this. He was one of the men for whom there are no<br>mornings, no birds, no flowers. In that immense horizon, which<br>assumed so many aspects about him, his contemplation was<br>concentrated on a single point.</p>\n<p>Quasimodo was burning to ask him what he had done with the gypsy;<br>but the archdeacon seemed to be out of the world at that moment.<br>He was evidently in one of those violent moments of life when one<br>would not feel the earth crumble. He remained motionless and<br>silent, with his eyes steadily fixed on a certain point; and<br>there was something so terrible about this silence and immobility<br>that the savage bellringer shuddered before it and dared not come<br>in contact with it. Only, and this was also one way of<br>interrogating the archdeacon, he followed the direction of his<br>vision, and in this way the glance of the unhappy deaf man fell<br>upon the Place de Grève.</p>\n<p>Thus he saw what the priest was looking at. The ladder was<br>erected near the permanent gallows. There were some people and<br>many soldiers in the Place. A man was dragging a white thing,<br>from which hung something black, along the pavement. This man<br>halted at the foot of the gallows.</p>\n<p>Here something took place which Quasimodo could not see very<br>clearly. It was not because his only eye had not preserved its<br>long range, but there was a group of soldiers which prevented his<br>seeing everything. Moreover, at that moment the sun appeared, and<br>such a flood of light overflowed the horizon that one would have<br>said that all the points in Paris, spires, chimneys, gables, had<br>simultaneously taken fire.</p>\n<p>Meanwhile, the man began to mount the ladder. Then Quasimodo saw<br>him again distinctly. He was carrying a woman on his shoulder, a<br>young girl dressed in white; that young girl had a noose about<br>her neck. Quasimodo recognized her.</p>\n<p>It was she.</p>\n<p>The man reached the top of the ladder. There he arranged the<br>noose. Here the priest, in order to see the better, knelt upon<br>the balustrade.</p>\n<p>All at once the man kicked away the ladder abruptly, and<br>Quasimodo, who had not breathed for several moments, beheld the<br>unhappy child dangling at the end of the rope two fathoms above<br>the pavement, with the man squatting on her shoulders. The rope<br>made several gyrations on itself, and Quasimodo beheld horrible<br>convulsions run along the gypsy’s body. The priest, on his side,<br>with outstretched neck and eyes starting from his head,<br>contemplated this horrible group of the man and the young<br>girl,—the spider and the fly.</p>\n<p>At the moment when it was most horrible, the laugh of a demon, a<br>laugh which one can only give vent to when one is no longer<br>human, burst forth on the priest’s livid face.</p>\n<p>Quasimodo did not hear that laugh, but he saw it.</p>\n<p>The bellringer retreated several paces behind the archdeacon, and<br>suddenly hurling himself upon him with fury, with his huge hands<br>he pushed him by the back over into the abyss over which Dom<br>Claude was leaning.</p>\n<p>The priest shrieked: “Damnation!” and fell.</p>\n<p>The spout, above which he had stood, arrested him in his fall. He<br>clung to it with desperate hands, and, at the moment when he<br>opened his mouth to utter a second cry, he beheld the formidable<br>and avenging face of Quasimodo thrust over the edge of the<br>balustrade above his head.</p>\n<p>Then he was silent.</p>\n<p>The abyss was there below him. A fall of more than two hundred<br>feet and the pavement.</p>\n<p>In this terrible situation, the archdeacon said not a word,<br>uttered not a groan. He merely writhed upon the spout, with<br>incredible efforts to climb up again; but his hands had no hold<br>on the granite, his feet slid along the blackened wall without<br>catching fast. People who have ascended the towers of Notre-Dame<br>know that there is a swell of the stone immediately beneath the<br>balustrade. It was on this retreating angle that miserable<br>archdeacon exhausted himself. He had not to deal with a<br>perpendicular wall, but with one which sloped away beneath him.</p>\n<p>Quasimodo had but to stretch out his hand in order to draw him<br>from the gulf; but he did not even look at him. He was looking at<br>the Grève. He was looking at the gallows. He was looking at the<br>gypsy.</p>\n<p>The deaf man was leaning, with his elbows on the balustrade, at<br>the spot where the archdeacon had been a moment before, and<br>there, never detaching his gaze from the only object which<br>existed for him in the world at that moment, he remained<br>motionless and mute, like a man struck by lightning, and a long<br>stream of tears flowed in silence from that eye which, up to that<br>time, had never shed but one tear.</p>\n<p>Meanwhile, the archdeacon was panting. His bald brow was dripping<br>with perspiration, his nails were bleeding against the stones,<br>his knees were flayed by the wall.</p>\n<p>He heard his cassock, which was caught on the spout, crack and<br>rip at every jerk that he gave it. To complete his misfortune,<br>this spout ended in a leaden pipe which bent under the weight of<br>his body. The archdeacon felt this pipe slowly giving way. The<br>miserable man said to himself that, when his hands should be worn<br>out with fatigue, when his cassock should tear asunder, when the<br>lead should give way, he would be obliged to fall, and terror<br>seized upon his very vitals. Now and then he glanced wildly at a<br>sort of narrow shelf formed, ten feet lower down, by projections<br>of the sculpture, and he prayed heaven, from the depths of his<br>distressed soul, that he might be allowed to finish his life,<br>were it to last two centuries, on that space two feet square.<br>Once, he glanced below him into the Place, into the abyss; the<br>head which he raised again had its eyes closed and its hair<br>standing erect.</p>\n<p>There was something frightful in the silence of these two men.<br>While the archdeacon agonized in this terrible fashion a few feet<br>below him, Quasimodo wept and gazed at the Grève.</p>\n<p>The archdeacon, seeing that all his exertions served only to<br>weaken the fragile support which remained to him, decided to<br>remain quiet. There he hung, embracing the gutter, hardly<br>breathing, no longer stirring, making no longer any other<br>movements than that mechanical convulsion of the stomach, which<br>one experiences in dreams when one fancies himself falling. His<br>fixed eyes were wide open with a stare. He lost ground little by<br>little, nevertheless, his fingers slipped along the spout; he<br>became more and more conscious of the feebleness of his arms and<br>the weight of his body. The curve of the lead which sustained him<br>inclined more and more each instant towards the abyss.</p>\n<p>He beheld below him, a frightful thing, the roof of Saint-Jean le<br>Rond, as small as a card folded in two. He gazed at the<br>impressive carvings, one by one, of the tower, suspended like<br>himself over the precipice, but without terror for themselves or<br>pity for him. All was stone around him; before his eyes, gaping<br>monsters; below, quite at the bottom, in the Place, the pavement;<br>above his head, Quasimodo weeping.</p>\n<p>In the Parvis there were several groups of curious good people,<br>who were tranquilly seeking to divine who the madman could be who<br>was amusing himself in so strange a manner. The priest heard them<br>saying, for their voices reached him, clear and shrill: “Why, he<br>will break his neck!”</p>\n<p>Quasimodo wept.</p>\n<p>At last the archdeacon, foaming with rage and despair, understood<br>that all was in vain. Nevertheless, he collected all the strength<br>which remained to him for a final effort. He stiffened himself<br>upon the spout, pushed against the wall with both his knees,<br>clung to a crevice in the stones with his hands, and succeeded in<br>climbing back with one foot, perhaps; but this effort made the<br>leaden beak on which he rested bend abruptly. His cassock burst<br>open at the same time. Then, feeling everything give way beneath<br>him, with nothing but his stiffened and failing hands to support<br>him, the unfortunate man closed his eyes and let go of the spout.<br>He fell.</p>\n<p>Quasimodo watched him fall.</p>\n<p>A fall from such a height is seldom perpendicular. The<br>archdeacon, launched into space, fell at first head foremost,<br>with outspread hands; then he whirled over and over many times;<br>the wind blew him upon the roof of a house, where the unfortunate<br>man began to break up. Nevertheless, he was not dead when he<br>reached there. The bellringer saw him still endeavor to cling to<br>a gable with his nails; but the surface sloped too much, and he<br>had no more strength. He slid rapidly along the roof like a<br>loosened tile, and dashed upon the pavement. There he no longer<br>moved.</p>\n<p>Then Quasimodo raised his eyes to the gypsy, whose body he beheld<br>hanging from the gibbet, quivering far away beneath her white<br>robe with the last shudderings of anguish, then he dropped them<br>on the archdeacon, stretched out at the base of the tower, and no<br>longer retaining the human form, and he said, with a sob which<br>heaved his deep chest,—“Oh! all that I have ever loved!”</p>\n<h1 class=\"chapter\" id=\"chapter-iii-the-marriage-of-phoebus\">Chapter III. THE MARRIAGE OF PHOEBUS.</h1>\n<p>Towards evening on that day, when the judiciary officers of the<br>bishop came to pick up from the pavement of the Parvis the<br>dislocated corpse of the archdeacon, Quasimodo had disappeared.</p>\n<p>A great many rumors were in circulation with regard to this<br>adventure. No one doubted but that the day had come when, in<br>accordance with their compact, Quasimodo, that is to say, the<br>devil, was to carry off Claude Frollo, that is to say, the<br>sorcerer. It was presumed that he had broken the body when taking<br>the soul, like monkeys who break the shell to get at the nut.</p>\n<p>This is why the archdeacon was not interred in consecrated earth.</p>\n<p>Louis XI. died a year later, in the month of August, 1483.</p>\n<p>As for Pierre Gringoire, he succeeded in saving the goat, and he<br>won success in tragedy. It appears that, after having tasted<br>astrology, philosophy, architecture, hermetics,—all vanities, he<br>returned to tragedy, vainest pursuit of all. This is what he<br>called “coming to a tragic end.” This is what is to be read, on<br>the subject of his dramatic triumphs, in 1483, in the accounts of<br>the “Ordinary:” “To Jehan Marchand and Pierre Gringoire,<br>carpenter and composer, who have made and composed the mystery<br>made at the Châtelet of Paris, at the entry of Monsieur the<br>Legate, and have ordered the personages, clothed and dressed the<br>same, as in the said mystery was required; and likewise, for<br>having made the scaffoldings thereto necessary; and for this<br>deed,—one hundred livres.”</p>\n<p>Phœbus de Châteaupers also came to a tragic end. He married.</p>\n<h1 class=\"chapter\" id=\"chapter-iv-the-marriage-of-quasimodo\">Chapter IV. THE MARRIAGE OF QUASIMODO.</h1>\n<p>We have just said that Quasimodo disappeared from Notre-Dame on<br>the day of the gypsy’s and of the archdeacon’s death. He was not<br>seen again, in fact; no one knew what had become of him.</p>\n<p>During the night which followed the execution of la Esmeralda,<br>the night men had detached her body from the gibbet, and had<br>carried it, according to custom, to the cellar of Montfaucon.</p>\n<p>Montfaucon was, as Sauval says, “the most ancient and the most<br>superb gibbet in the kingdom.” Between the faubourgs of the<br>Temple and Saint Martin, about a hundred and sixty toises from<br>the walls of Paris, a few bow shots from La Courtille, there was<br>to be seen on the crest of a gentle, almost imperceptible<br>eminence, but sufficiently elevated to be seen for several<br>leagues round about, an edifice of strange form, bearing<br>considerable resemblance to a Celtic cromlech, and where also<br>human sacrifices were offered.</p>\n<p>Let the reader picture to himself, crowning a limestone hillock,<br>an oblong mass of masonry fifteen feet in height, thirty wide,<br>forty long, with a gate, an external railing and a platform; on<br>this platform sixteen enormous pillars of rough hewn stone,<br>thirty feet in height, arranged in a colonnade round three of the<br>four sides of the mass which support them, bound together at<br>their summits by heavy beams, whence hung chains at intervals; on<br>all these chains, skeletons; in the vicinity, on the plain, a<br>stone cross and two gibbets of secondary importance, which seemed<br>to have sprung up as shoots around the central gallows; above all<br>this, in the sky, a perpetual flock of crows; that was<br>Montfaucon.</p>\n<p>At the end of the fifteenth century, the formidable gibbet which<br>dated from 1328, was already very much dilapidated; the beams<br>were wormeaten, the chains rusted, the pillars green with mould;<br>the layers of hewn stone were all cracked at their joints, and<br>grass was growing on that platform which no feet touched. The<br>monument made a horrible profile against the sky; especially at<br>night when there was a little moonlight on those white skulls, or<br>when the breeze of evening brushed the chains and the skeletons,<br>and swayed all these in the darkness. The presence of this gibbet<br>sufficed to render gloomy all the surrounding places.</p>\n<p>The mass of masonry which served as foundation to the odious<br>edifice was hollow. A huge cellar had been constructed there,<br>closed by an old iron grating, which was out of order, into which<br>were cast not only the human remains, which were taken from the<br>chains of Montfaucon, but also the bodies of all the unfortunates<br>executed on the other permanent gibbets of Paris. To that deep<br>charnel-house, where so many human remains and so many crimes<br>have rotted in company, many great ones of this world, many<br>innocent people, have contributed their bones, from Enguerrand de<br>Marigni, the first victim, and a just man, to Admiral de Coligni,<br>who was its last, and who was also a just man.</p>\n<p>As for the mysterious disappearance of Quasimodo, this is all<br>that we have been able to discover.</p>\n<p>About eighteen months or two years after the events which<br>terminate this story, when search was made in that cavern for the<br>body of Olivier le Daim, who had been hanged two days previously,<br>and to whom Charles VIII. had granted the favor of being buried<br>in Saint Laurent, in better company, they found among all those<br>hideous carcasses two skeletons, one of which held the other in<br>its embrace. One of these skeletons, which was that of a woman,<br>still had a few strips of a garment which had once been white,<br>and around her neck was to be seen a string of adrézarach beads<br>with a little silk bag ornamented with green glass, which was<br>open and empty. These objects were of so little value that the<br>executioner had probably not cared for them. The other, which<br>held this one in a close embrace, was the skeleton of a man. It<br>was noticed that his spinal column was crooked, his head seated<br>on his shoulder blades, and that one leg was shorter than the<br>other. Moreover, there was no fracture of the vertebrae at the<br>nape of the neck, and it was evident that he had not been hanged.<br>Hence, the man to whom it had belonged had come thither and had<br>died there. When they tried to detach the skeleton which he held<br>in his embrace, he fell to dust.</p>\n<p>NOTE<br>ADDED TO THE DEFINITIVE EDITION.</p>\n<p>It is by mistake that this edition was announced as augmented by<br>many <em>new</em> chapters. The word should have been <em>unpublished</em>. In<br>fact, if by new, <em>newly made</em> is to be understood, the chapters<br>added to this edition are not new. They were written at the same<br>time as the rest of the work; they date from the same epoch, and<br>sprang from the same thought, they have always formed a part of<br>the manuscript of “Notre-Dame-de-Paris.” Moreover, the author<br>cannot comprehend how fresh developments could be added to a work<br>of this character after its completion. This is not to be done at<br>will. According to his idea, a romance is born in a manner that<br>is, in some sort, necessary, with all its chapters; a drama is<br>born with all its scenes. Think not that there is anything<br>arbitrary in the numbers of parts of which that whole, that<br>mysterious microcosm which you call a drama or a romance, is<br>composed. Grafting and soldering take badly on works of this<br>nature, which should gush forth in a single stream and so remain.<br>The thing once done, do not change your mind, do not touch it up.<br>The book once published, the sex of the work, whether virile or<br>not, has been recognized and proclaimed; when the child has once<br>uttered his first cry he is born, there he is, he is made so,<br>neither father nor mother can do anything, he belongs to the air<br>and to the sun, let him live or die, such as he is. Has your book<br>been a failure? So much the worse. Add no chapters to an<br>unsuccessful book. Is it incomplete? You should have completed it<br>when you conceived it. Is your tree crooked? You cannot<br>straighten it up. Is your romance consumptive? Is your romance<br>not capable of living? You cannot supply it with the breath which<br>it lacks. Has your drama been born lame? Take my advice, and do<br>not provide it with a wooden leg.</p>\n<p>Hence the author attaches particular importance to the public<br>knowing for a certainty that the chapters here added have not<br>been made expressly for this reprint. They were not published in<br>the preceding editions of the book for a very simple reason. At<br>the time when “Notre-Dame-de-Paris” was printed the first time,<br>the manuscript of these three chapters had been mislaid. It was<br>necessary to rewrite them or to dispense with them. The author<br>considered that the only two of these chapters which were in the<br>least important, owing to their extent, were chapters on art and<br>history which in no way interfered with the groundwork of the<br>drama and the romance, that the public would not notice their<br>loss, and that he, the author, would alone be in possession of<br>the secret. He decided to omit them, and then, if the whole truth<br>must be confessed, his indolence shrunk from the task of<br>rewriting the three lost chapters. He would have found it a<br>shorter matter to make a new romance.</p>\n<p>Now the chapters have been found, and he avails himself of the<br>first opportunity to restore them to their place.</p>\n<p>This now, is his entire work, such as he dreamed it, such as he<br>made it, good or bad, durable or fragile, but such as he wishes<br>it.</p>\n<p>These recovered chapters will possess no doubt, but little value<br>in the eyes of persons, otherwise very judicious, who have sought<br>in “Notre-Dame-de-Paris” only the drama, the romance. But there<br>are perchance, other readers, who have not found it useless to<br>study the æsthetic and philosophic thought concealed in this<br>book, and who have taken pleasure, while reading<br>“Notre-Dame-de-Paris,” in unravelling beneath the romance<br>something else than the romance, and in following (may we be<br>pardoned these rather ambitious expressions), the system of the<br>historian and the aim of the artist through the creation of the<br>poet.</p>\n<p>For such people especially, the chapters added to this edition<br>will complete “Notre-Dame-de-Paris,” if we admit that<br>“Notre-Dame-de-Paris” was worth the trouble of completing.</p>\n<p>In one of these chapters on the present decadence of<br>architecture, and on the death (in his mind almost inevitable) of<br>that king of arts, the author expresses and develops an opinion<br>unfortunately well rooted in him, and well thought out. But he<br>feels it necessary to say here that he earnestly desires that the<br>future may, some day, put him in the wrong. He knows that art in<br>all its forms has everything to hope from the new generations<br>whose genius, still in the germ, can be heard gushing forth in<br>our studios. The grain is in the furrow, the harvest will<br>certainly be fine. He merely fears, and the reason may be seen in<br>the second volume of this edition, that the sap may have been<br>withdrawn from that ancient soil of architecture which has been<br>for so many centuries the best field for art.</p>\n<p>Nevertheless, there are to-day in the artistic youth so much<br>life, power, and, so to speak, predestination, that in our<br>schools of architecture in particular, at the present time, the<br>professors, who are detestable, produce, not only unconsciously<br>but even in spite of themselves, excellent pupils; quite the<br>reverse of that potter mentioned by Horace, who dreamed amphoræ<br>and produced pots. <em>Currit rota, urcens exit</em>.</p>\n<p>But, in any case, whatever may be the future of architecture, in<br>whatever manner our young architects may one day solve the<br>question of their art, let us, while waiting for new monument,<br>preserve the ancient monuments. Let us, if possible, inspire the<br>nation with a love for national architecture. That, the author<br>declares, is one of the principal aims of this book; it is one of<br>the principal aims of his life.</p>\n<p>“Notre-Dame-de-Paris” has, perhaps opened some true perspectives<br>on the art of the Middle Ages, on that marvellous art which up to<br>the present time has been unknown to some, and, what is worse,<br>misknown by others. But the author is far from regarding as<br>accomplished, the task which he has voluntarily imposed on<br>himself. He has already pleaded on more than one occasion, the<br>cause of our ancient architecture, he has already loudly<br>denounced many profanations, many demolitions, many impieties. He<br>will not grow weary. He has promised himself to recur frequently<br>to this subject. He will return to it. He will be as<br>indefatigable in defending our historical edifices as our<br>iconoclasts of the schools and academies are eager in attacking<br>them; for it is a grievous thing to see into what hands the<br>architecture of the Middle Ages has fallen, and in what a manner<br>the botchers of plaster of the present day treat the ruin of this<br>grand art, it is even a shame for us intelligent men who see them<br>at work and content ourselves with hooting them. And we are not<br>speaking here merely of what goes on in the provinces, but of<br>what is done in Paris at our very doors, beneath our windows, in<br>the great city, in the lettered city, in the city of the press,<br>of word, of thought. We cannot resist the impulse to point out,<br>in concluding this note, some of the acts of vandalism which are<br>every day planned, debated, begun, continued, and successfully<br>completed under the eyes of the artistic public of Paris, face to<br>face with criticism, which is disconcerted by so much audacity.<br>An archbishop’s palace has just been demolished, an edifice in<br>poor taste, no great harm is done; but in a block with the<br>archiepiscopal palace a bishop’s palace has been demolished, a<br>rare fragment of the fourteenth century, which the demolishing<br>architect could not distinguish from the rest. He has torn up the<br>wheat with the tares; ’tis all the same. They are talking of<br>razing the admirable chapel of Vincennes, in order to make, with<br>its stones, some fortification, which Daumesnil did not need,<br>however. While the Palais Bourbon, that wretched edifice, is<br>being repaired at great expense, gusts of wind and equinoctial<br>storms are allowed to destroy the magnificent painted windows of<br>the Sainte-Chapelle. For the last few days there has been a<br>scaffolding on the tower of Saint Jacques de la Boucherie; and<br>one of these mornings the pick will be laid to it. A mason has<br>been found to build a little white house between the venerable<br>towers of the Palais de-Justice. Another has been found willing<br>to prune away Saint-Germain-des-Prés, the feudal abbey with three<br>bell towers. Another will be found, no doubt, capable of pulling<br>down Saint-Germain l’Auxerrois. All these masons claim to be<br>architects, are paid by the prefecture or from the petty budget,<br>and wear green coats. All the harm which false taste can inflict<br>on good taste, they accomplish. While we write, deplorable<br>spectacle! one of them holds possession of the Tuileries, one of<br>them is giving Philibert Delorme a scar across the middle of his<br>face; and it is not, assuredly, one of the least of the scandals<br>of our time to see with what effrontery the heavy architecture of<br>this gentleman is being flattened over one of the most delicate<br>façades of the Renaissance!</p>\n<p>PARIS, October 20, 1832.</p>\n<p>FOOTNOTES:</p>\n<p>1 (return) The word Gothic, in the sense in which it is generally employed, is wholly unsuitable, but wholly consecrated. Hence we accept it and we adopt it, like all the rest of the world, to characterize the architecture of the second half of the Middle Ages, where the ogive is the principle which succeeds the architecture of the first period, of which the semi-circle is the father.</p>\n<p>2 (return) <em>Faire le diable à quatre</em>.</p>\n<p>3 (return) <em>Thibaut au des</em>,—Thibaut of the dice.</p>\n<p>4 (return) An old French coin, equal to the two hundred and fortieth part of a pound.</p>\n<p>5 (return) Got the first idea of a thing.</p>\n<p>6 (return) The ancient French <em>hurrah</em>.</p>\n<p>7 (return) A chamber of the ancient parliament of Paris.</p>\n<p>8 (return) A blank: an old French coin; six blanks were worth two sous and a half; targe, an ancient coin of Burgundy, a farthing.</p>\n<p>9 (return) A coffer of great richness In a pillar’s heart they found, Within it lay new banners, With figures to astound.</p>\n<p>10 (return) Alms.</p>\n<p>11 (return) Give me the means to buy a bit of bread, sir.</p>\n<p>12 (return) A high-toned sharper.</p>\n<p>13 (return) Thieves.</p>\n<p>14 (return) L’argot.</p>\n<p>15 (return) A small dessert apple, bright red on one side and greenish-white on the other.</p>\n<p>16 (return) When the gay-plumaged birds grow weary, and the earth—</p>\n<p>17 (return) My father is a bird, my mother is a bird. I cross the water without a barque, I cross the water without a boat. My mother is a bird, my father is a bird.</p>\n<p>18 (return) Time is a devourer; man, more so.</p>\n<p>19 (return) <em>Histoire Gallicane</em>, liv. II. Periode III. fo. 130, p. 1.</p>\n<p>20 (return) This is the same which is called, according to locality, climate, and races, Lombard, Saxon, or Byzantine. There are four sister and parallel architectures, each having its special character, but derived from the same origin, the round arch.</p>\n<p><em>Facies non omnibus una, Non diversa tamen, qualem</em>, etc.</p>\n<p>Their faces not all alike, nor yet different, but such as the faces of sisters ought to be.</p>\n<p>21 (return) This portion of the spire, which was of woodwork, is precisely that which was consumed by lightning, in 1823.</p>\n<p>22 (return) The wall walling Paris makes Paris murmur.</p>\n<p>23 (return) We have seen with sorrow mingled with indignation, that it is the intention to increase, to recast, to make over, that is to say, to destroy this admirable palace. The architects of our day have too heavy a hand to touch these delicate works of the Renaissance. We still cherish a hope that they will not dare. Moreover, this demolition of the Tuileries now, would be not only a brutal deed of violence, which would make a drunken vandal blush—it would be an act of treason. The Tuileries is not simply a masterpiece of the art of the sixteenth century, it is a page of the history of the nineteenth. This palace no longer belongs to the king, but to the people. Let us leave it as it is. Our revolution has twice set its seal upon its front. On one of its two façades, there are the cannon-balls of the 10th of August; on the other, the balls of the 29th of July. It is sacred. Paris, April 7, 1831. (<em>Note to the fifth edition.</em>)</p>\n<p>24 (return) The tenth month of the French republican calendar, from the 19th of June to the 18th of July.</p>\n<p>25 (return) An official of Notre-Dame, lower than a beneficed clergyman, higher than simple paid chanters.</p>\n<p>26 (return) Hugo II. de Bisuncio, 1326-1332.</p>\n<p>27 (return) This comet against which Pope Calixtus, uncle of Borgia, ordered public prayers, is the same which reappeared in 1835.</p>\n<p>28 (return) Comptes du domaine, 1383.</p>\n<p>29 (return) A <em>Queue</em> was a cask which held a hogshead and a half.</p>\n<p>30 (return) A captain of fifty men.</p>\n<p>31 (return) Ox-eye daisy.</p>\n<p>32 (return) Easter daisy.</p>\n<p>33 (return) A rope for the gallows bird!  A fagot for the ape.</p>\n<p>34 (return) An ancient Burgundian coin.</p>\n<p>35 (return) An ancient French coin.</p>\n<p>36 (return) Truly, these roastings are a stupendous thing!</p>\n<p>37 (return) Peter the Slaughterer; and Baptist Crack-Gosling.</p>\n<p>38 (return) An ancient copper coin, the forty-fourth part of a sou or the twelfth part of a farthing.</p>\n<p>39 (return) Une vielle qui <em>scie</em> une <em>anse</em></p>\n<p>40 (return) Cut-Weazand Street.</p>\n<p>41 (return) Cut-Throat Street.</p>\n<p>42 (return) The children of the Petits Carreaux let themselves be hung like calves.</p>\n<p>43 (return) When the rats eat the cats, the king will be lord of Arras; when the sea which is great and wide, is frozen over at St. John’s tide, men will see across the ice, those who dwell in Arras quit their place.</p>\n<p>44 (return) Varieties of the crossbow.</p>\n<p>45 (return) The substance of this exordium is contained in the president’s sentence.</p>\n<p>46 (return) “He that heareth my word and believeth on Him that sent me, hath eternal life, and hath not come into condemnation; but is passed from death to life.”</p>\n<p>47 (return) “Out of the belly of hell cried I, and thou heardest my voice. For thou hadst cast me into the deep in the midst of the seas, and the floods compassed me about.”</p>\n<p>48 (return) “Go now, soul, trembling in the balance, and God have mercy upon thee.”</p>\n<p>49 (return) “Lord have mercy upon us.”</p>\n<p>50 (return) “All thy waves and thy billows have gone over me.”</p>\n<p>51 (return) Bark, Grève, grumble, Grève!  Spin, spin, my distaff, spin her rope for the hangman, who is whistling in the meadow. What a beautiful hempen rope! Sow hemp, not wheat, from Issy to Vanvre. The thief hath not stolen the beautiful hempen rope. Grumble, Grève, bark, Grève! To see the dissolute wench hang on the blear-eyed gibbet, windows are eyes.</p>\n<p>52 (return) Look not at the face, young girl, look at the heart.  The heart of a handsome young man is often deformed. There are hearts in which love does not keep. Young girl, the pine is not beautiful; it is not beautiful like the poplar, but it keeps its foliage in winter. Alas! What is the use of saying that? That which is not beautiful has no right to exist; beauty loves only beauty; April turns her back on January. Beauty is perfect, beauty can do all things, beauty is the only thing which does not exist by halves. The raven flies only by day, the owl flies only by night, the swan flies by day and by night.</p>\n<p>53 (return) <em>Sols neufs: poulets tués</em>.</p>\n<p>54 (return) An arrow with a pyramidal head of iron and copper spiral wings, by which a rotatory motion was communicated.</p>\n<p>55 (return) A game played on a checker-board containing three concentric sets of squares, with small stones. The game consisted in getting three stones in a row.</p>\n<p>56 (return) Good night, father and mother, the last cover up the fire.</p>\n<p>57 (return) That I will drink no spiced and honeyed wine for a year, if I am lying now.</p>\n<p>58 (return) And by the blood of God, I have neither faith nor law, nor fire nor dwelling-place, nor king nor God.</p>\n<p>59 (return) Men of the brotherhood of slang: thieves.</p>\n<p>60 (return) Cut-throat. Coupe-gueule being the vulgar word for cut-weazand.</p>\n<p>61 (return) The representation of a monstrous animal solemnly drawn about in Tarascon and other French towns.</p>\n<p>62 (return) An arrow with a pyramidal head of iron and copper spiral wings by which a rotatory motion was communicated.</p>\n<p>63 (return) The city of Cambrai is well dressed. Marafin plundered it.</p>\n<p>64 (return) An ancient long measure in France, containing six feet and nearly five inches English measure.</p>\n<p>65 (return) Master Jean Balue has lost sight of his bishoprics. Monsieur of Verdun has no longer one; all have been killed off.</p>\n<p>66 (return) One in charge of the highways.</p>\n<p>67 (return) A lord having a right on the woods of his vassals.</p>\n<p>68 (return) When thou shalt find its mate, thy mother will stretch out her arms to thee.</p>","quiz":[{"type":"mc","q":{"en":"What does “particular” mean here?","tr":"Bu kitapta geçen “particular” ne demek?"},"opts":[{"en":"","tr":"belirli, özel"},{"en":"","tr":"önemli"},{"en":"","tr":"kalıcı, sürekli"},{"en":"","tr":"dinî"}],"a":0,"why":{"tr":"(adj) belirli, özel — Belli bir tanesi.  Kitaptan: “The populace thronged the avenues of the law courts in particular, because they knew that the Flemish ambassadors, who had arrived two days previously, intended to be present …”"}},{"type":"mc","q":{"en":"What does “claim” mean here?","tr":"Bu kitapta geçen “claim” ne demek?"},"opts":[{"en":"","tr":"zorlamak; güç"},{"en":"","tr":"iddia etmek; iddia"},{"en":"","tr":"dinî"},{"en":"","tr":"kalıcı, sürekli"}],"a":1,"why":{"tr":"(v/n) iddia etmek; iddia — Kanıtı tartışmalı olabilecek bir öne sürüm.  Kitaptan: “She had come herself to claim the dolphin promised to the most beautiful.”"}},{"type":"mc","q":{"en":"What does “combat” mean here?","tr":"Bu kitapta geçen “combat” ne demek?"},"opts":[{"en":"","tr":"dinî"},{"en":"","tr":"çatışma, muharebe"},{"en":"","tr":"önemli"},{"en":"","tr":"belirli, özel"}],"a":1,"why":{"tr":"(n) çatışma, muharebe — Silahlı çarpışma durumu.  Kitaptan: “let us combat until the end,” he repeated to himself; “the power of poetry over people is great; I will bring them back.”"}},{"type":"mc","q":{"en":"What does “group” mean here?","tr":"Bu kitapta geçen “group” ne demek?"},"opts":[{"en":"","tr":"belirli, özel"},{"en":"","tr":"dinî"},{"en":"","tr":"hastane"},{"en":"","tr":"grup, öbek; gruplamak"}],"a":3,"why":{"tr":"(n/v) grup, öbek; gruplamak — Ortak özellikli birimler kümesi.  Kitaptan: “Among the rest there was a group of those merry imps, who, after smashing the glass in a window, had seated themselves hardily on the entablature, …”"}},{"type":"mc","q":{"en":"What does “permanent” mean here?","tr":"Bu kitapta geçen “permanent” ne demek?"},"opts":[{"en":"","tr":"kalıcı, sürekli"},{"en":"","tr":"savaş"},{"en":"","tr":"zorlamak; güç"},{"en":"","tr":"alanyazın, literatür"}],"a":0,"why":{"tr":"(adj) kalıcı, sürekli — Geçici olmayan.  Kitaptan: “It must be admitted that a permanent gibbet and a pillory, “a justice and a ladder,” as they were called in that day, erected side by side in the c …”"}},{"type":"mc","q":{"en":"What does “force” mean here?","tr":"Bu kitapta geçen “force” ne demek?"},"opts":[{"en":"","tr":"çatışma, muharebe"},{"en":"","tr":"kalıcı, sürekli"},{"en":"","tr":"zorlamak; güç"},{"en":"","tr":"önemli"}],"a":2,"why":{"tr":"(v/n) zorlamak; güç — 'forced displacement' = zorla yerinden edilme.  Kitaptan: “It was no easy matter on that day, to force one’s way into that grand hall, although it was then reputed to be the largest covered enclosure in the world (it …”"}},{"type":"mc","q":{"en":"What does “religious” mean here?","tr":"Bu kitapta geçen “religious” ne demek?"},"opts":[{"en":"","tr":"savaş"},{"en":"","tr":"dinî"},{"en":"","tr":"çatışma, muharebe"},{"en":"","tr":"belirli, özel"}],"a":1,"why":{"tr":"(adj) dinî — Dinle ilgili. 'religious marriage' = dinî nikâh.  Kitaptan: “… nkles of the new-born babe to the wrinkles of the aged and dying; all religious phantasmagories, from Faun to Beelzebub; all animal profiles, from the maw to the beak, from the jowl to the m …”"}},{"type":"mc","q":{"en":"What does “war” mean here?","tr":"Bu kitapta geçen “war” ne demek?"},"opts":[{"en":"","tr":"kalıcı, sürekli"},{"en":"","tr":"savaş"},{"en":"","tr":"grup, öbek; gruplamak"},{"en":"","tr":"geçmiş"}],"a":1,"why":{"tr":"(n) savaş — Silahlı toplu çatışma. 'war-affected' = savaştan etkilenen.  Kitaptan: “I presume that this hole is jointly inhabited by bats and spiders, and that, consequently, it wages a double war of extermination on the flies).”"}},{"type":"mc","q":{"en":"What does “important” mean here?","tr":"Bu kitapta geçen “important” ne demek?"},"opts":[{"en":"","tr":"savaş"},{"en":"","tr":"dinî"},{"en":"","tr":"çatışma, muharebe"},{"en":"","tr":"önemli"}],"a":3,"why":{"tr":"(adj) önemli — Dikkate alınması gereken.  Kitaptan: “Three important things are to-day lacking in that façade: in the first place, the staircase of eleven steps which formerly rai …”"}},{"type":"mc","q":{"en":"What does “past” mean here?","tr":"Bu kitapta geçen “past” ne demek?"},"opts":[{"en":"","tr":"kalıcı, sürekli"},{"en":"","tr":"geçmiş"},{"en":"","tr":"grup, öbek; gruplamak"},{"en":"","tr":"hastane"}],"a":1,"why":{"tr":"(adj/n) geçmiş — Daha önceki zaman.  Kitaptan: “It was also noticed that his horror for Bohemian women and gypsies had seemed to redouble for some time past.”"}},{"type":"mc","q":{"en":"What does “literature” mean here?","tr":"Bu kitapta geçen “literature” ne demek?"},"opts":[{"en":"","tr":"savaş"},{"en":"","tr":"alanyazın, literatür"},{"en":"","tr":"çatışma, muharebe"},{"en":"","tr":"kalıcı, sürekli"}],"a":1,"why":{"tr":"(n) alanyazın, literatür — Bir konudaki yayınların tümü.  Kitaptan: “We shall see which will carry the day, grimaces or polite literature.”"}},{"type":"mc","q":{"en":"What does “hospital” mean here?","tr":"Bu kitapta geçen “hospital” ne demek?"},"opts":[{"en":"","tr":"dinî"},{"en":"","tr":"hastane"},{"en":"","tr":"iddia etmek; iddia"},{"en":"","tr":"belirli, özel"}],"a":1,"why":{"tr":"(n) hastane — Tıbbi bakım kurumu.  Kitaptan: “… htfall, with their booty, all the drones of the social order; a lying hospital where the bohemian, the disfrocked monk, the ruined scholar, the ne’er-do-wells of all nations, Spaniards, Ital …”"}}]};
